//! Rust-native Vulkan training graph for Hugging Face Transformer models.
//!
//! This module deliberately reuses the same low-level Vulkan runtime, FP32
//! master parameters, AdamW kernels, SafeTensors checkpoint ABI, and tied token
//! embedding used by the Hierarchos recurrent graph. CPU code is orchestration
//! and checkpoint/data I/O only; forward, backward, loss and optimizer math are
//! recorded into Vulkan command buffers.

use std::{
    collections::{BTreeMap, BTreeSet},
    fs::{self, OpenOptions},
    io::{Read, Seek, SeekFrom, Write},
    path::{Component, Path, PathBuf},
    sync::{Arc, Mutex, OnceLock},
    time::Instant,
};

use anyhow::{anyhow, bail, Context, Result};
use bytemuck::{Pod, Zeroable};
use nalgebra::DMatrix;
use peft_rs::{HfLoraConfig, LoraKeyStyle};
use regex::Regex;
use safetensors::{
    serialize_to_file,
    tensor::{Dtype, SafeTensors, TensorView},
};
use serde::{Deserialize, Serialize};
use tokenizers::Tokenizer;

use crate::training_numerics::VulkanOrderedF32SumReducer;
use crate::{
    hierarchos_canonical_philox_word, hierarchos_dropout_threshold, read_f32_tensor, vulkan,
    AdamWHyperParams, CanonicalDropoutVulkanOp, GpuBuffer, HierarchosCanonicalRngReservation,
    SharedLmHeadParameter, TiedTokenEmbeddingOp, VulkanDevice,
};

