fn default_generation_assistant_confidence_threshold() -> Option<f32> {
    Some(0.4)
}

fn default_generation_assistant_lookbehind() -> usize {
    10
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum VulkanStopStringMatchingMode {
    Text,
    ByteLevel,
    ByteFallback,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct VulkanStopStringRule {
    target_len: usize,
    valid_positions: BTreeMap<u32, Vec<usize>>,
    end_overlaps: BTreeMap<u32, Vec<usize>>,
}

/// Tokenizer-preprocessed form of Hugging Face's `StopStringCriteria`.
///
/// The expensive tokenizer cleanup happens once. Runtime matching then walks
/// backward over token ids using only integer overlap metadata, just like the
/// tensorized upstream criterion.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VulkanTransformerStopStringMatcher {
    stop_strings: Vec<String>,
    maximum_token_len: usize,
    token_lengths: BTreeMap<u32, usize>,
    rules: Vec<VulkanStopStringRule>,
}

fn stop_string_decoder_has_type(value: &serde_json::Value, decoder_type: &str) -> bool {
    match value {
        serde_json::Value::Object(map) => {
            map.get("type").and_then(serde_json::Value::as_str) == Some(decoder_type)
                || map
                    .values()
                    .any(|value| stop_string_decoder_has_type(value, decoder_type))
        }
        serde_json::Value::Array(values) => values
            .iter()
            .any(|value| stop_string_decoder_has_type(value, decoder_type)),
        _ => false,
    }
}

fn stop_string_matching_mode(tokenizer: &Tokenizer) -> Result<VulkanStopStringMatchingMode> {
    let tokenizer_json = tokenizer
        .to_string(false)
        .map_err(|error| anyhow!("serializing tokenizer for stop-string matching: {error}"))?;
    let tokenizer_json: serde_json::Value = serde_json::from_str(&tokenizer_json)
        .context("decoding tokenizer JSON for stop-string matching")?;
    let decoder = tokenizer_json.get("decoder");
    if decoder.is_some_and(|decoder| stop_string_decoder_has_type(decoder, "ByteFallback")) {
        Ok(VulkanStopStringMatchingMode::ByteFallback)
    } else if decoder.is_some_and(|decoder| stop_string_decoder_has_type(decoder, "ByteLevel")) {
        Ok(VulkanStopStringMatchingMode::ByteLevel)
    } else {
        Ok(VulkanStopStringMatchingMode::Text)
    }
}

fn stop_string_byte_level_decode_char(character: char) -> Option<u8> {
    let codepoint = character as u32;
    if (33..=126).contains(&codepoint)
        || (161..=172).contains(&codepoint)
        || (174..=255).contains(&codepoint)
    {
        return u8::try_from(codepoint).ok();
    }
    let extra_index = codepoint.checked_sub(256)? as usize;
    (0u16..=255)
        .map(|value| value as u8)
        .filter(|value| {
            let value = u32::from(*value);
            !((33..=126).contains(&value)
                || (161..=172).contains(&value)
                || (174..=255).contains(&value))
        })
        .nth(extra_index)
}

fn stop_string_units_from_text(value: &str, mode: VulkanStopStringMatchingMode) -> Vec<u32> {
    match mode {
        VulkanStopStringMatchingMode::Text => {
            value.chars().map(|character| character as u32).collect()
        }
        VulkanStopStringMatchingMode::ByteLevel | VulkanStopStringMatchingMode::ByteFallback => {
            value
                .as_bytes()
                .iter()
                .map(|byte| u32::from(*byte))
                .collect()
        }
    }
}

fn stop_string_raw_token_units(
    token: &str,
    mode: VulkanStopStringMatchingMode,
) -> Option<Vec<u32>> {
    match mode {
        VulkanStopStringMatchingMode::ByteLevel => token
            .chars()
            .map(stop_string_byte_level_decode_char)
            .collect::<Option<Vec<_>>>()
            .map(|bytes| bytes.into_iter().map(u32::from).collect()),
        VulkanStopStringMatchingMode::ByteFallback => {
            if token.len() == 6
                && token.starts_with("<0x")
                && token.ends_with('>')
                && token[3..5]
                    .chars()
                    .all(|character| character.is_ascii_hexdigit())
            {
                u8::from_str_radix(&token[3..5], 16)
                    .ok()
                    .map(|byte| vec![u32::from(byte)])
            } else {
                None
            }
        }
        VulkanStopStringMatchingMode::Text => None,
    }
}

fn stop_string_matching_positions(token: &[u32], stop_string: &[u32]) -> (Vec<usize>, Vec<usize>) {
    if token.is_empty() || stop_string.is_empty() {
        return (Vec::new(), Vec::new());
    }
    let reversed_token = token.iter().rev().copied().collect::<Vec<_>>();
    let reversed_stop = stop_string.iter().rev().copied().collect::<Vec<_>>();
    let mut matching_positions = Vec::new();
    let mut possible_end_lengths = Vec::new();
    let start = 1isize - token.len() as isize;
    let end = stop_string.len() as isize;
    for raw_position in start..end {
        let (token_slice, position) = if raw_position < 0 {
            (&reversed_token[(-raw_position) as usize..], 0usize)
        } else {
            (reversed_token.as_slice(), raw_position as usize)
        };
        let stop_end = (position + token_slice.len()).min(reversed_stop.len());
        let stop_slice = &reversed_stop[position..stop_end];
        if token_slice.starts_with(stop_slice) {
            if position == 0 {
                possible_end_lengths.push(token_slice.len().min(stop_slice.len()));
            } else {
                matching_positions.push(position);
            }
        }
    }
    (matching_positions, possible_end_lengths)
}

impl VulkanTransformerStopStringMatcher {
    pub fn new(tokenizer: &Tokenizer, stop_strings: &[String]) -> Result<Self> {
        if stop_strings.is_empty() {
            bail!("stop-string matcher requires at least one stop string");
        }
        if stop_strings
            .iter()
            .any(|stop_string| stop_string.is_empty())
        {
            bail!("stop-string matcher does not accept empty stop strings");
        }
        let mode = stop_string_matching_mode(tokenizer)?;
        let stop_units = stop_strings
            .iter()
            .map(|stop_string| stop_string_units_from_text(stop_string, mode))
            .collect::<Vec<_>>();
        let maximum_token_len = stop_units
            .iter()
            .map(Vec::len)
            .max()
            .context("stop-string matcher has no target lengths")?;

        let static_prefix = "abcdef";
        let prefix_encoding = tokenizer
            .encode(static_prefix, false)
            .map_err(|error| anyhow!("tokenizing static stop-string prefix: {error}"))?;
        let prefix_ids = prefix_encoding.get_ids();
        let vocab = tokenizer.get_vocab(true);
        let mut cleaned_tokens = BTreeMap::<u32, Vec<u32>>::new();
        for (token, token_id) in vocab {
            let units = if let Some(units) = stop_string_raw_token_units(&token, mode) {
                units
            } else {
                let mut ids = Vec::with_capacity(prefix_ids.len() + 1);
                ids.extend_from_slice(prefix_ids);
                ids.push(token_id);
                let decoded = tokenizer.decode(&ids, false).map_err(|error| {
                    anyhow!("decoding tokenizer token {token_id} for stop-string matching: {error}")
                })?;
                let prefix_offset = decoded.find(static_prefix).with_context(|| {
                    format!(
                        "tokenizer decoder did not preserve static stop-string prefix while cleaning token {token_id}"
                    )
                })?;
                let suffix = &decoded[prefix_offset + static_prefix.len()..];
                stop_string_units_from_text(suffix, mode)
            };
            cleaned_tokens.insert(token_id, units);
        }

        let token_lengths = cleaned_tokens
            .iter()
            .map(|(&token_id, token)| (token_id, token.len()))
            .collect::<BTreeMap<_, _>>();
        let mut rules = Vec::with_capacity(stop_units.len());
        let mut any_end_overlap = false;
        for target in &stop_units {
            let mut valid_positions = BTreeMap::new();
            let mut end_overlaps = BTreeMap::new();
            for (&token_id, token) in &cleaned_tokens {
                let (positions, overlaps) = stop_string_matching_positions(token, target);
                if !positions.is_empty() {
                    valid_positions.insert(token_id, positions);
                }
                if !overlaps.is_empty() {
                    any_end_overlap = true;
                    end_overlaps.insert(token_id, overlaps);
                }
            }
            rules.push(VulkanStopStringRule {
                target_len: target.len(),
                valid_positions,
                end_overlaps,
            });
        }
        if !any_end_overlap {
            bail!(
                "stop string preprocessing found no tokenizer tokens that can complete the supplied stop strings"
            );
        }
        Ok(Self {
            stop_strings: stop_strings.to_vec(),
            maximum_token_len,
            token_lengths,
            rules,
        })
    }

    pub fn matches(&self, input_ids: &[u32]) -> bool {
        let Some(&last_token) = input_ids.last() else {
            return false;
        };
        for rule in &self.rules {
            let Some(end_lengths) = rule.end_overlaps.get(&last_token) else {
                continue;
            };
            for &end_length in end_lengths {
                let mut matched = end_length;
                if matched >= rule.target_len {
                    return true;
                }
                for &token in input_ids
                    .iter()
                    .rev()
                    .skip(1)
                    .take(self.maximum_token_len.saturating_sub(1))
                {
                    let Some(positions) = rule.valid_positions.get(&token) else {
                        break;
                    };
                    if !positions.contains(&matched) {
                        break;
                    }
                    matched = matched.saturating_add(
                        self.token_lengths.get(&token).copied().unwrap_or_default(),
                    );
                    if matched >= rule.target_len {
                        return true;
                    }
                }
            }
        }
        false
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum VulkanTransformerGenerationMode {
    GreedySearch,
    Sample,
    BeamSearch,
    BeamSample,
    ContrastiveSearch,
    GroupBeamSearch,
    ConstrainedBeamSearch,
    AssistedGeneration,
    DolaGeneration,
}

/// Hugging Face accepts either one decoder start token for the whole request
/// or one token per batch item. Keep the representation untagged so
/// `generation_config.json` round-trips with the same scalar-or-list shape.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum VulkanTransformerDecoderStartTokenId {
    Single(u32),
    Batch(Vec<u32>),
}

impl From<u32> for VulkanTransformerDecoderStartTokenId {
    fn from(value: u32) -> Self {
        Self::Single(value)
    }
}

impl VulkanTransformerDecoderStartTokenId {
    fn ids(&self) -> &[u32] {
        match self {
            Self::Single(value) => std::slice::from_ref(value),
            Self::Batch(values) => values,
        }
    }

    fn for_single_request(&self) -> Result<u32> {
        match self {
            Self::Single(value) => Ok(*value),
            Self::Batch(values) if values.len() == 1 => Ok(values[0]),
            Self::Batch(values) => bail!(
                "generation decoder_start_token_id contains {} batch values; use a batch generation entrypoint",
                values.len()
            ),
        }
    }

    fn for_batch_item(&self, batch_index: usize, batch_size: usize) -> Result<u32> {
        match self {
            Self::Single(value) => Ok(*value),
            Self::Batch(values) if values.len() == batch_size => Ok(values[batch_index]),
            Self::Batch(values) => bail!(
                "generation decoder_start_token_id contains {} values for batch size {}",
                values.len(),
                batch_size
            ),
        }
    }
}

impl VulkanTransformerGenerationMode {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::GreedySearch => "greedy_search",
            Self::Sample => "sample",
            Self::BeamSearch => "beam_search",
            Self::BeamSample => "beam_sample",
            Self::ContrastiveSearch => "contrastive_search",
            Self::GroupBeamSearch => "group_beam_search",
            Self::ConstrainedBeamSearch => "constrained_beam_search",
            Self::AssistedGeneration => "assisted_generation",
            Self::DolaGeneration => "dola_generation",
        }
    }
}

/// Host-side generation policy compatible with the common Hugging Face
/// `GenerationConfig` fields used by causal language models.
///
/// Transformer math remains Vulkan-native. Sampling and beam bookkeeping are
/// deliberately host-side, matching the role played by `generate()`'s logits
/// processors/warpers in Transformers while keeping the model executor
/// independent from a particular decoding policy.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct VulkanTransformerGenerationConfig {
    #[serde(default)]
    pub max_new_tokens: Option<usize>,
    #[serde(default = "default_generation_max_length")]
    pub max_length: Option<usize>,
    #[serde(default)]
    pub min_length: usize,
    #[serde(default)]
    pub min_new_tokens: usize,
    #[serde(default)]
    pub max_time: Option<f64>,
    /// Decoded-text termination strings from Hugging Face `GenerationConfig`.
    /// Matching requires tokenizer metadata, so these are preserved here and
    /// consumed by the tokenizer-aware generation entrypoints.
    #[serde(default)]
    pub stop_strings: Vec<String>,
    /// Runtime-only tokenizer preprocessing for `stop_strings`. Like HF's
    /// `StopStringCriteria`, this is derived from the tokenizer rather than
    /// serialized into generation_config.json.
    #[serde(skip, default)]
    pub stop_string_matcher: Option<VulkanTransformerStopStringMatcher>,
    #[serde(default)]
    pub do_sample: bool,
    #[serde(default = "default_generation_use_cache")]
    pub use_cache: bool,
    /// Hugging Face cache policy. `None`, `dynamic`, and `static` map onto the
    /// native Vulkan KV-cache executor. Other upstream cache backends remain
    /// explicit until their storage/transport semantics are implemented.
    #[serde(default)]
    pub cache_implementation: Option<String>,
    #[serde(default)]
    pub cache_config: Option<serde_json::Value>,
    #[serde(default)]
    pub max_cache_len: Option<usize>,
    /// Chunk size used to schedule long prompt prefills. This is a scheduling
    /// hint only and does not change model numerics.
    #[serde(default)]
    pub prefill_chunk_size: Option<usize>,
    /// Classifier-free guidance scale used by Hugging Face's unbatched CFG
    /// logits processor. `None` and `Some(1.0)` leave logits unchanged.
    #[serde(default)]
    pub guidance_scale: Option<f32>,
    #[serde(default)]
    pub token_healing: bool,
    #[serde(default)]
    pub watermarking_config: Option<serde_json::Value>,
    /// Runtime-only negative/unconditional prompt ids. Hugging Face accepts
    /// these as `generate()` arguments rather than serializing them in
    /// `GenerationConfig`, so preserve the same split here.
    #[serde(skip, default)]
    pub negative_prompt_ids: Option<Vec<u32>>,
    /// Runtime-only attention mask paired with `negative_prompt_ids`.
    #[serde(skip, default)]
    pub negative_prompt_attention_mask: Option<Vec<f32>>,
    #[serde(default = "default_generation_temperature")]
    pub temperature: f32,
    #[serde(default = "default_generation_top_k")]
    pub top_k: usize,
    #[serde(default = "default_generation_top_p")]
    pub top_p: f32,
    #[serde(default)]
    pub top_h: Option<f32>,
    #[serde(default)]
    pub min_p: Option<f32>,
    #[serde(default)]
    pub typical_p: Option<f32>,
    #[serde(default)]
    pub epsilon_cutoff: Option<f32>,
    #[serde(default)]
    pub eta_cutoff: Option<f32>,
    #[serde(default = "default_generation_repetition_penalty")]
    pub repetition_penalty: f32,
    #[serde(default = "default_generation_repetition_penalty")]
    pub encoder_repetition_penalty: f32,
    #[serde(default)]
    pub encoder_no_repeat_ngram_size: usize,
    /// Runtime encoder/source token ids used by Hugging Face's encoder-side
    /// logits processors. `GenerationConfig` itself does not serialize these
    /// ids; they are request inputs, so keep them out of config JSON while
    /// carrying them through cloned generation requests internally.
    #[serde(skip, default)]
    pub encoder_input_ids: Option<Vec<u32>>,
    /// Hugging Face `sequence_bias`, stored in its JSON-compatible
    /// `[[token_ids, bias], ...]` representation.
    #[serde(default)]
    pub sequence_bias: Vec<(Vec<u32>, f32)>,
    #[serde(default = "default_generation_num_beams")]
    pub num_beams: usize,
    #[serde(default)]
    pub penalty_alpha: Option<f32>,
    #[serde(default)]
    pub diversity_penalty: Option<f32>,
    #[serde(default)]
    pub num_beam_groups: Option<usize>,
    #[serde(default)]
    pub constraints: Option<serde_json::Value>,
    #[serde(default)]
    pub force_words_ids: Option<serde_json::Value>,
    #[serde(default)]
    pub use_mtp: bool,
    #[serde(default)]
    pub is_assistant: bool,
    /// Maximum draft length used by model-backed assisted generation. This
    /// matches the global Hugging Face assistant default after
    /// `_get_default_generation_params()` is applied.
    #[serde(default = "default_generation_num_assistant_tokens")]
    pub num_assistant_tokens: usize,
    /// Hugging Face assistant token schedule: `constant`, `heuristic`, or
    /// `heuristic_transient`. The Vulkan request object is immutable, so the
    /// heuristic state is local to one generation call; `heuristic` and
    /// `heuristic_transient` therefore differ only in future stateful APIs.
    #[serde(default = "default_generation_num_assistant_tokens_schedule")]
    pub num_assistant_tokens_schedule: String,
    /// Stop drafting after a token whose assistant probability falls below
    /// this threshold. `None` disables confidence stopping.
    #[serde(default = "default_generation_assistant_confidence_threshold")]
    pub assistant_confidence_threshold: Option<f32>,
    /// Static target/assistant ensemble weight used by current Transformers'
    /// DIVERSE speculative verification. `None` selects ordinary lossless
    /// speculative decoding; values in `(0, 1)` trade controlled target bias
    /// for higher draft acceptance.
    #[serde(default)]
    pub assistant_ensemble_weight: Option<f32>,
    #[serde(default)]
    pub prompt_lookup_num_tokens: Option<usize>,
    #[serde(default)]
    pub max_matching_ngram_size: Option<usize>,
    #[serde(default)]
    pub assistant_early_exit: Option<usize>,
    #[serde(default = "default_generation_assistant_lookbehind")]
    pub assistant_lookbehind: usize,
    #[serde(default = "default_generation_assistant_lookbehind")]
    pub target_lookbehind: usize,
    #[serde(default)]
    pub speculation_type: Option<String>,
    #[serde(default)]
    pub dola_layers: Option<serde_json::Value>,
    #[serde(default = "default_generation_num_return_sequences")]
    pub num_return_sequences: usize,
    #[serde(default = "default_generation_length_penalty")]
    pub length_penalty: f32,
    #[serde(default)]
    pub early_stopping: bool,
    /// Hugging Face distinguishes `early_stopping=false` from the canonical
    /// exhaustive beam-search mode `early_stopping="never"`. Keep the public
    /// bool for source compatibility while preserving that third state here.
    #[serde(default)]
    pub early_stopping_never: bool,
    #[serde(default)]
    pub renormalize_logits: bool,
    #[serde(default)]
    pub remove_invalid_values: bool,
    #[serde(default)]
    pub exponential_decay_length_penalty: Option<(usize, f32)>,
    #[serde(default)]
    pub no_repeat_ngram_size: usize,
    #[serde(default)]
    pub bad_words_ids: Vec<Vec<u32>>,
    #[serde(default)]
    pub suppress_tokens: Vec<u32>,
    #[serde(default)]
    pub begin_suppress_tokens: Vec<u32>,
    /// Hugging Face special-token metadata used while preparing decoder
    /// inputs. These are distinct from the forced BOS/EOS logits processors:
    /// `bos_token_id` may seed an otherwise empty decoder-only prompt, while
    /// encoder-decoder generation uses `decoder_start_token_id` (falling back
    /// to BOS) as the first decoder token.
    #[serde(default)]
    pub pad_token_id: Option<u32>,
    #[serde(default)]
    pub bos_token_id: Option<u32>,
    #[serde(default)]
    pub decoder_start_token_id: Option<VulkanTransformerDecoderStartTokenId>,
    #[serde(default)]
    pub forced_bos_token_id: Option<u32>,
    #[serde(default)]
    pub forced_eos_token_ids: Vec<u32>,
    /// HF permits either an integer or a list for `eos_token_id`. The custom
    /// deserializer below normalizes both forms into this list.
    #[serde(default)]
    pub eos_token_ids: Vec<u32>,
    #[serde(default)]
    pub output_scores: bool,
    #[serde(default)]
    pub output_logits: bool,
    #[serde(default)]
    pub output_attentions: bool,
    #[serde(default)]
    pub output_hidden_states: bool,
    #[serde(default)]
    pub return_dict_in_generate: bool,
    /// `torch.compile` settings are accepted as compatibility metadata. The
    /// Rust/Vulkan executor does not route through torch.compile, so these do
    /// not alter native command recording.
    #[serde(default)]
    pub compile_config: Option<serde_json::Value>,
    #[serde(default)]
    pub disable_compile: bool,
    /// Deprecated upstream GenerationConfig compatibility fields. They are
    /// retained so current generation_config.json files round-trip without
    /// dropping user metadata.
    #[serde(default)]
    pub continuous_batching_config: Option<serde_json::Value>,
    #[serde(default)]
    pub low_memory: Option<bool>,
    /// Deterministic seed for the host-side Philox sampling stream. Hugging
    /// Face normally obtains this from the framework RNG rather than
    /// `generation_config.json`, so packages that omit it receive zero.
    #[serde(default)]
    pub seed: u64,
}

impl Default for VulkanTransformerGenerationConfig {
    fn default() -> Self {
        Self {
            max_new_tokens: None,
            max_length: default_generation_max_length(),
            min_length: 0,
            min_new_tokens: 0,
            max_time: None,
            stop_strings: Vec::new(),
            stop_string_matcher: None,
            do_sample: false,
            use_cache: default_generation_use_cache(),
            cache_implementation: None,
            cache_config: None,
            max_cache_len: None,
            prefill_chunk_size: None,
            guidance_scale: None,
            token_healing: false,
            watermarking_config: None,
            negative_prompt_ids: None,
            negative_prompt_attention_mask: None,
            temperature: default_generation_temperature(),
            top_k: default_generation_top_k(),
            top_p: default_generation_top_p(),
            top_h: None,
            min_p: None,
            typical_p: None,
            epsilon_cutoff: None,
            eta_cutoff: None,
            repetition_penalty: default_generation_repetition_penalty(),
            encoder_repetition_penalty: default_generation_repetition_penalty(),
            encoder_no_repeat_ngram_size: 0,
            encoder_input_ids: None,
            sequence_bias: Vec::new(),
            num_beams: default_generation_num_beams(),
            penalty_alpha: None,
            diversity_penalty: None,
            num_beam_groups: None,
            constraints: None,
            force_words_ids: None,
            use_mtp: false,
            is_assistant: false,
            num_assistant_tokens: default_generation_num_assistant_tokens(),
            num_assistant_tokens_schedule: default_generation_num_assistant_tokens_schedule(),
            assistant_confidence_threshold: default_generation_assistant_confidence_threshold(),
            assistant_ensemble_weight: None,
            prompt_lookup_num_tokens: None,
            max_matching_ngram_size: None,
            assistant_early_exit: None,
            assistant_lookbehind: default_generation_assistant_lookbehind(),
            target_lookbehind: default_generation_assistant_lookbehind(),
            speculation_type: None,
            dola_layers: None,
            num_return_sequences: default_generation_num_return_sequences(),
            length_penalty: default_generation_length_penalty(),
            early_stopping: false,
            early_stopping_never: false,
            renormalize_logits: false,
            remove_invalid_values: false,
            exponential_decay_length_penalty: None,
            no_repeat_ngram_size: 0,
            bad_words_ids: Vec::new(),
            suppress_tokens: Vec::new(),
            begin_suppress_tokens: Vec::new(),
            pad_token_id: None,
            bos_token_id: None,
            decoder_start_token_id: None,
            forced_bos_token_id: None,
            forced_eos_token_ids: Vec::new(),
            eos_token_ids: Vec::new(),
            output_scores: false,
            output_logits: false,
            output_attentions: false,
            output_hidden_states: false,
            return_dict_in_generate: false,
            compile_config: None,
            disable_compile: false,
            continuous_batching_config: None,
            low_memory: None,
            seed: 0,
        }
    }
}

/// Structured generation result for one expanded return sequence.
///
/// `sequence` includes the decoder prompt followed by generated tokens, like
/// Hugging Face's `GenerateDecoderOnlyOutput.sequences`. `scores` contain the
/// fully processed values used for token selection, while `logits` preserve
/// the raw model-head output before generation processors and sampling
/// warpers. Both are stored as `[generation_step][vocab]` when requested.
#[derive(Clone, Debug, PartialEq)]
pub struct VulkanTransformerGenerationHiddenState {
    /// Number of active sequence rows represented by `values`.
    pub rows: usize,
    /// Hidden width for each row. This can differ from the block hidden width
    /// for architectures with a decoder output projection such as OPT.
    pub hidden_size: usize,
    /// Row-major `[rows, hidden_size]` tensor values.
    pub values: Vec<f32>,
}

/// One attention-probability tensor from a single generated sequence.
/// `values` is row-major `[num_heads, query_rows, key_rows]`. Generation
/// prefill exposes the full active prompt; cached follow-up steps expose one
/// query row against the complete key prefix, matching Transformers' visible
/// decoder-attention shape contract.
#[derive(Clone, Debug, PartialEq)]
pub struct VulkanTransformerGenerationAttention {
    pub query_rows: usize,
    pub key_rows: usize,
    pub num_heads: usize,
    pub values: Vec<f32>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct VulkanTransformerGenerationSequenceOutput {
    pub sequence: Vec<u32>,
    pub prompt_length: usize,
    pub scores: Option<Vec<Vec<f32>>>,
    pub logits: Option<Vec<Vec<f32>>>,
    /// Hugging Face-style decoder hidden-state trace. The outer dimension is
    /// the generation step and the inner dimension is the embedding state plus
    /// one state per Transformer layer.
    pub hidden_states: Option<Vec<Vec<VulkanTransformerGenerationHiddenState>>>,
    /// Decoder self-attention probabilities as `[generation_step][layer]`.
    pub attentions: Option<Vec<Vec<VulkanTransformerGenerationAttention>>>,
    /// Decoder-to-encoder attention probabilities as
    /// `[generation_step][cross_attention_layer]` when encoder context is
    /// active.
    pub cross_attentions: Option<Vec<Vec<VulkanTransformerGenerationAttention>>>,
    pub sequence_score: Option<f64>,
    pub beam_indices: Option<Vec<usize>>,
}

impl VulkanTransformerGenerationSequenceOutput {
    pub fn generated_ids(&self) -> &[u32] {
        &self.sequence[self.prompt_length.min(self.sequence.len())..]
    }
}

/// Hugging Face-style structured generation container. The outer sequence
/// dimension corresponds to `num_return_sequences` for the current batch-1
/// Vulkan graph. Existing `generate_ids`/`generate_sequences_ids` APIs remain
/// continuation-only compatibility projections.
#[derive(Clone, Debug, PartialEq)]
pub struct VulkanTransformerGenerationOutput {
    pub sequences: Vec<VulkanTransformerGenerationSequenceOutput>,
}

impl VulkanTransformerGenerationConfig {
    fn specialize_decoder_start_token_for_batch(
        &mut self,
        batch_index: usize,
        batch_size: usize,
    ) -> Result<()> {
        if let Some(decoder_start) = self.decoder_start_token_id.as_ref() {
            self.decoder_start_token_id = Some(VulkanTransformerDecoderStartTokenId::Single(
                decoder_start.for_batch_item(batch_index, batch_size)?,
            ));
        }
        Ok(())
    }

    /// Precompute Hugging Face-compatible stop-string overlap metadata for the
    /// tokenizer used by this generation request.
    pub fn prepare_stop_strings(&mut self, tokenizer: &Tokenizer) -> Result<()> {
        self.stop_string_matcher = if self.stop_strings.is_empty() {
            None
        } else {
            Some(VulkanTransformerStopStringMatcher::new(
                tokenizer,
                &self.stop_strings,
            )?)
        };
        Ok(())
    }

    pub fn from_hf_generation_config(path: impl AsRef<Path>) -> Result<Self> {
        let path = path.as_ref();
        let value: serde_json::Value = serde_json::from_slice(
            &fs::read(path).with_context(|| format!("reading {}", path.display()))?,
        )
        .with_context(|| format!("decoding {}", path.display()))?;
        Self::from_hf_value(&value)
    }

    pub fn from_hf_value(value: &serde_json::Value) -> Result<Self> {
        let mut config = Self::default();
        if let Some(raw) = value.get("max_new_tokens") {
            if !raw.is_null() {
                config.max_new_tokens = Some(
                    raw.as_u64()
                        .context("generation max_new_tokens must be a non-negative integer")?
                        .try_into()
                        .context("generation max_new_tokens exceeds usize")?,
                );
            }
        }
        if let Some(raw) = value.get("max_length") {
            config.max_length = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_u64()
                        .context("generation max_length must be a non-negative integer")?
                        .try_into()
                        .context("generation max_length exceeds usize")?,
                )
            };
        }
        if let Some(raw) = value.get("min_length") {
            if !raw.is_null() {
                config.min_length = raw
                    .as_u64()
                    .context("generation min_length must be a non-negative integer")?
                    .try_into()
                    .context("generation min_length exceeds usize")?;
            }
        }
        if let Some(raw) = value.get("min_new_tokens") {
            if !raw.is_null() {
                config.min_new_tokens = raw
                    .as_u64()
                    .context("generation min_new_tokens must be a non-negative integer")?
                    .try_into()
                    .context("generation min_new_tokens exceeds usize")?;
            }
        }
        if let Some(raw) = value.get("max_time") {
            config.max_time = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_f64()
                        .context("generation max_time must be numeric")?,
                )
            };
        }
        if let Some(raw) = value.get("stop_strings") {
            config.stop_strings = match raw {
                serde_json::Value::Null => Vec::new(),
                serde_json::Value::String(stop_string) => vec![stop_string.clone()],
                serde_json::Value::Array(stop_strings) => stop_strings
                    .iter()
                    .enumerate()
                    .map(|(index, stop_string)| {
                        stop_string
                            .as_str()
                            .with_context(|| {
                                format!("generation stop_strings[{index}] must be a string")
                            })
                            .map(str::to_owned)
                    })
                    .collect::<Result<Vec<_>>>()?,
                _ => bail!("generation stop_strings must be a string, string list, or null"),
            };
        }
        if let Some(raw) = value.get("do_sample") {
            if !raw.is_null() {
                config.do_sample = raw
                    .as_bool()
                    .context("generation do_sample must be a boolean")?;
            }
        }
        if let Some(raw) = value.get("use_cache") {
            if !raw.is_null() {
                config.use_cache = raw
                    .as_bool()
                    .context("generation use_cache must be a boolean")?;
            }
        }
        if let Some(raw) = value.get("cache_implementation") {
            config.cache_implementation = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_str()
                        .context("generation cache_implementation must be a string")?
                        .to_owned(),
                )
            };
        }
        if let Some(raw) = value.get("cache_config") {
            config.cache_config = (!raw.is_null()).then(|| raw.clone());
        }
        if let Some(raw) = value.get("max_cache_len") {
            config.max_cache_len = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_u64()
                        .context("generation max_cache_len must be a positive integer")?
                        .try_into()
                        .context("generation max_cache_len exceeds usize")?,
                )
            };
        }
        if let Some(raw) = value.get("prefill_chunk_size") {
            config.prefill_chunk_size = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_u64()
                        .context("generation prefill_chunk_size must be a positive integer")?
                        .try_into()
                        .context("generation prefill_chunk_size exceeds usize")?,
                )
            };
        }
        if let Some(raw) = value.get("guidance_scale") {
            config.guidance_scale = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_f64()
                        .context("generation guidance_scale must be numeric")?
                        as f32,
                )
            };
        }
        if let Some(raw) = value.get("token_healing") {
            if !raw.is_null() {
                config.token_healing = raw
                    .as_bool()
                    .context("generation token_healing must be a boolean")?;
            }
        }
        if let Some(raw) = value.get("watermarking_config") {
            config.watermarking_config = (!raw.is_null()).then(|| raw.clone());
        }
        for (field, slot) in [
            ("temperature", &mut config.temperature),
            ("top_p", &mut config.top_p),
            ("repetition_penalty", &mut config.repetition_penalty),
            (
                "encoder_repetition_penalty",
                &mut config.encoder_repetition_penalty,
            ),
            ("length_penalty", &mut config.length_penalty),
        ] {
            if let Some(raw) = value.get(field) {
                if !raw.is_null() {
                    *slot = raw
                        .as_f64()
                        .with_context(|| format!("generation {field} must be numeric"))?
                        as f32;
                }
            }
        }
        for (field, slot) in [
            ("top_h", &mut config.top_h),
            ("min_p", &mut config.min_p),
            ("typical_p", &mut config.typical_p),
            ("epsilon_cutoff", &mut config.epsilon_cutoff),
            ("eta_cutoff", &mut config.eta_cutoff),
        ] {
            if let Some(raw) = value.get(field) {
                *slot = if raw.is_null() {
                    None
                } else {
                    Some(
                        raw.as_f64()
                            .with_context(|| format!("generation {field} must be numeric"))?
                            as f32,
                    )
                };
            }
        }
        if let Some(raw) = value.get("top_k") {
            if !raw.is_null() {
                config.top_k = raw
                    .as_u64()
                    .context("generation top_k must be a non-negative integer")?
                    .try_into()
                    .context("generation top_k exceeds usize")?;
            }
        }
        if let Some(raw) = value.get("num_beams") {
            if !raw.is_null() {
                config.num_beams = raw
                    .as_u64()
                    .context("generation num_beams must be a positive integer")?
                    .try_into()
                    .context("generation num_beams exceeds usize")?;
            }
        }
        for (field, slot) in [
            ("penalty_alpha", &mut config.penalty_alpha),
            ("diversity_penalty", &mut config.diversity_penalty),
        ] {
            if let Some(raw) = value.get(field) {
                *slot = if raw.is_null() {
                    None
                } else {
                    Some(
                        raw.as_f64()
                            .with_context(|| format!("generation {field} must be numeric"))?
                            as f32,
                    )
                };
            }
        }
        for (field, slot) in [
            ("num_beam_groups", &mut config.num_beam_groups),
            (
                "prompt_lookup_num_tokens",
                &mut config.prompt_lookup_num_tokens,
            ),
            (
                "max_matching_ngram_size",
                &mut config.max_matching_ngram_size,
            ),
            ("assistant_early_exit", &mut config.assistant_early_exit),
        ] {
            if let Some(raw) = value.get(field) {
                *slot = if raw.is_null() {
                    None
                } else {
                    Some(
                        raw.as_u64()
                            .with_context(|| {
                                format!("generation {field} must be a non-negative integer")
                            })?
                            .try_into()
                            .with_context(|| format!("generation {field} exceeds usize"))?,
                    )
                };
            }
        }
        if let Some(raw) = value.get("use_mtp") {
            if !raw.is_null() {
                config.use_mtp = raw
                    .as_bool()
                    .context("generation use_mtp must be a boolean")?;
            }
        }
        if let Some(raw) = value.get("is_assistant") {
            if !raw.is_null() {
                config.is_assistant = raw
                    .as_bool()
                    .context("generation is_assistant must be a boolean")?;
            }
        }
        if let Some(raw) = value.get("num_assistant_tokens") {
            if !raw.is_null() {
                config.num_assistant_tokens = raw
                    .as_u64()
                    .context("generation num_assistant_tokens must be a positive integer")?
                    .try_into()
                    .context("generation num_assistant_tokens exceeds usize")?;
            }
        }
        if let Some(raw) = value.get("num_assistant_tokens_schedule") {
            if !raw.is_null() {
                config.num_assistant_tokens_schedule = raw
                    .as_str()
                    .context("generation num_assistant_tokens_schedule must be a string")?
                    .to_owned();
            }
        }
        if let Some(raw) = value.get("assistant_confidence_threshold") {
            config.assistant_confidence_threshold = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_f64()
                        .context("generation assistant_confidence_threshold must be numeric")?
                        as f32,
                )
            };
        }
        if let Some(raw) = value.get("assistant_ensemble_weight") {
            config.assistant_ensemble_weight = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_f64()
                        .context("generation assistant_ensemble_weight must be numeric")?
                        as f32,
                )
            };
        }
        for (field, slot) in [
            ("assistant_lookbehind", &mut config.assistant_lookbehind),
            ("target_lookbehind", &mut config.target_lookbehind),
        ] {
            if let Some(raw) = value.get(field) {
                if !raw.is_null() {
                    *slot = raw
                        .as_u64()
                        .with_context(|| {
                            format!("generation {field} must be a non-negative integer")
                        })?
                        .try_into()
                        .with_context(|| format!("generation {field} exceeds usize"))?;
                }
            }
        }
        if let Some(raw) = value.get("speculation_type") {
            config.speculation_type = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_str()
                        .context("generation speculation_type must be a string")?
                        .to_owned(),
                )
            };
        }
        for (field, slot) in [
            ("constraints", &mut config.constraints),
            ("force_words_ids", &mut config.force_words_ids),
            ("dola_layers", &mut config.dola_layers),
        ] {
            if let Some(raw) = value.get(field) {
                *slot = (!raw.is_null()).then(|| raw.clone());
            }
        }
        if let Some(raw) = value.get("num_return_sequences") {
            if !raw.is_null() {
                config.num_return_sequences = raw
                    .as_u64()
                    .context("generation num_return_sequences must be a positive integer")?
                    .try_into()
                    .context("generation num_return_sequences exceeds usize")?;
            }
        }
        if let Some(raw) = value.get("no_repeat_ngram_size") {
            if !raw.is_null() {
                config.no_repeat_ngram_size = raw
                    .as_u64()
                    .context("generation no_repeat_ngram_size must be a non-negative integer")?
                    .try_into()
                    .context("generation no_repeat_ngram_size exceeds usize")?;
            }
        }
        if let Some(raw) = value.get("encoder_no_repeat_ngram_size") {
            if !raw.is_null() {
                config.encoder_no_repeat_ngram_size = raw
                    .as_u64()
                    .context(
                        "generation encoder_no_repeat_ngram_size must be a non-negative integer",
                    )?
                    .try_into()
                    .context("generation encoder_no_repeat_ngram_size exceeds usize")?;
            }
        }
        if let Some(raw) = value.get("early_stopping") {
            match raw {
                serde_json::Value::Null => {}
                serde_json::Value::Bool(value) => {
                    config.early_stopping = *value;
                    config.early_stopping_never = false;
                }
                serde_json::Value::String(value) if value == "never" => {
                    config.early_stopping = false;
                    config.early_stopping_never = true;
                }
                _ => bail!(
                    "generation early_stopping must be a boolean or the Hugging Face string \"never\""
                ),
            }
        }
        for (field, slot) in [
            ("renormalize_logits", &mut config.renormalize_logits),
            ("remove_invalid_values", &mut config.remove_invalid_values),
            ("output_scores", &mut config.output_scores),
            ("output_logits", &mut config.output_logits),
            ("output_attentions", &mut config.output_attentions),
            ("output_hidden_states", &mut config.output_hidden_states),
            (
                "return_dict_in_generate",
                &mut config.return_dict_in_generate,
            ),
            ("disable_compile", &mut config.disable_compile),
        ] {
            if let Some(raw) = value.get(field) {
                if !raw.is_null() {
                    *slot = raw
                        .as_bool()
                        .with_context(|| format!("generation {field} must be a boolean"))?;
                }
            }
        }
        if let Some(raw) = value.get("compile_config") {
            config.compile_config = (!raw.is_null()).then(|| raw.clone());
        }
        if let Some(raw) = value.get("continuous_batching_config") {
            config.continuous_batching_config = (!raw.is_null()).then(|| raw.clone());
        }
        if let Some(raw) = value.get("low_memory") {
            config.low_memory = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_bool()
                        .context("generation low_memory must be a boolean")?,
                )
            };
        }
        if let Some(raw) = value.get("exponential_decay_length_penalty") {
            config.exponential_decay_length_penalty = match raw {
                serde_json::Value::Null => None,
                serde_json::Value::Array(values) if values.len() == 2 => {
                    let start_index = values[0]
                        .as_u64()
                        .context(
                            "generation exponential_decay_length_penalty start index must be a non-negative integer",
                        )?
                        .try_into()
                        .context(
                            "generation exponential_decay_length_penalty start index exceeds usize",
                        )?;
                    let factor = values[1]
                        .as_f64()
                        .context(
                            "generation exponential_decay_length_penalty factor must be numeric",
                        )? as f32;
                    Some((start_index, factor))
                }
                _ => bail!(
                    "generation exponential_decay_length_penalty must be [start_index, decay_factor] or null"
                ),
            };
        }
        if let Some(raw) = value.get("seed") {
            if !raw.is_null() {
                config.seed = raw
                    .as_u64()
                    .context("generation seed must be a non-negative integer")?;
            }
        }
        if let Some(raw) = value.get("sequence_bias") {
            config.sequence_bias = match raw {
                serde_json::Value::Null => Vec::new(),
                serde_json::Value::Array(entries) => entries
                    .iter()
                    .enumerate()
                    .map(|(entry_index, entry)| {
                        let pair = entry.as_array().with_context(|| {
                            format!(
                                "generation sequence_bias[{entry_index}] must be [token_ids, bias]"
                            )
                        })?;
                        if pair.len() != 2 {
                            bail!(
                                "generation sequence_bias[{entry_index}] must contain exactly token_ids and bias"
                            );
                        }
                        let tokens = pair[0].as_array().with_context(|| {
                            format!(
                                "generation sequence_bias[{entry_index}][0] must be a non-empty integer list"
                            )
                        })?;
                        if tokens.is_empty() {
                            bail!(
                                "generation sequence_bias[{entry_index}][0] must not be empty"
                            );
                        }
                        let tokens = tokens
                            .iter()
                            .enumerate()
                            .map(|(token_index, token)| {
                                token
                                    .as_u64()
                                    .with_context(|| {
                                        format!(
                                            "generation sequence_bias[{entry_index}][0][{token_index}] must be a non-negative integer"
                                        )
                                    })?
                                    .try_into()
                                    .context("generation sequence_bias token exceeds u32")
                            })
                            .collect::<Result<Vec<_>>>()?;
                        let bias = pair[1].as_f64().with_context(|| {
                            format!("generation sequence_bias[{entry_index}][1] must be numeric")
                        })? as f32;
                        if !bias.is_finite() {
                            bail!("generation sequence_bias[{entry_index}][1] must be finite");
                        }
                        Ok((tokens, bias))
                    })
                    .collect::<Result<Vec<_>>>()?,
                _ => bail!(
                    "generation sequence_bias must be a list of [token_ids, bias] pairs or null"
                ),
            };
        }
        if let Some(raw) = value.get("bad_words_ids") {
            config.bad_words_ids = match raw {
                serde_json::Value::Null => Vec::new(),
                serde_json::Value::Array(sequences) => sequences
                    .iter()
                    .enumerate()
                    .map(|(sequence_index, sequence)| {
                        let sequence = sequence.as_array().with_context(|| {
                            format!(
                                "generation bad_words_ids[{sequence_index}] must be an integer list"
                            )
                        })?;
                        if sequence.is_empty() {
                            bail!("generation bad_words_ids[{sequence_index}] must not be empty");
                        }
                        sequence
                            .iter()
                            .enumerate()
                            .map(|(token_index, token)| {
                                token
                                    .as_u64()
                                    .with_context(|| {
                                        format!(
                                            "generation bad_words_ids[{sequence_index}][{token_index}] must be a non-negative integer"
                                        )
                                    })?
                                    .try_into()
                                    .context("generation bad_words_ids token exceeds u32")
                            })
                            .collect::<Result<Vec<_>>>()
                    })
                    .collect::<Result<Vec<_>>>()?,
                _ => bail!("generation bad_words_ids must be a list of integer lists or null"),
            };
        }
        for (field, target) in [
            ("suppress_tokens", &mut config.suppress_tokens),
            ("begin_suppress_tokens", &mut config.begin_suppress_tokens),
        ] {
            if let Some(raw) = value.get(field) {
                *target = match raw {
                    serde_json::Value::Null => Vec::new(),
                    serde_json::Value::Array(tokens) => tokens
                        .iter()
                        .map(|token| {
                            token
                                .as_u64()
                                .with_context(|| {
                                    format!(
                                        "generation {field} entries must be non-negative integers"
                                    )
                                })?
                                .try_into()
                                .with_context(|| format!("generation {field} token exceeds u32"))
                        })
                        .collect::<Result<Vec<_>>>()?,
                    _ => bail!("generation {field} must be an integer list or null"),
                };
            }
        }
        for (field, target) in [
            ("pad_token_id", &mut config.pad_token_id),
            ("bos_token_id", &mut config.bos_token_id),
        ] {
            if let Some(raw) = value.get(field) {
                *target = if raw.is_null() {
                    None
                } else {
                    Some(
                        raw.as_u64()
                            .with_context(|| {
                                format!("generation {field} must be a non-negative integer")
                            })?
                            .try_into()
                            .with_context(|| format!("generation {field} exceeds u32"))?,
                    )
                };
            }
        }
        if let Some(raw) = value.get("decoder_start_token_id") {
            config.decoder_start_token_id = match raw {
                serde_json::Value::Null => None,
                serde_json::Value::Number(number) => Some(
                    number
                        .as_u64()
                        .context(
                            "generation decoder_start_token_id must be a non-negative integer or integer list",
                        )?
                        .try_into()
                        .map(VulkanTransformerDecoderStartTokenId::Single)
                        .context("generation decoder_start_token_id exceeds u32")?,
                ),
                serde_json::Value::Array(values) => Some(
                    VulkanTransformerDecoderStartTokenId::Batch(
                        values
                            .iter()
                            .map(|item| {
                                item.as_u64()
                                    .context(
                                        "generation decoder_start_token_id entries must be non-negative integers",
                                    )?
                                    .try_into()
                                    .context(
                                        "generation decoder_start_token_id entry exceeds u32",
                                    )
                            })
                            .collect::<Result<Vec<_>>>()?,
                    ),
                ),
                _ => bail!(
                    "generation decoder_start_token_id must be a non-negative integer, integer list, or null"
                ),
            };
        }
        if let Some(raw) = value.get("forced_bos_token_id") {
            config.forced_bos_token_id = if raw.is_null() {
                None
            } else {
                Some(
                    raw.as_u64()
                        .context("generation forced_bos_token_id must be a non-negative integer")?
                        .try_into()
                        .context("generation forced_bos_token_id exceeds u32")?,
                )
            };
        }
        if let Some(raw) = value.get("forced_eos_token_id") {
            config.forced_eos_token_ids = match raw {
                serde_json::Value::Null => Vec::new(),
                serde_json::Value::Number(number) => vec![number
                    .as_u64()
                    .context("generation forced_eos_token_id must be non-negative")?
                    .try_into()
                    .context("generation forced_eos_token_id exceeds u32")?],
                serde_json::Value::Array(values) => values
                    .iter()
                    .map(|item| {
                        item.as_u64()
                            .context(
                                "generation forced_eos_token_id entries must be non-negative integers",
                            )?
                            .try_into()
                            .context("generation forced_eos_token_id entry exceeds u32")
                    })
                    .collect::<Result<Vec<_>>>()?,
                _ => bail!(
                    "generation forced_eos_token_id must be an integer, integer list, or null"
                ),
            };
        }
        if let Some(raw) = value.get("eos_token_id") {
            config.eos_token_ids = match raw {
                serde_json::Value::Null => Vec::new(),
                serde_json::Value::Number(number) => vec![number
                    .as_u64()
                    .context("generation eos_token_id must be non-negative")?
                    .try_into()
                    .context("generation eos_token_id exceeds u32")?],
                serde_json::Value::Array(values) => values
                    .iter()
                    .map(|item| {
                        item.as_u64()
                            .context(
                                "generation eos_token_id entries must be non-negative integers",
                            )?
                            .try_into()
                            .context("generation eos_token_id entry exceeds u32")
                    })
                    .collect::<Result<Vec<_>>>()?,
                _ => bail!("generation eos_token_id must be an integer, integer list, or null"),
            };
        }
        config
            .bad_words_ids
            .retain(|sequence| sequence.len() != 1 || !config.eos_token_ids.contains(&sequence[0]));
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<()> {
        if self.max_length == Some(0) {
            bail!("generation max_length must be positive when provided");
        }
        if self.max_new_tokens == Some(0) {
            bail!("generation max_new_tokens must be greater than 0 when provided");
        }
        if self.max_new_tokens.is_none() && self.max_length.is_none() {
            bail!("generation requires max_new_tokens or max_length");
        }
        if self.max_time.is_some_and(|max_time| !max_time.is_finite()) {
            bail!("generation max_time must be finite when provided");
        }
        if self
            .stop_strings
            .iter()
            .any(|stop_string| stop_string.is_empty())
        {
            bail!("generation stop_strings entries must not be empty");
        }
        if let Some(cache_implementation) = self.cache_implementation.as_deref() {
            if !matches!(
                cache_implementation,
                "static"
                    | "offloaded_static"
                    | "sliding_window"
                    | "hybrid"
                    | "hybrid_chunked"
                    | "offloaded_hybrid"
                    | "offloaded_hybrid_chunked"
                    | "dynamic"
                    | "offloaded"
                    | "quantized"
                    | "paged"
            ) {
                bail!(
                    "invalid generation cache_implementation {cache_implementation:?}; expected a current Hugging Face cache implementation"
                );
            }
        }
        if self.max_cache_len == Some(0) {
            bail!("generation max_cache_len must be positive when provided");
        }
        if self.prefill_chunk_size == Some(0) {
            bail!("generation prefill_chunk_size must be positive when provided");
        }
        if self.decoder_start_token_id.as_ref().is_some_and(|decoder_start| {
            matches!(decoder_start, VulkanTransformerDecoderStartTokenId::Batch(values) if values.is_empty())
        }) {
            bail!("generation decoder_start_token_id batch list must not be empty");
        }
        if self.assistant_lookbehind == 0 {
            bail!("generation assistant_lookbehind must be positive");
        }
        if self.target_lookbehind == 0 {
            bail!("generation target_lookbehind must be positive");
        }
        for (field, config) in [
            ("cache_config", self.cache_config.as_ref()),
            ("compile_config", self.compile_config.as_ref()),
            (
                "continuous_batching_config",
                self.continuous_batching_config.as_ref(),
            ),
            ("watermarking_config", self.watermarking_config.as_ref()),
        ] {
            if config.is_some_and(|config| !config.is_object()) {
                bail!("generation {field} must be an object when provided");
            }
        }
        if let Some(watermarking_config) = self.watermarking_config.as_ref() {
            generation_parse_watermarking_config(watermarking_config)?;
        }
        if self
            .guidance_scale
            .is_some_and(|guidance_scale| !guidance_scale.is_finite())
        {
            bail!("generation guidance_scale must be finite when provided");
        }
        if self
            .guidance_scale
            .is_some_and(|guidance_scale| guidance_scale != 1.0)
        {
            if self
                .negative_prompt_ids
                .as_ref()
                .is_some_and(|negative_prompt_ids| negative_prompt_ids.is_empty())
            {
                bail!("generation negative_prompt_ids must not be empty when CFG is enabled");
            }
            if let Some(negative_prompt_attention_mask) =
                self.negative_prompt_attention_mask.as_ref()
            {
                let expected_len = self.negative_prompt_ids.as_ref().map_or(1, Vec::len);
                if negative_prompt_attention_mask.len() != expected_len {
                    bail!(
                        "generation negative_prompt_attention_mask length {} does not match unconditional prompt length {}",
                        negative_prompt_attention_mask.len(),
                        expected_len
                    );
                }
                if negative_prompt_attention_mask
                    .iter()
                    .any(|value| !value.is_finite())
                {
                    bail!("generation negative_prompt_attention_mask values must be finite");
                }
            }
        }
        if !self.temperature.is_finite() || self.temperature <= 0.0 {
            bail!("generation temperature must be finite and positive");
        }
        if !self.top_p.is_finite() || !(0.0..=1.0).contains(&self.top_p) || self.top_p == 0.0 {
            bail!("generation top_p must be finite and in (0, 1]");
        }
        if let Some(top_h) = self.top_h {
            if !top_h.is_finite() || !(0.0..=1.0).contains(&top_h) || top_h == 0.0 {
                bail!("generation top_h must be finite and in (0, 1]");
            }
        }
        if let Some(min_p) = self.min_p {
            if !min_p.is_finite() || !(0.0..=1.0).contains(&min_p) {
                bail!("generation min_p must be finite and in [0, 1]");
            }
        }
        if let Some(typical_p) = self.typical_p {
            if !typical_p.is_finite() || !(0.0..=1.0).contains(&typical_p) || typical_p == 0.0 {
                bail!("generation typical_p must be finite and in (0, 1]");
            }
        }
        for (field, cutoff) in [
            ("epsilon_cutoff", self.epsilon_cutoff),
            ("eta_cutoff", self.eta_cutoff),
        ] {
            if let Some(cutoff) = cutoff {
                if !cutoff.is_finite() || !(0.0..1.0).contains(&cutoff) || cutoff == 0.0 {
                    bail!("generation {field} must be finite and in (0, 1)");
                }
            }
        }
        if !self.repetition_penalty.is_finite() || self.repetition_penalty <= 0.0 {
            bail!("generation repetition_penalty must be finite and positive");
        }
        if !self.encoder_repetition_penalty.is_finite() || self.encoder_repetition_penalty <= 0.0 {
            bail!("generation encoder_repetition_penalty must be finite and positive");
        }
        if self
            .sequence_bias
            .iter()
            .any(|(tokens, bias)| tokens.is_empty() || !bias.is_finite())
        {
            bail!(
                "generation sequence_bias entries require non-empty token lists and finite biases"
            );
        }
        if let Some((_, factor)) = self.exponential_decay_length_penalty {
            if !factor.is_finite() || factor <= 0.0 {
                bail!(
                    "generation exponential_decay_length_penalty factor must be finite and positive"
                );
            }
        }
        if self.num_beams == 0 {
            bail!("generation num_beams must be positive");
        }
        if self.num_assistant_tokens == 0 {
            bail!("generation num_assistant_tokens must be positive");
        }
        if !matches!(
            self.num_assistant_tokens_schedule.as_str(),
            "constant" | "heuristic" | "heuristic_transient"
        ) {
            bail!(
                "generation num_assistant_tokens_schedule must be one of constant, heuristic, or heuristic_transient"
            );
        }
        if self
            .assistant_confidence_threshold
            .is_some_and(|threshold| !threshold.is_finite() || !(0.0..=1.0).contains(&threshold))
        {
            bail!("generation assistant_confidence_threshold must be finite and in [0, 1]");
        }
        if self
            .assistant_ensemble_weight
            .is_some_and(|weight| !weight.is_finite() || weight <= 0.0 || weight >= 1.0)
        {
            bail!(
                "generation assistant_ensemble_weight must be finite and in the open interval (0, 1)"
            );
        }
        if self.prompt_lookup_num_tokens == Some(0) {
            bail!("generation prompt_lookup_num_tokens must be positive when provided");
        }
        if self.max_matching_ngram_size == Some(0) {
            bail!("generation max_matching_ngram_size must be positive when provided");
        }
        if self.assistant_early_exit == Some(0) {
            bail!("generation assistant_early_exit must be positive when provided");
        }
        if let Some(dola_layers) = self.dola_layers.as_ref() {
            generation_validate_dola_layers(dola_layers)?;
        }
        if self.constraints.is_some() || self.force_words_ids.is_some() {
            if self.num_beams <= 1 {
                bail!("constrained beam search requires num_beams > 1");
            }
            if self.do_sample {
                bail!("constrained beam search requires do_sample=false");
            }
            if self.constraints.is_none() {
                generation_parse_force_words_ids(
                    self.force_words_ids
                        .as_ref()
                        .context("constrained beam search requires force_words_ids")?,
                )?;
            }
        }
        if self
            .penalty_alpha
            .is_some_and(|penalty_alpha| !penalty_alpha.is_finite())
        {
            bail!("generation penalty_alpha must be finite when provided");
        }
        if self
            .diversity_penalty
            .is_some_and(|diversity_penalty| !diversity_penalty.is_finite())
        {
            bail!("generation diversity_penalty must be finite when provided");
        }
        if let Some(num_beam_groups) = self.num_beam_groups {
            if num_beam_groups == 0 {
                bail!("generation num_beam_groups must be positive when provided");
            }
            if num_beam_groups > self.num_beams {
                bail!(
                    "generation num_beam_groups {} exceeds num_beams {}",
                    num_beam_groups,
                    self.num_beams
                );
            }
            if self.num_beams % num_beam_groups != 0 {
                bail!(
                    "generation num_beams {} must be divisible by num_beam_groups {}",
                    self.num_beams,
                    num_beam_groups
                );
            }
            if num_beam_groups > 1 {
                if self.do_sample {
                    bail!("group beam search requires do_sample=false");
                }
                if self.diversity_penalty.unwrap_or(0.0) <= 0.0 {
                    bail!("group beam search requires diversity_penalty > 0");
                }
            }
        }
        if self.num_return_sequences == 0 {
            bail!("generation num_return_sequences must be positive");
        }
        if self.num_beams == 1 && !self.do_sample && self.num_return_sequences != 1 {
            bail!(
                "greedy generation requires num_return_sequences=1; enable sampling or beam search for multiple sequences"
            );
        }
        if self.num_beams > 1 && self.num_return_sequences > self.num_beams {
            bail!(
                "generation num_return_sequences {} exceeds num_beams {}",
                self.num_return_sequences,
                self.num_beams
            );
        }
        if !self.length_penalty.is_finite() {
            bail!("generation length_penalty must be finite");
        }
        Ok(())
    }

    pub fn generation_mode(&self) -> VulkanTransformerGenerationMode {
        let mut mode = if self.constraints.is_some() || self.force_words_ids.is_some() {
            VulkanTransformerGenerationMode::ConstrainedBeamSearch
        } else if self.num_beams == 1 {
            if !self.do_sample {
                if self.top_k > 1
                    && self
                        .penalty_alpha
                        .is_some_and(|penalty_alpha| penalty_alpha > 0.0)
                {
                    VulkanTransformerGenerationMode::ContrastiveSearch
                } else {
                    VulkanTransformerGenerationMode::GreedySearch
                }
            } else {
                VulkanTransformerGenerationMode::Sample
            }
        } else if self.num_beam_groups.is_some_and(|groups| groups > 1) {
            VulkanTransformerGenerationMode::GroupBeamSearch
        } else if self.do_sample {
            VulkanTransformerGenerationMode::BeamSample
        } else {
            VulkanTransformerGenerationMode::BeamSearch
        };

        if (self.use_mtp
            || self.prompt_lookup_num_tokens.is_some()
            || self.assistant_early_exit.is_some())
            && matches!(
                mode,
                VulkanTransformerGenerationMode::GreedySearch
                    | VulkanTransformerGenerationMode::Sample
            )
        {
            mode = VulkanTransformerGenerationMode::AssistedGeneration;
        }
        if self.dola_layers.is_some()
            && matches!(
                mode,
                VulkanTransformerGenerationMode::GreedySearch
                    | VulkanTransformerGenerationMode::Sample
            )
        {
            mode = VulkanTransformerGenerationMode::DolaGeneration;
        }
        mode
    }

    fn validate_supported_generation_mode(&self) -> Result<()> {
        self.validate()?;
        if let Some(cache_implementation) = self.cache_implementation.as_deref() {
            // The native Vulkan executor owns its KV allocation policy. HF's
            // dynamic/static/offload/hybrid spellings therefore all map to the
            // existing numerically exact contiguous native cache while
            // retaining the request metadata. HF's `paged` spelling opts into
            // the native paged Vulkan KV backend for compatible attention
            // layers. Quantized caches still change the stored KV precision
            // and require a distinct native implementation.
            if cache_implementation == "quantized" {
                bail!(
                    "Vulkan Transformer generation does not yet implement cache_implementation={cache_implementation:?}; quantized caches require a dedicated native storage backend"
                );
            }
        }
        if self.uses_paged_kv_cache() && !self.use_cache {
            bail!("cache_implementation=\"paged\" requires use_cache=true");
        }
        // Current Transformers only consumes `cache_config` for quantized
        // caches. Other cache implementations ignore it, which is also the
        // correct behavior for the native cache above. `prefill_chunk_size`
        // is a compile/scheduling hint; Vulkan command recording is already
        // independent of torch.compile, so accepting the hint is numerically
        // equivalent to HF generation without chunked compilation.
        if !self.stop_strings.is_empty()
            && self
                .stop_string_matcher
                .as_ref()
                .is_none_or(|matcher| matcher.stop_strings != self.stop_strings)
        {
            bail!(
                "Vulkan Transformer generation with stop_strings requires prepare_stop_strings() with the request tokenizer"
            );
        }
        if self.token_healing {
            bail!(
                "Vulkan Transformer generation requires a tokenizer-aware entrypoint for token_healing"
            );
        }
        if let Some(speculation_type) = self.speculation_type.as_deref() {
            bail!(
                "Vulkan Transformer generation does not yet implement speculation_type={speculation_type:?}"
            );
        }
        if self.continuous_batching_config.is_some() {
            if !self.uses_paged_kv_cache() {
                bail!(
                    "Vulkan Transformer continuous_batching_config requires cache_implementation=\"paged\""
                );
            }
            // Validate the native continuous-serving surface up front. The HF
            // config object contains allocator, offload, scheduler, CUDA-graph,
            // and serving knobs whose semantics are not interchangeable with
            // this Vulkan scheduler; accepting them and silently ignoring them
            // would make an explicitly requested serving policy misleading.
            self.continuous_batching_max_requests(1)?;
        }
        match self.generation_mode() {
            VulkanTransformerGenerationMode::GreedySearch
            | VulkanTransformerGenerationMode::Sample
            | VulkanTransformerGenerationMode::BeamSearch
            | VulkanTransformerGenerationMode::BeamSample
            | VulkanTransformerGenerationMode::GroupBeamSearch
            | VulkanTransformerGenerationMode::ContrastiveSearch
            | VulkanTransformerGenerationMode::DolaGeneration => Ok(()),
            VulkanTransformerGenerationMode::ConstrainedBeamSearch => {
                generation_force_constraints_from_config(self).map(|_| ())
            }
            VulkanTransformerGenerationMode::AssistedGeneration => {
                if self.num_return_sequences != 1 {
                    bail!(
                        "assisted generation requires num_return_sequences=1, got {}",
                        self.num_return_sequences
                    );
                }
                if !self.use_cache {
                    bail!("assisted generation requires use_cache=true");
                }
                if self.assistant_early_exit.is_some() {
                    return Ok(());
                }
                if self.prompt_lookup_num_tokens.is_some() {
                    if self.assistant_ensemble_weight.is_some() {
                        bail!(
                            "assistant_ensemble_weight requires candidate logits and is not supported with prompt lookup decoding"
                        );
                    }
                    return Ok(());
                }
                if self.use_mtp {
                    bail!("Vulkan Transformer assisted generation does not yet implement use_mtp");
                }
                bail!(
                    "Vulkan Transformer assisted generation currently requires prompt_lookup_num_tokens"
                )
            }
        }
    }

    fn effective_max_new_tokens(&self, prompt_len: usize, context_len: usize) -> usize {
        let capacity = context_len.saturating_sub(prompt_len);
        match self.max_new_tokens {
            Some(value) => value.min(capacity),
            None => self
                .max_length
                .unwrap_or(context_len)
                .saturating_sub(prompt_len)
                .min(capacity),
        }
    }

    fn is_eos(&self, token: u32) -> bool {
        self.eos_token_ids.contains(&token)
    }

    fn should_stop_sequence(&self, sequence: &[u32]) -> bool {
        sequence.last().is_some_and(|token| self.is_eos(*token))
            || self
                .stop_string_matcher
                .as_ref()
                .is_some_and(|matcher| matcher.matches(sequence))
    }

    fn uses_static_cache_policy(&self) -> bool {
        matches!(
            self.cache_implementation.as_deref(),
            Some(
                "static"
                    | "offloaded_static"
                    | "sliding_window"
                    | "hybrid"
                    | "hybrid_chunked"
                    | "offloaded_hybrid"
                    | "offloaded_hybrid_chunked"
            )
        )
    }

    fn uses_paged_kv_cache(&self) -> bool {
        self.cache_implementation.as_deref() == Some("paged")
    }

    fn continuous_batching_max_requests(&self, batch_len: usize) -> Result<usize> {
        let Some(raw) = self.continuous_batching_config.as_ref() else {
            return Ok(batch_len.max(1));
        };
        let object = raw
            .as_object()
            .context("continuous_batching_config must be a JSON object")?;
        for field in object.keys() {
            if !matches!(field.as_str(), "block_size" | "max_requests_per_batch") {
                bail!(
                    "continuous_batching_config.{field} is not implemented by the native Vulkan scheduler; supported fields are block_size and max_requests_per_batch"
                );
            }
        }
        let max_requests = object
            .get("max_requests_per_batch")
            .filter(|value| !value.is_null())
            .map(|value| {
                value
                    .as_u64()
                    .context("continuous_batching_config.max_requests_per_batch must be a positive integer")
                    .and_then(|value| {
                        usize::try_from(value).context(
                            "continuous_batching_config.max_requests_per_batch exceeds usize",
                        )
                    })
            })
            .transpose()?
            .unwrap_or(batch_len.max(1));
        if max_requests == 0 {
            bail!("continuous_batching_config.max_requests_per_batch must be >= 1");
        }
        if let Some(block_size) = object
            .get("block_size")
            .filter(|value| !value.is_null())
            .map(|value| {
                value
                    .as_u64()
                    .context("continuous_batching_config.block_size must be a positive integer")
            })
            .transpose()?
        {
            if block_size != GENERATION_KV_PAGE_TOKENS as u64 {
                bail!(
                    "continuous_batching_config.block_size={block_size} is incompatible with this Vulkan build; native paged KV uses block_size={} tokens",
                    GENERATION_KV_PAGE_TOKENS
                );
            }
        }
        Ok(max_requests.min(batch_len.max(1)))
    }

    fn should_stop_after_token(&self, sequence: &[u32], token: u32) -> bool {
        if self.is_eos(token) {
            return true;
        }
        let Some(matcher) = self.stop_string_matcher.as_ref() else {
            return false;
        };
        let mut candidate = Vec::with_capacity(sequence.len() + 1);
        candidate.extend_from_slice(sequence);
        candidate.push(token);
        matcher.matches(&candidate)
    }
}

fn generation_max_time_reached(
    started: Instant,
    config: &VulkanTransformerGenerationConfig,
) -> bool {
    config
        .max_time
        .is_some_and(|max_time| started.elapsed().as_secs_f64() > max_time)
}

fn generation_remaining_max_time(max_time: Option<f64>, started: Instant) -> Option<f64> {
    max_time.map(|max_time| max_time - started.elapsed().as_secs_f64())
}

fn generation_apply_repetition_penalty(logits: &mut [f32], history: &[u32], penalty: f32) {
    if penalty == 1.0 {
        return;
    }
    let mut seen = BTreeSet::new();
    for &token in history {
        let index = token as usize;
        if index >= logits.len() || !seen.insert(index) {
            continue;
        }
        let score = &mut logits[index];
        if *score < 0.0 {
            *score *= penalty;
        } else {
            *score /= penalty;
        }
    }
}

fn generation_apply_encoder_repetition_penalty(
    scores: &mut [f32],
    encoder_input_ids: &[u32],
    penalty: f32,
) {
    if penalty == 1.0 {
        return;
    }
    // HF's EncoderRepetitionPenaltyLogitsProcessor deliberately applies the
    // inverse of ordinary repetition penalty: values > 1 reward tokens from
    // the source/prompt instead of suppressing them.
    let inverse_penalty = 1.0 / penalty;
    let mut seen = BTreeSet::new();
    for &token in encoder_input_ids {
        let index = token as usize;
        if index >= scores.len() || !seen.insert(index) {
            continue;
        }
        let score = &mut scores[index];
        if *score < 0.0 {
            *score *= inverse_penalty;
        } else {
            *score /= inverse_penalty;
        }
    }
}

fn generation_apply_encoder_no_repeat_ngram(
    scores: &mut [f32],
    history: &[u32],
    encoder_input_ids: &[u32],
    ngram_size: usize,
) {
    if ngram_size == 0 || encoder_input_ids.len() < ngram_size || history.len() + 1 < ngram_size {
        return;
    }
    if ngram_size == 1 {
        generation_suppress_tokens(scores, encoder_input_ids);
        return;
    }

    let prefix_len = ngram_size - 1;
    let suffix = &history[history.len() - prefix_len..];
    for window in encoder_input_ids.windows(ngram_size) {
        if &window[..prefix_len] == suffix {
            if let Some(score) = scores.get_mut(window[prefix_len] as usize) {
                *score = f32::NEG_INFINITY;
            }
        }
    }
}

fn generation_encoder_input_ids<'a>(
    history: &'a [u32],
    config: &'a VulkanTransformerGenerationConfig,
    step: usize,
) -> &'a [u32] {
    config.encoder_input_ids.as_deref().unwrap_or_else(|| {
        let prompt_len = history.len().saturating_sub(step);
        &history[..prompt_len]
    })
}

fn generation_apply_sequence_bias(
    scores: &mut [f32],
    history: &[u32],
    sequence_bias: &[(Vec<u32>, f32)],
) -> Result<()> {
    for (sequence, bias) in sequence_bias {
        let Some((&token, prefix)) = sequence.split_last() else {
            continue;
        };
        let token_index = token as usize;
        if token_index >= scores.len() {
            bail!(
                "generation sequence_bias token {} exceeds model vocabulary size {}",
                token,
                scores.len()
            );
        }
        if prefix.is_empty() {
            scores[token_index] += *bias;
            continue;
        }
        // Match current Transformers SequenceBiasLogitsProcessor exactly: a
        // multi-token bias is ignored until the context is at least as long
        // as the complete biased sequence, then its prefix is suffix-matched.
        if sequence.len() <= history.len() && &history[history.len() - prefix.len()..] == prefix {
            scores[token_index] += *bias;
        }
    }
    Ok(())
}

fn generation_suppress_eos(logits: &mut [f32], eos_token_ids: &[u32]) {
    for &token in eos_token_ids {
        if let Some(score) = logits.get_mut(token as usize) {
            *score = f32::NEG_INFINITY;
        }
    }
}

fn generation_suppress_tokens(scores: &mut [f32], token_ids: &[u32]) {
    for &token in token_ids {
        if let Some(score) = scores.get_mut(token as usize) {
            *score = f32::NEG_INFINITY;
        }
    }
}

fn generation_force_tokens(scores: &mut [f32], token_ids: &[u32]) {
    if token_ids.is_empty() {
        return;
    }
    let allowed = token_ids.iter().copied().collect::<BTreeSet<_>>();
    for (token, score) in scores.iter_mut().enumerate() {
        if !allowed.contains(&(token as u32)) {
            *score = f32::NEG_INFINITY;
        }
    }
}

fn generation_apply_exponential_decay_length_penalty(
    scores: &mut [f32],
    history_len: usize,
    prompt_len: usize,
    eos_token_ids: &[u32],
    penalty: Option<(usize, f32)>,
) {
    let Some((start_index, decay_factor)) = penalty else {
        return;
    };
    let regulation_start = prompt_len.saturating_add(start_index);
    if history_len <= regulation_start {
        return;
    }
    let penalty_index = history_len - regulation_start;
    let multiplier = decay_factor.powf(penalty_index as f32) - 1.0;
    for &token in eos_token_ids {
        if let Some(score) = scores.get_mut(token as usize) {
            *score += score.abs() * multiplier;
        }
    }
}

fn generation_remove_invalid_values(scores: &mut [f32]) {
    for score in scores {
        if score.is_nan() {
            *score = 0.0;
        } else if *score == f32::INFINITY {
            *score = f32::MAX;
        } else if *score == f32::NEG_INFINITY {
            *score = f32::MIN;
        }
    }
}

fn generation_apply_no_repeat_ngram(scores: &mut [f32], history: &[u32], ngram_size: usize) {
    if ngram_size == 0 || history.len() + 1 < ngram_size {
        return;
    }
    if ngram_size == 1 {
        generation_suppress_tokens(scores, history);
        return;
    }

    let prefix_len = ngram_size - 1;
    let suffix = &history[history.len() - prefix_len..];
    for window in history.windows(ngram_size) {
        if &window[..prefix_len] == suffix {
            if let Some(score) = scores.get_mut(window[prefix_len] as usize) {
                *score = f32::NEG_INFINITY;
            }
        }
    }
}

fn generation_apply_bad_words(scores: &mut [f32], history: &[u32], bad_words_ids: &[Vec<u32>]) {
    for sequence in bad_words_ids {
        let Some((&token, prefix)) = sequence.split_last() else {
            continue;
        };
        if prefix.len() <= history.len() && &history[history.len() - prefix.len()..] == prefix {
            if let Some(score) = scores.get_mut(token as usize) {
                *score = f32::NEG_INFINITY;
            }
        }
    }
}

fn generation_apply_sequence_constraints(
    scores: &mut [f32],
    history: &[u32],
    encoder_input_ids: &[u32],
    config: &VulkanTransformerGenerationConfig,
    step: usize,
    is_last_step: bool,
) {
    generation_apply_no_repeat_ngram(scores, history, config.no_repeat_ngram_size);
    generation_apply_encoder_no_repeat_ngram(
        scores,
        history,
        encoder_input_ids,
        config.encoder_no_repeat_ngram_size,
    );
    generation_apply_bad_words(scores, history, &config.bad_words_ids);
    if history.len() < config.min_length || step < config.min_new_tokens {
        generation_suppress_eos(scores, &config.eos_token_ids);
    }
    if history.len() == 1 {
        if let Some(token) = config.forced_bos_token_id {
            generation_force_tokens(scores, &[token]);
        }
    }
    if is_last_step && !config.forced_eos_token_ids.is_empty() {
        generation_force_tokens(scores, &config.forced_eos_token_ids);
    }
    // Match Transformers' InfNanRemoveLogitsProcessor placement: it runs
    // after forced BOS/EOS processors but before suppress/begin-suppress.
    if config.remove_invalid_values {
        generation_remove_invalid_values(scores);
    }
    let prompt_len = history.len().saturating_sub(step);
    generation_apply_exponential_decay_length_penalty(
        scores,
        history.len(),
        prompt_len,
        &config.eos_token_ids,
        config.exponential_decay_length_penalty,
    );
    generation_suppress_tokens(scores, &config.suppress_tokens);
    let begin_index = if history.len() == 1 && config.forced_bos_token_id.is_some() {
        2
    } else {
        history.len()
    };
    if history.len() == begin_index && step == 0 {
        generation_suppress_tokens(scores, &config.begin_suppress_tokens);
    } else if config.forced_bos_token_id.is_some() && history.len() == 2 && step == 1 {
        generation_suppress_tokens(scores, &config.begin_suppress_tokens);
    }
}

fn generation_argmax(logits: &[f32]) -> Result<u32> {
    let (index, _) = logits
        .iter()
        .copied()
        .enumerate()
        .filter(|(_, value)| value.is_finite())
        .max_by(|(left_index, left), (right_index, right)| {
            left.total_cmp(right)
                .then_with(|| right_index.cmp(left_index))
        })
        .context("generation logits contain no finite values")?;
    u32::try_from(index).context("generation token index exceeds u32")
}

fn generation_ranked_finite_logits(logits: &[f32]) -> Vec<(usize, f32)> {
    let mut ranked = logits
        .iter()
        .copied()
        .enumerate()
        .filter(|(_, value)| value.is_finite())
        .collect::<Vec<_>>();
    ranked.sort_by(|(left_index, left), (right_index, right)| {
        right
            .total_cmp(left)
            .then_with(|| left_index.cmp(right_index))
    });
    ranked
}

fn generation_log_softmax(logits: &[f32]) -> Result<Vec<f32>> {
    let ranked = generation_ranked_finite_logits(logits);
    let max_logit = ranked
        .first()
        .map(|(_, value)| f64::from(*value))
        .context("generation logits contain no finite values")?;
    let normalizer = ranked
        .iter()
        .map(|(_, value)| (f64::from(*value) - max_logit).exp())
        .sum::<f64>();
    if !normalizer.is_finite() || normalizer <= 0.0 {
        bail!("generation softmax normalizer is invalid");
    }
    let log_normalizer = normalizer.ln();
    let mut log_probs = vec![f32::NEG_INFINITY; logits.len()];
    for (index, value) in ranked {
        log_probs[index] = (f64::from(value) - max_logit - log_normalizer) as f32;
    }
    Ok(log_probs)
}

fn generation_validate_dola_layers(dola_layers: &serde_json::Value) -> Result<()> {
    match dola_layers {
        serde_json::Value::String(value) if value == "low" || value == "high" => Ok(()),
        serde_json::Value::Array(values) => {
            if values.is_empty() {
                bail!("generation dola_layers list must contain at least one layer index");
            }
            for (index, value) in values.iter().enumerate() {
                let layer = value.as_i64().with_context(|| {
                    format!("generation dola_layers[{index}] must be an integer layer index")
                })?;
                if layer < 0 {
                    bail!("generation dola_layers[{index}] must be non-negative, got {layer}");
                }
            }
            Ok(())
        }
        _ => bail!("generation dola_layers must be either \"low\", \"high\", or a list of integer layer indices"),
    }
}

/// Resolve the candidate premature hidden-state indices used by the official
/// `transformers-community/dola` generator. Hidden-state index zero is the
/// embedding output and index `num_layers` is the mature final decoder state,
/// so explicit premature candidates are always strictly below `num_layers`.
fn generation_dola_candidate_layers(
    dola_layers: &serde_json::Value,
    num_layers: usize,
    tie_word_embeddings: bool,
) -> Result<Vec<usize>> {
    generation_validate_dola_layers(dola_layers)?;
    if num_layers == 0 {
        bail!("DoLa generation requires a Transformer with at least one hidden layer");
    }

    let start_layer = if !tie_word_embeddings {
        0
    } else if num_layers > 2 {
        2
    } else if num_layers == 2 {
        1
    } else {
        0
    };

    let layers = match dola_layers {
        serde_json::Value::String(value) if value == "low" => {
            if start_layer == num_layers / 2 {
                vec![start_layer]
            } else {
                let end = if num_layers <= 40 { num_layers / 2 } else { 20 };
                (start_layer..end).step_by(2).collect()
            }
        }
        serde_json::Value::String(value) if value == "high" => {
            let start = if num_layers <= 40 {
                num_layers / 2
            } else {
                num_layers.saturating_sub(20)
            };
            (start..num_layers).step_by(2).collect()
        }
        serde_json::Value::Array(values) => values
            .iter()
            .filter_map(|value| value.as_u64())
            .filter_map(|value| usize::try_from(value).ok())
            .filter(|&layer| layer < num_layers)
            .collect(),
        _ => unreachable!("generation_validate_dola_layers accepted an invalid value"),
    };
    if layers.is_empty() {
        bail!("generation dola_layers selects no premature layers below final layer {num_layers}");
    }
    Ok(layers)
}

fn generation_dola_relative_top_filter(
    final_logits: &[f32],
    baseline_logits: &[f32],
) -> Result<(Vec<f32>, Vec<f32>)> {
    if final_logits.len() != baseline_logits.len() || final_logits.is_empty() {
        bail!("DoLa mature and premature logits must have the same non-zero vocabulary size");
    }
    let mut final_scores = generation_log_softmax(final_logits)?;
    let mut baseline_scores = generation_log_softmax(baseline_logits)?;
    let max_log_probability = final_scores
        .iter()
        .copied()
        .filter(|value| value.is_finite())
        .max_by(f32::total_cmp)
        .context("DoLa mature logits contain no finite values")?;
    // Official DoLa uses relative_top=0.1 and min_tokens_to_keep=1.
    let threshold = max_log_probability.min(max_log_probability + 0.1_f32.ln());
    for (final_score, baseline_score) in final_scores.iter_mut().zip(&mut baseline_scores) {
        if *final_score < threshold {
            *final_score = f32::NEG_INFINITY;
            *baseline_score = -1.0e-3;
        }
    }
    Ok((final_scores, baseline_scores))
}

fn generation_dola_js_divergence(final_logits: &[f32], premature_logits: &[f32]) -> Result<f64> {
    if final_logits.len() != premature_logits.len() || final_logits.is_empty() {
        bail!("DoLa mature and premature logits must have the same non-zero vocabulary size");
    }
    let final_log_probs = generation_log_softmax(final_logits)?;
    let premature_log_probs = generation_log_softmax(premature_logits)?;
    let mut kl_final = 0.0f64;
    let mut kl_premature = 0.0f64;
    for (&final_log_prob, &premature_log_prob) in final_log_probs.iter().zip(&premature_log_probs) {
        let final_probability = if final_log_prob.is_finite() {
            f64::from(final_log_prob).exp()
        } else {
            0.0
        };
        let premature_probability = if premature_log_prob.is_finite() {
            f64::from(premature_log_prob).exp()
        } else {
            0.0
        };
        let average_probability = 0.5 * (final_probability + premature_probability);
        if average_probability == 0.0 {
            continue;
        }
        let average_log_probability = average_probability.ln();
        if final_probability == 0.0 || premature_probability == 0.0 {
            return Ok(f64::INFINITY);
        }
        // Match torch.nn.functional.kl_div(log_softmax_distribution,
        // avg_dist, reduction="none").mean(-1) from the community generator.
        kl_final += average_probability * (average_log_probability - f64::from(final_log_prob));
        kl_premature +=
            average_probability * (average_log_probability - f64::from(premature_log_prob));
    }
    let vocabulary_size = final_logits.len() as f64;
    Ok(0.5 * (kl_final + kl_premature) / vocabulary_size)
}

fn generation_dola_select_contrast(
    candidate_premature_logits: &[(usize, Vec<f32>)],
    final_logits: &[f32],
) -> Result<Vec<f32>> {
    let (_, baseline_logits) = match candidate_premature_logits {
        [] => bail!("DoLa generation requires at least one premature layer"),
        [candidate] => candidate,
        candidates => {
            let mut best = &candidates[0];
            let mut best_divergence = generation_dola_js_divergence(final_logits, &best.1)?;
            for candidate in &candidates[1..] {
                let divergence = generation_dola_js_divergence(final_logits, &candidate.1)?;
                if divergence > best_divergence {
                    best = candidate;
                    best_divergence = divergence;
                }
            }
            best
        }
    };
    let (final_scores, baseline_scores) =
        generation_dola_relative_top_filter(final_logits, baseline_logits)?;
    Ok(final_scores
        .into_iter()
        .zip(baseline_scores)
        .map(|(final_score, baseline_score)| final_score - baseline_score)
        .collect())
}

fn generation_bloom_alibi_slope(head: usize, num_heads: usize) -> f32 {
    let mut closest_power = 1usize;
    while closest_power.saturating_mul(2) <= num_heads {
        closest_power *= 2;
    }
    let base = 2.0_f32.powf(-2.0_f32.powf(-((closest_power as f32).log2() - 3.0)));
    if head < closest_power {
        base.powf((head + 1) as f32)
    } else {
        let extra_base = 2.0_f32.powf(-2.0_f32.powf(-(((2 * closest_power) as f32).log2() - 3.0)));
        let extra_head = head - closest_power;
        extra_base.powf((1 + 2 * extra_head) as f32)
    }
}

fn generation_mpt_alibi_slope(head: usize, num_heads: usize, bias_max: f32) -> f32 {
    let mut power = 1usize;
    while power < num_heads {
        power *= 2;
    }
    let slope_index = if power == num_heads {
        head
    } else {
        let odd_count = power / 2;
        if head < odd_count {
            2 * head + 1
        } else {
            2 * (head - odd_count)
        }
    };
    2.0_f32.powf(-bias_max * (slope_index + 1) as f32 / power as f32)
}

fn generation_t5_relative_position_bucket(
    query: usize,
    key: usize,
    mut num_buckets: usize,
    max_distance: usize,
    causal: bool,
) -> usize {
    let relative_position = key as i64 - query as i64;
    let mut bucket = 0usize;
    let distance = if !causal {
        let half_buckets = num_buckets / 2;
        if relative_position > 0 {
            bucket += half_buckets;
        }
        num_buckets = half_buckets;
        relative_position.unsigned_abs() as usize
    } else {
        (-relative_position).max(0) as usize
    };
    let max_exact = num_buckets / 2;
    if distance < max_exact {
        return bucket + distance;
    }
    let log_scale = ((distance as f32) / max_exact as f32).ln()
        / ((max_distance as f32) / max_exact as f32).ln();
    let large_bucket = max_exact + (log_scale * (num_buckets - max_exact) as f32) as usize;
    bucket + large_bucket.min(num_buckets - 1)
}

#[allow(clippy::too_many_arguments)]
fn generation_attention_probabilities_from_qk(
    q_values: &[f32],
    k_values: &[f32],
    total_query_rows: usize,
    first_output_query: usize,
    key_rows: usize,
    num_heads: usize,
    num_key_value_heads: usize,
    head_dim: usize,
    scale: f32,
    softcap: f32,
    causal: bool,
    window_size: usize,
    alibi_mode: u32,
    alibi_bias_max: f32,
    relative_bias: Option<&[f32]>,
    relative_bias_num_buckets: usize,
    relative_bias_max_distance: usize,
    sink_values: Option<&[f32]>,
    key_mask: &[f32],
) -> Result<VulkanTransformerGenerationAttention> {
    if total_query_rows == 0 || first_output_query >= total_query_rows {
        bail!("generation attention query geometry is invalid");
    }
    if key_rows == 0 || key_mask.len() < key_rows {
        bail!("generation attention key geometry is invalid");
    }
    if num_heads == 0
        || num_key_value_heads == 0
        || !num_heads.is_multiple_of(num_key_value_heads)
        || head_dim == 0
    {
        bail!("generation attention head geometry is invalid");
    }
    let query_hidden = num_heads * head_dim;
    let key_hidden = num_key_value_heads * head_dim;
    if q_values.len() < total_query_rows * query_hidden || k_values.len() < key_rows * key_hidden {
        bail!("generation attention Q/K buffers are smaller than the active tensor geometry");
    }
    if let Some(relative_bias) = relative_bias {
        let expected = relative_bias_num_buckets
            .checked_mul(num_heads)
            .context("generation relative-attention bias geometry overflow")?;
        if relative_bias.len() < expected || relative_bias_num_buckets < 2 {
            bail!("generation relative-attention bias tensor has invalid geometry");
        }
    }
    if sink_values.is_some_and(|sink| sink.len() < num_heads) {
        bail!("generation attention sink tensor has invalid geometry");
    }

    let output_query_rows = total_query_rows - first_output_query;
    let mut values = vec![0.0f32; num_heads * output_query_rows * key_rows];
    let queries_per_kv = num_heads / num_key_value_heads;

    for head in 0..num_heads {
        let kv_head = head / queries_per_kv;
        let bloom_slope =
            matches!(alibi_mode, 1 | 3).then(|| generation_bloom_alibi_slope(head, num_heads));
        let mpt_slope =
            (alibi_mode == 2).then(|| generation_mpt_alibi_slope(head, num_heads, alibi_bias_max));
        for output_query in 0..output_query_rows {
            let query = first_output_query + output_query;
            let mut first_key = 0usize;
            let mut last_key = if causal {
                query.min(key_rows - 1)
            } else {
                key_rows - 1
            };
            if window_size != 0 {
                if causal {
                    first_key = (query + 1).saturating_sub(window_size);
                } else {
                    first_key = query.saturating_sub(window_size);
                    last_key = query.saturating_add(window_size).min(key_rows - 1);
                }
            }

            let score_for_key = |key: usize| {
                let q_base = query * query_hidden + head * head_dim;
                let k_base = key * key_hidden + kv_head * head_dim;
                let mut score = 0.0f32;
                for dim in 0..head_dim {
                    score = q_values[q_base + dim].mul_add(k_values[k_base + dim], score);
                }
                score *= scale;
                if let Some(slope) = bloom_slope {
                    score += slope * key as f32 * if alibi_mode == 3 { scale } else { 1.0 };
                } else if let Some(slope) = mpt_slope {
                    score += slope * key as f32;
                }
                if let Some(relative_bias) = relative_bias {
                    let bucket = generation_t5_relative_position_bucket(
                        query,
                        key,
                        relative_bias_num_buckets,
                        relative_bias_max_distance,
                        causal,
                    );
                    score += relative_bias[bucket * num_heads + head];
                }
                if softcap > 0.0 {
                    score = softcap * (score / softcap).tanh();
                }
                score
            };

            let mut max_score = f32::NEG_INFINITY;
            let mut found = false;
            for key in first_key..=last_key {
                if key_mask[key] <= 0.0 {
                    continue;
                }
                let score = score_for_key(key);
                max_score = if found { max_score.max(score) } else { score };
                found = true;
            }
            if !found {
                continue;
            }
            if let Some(sink) = sink_values {
                max_score = max_score.max(sink[head]);
            }
            let mut denominator = sink_values
                .map(|sink| (sink[head] - max_score).exp())
                .unwrap_or(0.0);
            for key in first_key..=last_key {
                if key_mask[key] > 0.0 {
                    denominator += (score_for_key(key) - max_score).exp();
                }
            }
            if !denominator.is_finite() || denominator <= 0.0 {
                bail!("generation attention softmax normalizer is invalid");
            }
            let base = (head * output_query_rows + output_query) * key_rows;
            for key in first_key..=last_key {
                if key_mask[key] > 0.0 {
                    values[base + key] = (score_for_key(key) - max_score).exp() / denominator;
                }
            }
        }
    }

    Ok(VulkanTransformerGenerationAttention {
        query_rows: output_query_rows,
        key_rows,
        num_heads,
        values,
    })
}

fn generation_probabilities(scores: &[f32]) -> Result<Vec<f64>> {
    let max_score = scores
        .iter()
        .copied()
        .filter(|score| score.is_finite())
        .map(f64::from)
        .max_by(f64::total_cmp)
        .context("generation logits contain no finite values")?;
    let mut probabilities = scores
        .iter()
        .map(|&score| {
            if score.is_finite() {
                (f64::from(score) - max_score).exp()
            } else {
                0.0
            }
        })
        .collect::<Vec<_>>();
    let total = probabilities.iter().sum::<f64>();
    if !total.is_finite() || total <= 0.0 {
        bail!("generation sampling softmax normalizer is invalid");
    }
    for probability in &mut probabilities {
        *probability /= total;
    }
    Ok(probabilities)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum VulkanTransformerWatermarkSeedingScheme {
    LeftHash,
    SelfHash,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct VulkanTransformerWatermarkConfig {
    greenlist_ratio: f64,
    bias: f32,
    hashing_key: i128,
    seeding_scheme: VulkanTransformerWatermarkSeedingScheme,
    context_width: usize,
}

impl VulkanTransformerWatermarkConfig {
    fn from_value(value: &serde_json::Value) -> Result<Self> {
        let object = value
            .as_object()
            .context("generation watermarking_config must be an object")?;
        let greenlist_ratio = object
            .get("greenlist_ratio")
            .map(|value| {
                value
                    .as_f64()
                    .context("generation watermarking_config.greenlist_ratio must be numeric")
            })
            .transpose()?
            .unwrap_or(0.25);
        if !greenlist_ratio.is_finite() || !(0.0..1.0).contains(&greenlist_ratio) {
            bail!(
                "generation watermarking_config.greenlist_ratio must be finite and in the open interval (0, 1)"
            );
        }
        let bias = object
            .get("bias")
            .map(|value| {
                value
                    .as_f64()
                    .context("generation watermarking_config.bias must be numeric")
                    .and_then(|value| {
                        let value = value as f32;
                        if value.is_finite() {
                            Ok(value)
                        } else {
                            bail!("generation watermarking_config.bias must be finite")
                        }
                    })
            })
            .transpose()?
            .unwrap_or(2.0);
        let hashing_key = match object.get("hashing_key") {
            Some(serde_json::Value::Number(number)) => {
                if let Some(value) = number.as_i64() {
                    i128::from(value)
                } else if let Some(value) = number.as_u64() {
                    i128::from(value)
                } else {
                    bail!("generation watermarking_config.hashing_key must be an integer");
                }
            }
            Some(_) => bail!("generation watermarking_config.hashing_key must be an integer"),
            None => 15_485_863,
        };
        if hashing_key < i128::from(i64::MIN) || hashing_key > i128::from(u64::MAX) {
            bail!(
                "generation watermarking_config.hashing_key must fit PyTorch manual_seed's [-2^63, 2^64-1] range"
            );
        }
        let seeding_scheme = match object
            .get("seeding_scheme")
            .map(|value| {
                value
                    .as_str()
                    .context("generation watermarking_config.seeding_scheme must be a string")
            })
            .transpose()?
            .unwrap_or("lefthash")
        {
            "lefthash" => VulkanTransformerWatermarkSeedingScheme::LeftHash,
            "selfhash" => VulkanTransformerWatermarkSeedingScheme::SelfHash,
            other => bail!(
                "generation watermarking_config.seeding_scheme must be lefthash or selfhash, got {other:?}"
            ),
        };
        if matches!(
            seeding_scheme,
            VulkanTransformerWatermarkSeedingScheme::SelfHash
        ) && hashing_key > i128::from(i64::MAX)
        {
            // In Transformers the self-hash expression is evaluated in a
            // torch.int64 tensor. Python integers above i64::MAX therefore
            // cannot be represented by that processor either.
            bail!("generation selfhash watermarking_config.hashing_key exceeds torch.int64");
        }
        let context_width = object
            .get("context_width")
            .map(|value| {
                value
                    .as_u64()
                    .context(
                        "generation watermarking_config.context_width must be a positive integer",
                    )
                    .and_then(|value| {
                        usize::try_from(value)
                            .context("generation watermarking_config.context_width exceeds usize")
                    })
            })
            .transpose()?
            .unwrap_or(1);
        if context_width == 0 {
            bail!("generation watermarking_config.context_width must be positive");
        }
        Ok(Self {
            greenlist_ratio,
            bias,
            hashing_key,
            seeding_scheme,
            context_width,
        })
    }
}

#[derive(Clone, Debug, PartialEq)]
struct VulkanTransformerSynthIdWatermarkConfig {
    ngram_len: usize,
    keys: Vec<i64>,
    sampling_table_size: usize,
    sampling_table_seed: i128,
    context_history_size: usize,
    skip_first_ngram_calls: bool,
    debug_mode: bool,
}

impl VulkanTransformerSynthIdWatermarkConfig {
    fn from_value(value: &serde_json::Value) -> Result<Self> {
        let object = value
            .as_object()
            .context("generation SynthIDTextWatermarkingConfig must be an object")?;
        let ngram_len = object
            .get("ngram_len")
            .and_then(serde_json::Value::as_u64)
            .context("generation SynthID watermarking_config.ngram_len must be a positive integer")?
            .try_into()
            .context("generation SynthID watermarking_config.ngram_len exceeds usize")?;
        if ngram_len == 0 {
            bail!("generation SynthID watermarking_config.ngram_len must be positive");
        }
        let keys = object
            .get("keys")
            .and_then(serde_json::Value::as_array)
            .context("generation SynthID watermarking_config.keys must be an integer list")?
            .iter()
            .map(|value| {
                value.as_i64().context(
                    "generation SynthID watermarking_config.keys entries must fit torch.int64",
                )
            })
            .collect::<Result<Vec<_>>>()?;
        if keys.is_empty() {
            bail!("generation SynthID watermarking_config.keys must not be empty");
        }
        let sampling_table_size = object
            .get("sampling_table_size")
            .map(|value| {
                value
                    .as_u64()
                    .context("generation SynthID watermarking_config.sampling_table_size must be an integer")
                    .and_then(|value| {
                        usize::try_from(value)
                            .context("generation SynthID watermarking_config.sampling_table_size exceeds usize")
                    })
            })
            .transpose()?
            .unwrap_or(1 << 16);
        if sampling_table_size == 0 || sampling_table_size > (1 << 24) {
            bail!(
                "generation SynthID watermarking_config.sampling_table_size must be in 1..=2**24"
            );
        }
        let sampling_table_seed = match object.get("sampling_table_seed") {
            Some(serde_json::Value::Number(number)) => {
                if let Some(value) = number.as_i64() {
                    i128::from(value)
                } else if let Some(value) = number.as_u64() {
                    i128::from(value)
                } else {
                    bail!("generation SynthID watermarking_config.sampling_table_seed must be an integer");
                }
            }
            Some(_) => bail!(
                "generation SynthID watermarking_config.sampling_table_seed must be an integer"
            ),
            None => 0,
        };
        generation_pytorch_manual_seed(sampling_table_seed)?;
        let context_history_size = object
            .get("context_history_size")
            .map(|value| {
                value
                    .as_u64()
                    .context("generation SynthID watermarking_config.context_history_size must be a non-negative integer")
                    .and_then(|value| {
                        usize::try_from(value)
                            .context("generation SynthID watermarking_config.context_history_size exceeds usize")
                    })
            })
            .transpose()?
            .unwrap_or(1024);
        let skip_first_ngram_calls = object
            .get("skip_first_ngram_calls")
            .map(|value| {
                value.as_bool().context(
                    "generation SynthID watermarking_config.skip_first_ngram_calls must be boolean",
                )
            })
            .transpose()?
            .unwrap_or(false);
        let debug_mode = object
            .get("debug_mode")
            .map(|value| {
                value
                    .as_bool()
                    .context("generation SynthID watermarking_config.debug_mode must be boolean")
            })
            .transpose()?
            .unwrap_or(false);
        Ok(Self {
            ngram_len,
            keys,
            sampling_table_size,
            sampling_table_seed,
            context_history_size,
            skip_first_ngram_calls,
            debug_mode,
        })
    }
}

#[derive(Clone, Debug, PartialEq)]
enum VulkanTransformerParsedWatermarkConfig {
    Classic(VulkanTransformerWatermarkConfig),
    SynthId(VulkanTransformerSynthIdWatermarkConfig),
}

fn generation_parse_watermarking_config(
    value: &serde_json::Value,
) -> Result<VulkanTransformerParsedWatermarkConfig> {
    let object = value
        .as_object()
        .context("generation watermarking_config must be an object")?;
    if object.contains_key("ngram_len") || object.contains_key("keys") {
        Ok(VulkanTransformerParsedWatermarkConfig::SynthId(
            VulkanTransformerSynthIdWatermarkConfig::from_value(value)?,
        ))
    } else {
        Ok(VulkanTransformerParsedWatermarkConfig::Classic(
            VulkanTransformerWatermarkConfig::from_value(value)?,
        ))
    }
}

/// Minimal copy of PyTorch's CPU MT19937 engine. Watermarking must use this
/// stream instead of Hierarchos' Philox stream because Transformers constructs
/// `WatermarkLogitsProcessor` with a CPU `torch.Generator` and then calls
/// `torch.randperm`. Keeping the engine local avoids a libtorch dependency while
/// preserving detector-compatible greenlists.
struct VulkanTorchMt19937 {
    state: [u32; 624],
    left: usize,
    next: usize,
}

impl VulkanTorchMt19937 {
    fn new(seed: u64) -> Self {
        let mut state = [0u32; 624];
        state[0] = seed as u32;
        for index in 1..624 {
            state[index] = 1_812_433_253u32
                .wrapping_mul(state[index - 1] ^ (state[index - 1] >> 30))
                .wrapping_add(index as u32);
        }
        Self {
            state,
            left: 1,
            next: 0,
        }
    }

    fn next_state(&mut self) {
        const MATRIX_A: u32 = 0x9908_b0df;
        const UPPER_MASK: u32 = 0x8000_0000;
        const LOWER_MASK: u32 = 0x7fff_ffff;
        for index in 0..624 {
            let mixed =
                (self.state[index] & UPPER_MASK) | (self.state[(index + 1) % 624] & LOWER_MASK);
            let twisted = (mixed >> 1) ^ if mixed & 1 != 0 { MATRIX_A } else { 0 };
            self.state[index] = self.state[(index + 397) % 624] ^ twisted;
        }
        self.left = 624;
        self.next = 0;
    }

    fn random_u32(&mut self) -> u32 {
        self.left -= 1;
        if self.left == 0 {
            self.next_state();
        }
        let mut value = self.state[self.next];
        self.next += 1;
        value ^= value >> 11;
        value ^= (value << 7) & 0x9d2c_5680;
        value ^= (value << 15) & 0xefc6_0000;
        value ^= value >> 18;
        value
    }
}

fn generation_torch_cpu_randperm(n: usize, seed: u64) -> Result<Vec<u32>> {
    // PyTorch uses this exact 32-bit Fisher-Yates path while
    // n < UINT32_MAX / 20. Every practical Transformer vocabulary and the
    // watermark fixed table are far below that threshold.
    if n >= (u32::MAX as usize) / 20 {
        bail!("watermark randperm length {n} exceeds PyTorch's 32-bit CPU Fisher-Yates path");
    }
    let mut permutation = (0..n)
        .map(|index| u32::try_from(index).context("watermark permutation index exceeds u32"))
        .collect::<Result<Vec<_>>>()?;
    if n < 2 {
        return Ok(permutation);
    }
    let mut rng = VulkanTorchMt19937::new(seed);
    for index in 0..n - 1 {
        let remaining = n - index;
        let offset = (rng.random_u32() as usize) % remaining;
        permutation.swap(index, index + offset);
    }
    Ok(permutation)
}

fn generation_pytorch_manual_seed(hashing_key: i128) -> Result<u64> {
    if hashing_key < i128::from(i64::MIN) || hashing_key > i128::from(u64::MAX) {
        bail!("watermark hashing_key is outside PyTorch manual_seed range");
    }
    if hashing_key < 0 {
        Ok(((1_i128 << 64) + hashing_key) as u64)
    } else {
        Ok(hashing_key as u64)
    }
}

fn generation_watermark_mod_seed(seed: i128) -> u64 {
    // WatermarkLogitsProcessor applies `% (2**64 - 1)` immediately before
    // `manual_seed`. rem_euclid reproduces Python's positive modulo for
    // negative self-hash values.
    seed.rem_euclid(i128::from(u64::MAX)) as u64
}

fn generation_watermark_fixed_table(hashing_key: i128) -> Result<Arc<Vec<u32>>> {
    type FixedTableCache = Option<(i128, Arc<Vec<u32>>)>;
    static CACHE: OnceLock<Mutex<FixedTableCache>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(None));
    {
        let guard = cache
            .lock()
            .map_err(|_| anyhow!("watermark fixed-table cache lock is poisoned"))?;
        if let Some((cached_key, table)) = guard.as_ref() {
            if *cached_key == hashing_key {
                return Ok(Arc::clone(table));
            }
        }
    }
    let seed = generation_pytorch_manual_seed(hashing_key)?;
    let table = Arc::new(generation_torch_cpu_randperm(1_000_003, seed)?);
    let mut guard = cache
        .lock()
        .map_err(|_| anyhow!("watermark fixed-table cache lock is poisoned"))?;
    *guard = Some((hashing_key, Arc::clone(&table)));
    Ok(table)
}

fn generation_synthid_sampling_table(
    config: &VulkanTransformerSynthIdWatermarkConfig,
) -> Result<Arc<Vec<u8>>> {
    type SamplingTableCache = Option<(i128, usize, Arc<Vec<u8>>)>;
    static CACHE: OnceLock<Mutex<SamplingTableCache>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(None));
    {
        let guard = cache
            .lock()
            .map_err(|_| anyhow!("SynthID sampling-table cache lock is poisoned"))?;
        if let Some((seed, size, table)) = guard.as_ref() {
            if *seed == config.sampling_table_seed && *size == config.sampling_table_size {
                return Ok(Arc::clone(table));
            }
        }
    }
    let seed = generation_pytorch_manual_seed(config.sampling_table_seed)?;
    let mut rng = VulkanTorchMt19937::new(seed);
    let table = Arc::new(
        (0..config.sampling_table_size)
            .map(|_| (rng.random_u32() % 2) as u8)
            .collect::<Vec<_>>(),
    );
    let mut guard = cache
        .lock()
        .map_err(|_| anyhow!("SynthID sampling-table cache lock is poisoned"))?;
    *guard = Some((
        config.sampling_table_seed,
        config.sampling_table_size,
        Arc::clone(&table),
    ));
    Ok(table)
}

fn generation_synthid_accumulate_hash(mut hash: i64, data: impl IntoIterator<Item = i64>) -> i64 {
    const MULTIPLIER: i64 = 6_364_136_223_846_793_005;
    for value in data {
        hash = hash
            .wrapping_add(value)
            .wrapping_mul(MULTIPLIER)
            .wrapping_add(1);
    }
    hash
}

fn generation_synthid_context(
    history: &[u32],
    prompt_len: usize,
    generation_step: usize,
    ngram_len: usize,
) -> Result<Vec<i64>> {
    let context_len = ngram_len.saturating_sub(1);
    if context_len == 0 {
        return Ok(Vec::new());
    }
    let sequence_len = prompt_len
        .checked_add(generation_step)
        .context("SynthID generation sequence length overflow")?;
    if sequence_len > history.len() {
        bail!("SynthID generation step exceeds available history");
    }
    let used = generation_step.min(context_len);
    let mut context = vec![0_i64; context_len - used];
    context.extend(
        history[sequence_len - used..sequence_len]
            .iter()
            .map(|token| i64::from(*token)),
    );
    Ok(context)
}

fn generation_synthid_context_hash(context: &[i64]) -> i64 {
    generation_synthid_accumulate_hash(1, context.iter().copied())
}

fn generation_synthid_context_was_repeated(
    history: &[u32],
    step: usize,
    config: &VulkanTransformerSynthIdWatermarkConfig,
    current_hash: i64,
) -> Result<bool> {
    if config.context_history_size == 0 {
        return Ok(false);
    }
    let prompt_len = history
        .len()
        .checked_sub(step)
        .context("SynthID generation step exceeds sequence history")?;
    let mut stored_hashes = Vec::new();
    for prior_step in 0..step {
        if config.skip_first_ngram_calls && prior_step + 1 < config.ngram_len {
            continue;
        }
        let context =
            generation_synthid_context(history, prompt_len, prior_step, config.ngram_len)?;
        stored_hashes.push(generation_synthid_context_hash(&context));
    }
    if stored_hashes
        .iter()
        .rev()
        .take(config.context_history_size)
        .any(|hash| *hash == current_hash)
    {
        return Ok(true);
    }
    // SynthIDTextWatermarkState initializes unused history slots to zero.
    Ok(stored_hashes.len() < config.context_history_size && current_hash == 0)
}

fn generation_apply_synthid_watermarking(
    scores: &mut [f32],
    history: &[u32],
    step: usize,
    config: &VulkanTransformerSynthIdWatermarkConfig,
) -> Result<()> {
    if config.debug_mode {
        scores.fill(1.0);
    }
    let call_number = step.saturating_add(1);
    if config.skip_first_ngram_calls && call_number < config.ngram_len {
        return Ok(());
    }
    if scores.is_empty() {
        return Ok(());
    }
    let prompt_len = history
        .len()
        .checked_sub(step)
        .context("SynthID generation step exceeds sequence history")?;
    let context = generation_synthid_context(history, prompt_len, step, config.ngram_len)?;
    let context_hash = generation_synthid_context_hash(&context);
    if generation_synthid_context_was_repeated(history, step, config, context_hash)? {
        return Ok(());
    }

    let sampling_table = generation_synthid_sampling_table(config)?;
    let max_score = scores
        .iter()
        .copied()
        .filter(|score| score.is_finite())
        .max_by(f32::total_cmp)
        .context("SynthID watermarking scores contain no finite values")?;
    let mut probabilities = scores
        .iter()
        .map(|score| {
            if score.is_finite() {
                (*score - max_score).exp()
            } else {
                0.0
            }
        })
        .collect::<Vec<_>>();
    let normalizer = probabilities.iter().copied().sum::<f32>();
    if !normalizer.is_finite() || normalizer <= 0.0 {
        bail!("SynthID watermarking softmax normalizer is invalid");
    }
    for probability in &mut probabilities {
        *probability /= normalizer;
    }

    let token_hashes = (0..scores.len())
        .map(|token| {
            generation_synthid_accumulate_hash(context_hash, std::iter::once(token as i64))
        })
        .collect::<Vec<_>>();
    for &key in &config.keys {
        let mut g_values = vec![0_u8; scores.len()];
        let mut g_mass = 0.0_f32;
        for (token, token_hash) in token_hashes.iter().copied().enumerate() {
            let ngram_key = generation_synthid_accumulate_hash(token_hash, std::iter::once(key));
            let table_index = ngram_key.rem_euclid(config.sampling_table_size as i64) as usize;
            let g_value = sampling_table[table_index];
            g_values[token] = g_value;
            if g_value != 0 {
                g_mass += probabilities[token];
            }
        }
        for (token, probability) in probabilities.iter_mut().enumerate() {
            *probability *= 1.0 + f32::from(g_values[token]) - g_mass;
        }
    }
    for (score, probability) in scores.iter_mut().zip(probabilities) {
        let value = probability.ln();
        *score = if value.is_finite() { value } else { f32::MIN };
    }
    Ok(())
}

fn generation_watermark_seed(
    history: &[u32],
    config: VulkanTransformerWatermarkConfig,
    fixed_table: Option<&[u32]>,
) -> Result<u64> {
    if history.len() < config.context_width {
        bail!("watermark seed requires at least context_width history tokens");
    }
    let context = &history[history.len() - config.context_width..];
    match config.seeding_scheme {
        VulkanTransformerWatermarkSeedingScheme::LeftHash => Ok(generation_watermark_mod_seed(
            config.hashing_key * i128::from(*context.last().unwrap()),
        )),
        VulkanTransformerWatermarkSeedingScheme::SelfHash => {
            let table =
                fixed_table.context("selfhash watermarking requires the PyTorch fixed table")?;
            let hashing_key = i64::try_from(config.hashing_key)
                .context("selfhash watermarking hashing_key exceeds torch.int64")?;
            let last = *context.last().unwrap() as usize % table.len();
            let b = i64::from(table[last]) + 1;
            let mut minimum = i64::MAX;
            for &token in context {
                let index = token as usize % table.len();
                let a = i64::from(table[index]) + 1;
                let value = hashing_key.wrapping_mul(a).wrapping_mul(b);
                minimum = minimum.min(value);
            }
            Ok(generation_watermark_mod_seed(i128::from(minimum)))
        }
    }
}

fn generation_apply_watermarking(
    scores: &mut [f32],
    history: &[u32],
    step: usize,
    generation_config: &VulkanTransformerGenerationConfig,
) -> Result<()> {
    let Some(raw_config) = generation_config.watermarking_config.as_ref() else {
        return Ok(());
    };
    let parsed = generation_parse_watermarking_config(raw_config)?;
    let VulkanTransformerParsedWatermarkConfig::Classic(config) = parsed else {
        if let VulkanTransformerParsedWatermarkConfig::SynthId(config) = parsed {
            return generation_apply_synthid_watermarking(scores, history, step, &config);
        }
        unreachable!();
    };
    if history.len() < config.context_width || scores.is_empty() {
        return Ok(());
    }
    let greenlist_size = ((scores.len() as f64) * config.greenlist_ratio) as usize;
    if greenlist_size == 0 {
        return Ok(());
    }

    match config.seeding_scheme {
        VulkanTransformerWatermarkSeedingScheme::LeftHash => {
            let seed = generation_watermark_seed(history, config, None)?;
            let permutation = generation_torch_cpu_randperm(scores.len(), seed)?;
            for &token in permutation.iter().take(greenlist_size) {
                scores[token as usize] += config.bias;
            }
        }
        VulkanTransformerWatermarkSeedingScheme::SelfHash => {
            let fixed_table = generation_watermark_fixed_table(config.hashing_key)?;
            let ranked = generation_ranked_finite_logits(scores);
            // Transformers checks the 40 highest-scoring candidate tokens. Its
            // Python implementation assumes vocab_size >= 40; min() is the
            // bounds-safe equivalent for synthetic/tiny test vocabularies.
            for &(token, _) in ranked.iter().take(40) {
                let token =
                    u32::try_from(token).context("watermark candidate token exceeds u32")?;
                let mut candidate_history = history.to_vec();
                candidate_history.push(token);
                let seed = generation_watermark_seed(
                    &candidate_history,
                    config,
                    Some(fixed_table.as_slice()),
                )?;
                let permutation = generation_torch_cpu_randperm(scores.len(), seed)?;
                if permutation
                    .iter()
                    .take(greenlist_size)
                    .any(|green_token| *green_token == token)
                {
                    scores[token as usize] += config.bias;
                }
            }
        }
    }
    Ok(())
}

fn generation_apply_sampling_warpers(
    scores: &mut [f32],
    config: &VulkanTransformerGenerationConfig,
    min_tokens_to_keep: usize,
) -> Result<()> {
    for score in scores.iter_mut().filter(|score| score.is_finite()) {
        *score /= config.temperature;
    }
    let mut ranked = generation_ranked_finite_logits(scores);
    if ranked.is_empty() {
        bail!("generation logits contain no finite values after sampling processors");
    }

    if let Some(top_h) = config.top_h {
        let top_n = ranked.len().min(100);
        let top = &ranked[..top_n];
        let max_score = f64::from(top[0].1);
        let mut probabilities = top
            .iter()
            .map(|(_, score)| (f64::from(*score) - max_score).exp())
            .collect::<Vec<_>>();
        let total = probabilities.iter().sum::<f64>();
        if !total.is_finite() || total <= 0.0 {
            bail!("generation Top-H softmax normalizer is invalid");
        }
        for probability in &mut probabilities {
            *probability /= total;
        }
        let entropy = probabilities
            .iter()
            .filter(|probability| **probability > 0.0)
            .map(|probability| -*probability * probability.ln())
            .sum::<f64>();
        let tau = entropy * f64::from(top_h);
        let mut cumulative_entropy = 0.0f64;
        let mut keep = BTreeSet::new();
        for (rank, ((token, _), probability)) in top.iter().zip(&probabilities).enumerate() {
            if *probability > 0.0 {
                cumulative_entropy += -*probability * probability.ln();
            }
            if rank == 0 || cumulative_entropy <= tau {
                keep.insert(*token);
            }
        }
        for (token, score) in scores.iter_mut().enumerate() {
            if !keep.contains(&token) {
                *score = f32::NEG_INFINITY;
            }
        }
        ranked = generation_ranked_finite_logits(scores);
    }

    if config.top_k > 0 {
        let keep = config.top_k.max(min_tokens_to_keep).min(ranked.len());
        // Match HF TopKLogitsWarper exactly: filtering is score-threshold
        // based, not rank-count based. This matters for ties (including the
        // all-ones synthetic logits used by prompt-lookup candidate checks),
        // where every token tied with the kth score must remain selectable.
        let threshold = ranked[keep - 1].1;
        for score in scores.iter_mut() {
            if score.is_finite() && *score < threshold {
                *score = f32::NEG_INFINITY;
            }
        }
        ranked = generation_ranked_finite_logits(scores);
    }

    if config.top_p < 1.0 && ranked.len() > min_tokens_to_keep {
        // HF TopPLogitsWarper sorts from least to most likely and removes the
        // low-probability prefix while its cumulative mass is <= 1-top_p.
        // Reproduce that formulation directly so boundary and tie behavior
        // stays aligned with the local Transformers checkout.
        let mut ascending = ranked.clone();
        ascending.sort_by(|(left_token, left), (right_token, right)| {
            left.total_cmp(right)
                .then_with(|| left_token.cmp(right_token))
        });
        let max_score = ascending
            .iter()
            .map(|(_, value)| f64::from(*value))
            .max_by(f64::total_cmp)
            .context("generation top_p logits contain no finite values")?;
        let weights = ascending
            .iter()
            .map(|(_, value)| (f64::from(*value) - max_score).exp())
            .collect::<Vec<_>>();
        let total = weights.iter().sum::<f64>();
        if !total.is_finite() || total <= 0.0 {
            bail!("generation sampling softmax normalizer is invalid");
        }
        let mut cumulative = 0.0f64;
        let protected_start = ascending.len().saturating_sub(min_tokens_to_keep);
        for (rank, ((token, _), weight)) in ascending.iter().zip(weights.iter()).enumerate() {
            cumulative += *weight / total;
            if rank < protected_start && cumulative <= 1.0 - f64::from(config.top_p) {
                scores[*token] = f32::NEG_INFINITY;
            }
        }
        ranked = generation_ranked_finite_logits(scores);
    }

    if let Some(min_p) = config.min_p.filter(|min_p| *min_p > 0.0) {
        let probabilities = generation_probabilities(scores)?;
        let top_probability = probabilities.iter().copied().fold(0.0f64, f64::max);
        let threshold = f64::from(min_p) * top_probability;
        let protected = ranked
            .iter()
            .take(min_tokens_to_keep.min(ranked.len()))
            .map(|(token, _)| *token)
            .collect::<BTreeSet<_>>();
        for (token, score) in scores.iter_mut().enumerate() {
            if score.is_finite() && probabilities[token] < threshold && !protected.contains(&token)
            {
                *score = f32::NEG_INFINITY;
            }
        }
        ranked = generation_ranked_finite_logits(scores);
    }

    if let Some(typical_p) = config.typical_p.filter(|typical_p| *typical_p < 1.0) {
        let log_probs = generation_log_softmax(scores)?;
        let probabilities = log_probs
            .iter()
            .map(|&log_probability| {
                if log_probability.is_finite() {
                    f64::from(log_probability).exp()
                } else {
                    0.0
                }
            })
            .collect::<Vec<_>>();
        let entropy = log_probs
            .iter()
            .zip(&probabilities)
            .filter(|(log_probability, probability)| {
                log_probability.is_finite() && **probability > 0.0
            })
            .map(|(log_probability, probability)| -f64::from(*log_probability) * *probability)
            .sum::<f64>();
        let mut typical_ranked = log_probs
            .iter()
            .copied()
            .enumerate()
            .filter(|(_, log_probability)| log_probability.is_finite())
            .map(|(token, log_probability)| (token, (-f64::from(log_probability) - entropy).abs()))
            .collect::<Vec<_>>();
        typical_ranked.sort_by(|(left_token, left), (right_token, right)| {
            left.total_cmp(right)
                .then_with(|| left_token.cmp(right_token))
        });
        let total = typical_ranked
            .iter()
            .map(|(token, _)| probabilities[*token])
            .sum::<f64>();
        let mut cumulative = 0.0f64;
        let mut last_index = typical_ranked.len().saturating_sub(1);
        for (index, (token, _)) in typical_ranked.iter().enumerate() {
            cumulative += probabilities[*token] / total;
            if cumulative >= f64::from(typical_p) {
                last_index = index;
                break;
            }
        }
        let threshold = typical_ranked[last_index].1;
        let protected = typical_ranked
            .iter()
            .take(min_tokens_to_keep.min(typical_ranked.len()))
            .map(|(token, _)| *token)
            .collect::<BTreeSet<_>>();
        for (token, shifted) in typical_ranked {
            if shifted > threshold && !protected.contains(&token) {
                scores[token] = f32::NEG_INFINITY;
            }
        }
        ranked = generation_ranked_finite_logits(scores);
    }

    if let Some(epsilon) = config.epsilon_cutoff {
        let probabilities = generation_probabilities(scores)?;
        let protected = ranked
            .iter()
            .take(min_tokens_to_keep.min(ranked.len()))
            .map(|(token, _)| *token)
            .collect::<BTreeSet<_>>();
        for (token, score) in scores.iter_mut().enumerate() {
            if score.is_finite()
                && probabilities[token] < f64::from(epsilon)
                && !protected.contains(&token)
            {
                *score = f32::NEG_INFINITY;
            }
        }
        ranked = generation_ranked_finite_logits(scores);
    }

    if let Some(epsilon) = config.eta_cutoff {
        let probabilities = generation_probabilities(scores)?;
        let entropy = probabilities
            .iter()
            .filter(|probability| **probability > 0.0)
            .map(|probability| -*probability * probability.ln())
            .sum::<f64>();
        let epsilon = f64::from(epsilon);
        let eta = epsilon.min(epsilon.sqrt() * (-entropy).exp());
        let protected = ranked
            .iter()
            .take(min_tokens_to_keep.min(ranked.len()))
            .map(|(token, _)| *token)
            .collect::<BTreeSet<_>>();
        for (token, score) in scores.iter_mut().enumerate() {
            if score.is_finite() && probabilities[token] < eta && !protected.contains(&token) {
                *score = f32::NEG_INFINITY;
            }
        }
    }
    Ok(())
}

fn generation_sample_token(
    logits: &[f32],
    config: &VulkanTransformerGenerationConfig,
    sample_index: u64,
) -> Result<u32> {
    let mut scores = logits.to_vec();
    generation_apply_sampling_warpers(&mut scores, config, 1)?;
    generation_sample_processed_scores(&scores, config.seed, sample_index)
}

fn generation_sample_processed_scores(scores: &[f32], seed: u64, sample_index: u64) -> Result<u32> {
    let ranked = generation_ranked_finite_logits(scores);
    if ranked.is_empty() {
        bail!("generation logits contain no finite values");
    }
    let max_logit = f64::from(ranked[0].1);
    let weights = ranked
        .iter()
        .map(|(_, value)| (f64::from(*value) - max_logit).exp())
        .collect::<Vec<_>>();
    let total = weights.iter().sum::<f64>();
    if !total.is_finite() || total <= 0.0 {
        bail!("generation sampling softmax normalizer is invalid");
    }
    let random_word = hierarchos_canonical_philox_word(seed, sample_index);
    let unit = (f64::from(random_word) + 0.5) / 4_294_967_296.0;
    let target = unit * total;
    let mut cumulative = 0.0f64;
    for ((token, _), weight) in ranked.iter().zip(weights.iter()) {
        cumulative += *weight;
        if target < cumulative {
            return u32::try_from(*token).context("generation token index exceeds u32");
        }
    }
    u32::try_from(ranked.last().unwrap().0).context("generation token index exceeds u32")
}

fn generation_uniform_unit(seed: u64, sample_index: u64) -> f64 {
    let random_word = hierarchos_canonical_philox_word(seed, sample_index);
    (f64::from(random_word) + 0.5) / 4_294_967_296.0
}

fn generation_sample_probabilities(
    probabilities: &[f64],
    seed: u64,
    sample_index: u64,
) -> Result<u32> {
    if probabilities.is_empty()
        || probabilities
            .iter()
            .any(|probability| !probability.is_finite() || *probability < 0.0)
    {
        bail!("generation probability vector is invalid");
    }
    let total = probabilities.iter().sum::<f64>();
    if !total.is_finite() || total <= 0.0 {
        bail!("generation probability normalizer is invalid");
    }
    let target = generation_uniform_unit(seed, sample_index) * total;
    let mut cumulative = 0.0f64;
    for (token, probability) in probabilities.iter().enumerate() {
        cumulative += *probability;
        if target < cumulative {
            return u32::try_from(token).context("generation token index exceeds u32");
        }
    }
    u32::try_from(probabilities.len() - 1).context("generation token index exceeds u32")
}

/// Lossless speculative sampling, equivalent to Transformers'
/// `_speculative_sampling` for a batch of one. Candidate and target rows are
/// the processed distributions actually used for decoding.
fn generation_speculative_sample(
    draft: &[u32],
    candidate_scores: &[Vec<f32>],
    target_scores: &[Vec<f32>],
    candidate_is_done: bool,
    assistant_ensemble_weight: Option<f32>,
    seed: u64,
    sample_index: u64,
) -> Result<(Vec<u32>, usize, u64)> {
    if candidate_scores.len() != draft.len() || target_scores.len() != draft.len() + 1 {
        bail!("speculative sampling score geometry does not match candidate length");
    }

    let candidate_probabilities = candidate_scores
        .iter()
        .map(|scores| generation_probabilities(scores))
        .collect::<Result<Vec<_>>>()?;
    let target_probabilities = target_scores
        .iter()
        .map(|scores| generation_probabilities(scores))
        .collect::<Result<Vec<_>>>()?;

    // PyTorch draws one uniform value for every candidate before looking for
    // the first rejection. Consume the same number of deterministic RNG slots
    // even when an earlier candidate already failed.
    let mut first_rejection = None;
    for (index, &token) in draft.iter().enumerate() {
        let token = token as usize;
        let q = candidate_probabilities[index]
            .get(token)
            .copied()
            .context("assistant candidate token is outside its probability vector")?;
        let p = target_probabilities[index]
            .get(token)
            .copied()
            .context("target candidate token is outside its probability vector")?;
        let target_ratio = if q <= f64::MIN_POSITIVE {
            if p > 0.0 {
                f64::INFINITY
            } else {
                0.0
            }
        } else {
            p / q
        };
        let acceptance = if let Some(weight) = assistant_ensemble_weight {
            let weight = f64::from(weight);
            1.0 - weight + weight * target_ratio
        } else {
            target_ratio
        };
        let unit = generation_uniform_unit(seed, sample_index.wrapping_add(index as u64));
        if first_rejection.is_none() && unit > acceptance {
            first_rejection = Some(index);
        }
    }
    let mut next_sample_index = sample_index.wrapping_add(draft.len() as u64);
    let n_matches = first_rejection.unwrap_or(draft.len());

    if n_matches == draft.len() {
        if candidate_is_done && !draft.is_empty() {
            return Ok((draft.to_vec(), draft.len() - 1, next_sample_index));
        }
        let bonus = generation_sample_probabilities(
            &target_probabilities[draft.len()],
            seed,
            next_sample_index,
        )?;
        next_sample_index = next_sample_index.wrapping_add(1);
        let mut valid = draft.to_vec();
        valid.push(bonus);
        return Ok((valid, n_matches, next_sample_index));
    }

    let p = &target_probabilities[n_matches];
    let q = &candidate_probabilities[n_matches];
    let mut residual = p
        .iter()
        .zip(q)
        .map(|(p, q)| (p - q).max(0.0))
        .collect::<Vec<_>>();
    let residual_sum = residual.iter().sum::<f64>();
    if !residual_sum.is_finite() || residual_sum <= f64::MIN_POSITIVE {
        residual.clone_from(p);
    }
    let correction = generation_sample_probabilities(&residual, seed, next_sample_index)?;
    next_sample_index = next_sample_index.wrapping_add(1);
    let mut valid = draft[..n_matches].to_vec();
    valid.push(correction);
    Ok((valid, n_matches, next_sample_index))
}

fn generation_ensemble_argmax(
    target_scores: &[f32],
    candidate_scores: &[f32],
    assistant_ensemble_weight: f32,
) -> Result<u32> {
    if target_scores.len() != candidate_scores.len() || target_scores.is_empty() {
        bail!("assistant ensemble score vectors must be non-empty and have matching widths");
    }
    let target_probabilities = generation_probabilities(target_scores)?;
    let candidate_probabilities = generation_probabilities(candidate_scores)?;
    let target_weight = f64::from(assistant_ensemble_weight);
    let assistant_weight = 1.0 - target_weight;
    let mut best_index = 0usize;
    let mut best_probability = f64::NEG_INFINITY;
    for (index, (&target, &assistant)) in target_probabilities
        .iter()
        .zip(&candidate_probabilities)
        .enumerate()
    {
        let probability = target_weight * target + assistant_weight * assistant;
        if probability > best_probability {
            best_probability = probability;
            best_index = index;
        }
    }
    u32::try_from(best_index).context("assistant ensemble token index exceeds u32")
}

fn generation_processed_non_beam_scores(
    logits: &[f32],
    history: &[u32],
    config: &VulkanTransformerGenerationConfig,
    step: usize,
    is_last_step: bool,
) -> Result<Vec<f32>> {
    generation_processed_non_beam_scores_from_initial_scores(
        logits.to_vec(),
        history,
        config,
        step,
        is_last_step,
    )
}

fn generation_processed_non_beam_scores_from_initial_scores(
    mut scores: Vec<f32>,
    history: &[u32],
    config: &VulkanTransformerGenerationConfig,
    step: usize,
    is_last_step: bool,
) -> Result<Vec<f32>> {
    generation_apply_sequence_bias(&mut scores, history, &config.sequence_bias)?;
    let encoder_input_ids = generation_encoder_input_ids(history, config, step);
    generation_apply_encoder_repetition_penalty(
        &mut scores,
        encoder_input_ids,
        config.encoder_repetition_penalty,
    );
    generation_apply_repetition_penalty(&mut scores, history, config.repetition_penalty);
    generation_apply_sequence_constraints(
        &mut scores,
        history,
        encoder_input_ids,
        config,
        step,
        is_last_step,
    );
    if config.do_sample {
        generation_apply_sampling_warpers(&mut scores, config, 1)?;
    }
    generation_apply_watermarking(&mut scores, history, step, config)?;
    if config.renormalize_logits {
        scores = generation_log_softmax(&scores)?;
    }
    Ok(scores)
}

fn generation_classifier_free_guidance_scores(
    conditional_logits: &[f32],
    unconditional_logits: &[f32],
    guidance_scale: f32,
) -> Result<Vec<f32>> {
    if conditional_logits.len() != unconditional_logits.len() {
        bail!(
            "CFG conditional vocabulary width {} does not match unconditional width {}",
            conditional_logits.len(),
            unconditional_logits.len()
        );
    }
    let conditional = generation_log_softmax(conditional_logits)?;
    let unconditional = generation_log_softmax(unconditional_logits)?;
    Ok(conditional
        .into_iter()
        .zip(unconditional)
        .map(|(conditional, unconditional)| {
            unconditional + guidance_scale * (conditional - unconditional)
        })
        .collect())
}

/// Mirror Transformers' `PromptLookupCandidateGenerator`: search the current
/// sequence for the first earlier occurrence of the longest matching suffix
/// n-gram and reuse the following tokens as a speculative draft. Candidate
/// tokens that the configured logits processors would forbid are truncated,
/// and EOS is never included in the returned draft.
fn generation_prompt_lookup_candidates(
    history: &[u32],
    prompt_len: usize,
    max_total_len: usize,
    vocab_size: usize,
    config: &VulkanTransformerGenerationConfig,
) -> Result<Vec<u32>> {
    let num_output_tokens = config
        .prompt_lookup_num_tokens
        .context("prompt lookup generation requires prompt_lookup_num_tokens")?;
    let max_matching_ngram_size = config.max_matching_ngram_size.unwrap_or(2);
    if num_output_tokens == 0 || max_matching_ngram_size == 0 {
        bail!("prompt lookup generation requires positive draft and n-gram sizes");
    }
    if history.len() < 2 || history.len() + 1 >= max_total_len {
        return Ok(Vec::new());
    }

    // Keep one slot for the target model's correction/bonus token. HF may
    // temporarily draft beyond max_length and clips later, but this graph has
    // a fixed context allocation, so capping the draft here preserves the
    // generated result while avoiding an out-of-context speculative forward.
    let max_draft_len = max_total_len
        .saturating_sub(history.len())
        .saturating_sub(1);
    if max_draft_len == 0 {
        return Ok(Vec::new());
    }

    let largest_ngram = max_matching_ngram_size.min(history.len() - 1);
    for ngram_size in (1..=largest_ngram).rev() {
        let suffix = &history[history.len() - ngram_size..];
        for match_index in 0..=history.len() - ngram_size {
            if &history[match_index..match_index + ngram_size] != suffix {
                continue;
            }
            let start = match_index + ngram_size;
            let end = (start + num_output_tokens).min(history.len());
            if start >= end {
                continue;
            }
            let mut chosen = history[start..end]
                .iter()
                .copied()
                .take(max_draft_len)
                .collect::<Vec<_>>();
            if chosen.is_empty() {
                continue;
            }

            // PromptLookupCandidateGenerator probes the configured logits
            // processor list with synthetic logits and truncates a match at
            // the first forbidden token. Reuse the backend's processor stack
            // here so no-repeat/bad-word/forced/suppression behavior stays in
            // sync with normal generation.
            let mut candidate_history = history.to_vec();
            let mut allowed_len = 0usize;
            for &token in &chosen {
                let step = candidate_history.len().saturating_sub(prompt_len);
                let is_last_step = candidate_history.len() + 1 >= max_total_len;
                let fake_logits = vec![1.0f32; vocab_size];
                let processed = generation_processed_non_beam_scores(
                    &fake_logits,
                    &candidate_history,
                    config,
                    step,
                    is_last_step,
                )?;
                let token_score = processed
                    .get(token as usize)
                    .copied()
                    .unwrap_or(f32::NEG_INFINITY);
                if !token_score.is_finite() || token_score == f32::MIN {
                    break;
                }
                candidate_history.push(token);
                allowed_len += 1;
            }
            chosen.truncate(allowed_len);
            if chosen.is_empty() {
                continue;
            }

            // HF marks the match as found before cropping EOS. If EOS is the
            // first proposed token this therefore returns an empty draft
            // instead of searching a later occurrence.
            if let Some(eos_index) = chosen.iter().position(|token| config.is_eos(*token)) {
                chosen.truncate(eos_index);
            }
            return Ok(chosen);
        }
    }
    Ok(Vec::new())
}

fn generation_contrastive_top_k(scores: &[f32], top_k: usize) -> Result<Vec<(u32, f64)>> {
    if top_k <= 1 {
        bail!("contrastive generation requires top_k > 1");
    }
    if top_k > scores.len() {
        bail!(
            "contrastive generation top_k {top_k} exceeds vocabulary size {}",
            scores.len()
        );
    }
    let probabilities = generation_probabilities(scores)?;
    let mut ranked = probabilities
        .into_iter()
        .enumerate()
        .filter(|(token, _)| scores[*token].is_finite())
        .collect::<Vec<_>>();
    ranked.sort_by(
        |(left_token, left_probability), (right_token, right_probability)| {
            right_probability
                .total_cmp(left_probability)
                .then_with(|| left_token.cmp(right_token))
        },
    );
    ranked.truncate(top_k);
    ranked
        .into_iter()
        .map(|(token, probability)| {
            Ok((
                u32::try_from(token).context("generation token index exceeds u32")?,
                probability,
            ))
        })
        .collect()
}

fn generation_max_cosine_similarity(
    context_hidden: &[f32],
    candidate_hidden: &[f32],
    hidden_size: usize,
) -> Result<f64> {
    if hidden_size == 0
        || candidate_hidden.len() != hidden_size
        || context_hidden.is_empty()
        || context_hidden.len() % hidden_size != 0
    {
        bail!("contrastive generation received invalid hidden-state geometry");
    }
    let candidate_norm = candidate_hidden
        .iter()
        .map(|value| f64::from(*value).powi(2))
        .sum::<f64>()
        .sqrt();
    if !candidate_norm.is_finite() || candidate_norm == 0.0 {
        bail!("contrastive generation candidate hidden state has invalid norm");
    }
    let mut maximum = f64::NEG_INFINITY;
    for context in context_hidden.chunks_exact(hidden_size) {
        let context_norm = context
            .iter()
            .map(|value| f64::from(*value).powi(2))
            .sum::<f64>()
            .sqrt();
        if !context_norm.is_finite() || context_norm == 0.0 {
            continue;
        }
        let dot = context
            .iter()
            .zip(candidate_hidden)
            .map(|(left, right)| f64::from(*left) * f64::from(*right))
            .sum::<f64>();
        maximum = maximum.max(dot / (context_norm * candidate_norm));
    }
    if !maximum.is_finite() {
        bail!("contrastive generation context hidden states have no finite cosine similarity");
    }
    Ok(maximum)
}

fn generation_select_contrastive_candidate(
    context_hidden: &[f32],
    hidden_size: usize,
    candidates: &[(u32, f64, Vec<f32>)],
    penalty_alpha: f32,
) -> Result<u32> {
    if candidates.is_empty() {
        bail!("contrastive generation produced no candidates");
    }
    if !penalty_alpha.is_finite() || penalty_alpha <= 0.0 {
        bail!("contrastive generation penalty_alpha must be finite and positive");
    }
    let alpha = f64::from(penalty_alpha);
    let mut selected = None::<(u32, f64)>;
    for (token, probability, candidate_hidden) in candidates {
        let degeneration =
            generation_max_cosine_similarity(context_hidden, candidate_hidden, hidden_size)?;
        let contrastive_score = (1.0 - alpha) * *probability - alpha * degeneration;
        if !contrastive_score.is_finite() {
            bail!("contrastive generation produced a non-finite ranking score");
        }
        if selected
            .as_ref()
            .is_none_or(|(_, best_score)| contrastive_score > *best_score)
        {
            selected = Some((*token, contrastive_score));
        }
    }
    selected
        .map(|(token, _)| token)
        .context("contrastive generation produced no selectable candidate")
}

#[derive(Clone, Debug)]
struct VulkanGenerationBeam {
    tokens: Vec<u32>,
    score: f64,
}

#[derive(Clone, Debug)]
struct VulkanGenerationBeamCandidate {
    parent_index: usize,
    token: u32,
    score: f64,
    finished: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum VulkanGenerationForceConstraint {
    Phrasal(Vec<u32>),
    Disjunctive(Vec<Vec<u32>>),
}

impl VulkanGenerationForceConstraint {
    fn max_len(&self) -> usize {
        match self {
            Self::Phrasal(tokens) => tokens.len(),
            Self::Disjunctive(alternatives) => alternatives.iter().map(Vec::len).max().unwrap_or(0),
        }
    }

    fn initial_tokens(&self) -> Vec<u32> {
        match self {
            Self::Phrasal(tokens) => tokens.first().copied().into_iter().collect(),
            Self::Disjunctive(alternatives) => {
                let mut tokens = Vec::new();
                for token in alternatives
                    .iter()
                    .filter_map(|alternative| alternative.first().copied())
                {
                    if !tokens.contains(&token) {
                        tokens.push(token);
                    }
                }
                tokens
            }
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum VulkanGenerationConstraintProgress {
    Phrasal(usize),
    Disjunctive(Vec<u32>),
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct VulkanGenerationConstraintListState<'a> {
    constraints: &'a [VulkanGenerationForceConstraint],
    pending: Vec<usize>,
    completed: Vec<usize>,
    in_progress: Option<(usize, VulkanGenerationConstraintProgress)>,
    max_len: usize,
}

impl<'a> VulkanGenerationConstraintListState<'a> {
    fn new(constraints: &'a [VulkanGenerationForceConstraint]) -> Self {
        Self {
            constraints,
            pending: (0..constraints.len()).collect(),
            completed: Vec::new(),
            in_progress: None,
            max_len: constraints
                .iter()
                .map(VulkanGenerationForceConstraint::max_len)
                .max()
                .unwrap_or(0),
        }
    }

    fn from_history(constraints: &'a [VulkanGenerationForceConstraint], history: &[u32]) -> Self {
        let mut state = Self::new(constraints);
        for &token in history {
            state.add(token);
            if state.is_completed() {
                break;
            }
        }
        state
    }

    fn is_completed(&self) -> bool {
        self.completed.len() == self.constraints.len()
    }

    fn progress_advance_tokens(
        constraint: &VulkanGenerationForceConstraint,
        progress: &VulkanGenerationConstraintProgress,
    ) -> Vec<u32> {
        match (constraint, progress) {
            (
                VulkanGenerationForceConstraint::Phrasal(tokens),
                VulkanGenerationConstraintProgress::Phrasal(matched),
            ) => tokens.get(*matched).copied().into_iter().collect(),
            (
                VulkanGenerationForceConstraint::Disjunctive(alternatives),
                VulkanGenerationConstraintProgress::Disjunctive(prefix),
            ) => {
                let mut next_tokens = Vec::new();
                for token in alternatives
                    .iter()
                    .filter(|tokens| tokens.starts_with(prefix))
                    .filter_map(|tokens| tokens.get(prefix.len()).copied())
                {
                    if !next_tokens.contains(&token) {
                        next_tokens.push(token);
                    }
                }
                next_tokens
            }
            _ => Vec::new(),
        }
    }

    fn advance_tokens(&self) -> Vec<u32> {
        if self.is_completed() {
            return Vec::new();
        }
        if let Some((constraint_index, progress)) = self.in_progress.as_ref() {
            return Self::progress_advance_tokens(&self.constraints[*constraint_index], progress);
        }
        let mut tokens = Vec::new();
        for token in self
            .pending
            .iter()
            .flat_map(|&index| self.constraints[index].initial_tokens())
        {
            if !tokens.contains(&token) {
                tokens.push(token);
            }
        }
        tokens
    }

    fn progress_remaining(
        constraint: &VulkanGenerationForceConstraint,
        progress: &VulkanGenerationConstraintProgress,
    ) -> usize {
        match (constraint, progress) {
            (
                VulkanGenerationForceConstraint::Phrasal(tokens),
                VulkanGenerationConstraintProgress::Phrasal(matched),
            ) => tokens.len().saturating_sub(*matched),
            (
                VulkanGenerationForceConstraint::Disjunctive(alternatives),
                VulkanGenerationConstraintProgress::Disjunctive(prefix),
            ) => alternatives
                .iter()
                .filter(|tokens| tokens.starts_with(prefix))
                .map(|tokens| tokens.len().saturating_sub(prefix.len()))
                .max()
                .unwrap_or(0),
            _ => constraint.max_len(),
        }
    }

    fn bank(&self) -> usize {
        let mut bank = self.completed.len().saturating_mul(self.max_len);
        if let Some((constraint_index, progress)) = self.in_progress.as_ref() {
            bank = bank.saturating_add(self.max_len.saturating_sub(Self::progress_remaining(
                &self.constraints[*constraint_index],
                progress,
            )));
        }
        bank
    }

    fn start_progress(
        constraint: &VulkanGenerationForceConstraint,
        token: u32,
    ) -> Option<(VulkanGenerationConstraintProgress, bool)> {
        match constraint {
            VulkanGenerationForceConstraint::Phrasal(tokens) => {
                if tokens.first().copied() != Some(token) {
                    return None;
                }
                Some((
                    VulkanGenerationConstraintProgress::Phrasal(1),
                    tokens.len() == 1,
                ))
            }
            VulkanGenerationForceConstraint::Disjunctive(alternatives) => {
                if !alternatives
                    .iter()
                    .any(|tokens| tokens.first().copied() == Some(token))
                {
                    return None;
                }
                let prefix = vec![token];
                let completed = alternatives.iter().any(|tokens| *tokens == prefix);
                Some((
                    VulkanGenerationConstraintProgress::Disjunctive(prefix),
                    completed,
                ))
            }
        }
    }

    fn advance_progress(
        constraint: &VulkanGenerationForceConstraint,
        progress: &VulkanGenerationConstraintProgress,
        token: u32,
    ) -> Option<(VulkanGenerationConstraintProgress, bool)> {
        match (constraint, progress) {
            (
                VulkanGenerationForceConstraint::Phrasal(tokens),
                VulkanGenerationConstraintProgress::Phrasal(matched),
            ) => {
                if tokens.get(*matched).copied() != Some(token) {
                    return None;
                }
                let matched = *matched + 1;
                Some((
                    VulkanGenerationConstraintProgress::Phrasal(matched),
                    matched == tokens.len(),
                ))
            }
            (
                VulkanGenerationForceConstraint::Disjunctive(alternatives),
                VulkanGenerationConstraintProgress::Disjunctive(prefix),
            ) => {
                let mut next_prefix = prefix.clone();
                next_prefix.push(token);
                if !alternatives
                    .iter()
                    .any(|tokens| tokens.starts_with(&next_prefix))
                {
                    return None;
                }
                let completed = alternatives
                    .iter()
                    .any(|tokens| tokens.as_slice() == next_prefix.as_slice());
                Some((
                    VulkanGenerationConstraintProgress::Disjunctive(next_prefix),
                    completed,
                ))
            }
            _ => None,
        }
    }

    fn add(&mut self, token: u32) {
        if self.is_completed() {
            return;
        }
        if let Some((constraint_index, progress)) = self.in_progress.take() {
            if let Some((next_progress, completed)) =
                Self::advance_progress(&self.constraints[constraint_index], &progress, token)
            {
                if completed {
                    self.completed.push(constraint_index);
                } else {
                    self.in_progress = Some((constraint_index, next_progress));
                }
            } else {
                // Match Transformers' ConstraintListState: a token that breaks
                // an in-progress constraint resets only that constraint and is
                // not reconsidered as the start of another pending constraint.
                self.pending.push(constraint_index);
            }
            return;
        }

        let mut matched_pending = None;
        for (pending_offset, &constraint_index) in self.pending.iter().enumerate() {
            if let Some((progress, completed)) =
                Self::start_progress(&self.constraints[constraint_index], token)
            {
                matched_pending = Some((pending_offset, constraint_index, progress, completed));
                break;
            }
        }
        if let Some((pending_offset, constraint_index, progress, completed)) = matched_pending {
            self.pending.remove(pending_offset);
            if completed {
                self.completed.push(constraint_index);
            } else {
                self.in_progress = Some((constraint_index, progress));
            }
        }
    }
}

fn generation_parse_force_words_ids(
    raw: &serde_json::Value,
) -> Result<Vec<VulkanGenerationForceConstraint>> {
    let entries = raw
        .as_array()
        .context("generation force_words_ids must be a non-empty list")?;
    if entries.is_empty() {
        bail!("generation force_words_ids must be a non-empty list");
    }
    entries
        .iter()
        .enumerate()
        .map(|(constraint_index, entry)| {
            let values = entry.as_array().with_context(|| {
                format!("generation force_words_ids[{constraint_index}] must be a non-empty list")
            })?;
            if values.is_empty() {
                bail!("generation force_words_ids[{constraint_index}] must be a non-empty list");
            }
            if values[0].is_array() {
                let alternatives = values
                    .iter()
                    .enumerate()
                    .map(|(alternative_index, alternative)| {
                        let tokens = alternative.as_array().with_context(|| {
                            format!(
                                "generation force_words_ids[{constraint_index}][{alternative_index}] must be a non-empty integer list"
                            )
                        })?;
                        if tokens.is_empty() {
                            bail!(
                                "generation force_words_ids[{constraint_index}][{alternative_index}] must not be empty"
                            );
                        }
                        tokens
                            .iter()
                            .enumerate()
                            .map(|(token_index, token)| {
                                token
                                    .as_u64()
                                    .with_context(|| {
                                        format!(
                                            "generation force_words_ids[{constraint_index}][{alternative_index}][{token_index}] must be a non-negative integer"
                                        )
                                    })?
                                    .try_into()
                                    .context("generation force_words_ids token exceeds u32")
                            })
                            .collect::<Result<Vec<u32>>>()
                    })
                    .collect::<Result<Vec<_>>>()?;
                for left in 0..alternatives.len() {
                    for right in 0..alternatives.len() {
                        if left != right
                            && alternatives[left].len() <= alternatives[right].len()
                            && alternatives[right].starts_with(&alternatives[left])
                        {
                            bail!(
                                "generation force_words_ids[{constraint_index}] alternatives may not be prefixes of one another"
                            );
                        }
                    }
                }
                Ok(VulkanGenerationForceConstraint::Disjunctive(alternatives))
            } else {
                let tokens = values
                    .iter()
                    .enumerate()
                    .map(|(token_index, token)| {
                        token
                            .as_u64()
                            .with_context(|| {
                                format!(
                                    "generation force_words_ids[{constraint_index}][{token_index}] must be a non-negative integer"
                                )
                            })?
                            .try_into()
                            .context("generation force_words_ids token exceeds u32")
                    })
                    .collect::<Result<Vec<u32>>>()?;
                Ok(VulkanGenerationForceConstraint::Phrasal(tokens))
            }
        })
        .collect()
}

fn generation_force_constraints_from_config(
    config: &VulkanTransformerGenerationConfig,
) -> Result<Vec<VulkanGenerationForceConstraint>> {
    if config.constraints.is_some() {
        bail!(
            "Vulkan Transformer constrained generation currently accepts serializable force_words_ids; custom Constraint objects require a native constraint API"
        );
    }
    generation_parse_force_words_ids(
        config
            .force_words_ids
            .as_ref()
            .context("constrained beam search requires force_words_ids")?,
    )
}

fn generation_constraints_completed(
    history: &[u32],
    constraints: &[VulkanGenerationForceConstraint],
) -> bool {
    VulkanGenerationConstraintListState::from_history(constraints, history).is_completed()
}

fn generation_constraint_bank(
    history: &[u32],
    constraints: &[VulkanGenerationForceConstraint],
) -> usize {
    VulkanGenerationConstraintListState::from_history(constraints, history).bank()
}

#[derive(Clone, Debug)]
struct VulkanGenerationTraceBeam {
    tokens: Vec<u32>,
    score: f64,
    scores: Vec<Vec<f32>>,
    logits: Vec<Vec<f32>>,
    beam_indices: Vec<usize>,
}

const GENERATION_KV_PAGE_TOKENS: usize = 16;
const GENERATION_KV_UNMAPPED_PAGE: u32 = u32::MAX;

struct VulkanGenerationPagedKvArenaState {
    key: GpuBuffer,
    value: GpuBuffer,
    page_refcounts: Vec<usize>,
    free_pages: Vec<usize>,
}

struct VulkanGenerationPagedKvArena {
    device: VulkanDevice,
    key_width: usize,
    value_width: usize,
    page_size: usize,
    state: Mutex<VulkanGenerationPagedKvArenaState>,
}

struct VulkanGenerationPagedKvTableState {
    logical_to_physical: Vec<u32>,
    device: GpuBuffer,
}

struct VulkanGenerationPagedKvCache {
    arena: Arc<VulkanGenerationPagedKvArena>,
    table: Mutex<VulkanGenerationPagedKvTableState>,
}

struct VulkanGenerationPagedKvSnapshot {
    key: GpuBuffer,
    value: GpuBuffer,
    page_table: GpuBuffer,
    key_write_offsets: Vec<usize>,
    value_write_offsets: Vec<usize>,
    page_size: usize,
    page_table_stride: usize,
}

impl VulkanGenerationPagedKvArena {
    fn new(
        device: &VulkanDevice,
        key_width: usize,
        value_width: usize,
        initial_pages: usize,
    ) -> Result<Arc<Self>> {
        if key_width == 0 || value_width == 0 {
            bail!("generation paged KV arena requires positive K/V widths");
        }
        let physical_pages = initial_pages.max(1);
        if physical_pages > u32::MAX as usize {
            bail!("generation paged KV cache page count exceeds u32 address space");
        }
        let key_len =
            Self::checked_buffer_len(key_width, GENERATION_KV_PAGE_TOKENS, physical_pages, "key")?;
        let value_len = Self::checked_buffer_len(
            value_width,
            GENERATION_KV_PAGE_TOKENS,
            physical_pages,
            "value",
        )?;
        Ok(Arc::new(Self {
            device: device.clone(),
            key_width,
            value_width,
            page_size: GENERATION_KV_PAGE_TOKENS,
            state: Mutex::new(VulkanGenerationPagedKvArenaState {
                key: GpuBuffer::zeros_f32(device, key_len)?,
                value: GpuBuffer::zeros_f32(device, value_len)?,
                page_refcounts: vec![0; physical_pages],
                free_pages: (0..physical_pages).rev().collect(),
            }),
        }))
    }

    fn checked_buffer_len(
        width: usize,
        page_size: usize,
        pages: usize,
        label: &str,
    ) -> Result<usize> {
        pages
            .checked_mul(page_size)
            .and_then(|tokens| tokens.checked_mul(width))
            .with_context(|| format!("generation paged {label} cache allocation overflow"))
    }

    fn grow_locked(&self, state: &mut VulkanGenerationPagedKvArenaState) -> Result<()> {
        let old_pages = state.page_refcounts.len();
        let new_pages = old_pages
            .checked_mul(2)
            .unwrap_or(usize::MAX)
            .max(old_pages.saturating_add(1));
        if new_pages <= old_pages || new_pages > u32::MAX as usize {
            bail!("generation paged KV cache exhausted its physical page address space");
        }
        let key_len = Self::checked_buffer_len(self.key_width, self.page_size, new_pages, "key")?;
        let value_len =
            Self::checked_buffer_len(self.value_width, self.page_size, new_pages, "value")?;
        let new_key = GpuBuffer::zeros_f32(&self.device, key_len)?;
        let new_value = GpuBuffer::zeros_f32(&self.device, value_len)?;

        if old_pages != 0 {
            let old_key_len =
                Self::checked_buffer_len(self.key_width, self.page_size, old_pages, "key")?;
            let old_value_len =
                Self::checked_buffer_len(self.value_width, self.page_size, old_pages, "value")?;
            let mut commands = vulkan::ComputeBatch::new(&self.device)?;
            commands.copy_f32(&state.key, &new_key, old_key_len)?;
            commands.copy_f32(&state.value, &new_value, old_value_len)?;
            commands.submit()?;
        }

        state.key = new_key;
        state.value = new_value;
        state.page_refcounts.resize(new_pages, 0);
        state.free_pages.extend((old_pages..new_pages).rev());
        Ok(())
    }

    fn allocate_page_locked(&self, state: &mut VulkanGenerationPagedKvArenaState) -> Result<usize> {
        if state.free_pages.is_empty() {
            self.grow_locked(state)?;
        }
        let page = state
            .free_pages
            .pop()
            .context("generation paged KV cache failed to allocate a physical page")?;
        let refcount = state
            .page_refcounts
            .get_mut(page)
            .context("generation paged KV cache allocator returned an invalid physical page")?;
        if *refcount != 0 {
            bail!("generation paged KV cache allocator returned a referenced physical page");
        }
        *refcount = 1;
        Ok(page)
    }
}

impl VulkanGenerationPagedKvCache {
    fn new(
        device: &VulkanDevice,
        key_width: usize,
        value_width: usize,
        max_tokens: usize,
        prefix_len: usize,
    ) -> Result<Self> {
        if key_width == 0 || value_width == 0 || max_tokens == 0 {
            bail!("generation paged KV cache requires positive dimensions");
        }
        if prefix_len > max_tokens {
            bail!(
                "generation paged KV cache prefix {prefix_len} exceeds logical capacity {max_tokens}"
            );
        }
        let logical_pages = max_tokens.div_ceil(GENERATION_KV_PAGE_TOKENS);
        let prefix_pages = prefix_len.div_ceil(GENERATION_KV_PAGE_TOKENS);
        let physical_pages = prefix_pages.max(1);
        if logical_pages > u32::MAX as usize || physical_pages > u32::MAX as usize {
            bail!("generation paged KV cache page count exceeds u32 address space");
        }
        let arena =
            VulkanGenerationPagedKvArena::new(device, key_width, value_width, physical_pages)?;
        Self::new_in_arena(arena, max_tokens, prefix_len)
    }

    fn new_in_arena(
        arena: Arc<VulkanGenerationPagedKvArena>,
        max_tokens: usize,
        prefix_len: usize,
    ) -> Result<Self> {
        if max_tokens == 0 {
            bail!("generation paged KV cache requires a positive logical capacity");
        }
        if prefix_len > max_tokens {
            bail!(
                "generation paged KV cache prefix {prefix_len} exceeds logical capacity {max_tokens}"
            );
        }
        let logical_pages = max_tokens.div_ceil(arena.page_size);
        let prefix_pages = prefix_len.div_ceil(arena.page_size);
        if logical_pages > u32::MAX as usize {
            bail!("generation paged KV cache page count exceeds u32 address space");
        }

        let mut logical_to_physical = vec![GENERATION_KV_UNMAPPED_PAGE; logical_pages];
        {
            let mut arena_state = arena
                .state
                .lock()
                .map_err(|_| anyhow!("generation paged KV arena mutex is poisoned"))?;
            for physical_page in logical_to_physical.iter_mut().take(prefix_pages) {
                *physical_page = u32::try_from(arena.allocate_page_locked(&mut arena_state)?)
                    .context("generation paged KV cache physical page exceeds u32")?;
            }
        }
        let page_table = GpuBuffer::from_u32(&arena.device, &logical_to_physical)?;
        Ok(Self {
            arena,
            table: Mutex::new(VulkanGenerationPagedKvTableState {
                logical_to_physical,
                device: page_table,
            }),
        })
    }

    fn clone_prefix(&self, prefix_len: usize) -> Result<Self> {
        let prefix_pages = prefix_len.div_ceil(self.arena.page_size);
        let parent = self
            .table
            .lock()
            .map_err(|_| anyhow!("generation paged KV page-table mutex is poisoned"))?;
        if prefix_pages > parent.logical_to_physical.len() {
            bail!(
                "generation paged KV clone prefix {prefix_len} exceeds logical cache capacity {}",
                parent.logical_to_physical.len() * self.arena.page_size
            );
        }
        let mut logical_to_physical =
            vec![GENERATION_KV_UNMAPPED_PAGE; parent.logical_to_physical.len()];
        logical_to_physical[..prefix_pages]
            .copy_from_slice(&parent.logical_to_physical[..prefix_pages]);
        if logical_to_physical[..prefix_pages].contains(&GENERATION_KV_UNMAPPED_PAGE) {
            bail!("generation paged KV clone encountered an unmapped prefix page");
        }
        let device_table = GpuBuffer::from_u32(&self.arena.device, &logical_to_physical)?;
        let mut arena = self
            .arena
            .state
            .lock()
            .map_err(|_| anyhow!("generation paged KV arena mutex is poisoned"))?;
        for &physical in &logical_to_physical[..prefix_pages] {
            let physical = physical as usize;
            let refcount = arena
                .page_refcounts
                .get_mut(physical)
                .context("generation paged KV clone references an invalid physical page")?;
            *refcount = refcount
                .checked_add(1)
                .context("generation paged KV page reference count overflow")?;
        }
        drop(arena);
        drop(parent);
        Ok(Self {
            arena: Arc::clone(&self.arena),
            table: Mutex::new(VulkanGenerationPagedKvTableState {
                logical_to_physical,
                device: device_table,
            }),
        })
    }

    fn prepare_write(&self, position: usize) -> Result<()> {
        let logical_page = position / self.arena.page_size;
        let mut table = self
            .table
            .lock()
            .map_err(|_| anyhow!("generation paged KV page-table mutex is poisoned"))?;
        if logical_page >= table.logical_to_physical.len() {
            bail!(
                "generation paged KV write position {position} exceeds logical cache capacity {}",
                table.logical_to_physical.len() * self.arena.page_size
            );
        }
        let current = table.logical_to_physical[logical_page];
        let mut arena = self
            .arena
            .state
            .lock()
            .map_err(|_| anyhow!("generation paged KV arena mutex is poisoned"))?;

        let mut copied_from = None;
        let target = if current == GENERATION_KV_UNMAPPED_PAGE {
            self.arena.allocate_page_locked(&mut arena)?
        } else {
            let current_page = current as usize;
            let refcount = *arena
                .page_refcounts
                .get(current_page)
                .context("generation paged KV page table references an invalid physical page")?;
            if refcount > 1 {
                let target = self.arena.allocate_page_locked(&mut arena)?;
                let old_refcount = arena
                    .page_refcounts
                    .get_mut(current_page)
                    .context("generation paged KV COW source page is invalid")?;
                *old_refcount -= 1;
                copied_from = Some(current_page);
                target
            } else {
                return Ok(());
            }
        };
        table.logical_to_physical[logical_page] =
            u32::try_from(target).context("generation paged KV physical page exceeds u32")?;

        let mut commands = vulkan::ComputeBatch::new(&self.arena.device)?;
        if let Some(source) = copied_from {
            let key_page_len = self
                .arena
                .page_size
                .checked_mul(self.arena.key_width)
                .context("generation paged key page size overflow")?;
            let value_page_len = self
                .arena
                .page_size
                .checked_mul(self.arena.value_width)
                .context("generation paged value page size overflow")?;
            commands.copy_f32_range(
                &arena.key,
                source * key_page_len,
                &arena.key,
                target * key_page_len,
                key_page_len,
            )?;
            commands.copy_f32_range(
                &arena.value,
                source * value_page_len,
                &arena.value,
                target * value_page_len,
                value_page_len,
            )?;
        }
        commands.upload_u32(&table.device, &table.logical_to_physical)?;
        commands.submit()?;
        Ok(())
    }

    fn snapshot_for_position(&self, position: usize) -> Result<VulkanGenerationPagedKvSnapshot> {
        let logical_page = position / self.arena.page_size;
        let within_page = position % self.arena.page_size;
        let table = self
            .table
            .lock()
            .map_err(|_| anyhow!("generation paged KV page-table mutex is poisoned"))?;
        let physical_page = *table
            .logical_to_physical
            .get(logical_page)
            .context("generation paged KV snapshot position exceeds logical cache capacity")?;
        if physical_page == GENERATION_KV_UNMAPPED_PAGE {
            bail!("generation paged KV snapshot requested an unmapped logical page");
        }
        let physical_row = (physical_page as usize)
            .checked_mul(self.arena.page_size)
            .and_then(|base| base.checked_add(within_page))
            .context("generation paged KV physical row overflow")?;
        let arena = self
            .arena
            .state
            .lock()
            .map_err(|_| anyhow!("generation paged KV arena mutex is poisoned"))?;
        Ok(VulkanGenerationPagedKvSnapshot {
            key: arena.key.clone(),
            value: arena.value.clone(),
            page_table: table.device.clone(),
            key_write_offsets: vec![physical_row
                .checked_mul(self.arena.key_width)
                .context("generation paged KV key write offset overflow")?],
            value_write_offsets: vec![physical_row
                .checked_mul(self.arena.value_width)
                .context("generation paged KV value write offset overflow")?],
            page_size: self.arena.page_size,
            page_table_stride: table.logical_to_physical.len(),
        })
    }

    fn record_prefill_from_sources(
        &self,
        commands: &mut vulkan::ComputeBatch,
        key_source: &GpuBuffer,
        value_source: &GpuBuffer,
        source_row_offset: usize,
        prefix_len: usize,
    ) -> Result<()> {
        if prefix_len == 0 {
            return Ok(());
        }
        let table = self
            .table
            .lock()
            .map_err(|_| anyhow!("generation paged KV page-table mutex is poisoned"))?;
        let arena = self
            .arena
            .state
            .lock()
            .map_err(|_| anyhow!("generation paged KV arena mutex is poisoned"))?;
        let prefix_pages = prefix_len.div_ceil(self.arena.page_size);
        if prefix_pages > table.logical_to_physical.len() {
            bail!("generation paged KV prefill exceeds logical cache capacity");
        }
        for logical_page in 0..prefix_pages {
            let physical_page = table.logical_to_physical[logical_page];
            if physical_page == GENERATION_KV_UNMAPPED_PAGE {
                bail!("generation paged KV prefill encountered an unmapped logical page");
            }
            let first_token = logical_page * self.arena.page_size;
            let token_count = (prefix_len - first_token).min(self.arena.page_size);
            let source_row = source_row_offset
                .checked_add(first_token)
                .context("generation paged KV prefill source row overflow")?;
            let destination_row = (physical_page as usize)
                .checked_mul(self.arena.page_size)
                .context("generation paged KV prefill physical row overflow")?;
            commands.copy_f32_range(
                key_source,
                source_row
                    .checked_mul(self.arena.key_width)
                    .context("generation paged KV prefill key source offset overflow")?,
                &arena.key,
                destination_row
                    .checked_mul(self.arena.key_width)
                    .context("generation paged KV prefill key destination offset overflow")?,
                token_count
                    .checked_mul(self.arena.key_width)
                    .context("generation paged KV prefill key length overflow")?,
            )?;
            commands.copy_f32_range(
                value_source,
                source_row
                    .checked_mul(self.arena.value_width)
                    .context("generation paged KV prefill value source offset overflow")?,
                &arena.value,
                destination_row
                    .checked_mul(self.arena.value_width)
                    .context("generation paged KV prefill value destination offset overflow")?,
                token_count
                    .checked_mul(self.arena.value_width)
                    .context("generation paged KV prefill value length overflow")?,
            )?;
        }
        Ok(())
    }
}

impl Drop for VulkanGenerationPagedKvCache {
    fn drop(&mut self) {
        let Ok(table) = self.table.lock() else {
            return;
        };
        let Ok(mut arena) = self.arena.state.lock() else {
            return;
        };
        for &physical in &table.logical_to_physical {
            if physical == GENERATION_KV_UNMAPPED_PAGE {
                continue;
            }
            let physical = physical as usize;
            let Some(refcount) = arena.page_refcounts.get_mut(physical) else {
                continue;
            };
            if *refcount == 0 {
                continue;
            }
            *refcount -= 1;
            if *refcount == 0 {
                arena.free_pages.push(physical);
            }
        }
    }
}

struct VulkanGenerationLayerKvCache {
    key: GpuBuffer,
    value: GpuBuffer,
    /// Ordinary causal attention uses a Vulkan-resident page table over a
    /// growable physical K/V arena. Beam forks share mapped prefix pages and
    /// copy only a partially shared page on first write.
    paged_kv: Option<VulkanGenerationPagedKvCache>,
    /// DeepSeek-V4's CSA/HCA compressors consume the pre-attention hidden
    /// stream, not only the projected K/V state. Cached decoding retains that
    /// stream so completed compression windows can be refreshed without
    /// replaying earlier Transformer layers.
    deepseek_v4_attention_input: Option<GpuBuffer>,
    /// DeepSeek-V3.2's lightning indexer owns a separate single-head key
    /// stream. Other architectures leave this absent and retain the historical
    /// K/V-only generation cache layout.
    indexer_key: Option<GpuBuffer>,
    /// Hybrid Qwen linear-attention layers use a depthwise Conv1D history
    /// instead of K/V state. Layout is token-major [kernel, channels], oldest
    /// to newest, so a single-token update can shift one channel independently.
    qwen_gated_delta_conv_state: Option<GpuBuffer>,
    /// Recurrent Gated DeltaNet state [value_head, key_dim, value_dim].
    qwen_gated_delta_recurrent_state: Option<GpuBuffer>,
    /// Qwen4 PLE's dilated depthwise Conv1D history. The buffer is token-major
    /// [history_token, hyper_channel], oldest to newest.
    qwen4_ple_conv_state: Option<GpuBuffer>,
    /// CPU-side lexical history used to reproduce Hugging Face's hashed PLE
    /// n-gram ids for the next cached token. Beam-cache clones own independent
    /// copies so speculative/beam branches cannot mutate one another.
    qwen4_ple_ngram_history: Option<Mutex<Vec<u32>>>,
}

struct VulkanGenerationKvCache {
    layers: Vec<VulkanGenerationLayerKvCache>,
    attention_mask: GpuBuffer,
    alibi_positions: GpuBuffer,
}

struct VulkanGenerationCachedBeam {
    beam: VulkanGenerationBeam,
    logits: Vec<f32>,
    cache: VulkanGenerationKvCache,
}

struct VulkanGenerationContinuousRequest {
    batch_index: usize,
    config: VulkanTransformerGenerationConfig,
    sequence: Vec<u32>,
    generated: Vec<u32>,
    logits: Vec<f32>,
    cache: VulkanGenerationKvCache,
    requested: usize,
}

impl VulkanGenerationBeam {
    fn normalized_score(&self, prompt_len: usize, length_penalty: f32) -> f64 {
        let generated_len = self.tokens.len().saturating_sub(prompt_len).max(1) as f64;
        self.score / generated_len.powf(f64::from(length_penalty))
    }
}

impl VulkanGenerationTraceBeam {
    fn normalized_score(&self, prompt_len: usize, length_penalty: f32) -> f64 {
        let generated_len = self.tokens.len().saturating_sub(prompt_len).max(1) as f64;
        self.score / generated_len.powf(f64::from(length_penalty))
    }
}

fn generation_trim_completed_trace_beams(
    completed: &mut Vec<VulkanGenerationTraceBeam>,
    prompt_len: usize,
    beam_width: usize,
    length_penalty: f32,
) {
    completed.sort_by(|left, right| {
        right
            .normalized_score(prompt_len, length_penalty)
            .total_cmp(&left.normalized_score(prompt_len, length_penalty))
            .then_with(|| left.tokens.cmp(&right.tokens))
    });
    completed.truncate(beam_width);
}

fn generation_beam_should_stop_for_width<'a, I>(
    running: I,
    completed: &[VulkanGenerationBeam],
    prompt_len: usize,
    requested: usize,
    beam_width: usize,
    config: &VulkanTransformerGenerationConfig,
) -> bool
where
    I: IntoIterator<Item = &'a VulkanGenerationBeam>,
{
    if completed.len() < beam_width {
        return false;
    }
    if config.early_stopping {
        return true;
    }

    let mut finished_scores = completed
        .iter()
        .map(|beam| beam.normalized_score(prompt_len, config.length_penalty))
        .collect::<Vec<_>>();
    finished_scores.sort_by(|left, right| right.total_cmp(left));
    finished_scores.truncate(beam_width);
    let Some(&worst_finished_score) = finished_scores.last() else {
        return false;
    };

    let mut best_possible_running_score = f64::NEG_INFINITY;
    for beam in running {
        let current_generated_len = beam.tokens.len().saturating_sub(prompt_len).max(1);
        let hypothetical_len = if config.early_stopping_never && config.length_penalty > 0.0 {
            requested.max(1)
        } else {
            current_generated_len
        } as f64;
        let score = beam.score / hypothetical_len.powf(f64::from(config.length_penalty));
        best_possible_running_score = best_possible_running_score.max(score);
    }
    best_possible_running_score <= worst_finished_score
}

fn generation_beam_should_stop<'a, I>(
    running: I,
    completed: &[VulkanGenerationBeam],
    prompt_len: usize,
    requested: usize,
    config: &VulkanTransformerGenerationConfig,
) -> bool
where
    I: IntoIterator<Item = &'a VulkanGenerationBeam>,
{
    generation_beam_should_stop_for_width(
        running,
        completed,
        prompt_len,
        requested,
        config.num_beams,
        config,
    )
}

fn generation_trim_completed_beams(
    completed: &mut Vec<VulkanGenerationBeam>,
    prompt_len: usize,
    beam_width: usize,
    length_penalty: f32,
) {
    completed.sort_by(|left, right| {
        right
            .normalized_score(prompt_len, length_penalty)
            .total_cmp(&left.normalized_score(prompt_len, length_penalty))
            .then_with(|| left.tokens.cmp(&right.tokens))
    });
    completed.truncate(beam_width);
}

fn generation_finalize_beams(
    mut completed: Vec<VulkanGenerationBeam>,
    prompt_len: usize,
    config: &VulkanTransformerGenerationConfig,
) -> Result<Vec<Vec<u32>>> {
    completed.sort_by(|left, right| {
        right
            .normalized_score(prompt_len, config.length_penalty)
            .total_cmp(&left.normalized_score(prompt_len, config.length_penalty))
            .then_with(|| left.tokens.cmp(&right.tokens))
    });
    completed.truncate(config.num_return_sequences);
    if completed.len() < config.num_return_sequences {
        bail!(
            "beam search produced {} hypotheses, fewer than num_return_sequences {}",
            completed.len(),
            config.num_return_sequences
        );
    }
    Ok(completed
        .into_iter()
        .map(|beam| beam.tokens[prompt_len..].to_vec())
        .collect())
}

fn generation_finalize_constrained_beams(
    mut completed: Vec<VulkanGenerationBeam>,
    active: Vec<VulkanGenerationBeam>,
    prompt_len: usize,
    constraints: &[VulkanGenerationForceConstraint],
    config: &VulkanTransformerGenerationConfig,
) -> Result<Vec<Vec<u32>>> {
    let mut fallback = Vec::new();
    for beam in active {
        if generation_constraints_completed(&beam.tokens, constraints) {
            completed.push(beam);
        } else {
            fallback.push(beam);
        }
    }
    let ranking = |left: &VulkanGenerationBeam, right: &VulkanGenerationBeam| {
        right
            .normalized_score(prompt_len, config.length_penalty)
            .total_cmp(&left.normalized_score(prompt_len, config.length_penalty))
            .then_with(|| left.tokens.cmp(&right.tokens))
    };
    completed.sort_by(ranking);
    fallback.sort_by(ranking);
    completed.truncate(config.num_return_sequences);
    if completed.len() < config.num_return_sequences {
        let missing = config.num_return_sequences - completed.len();
        completed.extend(fallback.into_iter().take(missing));
    }
    if completed.len() < config.num_return_sequences {
        bail!(
            "constrained beam search produced {} hypotheses, fewer than num_return_sequences {}",
            completed.len(),
            config.num_return_sequences
        );
    }
    Ok(completed
        .into_iter()
        .map(|beam| beam.tokens[prompt_len..].to_vec())
        .collect())
}

fn generation_beam_processed_log_probs(
    logits: &[f32],
    history: &[u32],
    config: &VulkanTransformerGenerationConfig,
    step: usize,
    is_last_step: bool,
) -> Result<Vec<f32>> {
    // Current HF beam search first converts model logits to log probabilities,
    // then applies its processor/warper stack, and only afterwards adds the
    // accumulated beam score. Preserve that order here; repetition penalty is
    // intentionally applied to log probabilities in beam mode.
    generation_beam_processed_log_probs_from_log_probs(
        generation_log_softmax(logits)?,
        history,
        config,
        step,
        is_last_step,
    )
}

fn generation_beam_processed_log_probs_from_log_probs(
    mut log_probs: Vec<f32>,
    history: &[u32],
    config: &VulkanTransformerGenerationConfig,
    step: usize,
    is_last_step: bool,
) -> Result<Vec<f32>> {
    generation_apply_sequence_bias(&mut log_probs, history, &config.sequence_bias)?;
    let encoder_input_ids = generation_encoder_input_ids(history, config, step);
    generation_apply_encoder_repetition_penalty(
        &mut log_probs,
        encoder_input_ids,
        config.encoder_repetition_penalty,
    );
    generation_apply_repetition_penalty(&mut log_probs, history, config.repetition_penalty);
    generation_apply_sequence_constraints(
        &mut log_probs,
        history,
        encoder_input_ids,
        config,
        step,
        is_last_step,
    );
    if config.do_sample {
        let min_tokens_to_keep = config.eos_token_ids.len().saturating_add(1).max(2);
        generation_apply_sampling_warpers(&mut log_probs, config, min_tokens_to_keep)?;
    }
    generation_apply_watermarking(&mut log_probs, history, step, config)?;
    if config.renormalize_logits {
        log_probs = generation_log_softmax(&log_probs)?;
    }
    Ok(log_probs)
}

fn generation_select_beam_candidates_for_width(
    mut candidates: Vec<VulkanGenerationBeamCandidate>,
    config: &VulkanTransformerGenerationConfig,
    step: usize,
    beam_width: usize,
) -> Result<Vec<VulkanGenerationBeamCandidate>> {
    if candidates.is_empty() {
        bail!("beam search produced no finite continuation candidates");
    }
    let beams_to_keep = config
        .eos_token_ids
        .len()
        .saturating_add(1)
        .max(2)
        .saturating_mul(beam_width)
        .min(candidates.len());

    if !config.do_sample {
        candidates.sort_by(|left, right| {
            right
                .score
                .total_cmp(&left.score)
                .then_with(|| left.parent_index.cmp(&right.parent_index))
                .then_with(|| left.token.cmp(&right.token))
        });
        candidates.truncate(beams_to_keep);
        return Ok(candidates);
    }

    // HF beam sampling draws from the flattened beam×vocabulary distribution
    // without replacement. Use the backend's canonical Philox stream so the
    // Vulkan surface stays reproducible independent of host RNG libraries.
    let mut selected = Vec::with_capacity(beams_to_keep);
    for draw in 0..beams_to_keep {
        let max_score = candidates
            .iter()
            .map(|candidate| candidate.score)
            .filter(|score| score.is_finite())
            .max_by(f64::total_cmp)
            .context("beam sampling candidates contain no finite scores")?;
        let weights = candidates
            .iter()
            .map(|candidate| {
                if candidate.score.is_finite() {
                    (candidate.score - max_score).exp()
                } else {
                    0.0
                }
            })
            .collect::<Vec<_>>();
        let total = weights.iter().sum::<f64>();
        if !total.is_finite() || total <= 0.0 {
            bail!("beam sampling softmax normalizer is invalid");
        }
        let sample_index = ((step as u64) << 32) | draw as u64;
        let random_word = hierarchos_canonical_philox_word(config.seed, sample_index);
        let target = ((f64::from(random_word) + 0.5) / 4_294_967_296.0) * total;
        let mut cumulative = 0.0f64;
        let mut selected_index = candidates.len() - 1;
        for (index, weight) in weights.iter().enumerate() {
            cumulative += *weight;
            if target < cumulative {
                selected_index = index;
                break;
            }
        }
        selected.push(candidates.remove(selected_index));
    }
    Ok(selected)
}

fn generation_select_beam_candidates(
    candidates: Vec<VulkanGenerationBeamCandidate>,
    config: &VulkanTransformerGenerationConfig,
    step: usize,
) -> Result<Vec<VulkanGenerationBeamCandidate>> {
    generation_select_beam_candidates_for_width(candidates, config, step, config.num_beams)
}

fn generation_apply_hamming_diversity(
    scores: &mut [f32],
    previous_group_tokens: &[u32],
    diversity_penalty: f32,
) {
    if previous_group_tokens.is_empty() || diversity_penalty <= 0.0 {
        return;
    }
    let mut frequency = vec![0_u32; scores.len()];
    for &token in previous_group_tokens {
        if let Some(slot) = frequency.get_mut(token as usize) {
            *slot = slot.saturating_add(1);
        }
    }
    for (score, count) in scores.iter_mut().zip(frequency) {
        if count != 0 {
            *score -= diversity_penalty * count as f32;
        }
    }
}

fn generation_select_constrained_beam_step(
    histories: &[Vec<u32>],
    accumulated_scores: &[f64],
    processed_scores: &[Vec<f32>],
    constraints: &[VulkanGenerationForceConstraint],
    config: &VulkanTransformerGenerationConfig,
    step: usize,
) -> Result<(
    Vec<VulkanGenerationBeamCandidate>,
    Vec<VulkanGenerationBeamCandidate>,
)> {
    if histories.len() != accumulated_scores.len() || histories.len() != processed_scores.len() {
        bail!("constrained beam state vectors have inconsistent lengths");
    }

    let mut all_candidates = Vec::new();
    for parent_index in 0..histories.len() {
        for (token, log_probability) in processed_scores[parent_index]
            .iter()
            .copied()
            .enumerate()
            .filter(|(_, score)| score.is_finite())
        {
            let token = u32::try_from(token).context("generation token index exceeds u32")?;
            all_candidates.push(VulkanGenerationBeamCandidate {
                parent_index,
                token,
                score: accumulated_scores[parent_index] + f64::from(log_probability),
                finished: config.should_stop_after_token(&histories[parent_index], token),
            });
        }
    }

    let selected = generation_select_beam_candidates(all_candidates, config, step)?;
    let mut completed = Vec::new();
    let mut next = Vec::with_capacity(config.num_beams);
    for (selection_index, candidate) in selected.into_iter().enumerate() {
        if candidate.finished {
            if selection_index < config.num_beams
                && generation_constraints_completed(&histories[candidate.parent_index], constraints)
            {
                completed.push(candidate);
            }
            continue;
        }
        if next.len() < config.num_beams {
            next.push(candidate);
        }
        if next.len() == config.num_beams {
            break;
        }
    }
    if next.len() < config.num_beams {
        bail!(
            "constrained beam search produced only {} non-EOS continuations for {} beams",
            next.len(),
            config.num_beams
        );
    }

    let mut seen_sequences = BTreeSet::<Vec<u32>>::new();
    for candidate in &next {
        let mut sequence = histories[candidate.parent_index].clone();
        sequence.push(candidate.token);
        seen_sequences.insert(sequence);
    }
    let mut injected = Vec::new();
    for parent_index in 0..histories.len() {
        let state = VulkanGenerationConstraintListState::from_history(
            constraints,
            &histories[parent_index],
        );
        if state.is_completed() {
            continue;
        }
        for token in state.advance_tokens() {
            let token_index = token as usize;
            let Some(&log_probability) = processed_scores[parent_index].get(token_index) else {
                bail!(
                    "force_words_ids token {} exceeds model vocabulary size {}",
                    token,
                    processed_scores[parent_index].len()
                );
            };
            if !log_probability.is_finite() {
                continue;
            }
            let mut sequence = histories[parent_index].clone();
            sequence.push(token);
            if !seen_sequences.insert(sequence) {
                continue;
            }
            injected.push(VulkanGenerationBeamCandidate {
                parent_index,
                token,
                score: accumulated_scores[parent_index] + f64::from(log_probability),
                // Transformers' constraint scorer injects progress tokens into
                // the next live beam set even when the token is also EOS.
                finished: false,
            });
        }
    }
    next.extend(injected);

    #[derive(Clone)]
    struct BankCandidate {
        candidate: VulkanGenerationBeamCandidate,
        bank: usize,
        within_bank_rank: usize,
    }

    let mut banked = next
        .into_iter()
        .map(|candidate| {
            let mut sequence = histories[candidate.parent_index].clone();
            sequence.push(candidate.token);
            BankCandidate {
                bank: generation_constraint_bank(&sequence, constraints),
                candidate,
                within_bank_rank: 0,
            }
        })
        .collect::<Vec<_>>();

    // Match ConstrainedBeamSearchScorer.step_sentence_constraint: first sort
    // by bank*100 + accumulated score, then stably interleave equal-bank
    // candidates by their rank within each sorted bank block.
    banked.sort_by(|left, right| {
        let left_key = left.bank as f64 * 100.0 + left.candidate.score;
        let right_key = right.bank as f64 * 100.0 + right.candidate.score;
        right_key
            .total_cmp(&left_key)
            .then_with(|| {
                left.candidate
                    .parent_index
                    .cmp(&right.candidate.parent_index)
            })
            .then_with(|| left.candidate.token.cmp(&right.candidate.token))
    });
    let mut current_bank = None;
    let mut rank = 0usize;
    for candidate in &mut banked {
        if current_bank == Some(candidate.bank) {
            rank = rank.saturating_add(1);
        } else {
            current_bank = Some(candidate.bank);
            rank = 0;
        }
        candidate.within_bank_rank = rank;
    }
    banked.sort_by_key(|candidate| candidate.within_bank_rank);
    banked.truncate(config.num_beams);
    Ok((
        banked
            .into_iter()
            .map(|candidate| candidate.candidate)
            .collect(),
        completed,
    ))
}

