    pub fn supported_hf_model_types() -> Vec<&'static str> {
        let mut model_types = Self::ALL
            .iter()
            .map(|architecture| architecture.model_type())
            .collect::<Vec<_>>();
        model_types.extend_from_slice(Self::HF_MODEL_TYPE_ALIASES);
        model_types
    }

