    fn bert_family_base_prefix(self) -> Option<&'static str> {
        match self {
            Self::Bert | Self::BigBird | Self::BertGeneration | Self::MegatronBert => Some("bert"),
            Self::Albert => Some("albert"),
            Self::RoCBert => Some("roc_bert"),
            Self::RemBert => Some("rembert"),
            Self::Electra => Some("electra"),
            Self::Ernie => Some("ernie"),
            Self::RoFormer => Some("roformer"),
            Self::Roberta | Self::Camembert | Self::XlmRoberta | Self::XlmRobertaXL => {
                Some("roberta")
            }
            Self::RobertaPreLayerNorm => Some("roberta_prelayernorm"),
            Self::Data2VecText => Some("data2vec_text"),
            Self::JinaEmbeddingsV3 => Some("roberta"),
            Self::Esm => Some("esm"),
            _ => None,
        }
    }

    fn uses_fixed_sinusoidal_positions(self) -> bool {
        matches!(
            self,
            Self::Xglm
                | Self::Ctrl
                | Self::Marian
                | Self::Fsmt
                | Self::Pegasus
                | Self::M2M100
                | Self::PegasusX
        )
    }

    /// BlenderbotSmall is unusual among the BART-layout decoders: it applies
    /// `layernorm_embedding` to token embeddings before adding learned
    /// positions. Other embedding-LayerNorm families normalize the composed
    /// token + position (+ token type) tensor.
    fn embedding_norm_before_positions(self) -> bool {
        self == Self::BlenderbotSmall
    }

    /// BigBird intentionally applies embedding dropout before its embedding
    /// LayerNorm, whereas BERT and the other BERT-layout families normalize
    /// first and drop the normalized result.
    fn embedding_dropout_before_norm(self) -> bool {
        self == Self::BigBird
    }

    /// BigBird's `rescale_embeddings` multiplies only the token embedding
    /// contribution, before token-type and position embeddings are added.
    fn token_scale_before_embedding_composition(self) -> bool {
        self == Self::BigBird
    }

