    /// OLMoE applies its full-projection Q/K RMSNorm before `clip_qkv`.
    /// Other currently supported clipped-QKV families clamp the projection
    /// output directly, before any optional Q/K normalization.
    fn clips_qkv_after_qk_norm(self) -> bool {
        self == Self::Olmoe
    }

    fn rms_norm_weight_offset(self) -> f32 {
        if matches!(
            self,
            Self::Gemma
                | Self::Gemma2
                | Self::Gemma3
                | Self::T5Gemma
                | Self::VaultGemma
                | Self::MiniMaxM3VLText
                | Self::Qwen3Next
                | Self::Qwen35
                | Self::Qwen35Moe
                | Self::Qwen4Exp
        ) {
            1.0
        } else {
            0.0
        }
    }

    fn rms_qk_norm_weight_offset(self) -> f32 {
        if matches!(
            self,
            Self::Gemma3
                | Self::MiniMaxM3VLText
                | Self::Qwen3Next
                | Self::Qwen35
                | Self::Qwen35Moe
                | Self::Qwen4Exp
        ) {
            1.0
        } else {
            0.0
        }
    }

    /// Gemma 4 inherits Gemma3nRMSNorm, whose reference implementation uses
    /// `torch.pow(mean_squared, -0.5)` deliberately instead of `torch.rsqrt`.
    /// Preserve that operation choice for strict FP32 training parity.
    fn uses_pow_rms_norm(self) -> bool {
        self == Self::Gemma4
    }

    /// Current Qwen hybrid RMSNorm implementations explicitly materialize
    /// elementwise products (`x.pow(2)`) before their reductions. Preserve
    /// that non-contracted FP32 order for strict Transformers parity.
    fn uses_unfused_rms_products(self) -> bool {
        matches!(
            self,
            Self::Qwen3Next | Self::Qwen35 | Self::Qwen35Moe | Self::Qwen4Exp
        )
    }

    fn token_embedding_scale(self, hidden_size: usize) -> f32 {
        if matches!(
            self,
            Self::Gemma
                | Self::Gemma2
                | Self::Gemma3
                | Self::Gemma4
                | Self::T5Gemma
                | Self::VaultGemma
                | Self::Ctrl
        ) {
            (hidden_size as f32).sqrt()
        } else {
            1.0
        }
    }

