    /// Parse the dense encoder contract shared by XLM and Flaubert.
    ///
    /// Both models use learned token/position embeddings followed by an
    /// embedding LayerNorm, split Q/K/V attention, post-residual LayerNorms,
    /// and a direct (normally tied) vocabulary projection.  The native graph
    /// implements that common path exactly.  Less common options that change
    /// the graph itself are rejected rather than silently approximated.
    fn from_xlm_family_value(
        value: &serde_json::Value,
        architecture: VulkanTransformerArchitecture,
        family: &str,
        supports_pre_norm_flag: bool,
    ) -> Result<Self> {
        if let Some(model_type) = value.get("model_type").and_then(serde_json::Value::as_str) {
            if model_type != architecture.model_type() {
                bail!(
                    "expected {family} model_type {:?}, got {model_type:?}",
                    architecture.model_type()
                );
            }
        }
        if !value
            .get("is_encoder")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true)
        {
            bail!(
                "{family} is_encoder=false is not supported by Hugging Face's current encoder implementation"
            );
        }
        let causal = value
            .get("causal")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        if value
            .get("asm")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
        {
            bail!(
                "{family} asm=true requires AdaptiveLogSoftmaxWithLoss, which is not implemented by the Vulkan LM head"
            );
        }
        let n_langs = value
            .get("n_langs")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(1) as usize;
        if n_langs == 0 {
            bail!("{family} n_langs must be positive");
        }
        let pre_norm = supports_pre_norm_flag
            && value
                .get("pre_norm")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false);
        if supports_pre_norm_flag {
            let _layerdrop = Self::dropout_probability(
                value
                    .get("layerdrop")
                    .and_then(serde_json::Value::as_f64)
                    .unwrap_or(0.0),
                family,
                "layerdrop",
            )?;
        }

        let usize_field = |primary: &str, alias: &str| -> Result<usize> {
            value
                .get(primary)
                .or_else(|| value.get(alias))
                .and_then(serde_json::Value::as_u64)
                .map(|v| v as usize)
                .with_context(|| {
                    format!("{family} config is missing integer {primary:?}/{alias:?}")
                })
        };
        let hidden_size = usize_field("emb_dim", "hidden_size")?;
        let num_heads = usize_field("n_heads", "num_attention_heads")?;
        if num_heads == 0 || !hidden_size.is_multiple_of(num_heads) {
            bail!(
                "{family} hidden size {hidden_size} must be divisible by positive attention head count {num_heads}"
            );
        }
        let num_layers = usize_field("n_layers", "num_hidden_layers")?;
        let intermediate_size = hidden_size
            .checked_mul(4)
            .with_context(|| format!("{family} intermediate size overflow"))?;
        let dropout = Self::dropout_probability(
            value
                .get("dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            family,
            "dropout",
        )?;
        let attention_dropout = Self::dropout_probability(
            value
                .get("attention_dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            family,
            "attention_dropout",
        )?;
        let activation_function = if value
            .get("gelu_activation")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true)
        {
            "gelu"
        } else {
            "relu"
        }
        .to_owned();
        let config = Self {
            causal_attention: Some(causal),
            architecture,
            vocab_size: usize_field("vocab_size", "n_words")?,
            hidden_size,
            embedding_size: hidden_size,
            num_layers,
            num_heads,
            num_key_value_heads: num_heads,
            head_dim: hidden_size / num_heads,
            intermediate_size,
            max_position_embeddings: usize_field(
                "max_position_embeddings",
                "max_position_embeddings",
            )?,
            layer_norm_eps: value
                .get("layer_norm_eps")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(1.0e-12) as f32,
            layer_norm_elementwise_affine: true,
            activation_function,
            tie_word_embeddings: value
                .get("tie_word_embeddings")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
            rotary_dim: 0,
            rotary_emb_base: 10_000.0,
            rope_scaling: VulkanRopeScaling::default(),
            attention_dropout,
            attention_output_dropout: dropout,
            activation_dropout: 0.0,
            mlp_output_dropout: dropout,
            embedding_dropout: dropout,
            embedding_multiplier: 1.0,
            attention_multiplier: None,
            scale_attn_by_inverse_layer_idx: false,
            alibi_bias_max: default_alibi_bias_max(),
            qkv_clip: None,
            residual_multiplier: 1.0,
            logits_multiplier: 1.0,
            final_logit_softcapping: None,
            attention_logit_softcapping: None,
            parallel_residual: false,
            shared_pre_norm: false,
            residual_connection_post_layernorm: false,
            use_post_norm: supports_pre_norm_flag && !pre_norm,
            remove_final_norm: false,
            moe: None,
            attention_windows: vec![0; num_layers],
            activation_situ_beta: default_situ_beta(),
            activation_situ_linear_beta: None,
            linear_attention_layers: vec![],
        };
        config.validate()?;
        Ok(config)
    }

    fn from_roberta_family_value(
        value: &serde_json::Value,
        architecture: VulkanTransformerArchitecture,
        family: &str,
    ) -> Result<Self> {
        if let Some(model_type) = value.get("model_type").and_then(serde_json::Value::as_str) {
            if model_type != architecture.model_type() {
                bail!(
                    "expected {family} model_type {:?}, got {model_type:?}",
                    architecture.model_type()
                );
            }
        }
        let is_decoder = value
            .get("is_decoder")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        let add_cross_attention = value
            .get("add_cross_attention")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        if add_cross_attention && !is_decoder {
            bail!("{family} add_cross_attention=true requires is_decoder=true");
        }
        let position_embedding_type = value
            .get("position_embedding_type")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("absolute");
        if position_embedding_type != "absolute" {
            bail!(
                "{family} position_embedding_type={position_embedding_type:?} is not supported; the current Vulkan graph implements absolute learned positions"
            );
        }
        let usize_field = |name: &str| -> Result<usize> {
            value
                .get(name)
                .and_then(serde_json::Value::as_u64)
                .map(|v| v as usize)
                .with_context(|| format!("{family} config is missing integer {name:?}"))
        };
        let hidden_size = usize_field("hidden_size")?;
        let num_heads = usize_field("num_attention_heads")?;
        if num_heads == 0 || !hidden_size.is_multiple_of(num_heads) {
            bail!(
                "{family} hidden size {hidden_size} must be divisible by positive attention head count {num_heads}"
            );
        }
        let type_vocab_size = value
            .get("type_vocab_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(2) as usize;
        if type_vocab_size == 0 {
            bail!("{family} type_vocab_size must be positive");
        }
        let vocab_size = usize_field("vocab_size")?;
        let max_position_embeddings = usize_field("max_position_embeddings")?;
        let padding_idx = value
            .get("pad_token_id")
            .and_then(serde_json::Value::as_i64)
            .with_context(|| {
                format!(
                    "{family} pad_token_id must be a non-negative integer because position IDs are derived from padding"
                )
            })?;
        if padding_idx < 0 || padding_idx as usize >= vocab_size {
            bail!("{family} pad_token_id {padding_idx} is outside vocabulary size {vocab_size}");
        }
        if padding_idx as usize >= max_position_embeddings {
            bail!(
                "{family} pad_token_id {padding_idx} is outside position embedding table size {max_position_embeddings}"
            );
        }
        let num_layers = usize_field("num_hidden_layers")?;
        let hidden_dropout = Self::dropout_probability(
            value
                .get("hidden_dropout_prob")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            family,
            "hidden_dropout_prob",
        )?;
        let attention_dropout = Self::dropout_probability(
            value
                .get("attention_probs_dropout_prob")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            family,
            "attention_probs_dropout_prob",
        )?;
        let config = Self {
            causal_attention: Some(is_decoder),
            architecture,
            vocab_size,
            hidden_size,
            embedding_size: hidden_size,
            num_layers,
            num_heads,
            num_key_value_heads: num_heads,
            head_dim: hidden_size / num_heads,
            intermediate_size: usize_field("intermediate_size")?,
            max_position_embeddings,
            layer_norm_eps: value
                .get("layer_norm_eps")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(1.0e-12) as f32,
            layer_norm_elementwise_affine: true,
            activation_function: value
                .get("hidden_act")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("gelu")
                .to_owned(),
            tie_word_embeddings: value
                .get("tie_word_embeddings")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
            rotary_dim: 0,
            rotary_emb_base: 10_000.0,
            rope_scaling: VulkanRopeScaling::default(),
            attention_dropout,
            attention_output_dropout: hidden_dropout,
            activation_dropout: 0.0,
            mlp_output_dropout: hidden_dropout,
            embedding_dropout: hidden_dropout,
            embedding_multiplier: 1.0,
            attention_multiplier: None,
            scale_attn_by_inverse_layer_idx: false,
            alibi_bias_max: default_alibi_bias_max(),
            qkv_clip: None,
            residual_multiplier: 1.0,
            logits_multiplier: 1.0,
            final_logit_softcapping: None,
            attention_logit_softcapping: None,
            parallel_residual: false,
            shared_pre_norm: false,
            residual_connection_post_layernorm: false,
            use_post_norm: false,
            remove_final_norm: false,
            moe: None,
            attention_windows: vec![0; num_layers],
            activation_situ_beta: default_situ_beta(),
            activation_situ_linear_beta: None,
            linear_attention_layers: vec![],
        };
        config.validate()?;
        Ok(config)
    }

