    fn switch_sparse_layer_mask(num_layers: usize, num_sparse_layers: usize) -> Vec<bool> {
        // Mirror SwitchTransformersConfig.__post_init__ +
        // SwitchTransformersStack.__init__ exactly. In particular, current HF
        // computes a zero sparse step when num_sparse_layers > num_layers and
        // treats that as an all-dense stack.
        let sparse_step = if num_sparse_layers > 0 {
            num_layers / num_sparse_layers
        } else {
            num_layers
        };
        (0..num_layers)
            .map(|index| sparse_step > 0 && (sparse_step == 1 || index % sparse_step == 1))
            .collect()
    }

    fn from_switch_transformers_value(value: &serde_json::Value) -> Result<Self> {
        if let Some(model_type) = value.get("model_type").and_then(serde_json::Value::as_str) {
            if model_type != "switch_transformers" {
                bail!(
                    "expected Switch Transformers model_type \"switch_transformers\", got {model_type:?}"
                );
            }
        }
        let usize_field_or = |name: &str, default: usize| -> Result<usize> {
            match value.get(name) {
                Some(raw) if !raw.is_null() => raw
                    .as_u64()
                    .map(|v| v as usize)
                    .with_context(|| format!("Switch Transformers {name} must be an integer")),
                _ => Ok(default),
            }
        };
        let hidden_size = usize_field_or("d_model", 768)?;
        let num_heads = usize_field_or("num_heads", 12)?;
        let head_dim = usize_field_or("d_kv", 64)?;
        let num_encoder_layers = usize_field_or("num_layers", 12)?;
        let num_layers = usize_field_or("num_decoder_layers", num_encoder_layers)?;
        let intermediate_size = usize_field_or("d_ff", 2048)?;
        let num_experts = usize_field_or("num_experts", 8)?;
        let num_sparse_decoder_layers = usize_field_or("num_sparse_decoder_layers", 3)?;
        let relative_attention_num_buckets = usize_field_or("relative_attention_num_buckets", 32)?;
        let relative_attention_max_distance =
            usize_field_or("relative_attention_max_distance", 128)?;
        if hidden_size == 0
            || num_heads == 0
            || head_dim == 0
            || num_layers == 0
            || intermediate_size == 0
            || num_experts == 0
            || relative_attention_num_buckets < 2
            || !relative_attention_num_buckets.is_multiple_of(2)
            || relative_attention_max_distance == 0
        {
            bail!("Switch Transformers config contains invalid zero/relative-attention geometry");
        }
        let dropout = Self::dropout_probability(
            value
                .get("dropout_rate")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            "Switch Transformers",
            "dropout_rate",
        )?;
        let router_jitter_noise = value
            .get("router_jitter_noise")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(0.01) as f32;
        if !router_jitter_noise.is_finite() || router_jitter_noise < 0.0 {
            bail!("Switch Transformers router_jitter_noise must be finite and non-negative");
        }
        let router_aux_loss_coef = value
            .get("router_aux_loss_coef")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(0.001) as f32;
        let activation_function = value
            .get("dense_act_fn")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("relu")
            .to_owned();
        let tie_word_embeddings = value
            .get("tie_word_embeddings")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true);
        let sparse_layer_mask =
            Self::switch_sparse_layer_mask(num_layers, num_sparse_decoder_layers);
        let config = Self {
            causal_attention: Some(true),
            architecture: VulkanTransformerArchitecture::SwitchTransformers,
            vocab_size: usize_field_or("vocab_size", 32_128)?,
            hidden_size,
            embedding_size: hidden_size,
            num_layers,
            num_heads,
            num_key_value_heads: num_heads,
            head_dim,
            intermediate_size,
            max_position_embeddings: relative_attention_max_distance,
            layer_norm_eps: value
                .get("layer_norm_epsilon")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(1.0e-6) as f32,
            layer_norm_elementwise_affine: true,
            activation_function,
            tie_word_embeddings,
            rotary_dim: 0,
            rotary_emb_base: 10_000.0,
            rope_scaling: VulkanRopeScaling::default(),
            attention_dropout: dropout,
            attention_output_dropout: dropout,
            activation_dropout: dropout,
            mlp_output_dropout: dropout,
            embedding_dropout: dropout,
            embedding_multiplier: 1.0,
            // Switch attention, like T5, intentionally omits the usual
            // 1/sqrt(d_kv) attention-score multiplier.
            attention_multiplier: Some(1.0),
            scale_attn_by_inverse_layer_idx: false,
            alibi_bias_max: default_alibi_bias_max(),
            qkv_clip: None,
            residual_multiplier: 1.0,
            logits_multiplier: if tie_word_embeddings {
                1.0 / (hidden_size as f32).sqrt()
            } else {
                1.0
            },
            final_logit_softcapping: None,
            attention_logit_softcapping: None,
            parallel_residual: false,
            shared_pre_norm: false,
            residual_connection_post_layernorm: false,
            use_post_norm: false,
            remove_final_norm: false,
            moe: Some(VulkanTransformerMoeConfig {
                num_experts,
                top_k: 1,
                sparse_layer_mask,
                dense_intermediate_size: intermediate_size,
                shared_expert_intermediate_size: 0,
                use_rms_norm: true,
                shared_expert_combination_scale: 1.0,
                // Switch multiplies the selected expert by its top-1 softmax
                // probability; top-1 is deliberately not renormalized to 1.
                normalize_top_k: false,
                router_score_function: VulkanMoeRouterScoreFunction::Softmax,
                router_logit_softcapping: 0.0,
                routed_scaling_factor: 1.0,
                router_group_count: 1,
                router_topk_group: 1,
                router_aux_loss_coef,
                input_jitter_noise: 0.0,
                router_jitter_noise,
            }),
            attention_windows: vec![0; num_layers],
            activation_situ_beta: default_situ_beta(),
            activation_situ_linear_beta: None,
            linear_attention_layers: vec![],
        };
        config.validate()?;
        Ok(config)
    }

    fn from_t5_family_value(
        value: &serde_json::Value,
        architecture: VulkanTransformerArchitecture,
        expected_model_type: &str,
        family_name: &str,
    ) -> Result<Self> {
        if let Some(model_type) = value.get("model_type").and_then(serde_json::Value::as_str) {
            if model_type != expected_model_type {
                bail!(
                    "expected {family_name} model_type {expected_model_type:?}, got {model_type:?}"
                );
            }
        }
        let usize_field = |name: &str| -> Result<usize> {
            value
                .get(name)
                .and_then(serde_json::Value::as_u64)
                .map(|v| v as usize)
                .with_context(|| format!("{family_name} config is missing integer {name:?}"))
        };
        let hidden_size = usize_field("d_model")?;
        let num_heads = usize_field("num_heads")?;
        let head_dim = usize_field("d_kv")?;
        let num_layers = value
            .get("num_decoder_layers")
            .filter(|v| !v.is_null())
            .and_then(serde_json::Value::as_u64)
            .map(|v| v as usize)
            .unwrap_or(usize_field("num_layers")?);
        let relative_attention_num_buckets = value
            .get("relative_attention_num_buckets")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(32) as usize;
        let relative_attention_max_distance = value
            .get("relative_attention_max_distance")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(128) as usize;
        if num_heads == 0
            || head_dim == 0
            || relative_attention_num_buckets < 2
            || !relative_attention_num_buckets.is_multiple_of(2)
            || relative_attention_max_distance == 0
        {
            bail!(
                "{family_name} requires positive num_heads/d_kv/max relative distance and an even relative_attention_num_buckets >= 2"
            );
        }
        let dropout = Self::dropout_probability(
            value
                .get("dropout_rate")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            family_name,
            "dropout_rate",
        )?;
        let feed_forward_proj = value
            .get("feed_forward_proj")
            .and_then(serde_json::Value::as_str)
            .unwrap_or(
                if matches!(
                    architecture,
                    VulkanTransformerArchitecture::MT5 | VulkanTransformerArchitecture::UMT5
                ) {
                    "gated-gelu"
                } else {
                    "relu"
                },
            );
        let (gated, mut dense_act_fn) = match feed_forward_proj.split_once('-') {
            Some(("gated", activation)) if !activation.is_empty() && !activation.contains('-') => {
                (true, activation)
            }
            None => (false, feed_forward_proj),
            _ => bail!(
                "invalid {family_name} feed_forward_proj {feed_forward_proj:?}; expected ACT or gated-ACT"
            ),
        };
        // Current Transformers preserves the historical T5-family naming rule:
        // gated-gelu means the tanh GELU approximation (`gelu_new`). MT5 uses
        // this gated form by default.
        if feed_forward_proj == "gated-gelu" {
            dense_act_fn = "gelu_new";
        }
        let activation_function = if gated {
            format!("gated-{dense_act_fn}")
        } else {
            dense_act_fn.to_owned()
        };
        let raw_tie_word_embeddings = value
            .get("tie_word_embeddings")
            .and_then(serde_json::Value::as_bool);
        let scale_decoder_outputs = if matches!(
            architecture,
            VulkanTransformerArchitecture::MT5 | VulkanTransformerArchitecture::UMT5
        ) {
            // Current MT5/UMT5 always tie and scale, even though official legacy
            // MT5 configs can serialize tie_word_embeddings=false.
            true
        } else {
            // T5 uses the serialized legacy flag to distinguish original T5
            // from T5 v1.1 decoder-output scaling.
            raw_tie_word_embeddings != Some(false)
        };
        let config = Self {
            causal_attention: Some(true),
            architecture,
            vocab_size: usize_field("vocab_size")?,
            hidden_size,
            embedding_size: hidden_size,
            num_layers,
            num_heads,
            num_key_value_heads: num_heads,
            head_dim,
            intermediate_size: usize_field("d_ff")?,
            // T5/MT5 have no absolute position table and relative buckets generalize
            // beyond max_distance. Keep a positive metadata value while the
            // graph's sequence-capacity check explicitly treats this family as unbounded.
            max_position_embeddings: relative_attention_max_distance,
            layer_norm_eps: value
                .get("layer_norm_epsilon")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(1.0e-6) as f32,
            layer_norm_elementwise_affine: true,
            activation_function,
            // T5 and MT5 always share the token table with the LM head in current HF.
            // T5's serialized legacy flag controls only decoder-output scale.
            tie_word_embeddings: true,
            rotary_dim: 0,
            rotary_emb_base: 10_000.0,
            rope_scaling: VulkanRopeScaling::default(),
            attention_dropout: dropout,
            attention_output_dropout: dropout,
            activation_dropout: dropout,
            mlp_output_dropout: dropout,
            embedding_dropout: dropout,
            embedding_multiplier: 1.0,
            // T5-family attention intentionally does not apply 1/sqrt(d_kv).
            attention_multiplier: Some(1.0),
            scale_attn_by_inverse_layer_idx: false,
            alibi_bias_max: default_alibi_bias_max(),
            qkv_clip: None,
            residual_multiplier: 1.0,
            logits_multiplier: if scale_decoder_outputs {
                1.0 / (hidden_size as f32).sqrt()
            } else {
                1.0
            },
            final_logit_softcapping: None,
            attention_logit_softcapping: None,
            parallel_residual: false,
            shared_pre_norm: false,
            residual_connection_post_layernorm: false,
            use_post_norm: false,
            remove_final_norm: false,
            moe: None,
            attention_windows: vec![0; num_layers],
            activation_situ_beta: default_situ_beta(),
            activation_situ_linear_beta: None,
            linear_attention_layers: vec![],
        };
        config.validate()?;
        Ok(config)
    }

