    fn from_fsmt_value(value: &serde_json::Value) -> Result<Self> {
        if let Some(model_type) = value.get("model_type").and_then(serde_json::Value::as_str) {
            if model_type != "fsmt" {
                bail!("expected FSMT model_type, got {model_type:?}");
            }
        }
        let usize_field = |name: &str| -> Result<usize> {
            value
                .get(name)
                .and_then(serde_json::Value::as_u64)
                .map(|v| v as usize)
                .with_context(|| format!("FSMT config is missing integer {name:?}"))
        };
        let hidden_size = usize_field("d_model")?;
        let num_heads = usize_field("decoder_attention_heads")?;
        if num_heads == 0 || !hidden_size.is_multiple_of(num_heads) {
            bail!("FSMT d_model must be divisible by decoder_attention_heads");
        }
        let encoder_heads = usize_field("encoder_attention_heads")?;
        if encoder_heads == 0 || !hidden_size.is_multiple_of(encoder_heads) {
            bail!("FSMT d_model must be divisible by encoder_attention_heads");
        }
        let src_vocab_size = usize_field("src_vocab_size")?;
        if src_vocab_size == 0 {
            bail!("FSMT src_vocab_size must be positive");
        }
        let vocab_size = usize_field("tgt_vocab_size")?;
        if vocab_size == 0 {
            bail!("FSMT tgt_vocab_size must be positive");
        }
        if usize_field("encoder_layers")? == 0 || usize_field("encoder_ffn_dim")? == 0 {
            bail!("FSMT encoder_layers and encoder_ffn_dim must be positive");
        }
        let num_layers = usize_field("decoder_layers")?;
        let intermediate_size = usize_field("decoder_ffn_dim")?;
        if num_layers == 0 || intermediate_size == 0 {
            bail!("FSMT decoder_layers and decoder_ffn_dim must be positive");
        }
        let _encoder_layerdrop = Self::dropout_probability(
            value
                .get("encoder_layerdrop")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "FSMT",
            "encoder_layerdrop",
        )?;
        let _decoder_layerdrop = Self::dropout_probability(
            value
                .get("decoder_layerdrop")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "FSMT",
            "decoder_layerdrop",
        )?;
        let dropout = Self::dropout_probability(
            value
                .get("dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            "FSMT",
            "dropout",
        )?;
        let attention_dropout = Self::dropout_probability(
            value
                .get("attention_dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "FSMT",
            "attention_dropout",
        )?;
        let activation_dropout = Self::dropout_probability(
            value
                .get("activation_dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "FSMT",
            "activation_dropout",
        )?;
        let max_position_embeddings = usize_field("max_position_embeddings")?;
        let pad_token_id = value
            .get("pad_token_id")
            .and_then(serde_json::Value::as_i64)
            .unwrap_or(1);
        if pad_token_id < 0 || pad_token_id as usize >= vocab_size {
            bail!(
                "FSMT pad_token_id {pad_token_id} is outside target vocabulary size {vocab_size}"
            );
        }
        let scale_embedding = value
            .get("scale_embedding")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true);
        let config = Self {
            causal_attention: None,
            architecture: VulkanTransformerArchitecture::Fsmt,
            vocab_size,
            hidden_size,
            embedding_size: hidden_size,
            num_layers,
            num_heads,
            num_key_value_heads: num_heads,
            head_dim: hidden_size / num_heads,
            intermediate_size,
            max_position_embeddings,
            // FSMT constructs torch.nn.LayerNorm without overriding its 1e-5 default.
            layer_norm_eps: 1.0e-5,
            layer_norm_elementwise_affine: true,
            activation_function: value
                .get("activation_function")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("relu")
                .to_owned(),
            tie_word_embeddings: value
                .get("tie_word_embeddings")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            rotary_dim: 0,
            rotary_emb_base: 10_000.0,
            rope_scaling: VulkanRopeScaling::default(),
            attention_dropout,
            attention_output_dropout: dropout,
            activation_dropout,
            mlp_output_dropout: dropout,
            embedding_dropout: dropout,
            embedding_multiplier: if scale_embedding {
                (hidden_size as f32).sqrt()
            } else {
                1.0
            },
            attention_multiplier: None,
            scale_attn_by_inverse_layer_idx: false,
            alibi_bias_max: default_alibi_bias_max(),
            qkv_clip: None,
            residual_multiplier: 1.0,
            logits_multiplier: 1.0,
            final_logit_softcapping: None,
            attention_logit_softcapping: None,
            parallel_residual: false,
            shared_pre_norm: false,
            residual_connection_post_layernorm: false,
            use_post_norm: false,
            remove_final_norm: false,
            moe: None,
            attention_windows: vec![0; num_layers],
            activation_situ_beta: default_situ_beta(),
            activation_situ_linear_beta: None,
            linear_attention_layers: vec![],
        };
        config.validate()?;
        Ok(config)
    }

