    fn from_stablelm_value(value: &serde_json::Value) -> Result<Self> {
        let usize_field = |name: &str| -> Result<usize> {
            value
                .get(name)
                .and_then(serde_json::Value::as_u64)
                .map(|v| v as usize)
                .with_context(|| format!("StableLM config is missing integer {name:?}"))
        };
        let hidden_size = usize_field("hidden_size")?;
        let num_heads = usize_field("num_attention_heads")?;
        if num_heads == 0 || !hidden_size.is_multiple_of(num_heads) {
            bail!("StableLM hidden_size must be divisible by num_attention_heads");
        }
        let head_dim = hidden_size / num_heads;
        let num_key_value_heads = value
            .get("num_key_value_heads")
            .and_then(serde_json::Value::as_u64)
            .map(|v| v as usize)
            .unwrap_or(num_heads);
        if num_key_value_heads == 0 || !num_heads.is_multiple_of(num_key_value_heads) {
            bail!(
                "StableLM num_attention_heads={num_heads} must be divisible by num_key_value_heads={num_key_value_heads}"
            );
        }
        let use_parallel_residual = value
            .get("use_parallel_residual")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        let hidden_dropout = Self::dropout_probability(
            value
                .get("hidden_dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "StableLM",
            "hidden_dropout",
        )?;
        let attention_dropout = Self::dropout_probability(
            value
                .get("attention_dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "StableLM",
            "attention_dropout",
        )?;
        let partial_rotary_factor =
            Self::partial_rotary_factor(value, "partial_rotary_factor", 0.25);
        if !partial_rotary_factor.is_finite()
            || partial_rotary_factor <= 0.0
            || partial_rotary_factor > 1.0
        {
            bail!("StableLM partial_rotary_factor must be finite and in (0, 1]");
        }
        let rotary_dim = (head_dim as f64 * partial_rotary_factor) as usize;
        let activation = value
            .get("hidden_act")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("silu");
        let num_layers = usize_field("num_hidden_layers")?;
        let mut config = Self {
            causal_attention: None,
            architecture: VulkanTransformerArchitecture::StableLm,
            vocab_size: usize_field("vocab_size")?,
            hidden_size,
            embedding_size: hidden_size,
            num_layers,
            num_heads,
            num_key_value_heads,
            head_dim,
            intermediate_size: usize_field("intermediate_size")?,
            max_position_embeddings: usize_field("max_position_embeddings")?,
            layer_norm_eps: value
                .get("layer_norm_eps")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(1.0e-5) as f32,
            layer_norm_elementwise_affine: true,
            activation_function: activation.to_owned(),
            tie_word_embeddings: value
                .get("tie_word_embeddings")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            rotary_dim,
            rotary_emb_base: Self::rope_theta(value, 10_000.0),
            rope_scaling: VulkanRopeScaling::default(),
            attention_dropout,
            attention_output_dropout: 0.0,
            activation_dropout: 0.0,
            mlp_output_dropout: hidden_dropout,
            embedding_dropout: 0.0,
            embedding_multiplier: 1.0,
            attention_multiplier: None,
            scale_attn_by_inverse_layer_idx: false,
            alibi_bias_max: default_alibi_bias_max(),
            qkv_clip: None,
            residual_multiplier: 1.0,
            logits_multiplier: 1.0,
            final_logit_softcapping: None,
            attention_logit_softcapping: None,
            parallel_residual: use_parallel_residual,
            shared_pre_norm: use_parallel_residual,
            residual_connection_post_layernorm: false,
            use_post_norm: false,
            remove_final_norm: false,
            moe: None,
            attention_windows: vec![0; num_layers],
            activation_situ_beta: default_situ_beta(),
            activation_situ_linear_beta: None,
            linear_attention_layers: vec![],
        };
        config.rope_scaling =
            Self::parse_rope_scaling(value, "StableLM", config.max_position_embeddings)?;
        config.validate()?;
        Ok(config)
    }

    fn from_llama_value(value: &serde_json::Value) -> Result<Self> {
        Self::from_llama_family_value(value, VulkanTransformerArchitecture::Llama, "Llama", 0)
    }

    /// Resolve the physical Mllama decoder layers that execute during a
    /// text-only forward pass. Hugging Face completely skips configured
    /// cross-attention layers when no vision/cross-attention states are
    /// supplied; those layers do not run their MLP either. The native Vulkan
    /// text graph therefore contains only the self-attention layers while the
    /// package I/O path preserves the skipped tensors verbatim.
    fn mllama_text_self_attention_layers(value: &serde_json::Value) -> Result<Vec<usize>> {
        let num_layers = value
            .get("num_hidden_layers")
            .and_then(serde_json::Value::as_u64)
            .context("Mllama text config is missing integer \"num_hidden_layers\"")?
            as usize;
        if num_layers == 0 {
            bail!("Mllama text num_hidden_layers must be positive");
        }
        let default_cross_attention_layers = serde_json::json!([3, 8, 13, 18, 23, 28, 33, 38]);
        let configured = value
            .get("cross_attention_layers")
            .filter(|value| !value.is_null())
            .unwrap_or(&default_cross_attention_layers)
            .as_array()
            .context("Mllama text cross_attention_layers must be an array or null")?;
        let mut cross_attention = vec![false; num_layers];
        for (entry_index, entry) in configured.iter().enumerate() {
            let layer = entry.as_i64().with_context(|| {
                format!("Mllama text cross_attention_layers[{entry_index}] must be an integer")
            })?;
            // Transformers uses Python `layer_idx in cross_attention_layers`.
            // Negative or out-of-range entries therefore simply never match a
            // real decoder index; mirror that behavior instead of rejecting a
            // config that Python accepts.
            if layer >= 0 && (layer as usize) < num_layers {
                cross_attention[layer as usize] = true;
            }
        }
        let self_attention_layers = cross_attention
            .into_iter()
            .enumerate()
            .filter_map(|(index, is_cross_attention)| (!is_cross_attention).then_some(index))
            .collect::<Vec<_>>();
        if self_attention_layers.is_empty() {
            bail!(
                "Mllama text-only execution requires at least one self-attention layer; all {num_layers} configured layers are cross-attention"
            );
        }
        Ok(self_attention_layers)
    }

    fn from_mllama_text_value(value: &serde_json::Value) -> Result<Self> {
        let self_attention_layers = Self::mllama_text_self_attention_layers(value)?;
        let mut normalized = value.clone();
        normalized["num_hidden_layers"] = serde_json::json!(self_attention_layers.len());
        // Reuse the exact Llama decoder kernels for Mllama's self-attention
        // blocks. The cross-attention blocks are absent from text-only HF
        // execution and are preserved untouched during package export.
        normalized["model_type"] = serde_json::json!("llama");
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Llama,
            "Mllama text-only",
            0,
        )?;
        config.rotary_emb_base = Self::rope_theta(value, 500_000.0);
        config.rope_scaling =
            Self::parse_rope_scaling(value, "Mllama text-only", config.max_position_embeddings)?;
        config.attention_dropout = Self::dropout_probability(
            value
                .get("dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "Mllama text-only",
            "dropout",
        )?;
        config.validate()?;
        Ok(config)
    }

    fn from_llama4_text_value(value: &serde_json::Value) -> Result<Self> {
        let num_layers = value
            .get("num_hidden_layers")
            .and_then(serde_json::Value::as_u64)
            .context("Llama 4 text config is missing integer \"num_hidden_layers\"")?
            as usize;
        if num_layers == 0 {
            bail!("Llama 4 text num_hidden_layers must be positive");
        }

        let num_experts = value
            .get("num_local_experts")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(16) as usize;
        let top_k = value
            .get("num_experts_per_tok")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(1) as usize;
        let routed_intermediate_size = value
            .get("intermediate_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(8192) as usize;
        let dense_intermediate_size = value
            .get("intermediate_size_mlp")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(16_384) as usize;
        if routed_intermediate_size == 0 || dense_intermediate_size == 0 {
            bail!("Llama 4 text intermediate sizes must be positive");
        }

        let sparse_layer_mask = if let Some(moe_layers) =
            value.get("moe_layers").filter(|value| !value.is_null())
        {
            let moe_layers = moe_layers
                .as_array()
                .context("Llama 4 text moe_layers must be an array or null")?;
            let mut mask = vec![false; num_layers];
            for (entry_index, layer) in moe_layers.iter().enumerate() {
                let layer = layer.as_u64().with_context(|| {
                    format!("Llama 4 text moe_layers[{entry_index}] must be a non-negative integer")
                })? as usize;
                if layer >= num_layers {
                    bail!(
                        "Llama 4 text moe_layers[{entry_index}]={layer} is outside num_hidden_layers={num_layers}"
                    );
                }
                mask[layer] = true;
            }
            mask
        } else {
            let step = value
                .get("interleave_moe_layer_step")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(1) as usize;
            if step == 0 {
                bail!("Llama 4 text interleave_moe_layer_step must be positive");
            }
            (0..num_layers)
                .map(|layer| (layer + 1).is_multiple_of(step))
                .collect()
        };

        let rotary_layers = Self::llama4_rotary_layers(value, num_layers)?;
        let chunk_size = value
            .get("attention_chunk_size")
            .filter(|value| !value.is_null())
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(8192) as usize;
        if chunk_size == 0 {
            bail!("Llama 4 text attention_chunk_size must be positive");
        }
        let attention_windows = if let Some(layer_types) =
            value.get("layer_types").filter(|value| !value.is_null())
        {
            let layer_types = layer_types
                .as_array()
                .context("Llama 4 text layer_types must be an array or null")?;
            if layer_types.len() != num_layers {
                bail!(
                    "Llama 4 text layer_types length {} does not match num_hidden_layers {num_layers}",
                    layer_types.len()
                );
            }
            layer_types
                .iter()
                .enumerate()
                .map(|(index, layer_type)| match layer_type.as_str() {
                    Some("full_attention") => Ok(0),
                    Some("chunked_attention") => Ok(chunk_size),
                    Some(other) => bail!(
                        "unsupported Llama 4 text layer_types[{index}]={other:?}; expected \"full_attention\" or \"chunked_attention\""
                    ),
                    None => bail!("Llama 4 text layer_types[{index}] must be a string"),
                })
                .collect::<Result<Vec<_>>>()?
        } else {
            rotary_layers
                .iter()
                .map(|uses_rope| if *uses_rope { chunk_size } else { 0 })
                .collect()
        };

        // Parse the shared Llama geometry first because the common parser
        // validates before returning and Llama4's MoE contract is attached
        // below.
        let mut config = Self::from_llama_family_value(
            value,
            VulkanTransformerArchitecture::Llama,
            "Llama 4 text",
            0,
        )?;
        config.architecture = VulkanTransformerArchitecture::Llama4Text;
        config.rotary_emb_base = Self::rope_theta(value, 500_000.0);
        config.rope_scaling =
            Self::parse_rope_scaling(value, "Llama 4 text", config.max_position_embeddings)?;
        config.attention_windows = attention_windows;
        config.moe = Some(VulkanTransformerMoeConfig {
            num_experts,
            top_k,
            sparse_layer_mask,
            dense_intermediate_size,
            shared_expert_intermediate_size: routed_intermediate_size,
            use_rms_norm: true,
            shared_expert_combination_scale: 1.0,
            normalize_top_k: false,
            router_score_function: VulkanMoeRouterScoreFunction::SigmoidGrouped,
            router_logit_softcapping: 0.0,
            routed_scaling_factor: 1.0,
            router_group_count: 1,
            router_topk_group: 1,
            router_aux_loss_coef: value
                .get("router_aux_loss_coef")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.001) as f32,
            input_jitter_noise: 0.0,
            router_jitter_noise: value
                .get("router_jitter_noise")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0) as f32,
        });
        config.validate()?;
        Ok(config)
    }

    fn llama4_rotary_layers(value: &serde_json::Value, num_layers: usize) -> Result<Vec<bool>> {
        if let Some(no_rope_layers) = value.get("no_rope_layers").filter(|value| !value.is_null()) {
            let no_rope_layers = no_rope_layers
                .as_array()
                .context("Llama 4 text no_rope_layers must be an array of 0/1 integers or null")?;
            if no_rope_layers.len() < num_layers {
                bail!(
                    "Llama 4 text no_rope_layers has {} entries for {} layers",
                    no_rope_layers.len(),
                    num_layers
                );
            }
            return no_rope_layers[..num_layers]
                .iter()
                .enumerate()
                .map(|(index, value)| match value.as_u64() {
                    Some(0) => Ok(false),
                    Some(1) => Ok(true),
                    _ => bail!(
                        "Llama 4 text no_rope_layers[{index}] must be integer 0 (NoPE) or 1 (RoPE)"
                    ),
                })
                .collect();
        }

        let interval = value
            .get("no_rope_layer_interval")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(4) as usize;
        if interval == 0 {
            bail!("Llama 4 text no_rope_layer_interval must be positive");
        }
        Ok((0..num_layers)
            .map(|layer_index| !(layer_index + 1).is_multiple_of(interval))
            .collect())
    }

    fn from_open_llama_value(value: &serde_json::Value) -> Result<Self> {
        if let Some(model_type) = value.get("model_type").and_then(serde_json::Value::as_str) {
            if model_type != "open-llama" {
                bail!("expected OpenLLaMA model_type, got {model_type:?}");
            }
        }
        let mut config = Self::from_llama_family_value(
            value,
            VulkanTransformerArchitecture::OpenLlama,
            "OpenLLaMA",
            0,
        )?;
        config.attention_dropout = Self::dropout_probability(
            value
                .get("attention_dropout_prob")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            "OpenLLaMA",
            "attention_dropout_prob",
        )?;
        config.mlp_output_dropout = Self::dropout_probability(
            value
                .get("hidden_dropout_prob")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            "OpenLLaMA",
            "hidden_dropout_prob",
        )?;
        // OpenLLaMA's CausalLM head is controlled by this historical flag,
        // independently of PretrainedConfig.tie_word_embeddings.
        config.tie_word_embeddings = value
            .get("shared_input_output_embedding")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true);
        config.validate()?;
        Ok(config)
    }

    fn from_bitnet_value(value: &serde_json::Value) -> Result<Self> {
        let mut config = Self::from_llama_family_value(
            value,
            VulkanTransformerArchitecture::BitNet,
            "BitNet",
            0,
        )?;
        // BitNet intentionally differs from Llama's defaults even though its
        // outer decoder topology is Llama-compatible.
        config.activation_function = value
            .get("hidden_activation")
            .or_else(|| value.get("hidden_act"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or("relu2")
            .to_owned();
        config.layer_norm_eps = value
            .get("rms_norm_eps")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(1.0e-5) as f32;
        config.rotary_emb_base = Self::rope_theta(value, 500_000.0);
        if config.query_hidden_size() != config.hidden_size {
            bail!(
                "BitNet requires num_attention_heads * head_dim == hidden_size because attn_sub_norm is hidden-sized"
            );
        }
        config.validate()?;
        Ok(config)
    }

    fn from_eurobert_value(value: &serde_json::Value) -> Result<Self> {
        Self::from_llama_family_value(
            value,
            VulkanTransformerArchitecture::EuroBert,
            "EuroBERT",
            0,
        )
    }

    fn from_esm_value(value: &serde_json::Value) -> Result<Self> {
        if let Some(model_type) = value.get("model_type").and_then(serde_json::Value::as_str) {
            if model_type != "esm" {
                bail!("expected ESM model_type, got {model_type:?}");
            }
        }
        if value
            .get("is_folding_model")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
        {
            bail!(
                "ESMFold checkpoints are not the plain ESM Transformer graph; native Vulkan ESM currently loads the ESM language-model stack"
            );
        }
        let usize_field = |name: &str| -> Result<usize> {
            value
                .get(name)
                .and_then(serde_json::Value::as_u64)
                .map(|value| value as usize)
                .with_context(|| format!("ESM config is missing integer {name:?}"))
        };
        let hidden_size = usize_field("hidden_size")?;
        let num_heads = usize_field("num_attention_heads")?;
        if num_heads == 0 || !hidden_size.is_multiple_of(num_heads) {
            bail!(
                "ESM hidden_size={hidden_size} must be divisible by positive num_attention_heads={num_heads}"
            );
        }
        let head_dim = hidden_size / num_heads;
        if !head_dim.is_multiple_of(2) {
            bail!("ESM attention head dimension must be even for rotary compatibility; got {head_dim}");
        }
        let num_layers = usize_field("num_hidden_layers")?;
        let max_position_embeddings = usize_field("max_position_embeddings")?;
        let position_embedding_type = value
            .get("position_embedding_type")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("absolute");
        let rotary_dim = match position_embedding_type {
            "absolute" => 0,
            "rotary" => head_dim,
            other => bail!(
                "unsupported ESM position_embedding_type={other:?}; expected \"absolute\" or \"rotary\""
            ),
        };
        let is_decoder = value
            .get("is_decoder")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        let add_cross_attention = value
            .get("add_cross_attention")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        if add_cross_attention && !is_decoder {
            bail!("ESM add_cross_attention=true requires is_decoder=true");
        }
        let hidden_dropout = Self::dropout_probability(
            value
                .get("hidden_dropout_prob")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            "ESM",
            "hidden_dropout_prob",
        )?;
        let attention_dropout = Self::dropout_probability(
            value
                .get("attention_probs_dropout_prob")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.1),
            "ESM",
            "attention_probs_dropout_prob",
        )?;
        let config = Self {
            architecture: VulkanTransformerArchitecture::Esm,
            causal_attention: Some(is_decoder),
            vocab_size: usize_field("vocab_size")?,
            hidden_size,
            embedding_size: hidden_size,
            num_layers,
            num_heads,
            num_key_value_heads: num_heads,
            head_dim,
            intermediate_size: usize_field("intermediate_size")?,
            max_position_embeddings,
            layer_norm_eps: value
                .get("layer_norm_eps")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(1.0e-12) as f32,
            layer_norm_elementwise_affine: true,
            activation_function: "gelu".to_owned(),
            tie_word_embeddings: value
                .get("tie_word_embeddings")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
            rotary_dim,
            rotary_emb_base: Self::rope_theta(value, 10_000.0),
            rope_scaling: VulkanRopeScaling::default(),
            attention_dropout,
            attention_output_dropout: hidden_dropout,
            mlp_output_dropout: hidden_dropout,
            activation_dropout: 0.0,
            // EsmEmbeddings owns a Dropout module for historical compatibility,
            // but current HF intentionally does not call it in forward().
            embedding_dropout: 0.0,
            embedding_multiplier: 1.0,
            attention_multiplier: None,
            scale_attn_by_inverse_layer_idx: false,
            alibi_bias_max: default_alibi_bias_max(),
            qkv_clip: None,
            residual_multiplier: 1.0,
            logits_multiplier: 1.0,
            final_logit_softcapping: None,
            attention_logit_softcapping: None,
            parallel_residual: false,
            shared_pre_norm: false,
            residual_connection_post_layernorm: false,
            use_post_norm: false,
            remove_final_norm: false,
            moe: None,
            attention_windows: vec![0; num_layers],
            activation_situ_beta: default_situ_beta(),
            activation_situ_linear_beta: None,
            linear_attention_layers: vec![],
        };
        config.validate()?;
        Ok(config)
    }

    fn from_esmc_value(value: &serde_json::Value) -> Result<Self> {
        let mut config =
            Self::from_llama_family_value(value, VulkanTransformerArchitecture::Esmc, "ESMC", 0)?;
        if config.num_key_value_heads != config.num_heads {
            bail!(
                "ESMC requires num_key_value_heads == num_attention_heads; got {} and {}",
                config.num_key_value_heads,
                config.num_heads
            );
        }
        // ESMC replaces Llama RMSNorm with ordinary LayerNorm throughout,
        // including full-projection Q/K normalization. PyTorch LayerNorm's
        // default epsilon is 1e-5 and ESMC does not expose rms_norm_eps.
        config.layer_norm_eps = value
            .get("layer_norm_eps")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(1.0e-5) as f32;
        // Each attention/MLP branch is divided by sqrt(num_layers / 36).
        config.residual_multiplier = (36.0 / config.num_layers as f32).sqrt();
        config.causal_attention = Some(false);
        config.validate()?;
        Ok(config)
    }

    fn modernbert_layer_types(value: &serde_json::Value, num_layers: usize) -> Result<Vec<String>> {
        if let Some(layer_types) = value.get("layer_types").filter(|value| !value.is_null()) {
            let layer_types = layer_types
                .as_array()
                .context("ModernBERT layer_types must be an array or null")?;
            if layer_types.len() != num_layers {
                bail!(
                    "ModernBERT layer_types length {} does not match num_hidden_layers {num_layers}",
                    layer_types.len()
                );
            }
            return layer_types
                .iter()
                .enumerate()
                .map(|(index, layer_type)| match layer_type.as_str() {
                    Some("full_attention") => Ok("full_attention".to_owned()),
                    Some("sliding_attention") => Ok("sliding_attention".to_owned()),
                    Some(other) => bail!(
                        "unsupported ModernBERT layer_types[{index}]={other:?}; expected \"full_attention\" or \"sliding_attention\""
                    ),
                    None => bail!("ModernBERT layer_types[{index}] must be a string"),
                })
                .collect();
        }

        // Mirrors ModernBertConfig.__post_init__. Historical Hub configs may
        // retain this compatibility field even though current configs persist
        // the expanded layer_types list.
        let global_every = value
            .get("global_attn_every_n_layers")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(3) as usize;
        if global_every == 0 {
            bail!("ModernBERT global_attn_every_n_layers must be positive");
        }
        Ok((0..num_layers)
            .map(|index| {
                if index.is_multiple_of(global_every) {
                    "full_attention".to_owned()
                } else {
                    "sliding_attention".to_owned()
                }
            })
            .collect())
    }

    fn from_modernbert_value(value: &serde_json::Value) -> Result<Self> {
        let usize_field = |name: &str| -> Result<usize> {
            value
                .get(name)
                .and_then(serde_json::Value::as_u64)
                .map(|v| v as usize)
                .with_context(|| format!("ModernBERT config is missing integer {name:?}"))
        };
        let hidden_size = usize_field("hidden_size")?;
        let num_heads = usize_field("num_attention_heads")?;
        if num_heads == 0 || !hidden_size.is_multiple_of(num_heads) {
            bail!("ModernBERT hidden_size must be divisible by num_attention_heads");
        }
        let num_layers = usize_field("num_hidden_layers")?;
        let local_attention = value
            .get("local_attention")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(128) as usize;
        if local_attention < 2 {
            bail!("ModernBERT local_attention must be at least 2");
        }
        let sliding_window = local_attention / 2;
        let layer_types = Self::modernbert_layer_types(value, num_layers)?;
        let attention_windows = layer_types
            .iter()
            .map(|layer_type| {
                if layer_type == "sliding_attention" {
                    sliding_window
                } else {
                    0
                }
            })
            .collect();
        let attention_dropout = Self::dropout_probability(
            value
                .get("attention_dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "ModernBERT",
            "attention_dropout",
        )?;
        let embedding_dropout = Self::dropout_probability(
            value
                .get("embedding_dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "ModernBERT",
            "embedding_dropout",
        )?;
        let mlp_dropout = Self::dropout_probability(
            value
                .get("mlp_dropout")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.0),
            "ModernBERT",
            "mlp_dropout",
        )?;
        let head_dim = hidden_size / num_heads;
        if !head_dim.is_multiple_of(2) {
            bail!("ModernBERT attention head dimension must be even for RoPE");
        }
        let full_rope = value
            .get("rope_parameters")
            .and_then(serde_json::Value::as_object)
            .and_then(|parameters| parameters.get("full_attention"));
        let rotary_emb_base = full_rope
            .and_then(|parameters| parameters.get("rope_theta"))
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(160_000.0) as f32;
        let config = Self {
            causal_attention: None,
            architecture: VulkanTransformerArchitecture::ModernBert,
            vocab_size: usize_field("vocab_size")?,
            hidden_size,
            embedding_size: hidden_size,
            num_layers,
            num_heads,
            num_key_value_heads: num_heads,
            head_dim,
            intermediate_size: usize_field("intermediate_size")?,
            max_position_embeddings: usize_field("max_position_embeddings")?,
            layer_norm_eps: value
                .get("norm_eps")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(1.0e-5) as f32,
            layer_norm_elementwise_affine: true,
            activation_function: value
                .get("hidden_activation")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("gelu")
                .to_owned(),
            tie_word_embeddings: value
                .get("tie_word_embeddings")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
            rotary_dim: head_dim,
            rotary_emb_base,
            // ModernBERT stores independent RoPE dictionaries per attention
            // type. transformer_rotary_layers_for_package resolves those into
            // per-layer specs instead of flattening them into one shared value.
            rope_scaling: VulkanRopeScaling::default(),
            attention_dropout,
            attention_output_dropout: attention_dropout,
            activation_dropout: mlp_dropout,
            mlp_output_dropout: 0.0,
            embedding_dropout,
            embedding_multiplier: 1.0,
            attention_multiplier: None,
            scale_attn_by_inverse_layer_idx: false,
            alibi_bias_max: default_alibi_bias_max(),
            qkv_clip: None,
            residual_multiplier: 1.0,
            logits_multiplier: 1.0,
            final_logit_softcapping: None,
            attention_logit_softcapping: None,
            parallel_residual: false,
            shared_pre_norm: false,
            residual_connection_post_layernorm: false,
            use_post_norm: false,
            remove_final_norm: false,
            moe: None,
            attention_windows,
            activation_situ_beta: default_situ_beta(),
            activation_situ_linear_beta: None,
            linear_attention_layers: vec![],
        };
        if !config.rotary_emb_base.is_finite() || config.rotary_emb_base <= 1.0 {
            bail!("ModernBERT full-attention rope_theta must be finite and > 1");
        }
        config.validate()?;
        Ok(config)
    }

    fn from_modernbert_decoder_value(value: &serde_json::Value) -> Result<Self> {
        // ModernBERT Decoder deliberately preserves ModernBERT's embedding,
        // normalization, GLU, dropout, local/global attention schedule, and
        // per-layer RoPE contract. Its architectural differences are causal
        // masking plus split Q/K/V projection tensors, which are represented
        // by the architecture discriminator and package loader below.
        let mut config = Self::from_modernbert_value(value)?;
        config.architecture = VulkanTransformerArchitecture::ModernBertDecoder;
        config.validate()?;
        Ok(config)
    }

    fn from_emu3_text_value(value: &serde_json::Value) -> Result<Self> {
        let mut normalized = value.clone();
        let object = normalized
            .as_object_mut()
            .context("Emu3Text config must be a JSON object")?;
        let has_rope_theta = object.get("rope_theta").is_some()
            || object
                .get("rope_parameters")
                .and_then(serde_json::Value::as_object)
                .is_some_and(|parameters| parameters.get("rope_theta").is_some());
        if !has_rope_theta {
            object.insert("rope_theta".to_owned(), serde_json::json!(1_000_000.0));
        }
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Emu3Text,
            "Emu3Text",
            0,
        )?;
        // Emu3 reuses Llama attention/MLP math but applies the same
        // attention_dropout probability both inside attention and to each
        // decoder residual branch.
        config.attention_output_dropout = config.attention_dropout;
        config.mlp_output_dropout = config.attention_dropout;
        config.validate()?;
        Ok(config)
    }

    fn from_nanochat_value(value: &serde_json::Value) -> Result<Self> {
        if value
            .get("attention_bias")
            .is_some_and(|flag| !flag.is_boolean())
        {
            bail!("NanoChat attention_bias must be a boolean when specified");
        }
        let mut normalized = value.clone();
        let object = normalized
            .as_object_mut()
            .context("NanoChat config must be a JSON object")?;
        // NanoChat supports biased attention projections, while the generic
        // Llama-family parser intentionally rejects them. The package loader
        // below preserves the actual bias flag from the source config.
        object.insert("attention_bias".to_owned(), serde_json::json!(false));
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::NanoChat,
            "NanoChat",
            0,
        )?;
        config.final_logit_softcapping = match value.get("final_logit_softcapping") {
            None => Some(15.0),
            Some(value) if value.is_null() => None,
            Some(value) => {
                let cap = value
                    .as_f64()
                    .context("NanoChat final_logit_softcapping must be a positive number or null")?
                    as f32;
                if !cap.is_finite() || cap <= 0.0 {
                    bail!("NanoChat final_logit_softcapping must be finite and > 0 when specified");
                }
                Some(cap)
            }
        };
        config.validate()?;
        Ok(config)
    }

    fn from_arcee_value(value: &serde_json::Value) -> Result<Self> {
        Self::from_llama_family_value(value, VulkanTransformerArchitecture::Arcee, "Arcee", 0)
    }

    fn from_mistral_value(value: &serde_json::Value) -> Result<Self> {
        let sliding_window = match value.get("sliding_window") {
            Some(value) if value.is_null() => 0,
            Some(value) => value
                .as_u64()
                .context("Mistral sliding_window must be a positive integer or null")?
                as usize,
            None => 4096,
        };
        if value.get("sliding_window").is_some_and(|v| !v.is_null()) && sliding_window == 0 {
            bail!("Mistral sliding_window must be positive when specified");
        }
        Self::from_llama_family_value(
            value,
            VulkanTransformerArchitecture::Mistral,
            "Mistral",
            sliding_window,
        )
    }

    fn from_mixtral_value(value: &serde_json::Value) -> Result<Self> {
        let sliding_window = match value.get("sliding_window") {
            Some(value) if value.is_null() => 0,
            Some(value) => value
                .as_u64()
                .context("Mixtral sliding_window must be a positive integer or null")?
                as usize,
            None => 0,
        };
        if value.get("sliding_window").is_some_and(|v| !v.is_null()) && sliding_window == 0 {
            bail!("Mixtral sliding_window must be positive when specified");
        }

        // Mixtral's HF default theta differs from Llama/Mistral. Preserve an
        // explicit rope_parameters/rope_theta value and only synthesize the
        // current HF default when the package omits both spellings.
        let has_nested_theta = value
            .get("rope_parameters")
            .and_then(serde_json::Value::as_object)
            .and_then(|parameters| parameters.get("rope_theta"))
            .is_some();
        let mut normalized = value.clone();
        if value.get("rope_theta").is_none() && !has_nested_theta {
            normalized
                .as_object_mut()
                .context("Mixtral config must be a JSON object")?
                .insert("rope_theta".to_owned(), serde_json::json!(1_000_000.0));
        }
        let mut config = Self::from_llama_family_value(
            &normalized,
            // Parse the shared Mistral geometry before promoting the model to
            // Mixtral. The common Llama-family parser validates before it
            // returns, while Mixtral's routed-MoE contract is attached below;
            // validating as Mixtral here would therefore reject every valid
            // checkpoint as temporarily missing its MoE configuration.
            VulkanTransformerArchitecture::Mistral,
            "Mixtral",
            sliding_window,
        )?;
        config.architecture = VulkanTransformerArchitecture::Mixtral;
        let num_experts = value
            .get("num_local_experts")
            .or_else(|| value.get("num_experts"))
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(8) as usize;
        let top_k = value
            .get("num_experts_per_tok")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(2) as usize;
        let router_aux_loss_coef = value
            .get("router_aux_loss_coef")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(0.001) as f32;
        let router_jitter_noise = value
            .get("router_jitter_noise")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(0.0) as f32;
        config.moe = Some(VulkanTransformerMoeConfig {
            num_experts,
            top_k,
            sparse_layer_mask: Vec::new(),
            dense_intermediate_size: 0,
            shared_expert_intermediate_size: 0,
            use_rms_norm: false,
            shared_expert_combination_scale: 1.0,
            normalize_top_k: true,
            router_score_function: VulkanMoeRouterScoreFunction::Softmax,
            router_logit_softcapping: 0.0,
            routed_scaling_factor: 1.0,
            router_group_count: 1,
            router_topk_group: 1,
            router_aux_loss_coef,
            input_jitter_noise: 0.0,
            router_jitter_noise,
        });
        config.validate()?;
        Ok(config)
    }

    fn from_phimoe_value(value: &serde_json::Value) -> Result<Self> {
        let sliding_window = match value.get("sliding_window") {
            Some(value) if value.is_null() => 0,
            Some(value) => value
                .as_u64()
                .context("Phi-MoE sliding_window must be a positive integer or null")?
                as usize,
            None => 0,
        };
        if value.get("sliding_window").is_some_and(|v| !v.is_null()) && sliding_window == 0 {
            bail!("Phi-MoE sliding_window must be positive when specified");
        }

        // Phi-MoE shares the split-QKV/GQA/rotary decoder geometry with the
        // Llama family, but it intentionally uses affine LayerNorm rather than
        // RMSNorm and routes every MLP through SparseMixer. Parse the common
        // geometry through Llama first so attention_bias=true is accepted,
        // then promote the contract before final validation.
        let has_nested_theta = value
            .get("rope_parameters")
            .and_then(serde_json::Value::as_object)
            .and_then(|parameters| parameters.get("rope_theta"))
            .is_some();
        let mut normalized = value.clone();
        if value.get("rope_theta").is_none() && !has_nested_theta {
            normalized
                .as_object_mut()
                .context("Phi-MoE config must be a JSON object")?
                .insert("rope_theta".to_owned(), serde_json::json!(1_000_000.0));
        }
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Llama,
            "Phi-MoE",
            sliding_window,
        )?;
        config.architecture = VulkanTransformerArchitecture::Phimoe;
        config.layer_norm_eps = value
            .get("rms_norm_eps")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(1.0e-5) as f32;

        let num_experts = value
            .get("num_local_experts")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(16) as usize;
        let top_k = value
            .get("num_experts_per_tok")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(2) as usize;
        // The current HF sparsemixer implementation performs exactly two
        // sequential selections regardless of the optional function argument.
        // Reject a contradictory config instead of silently executing different
        // routing math.
        if top_k != 2 {
            bail!("Phi-MoE SparseMixer requires num_experts_per_tok=2, got {top_k}");
        }
        let router_jitter_noise = value
            .get("router_jitter_noise")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(0.01) as f32;
        let input_jitter_noise = value
            .get("input_jitter_noise")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(0.0) as f32;
        config.moe = Some(VulkanTransformerMoeConfig {
            num_experts,
            top_k,
            sparse_layer_mask: Vec::new(),
            dense_intermediate_size: 0,
            shared_expert_intermediate_size: 0,
            use_rms_norm: false,
            shared_expert_combination_scale: 1.0,
            normalize_top_k: false,
            router_score_function: VulkanMoeRouterScoreFunction::SparseMixer,
            router_logit_softcapping: 0.0,
            routed_scaling_factor: 1.0,
            router_group_count: 1,
            router_topk_group: 1,
            router_aux_loss_coef: value
                .get("router_aux_loss_coef")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.001) as f32,
            input_jitter_noise,
            router_jitter_noise,
        });
        config.validate()?;
        Ok(config)
    }

    fn from_aria_text_value(value: &serde_json::Value) -> Result<Self> {
        let activation = value
            .get("hidden_act")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("silu");
        // Aria's routed experts hard-code SiLU while the always-on shared
        // expert follows hidden_act. The native MoE graph intentionally uses
        // one activation contract for both paths, so only the configuration
        // where those two HF branches are mathematically identical is valid.
        if activation != "silu" {
            bail!(
                "Aria Text hidden_act={activation:?} is not supported because routed experts hard-code SiLU while shared experts use hidden_act"
            );
        }

        // Parse through the dense Llama contract first because the common
        // Llama-family parser validates before returning. Promote to Aria only
        // after attaching its routed-MoE geometry, mirroring Mixtral's parser.
        let mut config = Self::from_llama_family_value(
            value,
            VulkanTransformerArchitecture::Llama,
            "Aria Text",
            0,
        )?;
        config.architecture = VulkanTransformerArchitecture::AriaText;
        let num_experts = value
            .get("moe_num_experts")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(8) as usize;
        let top_k = value
            .get("moe_topk")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(2) as usize;
        let num_shared_experts = value
            .get("moe_num_shared_experts")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(2) as usize;
        if num_shared_experts == 0 {
            bail!("Aria Text moe_num_shared_experts must be positive");
        }
        let shared_expert_intermediate_size = config
            .intermediate_size
            .checked_mul(num_shared_experts)
            .context("Aria Text shared-expert intermediate size overflow")?;
        config.moe = Some(VulkanTransformerMoeConfig {
            num_experts,
            top_k,
            sparse_layer_mask: Vec::new(),
            dense_intermediate_size: 0,
            shared_expert_intermediate_size,
            use_rms_norm: false,
            shared_expert_combination_scale: 1.0,
            normalize_top_k: true,
            router_score_function: VulkanMoeRouterScoreFunction::Softmax,
            router_logit_softcapping: 0.0,
            routed_scaling_factor: 1.0,
            router_group_count: 1,
            router_topk_group: 1,
            router_aux_loss_coef: 0.0,
            input_jitter_noise: 0.0,
            router_jitter_noise: 0.0,
        });
        config.validate()?;
        Ok(config)
    }

    fn from_ministral_value(value: &serde_json::Value) -> Result<Self> {
        // Hugging Face Ministral is a Qwen2-style decoder with Mistral's
        // bias-free projections. Its default layer topology is sliding
        // attention for every layer whenever sliding_window is configured.
        let mut config = Self::from_mistral_value(value)?;
        config.architecture = VulkanTransformerArchitecture::Ministral;
        Self::apply_qwen_attention_windows(value, &mut config, "Ministral")?;
        config.validate()?;
        Ok(config)
    }

    fn from_ministral3_value(value: &serde_json::Value) -> Result<Self> {
        let sliding_window = match value.get("sliding_window") {
            Some(value) if value.is_null() => 0,
            Some(value) => value
                .as_u64()
                .context("Ministral3 sliding_window must be a positive integer or null")?
                as usize,
            None => 0,
        };
        if value.get("sliding_window").is_some_and(|v| !v.is_null()) && sliding_window == 0 {
            bail!("Ministral3 sliding_window must be positive when specified");
        }
        let config = Self::from_llama_family_value(
            value,
            VulkanTransformerArchitecture::Ministral3,
            "Ministral3",
            sliding_window,
        )?;
        if config.rope_scaling.scaling_type == VulkanRopeScalingType::Yarn
            && config.rope_scaling.original_max_position_embeddings == 0
        {
            bail!("Ministral3 YaRN requires original_max_position_embeddings");
        }
        config.validate()?;
        Ok(config)
    }

    fn from_jais2_value(value: &serde_json::Value) -> Result<Self> {
        for field in ["attention_bias", "mlp_bias"] {
            if value.get(field).is_some_and(|flag| !flag.is_boolean()) {
                bail!("Jais2 {field} must be a boolean when specified");
            }
        }
        let layer_norm_eps = value
            .get("layer_norm_eps")
            .and_then(serde_json::Value::as_f64)
            .unwrap_or(1.0e-5);
        let mut normalized = value.clone();
        let object = normalized
            .as_object_mut()
            .context("Jais2 config must be a JSON object")?;
        // Reuse the dense split-QKV Llama-family parser for dimensions/RoPE,
        // while Jais2's LayerNorm and configurable projection biases are
        // handled by its architecture flag and package-weight loader below.
        object.insert("attention_bias".to_owned(), serde_json::json!(false));
        object.insert("mlp_bias".to_owned(), serde_json::json!(false));
        object.insert("rms_norm_eps".to_owned(), serde_json::json!(layer_norm_eps));
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Jais2,
            "Jais2",
            0,
        )?;
        config.layer_norm_eps = layer_norm_eps as f32;
        if !config.hidden_size.is_multiple_of(config.num_heads) {
            bail!("Jais2 hidden_size must be divisible by num_attention_heads");
        }
        config.validate()?;
        Ok(config)
    }

    fn from_qwen2_value(value: &serde_json::Value) -> Result<Self> {
        if value
            .get("attention_bias")
            .is_some_and(|flag| !flag.is_boolean())
        {
            bail!("Qwen2 attention_bias must be a boolean when specified");
        }
        let mut normalized = value.clone();
        normalized
            .as_object_mut()
            .context("Qwen2 config must be a JSON object")?
            // Qwen2's flag controls Q/K/V only; the shared Llama parser's
            // generic attention-bias contract also includes o_proj. Preserve
            // the source flag in config.json and let the package loader below
            // apply it specifically to Q/K/V.
            .insert("attention_bias".to_owned(), serde_json::json!(false));
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Qwen2,
            "Qwen2",
            0,
        )?;
        Self::apply_qwen_attention_windows(value, &mut config, "Qwen2")?;
        config.validate()?;
        Ok(config)
    }

    fn qwen_moe_sparse_layer_mask(
        value: &serde_json::Value,
        num_layers: usize,
        num_experts: usize,
        family: &str,
    ) -> Result<Vec<bool>> {
        let decoder_sparse_step = value
            .get("decoder_sparse_step")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(1) as usize;
        if decoder_sparse_step == 0 {
            bail!("{family} decoder_sparse_step must be positive");
        }
        let mlp_only_layers = match value.get("mlp_only_layers") {
            None | Some(serde_json::Value::Null) => Vec::new(),
            Some(value) => value
                .as_array()
                .with_context(|| format!("{family} mlp_only_layers must be an array or null"))?
                .iter()
                .enumerate()
                .map(|(position, value)| {
                    let layer = value.as_u64().with_context(|| {
                        format!("{family} mlp_only_layers[{position}] must be a non-negative integer")
                    })? as usize;
                    if layer >= num_layers {
                        bail!(
                            "{family} mlp_only_layers[{position}]={layer} is outside num_hidden_layers={num_layers}"
                        );
                    }
                    Ok(layer)
                })
                .collect::<Result<Vec<_>>>()?,
        };
        Ok((0..num_layers)
            .map(|layer| {
                num_experts > 0
                    && !mlp_only_layers.contains(&layer)
                    && (layer + 1).is_multiple_of(decoder_sparse_step)
            })
            .collect())
    }

    fn from_qwen2_moe_value(value: &serde_json::Value) -> Result<Self> {
        let num_experts = value
            .get("num_experts")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(60) as usize;
        let top_k = value
            .get("num_experts_per_tok")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(4) as usize;
        let moe_intermediate_size = value
            .get("moe_intermediate_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(1408) as usize;
        let shared_expert_intermediate_size = value
            .get("shared_expert_intermediate_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(5632) as usize;
        if moe_intermediate_size == 0 || shared_expert_intermediate_size == 0 {
            bail!("Qwen2-MoE expert intermediate sizes must be positive");
        }
        let dense_intermediate_size = value
            .get("intermediate_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(5632) as usize;
        if dense_intermediate_size == 0 {
            bail!("Qwen2-MoE intermediate_size must be positive");
        }
        let num_layers = value
            .get("num_hidden_layers")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(24) as usize;
        let sparse_layer_mask =
            Self::qwen_moe_sparse_layer_mask(value, num_layers, num_experts, "Qwen2-MoE")?;

        let mut normalized = value.clone();
        normalized
            .as_object_mut()
            .context("Qwen2-MoE config must be a JSON object")?
            .insert(
                "intermediate_size".to_owned(),
                serde_json::json!(moe_intermediate_size),
            );
        if value
            .get("attention_bias")
            .is_some_and(|flag| !flag.is_boolean())
        {
            bail!("Qwen2-MoE attention_bias must be a boolean when specified");
        }
        normalized
            .as_object_mut()
            .expect("validated Qwen2-MoE object")
            .insert("attention_bias".to_owned(), serde_json::json!(false));
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Qwen2,
            "Qwen2-MoE",
            0,
        )?;
        config.architecture = VulkanTransformerArchitecture::Qwen2Moe;
        Self::apply_qwen_attention_windows(value, &mut config, "Qwen2-MoE")?;
        config.moe = Some(VulkanTransformerMoeConfig {
            num_experts,
            top_k,
            sparse_layer_mask,
            dense_intermediate_size,
            shared_expert_intermediate_size,
            use_rms_norm: false,
            shared_expert_combination_scale: 1.0,
            normalize_top_k: value
                .get("norm_topk_prob")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            router_score_function: VulkanMoeRouterScoreFunction::Softmax,
            router_logit_softcapping: 0.0,
            routed_scaling_factor: 1.0,
            router_group_count: 1,
            router_topk_group: 1,
            router_aux_loss_coef: value
                .get("router_aux_loss_coef")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.001) as f32,
            input_jitter_noise: 0.0,
            router_jitter_noise: 0.0,
        });
        config.validate()?;
        Ok(config)
    }

    fn from_qwen2_vl_text_value(value: &serde_json::Value) -> Result<Self> {
        let mut normalized = value.clone();
        let object = normalized
            .as_object_mut()
            .context("Qwen2-VL text config must be a JSON object")?;

        // Both Qwen2-VL text families use 1e6 as their config-level RoPE
        // default. Keep that default even for older raw config.json files that
        // omit rope_theta entirely; the shared Llama-family parser otherwise
        // defaults to 1e4.
        let has_nested_theta = ["rope_parameters", "rope_scaling"]
            .into_iter()
            .filter_map(|field| object.get(field))
            .filter_map(serde_json::Value::as_object)
            .any(|parameters| parameters.get("rope_theta").is_some());
        if object.get("rope_theta").is_none() && !has_nested_theta {
            object.insert("rope_theta".to_owned(), serde_json::json!(1_000_000.0));
        }
        if value
            .get("attention_bias")
            .is_some_and(|flag| !flag.is_boolean())
        {
            bail!("Qwen2-VL text attention_bias must be a boolean when specified");
        }

        // Current Transformers standardizes the historical `mrope` spelling
        // to ordinary RoPE plus an `mrope_section` layout. The section only
        // changes how distinct temporal/height/width positions are mixed for
        // visual tokens. Text-only positions are equal across all three axes,
        // so preserving theta/scaling while canonicalizing the type to
        // `default` is mathematically exact for this backend's text path.
        for field in ["rope_parameters", "rope_scaling"] {
            if let Some(parameters) = object
                .get_mut(field)
                .and_then(serde_json::Value::as_object_mut)
            {
                let rope_type = parameters
                    .get("rope_type")
                    .or_else(|| parameters.get("type"))
                    .and_then(serde_json::Value::as_str);
                if rope_type == Some("mrope") {
                    parameters.insert("rope_type".to_owned(), serde_json::json!("default"));
                    parameters.remove("type");
                }
            }
        }

        // Qwen2-VL uses biased Q/K/V projections just like Qwen2. The generic
        // Qwen2 architecture flag drives the checkpoint loader's required bias
        // handling, while o_proj and MLP projections remain bias-free.
        object.insert("attention_bias".to_owned(), serde_json::json!(false));
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Qwen2,
            "Qwen2-VL text",
            0,
        )?;
        Self::apply_qwen_attention_windows(&normalized, &mut config, "Qwen2-VL text")?;
        config.validate()?;
        Ok(config)
    }

    fn from_paddleocr_vl_text_value(value: &serde_json::Value) -> Result<Self> {
        let mut normalized = value.clone();
        let object = normalized
            .as_object_mut()
            .context("PaddleOCR-VL text config must be a JSON object")?;
        let use_bias = match object.get("use_bias") {
            Some(value) => value
                .as_bool()
                .context("PaddleOCR-VL text use_bias must be a boolean")?,
            None => false,
        };

        // PaddleOCR's decoder is the same pre-norm RMSNorm + split-GQA +
        // gated-SiLU graph represented by the native Llama contract, with an
        // explicit head_dim and one shared `use_bias` flag for every attention
        // and MLP projection. Translate that flag into the generic native bias
        // fields while retaining the exact checkpoint tensor names.
        object.insert("attention_bias".to_owned(), serde_json::json!(use_bias));
        object.insert("mlp_bias".to_owned(), serde_json::json!(use_bias));
        // The current HF attention module deliberately fixes dropout to zero
        // even though the config carries an attention_dropout field.
        object.insert("attention_dropout".to_owned(), serde_json::json!(0.0));

        let has_nested_theta = ["rope_parameters", "rope_scaling"]
            .into_iter()
            .filter_map(|field| object.get(field))
            .filter_map(serde_json::Value::as_object)
            .any(|parameters| parameters.get("rope_theta").is_some());
        if object.get("rope_theta").is_none() && !has_nested_theta {
            object.insert("rope_theta".to_owned(), serde_json::json!(500_000.0));
        }

        // PaddleOCR's multimodal RoPE differs only when temporal, height, and
        // width position ids diverge. Pure text uses equal ids on all axes, so
        // the transform reduces exactly to ordinary 1-D RoPE.
        for field in ["rope_parameters", "rope_scaling"] {
            if let Some(parameters) = object
                .get_mut(field)
                .and_then(serde_json::Value::as_object_mut)
            {
                let rope_type = parameters
                    .get("rope_type")
                    .or_else(|| parameters.get("type"))
                    .and_then(serde_json::Value::as_str);
                if rope_type == Some("mrope") {
                    parameters.insert("rope_type".to_owned(), serde_json::json!("default"));
                    parameters.remove("type");
                }
            }
        }

        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Llama,
            "PaddleOCR-VL text",
            0,
        )?;
        Self::apply_qwen_attention_windows(&normalized, &mut config, "PaddleOCR-VL text")?;
        config.tie_word_embeddings = value
            .get("tie_word_embeddings")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true);
        config.validate()?;
        Ok(config)
    }

    fn from_qwen3_value(value: &serde_json::Value) -> Result<Self> {
        let mut config =
            Self::from_llama_family_value(value, VulkanTransformerArchitecture::Qwen3, "Qwen3", 0)?;
        Self::apply_qwen_attention_windows(value, &mut config, "Qwen3")?;
        config.validate()?;
        Ok(config)
    }

    fn qwen_hybrid_linear_attention_layers(
        value: &serde_json::Value,
        num_layers: usize,
        family: &str,
    ) -> Result<Vec<bool>> {
        if let Some(layer_types) = value
            .get("layer_types")
            .filter(|layer_types| !layer_types.is_null())
        {
            let layer_types = layer_types
                .as_array()
                .with_context(|| format!("{family} layer_types must be an array or null"))?;
            if layer_types.len() != num_layers {
                bail!(
                    "{family} layer_types length {} does not match num_hidden_layers={num_layers}",
                    layer_types.len()
                );
            }
            return layer_types
                .iter()
                .enumerate()
                .map(|(index, layer_type)| match layer_type.as_str() {
                    Some("linear_attention") => Ok(true),
                    Some("full_attention") => Ok(false),
                    Some(other) => bail!(
                        "unsupported {family} layer_types[{index}]={other:?}; expected linear_attention or full_attention"
                    ),
                    None => bail!("{family} layer_types[{index}] must be a string"),
                })
                .collect();
        }

        let interval = value
            .get("full_attention_interval")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(4) as usize;
        if interval == 0 {
            bail!("{family} full_attention_interval must be positive");
        }
        Ok((0..num_layers)
            .map(|layer| !(layer + 1).is_multiple_of(interval))
            .collect())
    }

    fn apply_qwen_hybrid_rope(
        value: &serde_json::Value,
        config: &mut VulkanTransformerConfig,
        family: &str,
        default_partial_rotary_factor: f64,
    ) -> Result<()> {
        let partial_rotary_factor = Self::partial_rotary_factor(
            value,
            "partial_rotary_factor",
            default_partial_rotary_factor,
        );
        if !partial_rotary_factor.is_finite()
            || partial_rotary_factor <= 0.0
            || partial_rotary_factor > 1.0
        {
            bail!("{family} partial_rotary_factor must be finite and in (0, 1]");
        }
        config.rotary_dim = (config.head_dim as f64 * partial_rotary_factor) as usize;
        if config.rotary_dim == 0 || !config.rotary_dim.is_multiple_of(2) {
            bail!("{family} rotary dimension must be a positive even integer");
        }
        Ok(())
    }

    fn normalize_qwen35_text_value(
        value: &serde_json::Value,
        family: &str,
    ) -> Result<serde_json::Value> {
        let mut normalized = value.clone();
        let object = normalized
            .as_object_mut()
            .with_context(|| format!("{family} config must be a JSON object"))?;
        // Qwen3.5 exposes multimodal mRoPE metadata even in the text config.
        // For a pure text stream all three position axes are identical, so
        // mRoPE reduces exactly to the ordinary 1-D rotary transform while
        // retaining theta and partial_rotary_factor.
        for field in ["rope_parameters", "rope_scaling"] {
            if let Some(parameters) = object
                .get_mut(field)
                .and_then(serde_json::Value::as_object_mut)
            {
                let rope_type = parameters
                    .get("rope_type")
                    .or_else(|| parameters.get("type"))
                    .and_then(serde_json::Value::as_str);
                if rope_type == Some("mrope") {
                    parameters.insert("rope_type".to_owned(), serde_json::json!("default"));
                    parameters.remove("type");
                }
            }
        }
        Ok(normalized)
    }

    fn from_qwen3_next_value(value: &serde_json::Value) -> Result<Self> {
        let num_layers = value
            .get("num_hidden_layers")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(48) as usize;
        let dense_intermediate_size = value
            .get("intermediate_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(5632) as usize;
        let moe_intermediate_size = value
            .get("moe_intermediate_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(512) as usize;
        let shared_expert_intermediate_size = value
            .get("shared_expert_intermediate_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(512) as usize;
        if dense_intermediate_size == 0
            || moe_intermediate_size == 0
            || shared_expert_intermediate_size == 0
        {
            bail!("Qwen3-Next expert and dense intermediate sizes must be positive");
        }
        let num_experts = value
            .get("num_experts")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(512) as usize;
        let top_k = value
            .get("num_experts_per_tok")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(10) as usize;
        let sparse_layer_mask =
            Self::qwen_moe_sparse_layer_mask(value, num_layers, num_experts, "Qwen3-Next")?;
        let linear_attention_layers =
            Self::qwen_hybrid_linear_attention_layers(value, num_layers, "Qwen3-Next")?;

        let mut normalized = value.clone();
        let object = normalized
            .as_object_mut()
            .context("Qwen3-Next config must be a JSON object")?;
        object.insert(
            "intermediate_size".to_owned(),
            serde_json::json!(moe_intermediate_size),
        );
        object
            .entry("vocab_size".to_owned())
            .or_insert_with(|| serde_json::json!(151_936));
        object
            .entry("hidden_size".to_owned())
            .or_insert_with(|| serde_json::json!(2048));
        object
            .entry("num_hidden_layers".to_owned())
            .or_insert_with(|| serde_json::json!(48));
        object
            .entry("num_attention_heads".to_owned())
            .or_insert_with(|| serde_json::json!(16));
        object
            .entry("num_key_value_heads".to_owned())
            .or_insert_with(|| serde_json::json!(2));
        object
            .entry("head_dim".to_owned())
            .or_insert_with(|| serde_json::json!(256));
        object
            .entry("max_position_embeddings".to_owned())
            .or_insert_with(|| serde_json::json!(32_768));
        object
            .entry("hidden_act".to_owned())
            .or_insert_with(|| serde_json::json!("silu"));
        object
            .entry("rms_norm_eps".to_owned())
            .or_insert_with(|| serde_json::json!(1.0e-6));

        // Parse common full-attention geometry using Qwen3, then promote the
        // graph after the routed-MoE contract is attached. This avoids the
        // fail-closed validation guard for a sparse architecture with no MoE.
        let mut config = Self::from_llama_family_value(
            &normalized,
            VulkanTransformerArchitecture::Qwen3,
            "Qwen3-Next",
            0,
        )?;
        config.architecture = VulkanTransformerArchitecture::Qwen3Next;
        config.linear_attention_layers = linear_attention_layers;
        Self::apply_qwen_hybrid_rope(value, &mut config, "Qwen3-Next", 0.25)?;
        config.moe = Some(VulkanTransformerMoeConfig {
            num_experts,
            top_k,
            sparse_layer_mask,
            dense_intermediate_size,
            shared_expert_intermediate_size,
            use_rms_norm: false,
            shared_expert_combination_scale: 1.0,
            normalize_top_k: value
                .get("norm_topk_prob")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
            router_score_function: VulkanMoeRouterScoreFunction::Softmax,
            router_logit_softcapping: 0.0,
            routed_scaling_factor: 1.0,
            router_group_count: 1,
            router_topk_group: 1,
            router_aux_loss_coef: value
                .get("router_aux_loss_coef")
                .and_then(serde_json::Value::as_f64)
                .unwrap_or(0.001) as f32,
            input_jitter_noise: 0.0,
            router_jitter_noise: 0.0,
        });
        config.validate()?;
        Ok(config)
    }

