fn load_lora_b_bias(
    weights_path: &Path,
    tensors: &SafeTensors<'_>,
    module: &str,
    output_dim: usize,
    allow_bare: bool,
) -> Result<Vec<f32>> {
    let names = tensors.names();
    let bias_name = lora_b_bias_tensor_candidates(module, allow_bare)
        .into_iter()
        .find(|candidate| names.iter().any(|name| *name == candidate))
        .with_context(|| format!("adapter is missing LoRA-B bias weights for module {module}"))?;
    let (shape, bias) = read_f32_tensor(weights_path, &bias_name)?;
    if shape != [output_dim] {
        bail!("adapter tensor {bias_name:?} has shape {shape:?}; expected [{output_dim}]");
    }
    Ok(bias)
}

