fn load_peft_bias_all_parameter(
    weights_path: &Path,
    tensors: &SafeTensors<'_>,
    parameter: &str,
    expected_shape: &[usize],
    allow_bare: bool,
) -> Result<Vec<f32>> {
    let names = tensors.names();
    let mut candidates = vec![
        format!("base_model.model.{parameter}"),
        parameter.to_owned(),
    ];
    if allow_bare {
        if let Some((_, leaf)) = parameter.rsplit_once('.') {
            candidates.push(leaf.to_owned());
        }
    }
    let tensor_name = candidates
        .into_iter()
        .find(|candidate| names.iter().any(|name| *name == candidate))
        .with_context(|| format!("adapter is missing bias=\"all\" tensor {parameter}"))?;
    let (shape, values) = read_f32_tensor(weights_path, &tensor_name)?;
    if shape != expected_shape {
        bail!("adapter tensor {tensor_name:?} has shape {shape:?}; expected {expected_shape:?}");
    }
    Ok(values)
}

