fn configure_peft_saved_layer_norm(
    device: &VulkanDevice,
    config: &VulkanTransformerLoraConfig,
    module: &str,
    norm: &mut VulkanLayerNorm,
    adapter: Option<(&Path, &SafeTensors<'_>, bool)>,
) -> Result<()> {
    if !config.saves_module(module) {
        return Ok(());
    }
    if let Some((weights_path, tensors, _allow_bare)) = adapter {
        let parameter_len = norm.dim * norm.parameter_groups;
        let weight = load_peft_module_tensor(
            weights_path,
            tensors,
            module,
            "weight",
            &[parameter_len],
            false,
        )?;
        norm.weight = TrainableParameter::new(device, &weight, false)?;
        if norm.has_bias && !norm.rms {
            let bias = load_peft_module_tensor(
                weights_path,
                tensors,
                module,
                "bias",
                &[parameter_len],
                false,
            )?;
            norm.bias = TrainableParameter::new(device, &bias, false)?;
        }
    }
    if !config.inference_mode {
        norm.enable_base_training();
    }
    Ok(())
}

fn export_peft_saved_layer_norm(
    owned: &mut BTreeMap<String, (Vec<usize>, Vec<u8>)>,
    config: &VulkanTransformerLoraConfig,
    module: &str,
    norm: &VulkanLayerNorm,
) -> Result<()> {
    if !config.saves_module(module) {
        return Ok(());
    }
    let parameter_len = norm.dim * norm.parameter_groups;
    owned.insert(
        peft_saved_module_tensor_key(module, "weight"),
        (vec![parameter_len], f32_le_bytes(&norm.weight.read()?)),
    );
    if norm.has_bias && !norm.rms {
        owned.insert(
            peft_saved_module_tensor_key(module, "bias"),
            (vec![parameter_len], f32_le_bytes(&norm.bias.read()?)),
        );
    }
    Ok(())
}

