fn load_lora_pair(
    weights_path: &Path,
    tensors: &SafeTensors<'_>,
    module: &str,
    rank: usize,
    input_dim: usize,
    output_dim: usize,
    allow_bare: bool,
) -> Result<(Vec<f32>, Vec<f32>)> {
    let names = tensors.names();
    let a_name = lora_tensor_candidates(module, 'A', allow_bare)
        .into_iter()
        .find(|candidate| names.iter().any(|name| *name == candidate))
        .with_context(|| format!("adapter is missing LoRA A weights for module {module}"))?;
    let b_name = lora_tensor_candidates(module, 'B', allow_bare)
        .into_iter()
        .find(|candidate| names.iter().any(|name| *name == candidate))
        .with_context(|| format!("adapter is missing LoRA B weights for module {module}"))?;
    let (a_shape, a) = read_f32_tensor(weights_path, &a_name)?;
    let (b_shape, b) = read_f32_tensor(weights_path, &b_name)?;
    if a_shape != [rank, input_dim] {
        bail!("adapter tensor {a_name:?} has shape {a_shape:?}; expected [{rank}, {input_dim}]");
    }
    if b_shape != [output_dim, rank] {
        bail!("adapter tensor {b_name:?} has shape {b_shape:?}; expected [{output_dim}, {rank}]");
    }
    Ok((a, b))
}

