fn load_factorized_embedding_project(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<HostLinear>> {
    let embedding_size = config.effective_embedding_size();
    // ALBERT always owns embedding_hidden_mapping_in, even for unusual custom
    // configs where embedding_size happens to equal hidden_size. Other
    // factorized families only materialize a projection when the widths differ.
    if embedding_size == config.hidden_size
        && config.architecture != VulkanTransformerArchitecture::Albert
    {
        return Ok(None);
    }
    if !matches!(
        config.architecture,
        VulkanTransformerArchitecture::Albert
            | VulkanTransformerArchitecture::Electra
            | VulkanTransformerArchitecture::RoFormer
            | VulkanTransformerArchitecture::RemBert
            | VulkanTransformerArchitecture::Opt
    ) {
        bail!(
            "{} does not support a factorized embedding projection",
            config.architecture.model_type()
        );
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    if config.architecture == VulkanTransformerArchitecture::Opt {
        return Ok(Some(HostLinear {
            weight: store.take_expected(
                "model.decoder.project_in.weight",
                &[config.hidden_size, embedding_size],
            )?,
            bias: None,
        }));
    }
    let base = config
        .architecture
        .bert_family_base_prefix()
        .context("factorized embedding projection requires a BERT-family checkpoint prefix")?;
    let projection_base = match config.architecture {
        VulkanTransformerArchitecture::Albert => {
            format!("{base}.encoder.embedding_hidden_mapping_in")
        }
        VulkanTransformerArchitecture::RemBert => {
            format!("{base}.encoder.embedding_hidden_mapping_in")
        }
        _ => format!("{base}.embeddings_project"),
    };
    Ok(Some(HostLinear {
        weight: store.take_expected(
            &format!("{projection_base}.weight"),
            &[config.hidden_size, embedding_size],
        )?,
        bias: Some(store.take_expected(&format!("{projection_base}.bias"), &[config.hidden_size])?),
    }))
}

fn load_factorized_output_project(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<HostLinear>> {
    let embedding_size = config.effective_embedding_size();
    if embedding_size == config.hidden_size {
        return Ok(None);
    }
    if config.architecture != VulkanTransformerArchitecture::Opt {
        return Ok(None);
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    Ok(Some(HostLinear {
        weight: store.take_expected(
            "model.decoder.project_out.weight",
            &[embedding_size, config.hidden_size],
        )?,
        bias: None,
    }))
}

