fn load_encoder_decoder_bert_component_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
    config_value: &serde_json::Value,
    component_prefix: &str,
    base_model_only: bool,
) -> Result<HostTransformerWeights> {
    if config.architecture != VulkanTransformerArchitecture::Bert {
        bail!("generic EncoderDecoder BERT component loader requires a BERT graph");
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    store = if base_model_only {
        // AutoModel(BertConfig) serializes the bare BertModel below
        // `encoder.*`, so restore BertModel's ordinary package prefix.
        store.rebase_prefix(component_prefix, "bert")?
    } else {
        // AutoModelForCausalLM(BertConfig) serializes `bert.*` + `cls.*`
        // below `decoder.*`; stripping only the outer composite namespace
        // restores the normal BertLMHeadModel state-dict layout.
        store.rebase_prefix(component_prefix, "")?
    };
    let d = config.hidden_size;
    let e = config.effective_embedding_size();
    let i = config.intermediate_size;
    let base = "bert";
    let type_vocab_size = config_value
        .get("type_vocab_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2) as usize;
    if type_vocab_size == 0 {
        bail!("BERT type_vocab_size must be positive");
    }
    let token_embedding = store.take_expected(
        &format!("{base}.embeddings.word_embeddings.weight"),
        &[config.vocab_size, e],
    )?;
    let position_embedding = Some(store.take_expected(
        &format!("{base}.embeddings.position_embeddings.weight"),
        &[config.max_position_embeddings, e],
    )?);
    // The runtime owns token-type embeddings separately from the common host
    // weight bundle. Consume the copy here to keep this loader's structural
    // validation equivalent to the ordinary BERT package loader; the caller
    // loads the same tensor into the dedicated embedding op below.
    let _token_type_embedding = store.take_expected(
        &format!("{base}.embeddings.token_type_embeddings.weight"),
        &[type_vocab_size, e],
    )?;
    let embedding_norm = HostLayerNorm {
        weight: store.take_expected(&format!("{base}.embeddings.LayerNorm.weight"), &[e])?,
        bias: store.take_expected(&format!("{base}.embeddings.LayerNorm.bias"), &[e])?,
    };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("{base}.encoder.layer.{layer}");
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.attention.output.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.attention.output.LayerNorm.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(HostLinear {
                weight: store
                    .take_expected(&format!("{p}.attention.self.query.weight"), &[d, d])?,
                bias: Some(store.take_expected(&format!("{p}.attention.self.query.bias"), &[d])?),
            }),
            k_proj: Some(HostLinear {
                weight: store.take_expected(&format!("{p}.attention.self.key.weight"), &[d, d])?,
                bias: Some(store.take_expected(&format!("{p}.attention.self.key.bias"), &[d])?),
            }),
            v_proj: Some(HostLinear {
                weight: store
                    .take_expected(&format!("{p}.attention.self.value.weight"), &[d, d])?,
                bias: Some(store.take_expected(&format!("{p}.attention.self.value.bias"), &[d])?),
            }),
            q_norm: None,
            k_norm: None,
            c_proj: HostLinear {
                weight: store
                    .take_expected(&format!("{p}.attention.output.dense.weight"), &[d, d])?,
                bias: Some(store.take_expected(&format!("{p}.attention.output.dense.bias"), &[d])?),
            },
            ln2: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.output.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.output.LayerNorm.bias"), &[d])?,
            },
            c_fc: HostLinear {
                weight: store.take_expected(&format!("{p}.intermediate.dense.weight"), &[i, d])?,
                bias: Some(store.take_expected(&format!("{p}.intermediate.dense.bias"), &[i])?),
            },
            c_gate: None,
            c_mlp_proj: HostLinear {
                weight: store.take_expected(&format!("{p}.output.dense.weight"), &[d, i])?,
                bias: Some(store.take_expected(&format!("{p}.output.dense.bias"), &[d])?),
            },
            xielu: None,
        });
    }
    let final_norm = HostLayerNorm {
        weight: vec![1.0; d],
        bias: vec![0.0; d],
    };
    if base_model_only {
        // EncoderDecoderModel requires AutoModel (no LM head) on the encoder.
        // The generic Vulkan graph still owns an internal vocabulary
        // projection, but callers of the seq2seq facade consume only the final
        // hidden state. Reuse tied embeddings for that inert projection.
        let inert_lm_head = (!config.tie_word_embeddings).then(|| token_embedding.clone());
        return Ok(HostTransformerWeights {
            token_embedding,
            position_embedding,
            embedding_norm: Some(embedding_norm),
            layers,
            final_norm,
            prediction_head: None,
            has_lm_head_alias: false,
            lm_head: inert_lm_head,
            lm_head_bias: None,
        });
    }

    let prediction_head = HostPredictionHead {
        dense: HostLinear {
            weight: store.take_expected("cls.predictions.transform.dense.weight", &[d, d])?,
            bias: Some(store.take_expected("cls.predictions.transform.dense.bias", &[d])?),
        },
        activation_function: config.activation_function.clone(),
        norm: HostLayerNorm {
            weight: store.take_expected("cls.predictions.transform.LayerNorm.weight", &[d])?,
            bias: store.take_expected("cls.predictions.transform.LayerNorm.bias", &[d])?,
        },
    };
    let decoder_weight_name = "cls.predictions.decoder.weight";
    let has_lm_head_alias = config.tie_word_embeddings && store.contains(decoder_weight_name);
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias = store.take_expected(decoder_weight_name, &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!(
                    "EncoderDecoder BERT decoder declares tied word embeddings but {decoder_weight_name} differs from bert.embeddings.word_embeddings.weight"
                );
            }
        }
        None
    } else {
        Some(store.take_expected(decoder_weight_name, &[config.vocab_size, d])?)
    };
    let lm_head_bias = if store.contains("cls.predictions.bias") {
        let bias = store.take_expected("cls.predictions.bias", &[config.vocab_size])?;
        if store.contains("cls.predictions.decoder.bias") {
            let alias =
                store.take_expected("cls.predictions.decoder.bias", &[config.vocab_size])?;
            if alias != bias {
                bail!(
                    "EncoderDecoder BERT decoder cls.predictions.decoder.bias differs from cls.predictions.bias"
                );
            }
        }
        Some(bias)
    } else {
        Some(store.take_expected("cls.predictions.decoder.bias", &[config.vocab_size])?)
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding,
        embedding_norm: Some(embedding_norm),
        layers,
        final_norm,
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_encoder_decoder_bert_token_type_embedding(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
    config_value: &serde_json::Value,
    component_prefix: &str,
    base_model_only: bool,
) -> Result<Vec<f32>> {
    let type_vocab_size = config_value
        .get("type_vocab_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2) as usize;
    let mut store = Gpt2TensorStore::load(model_dir)?;
    store = if base_model_only {
        store.rebase_prefix(component_prefix, "bert")?
    } else {
        store.rebase_prefix(component_prefix, "")?
    };
    store.take_expected(
        "bert.embeddings.token_type_embeddings.weight",
        &[type_vocab_size, config.effective_embedding_size()],
    )
}

fn load_encoder_decoder_bert_cross_attention_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
    component_prefix: &str,
) -> Result<Vec<HostCrossAttention>> {
    if config.architecture != VulkanTransformerArchitecture::Bert {
        bail!("generic EncoderDecoder BERT cross-attention loader requires a BERT graph");
    }
    let mut store = Gpt2TensorStore::load(model_dir)?.rebase_prefix(component_prefix, "")?;
    let d = config.hidden_size;
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("bert.encoder.layer.{layer}.crossattention");
        let linear = |store: &mut Gpt2TensorStore, name: &str| -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[d, d])?,
                bias: Some(store.take_expected(&format!("{name}.bias"), &[d])?),
            })
        };
        layers.push(HostCrossAttention {
            q_proj: linear(&mut store, &format!("{p}.self.query"))?,
            k_proj: linear(&mut store, &format!("{p}.self.key"))?,
            v_proj: linear(&mut store, &format!("{p}.self.value"))?,
            out_proj: linear(&mut store, &format!("{p}.output.dense"))?,
            norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.output.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.output.LayerNorm.bias"), &[d])?,
            },
            post_norm: None,
        });
    }
    Ok(layers)
}

fn load_bert_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let e = config.effective_embedding_size();
    let i = config.intermediate_size;
    let base = config
        .architecture
        .bert_family_base_prefix()
        .context("BERT-like checkpoint loader requires a BERT-family checkpoint prefix")?;
    let token_embedding = store.take_expected(
        &format!("{base}.embeddings.word_embeddings.weight"),
        &[config.vocab_size, e],
    )?;
    let position_embedding = if config.architecture == VulkanTransformerArchitecture::RoFormer {
        None
    } else {
        Some(store.take_expected(
            &format!("{base}.embeddings.position_embeddings.weight"),
            &[config.max_position_embeddings, e],
        )?)
    };
    let config_path = model_dir.join("config.json");
    let config_value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    let type_vocab_size = config_value
        .get("type_vocab_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2) as usize;
    let attention_projection_bias = config.architecture != VulkanTransformerArchitecture::BigBird
        || config_value
            .get("use_bias")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true);
    let _token_type_embedding = store.take_expected(
        &format!("{base}.embeddings.token_type_embeddings.weight"),
        &[type_vocab_size, e],
    )?;
    let embedding_norm = HostLayerNorm {
        weight: store.take_expected(&format!("{base}.embeddings.LayerNorm.weight"), &[e])?,
        bias: store.take_expected(&format!("{base}.embeddings.LayerNorm.bias"), &[e])?,
    };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("{base}.encoder.layer.{layer}");
        let q_proj = HostLinear {
            weight: store.take_expected(&format!("{p}.attention.self.query.weight"), &[d, d])?,
            bias: if attention_projection_bias {
                Some(store.take_expected(&format!("{p}.attention.self.query.bias"), &[d])?)
            } else {
                None
            },
        };
        let k_proj = HostLinear {
            weight: store.take_expected(&format!("{p}.attention.self.key.weight"), &[d, d])?,
            bias: if attention_projection_bias {
                Some(store.take_expected(&format!("{p}.attention.self.key.bias"), &[d])?)
            } else {
                None
            },
        };
        let v_proj = HostLinear {
            weight: store.take_expected(&format!("{p}.attention.self.value.weight"), &[d, d])?,
            bias: if attention_projection_bias {
                Some(store.take_expected(&format!("{p}.attention.self.value.bias"), &[d])?)
            } else {
                None
            },
        };
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.attention.output.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.attention.output.LayerNorm.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(q_proj),
            k_proj: Some(k_proj),
            v_proj: Some(v_proj),
            q_norm: None,
            k_norm: None,
            c_proj: HostLinear {
                weight: store
                    .take_expected(&format!("{p}.attention.output.dense.weight"), &[d, d])?,
                bias: Some(store.take_expected(&format!("{p}.attention.output.dense.bias"), &[d])?),
            },
            ln2: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.output.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.output.LayerNorm.bias"), &[d])?,
            },
            c_fc: HostLinear {
                weight: store.take_expected(&format!("{p}.intermediate.dense.weight"), &[i, d])?,
                bias: Some(store.take_expected(&format!("{p}.intermediate.dense.bias"), &[i])?),
            },
            c_gate: None,
            c_mlp_proj: HostLinear {
                weight: store.take_expected(&format!("{p}.output.dense.weight"), &[d, i])?,
                bias: Some(store.take_expected(&format!("{p}.output.dense.bias"), &[d])?),
            },
            xielu: None,
        });
    }
    let electra = config.architecture == VulkanTransformerArchitecture::Electra;
    let rembert = config.architecture == VulkanTransformerArchitecture::RemBert;
    let prediction_dim = if rembert {
        config_value
            .get("output_embedding_size")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(1664) as usize
    } else {
        e
    };
    if prediction_dim == 0 {
        bail!(
            "{} output embedding size must be positive",
            config.architecture.model_type()
        );
    }
    let (prediction_dense, prediction_norm, decoder_weight_name, activation_function) = if electra {
        (
            "generator_predictions.dense",
            "generator_predictions.LayerNorm",
            "generator_lm_head.weight",
            "gelu".to_owned(),
        )
    } else if rembert {
        (
            "cls.predictions.dense",
            "cls.predictions.LayerNorm",
            "cls.predictions.decoder.weight",
            config.activation_function.clone(),
        )
    } else {
        (
            "cls.predictions.transform.dense",
            "cls.predictions.transform.LayerNorm",
            "cls.predictions.decoder.weight",
            config.activation_function.clone(),
        )
    };
    let prediction_head = HostPredictionHead {
        dense: HostLinear {
            weight: store
                .take_expected(&format!("{prediction_dense}.weight"), &[prediction_dim, d])?,
            bias: Some(
                store.take_expected(&format!("{prediction_dense}.bias"), &[prediction_dim])?,
            ),
        },
        activation_function,
        norm: HostLayerNorm {
            weight: store.take_expected(&format!("{prediction_norm}.weight"), &[prediction_dim])?,
            bias: store.take_expected(&format!("{prediction_norm}.bias"), &[prediction_dim])?,
        },
    };
    let has_lm_head_alias = config.tie_word_embeddings && store.contains(decoder_weight_name);
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias =
                store.take_expected(decoder_weight_name, &[config.vocab_size, prediction_dim])?;
            if alias != token_embedding {
                bail!(
                    "{} package declares tied word embeddings but {decoder_weight_name} differs from {base}.embeddings.word_embeddings.weight",
                    config.architecture.model_type()
                );
            }
        }
        None
    } else {
        Some(store.take_expected(decoder_weight_name, &[config.vocab_size, prediction_dim])?)
    };
    let lm_head_bias = if electra {
        Some(store.take_expected("generator_lm_head.bias", &[config.vocab_size])?)
    } else if store.contains("cls.predictions.bias") {
        let bias = store.take_expected("cls.predictions.bias", &[config.vocab_size])?;
        if store.contains("cls.predictions.decoder.bias") {
            let alias =
                store.take_expected("cls.predictions.decoder.bias", &[config.vocab_size])?;
            if alias != bias {
                bail!(
                    "{} cls.predictions.decoder.bias differs from cls.predictions.bias",
                    config.architecture.model_type()
                );
            }
        }
        Some(bias)
    } else if store.contains("cls.predictions.decoder.bias") {
        Some(store.take_expected("cls.predictions.decoder.bias", &[config.vocab_size])?)
    } else {
        bail!(
            "{} package is missing cls.predictions.bias/cls.predictions.decoder.bias",
            config.architecture.model_type()
        )
    };
    // BertForMaskedLM ends directly after the final encoder block and applies
    // its transform/LayerNorm in the prediction head instead of a model-level
    // final normalization.
    let final_norm = HostLayerNorm {
        weight: vec![1.0; d],
        bias: vec![0.0; d],
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding,
        embedding_norm: Some(embedding_norm),
        layers,
        final_norm,
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_albert_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    if config.architecture != VulkanTransformerArchitecture::Albert {
        bail!("ALBERT checkpoint loader requires an ALBERT graph");
    }
    let topology = AlbertTopology::from_package(model_dir)?;
    if topology.logical_to_physical.len() != config.num_layers {
        bail!(
            "ALBERT config expands to {} native execution layers but the runtime config contains {}",
            topology.logical_to_physical.len(),
            config.num_layers
        );
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let e = config.effective_embedding_size();
    let i = config.intermediate_size;
    let token_embedding = store.take_expected(
        "albert.embeddings.word_embeddings.weight",
        &[config.vocab_size, e],
    )?;
    let position_embedding = Some(store.take_expected(
        "albert.embeddings.position_embeddings.weight",
        &[config.max_position_embeddings, e],
    )?);
    let config_path = model_dir.join("config.json");
    let config_value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    let type_vocab_size = config_value
        .get("type_vocab_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2) as usize;
    let _token_type_embedding = store.take_expected(
        "albert.embeddings.token_type_embeddings.weight",
        &[type_vocab_size, e],
    )?;
    let embedding_norm = HostLayerNorm {
        weight: store.take_expected("albert.embeddings.LayerNorm.weight", &[e])?,
        bias: store.take_expected("albert.embeddings.LayerNorm.bias", &[e])?,
    };

    let linear = |store: &mut Gpt2TensorStore,
                  name: &str,
                  output_dim: usize,
                  input_dim: usize|
     -> Result<HostLinear> {
        Ok(HostLinear {
            weight: store.take_expected(&format!("{name}.weight"), &[output_dim, input_dim])?,
            bias: Some(store.take_expected(&format!("{name}.bias"), &[output_dim])?),
        })
    };
    let physical_count = topology.physical_layer_count()?;
    let mut physical_layers = Vec::with_capacity(physical_count);
    for physical in 0..physical_count {
        let (group, inner) = topology.physical_coordinates(physical)?;
        let p = format!("albert.encoder.albert_layer_groups.{group}.albert_layers.{inner}");
        physical_layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.attention.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.attention.LayerNorm.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(linear(&mut store, &format!("{p}.attention.query"), d, d)?),
            k_proj: Some(linear(&mut store, &format!("{p}.attention.key"), d, d)?),
            v_proj: Some(linear(&mut store, &format!("{p}.attention.value"), d, d)?),
            q_norm: None,
            k_norm: None,
            c_proj: linear(&mut store, &format!("{p}.attention.dense"), d, d)?,
            ln2: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.full_layer_layer_norm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.full_layer_layer_norm.bias"), &[d])?,
            },
            c_fc: linear(&mut store, &format!("{p}.ffn"), i, d)?,
            c_gate: None,
            c_mlp_proj: linear(&mut store, &format!("{p}.ffn_output"), d, i)?,
            xielu: None,
        });
    }
    let layers = topology
        .logical_to_physical
        .iter()
        .map(|&physical| physical_layers[physical].clone())
        .collect::<Vec<_>>();

    let prediction_head = HostPredictionHead {
        dense: linear(&mut store, "predictions.dense", e, d)?,
        activation_function: config.activation_function.clone(),
        norm: HostLayerNorm {
            weight: store.take_expected("predictions.LayerNorm.weight", &[e])?,
            bias: store.take_expected("predictions.LayerNorm.bias", &[e])?,
        },
    };
    let decoder_weight_name = "predictions.decoder.weight";
    let has_lm_head_alias = config.tie_word_embeddings && store.contains(decoder_weight_name);
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias = store.take_expected(decoder_weight_name, &[config.vocab_size, e])?;
            if alias != token_embedding {
                bail!(
                    "ALBERT package declares tied word embeddings but {decoder_weight_name} differs from albert.embeddings.word_embeddings.weight"
                );
            }
        }
        None
    } else {
        Some(store.take_expected(decoder_weight_name, &[config.vocab_size, e])?)
    };
    let lm_head_bias = if store.contains("predictions.bias") {
        let bias = store.take_expected("predictions.bias", &[config.vocab_size])?;
        if store.contains("predictions.decoder.bias") {
            let alias = store.take_expected("predictions.decoder.bias", &[config.vocab_size])?;
            if alias != bias {
                bail!("ALBERT predictions.decoder.bias differs from predictions.bias");
            }
        }
        Some(bias)
    } else if store.contains("predictions.decoder.bias") {
        Some(store.take_expected("predictions.decoder.bias", &[config.vocab_size])?)
    } else {
        bail!("ALBERT package is missing predictions.bias/predictions.decoder.bias")
    };

    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding,
        embedding_norm: Some(embedding_norm),
        layers,
        final_norm: HostLayerNorm {
            weight: vec![1.0; d],
            bias: vec![0.0; d],
        },
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_megatron_bert_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    if config.architecture != VulkanTransformerArchitecture::MegatronBert {
        bail!("Megatron-BERT checkpoint loader requires a Megatron-BERT graph");
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let token_embedding = store.take_expected(
        "bert.embeddings.word_embeddings.weight",
        &[config.vocab_size, d],
    )?;
    let position_embedding = store.take_expected(
        "bert.embeddings.position_embeddings.weight",
        &[config.max_position_embeddings, d],
    )?;
    let config_path = model_dir.join("config.json");
    let config_value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    let type_vocab_size = config_value
        .get("type_vocab_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2) as usize;
    let _token_type_embedding = store.take_expected(
        "bert.embeddings.token_type_embeddings.weight",
        &[type_vocab_size, d],
    )?;
    let linear =
        |store: &mut Gpt2TensorStore, name: &str, out: usize, input: usize| -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[out, input])?,
                bias: Some(store.take_expected(&format!("{name}.bias"), &[out])?),
            })
        };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("bert.encoder.layer.{layer}");
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.attention.ln.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.attention.ln.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.query"),
                d,
                d,
            )?),
            k_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.key"),
                d,
                d,
            )?),
            v_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.value"),
                d,
                d,
            )?),
            q_norm: None,
            k_norm: None,
            c_proj: linear(&mut store, &format!("{p}.attention.output.dense"), d, d)?,
            ln2: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.ln.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.ln.bias"), &[d])?,
            },
            c_fc: linear(&mut store, &format!("{p}.intermediate.dense"), i, d)?,
            c_gate: None,
            c_mlp_proj: linear(&mut store, &format!("{p}.output.dense"), d, i)?,
            xielu: None,
        });
    }
    let final_norm = HostLayerNorm {
        weight: store.take_expected("bert.encoder.ln.weight", &[d])?,
        bias: store.take_expected("bert.encoder.ln.bias", &[d])?,
    };
    let prediction_head = HostPredictionHead {
        dense: linear(&mut store, "cls.predictions.transform.dense", d, d)?,
        activation_function: config.activation_function.clone(),
        norm: HostLayerNorm {
            weight: store.take_expected("cls.predictions.transform.LayerNorm.weight", &[d])?,
            bias: store.take_expected("cls.predictions.transform.LayerNorm.bias", &[d])?,
        },
    };
    let has_lm_head_alias =
        config.tie_word_embeddings && store.contains("cls.predictions.decoder.weight");
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias =
                store.take_expected("cls.predictions.decoder.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!(
                    "Megatron-BERT package declares tied word embeddings but cls.predictions.decoder.weight differs from bert.embeddings.word_embeddings.weight"
                );
            }
        }
        None
    } else {
        Some(store.take_expected("cls.predictions.decoder.weight", &[config.vocab_size, d])?)
    };
    let lm_head_bias = if store.contains("cls.predictions.bias") {
        let bias = store.take_expected("cls.predictions.bias", &[config.vocab_size])?;
        if store.contains("cls.predictions.decoder.bias") {
            let alias =
                store.take_expected("cls.predictions.decoder.bias", &[config.vocab_size])?;
            if alias != bias {
                bail!(
                    "Megatron-BERT cls.predictions.decoder.bias differs from cls.predictions.bias"
                );
            }
        }
        Some(bias)
    } else if store.contains("cls.predictions.decoder.bias") {
        Some(store.take_expected("cls.predictions.decoder.bias", &[config.vocab_size])?)
    } else {
        bail!("Megatron-BERT package is missing cls.predictions.bias/cls.predictions.decoder.bias")
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: Some(position_embedding),
        embedding_norm: None,
        layers,
        final_norm,
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_nomic_bert_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    if config.architecture != VulkanTransformerArchitecture::NomicBert {
        bail!("Nomic BERT checkpoint loader requires a Nomic BERT graph");
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let q = config.query_hidden_size();
    let token_embedding = store.take_expected(
        "nomic_bert.embeddings.word_embeddings.weight",
        &[config.vocab_size, d],
    )?;
    let config_path = model_dir.join("config.json");
    let config_value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    let type_vocab_size = config_value
        .get("type_vocab_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2) as usize;
    if type_vocab_size == 0 {
        bail!("Nomic BERT type_vocab_size must be positive");
    }
    let _token_type_embedding = store.take_expected(
        "nomic_bert.embeddings.token_type_embeddings.weight",
        &[type_vocab_size, d],
    )?;
    let embedding_norm = HostLayerNorm {
        weight: store.take_expected("nomic_bert.embeddings.LayerNorm.weight", &[d])?,
        bias: store.take_expected("nomic_bert.embeddings.LayerNorm.bias", &[d])?,
    };
    let linear_no_bias =
        |store: &mut Gpt2TensorStore, name: &str, out: usize, input: usize| -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[out, input])?,
                bias: None,
            })
        };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("nomic_bert.layers.{layer}");
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.post_attention_layernorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.post_attention_layernorm.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(linear_no_bias(
                &mut store,
                &format!("{p}.self_attn.q_proj"),
                q,
                d,
            )?),
            k_proj: Some(linear_no_bias(
                &mut store,
                &format!("{p}.self_attn.k_proj"),
                q,
                d,
            )?),
            v_proj: Some(linear_no_bias(
                &mut store,
                &format!("{p}.self_attn.v_proj"),
                q,
                d,
            )?),
            q_norm: None,
            k_norm: None,
            c_proj: linear_no_bias(&mut store, &format!("{p}.self_attn.o_proj"), d, q)?,
            ln2: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.post_mlp_layernorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.post_mlp_layernorm.bias"), &[d])?,
            },
            c_fc: linear_no_bias(&mut store, &format!("{p}.mlp.up_proj"), i, d)?,
            c_gate: Some(linear_no_bias(
                &mut store,
                &format!("{p}.mlp.gate_proj"),
                i,
                d,
            )?),
            c_mlp_proj: linear_no_bias(&mut store, &format!("{p}.mlp.down_proj"), d, i)?,
            xielu: None,
        });
    }
    let prediction_head = HostPredictionHead {
        dense: HostLinear {
            weight: store.take_expected("cls.predictions.transform.dense.weight", &[d, d])?,
            bias: Some(store.take_expected("cls.predictions.transform.dense.bias", &[d])?),
        },
        activation_function: config.activation_function.clone(),
        norm: HostLayerNorm {
            weight: store.take_expected("cls.predictions.transform.layer_norm.weight", &[d])?,
            bias: store.take_expected("cls.predictions.transform.layer_norm.bias", &[d])?,
        },
    };
    let has_lm_head_alias =
        config.tie_word_embeddings && store.contains("cls.predictions.decoder.weight");
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias =
                store.take_expected("cls.predictions.decoder.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!(
                    "Nomic BERT package declares tied word embeddings but cls.predictions.decoder.weight differs from nomic_bert.embeddings.word_embeddings.weight"
                );
            }
        }
        None
    } else {
        Some(store.take_expected("cls.predictions.decoder.weight", &[config.vocab_size, d])?)
    };
    let lm_head_bias = if store.contains("cls.predictions.bias") {
        let bias = store.take_expected("cls.predictions.bias", &[config.vocab_size])?;
        if store.contains("cls.predictions.decoder.bias") {
            let alias =
                store.take_expected("cls.predictions.decoder.bias", &[config.vocab_size])?;
            if alias != bias {
                bail!("Nomic BERT cls.predictions.decoder.bias differs from cls.predictions.bias");
            }
        }
        Some(bias)
    } else if store.contains("cls.predictions.decoder.bias") {
        Some(store.take_expected("cls.predictions.decoder.bias", &[config.vocab_size])?)
    } else {
        bail!("Nomic BERT package is missing cls.predictions.bias/cls.predictions.decoder.bias")
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: None,
        embedding_norm: Some(embedding_norm),
        layers,
        final_norm: HostLayerNorm {
            weight: vec![1.0; d],
            bias: vec![0.0; d],
        },
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_jina_embeddings_v3_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    if config.architecture != VulkanTransformerArchitecture::JinaEmbeddingsV3 {
        bail!("Jina Embeddings v3 checkpoint loader requires a Jina Embeddings v3 graph");
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let q = config.query_hidden_size();
    let kv = config.key_value_hidden_size();
    let token_embedding = store.take_expected(
        "roberta.embeddings.word_embeddings.weight",
        &[config.vocab_size, d],
    )?;
    let embedding_norm = HostLayerNorm {
        weight: store.take_expected("roberta.embeddings.LayerNorm.weight", &[d])?,
        bias: store.take_expected("roberta.embeddings.LayerNorm.bias", &[d])?,
    };
    let linear_with_bias =
        |store: &mut Gpt2TensorStore, name: &str, out: usize, input: usize| -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[out, input])?,
                bias: Some(store.take_expected(&format!("{name}.bias"), &[out])?),
            })
        };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("roberta.layers.{layer}");
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.post_attention_layernorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.post_attention_layernorm.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(linear_with_bias(
                &mut store,
                &format!("{p}.self_attn.q_proj"),
                q,
                d,
            )?),
            k_proj: Some(linear_with_bias(
                &mut store,
                &format!("{p}.self_attn.k_proj"),
                kv,
                d,
            )?),
            v_proj: Some(linear_with_bias(
                &mut store,
                &format!("{p}.self_attn.v_proj"),
                kv,
                d,
            )?),
            q_norm: None,
            k_norm: None,
            c_proj: linear_with_bias(&mut store, &format!("{p}.self_attn.o_proj"), d, q)?,
            ln2: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.post_mlp_layernorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.post_mlp_layernorm.bias"), &[d])?,
            },
            c_fc: linear_with_bias(&mut store, &format!("{p}.mlp.fc1"), i, d)?,
            c_gate: None,
            c_mlp_proj: linear_with_bias(&mut store, &format!("{p}.mlp.fc2"), d, i)?,
            xielu: None,
        });
    }
    let prediction_head = HostPredictionHead {
        dense: linear_with_bias(&mut store, "lm_head.dense", d, d)?,
        // Jina's MLM transform calls the exact GELU function directly rather
        // than reusing config.hidden_act.
        activation_function: "gelu".to_owned(),
        norm: HostLayerNorm {
            weight: store.take_expected("lm_head.layer_norm.weight", &[d])?,
            bias: store.take_expected("lm_head.layer_norm.bias", &[d])?,
        },
    };
    let has_lm_head_alias = config.tie_word_embeddings && store.contains("lm_head.decoder.weight");
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias = store.take_expected("lm_head.decoder.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!(
                    "Jina Embeddings v3 package declares tied word embeddings but lm_head.decoder.weight differs from roberta.embeddings.word_embeddings.weight"
                );
            }
        }
        None
    } else {
        Some(store.take_expected("lm_head.decoder.weight", &[config.vocab_size, d])?)
    };
    let lm_head_bias = if store.contains("lm_head.bias") {
        let bias = store.take_expected("lm_head.bias", &[config.vocab_size])?;
        if store.contains("lm_head.decoder.bias") {
            let alias = store.take_expected("lm_head.decoder.bias", &[config.vocab_size])?;
            if alias != bias {
                bail!("Jina Embeddings v3 lm_head.decoder.bias differs from lm_head.bias");
            }
        }
        Some(bias)
    } else if store.contains("lm_head.decoder.bias") {
        Some(store.take_expected("lm_head.decoder.bias", &[config.vocab_size])?)
    } else {
        bail!("Jina Embeddings v3 package is missing lm_head.bias/lm_head.decoder.bias")
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: None,
        embedding_norm: Some(embedding_norm),
        layers,
        // Jina ends directly after the final post-MLP LayerNorm. Keep the
        // graph's uniform placeholder, but uses_final_norm() bypasses it.
        final_norm: HostLayerNorm {
            weight: vec![1.0; d],
            bias: vec![0.0; d],
        },
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_roberta_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let pre_layer_norm = matches!(
        config.architecture,
        VulkanTransformerArchitecture::RobertaPreLayerNorm
            | VulkanTransformerArchitecture::XlmRobertaXL
    );
    let xlm_roberta_xl = config.architecture == VulkanTransformerArchitecture::XlmRobertaXL;
    let family = match config.architecture {
        VulkanTransformerArchitecture::RobertaPreLayerNorm => "RoBERTa-PreLayerNorm",
        VulkanTransformerArchitecture::Camembert => "CamemBERT",
        VulkanTransformerArchitecture::XlmRoberta => "XLM-RoBERTa",
        VulkanTransformerArchitecture::XlmRobertaXL => "XLM-RoBERTa-XL",
        VulkanTransformerArchitecture::Data2VecText => "Data2VecText",
        _ => "RoBERTa",
    };
    let base = config
        .architecture
        .bert_family_base_prefix()
        .context("RoBERTa-like checkpoint loader requires a BERT-family checkpoint prefix")?;
    let token_embedding = store.take_expected(
        &format!("{base}.embeddings.word_embeddings.weight"),
        &[config.vocab_size, d],
    )?;
    let position_embedding = store.take_expected(
        &format!("{base}.embeddings.position_embeddings.weight"),
        &[config.max_position_embeddings, d],
    )?;
    let config_path = model_dir.join("config.json");
    let config_value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    let type_vocab_size = config_value
        .get("type_vocab_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2) as usize;
    let _token_type_embedding = store.take_expected(
        &format!("{base}.embeddings.token_type_embeddings.weight"),
        &[type_vocab_size, d],
    )?;
    // XLM-RoBERTa-XL deliberately removes the embedding LayerNorm and moves
    // normalization to the pre-attention/pre-MLP sites plus one terminal
    // encoder LayerNorm. Preserve that topology instead of synthesizing an
    // identity affine layer, which would still change training semantics.
    let embedding_norm = if xlm_roberta_xl {
        None
    } else {
        Some(HostLayerNorm {
            weight: store.take_expected(&format!("{base}.embeddings.LayerNorm.weight"), &[d])?,
            bias: store.take_expected(&format!("{base}.embeddings.LayerNorm.bias"), &[d])?,
        })
    };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("{base}.encoder.layer.{layer}");
        let linear = |store: &mut Gpt2TensorStore,
                      name: &str,
                      out: usize,
                      input: usize|
         -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[out, input])?,
                bias: Some(store.take_expected(&format!("{name}.bias"), &[out])?),
            })
        };
        let attention_norm = if xlm_roberta_xl {
            format!("{p}.attention.self_attn_layer_norm")
        } else if pre_layer_norm {
            format!("{p}.attention.LayerNorm")
        } else {
            format!("{p}.attention.output.LayerNorm")
        };
        let mlp_norm = if xlm_roberta_xl {
            format!("{p}.LayerNorm")
        } else if pre_layer_norm {
            format!("{p}.intermediate.LayerNorm")
        } else {
            format!("{p}.output.LayerNorm")
        };
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store.take_expected(&format!("{attention_norm}.weight"), &[d])?,
                bias: store.take_expected(&format!("{attention_norm}.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.query"),
                d,
                d,
            )?),
            k_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.key"),
                d,
                d,
            )?),
            v_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.value"),
                d,
                d,
            )?),
            q_norm: None,
            k_norm: None,
            c_proj: linear(&mut store, &format!("{p}.attention.output.dense"), d, d)?,
            ln2: HostLayerNorm {
                weight: store.take_expected(&format!("{mlp_norm}.weight"), &[d])?,
                bias: store.take_expected(&format!("{mlp_norm}.bias"), &[d])?,
            },
            c_fc: linear(&mut store, &format!("{p}.intermediate.dense"), i, d)?,
            c_gate: None,
            c_mlp_proj: linear(&mut store, &format!("{p}.output.dense"), d, i)?,
            xielu: None,
        });
    }
    let prediction_head = HostPredictionHead {
        dense: HostLinear {
            weight: store.take_expected("lm_head.dense.weight", &[d, d])?,
            bias: Some(store.take_expected("lm_head.dense.bias", &[d])?),
        },
        // Both current HF heads call gelu() directly instead of consulting
        // hidden_act for the MLM transform.
        activation_function: "gelu".to_owned(),
        norm: HostLayerNorm {
            weight: store.take_expected("lm_head.layer_norm.weight", &[d])?,
            bias: store.take_expected("lm_head.layer_norm.bias", &[d])?,
        },
    };
    let has_lm_head_alias = config.tie_word_embeddings && store.contains("lm_head.decoder.weight");
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias = store.take_expected("lm_head.decoder.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!(
                    "{family} package declares tied word embeddings but lm_head.decoder.weight differs from {base}.embeddings.word_embeddings.weight"
                );
            }
        }
        None
    } else {
        Some(store.take_expected("lm_head.decoder.weight", &[config.vocab_size, d])?)
    };
    let lm_head_bias = if store.contains("lm_head.bias") {
        let bias = store.take_expected("lm_head.bias", &[config.vocab_size])?;
        if store.contains("lm_head.decoder.bias") {
            let alias = store.take_expected("lm_head.decoder.bias", &[config.vocab_size])?;
            if alias != bias {
                bail!("{family} lm_head.decoder.bias differs from lm_head.bias");
            }
        }
        Some(bias)
    } else if store.contains("lm_head.decoder.bias") {
        Some(store.take_expected("lm_head.decoder.bias", &[config.vocab_size])?)
    } else {
        bail!("{family} package is missing lm_head.bias/lm_head.decoder.bias")
    };
    let final_norm = if xlm_roberta_xl {
        HostLayerNorm {
            weight: store.take_expected(&format!("{base}.encoder.LayerNorm.weight"), &[d])?,
            bias: store.take_expected(&format!("{base}.encoder.LayerNorm.bias"), &[d])?,
        }
    } else if pre_layer_norm {
        HostLayerNorm {
            weight: store.take_expected(&format!("{base}.LayerNorm.weight"), &[d])?,
            bias: store.take_expected(&format!("{base}.LayerNorm.bias"), &[d])?,
        }
    } else {
        HostLayerNorm {
            weight: vec![1.0; d],
            bias: vec![0.0; d],
        }
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: Some(position_embedding),
        embedding_norm,
        layers,
        final_norm,
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_xlm_family_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    if !matches!(
        config.architecture,
        VulkanTransformerArchitecture::Xlm | VulkanTransformerArchitecture::Flaubert
    ) {
        bail!("XLM-family checkpoint loader requires an XLM or Flaubert graph");
    }
    let family = if config.architecture == VulkanTransformerArchitecture::Flaubert {
        "Flaubert"
    } else {
        "XLM"
    };
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let token_embedding =
        store.take_expected("transformer.embeddings.weight", &[config.vocab_size, d])?;
    let position_embedding = store.take_expected(
        "transformer.position_embeddings.weight",
        &[config.max_position_embeddings, d],
    )?;
    let embedding_norm = HostLayerNorm {
        weight: store.take_expected("transformer.layer_norm_emb.weight", &[d])?,
        bias: store.take_expected("transformer.layer_norm_emb.bias", &[d])?,
    };
    let linear =
        |store: &mut Gpt2TensorStore, name: &str, out: usize, input: usize| -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[out, input])?,
                bias: Some(store.take_expected(&format!("{name}.bias"), &[out])?),
            })
        };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let attention = format!("transformer.attentions.{layer}");
        let ffn = format!("transformer.ffns.{layer}");
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store
                    .take_expected(&format!("transformer.layer_norm1.{layer}.weight"), &[d])?,
                bias: store
                    .take_expected(&format!("transformer.layer_norm1.{layer}.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(linear(&mut store, &format!("{attention}.q_lin"), d, d)?),
            k_proj: Some(linear(&mut store, &format!("{attention}.k_lin"), d, d)?),
            v_proj: Some(linear(&mut store, &format!("{attention}.v_lin"), d, d)?),
            q_norm: None,
            k_norm: None,
            c_proj: linear(&mut store, &format!("{attention}.out_lin"), d, d)?,
            ln2: HostLayerNorm {
                weight: store
                    .take_expected(&format!("transformer.layer_norm2.{layer}.weight"), &[d])?,
                bias: store
                    .take_expected(&format!("transformer.layer_norm2.{layer}.bias"), &[d])?,
            },
            c_fc: linear(&mut store, &format!("{ffn}.lin1"), i, d)?,
            c_gate: None,
            c_mlp_proj: linear(&mut store, &format!("{ffn}.lin2"), d, i)?,
            xielu: None,
        });
    }
    let has_lm_head_alias = config.tie_word_embeddings && store.contains("pred_layer.proj.weight");
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias = store.take_expected("pred_layer.proj.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!(
                    "{family} package declares tied word embeddings but pred_layer.proj.weight differs from transformer.embeddings.weight"
                );
            }
        }
        None
    } else {
        Some(store.take_expected("pred_layer.proj.weight", &[config.vocab_size, d])?)
    };
    let lm_head_bias = Some(store.take_expected("pred_layer.proj.bias", &[config.vocab_size])?);
    // XLM/Flaubert finish after the final post-residual LayerNorm in the last
    // encoder block.  Keep an identity object for allocation symmetry, but the
    // architecture contract bypasses it in forward/backward and optimization.
    let final_norm = HostLayerNorm {
        weight: vec![1.0; d],
        bias: vec![0.0; d],
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: Some(position_embedding),
        embedding_norm: Some(embedding_norm),
        layers,
        final_norm,
        prediction_head: None,
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn bert_generation_cross_attention_enabled(model_dir: &Path) -> Result<bool> {
    let config_path = model_dir.join("config.json");
    let value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    Ok(value
        .get("add_cross_attention")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false))
}

fn bert_family_cross_attention_enabled(model_dir: &Path) -> Result<bool> {
    let config_path = model_dir.join("config.json");
    let value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    Ok(value
        .get("add_cross_attention")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false))
}

/// Hugging Face BigBird dynamically falls back from its configured
/// block-sparse attention to the ordinary full-attention implementation when
/// the concrete sequence is too short for the sparse global/window/random
/// pattern. It also forces full attention when cross-attention is enabled.
///
/// The Vulkan graph currently implements the exact full-attention path. Keep
/// config parsing broad enough to load normal BigBird packages, then make the
/// shape-dependent distinction here so short/default-package workloads are not
/// rejected merely because the serialized config says `block_sparse`.
fn validate_big_bird_attention_for_graph(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
    seq_len: usize,
) -> Result<()> {
    if config.architecture != VulkanTransformerArchitecture::BigBird {
        return Ok(());
    }
    let config_path = model_dir.join("config.json");
    let value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    let attention_type = value
        .get("attention_type")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("block_sparse");
    if attention_type == "original_full" {
        return Ok(());
    }
    if attention_type != "block_sparse" {
        bail!(
            "BigBird attention_type={attention_type:?} is invalid; expected \"original_full\" or \"block_sparse\""
        );
    }
    if value
        .get("add_cross_attention")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        // BigBirdModel.__init__ performs the same coercion before execution.
        return Ok(());
    }
    let block_size = value
        .get("block_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(64) as usize;
    if block_size == 0 {
        bail!("BigBird block_size must be positive");
    }
    let num_random_blocks = value
        .get("num_random_blocks")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(3) as usize;
    let max_tokens_to_attend = num_random_blocks
        .checked_mul(2)
        .and_then(|random| random.checked_add(5))
        .and_then(|blocks| blocks.checked_mul(block_size))
        .context("BigBird sparse-attention threshold overflow")?;
    if seq_len <= max_tokens_to_attend {
        // BigBirdModel.forward switches to original_full at exactly this
        // boundary, so the native dense attention graph is semantically exact.
        return Ok(());
    }
    bail!(
        "BigBird attention_type=\"block_sparse\" with sequence length {seq_len} requires the Hugging Face block-sparse global/window/random attention pattern (block_size={block_size}, num_random_blocks={num_random_blocks}); the current Vulkan graph is exact only for BigBird's original_full path or its automatic dense fallback at sequence lengths <= {max_tokens_to_attend}"
    )
}

fn load_bert_family_cross_attention_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<HostCrossAttention>>> {
    if !matches!(
        config.architecture,
        VulkanTransformerArchitecture::Bert
            | VulkanTransformerArchitecture::BigBird
            | VulkanTransformerArchitecture::RemBert
            | VulkanTransformerArchitecture::Electra
            | VulkanTransformerArchitecture::Ernie
    ) || !bert_family_cross_attention_enabled(model_dir)?
    {
        return Ok(None);
    }
    let base = config
        .architecture
        .bert_family_base_prefix()
        .context("BERT-family cross-attention requires a checkpoint prefix")?;
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let config_path = model_dir.join("config.json");
    let config_value: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    let attention_projection_bias = config.architecture != VulkanTransformerArchitecture::BigBird
        || config_value
            .get("use_bias")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true);
    let d = config.hidden_size;
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("{base}.encoder.layer.{layer}.crossattention");
        let attention_linear = |store: &mut Gpt2TensorStore, name: &str| -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[d, d])?,
                bias: if attention_projection_bias {
                    Some(store.take_expected(&format!("{name}.bias"), &[d])?)
                } else {
                    None
                },
            })
        };
        let output_linear = |store: &mut Gpt2TensorStore, name: &str| -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[d, d])?,
                bias: Some(store.take_expected(&format!("{name}.bias"), &[d])?),
            })
        };
        layers.push(HostCrossAttention {
            q_proj: attention_linear(&mut store, &format!("{p}.self.query"))?,
            k_proj: attention_linear(&mut store, &format!("{p}.self.key"))?,
            v_proj: attention_linear(&mut store, &format!("{p}.self.value"))?,
            out_proj: output_linear(&mut store, &format!("{p}.output.dense"))?,
            norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.output.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.output.LayerNorm.bias"), &[d])?,
            },
            post_norm: None,
        });
    }
    Ok(Some(layers))
}

fn load_roberta_family_cross_attention_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<HostCrossAttention>>> {
    if !matches!(
        config.architecture,
        VulkanTransformerArchitecture::Roberta
            | VulkanTransformerArchitecture::RobertaPreLayerNorm
            | VulkanTransformerArchitecture::Camembert
            | VulkanTransformerArchitecture::XlmRoberta
            | VulkanTransformerArchitecture::XlmRobertaXL
            | VulkanTransformerArchitecture::Data2VecText
    ) || !bert_family_cross_attention_enabled(model_dir)?
    {
        return Ok(None);
    }
    let base = config
        .architecture
        .bert_family_base_prefix()
        .context("RoBERTa-family cross-attention requires a checkpoint prefix")?;
    let pre_layer_norm = config.architecture == VulkanTransformerArchitecture::RobertaPreLayerNorm;
    let xlm_roberta_xl = config.architecture == VulkanTransformerArchitecture::XlmRobertaXL;
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("{base}.encoder.layer.{layer}.crossattention");
        let linear = |store: &mut Gpt2TensorStore, name: &str| -> Result<HostLinear> {
            Ok(HostLinear {
                weight: store.take_expected(&format!("{name}.weight"), &[d, d])?,
                bias: Some(store.take_expected(&format!("{name}.bias"), &[d])?),
            })
        };
        let norm = if xlm_roberta_xl {
            format!("{p}.self_attn_layer_norm")
        } else if pre_layer_norm {
            format!("{p}.LayerNorm")
        } else {
            format!("{p}.output.LayerNorm")
        };
        layers.push(HostCrossAttention {
            q_proj: linear(&mut store, &format!("{p}.self.query"))?,
            k_proj: linear(&mut store, &format!("{p}.self.key"))?,
            v_proj: linear(&mut store, &format!("{p}.self.value"))?,
            out_proj: linear(&mut store, &format!("{p}.output.dense"))?,
            norm: HostLayerNorm {
                weight: store.take_expected(&format!("{norm}.weight"), &[d])?,
                bias: store.take_expected(&format!("{norm}.bias"), &[d])?,
            },
            post_norm: None,
        });
    }
    Ok(Some(layers))
}

