fn load_xglm_cross_attention_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<HostCrossAttention>>> {
    if config.architecture != VulkanTransformerArchitecture::Xglm {
        return Ok(None);
    }
    let config_path = model_dir.join("config.json");
    let package_config: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    if !package_config
        .get("add_cross_attention")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        return Ok(None);
    }

    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let linear = |store: &mut Gpt2TensorStore, name: &str| -> Result<HostLinear> {
        Ok(HostLinear {
            weight: store.take_expected(&format!("{name}.weight"), &[d, d])?,
            bias: Some(store.take_expected(&format!("{name}.bias"), &[d])?),
        })
    };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("model.layers.{layer}");
        layers.push(HostCrossAttention {
            q_proj: linear(&mut store, &format!("{p}.encoder_attn.q_proj"))?,
            k_proj: linear(&mut store, &format!("{p}.encoder_attn.k_proj"))?,
            v_proj: linear(&mut store, &format!("{p}.encoder_attn.v_proj"))?,
            out_proj: linear(&mut store, &format!("{p}.encoder_attn.out_proj"))?,
            norm: HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.encoder_attn_layer_norm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.encoder_attn_layer_norm.bias"), &[d])?,
            },
            post_norm: None,
        });
    }
    Ok(Some(layers))
}

fn transformer_text_config_from_package(model_dir: &Path) -> Result<serde_json::Value> {
    let config_path = model_dir.join("config.json");
    let root: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    let model_type = root
        .get("model_type")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    let mut text = if model_type == "paddleocr_vl" && root.get("text_config").is_none() {
        let mut flat = root.clone();
        flat["model_type"] = serde_json::json!("paddleocr_vl_text");
        flat
    } else if model_type == "qwen3_omni_moe" {
        root.get("thinker_config")
            .and_then(|thinker| thinker.get("text_config"))
            .cloned()
            .context("qwen3_omni_moe package config is missing thinker_config.text_config")?
    } else if matches!(
        model_type,
        "qwen2_vl"
            | "qwen2_5_vl"
            | "qwen3_vl"
            | "qwen3_vl_moe"
            | "qwen4_exp"
            | "qwen3_omni_moe_thinker"
            | "mllama"
            | "glm4v"
            | "glm4v_moe"
            | "glm46v"
            | "glm_ocr"
            | "hunyuan_vl"
            | "gemma3"
            | "exaone4_5"
            | "cohere_compass"
            | "cohere2_vision"
            | "cosmos3_omni"
            | "got_ocr2"
            | "aya_vision"
            | "llava"
            | "llava_next"
            | "llava_next_video"
            | "llava_onevision"
            | "video_llava"
            | "video_llama_3"
            | "vipllava"
            | "idefics2"
            | "idefics3"
            | "smolvlm"
            | "qwen2_audio"
            | "voxtral"
            | "fast_vlm"
            | "internvl"
            | "janus"
            | "ovis2"
            | "paligemma"
            | "deepseek_vl"
            | "deepseek_vl_hybrid"
            | "paddleocr_vl"
            | "audioflamingo3"
            | "qwen3_asr"
            | "granite_speech"
            | "granite_speech_plus"
            | "granite4_vision"
            | "glmasr"
            | "musicflamingo"
            | "vibevoice_asr"
            | "kimi_k25"
            | "kimi_k3"
            | "emu3"
            | "aria"
            | "fuyu"
            | "mistral3"
            | "llama4"
    ) {
        root.get("text_config")
            .cloned()
            .with_context(|| format!("{model_type} package config is missing text_config"))?
    } else {
        root
    };

    // Kimi K2.5 accepts historical `kimi_k2` text configs but Transformers
    // normalizes those to DeepSeek-V3 before constructing the language model.
    // Mirror that normalization here because downstream MLA/MoE checkpoint
    // helpers inspect the package text model_type directly.
    if text.get("model_type").and_then(serde_json::Value::as_str) == Some("kimi_k2") {
        text["model_type"] = serde_json::json!("deepseek_v3");
    }

    if text.get("model_type").and_then(serde_json::Value::as_str) == Some("paddleocr_vl_text") {
        let use_bias = text
            .get("use_bias")
            .map(|value| {
                value
                    .as_bool()
                    .context("PaddleOCR-VL text use_bias must be a boolean")
            })
            .transpose()?
            .unwrap_or(false);
        let object = text
            .as_object_mut()
            .context("PaddleOCR-VL text config must be a JSON object")?;
        object.insert("attention_bias".to_owned(), serde_json::json!(use_bias));
        object.insert("mlp_bias".to_owned(), serde_json::json!(use_bias));
    }
    Ok(text)
}

fn validate_kimi_linear_package_quantization(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<()> {
    if config.architecture != VulkanTransformerArchitecture::KimiLinear {
        return Ok(());
    }
    let text_config = transformer_text_config_from_package(model_dir)?;
    if let Some(quantization) = text_config.get("quantization_config") {
        let format = quantization
            .get("format")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let quant_method = quantization
            .get("quant_method")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        if format.to_ascii_lowercase().contains("mxfp4")
            || (quant_method.eq_ignore_ascii_case("compressed-tensors")
                && format.to_ascii_lowercase().contains("mxfp4"))
        {
            bail!(
                "KimiLinear MXFP4 compressed-tensors checkpoints are not supported by the native Vulkan text backend; use an unquantized FP32/BF16 KimiLinear checkpoint"
            );
        }
    }
    Ok(())
}

fn transformer_package_model_type(model_dir: &Path) -> Result<Option<String>> {
    let config_path = model_dir.join("config.json");
    if !config_path.is_file() {
        return Ok(None);
    }
    let root: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;
    Ok(root
        .get("model_type")
        .and_then(serde_json::Value::as_str)
        .map(str::to_owned))
}

fn transformer_text_wrapper_prefix(model_type: &str) -> Option<&'static str> {
    match model_type {
        // MllamaForConditionalGeneration owns MllamaTextModel below
        // `model.language_model`, while a directly-saved MllamaForCausalLM
        // uses the ordinary `model.*` text prefix. Treat both as wrappers so
        // package export can preserve the reserved +8 embedding rows and any
        // skipped cross-attention tensors that are outside the text-only graph.
        "mllama" => Some("model.language_model"),
        "mllama_text_model" => Some("model"),
        // Llama4ForConditionalGeneration stores a full Llama4ForCausalLM in
        // `language_model`, whose decoder backbone is one level deeper at
        // `language_model.model.*`.
        "llama4" | "kimi_k3" => Some("language_model.model"),
        // Qwen3-Omni owns the multimodal thinker at `thinker.*`; the actual
        // Qwen3-MoE-compatible decoder is the thinker's `model` child.
        "qwen3_omni_moe" => Some("thinker.model"),
        "qwen2_vl"
        | "qwen2_5_vl"
        | "qwen3_vl"
        | "qwen3_vl_moe"
        | "qwen4_exp"
        | "glm4v"
        | "glm4v_moe"
        | "glm46v"
        | "glm_ocr"
        | "hunyuan_vl"
        | "gemma3"
        | "exaone4_5"
        | "cohere_compass"
        | "cohere2_vision"
        | "cosmos3_omni"
        | "got_ocr2"
        | "aya_vision"
        | "llava"
        | "llava_next"
        | "llava_next_video"
        | "llava_onevision"
        | "video_llava"
        | "video_llama_3"
        | "vipllava"
        | "qwen2_audio"
        | "voxtral"
        | "fast_vlm"
        | "internvl"
        | "janus"
        | "ovis2"
        | "aria"
        | "fuyu"
        | "mistral3"
        | "paligemma"
        | "deepseek_vl"
        | "deepseek_vl_hybrid"
        | "paddleocr_vl"
        | "audioflamingo3"
        | "qwen3_asr"
        | "granite_speech"
        | "granite_speech_plus"
        | "granite4_vision"
        | "glmasr"
        | "musicflamingo"
        | "vibevoice_asr"
        | "kimi_k25" => Some("model.language_model"),
        // Phi4MultimodalModel subclasses Phi3Model directly, so its text
        // tensors already live under `model.*`. Treat that root as a wrapper
        // prefix to preserve `model.embed_tokens_extend.*` and the image/audio
        // towers while replacing only the trained text parameters on export.
        "phi4_multimodal" => Some("model"),
        "emu3" | "idefics2" | "idefics3" | "smolvlm" | "modernvbert" => Some("model.text_model"),
        _ => None,
    }
}

fn load_llama_layout_tensor_store(model_dir: &Path) -> Result<Gpt2TensorStore> {
    let store = Gpt2TensorStore::load(model_dir)?;
    let package_model_type = transformer_package_model_type(model_dir)?;
    let Some(wrapper_prefix) = package_model_type
        .as_deref()
        .and_then(transformer_text_wrapper_prefix)
    else {
        return Ok(store);
    };
    let mut store = store.rebase_model_prefix(wrapper_prefix)?;
    if let Some(head_prefix) = package_model_type
        .as_deref()
        .and_then(transformer_text_wrapper_lm_head_prefix)
    {
        store = store.rebase_prefix(head_prefix, "lm_head")?;
    }
    Ok(store)
}

fn transformer_text_wrapper_lm_head_prefix(model_type: &str) -> Option<&'static str> {
    match model_type {
        // Llama4ForConditionalGeneration owns the language model under
        // `language_model.model` but keeps its output projection as the sibling
        // `language_model.lm_head` rather than at the package root.
        "llama4" | "kimi_k3" => Some("language_model.lm_head"),
        // Qwen3-Omni mirrors the same ownership pattern inside `thinker`.
        "qwen3_omni_moe" => Some("thinker.lm_head"),
        _ => None,
    }
}

fn remap_transformer_text_wrapper_tensors(
    tensors: BTreeMap<String, (Vec<usize>, Vec<f32>)>,
    wrapper_prefix: &str,
    model_type: Option<&str>,
) -> BTreeMap<String, (Vec<usize>, Vec<f32>)> {
    tensors
        .into_iter()
        .map(|(name, tensor)| {
            let mut name = name
                .strip_prefix("model.")
                .map(|suffix| format!("{wrapper_prefix}.{suffix}"))
                .unwrap_or(name);
            if model_type == Some("modernvbert") {
                if let Some(suffix) = name.strip_prefix("head.") {
                    name = format!("projection_head.{suffix}");
                } else if let Some(suffix) = name.strip_prefix("decoder.") {
                    name = format!("lm_head.{suffix}");
                }
            } else if let Some(head_prefix) =
                model_type.and_then(transformer_text_wrapper_lm_head_prefix)
            {
                if let Some(suffix) = name.strip_prefix("lm_head.") {
                    name = format!("{head_prefix}.{suffix}");
                }
            }
            (name, tensor)
        })
        .collect()
}

fn remap_mllama_text_only_layer_tensors(
    tensors: BTreeMap<String, (Vec<usize>, Vec<f32>)>,
    text_config: &serde_json::Value,
) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
    let source_layers = VulkanTransformerConfig::mllama_text_self_attention_layers(text_config)?;
    tensors
        .into_iter()
        .map(|(name, tensor)| {
            let Some(rest) = name.strip_prefix("model.layers.") else {
                return Ok((name, tensor));
            };
            let (native_index, suffix) = rest
                .split_once('.')
                .with_context(|| format!("malformed native Mllama layer tensor name {name:?}"))?;
            let native_index = native_index.parse::<usize>().with_context(|| {
                format!("invalid native Mllama layer index in tensor name {name:?}")
            })?;
            let source_index = *source_layers.get(native_index).with_context(|| {
                format!(
                    "native Mllama layer {native_index} is outside the {}-layer text-only map",
                    source_layers.len()
                )
            })?;
            Ok((format!("model.layers.{source_index}.{suffix}"), tensor))
        })
        .collect()
}

fn merge_transformer_text_wrapper_tensors(
    mut source: BTreeMap<String, (Vec<usize>, Vec<f32>)>,
    trained: BTreeMap<String, (Vec<usize>, Vec<f32>)>,
    wrapper_prefix: &str,
    model_type: Option<&str>,
) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
    for (name, (shape, values)) in
        remap_transformer_text_wrapper_tensors(trained, wrapper_prefix, model_type)
    {
        if matches!(model_type, Some("mllama") | Some("mllama_text_model"))
            && name == format!("{wrapper_prefix}.embed_tokens.weight")
        {
            let (source_shape, source_values) = source.get_mut(&name).with_context(|| {
                format!("Mllama source package is missing reserved embedding tensor {name:?}")
            })?;
            if shape.len() != 2 || source_shape.len() != 2 {
                bail!(
                    "Mllama embedding tensor must be rank-2; trained shape={shape:?}, source shape={source_shape:?}"
                );
            }
            let expected_source_rows = shape[0]
                .checked_add(8)
                .context("Mllama reserved embedding row count overflow")?;
            if source_shape[0] != expected_source_rows || source_shape[1] != shape[1] {
                bail!(
                    "Mllama source embedding has shape {source_shape:?}; expected [{expected_source_rows}, {}] for trained text embedding {shape:?}",
                    shape[1]
                );
            }
            if values.len() != shape[0] * shape[1]
                || source_values.len() != source_shape[0] * source_shape[1]
            {
                bail!("Mllama embedding tensor value count does not match its declared shape");
            }
            source_values[..values.len()].copy_from_slice(&values);
            continue;
        }
        source.insert(name, (shape, values));
    }
    Ok(source)
}

fn transformer_export_output_path(
    source_dir: &Path,
    output_dir: &Path,
    source_path: &Path,
) -> Result<PathBuf> {
    let relative = source_path.strip_prefix(source_dir).with_context(|| {
        format!(
            "checkpoint shard {} is outside source package {}",
            source_path.display(),
            source_dir.display()
        )
    })?;
    Ok(output_dir.join(relative))
}

fn copy_transformer_safetensors_checkpoint(source_dir: &Path, output_dir: &Path) -> Result<()> {
    let single = source_dir.join(GPT2_SAFETENSORS_FILENAME);
    if single.is_file() {
        fs::copy(&single, output_dir.join(GPT2_SAFETENSORS_FILENAME))
            .with_context(|| format!("copying Transformer checkpoint {}", single.display()))?;
        return Ok(());
    }

    let index_path = source_dir.join(GPT2_SAFETENSORS_INDEX_FILENAME);
    let index: serde_json::Value = serde_json::from_slice(
        &fs::read(&index_path).with_context(|| format!("reading {}", index_path.display()))?,
    )
    .with_context(|| format!("decoding {}", index_path.display()))?;
    let weight_map = index
        .get("weight_map")
        .and_then(serde_json::Value::as_object)
        .context("Transformer SafeTensors index is missing object weight_map")?;
    let mut shards = BTreeSet::new();
    for shard in weight_map.values() {
        let shard = shard
            .as_str()
            .context("Transformer SafeTensors index contains a non-string shard name")?;
        shards.insert(safe_relative_safetensors_path(shard)?);
    }
    for relative in shards {
        let source = source_dir.join(&relative);
        let target = output_dir.join(&relative);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::copy(&source, &target).with_context(|| {
            format!(
                "copying Transformer checkpoint shard {} to {}",
                source.display(),
                target.display()
            )
        })?;
    }
    fs::copy(
        &index_path,
        output_dir.join(GPT2_SAFETENSORS_INDEX_FILENAME),
    )
    .with_context(|| {
        format!(
            "copying Transformer checkpoint index {}",
            index_path.display()
        )
    })?;
    Ok(())
}

fn qwen_hybrid_attention_geometry(
    value: &serde_json::Value,
    family: &str,
) -> Result<(usize, usize, usize, usize, usize)> {
    let positive = |field: &str, default: usize| -> Result<usize> {
        let parsed = value
            .get(field)
            .and_then(serde_json::Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(default);
        if parsed == 0 {
            bail!("{family} {field} must be positive");
        }
        Ok(parsed)
    };
    let olmo_hybrid = family == "OLMo Hybrid";
    let glm5_next = family == "GLM-5 Next";
    if glm5_next {
        let num_heads = positive("linear_num_heads", 64)?;
        let head_dim = positive("linear_head_dim", 128)?;
        let conv_kernel_size = positive("linear_conv_kernel_dim", 4)?;
        return Ok((conv_kernel_size, num_heads, num_heads, head_dim, head_dim));
    }
    let default_key_heads = if olmo_hybrid {
        value
            .get("num_attention_heads")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(1) as usize
    } else {
        16
    };
    let num_key_heads = positive("linear_num_key_heads", default_key_heads)?;
    let default_value_heads = if olmo_hybrid { num_key_heads } else { 32 };
    let num_value_heads = positive("linear_num_value_heads", default_value_heads)?;
    let hidden_size = value
        .get("hidden_size")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0) as usize;
    let default_key_head_dim = if olmo_hybrid && hidden_size > 0 {
        hidden_size
            .checked_mul(3)
            .and_then(|width| width.checked_div(4 * num_key_heads))
            .unwrap_or(128)
    } else {
        128
    };
    let key_head_dim = positive("linear_key_head_dim", default_key_head_dim)?;
    let default_value_head_dim = if olmo_hybrid {
        key_head_dim
            .checked_mul(2)
            .context("OLMo Hybrid default linear value-head width overflow")?
    } else {
        128
    };
    let value_head_dim = positive("linear_value_head_dim", default_value_head_dim)?;
    let conv_kernel_size = positive("linear_conv_kernel_dim", 4)?;
    if !num_value_heads.is_multiple_of(num_key_heads) {
        bail!(
            "{family} linear_num_value_heads={num_value_heads} must be divisible by linear_num_key_heads={num_key_heads}"
        );
    }
    Ok((
        conv_kernel_size,
        num_key_heads,
        num_value_heads,
        key_head_dim,
        value_head_dim,
    ))
}

fn take_qwen4_gated_residual(
    store: &mut Gpt2TensorStore,
    prefix: &str,
    hidden_size: usize,
    hc_count: usize,
    hc_lowrank: usize,
    use_combine: bool,
) -> Result<HostQwen4GatedResidual> {
    if hidden_size == 0 || hc_count <= 1 || hc_lowrank == 0 {
        bail!(
            "Qwen4 hyper-connection checkpoint geometry requires positive hidden/lowrank and hc_count > 1"
        );
    }
    let hc_hidden_size = hidden_size
        .checked_mul(hc_count)
        .context("Qwen4 hyper-connection checkpoint width overflow")?;
    Ok(HostQwen4GatedResidual {
        norm_weight: store.take_expected(&format!("{prefix}.hc_norm.weight"), &[hc_hidden_size])?,
        input_mix_weight_down: store.take_expected(
            &format!("{prefix}.input_mix_weight_down.weight"),
            &[hc_lowrank, hc_hidden_size],
        )?,
        input_mix_weight_up: store.take_expected(
            &format!("{prefix}.input_mix_weight_up.weight"),
            &[hc_hidden_size, hc_lowrank],
        )?,
        block_inject_weight: use_combine
            .then(|| {
                store.take_expected(
                    &format!("{prefix}.block_inject_weight.weight"),
                    &[hc_count, hc_hidden_size],
                )
            })
            .transpose()?,
    })
}

fn load_qwen4_hyper_connections(
    model_dir: &Path,
    num_layers: usize,
    hidden_size: usize,
    hc_count: usize,
    hc_lowrank: usize,
) -> Result<(
    Vec<(HostQwen4GatedResidual, HostQwen4GatedResidual)>,
    HostQwen4GatedResidual,
)> {
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let root = if store.contains("model.hyper_connection_mixer.hc_norm.weight") {
        "model"
    } else if store.contains("model.language_model.hyper_connection_mixer.hc_norm.weight") {
        "model.language_model"
    } else {
        bail!(
            "Qwen4 checkpoint is missing model.hyper_connection_mixer or model.language_model.hyper_connection_mixer"
        );
    };
    let mut layers = Vec::with_capacity(num_layers);
    for layer in 0..num_layers {
        let prefix = format!("{root}.layers.{layer}");
        layers.push((
            take_qwen4_gated_residual(
                &mut store,
                &format!("{prefix}.attn_hyper_connection"),
                hidden_size,
                hc_count,
                hc_lowrank,
                true,
            )?,
            take_qwen4_gated_residual(
                &mut store,
                &format!("{prefix}.mlp_hyper_connection"),
                hidden_size,
                hc_count,
                hc_lowrank,
                true,
            )?,
        ));
    }
    let final_mixer = take_qwen4_gated_residual(
        &mut store,
        &format!("{root}.hyper_connection_mixer"),
        hidden_size,
        hc_count,
        hc_lowrank,
        false,
    )?;
    Ok((layers, final_mixer))
}

fn qwen4_eos_token_id(value: &serde_json::Value) -> Result<u32> {
    let raw = value
        .get("eos_token_id")
        .context("Qwen4-Exp PLE requires eos_token_id")?;
    let token = if let Some(token) = raw.as_u64() {
        token
    } else if let Some(tokens) = raw.as_array() {
        tokens
            .first()
            .and_then(serde_json::Value::as_u64)
            .context("Qwen4-Exp eos_token_id list must contain an integer")?
    } else {
        bail!("Qwen4-Exp eos_token_id must be an integer or non-empty integer list");
    };
    u32::try_from(token).context("Qwen4-Exp eos_token_id exceeds u32")
}

/// Load Qwen4 PLE layers without materializing the enormous hashed n-gram
/// embedding table. Every PLE embedding remains a file-backed source and is
/// row-gathered on demand by `VulkanQwen4Ple::prepare_embeddings`.
fn load_qwen4_ple_layers(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
    value: &serde_json::Value,
) -> Result<Vec<Option<HostQwen4Ple>>> {
    if config.architecture != VulkanTransformerArchitecture::Qwen4Exp {
        return Ok((0..config.num_layers).map(|_| None).collect());
    }
    let mut ple_layer_ids = value
        .get("ple_layer_ids")
        .and_then(serde_json::Value::as_array)
        .map(|layers| {
            layers
                .iter()
                .map(|layer| {
                    layer
                        .as_u64()
                        .and_then(|layer| usize::try_from(layer).ok())
                        .context("Qwen4-Exp ple_layer_ids must contain positive integers")
                })
                .collect::<Result<Vec<_>>>()
        })
        .transpose()?
        .unwrap_or_default();
    ple_layer_ids.sort_unstable();
    ple_layer_ids.dedup();
    if ple_layer_ids.is_empty() {
        return Ok((0..config.num_layers).map(|_| None).collect());
    }
    if ple_layer_ids
        .iter()
        .any(|layer| *layer == 0 || *layer > config.num_layers)
    {
        bail!(
            "Qwen4-Exp ple_layer_ids must use one-indexed decoder layers in 1..={}",
            config.num_layers
        );
    }

    let positive = |name: &str, default: usize| -> Result<usize> {
        let value = value
            .get(name)
            .and_then(serde_json::Value::as_u64)
            .and_then(|value| usize::try_from(value).ok())
            .unwrap_or(default);
        if value == 0 {
            bail!("Qwen4-Exp {name} must be positive");
        }
        Ok(value)
    };
    let hc_count = positive("hc_count", 4)?;
    let ple_embed_dim = positive("ple_embed_dim", config.hidden_size)?;
    let conv_kernel_size = positive("ple_conv_kernel_size", 4)?;
    let ngram_size = positive("ngram_size", 3)?;
    let heads_per_ngram = positive("heads_per_ngram", 8)?;
    let ngram_vocab_size_base = positive("ngram_vocab_size_base", 20_000_000)?;
    let ngram_vocab_divisor = positive("make_ngram_vocab_size_divisible_by", 128)?;
    let seed = value
        .get("seed")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(1234);
    let eos_token_id = qwen4_eos_token_id(value)?;
    if hc_count <= 1 || ngram_size < 2 {
        bail!("Qwen4-Exp PLE requires hc_count > 1 and ngram_size >= 2");
    }
    let ngram_heads = (ngram_size - 1)
        .checked_mul(heads_per_ngram)
        .context("Qwen4 PLE n-gram head count overflow")?;
    if !ple_embed_dim.is_multiple_of(ngram_heads) {
        bail!(
            "Qwen4-Exp ple_embed_dim={ple_embed_dim} must be divisible by n-gram head count {ngram_heads}"
        );
    }
    let head_dim = ple_embed_dim / ngram_heads;
    let hc_hidden_size = config
        .hidden_size
        .checked_mul(hc_count)
        .context("Qwen4 PLE hyper width overflow")?;

    let mut store = Gpt2TensorStore::load(model_dir)?;
    let first_layer = ple_layer_ids[0] - 1;
    let root = if store.contains(&format!("model.layers.{first_layer}.ple.key_proj.weight")) {
        "model"
    } else if store.contains(&format!(
        "model.language_model.layers.{first_layer}.ple.key_proj.weight"
    )) {
        "model.language_model"
    } else {
        bail!("Qwen4-Exp checkpoint is missing PLE parameters for configured PLE layers");
    };

    let mut output = (0..config.num_layers).map(|_| None).collect::<Vec<_>>();
    for (ple_layer_index, one_indexed_layer) in ple_layer_ids.into_iter().enumerate() {
        let layer = one_indexed_layer - 1;
        let prefix = format!("{root}.layers.{layer}.ple");
        let layout = Qwen4PleNgramLayout::new(
            config.vocab_size,
            ngram_size,
            heads_per_ngram,
            ngram_vocab_size_base,
            ple_layer_index,
            seed,
        )?;
        let padded_vocab_size = layout
            .total_vocab_size
            .checked_add(ngram_vocab_divisor - 1)
            .context("Qwen4 PLE padded vocabulary overflow")?
            / ngram_vocab_divisor
            * ngram_vocab_divisor;
        let embedding_name = format!("{prefix}.ple_embedding.ngram_embedding.weight");
        let embedding_source =
            store.take_expected_source(&embedding_name, &[padded_vocab_size, head_dim])?;
        let key_proj = HostLinear {
            weight: store.take_expected(
                &format!("{prefix}.key_proj.weight"),
                &[hc_hidden_size, ple_embed_dim],
            )?,
            bias: None,
        };
        let value_proj = HostLinear {
            weight: store.take_expected(
                &format!("{prefix}.value_proj.weight"),
                &[config.hidden_size, ple_embed_dim],
            )?,
            bias: None,
        };
        let norm_key =
            store.take_expected(&format!("{prefix}.norm_key.weight"), &[hc_hidden_size])?;
        let norm_query =
            store.take_expected(&format!("{prefix}.norm_query.weight"), &[hc_hidden_size])?;
        let norm_conv =
            store.take_expected(&format!("{prefix}.norm_conv.weight"), &[hc_hidden_size])?;
        let conv_weight = store.take_expected(
            &format!("{prefix}.conv1d.weight"),
            &[hc_hidden_size, 1, conv_kernel_size],
        )?;
        output[layer] = Some(HostQwen4Ple {
            ple_embed_dim,
            conv_kernel_size,
            eos_token_id,
            embedding_name,
            embedding_source,
            layout,
            key_proj,
            value_proj,
            norm_key,
            norm_query,
            norm_conv,
            conv_weight,
        });
    }
    Ok(output)
}

fn load_qwen_hybrid_gated_delta_nets(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<Option<HostQwenGatedDeltaNet>>>> {
    if !matches!(
        config.architecture,
        VulkanTransformerArchitecture::Qwen3Next
            | VulkanTransformerArchitecture::Qwen35
            | VulkanTransformerArchitecture::Qwen35Moe
            | VulkanTransformerArchitecture::Qwen4Exp
            | VulkanTransformerArchitecture::Glm5Next
            | VulkanTransformerArchitecture::KimiLinear
            | VulkanTransformerArchitecture::OlmoHybrid
    ) {
        return Ok(None);
    }

    let family = match config.architecture {
        VulkanTransformerArchitecture::Qwen3Next => "Qwen3-Next",
        VulkanTransformerArchitecture::Qwen35 => "Qwen3.5",
        VulkanTransformerArchitecture::Qwen35Moe => "Qwen3.5-MoE",
        VulkanTransformerArchitecture::Qwen4Exp => "Qwen4-Exp",
        VulkanTransformerArchitecture::Glm5Next => "GLM-5 Next",
        VulkanTransformerArchitecture::KimiLinear => "KimiLinear",
        VulkanTransformerArchitecture::OlmoHybrid => "OLMo Hybrid",
        _ => unreachable!(),
    };
    let package = transformer_text_config_from_package(model_dir)?;
    let (conv_kernel_size, num_key_heads, num_value_heads, key_head_dim, value_head_dim) =
        if config.architecture == VulkanTransformerArchitecture::Glm5Next {
            let positive = |field: &str| -> Result<usize> {
                package
                    .get(field)
                    .and_then(serde_json::Value::as_u64)
                    .map(|value| value as usize)
                    .filter(|value| *value != 0)
                    .with_context(|| format!("GLM-5 Next {field} must be a positive integer"))
            };
            let conv_kernel_size = positive("linear_conv_kernel_dim")?;
            let num_heads = positive("linear_num_heads")?;
            let head_dim = positive("linear_head_dim")?;
            (conv_kernel_size, num_heads, num_heads, head_dim, head_dim)
        } else if config.architecture == VulkanTransformerArchitecture::KimiLinear {
            let linear = package
                .get("linear_attn_config")
                .and_then(serde_json::Value::as_object)
                .context("KimiLinear config is missing linear_attn_config")?;
            let positive = |field: &str| -> Result<usize> {
                linear
                    .get(field)
                    .and_then(serde_json::Value::as_u64)
                    .map(|value| value as usize)
                    .filter(|value| *value != 0)
                    .with_context(|| {
                        format!("KimiLinear linear_attn_config.{field} must be a positive integer")
                    })
            };
            if linear
                .get("use_full_rank_gate")
                .and_then(serde_json::Value::as_bool)
                != Some(true)
            {
                bail!(
                    "KimiLinear native KDA currently requires linear_attn_config.use_full_rank_gate=true"
                );
            }
            let conv_kernel_size = positive("short_conv_kernel_size")?;
            let num_heads = positive("num_heads")?;
            let head_dim = positive("head_dim")?;
            (conv_kernel_size, num_heads, num_heads, head_dim, head_dim)
        } else {
            qwen_hybrid_attention_geometry(&package, family)?
        };
    let key_dim = num_key_heads
        .checked_mul(key_head_dim)
        .context("Qwen Gated DeltaNet key width overflow")?;
    let value_dim = num_value_heads
        .checked_mul(value_head_dim)
        .context("Qwen Gated DeltaNet value width overflow")?;
    let conv_dim = key_dim
        .checked_mul(2)
        .and_then(|width| width.checked_add(value_dim))
        .context("Qwen Gated DeltaNet convolution width overflow")?;
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context("Qwen hybrid checkpoint is missing its text backbone")?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };

    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        if !config.layer_uses_linear_attention(layer) {
            layers.push(None);
            continue;
        }
        let p = backbone_name(&format!(
            "layers.{layer}.{}",
            if config.architecture == VulkanTransformerArchitecture::KimiLinear {
                "self_attn"
            } else {
                "linear_attn"
            }
        ));
        let projection = if config.architecture == VulkanTransformerArchitecture::Qwen3Next {
            HostQwenGatedDeltaProjection::Qwen3Next {
                qkvz: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.in_proj_qkvz.weight"),
                        &[2 * key_dim + 2 * value_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                ba: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.in_proj_ba.weight"),
                        &[2 * num_value_heads, config.hidden_size],
                    )?,
                    bias: None,
                },
            }
        } else if config.architecture == VulkanTransformerArchitecture::KimiLinear {
            let low_rank = key_head_dim;
            HostQwenGatedDeltaProjection::Kimi {
                q: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.q_proj.weight"),
                        &[key_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                k: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.k_proj.weight"),
                        &[key_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                v: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.v_proj.weight"),
                        &[value_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                forget_a: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.f_a_proj.weight"),
                        &[low_rank, config.hidden_size],
                    )?,
                    bias: None,
                },
                forget_b: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.f_b_proj.weight"),
                        &[key_dim, low_rank],
                    )?,
                    bias: None,
                },
                beta: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.b_proj.weight"),
                        &[num_value_heads, config.hidden_size],
                    )?,
                    bias: None,
                },
                gate: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.g_proj.weight"),
                        &[value_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
            }
        } else if config.architecture == VulkanTransformerArchitecture::Glm5Next {
            let low_rank = key_head_dim;
            HostQwenGatedDeltaProjection::Glm5 {
                q: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.q_proj.weight"),
                        &[key_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                k: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.k_proj.weight"),
                        &[key_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                v: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.v_proj.weight"),
                        &[value_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                forget_a: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.forget_gate.f_a_proj.weight"),
                        &[low_rank, config.hidden_size],
                    )?,
                    bias: None,
                },
                forget_b: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.forget_gate.f_b_proj.weight"),
                        &[key_dim, low_rank],
                    )?,
                    bias: None,
                },
                beta: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.b_proj.weight"),
                        &[num_value_heads, config.hidden_size],
                    )?,
                    bias: None,
                },
                gate_a: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.g_a_proj.weight"),
                        &[low_rank, config.hidden_size],
                    )?,
                    bias: None,
                },
                gate_b: HostLinear {
                    weight: store
                        .take_expected(&format!("{p}.g_b_proj.weight"), &[value_dim, low_rank])?,
                    bias: None,
                },
            }
        } else if config.architecture == VulkanTransformerArchitecture::OlmoHybrid {
            HostQwenGatedDeltaProjection::OlmoHybrid {
                q: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.q_proj.weight"),
                        &[key_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                k: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.k_proj.weight"),
                        &[key_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                v: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.v_proj.weight"),
                        &[value_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                z: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.g_proj.weight"),
                        &[value_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                b: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.b_proj.weight"),
                        &[num_value_heads, config.hidden_size],
                    )?,
                    bias: None,
                },
                a: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.a_proj.weight"),
                        &[num_value_heads, config.hidden_size],
                    )?,
                    bias: None,
                },
            }
        } else {
            HostQwenGatedDeltaProjection::Qwen35 {
                qkv: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.in_proj_qkv.weight"),
                        &[conv_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                z: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.in_proj_z.weight"),
                        &[value_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                b: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.in_proj_b.weight"),
                        &[num_value_heads, config.hidden_size],
                    )?,
                    bias: None,
                },
                a: HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.in_proj_a.weight"),
                        &[num_value_heads, config.hidden_size],
                    )?,
                    bias: None,
                },
            }
        };
        let conv_weight = if config.architecture == VulkanTransformerArchitecture::KimiLinear {
            let mut packed = store.take_expected(
                &format!("{p}.q_conv1d.weight"),
                &[key_dim, conv_kernel_size],
            )?;
            packed.extend(store.take_expected(
                &format!("{p}.k_conv1d.weight"),
                &[key_dim, conv_kernel_size],
            )?);
            packed.extend(store.take_expected(
                &format!("{p}.v_conv1d.weight"),
                &[value_dim, conv_kernel_size],
            )?);
            packed
        } else {
            store.take_expected(
                &format!("{p}.conv1d.weight"),
                &[conv_dim, 1, conv_kernel_size],
            )?
        };
        layers.push(Some(HostQwenGatedDeltaNet {
            projection,
            conv_weight,
            dt_bias: if config.architecture == VulkanTransformerArchitecture::Glm5Next {
                store.take_expected(&format!("{p}.forget_gate.dt_bias"), &[value_dim])?
            } else if config.architecture == VulkanTransformerArchitecture::KimiLinear {
                store.take_expected(&format!("{p}.dt_bias"), &[value_dim])?
            } else {
                store.take_expected(&format!("{p}.dt_bias"), &[num_value_heads])?
            },
            a_log: if config.architecture == VulkanTransformerArchitecture::Glm5Next {
                store.take_expected(&format!("{p}.forget_gate.A_log"), &[num_value_heads])?
            } else {
                store.take_expected(&format!("{p}.A_log"), &[num_value_heads])?
            },
            norm_weight: store.take_expected(
                &if matches!(
                    config.architecture,
                    VulkanTransformerArchitecture::OlmoHybrid
                        | VulkanTransformerArchitecture::Glm5Next
                        | VulkanTransformerArchitecture::KimiLinear
                ) {
                    format!("{p}.o_norm.weight")
                } else {
                    format!("{p}.norm.weight")
                },
                &[value_head_dim],
            )?,
            conv_kernel_size,
            num_key_heads,
            num_value_heads,
            key_head_dim,
            value_head_dim,
            beta_scale: if config.architecture == VulkanTransformerArchitecture::OlmoHybrid
                && package
                    .get("linear_allow_neg_eigval")
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or(true)
            {
                2.0
            } else {
                1.0
            },
            safe_gate_lower_bound: if config.architecture == VulkanTransformerArchitecture::Glm5Next
            {
                package
                    .get("linear_lower_bound")
                    .filter(|value| !value.is_null())
                    .and_then(serde_json::Value::as_f64)
                    .map(|value| value as f32)
            } else if config.architecture == VulkanTransformerArchitecture::KimiLinear {
                package
                    .get("linear_attn_config")
                    .and_then(serde_json::Value::as_object)
                    .and_then(|linear| linear.get("gate_lower_bound"))
                    .filter(|value| !value.is_null())
                    .and_then(serde_json::Value::as_f64)
                    .map(|value| value as f32)
            } else {
                None
            },
            norm_epsilon: if config.architecture == VulkanTransformerArchitecture::OlmoHybrid {
                1.0e-5
            } else {
                1.0e-6
            },
        }));
    }
    Ok(Some(layers))
}

fn split_qwen_hybrid_query_gate(
    packed: &[f32],
    hidden_size: usize,
    num_heads: usize,
    head_dim: usize,
) -> Result<(Vec<f32>, Vec<f32>)> {
    let query_width = num_heads
        .checked_mul(head_dim)
        .context("Qwen hybrid query width overflow")?;
    if packed.len() != 2 * query_width * hidden_size {
        bail!("Qwen hybrid gated q_proj has an unexpected tensor length");
    }
    let mut query = Vec::with_capacity(query_width * hidden_size);
    let mut gate = Vec::with_capacity(query_width * hidden_size);
    let head_stride = 2 * head_dim * hidden_size;
    let half_stride = head_dim * hidden_size;
    for head in 0..num_heads {
        let base = head * head_stride;
        query.extend_from_slice(&packed[base..base + half_stride]);
        gate.extend_from_slice(&packed[base + half_stride..base + head_stride]);
    }
    Ok((query, gate))
}

fn split_qwen_hybrid_query_gate_bias(
    packed: &[f32],
    num_heads: usize,
    head_dim: usize,
) -> Result<(Vec<f32>, Vec<f32>)> {
    let query_width = num_heads
        .checked_mul(head_dim)
        .context("Qwen hybrid query-bias width overflow")?;
    if packed.len() != 2 * query_width {
        bail!("Qwen hybrid gated q_proj bias has an unexpected tensor length");
    }
    let mut query = Vec::with_capacity(query_width);
    let mut gate = Vec::with_capacity(query_width);
    for head in 0..num_heads {
        let base = head * 2 * head_dim;
        query.extend_from_slice(&packed[base..base + head_dim]);
        gate.extend_from_slice(&packed[base + head_dim..base + 2 * head_dim]);
    }
    Ok((query, gate))
}

fn pack_qwen_hybrid_query_gate(
    query: &[f32],
    gate: &[f32],
    hidden_size: usize,
    num_heads: usize,
    head_dim: usize,
) -> Result<Vec<f32>> {
    let query_width = num_heads
        .checked_mul(head_dim)
        .context("Qwen hybrid query width overflow")?;
    let half_stride = head_dim
        .checked_mul(hidden_size)
        .context("Qwen hybrid q_proj head stride overflow")?;
    let expected = query_width
        .checked_mul(hidden_size)
        .context("Qwen hybrid q_proj tensor size overflow")?;
    if query.len() != expected || gate.len() != expected {
        bail!("Qwen hybrid query/gate projections have unexpected tensor lengths");
    }
    let mut packed = Vec::with_capacity(2 * expected);
    for head in 0..num_heads {
        let start = head * half_stride;
        let end = start + half_stride;
        packed.extend_from_slice(&query[start..end]);
        packed.extend_from_slice(&gate[start..end]);
    }
    Ok(packed)
}

fn pack_qwen_hybrid_query_gate_bias(
    query: &[f32],
    gate: &[f32],
    num_heads: usize,
    head_dim: usize,
) -> Result<Vec<f32>> {
    let query_width = num_heads
        .checked_mul(head_dim)
        .context("Qwen hybrid query-bias width overflow")?;
    if query.len() != query_width || gate.len() != query_width {
        bail!("Qwen hybrid query/gate biases have unexpected tensor lengths");
    }
    let mut packed = Vec::with_capacity(2 * query_width);
    for head in 0..num_heads {
        let start = head * head_dim;
        let end = start + head_dim;
        packed.extend_from_slice(&query[start..end]);
        packed.extend_from_slice(&gate[start..end]);
    }
    Ok(packed)
}

fn load_qwen_hybrid_attention_gates(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<Option<HostLinear>>>> {
    if !matches!(
        config.architecture,
        VulkanTransformerArchitecture::Qwen3Next
            | VulkanTransformerArchitecture::Qwen35
            | VulkanTransformerArchitecture::Qwen35Moe
            | VulkanTransformerArchitecture::Qwen4Exp
            | VulkanTransformerArchitecture::KimiLinear
    ) {
        return Ok(None);
    }
    let package = transformer_text_config_from_package(model_dir)?;
    let kimi_mla_output_gate = config.architecture == VulkanTransformerArchitecture::KimiLinear
        && package
            .get("mla_use_output_gate")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
    let attention_bias = package
        .get("attention_bias")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context("Qwen hybrid checkpoint is missing its text backbone")?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };
    let q = config.query_hidden_size();
    let mut gates = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        if config.layer_uses_linear_attention(layer) {
            gates.push(None);
            continue;
        }
        if config.architecture == VulkanTransformerArchitecture::KimiLinear {
            if !kimi_mla_output_gate {
                gates.push(None);
                continue;
            }
            let v_head_dim = package
                .get("v_head_dim")
                .and_then(serde_json::Value::as_u64)
                .map(|value| value as usize)
                .filter(|value| *value != 0)
                .context("KimiLinear v_head_dim must be a positive integer")?;
            let gate_width = config
                .num_heads
                .checked_mul(v_head_dim)
                .context("KimiLinear MLA output-gate width overflow")?;
            let p = backbone_name(&format!("layers.{layer}.self_attn.g_proj"));
            gates.push(Some(HostLinear {
                weight: store.take_expected(
                    &format!("{p}.weight"),
                    &[gate_width, config.hidden_size],
                )?,
                bias: None,
            }));
            continue;
        }
        let p = backbone_name(&format!("layers.{layer}.self_attn.q_proj"));
        let packed = store.take_expected(&format!("{p}.weight"), &[2 * q, config.hidden_size])?;
        let (_, gate_weight) = split_qwen_hybrid_query_gate(
            &packed,
            config.hidden_size,
            config.num_heads,
            config.head_dim,
        )?;
        let gate_bias = if attention_bias {
            let packed_bias = store.take_expected(&format!("{p}.bias"), &[2 * q])?;
            let (_, gate_bias) =
                split_qwen_hybrid_query_gate_bias(&packed_bias, config.num_heads, config.head_dim)?;
            Some(gate_bias)
        } else {
            None
        };
        gates.push(Some(HostLinear {
            weight: gate_weight,
            bias: gate_bias,
        }));
    }
    Ok(Some(gates))
}

fn load_llama_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let package_model_type = transformer_package_model_type(model_dir)?;
    let mllama_source_layers = if matches!(
        package_model_type.as_deref(),
        Some("mllama") | Some("mllama_text_model")
    ) {
        let text_config = transformer_text_config_from_package(model_dir)?;
        let layers = VulkanTransformerConfig::mllama_text_self_attention_layers(&text_config)?;
        if layers.len() != config.num_layers {
            bail!(
                "Mllama text-only layer map has {} self-attention layers, but the Vulkan config contains {} layers",
                layers.len(),
                config.num_layers
            );
        }
        Some(layers)
    } else {
        None
    };
    let d = config.hidden_size;
    let q = config.query_hidden_size();
    let kv = config.key_value_hidden_size();
    let optional_qkv_bias = config.architecture == VulkanTransformerArchitecture::StableLm;
    let layer_norm_bias = matches!(
        config.architecture,
        VulkanTransformerArchitecture::StableLm
            | VulkanTransformerArchitecture::Jais2
            | VulkanTransformerArchitecture::Nemotron
    );
    let parameter_free_layer_norm = config.uses_parameter_free_layer_norm();
    let package_config = if config.architecture.uses_configurable_attention_bias()
        || matches!(
            config.architecture,
            VulkanTransformerArchitecture::StableLm
                | VulkanTransformerArchitecture::OpenLlama
                | VulkanTransformerArchitecture::Qwen2
                | VulkanTransformerArchitecture::Qwen2Moe
                | VulkanTransformerArchitecture::Jais2
                | VulkanTransformerArchitecture::Nemotron
                | VulkanTransformerArchitecture::SeedOss
                | VulkanTransformerArchitecture::Glm
                | VulkanTransformerArchitecture::Glm4
                | VulkanTransformerArchitecture::Glm4Moe
                | VulkanTransformerArchitecture::Ernie45
                | VulkanTransformerArchitecture::Ernie45Moe
                | VulkanTransformerArchitecture::Gemma2
                | VulkanTransformerArchitecture::Gemma3
                | VulkanTransformerArchitecture::VaultGemma
                | VulkanTransformerArchitecture::NanoChat
                | VulkanTransformerArchitecture::HyperClovax
                | VulkanTransformerArchitecture::Apertus
                | VulkanTransformerArchitecture::MiMoV2Flash
                | VulkanTransformerArchitecture::Qwen3Next
                | VulkanTransformerArchitecture::Qwen35
                | VulkanTransformerArchitecture::Qwen35Moe
                | VulkanTransformerArchitecture::Qwen4Exp
                | VulkanTransformerArchitecture::OlmoHybrid
                | VulkanTransformerArchitecture::KimiLinear
        ) {
        Some(transformer_text_config_from_package(model_dir)?)
    } else {
        None
    };
    let mimo_layer_types = if config.architecture == VulkanTransformerArchitecture::MiMoV2Flash {
        Some(VulkanTransformerConfig::mimo_v2_flash_layer_types(
            package_config
                .as_ref()
                .context("MiMo-V2-Flash package config is unavailable while loading weights")?,
            config.num_layers,
        )?)
    } else {
        None
    };
    let mimo_v_head_dim = if config.architecture == VulkanTransformerArchitecture::MiMoV2Flash {
        Some(VulkanTransformerConfig::mimo_v2_flash_v_head_dim(
            package_config
                .as_ref()
                .context("MiMo-V2-Flash package config is unavailable while loading weights")?,
        )?)
    } else {
        None
    };
    let mla_v_head_dim = if matches!(
        config.architecture,
        VulkanTransformerArchitecture::DeepseekV2
            | VulkanTransformerArchitecture::MiniCpm3
            | VulkanTransformerArchitecture::DeepseekV3
            | VulkanTransformerArchitecture::Glm5Next
            | VulkanTransformerArchitecture::KimiLinear
            | VulkanTransformerArchitecture::Axk1
            | VulkanTransformerArchitecture::Mistral4
            | VulkanTransformerArchitecture::Youtu
    ) {
        Some(
            package_config
                .as_ref()
                .and_then(|value| value.get("v_head_dim"))
                .and_then(serde_json::Value::as_u64)
                .map(|value| value as usize)
                .context("MLA package config is missing integer v_head_dim")?,
        )
    } else {
        None
    };
    let qwen2_attention_bias = package_config
        .as_ref()
        .filter(|_| {
            matches!(
                config.architecture,
                VulkanTransformerArchitecture::Qwen2 | VulkanTransformerArchitecture::Qwen2Moe
            )
        })
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let qwen_hybrid_attention_bias = package_config
        .as_ref()
        .filter(|_| {
            matches!(
                config.architecture,
                VulkanTransformerArchitecture::Qwen3Next
                    | VulkanTransformerArchitecture::Qwen35
                    | VulkanTransformerArchitecture::Qwen35Moe
                    | VulkanTransformerArchitecture::Qwen4Exp
            )
        })
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let configurable_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture.uses_configurable_attention_bias())
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(config.architecture == VulkanTransformerArchitecture::GptOss);
    let configurable_mlp_bias = package_config
        .as_ref()
        .filter(|_| config.architecture.uses_configurable_mlp_bias())
        .and_then(|value| value.get("mlp_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let open_llama_stable_embedding = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::OpenLlama)
        .and_then(|value| value.get("use_stable_embedding"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let stablelm_qk_layernorm = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::StableLm)
        .and_then(|value| value.get("qk_layernorm"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let cohere_qk_layernorm = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Cohere)
        .and_then(|value| value.get("use_qk_norm"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let cohere_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Cohere)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let cohere2_attention_bias = package_config
        .as_ref()
        .filter(|_| {
            matches!(
                config.architecture,
                VulkanTransformerArchitecture::Cohere2 | VulkanTransformerArchitecture::Cohere2Moe
            )
        })
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let jais2_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Jais2)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let jais2_mlp_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Jais2)
        .and_then(|value| value.get("mlp_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let nemotron_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Nemotron)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let nemotron_mlp_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Nemotron)
        .and_then(|value| value.get("mlp_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let seed_oss_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::SeedOss)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let seed_oss_attention_out_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::SeedOss)
        .and_then(|value| value.get("attention_out_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let seed_oss_mlp_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::SeedOss)
        .and_then(|value| value.get("mlp_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let glm4v_moe_text = package_config
        .as_ref()
        .and_then(|value| value.get("model_type"))
        .and_then(serde_json::Value::as_str)
        == Some("glm4v_moe_text");
    let glm_attention_bias = package_config
        .as_ref()
        .filter(|_| {
            matches!(
                config.architecture,
                VulkanTransformerArchitecture::Glm
                    | VulkanTransformerArchitecture::Glm4
                    | VulkanTransformerArchitecture::Glm4Moe
            )
        })
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(glm4v_moe_text || config.architecture != VulkanTransformerArchitecture::Glm4Moe);
    let glm4_moe_qk_norm = package_config
        .as_ref()
        .filter(|_| {
            config.architecture == VulkanTransformerArchitecture::Glm4Moe && !glm4v_moe_text
        })
        .and_then(|value| value.get("use_qk_norm"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let ernie_use_bias = package_config
        .as_ref()
        .filter(|_| {
            matches!(
                config.architecture,
                VulkanTransformerArchitecture::Ernie45 | VulkanTransformerArchitecture::Ernie45Moe
            )
        })
        .and_then(|value| value.get("use_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let gemma2_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Gemma2)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let gemma3_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Gemma3)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let vault_gemma_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::VaultGemma)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let nanochat_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::NanoChat)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let hyperclovax_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::HyperClovax)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let hyperclovax_mlp_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::HyperClovax)
        .and_then(|value| value.get("mlp_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let apertus_attention_bias = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Apertus)
        .and_then(|value| value.get("attention_bias"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let llama4_use_qk_norm = package_config
        .as_ref()
        .filter(|_| config.architecture == VulkanTransformerArchitecture::Llama4Text)
        .and_then(|value| value.get("use_qk_norm"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let llama4_rotary_layers = if config.architecture == VulkanTransformerArchitecture::Llama4Text {
        Some(VulkanTransformerConfig::llama4_rotary_layers(
            package_config
                .as_ref()
                .context("Llama 4 text package config is unavailable while loading weights")?,
            config.num_layers,
        )?)
    } else {
        None
    };
    let laguna_heads_per_layer = if config.architecture == VulkanTransformerArchitecture::Laguna {
        Some(VulkanTransformerConfig::laguna_attention_heads_per_layer(
            package_config
                .as_ref()
                .context("Laguna package config is unavailable while loading weights")?,
            config.num_layers,
            config.num_heads,
            config.num_key_value_heads,
        )?)
    } else {
        None
    };
    let hf_layer_norm_weight = |mut weight: Vec<f32>| {
        if config.architecture == VulkanTransformerArchitecture::Nemotron {
            for value in &mut weight {
                *value += 1.0;
            }
        }
        weight
    };
    // Most decoder-only packages save the text backbone under `model.*`.
    // Multimodal wrappers such as Qwen2-VL keep the exact same language model
    // under `model.language_model.*`, while a directly-saved bare text model
    // can omit the wrapper prefix entirely. Resolve the prefix from the actual
    // tensor inventory so one mathematically identical Vulkan graph can load
    // each canonical Hugging Face packaging form without renaming files.
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
        .into_iter()
        .find(|prefix| {
            let name = if prefix.is_empty() {
                "embed_tokens.weight".to_owned()
            } else {
                format!("{prefix}.embed_tokens.weight")
            };
            store.contains(&name)
        })
        .context(
            "Llama-layout checkpoint is missing an embed_tokens weight under model, model.language_model, model.text_model, language_model, or the bare text-model prefix",
        )?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };
    let token_embedding_name = backbone_name("embed_tokens.weight");
    let token_embedding = if mllama_source_layers.is_some() {
        // MllamaTextModel deliberately allocates eight reserved multimodal
        // token rows beyond config.vocab_size. Text logits still cover only
        // config.vocab_size, so keep those rows outside the native text-only
        // graph and restore them from the source package on export.
        store.take_expected_row_prefix(&token_embedding_name, config.vocab_size, d, 8)?
    } else {
        store.take_expected(&token_embedding_name, &[config.vocab_size, d])?
    };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let i = config.layer_intermediate_size(layer);
        let source_layer = mllama_source_layers
            .as_ref()
            .map(|layers| layers[layer])
            .unwrap_or(layer);
        let p = backbone_name(&format!("layers.{source_layer}"));
        let post_sublayer_norm = config.layer_uses_post_sublayer_norm(layer);
        let qwen_hybrid = matches!(
            config.architecture,
            VulkanTransformerArchitecture::Qwen3Next
                | VulkanTransformerArchitecture::Qwen35
                | VulkanTransformerArchitecture::Qwen35Moe
                | VulkanTransformerArchitecture::Qwen4Exp
        );
        let hybrid_gated_delta = qwen_hybrid
            || matches!(
                config.architecture,
                VulkanTransformerArchitecture::OlmoHybrid
                    | VulkanTransformerArchitecture::Glm5Next
                    | VulkanTransformerArchitecture::KimiLinear
            );
        let qwen_linear_attention = hybrid_gated_delta && config.layer_uses_linear_attention(layer);
        let kimi_sparse_moe = config.architecture == VulkanTransformerArchitecture::KimiLinear
            && config.layer_uses_moe(layer);
        let layer_num_key_value_heads = if mimo_layer_types
            .as_ref()
            .is_some_and(|layer_types| layer_types[layer] == "sliding_attention")
        {
            config
                .num_key_value_heads
                .checked_mul(2)
                .context("MiMo-V2-Flash sliding-attention KV-head count overflow")?
        } else {
            config.num_key_value_heads
        };
        let layer_num_heads = laguna_heads_per_layer
            .as_ref()
            .map(|heads| heads[layer])
            .unwrap_or(config.num_heads);
        let query_hidden = if config.architecture == VulkanTransformerArchitecture::Laguna {
            layer_num_heads
                .checked_mul(config.head_dim)
                .context("Laguna query projection width overflow")?
        } else {
            q
        };
        let key_hidden = if config.architecture == VulkanTransformerArchitecture::MiMoV2Flash {
            layer_num_key_value_heads
                .checked_mul(config.head_dim)
                .context("MiMo-V2-Flash key projection width overflow")?
        } else {
            kv
        };
        let value_hidden = if let Some(v_head_dim) = mimo_v_head_dim.or(mla_v_head_dim) {
            layer_num_key_value_heads
                .checked_mul(v_head_dim)
                .context("Transformer value projection width overflow")?
        } else {
            kv
        };
        let attention_hidden = if let Some(v_head_dim) = mimo_v_head_dim.or(mla_v_head_dim) {
            layer_num_heads
                .checked_mul(v_head_dim)
                .context("Transformer attention output width overflow")?
        } else {
            query_hidden
        };
        let ln1 = if config.architecture == VulkanTransformerArchitecture::Qwen4Exp {
            // Qwen4 replaces the ordinary decoder pre-norm/residual wrapper
            // with its learned hyper-connection mixer. Keep an inert norm in
            // the generic layer slot so the mature attention/MLP kernels can
            // stay shared without requiring checkpoint parameters that do not
            // exist in the HF Qwen4 decoder layer.
            HostLayerNorm {
                weight: vec![1.0; d],
                bias: Vec::new(),
            }
        } else if post_sublayer_norm {
            HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.post_attention_layernorm.weight"), &[d])?,
                bias: Vec::new(),
            }
        } else if parameter_free_layer_norm {
            HostLayerNorm {
                weight: vec![1.0; d],
                bias: Vec::new(),
            }
        } else {
            HostLayerNorm {
                weight: hf_layer_norm_weight(store.take_expected(
                    &if config.architecture == VulkanTransformerArchitecture::Apertus {
                        format!("{p}.attention_layernorm.weight")
                    } else {
                        format!("{p}.input_layernorm.weight")
                    },
                    &[d],
                )?),
                bias: if layer_norm_bias {
                    store.take_expected(&format!("{p}.input_layernorm.bias"), &[d])?
                } else {
                    Vec::new()
                },
            }
        };
        let q_proj = if qwen_linear_attention
            || config.architecture == VulkanTransformerArchitecture::KimiLinear
            || matches!(
                config.architecture,
                VulkanTransformerArchitecture::DeepseekV2
                    | VulkanTransformerArchitecture::MiniCpm3
                    | VulkanTransformerArchitecture::DeepseekV3
                    | VulkanTransformerArchitecture::DeepseekV4
                    | VulkanTransformerArchitecture::Axk1
                    | VulkanTransformerArchitecture::Mistral4
                    | VulkanTransformerArchitecture::Youtu
            ) {
            None
        } else if qwen_hybrid {
            let packed_weight =
                store.take_expected(&format!("{p}.self_attn.q_proj.weight"), &[2 * q, d])?;
            let (weight, _) =
                split_qwen_hybrid_query_gate(&packed_weight, d, config.num_heads, config.head_dim)?;
            let bias = if qwen_hybrid_attention_bias {
                let packed_bias =
                    store.take_expected(&format!("{p}.self_attn.q_proj.bias"), &[2 * q])?;
                let (bias, _) = split_qwen_hybrid_query_gate_bias(
                    &packed_bias,
                    config.num_heads,
                    config.head_dim,
                )?;
                Some(bias)
            } else {
                None
            };
            Some(HostLinear { weight, bias })
        } else {
            Some(HostLinear {
                weight: store
                    .take_expected(&format!("{p}.self_attn.q_proj.weight"), &[query_hidden, d])?,
                bias: if qwen2_attention_bias
                    && matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Qwen2
                            | VulkanTransformerArchitecture::Qwen2Moe
                    )
                    || configurable_attention_bias
                    || (config.architecture == VulkanTransformerArchitecture::Jais2
                        && jais2_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Nemotron
                        && nemotron_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::SeedOss
                        && seed_oss_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Glm
                            | VulkanTransformerArchitecture::Glm4
                            | VulkanTransformerArchitecture::Glm4Moe
                    ) && glm_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Ernie45
                            | VulkanTransformerArchitecture::Ernie45Moe
                    ) && ernie_use_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Gemma2
                        && gemma2_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Gemma3
                        && gemma3_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::VaultGemma
                        && vault_gemma_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::NanoChat
                        && nanochat_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::HyperClovax
                        && hyperclovax_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Apertus
                        && apertus_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Cohere
                        && cohere_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Cohere2
                            | VulkanTransformerArchitecture::Cohere2Moe
                    ) && cohere2_attention_bias)
                    || (optional_qkv_bias && store.contains(&format!("{p}.self_attn.q_proj.bias")))
                {
                    Some(
                        store.take_expected(
                            &format!("{p}.self_attn.q_proj.bias"),
                            &[query_hidden],
                        )?,
                    )
                } else {
                    None
                },
            })
        };
        let k_proj = if qwen_linear_attention
            || config.architecture == VulkanTransformerArchitecture::KimiLinear
            || matches!(
                config.architecture,
                VulkanTransformerArchitecture::DeepseekV2
                    | VulkanTransformerArchitecture::MiniCpm3
                    | VulkanTransformerArchitecture::DeepseekV3
                    | VulkanTransformerArchitecture::DeepseekV4
                    | VulkanTransformerArchitecture::Axk1
                    | VulkanTransformerArchitecture::Mistral4
                    | VulkanTransformerArchitecture::Youtu
            ) {
            None
        } else {
            Some(HostLinear {
                weight: store
                    .take_expected(&format!("{p}.self_attn.k_proj.weight"), &[key_hidden, d])?,
                bias: if qwen2_attention_bias
                    && matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Qwen2
                            | VulkanTransformerArchitecture::Qwen2Moe
                    )
                    || configurable_attention_bias
                    || (config.architecture == VulkanTransformerArchitecture::Jais2
                        && jais2_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Nemotron
                        && nemotron_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::SeedOss
                        && seed_oss_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Glm
                            | VulkanTransformerArchitecture::Glm4
                            | VulkanTransformerArchitecture::Glm4Moe
                    ) && glm_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Ernie45
                            | VulkanTransformerArchitecture::Ernie45Moe
                    ) && ernie_use_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Gemma2
                        && gemma2_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Gemma3
                        && gemma3_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::VaultGemma
                        && vault_gemma_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::NanoChat
                        && nanochat_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::HyperClovax
                        && hyperclovax_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Apertus
                        && apertus_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Cohere
                        && cohere_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Cohere2
                            | VulkanTransformerArchitecture::Cohere2Moe
                    ) && cohere2_attention_bias)
                    || (qwen_hybrid && qwen_hybrid_attention_bias)
                    || (optional_qkv_bias && store.contains(&format!("{p}.self_attn.k_proj.bias")))
                {
                    Some(
                        store
                            .take_expected(&format!("{p}.self_attn.k_proj.bias"), &[key_hidden])?,
                    )
                } else {
                    None
                },
            })
        };
        let v_proj = if qwen_linear_attention
            || config.architecture == VulkanTransformerArchitecture::KimiLinear
            || matches!(
                config.architecture,
                VulkanTransformerArchitecture::DeepseekV2
                    | VulkanTransformerArchitecture::MiniCpm3
                    | VulkanTransformerArchitecture::DeepseekV3
                    | VulkanTransformerArchitecture::DeepseekV4
                    | VulkanTransformerArchitecture::Axk1
                    | VulkanTransformerArchitecture::Mistral4
                    | VulkanTransformerArchitecture::Youtu
            ) {
            None
        } else {
            Some(HostLinear {
                weight: store
                    .take_expected(&format!("{p}.self_attn.v_proj.weight"), &[value_hidden, d])?,
                bias: if qwen2_attention_bias
                    && matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Qwen2
                            | VulkanTransformerArchitecture::Qwen2Moe
                    )
                    || configurable_attention_bias
                    || (config.architecture == VulkanTransformerArchitecture::Jais2
                        && jais2_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Nemotron
                        && nemotron_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::SeedOss
                        && seed_oss_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Glm
                            | VulkanTransformerArchitecture::Glm4
                            | VulkanTransformerArchitecture::Glm4Moe
                    ) && glm_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Ernie45
                            | VulkanTransformerArchitecture::Ernie45Moe
                    ) && ernie_use_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Gemma2
                        && gemma2_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Gemma3
                        && gemma3_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::VaultGemma
                        && vault_gemma_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::NanoChat
                        && nanochat_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::HyperClovax
                        && hyperclovax_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Apertus
                        && apertus_attention_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Cohere
                        && cohere_attention_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Cohere2
                            | VulkanTransformerArchitecture::Cohere2Moe
                    ) && cohere2_attention_bias)
                    || (qwen_hybrid && qwen_hybrid_attention_bias)
                    || (optional_qkv_bias && store.contains(&format!("{p}.self_attn.v_proj.bias")))
                {
                    Some(
                        store.take_expected(
                            &format!("{p}.self_attn.v_proj.bias"),
                            &[value_hidden],
                        )?,
                    )
                } else {
                    None
                },
            })
        };
        let (q_norm, k_norm) = if qwen_linear_attention {
            (None, None)
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::Gemma3
                | VulkanTransformerArchitecture::Gemma4
                | VulkanTransformerArchitecture::MiniMaxM3VLText
                | VulkanTransformerArchitecture::Qwen3Next
                | VulkanTransformerArchitecture::Qwen35
                | VulkanTransformerArchitecture::Qwen35Moe
                | VulkanTransformerArchitecture::Qwen4Exp
        ) {
            (
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.q_norm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.k_norm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
            )
        } else if config.architecture == VulkanTransformerArchitecture::NanoChat
            || (config.architecture == VulkanTransformerArchitecture::Llama4Text
                && llama4_use_qk_norm
                && llama4_rotary_layers
                    .as_ref()
                    .is_some_and(|layers| layers[layer]))
        {
            (
                Some(HostLayerNorm {
                    weight: vec![1.0; config.head_dim],
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: vec![1.0; config.head_dim],
                    bias: Vec::new(),
                }),
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::Olmo2
                | VulkanTransformerArchitecture::Olmo3
                | VulkanTransformerArchitecture::OlmoHybrid
                | VulkanTransformerArchitecture::Olmoe
                | VulkanTransformerArchitecture::FlexOlmo
                | VulkanTransformerArchitecture::MiniMaxM2
        ) {
            (
                Some(HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.self_attn.q_norm.weight"), &[q])?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.self_attn.k_norm.weight"), &[kv])?,
                    bias: Vec::new(),
                }),
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::HunYuanDenseV1
                | VulkanTransformerArchitecture::HunYuanMoeV1
        ) {
            (
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.query_layernorm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.key_layernorm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::Afmoe
                | VulkanTransformerArchitecture::Laguna
                | VulkanTransformerArchitecture::HyV3
                | VulkanTransformerArchitecture::Qwen3
                | VulkanTransformerArchitecture::Qwen3Moe
                | VulkanTransformerArchitecture::Dots1
                | VulkanTransformerArchitecture::Mellum
                | VulkanTransformerArchitecture::Exaone4
                | VulkanTransformerArchitecture::Apertus
        ) {
            (
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.q_norm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.k_norm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
            )
        } else if glm4_moe_qk_norm {
            (
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.q_norm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.k_norm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
            )
        } else if cohere_qk_layernorm {
            (
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.q_norm.weight"),
                        &[config.num_heads, config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{p}.self_attn.k_norm.weight"),
                        &[config.num_key_value_heads, config.head_dim],
                    )?,
                    bias: Vec::new(),
                }),
            )
        } else if stablelm_qk_layernorm {
            let mut q_weight = Vec::with_capacity(q);
            for head in 0..config.num_heads {
                q_weight.extend(store.take_expected(
                    &format!("{p}.self_attn.q_layernorm.norms.{head}.weight"),
                    &[config.head_dim],
                )?);
            }
            let mut k_weight = Vec::with_capacity(kv);
            for head in 0..config.num_key_value_heads {
                k_weight.extend(store.take_expected(
                    &format!("{p}.self_attn.k_layernorm.norms.{head}.weight"),
                    &[config.head_dim],
                )?);
            }
            (
                Some(HostLayerNorm {
                    weight: q_weight,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: k_weight,
                    bias: Vec::new(),
                }),
            )
        } else {
            (None, None)
        };
        let c_proj = if config.architecture == VulkanTransformerArchitecture::DeepseekV4 {
            // The dedicated DeepSeek-V4 attention object owns both o_a_proj and
            // o_b_proj. Keep a tiny inert host placeholder for the generic
            // layer ABI; VulkanTransformerLayer::new mirrors this with a 1x1
            // device-side placeholder and never executes it for V4.
            HostLinear {
                weight: vec![0.0],
                bias: None,
            }
        } else {
            HostLinear {
                weight: if qwen_linear_attention {
                    let package = package_config.as_ref().context(
                        "hybrid Gated DeltaNet package config is unavailable while loading weights",
                    )?;
                    let (linear_value_dim, output_name) =
                        if config.architecture == VulkanTransformerArchitecture::KimiLinear {
                            let linear = package
                                .get("linear_attn_config")
                                .and_then(serde_json::Value::as_object)
                                .context("KimiLinear config is missing linear_attn_config")?;
                            let positive = |field: &str| -> Result<usize> {
                                linear
                                    .get(field)
                                    .and_then(serde_json::Value::as_u64)
                                    .and_then(|value| usize::try_from(value).ok())
                                    .filter(|value| *value != 0)
                                    .with_context(|| {
                                        format!(
                                            "KimiLinear linear_attn_config.{field} must be a positive integer"
                                        )
                                    })
                            };
                            let linear_value_dim = positive("num_heads")?
                                .checked_mul(positive("head_dim")?)
                                .context("KimiLinear KDA output width overflow")?;
                            (linear_value_dim, format!("{p}.self_attn.o_proj.weight"))
                        } else {
                            let family = match config.architecture {
                                VulkanTransformerArchitecture::OlmoHybrid => "OLMo Hybrid",
                                VulkanTransformerArchitecture::Glm5Next => "GLM-5 Next",
                                _ => "Qwen hybrid",
                            };
                            let (_, _, num_value_heads, _, value_head_dim) =
                                qwen_hybrid_attention_geometry(package, family)?;
                            let linear_value_dim = num_value_heads
                                .checked_mul(value_head_dim)
                                .context("hybrid Gated DeltaNet value width overflow")?;
                            let output_name = if matches!(
                                config.architecture,
                                VulkanTransformerArchitecture::OlmoHybrid
                                    | VulkanTransformerArchitecture::Glm5Next
                            ) {
                                format!("{p}.linear_attn.o_proj.weight")
                            } else {
                                format!("{p}.linear_attn.out_proj.weight")
                            };
                            (linear_value_dim, output_name)
                        };
                    store.take_expected(&output_name, &[d, linear_value_dim])?
                } else {
                    store.take_expected(
                        &format!("{p}.self_attn.o_proj.weight"),
                        &[d, attention_hidden],
                    )?
                },
                bias: if !qwen_linear_attention
                    && ((config
                        .architecture
                        .uses_configurable_attention_output_bias()
                        && configurable_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::Jais2
                            && jais2_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::Nemotron
                            && nemotron_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::SeedOss
                            && seed_oss_attention_out_bias)
                        || (matches!(
                            config.architecture,
                            VulkanTransformerArchitecture::Ernie45
                                | VulkanTransformerArchitecture::Ernie45Moe
                        ) && ernie_use_bias)
                        || (config.architecture == VulkanTransformerArchitecture::Gemma2
                            && gemma2_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::Gemma3
                            && gemma3_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::VaultGemma
                            && vault_gemma_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::NanoChat
                            && nanochat_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::HyperClovax
                            && hyperclovax_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::Apertus
                            && apertus_attention_bias)
                        || (config.architecture == VulkanTransformerArchitecture::Cohere
                            && cohere_attention_bias)
                        || (matches!(
                            config.architecture,
                            VulkanTransformerArchitecture::Cohere2
                                | VulkanTransformerArchitecture::Cohere2Moe
                        ) && cohere2_attention_bias)
                        || (qwen_hybrid && qwen_hybrid_attention_bias))
                {
                    Some(store.take_expected(&format!("{p}.self_attn.o_proj.bias"), &[d])?)
                } else {
                    None
                },
            }
        };
        let ln2 = if config.architecture == VulkanTransformerArchitecture::Qwen4Exp {
            HostLayerNorm {
                weight: vec![1.0; d],
                bias: Vec::new(),
            }
        } else if config.architecture == VulkanTransformerArchitecture::Afmoe {
            HostLayerNorm {
                weight: store.take_expected(&format!("{p}.pre_mlp_layernorm.weight"), &[d])?,
                bias: Vec::new(),
            }
        } else if config.architecture == VulkanTransformerArchitecture::Glm4 {
            HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.post_attention_layernorm.weight"), &[d])?,
                bias: Vec::new(),
            }
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::Gemma2
                | VulkanTransformerArchitecture::Gemma3
                | VulkanTransformerArchitecture::Gemma4
                | VulkanTransformerArchitecture::VaultGemma
        ) {
            HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.pre_feedforward_layernorm.weight"), &[d])?,
                bias: Vec::new(),
            }
        } else if post_sublayer_norm {
            HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.post_feedforward_layernorm.weight"), &[d])?,
                bias: Vec::new(),
            }
        } else if config.shared_pre_norm {
            ln1.clone()
        } else if parameter_free_layer_norm {
            HostLayerNorm {
                weight: vec![1.0; d],
                bias: Vec::new(),
            }
        } else {
            HostLayerNorm {
                weight: hf_layer_norm_weight(store.take_expected(
                    &if config.architecture == VulkanTransformerArchitecture::Apertus {
                        format!("{p}.feedforward_layernorm.weight")
                    } else {
                        format!("{p}.post_attention_layernorm.weight")
                    },
                    &[d],
                )?),
                bias: if layer_norm_bias {
                    store.take_expected(&format!("{p}.post_attention_layernorm.bias"), &[d])?
                } else {
                    Vec::new()
                },
            }
        };
        let (c_gate, c_fc) = if kimi_sparse_moe {
            // The real Kimi sparse layer is fully owned by VulkanMoe, including
            // the latent down/norm/up shell and every routed expert. Keep only
            // inert shape-correct placeholders in the generic dense-MLP slots;
            // they are never executed for an MoE layer and are removed again
            // by kimi_linear_parameter_tensors() on export.
            (
                Some(HostLinear {
                    weight: vec![0.0; i * d],
                    bias: None,
                }),
                HostLinear {
                    weight: vec![0.0; i * d],
                    bias: None,
                },
            )
        } else if config.architecture == VulkanTransformerArchitecture::Llama4Text {
            if config.layer_uses_moe(layer) {
                let moe = config
                    .moe
                    .as_ref()
                    .context("Llama 4 text checkpoint loader is missing MoE config")?;
                let packed = store.take_expected(
                    &format!("{p}.feed_forward.experts.gate_up_proj"),
                    &[moe.num_experts, d, 2 * i],
                )?;
                let expert_stride = d * 2 * i;
                let expert0 = transpose(&packed[..expert_stride], d, 2 * i);
                let split = i * d;
                (
                    Some(HostLinear {
                        weight: expert0[..split].to_vec(),
                        bias: None,
                    }),
                    HostLinear {
                        weight: expert0[split..].to_vec(),
                        bias: None,
                    },
                )
            } else {
                (
                    Some(HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.feed_forward.gate_proj.weight"),
                            &[i, d],
                        )?,
                        bias: None,
                    }),
                    HostLinear {
                        weight: store
                            .take_expected(&format!("{p}.feed_forward.up_proj.weight"), &[i, d])?,
                        bias: None,
                    },
                )
            }
        } else if config.architecture == VulkanTransformerArchitecture::GptOss {
            let moe = config
                .moe
                .as_ref()
                .context("GPT-OSS checkpoint loader is missing MoE config")?;
            let gate_up = store.take_expected(
                &format!("{p}.mlp.experts.gate_up_proj"),
                &[moe.num_experts, d, 2 * i],
            )?;
            let gate_up_bias = store.take_expected(
                &format!("{p}.mlp.experts.gate_up_proj_bias"),
                &[moe.num_experts, 2 * i],
            )?;
            let expert_stride = d * 2 * i;
            let (gate_weight, up_weight) =
                gpt_oss_deinterleave_gate_up(&gate_up[..expert_stride], d, i)?;
            let (gate_bias, up_bias) =
                gpt_oss_deinterleave_gate_up_bias(&gate_up_bias[..2 * i], i)?;
            (
                Some(HostLinear {
                    weight: gate_weight,
                    bias: Some(gate_bias),
                }),
                HostLinear {
                    weight: up_weight,
                    bias: Some(up_bias),
                },
            )
        } else if config.architecture == VulkanTransformerArchitecture::AriaText {
            let moe = config
                .moe
                .as_ref()
                .context("Aria Text checkpoint loader is missing MoE config")?;
            let packed = store.take_expected(
                &format!("{p}.mlp.experts.fc1.weight"),
                &[moe.num_experts, d, 2 * i],
            )?;
            let expert_stride = d * 2 * i;
            let expert0 = transpose(&packed[..expert_stride], d, 2 * i);
            let split = i * d;
            (
                Some(HostLinear {
                    weight: expert0[..split].to_vec(),
                    bias: None,
                }),
                HostLinear {
                    weight: expert0[split..].to_vec(),
                    bias: None,
                },
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::Mixtral
                | VulkanTransformerArchitecture::Afmoe
                | VulkanTransformerArchitecture::Laguna
                | VulkanTransformerArchitecture::HyV3
                | VulkanTransformerArchitecture::Qwen2Moe
                | VulkanTransformerArchitecture::Qwen3Moe
                | VulkanTransformerArchitecture::Qwen3Next
                | VulkanTransformerArchitecture::Qwen35Moe
                | VulkanTransformerArchitecture::Qwen4Exp
                | VulkanTransformerArchitecture::Dots1
                | VulkanTransformerArchitecture::Mellum
                | VulkanTransformerArchitecture::Cohere2Moe
                | VulkanTransformerArchitecture::GraniteMoe
                | VulkanTransformerArchitecture::GraniteMoeShared
                | VulkanTransformerArchitecture::GraniteMoeSwa
                | VulkanTransformerArchitecture::Olmoe
                | VulkanTransformerArchitecture::FlexOlmo
                | VulkanTransformerArchitecture::MiniMaxM2
                | VulkanTransformerArchitecture::MiniMaxM3VLText
                | VulkanTransformerArchitecture::Ernie45Moe
                | VulkanTransformerArchitecture::HunYuanMoeV1
                | VulkanTransformerArchitecture::Glm4Moe
                | VulkanTransformerArchitecture::SolarOpen
                | VulkanTransformerArchitecture::MiMoV2Flash
                | VulkanTransformerArchitecture::DeepseekV2
                | VulkanTransformerArchitecture::DeepseekV3
                | VulkanTransformerArchitecture::Glm5Next
                | VulkanTransformerArchitecture::DeepseekV4
                | VulkanTransformerArchitecture::Axk1
                | VulkanTransformerArchitecture::Mistral4
        ) && config.layer_uses_moe(layer)
        {
            let moe = config
                .moe
                .as_ref()
                .context("Mixtral checkpoint loader is missing MoE config")?;
            let packed_name = if matches!(
                config.architecture,
                VulkanTransformerArchitecture::GraniteMoe
                    | VulkanTransformerArchitecture::GraniteMoeShared
                    | VulkanTransformerArchitecture::GraniteMoeSwa
            ) {
                format!("{p}.block_sparse_moe.experts.gate_up_proj")
            } else {
                format!("{p}.mlp.experts.gate_up_proj")
            };
            if store.contains(&packed_name) {
                let packed = store.take_expected(&packed_name, &[moe.num_experts, 2 * i, d])?;
                let expert_stride = 2 * i * d;
                let split = i * d;
                let expert0 = &packed[..expert_stride];
                (
                    Some(HostLinear {
                        weight: expert0[..split].to_vec(),
                        bias: None,
                    }),
                    HostLinear {
                        weight: expert0[split..].to_vec(),
                        bias: None,
                    },
                )
            } else {
                // Transformers' expert export hook may serialize a packed
                // [experts, 2 * intermediate, hidden] tensor as ordinary
                // per-expert gate/up/down projections. Qwen4-Exp currently
                // uses this representation in save_pretrained checkpoints.
                let hf_expert = format!("{p}.mlp.experts.0");
                let hf_gate = format!("{hf_expert}.gate_proj.weight");
                if store.contains(&hf_gate) {
                    (
                        Some(HostLinear {
                            weight: store.take_expected(&hf_gate, &[i, d])?,
                            bias: None,
                        }),
                        HostLinear {
                            weight: store
                                .take_expected(&format!("{hf_expert}.up_proj.weight"), &[i, d])?,
                            bias: None,
                        },
                    )
                } else {
                    let expert = format!("{p}.block_sparse_moe.experts.0");
                    (
                        Some(HostLinear {
                            weight: store.take_expected(&format!("{expert}.w1.weight"), &[i, d])?,
                            bias: None,
                        }),
                        HostLinear {
                            weight: store.take_expected(&format!("{expert}.w3.weight"), &[i, d])?,
                            bias: None,
                        },
                    )
                }
            }
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::Glm
                | VulkanTransformerArchitecture::Glm4
                | VulkanTransformerArchitecture::MiniMaxM3VLText
        ) {
            let gate_up =
                store.take_expected(&format!("{p}.mlp.gate_up_proj.weight"), &[2 * i, d])?;
            let split = i * d;
            (
                Some(HostLinear {
                    weight: gate_up[..split].to_vec(),
                    bias: None,
                }),
                HostLinear {
                    weight: gate_up[split..].to_vec(),
                    bias: None,
                },
            )
        } else if config.architecture == VulkanTransformerArchitecture::NanoChat {
            (
                None,
                HostLinear {
                    weight: store.take_expected(&format!("{p}.mlp.fc1.weight"), &[i, d])?,
                    bias: None,
                },
            )
        } else {
            let c_gate = if config.uses_gated_mlp() {
                Some(HostLinear {
                    weight: store.take_expected(&format!("{p}.mlp.gate_proj.weight"), &[i, d])?,
                    bias: if configurable_mlp_bias
                        || config.architecture == VulkanTransformerArchitecture::SeedOss
                            && seed_oss_mlp_bias
                        || matches!(
                            config.architecture,
                            VulkanTransformerArchitecture::Ernie45
                                | VulkanTransformerArchitecture::Ernie45Moe
                        ) && ernie_use_bias
                        || config.architecture == VulkanTransformerArchitecture::HyperClovax
                            && hyperclovax_mlp_bias
                    {
                        Some(store.take_expected(&format!("{p}.mlp.gate_proj.bias"), &[i])?)
                    } else {
                        None
                    },
                })
            } else {
                None
            };
            let c_fc = HostLinear {
                weight: store.take_expected(&format!("{p}.mlp.up_proj.weight"), &[i, d])?,
                bias: if configurable_mlp_bias
                    || (config.architecture == VulkanTransformerArchitecture::Jais2
                        && jais2_mlp_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Nemotron
                        && nemotron_mlp_bias)
                    || (config.architecture == VulkanTransformerArchitecture::SeedOss
                        && seed_oss_mlp_bias)
                    || (matches!(
                        config.architecture,
                        VulkanTransformerArchitecture::Ernie45
                            | VulkanTransformerArchitecture::Ernie45Moe
                    ) && ernie_use_bias)
                    || (config.architecture == VulkanTransformerArchitecture::HyperClovax
                        && hyperclovax_mlp_bias)
                {
                    Some(store.take_expected(&format!("{p}.mlp.up_proj.bias"), &[i])?)
                } else {
                    None
                },
            };
            (c_gate, c_fc)
        };
        let c_mlp_proj = HostLinear {
            weight: if kimi_sparse_moe {
                vec![0.0; d * i]
            } else if config.architecture == VulkanTransformerArchitecture::Llama4Text {
                if config.layer_uses_moe(layer) {
                    let moe = config
                        .moe
                        .as_ref()
                        .context("Llama 4 text checkpoint loader is missing MoE config")?;
                    let packed = store.take_expected(
                        &format!("{p}.feed_forward.experts.down_proj"),
                        &[moe.num_experts, i, d],
                    )?;
                    transpose(&packed[..i * d], i, d)
                } else {
                    store.take_expected(&format!("{p}.feed_forward.down_proj.weight"), &[d, i])?
                }
            } else if config.architecture == VulkanTransformerArchitecture::GptOss {
                let moe = config
                    .moe
                    .as_ref()
                    .context("GPT-OSS checkpoint loader is missing MoE config")?;
                let packed = store.take_expected(
                    &format!("{p}.mlp.experts.down_proj"),
                    &[moe.num_experts, i, d],
                )?;
                transpose(&packed[..i * d], i, d)
            } else if config.architecture == VulkanTransformerArchitecture::AriaText {
                let moe = config
                    .moe
                    .as_ref()
                    .context("Aria Text checkpoint loader is missing MoE config")?;
                let packed = store.take_expected(
                    &format!("{p}.mlp.experts.fc2.weight"),
                    &[moe.num_experts, i, d],
                )?;
                transpose(&packed[..i * d], i, d)
            } else if matches!(
                config.architecture,
                VulkanTransformerArchitecture::Mixtral
                    | VulkanTransformerArchitecture::Afmoe
                    | VulkanTransformerArchitecture::Laguna
                    | VulkanTransformerArchitecture::HyV3
                    | VulkanTransformerArchitecture::Qwen2Moe
                    | VulkanTransformerArchitecture::Qwen3Moe
                    | VulkanTransformerArchitecture::Qwen3Next
                    | VulkanTransformerArchitecture::Qwen35Moe
                    | VulkanTransformerArchitecture::Qwen4Exp
                    | VulkanTransformerArchitecture::Dots1
                    | VulkanTransformerArchitecture::Mellum
                    | VulkanTransformerArchitecture::Cohere2Moe
                    | VulkanTransformerArchitecture::GraniteMoe
                    | VulkanTransformerArchitecture::GraniteMoeShared
                    | VulkanTransformerArchitecture::GraniteMoeSwa
                    | VulkanTransformerArchitecture::Olmoe
                    | VulkanTransformerArchitecture::FlexOlmo
                    | VulkanTransformerArchitecture::MiniMaxM2
                    | VulkanTransformerArchitecture::MiniMaxM3VLText
                    | VulkanTransformerArchitecture::Ernie45Moe
                    | VulkanTransformerArchitecture::HunYuanMoeV1
                    | VulkanTransformerArchitecture::Glm4Moe
                    | VulkanTransformerArchitecture::SolarOpen
                    | VulkanTransformerArchitecture::MiMoV2Flash
                    | VulkanTransformerArchitecture::DeepseekV2
                    | VulkanTransformerArchitecture::DeepseekV3
                    | VulkanTransformerArchitecture::Glm5Next
                    | VulkanTransformerArchitecture::DeepseekV4
                    | VulkanTransformerArchitecture::Axk1
                    | VulkanTransformerArchitecture::Mistral4
            ) && config.layer_uses_moe(layer)
            {
                let moe = config
                    .moe
                    .as_ref()
                    .context("Mixtral checkpoint loader is missing MoE config")?;
                let packed_name = if matches!(
                    config.architecture,
                    VulkanTransformerArchitecture::GraniteMoe
                        | VulkanTransformerArchitecture::GraniteMoeShared
                        | VulkanTransformerArchitecture::GraniteMoeSwa
                ) {
                    format!("{p}.block_sparse_moe.experts.down_proj")
                } else {
                    format!("{p}.mlp.experts.down_proj")
                };
                if store.contains(&packed_name) {
                    let packed = store.take_expected(&packed_name, &[moe.num_experts, d, i])?;
                    packed[..d * i].to_vec()
                } else {
                    let hf_down = format!("{p}.mlp.experts.0.down_proj.weight");
                    if store.contains(&hf_down) {
                        store.take_expected(&hf_down, &[d, i])?
                    } else {
                        store.take_expected(
                            &format!("{p}.block_sparse_moe.experts.0.w2.weight"),
                            &[d, i],
                        )?
                    }
                }
            } else {
                store.take_expected(
                    &if config.architecture == VulkanTransformerArchitecture::NanoChat {
                        format!("{p}.mlp.fc2.weight")
                    } else {
                        format!("{p}.mlp.down_proj.weight")
                    },
                    &[d, i],
                )?
            },
            bias: if config.architecture == VulkanTransformerArchitecture::GptOss {
                let moe = config
                    .moe
                    .as_ref()
                    .context("GPT-OSS checkpoint loader is missing MoE config")?;
                let packed = store.take_expected(
                    &format!("{p}.mlp.experts.down_proj_bias"),
                    &[moe.num_experts, d],
                )?;
                Some(packed[..d].to_vec())
            } else if (configurable_mlp_bias
                && config.architecture != VulkanTransformerArchitecture::AriaText)
                || (config.architecture == VulkanTransformerArchitecture::Jais2 && jais2_mlp_bias)
                || (config.architecture == VulkanTransformerArchitecture::Nemotron
                    && nemotron_mlp_bias)
                || (config.architecture == VulkanTransformerArchitecture::SeedOss
                    && seed_oss_mlp_bias)
                || (matches!(
                    config.architecture,
                    VulkanTransformerArchitecture::Ernie45
                        | VulkanTransformerArchitecture::Ernie45Moe
                ) && ernie_use_bias)
                || (config.architecture == VulkanTransformerArchitecture::HyperClovax
                    && hyperclovax_mlp_bias)
            {
                Some(store.take_expected(&format!("{p}.mlp.down_proj.bias"), &[d])?)
            } else {
                None
            },
        };
        let xielu = if config.architecture == VulkanTransformerArchitecture::Apertus
            && config.activation_function == "xielu"
        {
            let beta = store.take_expected(&format!("{p}.mlp.act_fn.beta"), &[])?;
            let eps = store.take_expected(&format!("{p}.mlp.act_fn.eps"), &[])?;
            Some(HostXielu {
                alpha_p: store.take_expected(&format!("{p}.mlp.act_fn.alpha_p"), &[1])?,
                alpha_n: store.take_expected(&format!("{p}.mlp.act_fn.alpha_n"), &[1])?,
                beta: beta[0],
                eps: eps[0],
            })
        } else {
            None
        };
        let (post_attention_norm, post_mlp_norm) = if config.architecture
            == VulkanTransformerArchitecture::BitNet
        {
            (
                Some(HostLayerNorm {
                    weight: store
                        .take_expected(&format!("{p}.self_attn.attn_sub_norm.weight"), &[d])?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.mlp.ffn_sub_norm.weight"), &[i])?,
                    bias: Vec::new(),
                }),
            )
        } else if config.architecture == VulkanTransformerArchitecture::Afmoe {
            (
                Some(HostLayerNorm {
                    weight: store
                        .take_expected(&format!("{p}.post_attention_layernorm.weight"), &[d])?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.post_mlp_layernorm.weight"), &[d])?,
                    bias: Vec::new(),
                }),
            )
        } else if config.architecture == VulkanTransformerArchitecture::Axk1
            && config.layer_uses_moe(layer)
        {
            let converted = format!("{p}.mlp.post_mlp_layernorm.weight");
            let released = format!("{p}.post_mlp_layernorm.weight");
            if store.contains(&converted) && store.contains(&released) {
                bail!(
                    "A.X-K1 checkpoint contains both converted and released post_mlp_layernorm tensors for layer {layer}"
                );
            }
            let norm_name = if store.contains(&converted) {
                converted
            } else {
                released
            };
            (
                None,
                Some(HostLayerNorm {
                    weight: store.take_expected(&norm_name, &[d])?,
                    bias: Vec::new(),
                }),
            )
        } else if config.architecture == VulkanTransformerArchitecture::Glm4 {
            (
                Some(HostLayerNorm {
                    weight: store
                        .take_expected(&format!("{p}.post_self_attn_layernorm.weight"), &[d])?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.post_mlp_layernorm.weight"), &[d])?,
                    bias: Vec::new(),
                }),
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::Gemma2
                | VulkanTransformerArchitecture::Gemma3
                | VulkanTransformerArchitecture::Gemma4
        ) {
            (
                Some(HostLayerNorm {
                    weight: store
                        .take_expected(&format!("{p}.post_attention_layernorm.weight"), &[d])?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store
                        .take_expected(&format!("{p}.post_feedforward_layernorm.weight"), &[d])?,
                    bias: Vec::new(),
                }),
            )
        } else if config.architecture == VulkanTransformerArchitecture::HyperClovax
            && config.use_post_norm
        {
            (
                Some(HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.post_norm1.weight"), &[d])?,
                    bias: Vec::new(),
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.post_norm2.weight"), &[d])?,
                    bias: Vec::new(),
                }),
            )
        } else {
            (None, None)
        };
        layers.push(HostTransformerLayer {
            post_attention_norm,
            post_mlp_norm,
            ln1,
            c_attn: None,
            q_proj,
            k_proj,
            v_proj,
            q_norm,
            k_norm,
            c_proj,
            ln2,
            c_fc,
            c_gate,
            c_mlp_proj,
            xielu,
        });
    }
    let final_norm = if config.architecture == VulkanTransformerArchitecture::Qwen4Exp {
        // HF Qwen4 terminates with hyper_connection_mixer instead of model.norm.
        // The runtime keeps a placeholder here because the common graph owns a
        // final-norm field for every architecture; uses_final_norm() bypasses it.
        HostLayerNorm {
            weight: vec![1.0; d],
            bias: Vec::new(),
        }
    } else if parameter_free_layer_norm {
        HostLayerNorm {
            weight: vec![1.0; d],
            bias: Vec::new(),
        }
    } else {
        HostLayerNorm {
            weight: hf_layer_norm_weight(store.take_expected(&backbone_name("norm.weight"), &[d])?),
            bias: if layer_norm_bias {
                store.take_expected(&backbone_name("norm.bias"), &[d])?
            } else {
                Vec::new()
            },
        }
    };
    let has_lm_head_alias = store.contains("lm_head.weight") && config.tie_word_embeddings;
    let lm_head = if config.tie_word_embeddings {
        if store.contains("lm_head.weight") {
            let alias = store.take_expected("lm_head.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!("Llama-layout tied lm_head.weight differs from model.embed_tokens.weight");
            }
        }
        None
    } else {
        Some(store.take_expected("lm_head.weight", &[config.vocab_size, d])?)
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: None,
        embedding_norm: if config.architecture == VulkanTransformerArchitecture::OpenLlama
            && open_llama_stable_embedding
        {
            Some(HostLayerNorm {
                weight: store.take_expected(&backbone_name("embed_layer_norm.weight"), &[d])?,
                bias: store.take_expected(&backbone_name("embed_layer_norm.bias"), &[d])?,
            })
        } else if config.architecture == VulkanTransformerArchitecture::NanoChat {
            Some(HostLayerNorm {
                weight: vec![1.0; d],
                bias: Vec::new(),
            })
        } else {
            None
        },
        layers,
        final_norm,
        prediction_head: None,
        has_lm_head_alias,
        lm_head,
        lm_head_bias: None,
    })
}

fn load_longcat_flash_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    if config.architecture != VulkanTransformerArchitecture::LongCatFlash {
        bail!("LongCat-Flash checkpoint loader requires a LongCat-Flash graph");
    }
    if !config.num_layers.is_multiple_of(2) {
        bail!("LongCat-Flash physical layer count must be even");
    }
    let package_config = transformer_text_config_from_package(model_dir)?;
    let d = config.hidden_size;
    let dense_i = config
        .moe
        .as_ref()
        .map(|moe| moe.dense_intermediate_size)
        .filter(|width| *width != 0)
        .context("LongCat-Flash config is missing dense FFN width")?;
    let v_head_dim = package_config
        .get("v_head_dim")
        .and_then(serde_json::Value::as_u64)
        .map(|value| value as usize)
        .context("LongCat-Flash config is missing integer v_head_dim")?;
    let attention_hidden = config
        .num_heads
        .checked_mul(v_head_dim)
        .context("LongCat-Flash attention output width overflow")?;
    let attention_bias = package_config
        .get("attention_bias")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context(
        "LongCat-Flash checkpoint is missing embed_tokens under a supported text-backbone prefix",
    )?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };
    let token_embedding = store.take_expected(
        &backbone_name("embed_tokens.weight"),
        &[config.vocab_size, d],
    )?;
    let mut layers = Vec::with_capacity(config.num_layers);
    for physical_layer in 0..config.num_layers {
        let logical_layer = physical_layer / 2;
        let sublayer = physical_layer % 2;
        let p = backbone_name(&format!("layers.{logical_layer}"));
        let attn = format!("{p}.self_attn.{sublayer}");
        let mlp = format!("{p}.mlps.{sublayer}");
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.input_layernorm.{sublayer}.weight"), &[d])?,
                bias: Vec::new(),
            },
            c_attn: None,
            q_proj: None,
            k_proj: None,
            v_proj: None,
            q_norm: None,
            k_norm: None,
            c_proj: HostLinear {
                weight: store
                    .take_expected(&format!("{attn}.o_proj.weight"), &[d, attention_hidden])?,
                bias: if attention_bias {
                    Some(store.take_expected(&format!("{attn}.o_proj.bias"), &[d])?)
                } else {
                    None
                },
            },
            ln2: HostLayerNorm {
                weight: store.take_expected(
                    &format!("{p}.post_attention_layernorm.{sublayer}.weight"),
                    &[d],
                )?,
                bias: Vec::new(),
            },
            c_fc: HostLinear {
                weight: store.take_expected(&format!("{mlp}.up_proj.weight"), &[dense_i, d])?,
                bias: None,
            },
            c_gate: Some(HostLinear {
                weight: store.take_expected(&format!("{mlp}.gate_proj.weight"), &[dense_i, d])?,
                bias: None,
            }),
            c_mlp_proj: HostLinear {
                weight: store.take_expected(&format!("{mlp}.down_proj.weight"), &[d, dense_i])?,
                bias: None,
            },
            xielu: None,
        });
    }
    let final_norm = HostLayerNorm {
        weight: store.take_expected(&backbone_name("norm.weight"), &[d])?,
        bias: Vec::new(),
    };
    let has_lm_head_alias = store.contains("lm_head.weight") && config.tie_word_embeddings;
    let lm_head = if config.tie_word_embeddings {
        if store.contains("lm_head.weight") {
            let alias = store.take_expected("lm_head.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!("LongCat-Flash tied lm_head.weight differs from embed_tokens.weight");
            }
        }
        None
    } else {
        Some(store.take_expected("lm_head.weight", &[config.vocab_size, d])?)
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: None,
        embedding_norm: None,
        layers,
        final_norm,
        prediction_head: None,
        has_lm_head_alias,
        lm_head,
        lm_head_bias: None,
    })
}

fn load_longcat_flash_moe_layers(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<HostMoeLayer>> {
    if config.architecture != VulkanTransformerArchitecture::LongCatFlash {
        bail!("LongCat-Flash MoE loader requires a LongCat-Flash graph");
    }
    if !config.num_layers.is_multiple_of(2) {
        bail!("LongCat-Flash physical layer count must be even");
    }
    let package_config = transformer_text_config_from_package(model_dir)?;
    let moe = config
        .moe
        .as_ref()
        .context("LongCat-Flash config is missing MoE parameters")?;
    let routed_experts = package_config
        .get("n_routed_experts")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(512) as usize;
    if routed_experts == 0 || routed_experts > moe.num_experts {
        bail!("LongCat-Flash routed expert count {routed_experts} is incompatible with total expert count {}", moe.num_experts);
    }
    let router_bias = package_config
        .get("router_bias")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context("LongCat-Flash MoE checkpoint is missing the text backbone")?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };
    let mut layers = Vec::with_capacity(config.num_layers / 2);
    for logical_layer in 0..config.num_layers / 2 {
        let p = backbone_name(&format!("layers.{logical_layer}.mlp"));
        let router = HostLinear {
            weight: store.take_expected(
                &format!("{p}.router.classifier.weight"),
                &[moe.num_experts, d],
            )?,
            // Current HF LongCat explicitly calls F.linear with only the
            // classifier weight, so a configured classifier bias is persisted
            // but is not part of the forward graph.
            bias: None,
        };
        if router_bias && store.contains(&format!("{p}.router.classifier.bias")) {
            let _ =
                store.take_expected(&format!("{p}.router.classifier.bias"), &[moe.num_experts])?;
        }
        let correction_name = format!("{p}.router.e_score_correction_bias");
        let router_correction_bias = if store.contains(&correction_name) {
            store.take_expected(&correction_name, &[moe.num_experts])?
        } else {
            vec![0.0; moe.num_experts]
        };
        let gate_up = store.take_expected(
            &format!("{p}.experts.gate_up_proj"),
            &[moe.num_experts, 2 * i, d],
        )?;
        let down =
            store.take_expected(&format!("{p}.experts.down_proj"), &[routed_experts, d, i])?;
        let gate_up_stride = 2 * i * d;
        let split = i * d;
        let down_stride = d * i;
        let make_expert = |expert_index: usize| -> HostMoeExpert {
            let gate_up_base = expert_index * gate_up_stride;
            let down_base = expert_index * down_stride;
            HostMoeExpert {
                gate: Some(HostLinear {
                    weight: gate_up[gate_up_base..gate_up_base + split].to_vec(),
                    bias: None,
                }),
                up: HostLinear {
                    weight: gate_up[gate_up_base + split..gate_up_base + gate_up_stride].to_vec(),
                    bias: None,
                },
                down: HostLinear {
                    weight: down[down_base..down_base + down_stride].to_vec(),
                    bias: None,
                },
            }
        };
        let owned_expert0 = Some(make_expert(0));
        let experts = (1..routed_experts).map(make_expert).collect();
        layers.push(HostMoeLayer {
            router,
            router_correction_bias,
            hash_router: None,
            expert_capacity: 0,
            owned_expert0,
            identity_expert_start: routed_experts,
            experts,
            shared_expert: None,
            shared_expert_gate: None,
            latent: None,
        });
    }
    Ok(layers)
}

fn take_deepseek_v4_mhc(
    store: &mut Gpt2TensorStore,
    prefix: &str,
    hidden_size: usize,
    hc_mult: usize,
    sinkhorn_iters: usize,
    hc_eps: f32,
    norm_eps: f32,
) -> Result<HostDeepseekV4Mhc> {
    let hc_width = hidden_size
        .checked_mul(hc_mult)
        .context("DeepSeek-V4 mHC checkpoint width overflow")?;
    let mix = (2usize
        .checked_add(hc_mult)
        .context("DeepSeek-V4 mHC checkpoint mix overflow")?)
    .checked_mul(hc_mult)
    .context("DeepSeek-V4 mHC checkpoint mix overflow")?;
    Ok(HostDeepseekV4Mhc {
        fn_weight: store.take_expected(&format!("{prefix}.fn"), &[mix, hc_width])?,
        base: store.take_expected(&format!("{prefix}.base"), &[mix])?,
        scale: store.take_expected(&format!("{prefix}.scale"), &[3])?,
        hc_mult,
        sinkhorn_iters,
        hc_eps,
        norm_eps,
    })
}

fn load_deepseek_v4_hyper_connections(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<(
    Vec<(HostDeepseekV4Mhc, HostDeepseekV4Mhc)>,
    HostDeepseekV4HyperHead,
)> {
    if config.architecture != VulkanTransformerArchitecture::DeepseekV4 {
        bail!("DeepSeek-V4 hyper-connection loader requires a DeepSeek-V4 config");
    }
    let package_config = transformer_text_config_from_package(model_dir)?;
    let positive = |name: &str| -> Result<usize> {
        package_config
            .get(name)
            .and_then(serde_json::Value::as_u64)
            .map(|value| value as usize)
            .filter(|value| *value != 0)
            .with_context(|| format!("DeepSeek-V4 checkpoint config requires positive {name}"))
    };
    let hc_mult = positive("hc_mult")?;
    let sinkhorn_iters = positive("hc_sinkhorn_iters")?;
    if hc_mult > 8 {
        bail!("DeepSeek-V4 hc_mult={hc_mult} exceeds the native mHC kernel limit of 8");
    }
    if sinkhorn_iters > 32 {
        bail!(
            "DeepSeek-V4 hc_sinkhorn_iters={sinkhorn_iters} exceeds the native mHC kernel limit of 32"
        );
    }
    let hc_eps = package_config
        .get("hc_eps")
        .and_then(serde_json::Value::as_f64)
        .unwrap_or(1.0e-6) as f32;
    let norm_eps = package_config
        .get("rms_norm_eps")
        .and_then(serde_json::Value::as_f64)
        .unwrap_or(config.layer_norm_eps as f64) as f32;
    if !hc_eps.is_finite() || hc_eps <= 0.0 || !norm_eps.is_finite() || norm_eps <= 0.0 {
        bail!("DeepSeek-V4 hc_eps and rms_norm_eps must be finite and positive");
    }

    let hc_width = config
        .hidden_size
        .checked_mul(hc_mult)
        .context("DeepSeek-V4 hyper-head width overflow")?;
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context(
        "DeepSeek-V4 checkpoint is missing embed_tokens under a supported text-backbone prefix",
    )?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };

    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let prefix = backbone_name(&format!("layers.{layer}"));
        layers.push((
            take_deepseek_v4_mhc(
                &mut store,
                &format!("{prefix}.attn_hc"),
                config.hidden_size,
                hc_mult,
                sinkhorn_iters,
                hc_eps,
                norm_eps,
            )?,
            take_deepseek_v4_mhc(
                &mut store,
                &format!("{prefix}.ffn_hc"),
                config.hidden_size,
                hc_mult,
                sinkhorn_iters,
                hc_eps,
                norm_eps,
            )?,
        ));
    }
    let head_prefix = backbone_name("hc_head");
    let head = HostDeepseekV4HyperHead {
        fn_weight: store.take_expected(&format!("{head_prefix}.hc_fn"), &[hc_mult, hc_width])?,
        base: store.take_expected(&format!("{head_prefix}.hc_base"), &[hc_mult])?,
        scale: store.take_expected(&format!("{head_prefix}.hc_scale"), &[1])?,
        hc_mult,
        hc_eps,
        norm_eps,
    };
    Ok((layers, head))
}

fn load_glm5_hyper_connections(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<(Vec<(HostDeepseekV4Mhc, HostDeepseekV4Mhc)>, usize)> {
    if config.architecture != VulkanTransformerArchitecture::Glm5Next {
        bail!("GLM-5 Next hyper-connection loader requires a GLM-5 Next config");
    }
    let package_config = transformer_text_config_from_package(model_dir)?;
    let positive = |name: &str| -> Result<usize> {
        package_config
            .get(name)
            .and_then(serde_json::Value::as_u64)
            .map(|value| value as usize)
            .filter(|value| *value != 0)
            .with_context(|| format!("GLM-5 Next checkpoint config requires positive {name}"))
    };
    let hc_mult = positive("hc_mult")?;
    let sinkhorn_iters = positive("hc_sinkhorn_iters")?;
    if hc_mult > 8 {
        bail!("GLM-5 Next hc_mult={hc_mult} exceeds the native mHC kernel limit of 8");
    }
    if sinkhorn_iters > 32 {
        bail!(
            "GLM-5 Next hc_sinkhorn_iters={sinkhorn_iters} exceeds the native mHC kernel limit of 32"
        );
    }
    let hc_eps = package_config
        .get("hc_eps")
        .and_then(serde_json::Value::as_f64)
        .unwrap_or(1.0e-6) as f32;
    let norm_eps = package_config
        .get("rms_norm_eps")
        .and_then(serde_json::Value::as_f64)
        .unwrap_or(config.layer_norm_eps as f64) as f32;
    if !hc_eps.is_finite() || hc_eps <= 0.0 || !norm_eps.is_finite() || norm_eps <= 0.0 {
        bail!("GLM-5 Next hc_eps and rms_norm_eps must be finite and positive");
    }

    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context(
        "GLM-5 Next checkpoint is missing embed_tokens under a supported text-backbone prefix",
    )?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };

    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let prefix = backbone_name(&format!("layers.{layer}"));
        layers.push((
            take_deepseek_v4_mhc(
                &mut store,
                &format!("{prefix}.attn_hc"),
                config.hidden_size,
                hc_mult,
                sinkhorn_iters,
                hc_eps,
                norm_eps,
            )?,
            take_deepseek_v4_mhc(
                &mut store,
                &format!("{prefix}.ffn_hc"),
                config.hidden_size,
                hc_mult,
                sinkhorn_iters,
                hc_eps,
                norm_eps,
            )?,
        ));
    }
    Ok((layers, hc_mult))
}

fn load_deepseek_v4_attentions(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<HostDeepseekV4Attention>> {
    if config.architecture != VulkanTransformerArchitecture::DeepseekV4 {
        bail!("DeepSeek-V4 attention loader requires a DeepSeek-V4 config");
    }

    let package_config = transformer_text_config_from_package(model_dir)?;
    let positive = |name: &str| -> Result<usize> {
        package_config
            .get(name)
            .and_then(serde_json::Value::as_u64)
            .map(|value| value as usize)
            .filter(|value| *value != 0)
            .with_context(|| format!("DeepSeek-V4 checkpoint config requires positive {name}"))
    };
    let q_lora_rank = positive("q_lora_rank")?;
    let o_groups = positive("o_groups")?;
    let o_lora_rank = positive("o_lora_rank")?;
    let index_n_heads = positive("index_n_heads")?;
    let index_head_dim = positive("index_head_dim")?;
    let index_topk = positive("index_topk")?;
    let query_width = config
        .num_heads
        .checked_mul(config.head_dim)
        .context("DeepSeek-V4 attention query width overflow")?;
    if !query_width.is_multiple_of(o_groups) {
        bail!(
            "DeepSeek-V4 attention query width {query_width} must be divisible by o_groups={o_groups}"
        );
    }

    let layer_types = if let Some(layer_types) = package_config
        .get("layer_types")
        .filter(|value| !value.is_null())
    {
        let values = layer_types
            .as_array()
            .context("DeepSeek-V4 layer_types must be an array or null")?;
        if values.len() < config.num_layers {
            bail!(
                "DeepSeek-V4 layer_types has only {} entries for {} decoder layers",
                values.len(),
                config.num_layers
            );
        }
        values
            .iter()
            .take(config.num_layers)
            .map(|value| match value.as_str() {
                Some("sliding_attention") => Ok(DeepseekV4AttentionKind::Sliding),
                Some("compressed_sparse_attention") => Ok(DeepseekV4AttentionKind::Csa),
                Some("heavily_compressed_attention") => Ok(DeepseekV4AttentionKind::Hca),
                Some(other) => bail!("unsupported DeepSeek-V4 attention layer type {other:?}"),
                None => bail!("DeepSeek-V4 layer_types entries must be strings"),
            })
            .collect::<Result<Vec<_>>>()?
    } else if let Some(compress_ratios) = package_config
        .get("compress_ratios")
        .filter(|value| !value.is_null())
    {
        let values = compress_ratios
            .as_array()
            .context("DeepSeek-V4 compress_ratios must be an array or null")?;
        if values.len() < config.num_layers {
            bail!(
                "DeepSeek-V4 compress_ratios has only {} entries for {} decoder layers",
                values.len(),
                config.num_layers
            );
        }
        values
            .iter()
            .take(config.num_layers)
            .map(|value| match value.as_u64() {
                Some(0) => Ok(DeepseekV4AttentionKind::Sliding),
                Some(4) => Ok(DeepseekV4AttentionKind::Csa),
                Some(128) => Ok(DeepseekV4AttentionKind::Hca),
                Some(other) => {
                    bail!("unsupported DeepSeek-V4 compress ratio {other}; expected 0, 4, or 128")
                }
                None => bail!("DeepSeek-V4 compress_ratios entries must be integers"),
            })
            .collect::<Result<Vec<_>>>()?
    } else {
        bail!("DeepSeek-V4 checkpoint config is missing layer_types/compress_ratios");
    };
    let csa_compress_rate = package_config
        .get("compress_rates")
        .and_then(serde_json::Value::as_object)
        .and_then(|rates| rates.get("compressed_sparse_attention"))
        .and_then(serde_json::Value::as_u64)
        .or_else(|| {
            package_config
                .get("compress_rate_csa")
                .and_then(serde_json::Value::as_u64)
        })
        .unwrap_or(4) as usize;
    let hca_compress_rate = package_config
        .get("compress_rates")
        .and_then(serde_json::Value::as_object)
        .and_then(|rates| rates.get("heavily_compressed_attention"))
        .and_then(serde_json::Value::as_u64)
        .or_else(|| {
            package_config
                .get("compress_rate_hca")
                .and_then(serde_json::Value::as_u64)
        })
        .unwrap_or(128) as usize;
    if csa_compress_rate == 0 || hca_compress_rate == 0 {
        bail!("DeepSeek-V4 CSA/HCA compress_rate must be positive");
    }

    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context(
        "DeepSeek-V4 checkpoint is missing embed_tokens under a supported text-backbone prefix",
    )?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };

    let grouped_input = query_width / o_groups;
    let grouped_output = o_groups
        .checked_mul(o_lora_rank)
        .context("DeepSeek-V4 grouped output width overflow")?;
    let mut attentions = Vec::with_capacity(config.num_layers);
    for (layer, kind) in layer_types.into_iter().enumerate() {
        let p = backbone_name(&format!("layers.{layer}.self_attn"));
        let csa_compressor = if kind == DeepseekV4AttentionKind::Csa {
            let compressor = format!("{p}.compressor");
            let indexer = format!("{compressor}.indexer");
            let indexer_width = index_n_heads
                .checked_mul(index_head_dim)
                .context("DeepSeek-V4 Lightning Indexer query width overflow")?;
            let take_overlap = |store: &mut Gpt2TensorStore,
                                prefix: &str,
                                head_dim: usize|
             -> Result<HostDeepseekV4CsaOverlapCompressor> {
                let projected_dim = head_dim
                    .checked_mul(2)
                    .context("DeepSeek-V4 CSA projection width overflow")?;
                Ok(HostDeepseekV4CsaOverlapCompressor {
                    kv_proj: HostLinear {
                        weight: store.take_expected(
                            &format!("{prefix}.kv_proj.weight"),
                            &[projected_dim, config.hidden_size],
                        )?,
                        bias: None,
                    },
                    gate_proj: HostLinear {
                        weight: store.take_expected(
                            &format!("{prefix}.gate_proj.weight"),
                            &[projected_dim, config.hidden_size],
                        )?,
                        bias: None,
                    },
                    position_bias: store.take_expected(
                        &format!("{prefix}.position_bias"),
                        &[csa_compress_rate, projected_dim],
                    )?,
                    kv_norm: HostLayerNorm {
                        weight: store
                            .take_expected(&format!("{prefix}.kv_norm.weight"), &[head_dim])?,
                        bias: Vec::new(),
                    },
                    compress_rate: csa_compress_rate,
                    head_dim,
                })
            };
            let outer = take_overlap(&mut store, &compressor, config.head_dim)?;
            let indexer_compressor = take_overlap(&mut store, &indexer, index_head_dim)?;
            Some(HostDeepseekV4CsaCompressor {
                compressor: outer,
                indexer: HostDeepseekV4CsaIndexer {
                    compressor: indexer_compressor,
                    q_b_proj: HostLinear {
                        weight: store.take_expected(
                            &format!("{indexer}.q_b_proj.weight"),
                            &[indexer_width, q_lora_rank],
                        )?,
                        bias: None,
                    },
                    weights_proj: HostLinear {
                        weight: store.take_expected(
                            &format!("{indexer}.scorer.weights_proj.weight"),
                            &[index_n_heads, config.hidden_size],
                        )?,
                        bias: None,
                    },
                    num_heads: index_n_heads,
                    head_dim: index_head_dim,
                    top_k: index_topk,
                },
            })
        } else {
            None
        };
        let hca_compressor = if kind == DeepseekV4AttentionKind::Hca {
            let compressor = format!("{p}.compressor");
            Some(HostDeepseekV4HcaCompressor {
                kv_proj: HostLinear {
                    weight: store.take_expected(
                        &format!("{compressor}.kv_proj.weight"),
                        &[config.head_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                gate_proj: HostLinear {
                    weight: store.take_expected(
                        &format!("{compressor}.gate_proj.weight"),
                        &[config.head_dim, config.hidden_size],
                    )?,
                    bias: None,
                },
                position_bias: store.take_expected(
                    &format!("{compressor}.position_bias"),
                    &[hca_compress_rate, config.head_dim],
                )?,
                kv_norm: HostLayerNorm {
                    weight: store.take_expected(
                        &format!("{compressor}.kv_norm.weight"),
                        &[config.head_dim],
                    )?,
                    bias: Vec::new(),
                },
                compress_rate: hca_compress_rate,
                head_dim: config.head_dim,
            })
        } else {
            None
        };
        attentions.push(HostDeepseekV4Attention {
            kind,
            q_a_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.q_a_proj.weight"),
                    &[q_lora_rank, config.hidden_size],
                )?,
                bias: None,
            },
            q_a_norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.q_a_norm.weight"), &[q_lora_rank])?,
                bias: Vec::new(),
            },
            q_b_proj: HostLinear {
                weight: store
                    .take_expected(&format!("{p}.q_b_proj.weight"), &[query_width, q_lora_rank])?,
                bias: None,
            },
            kv_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.kv_proj.weight"),
                    &[config.head_dim, config.hidden_size],
                )?,
                bias: None,
            },
            kv_norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.kv_norm.weight"), &[config.head_dim])?,
                bias: Vec::new(),
            },
            o_a_weight: store.take_expected(
                &format!("{p}.o_a_proj.weight"),
                &[grouped_output, grouped_input],
            )?,
            o_b_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.o_b_proj.weight"),
                    &[config.hidden_size, grouped_output],
                )?,
                bias: None,
            },
            sinks: store.take_expected(&format!("{p}.sinks"), &[config.num_heads])?,
            q_lora_rank,
            o_groups,
            o_lora_rank,
            csa_compressor,
            hca_compressor,
        });
    }
    Ok(attentions)
}

fn load_deepseek_v4_hca_compressors(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<Option<HostDeepseekV4HcaCompressor>>> {
    if config.architecture != VulkanTransformerArchitecture::DeepseekV4 {
        bail!("DeepSeek-V4 HCA compressor loader requires a DeepSeek-V4 config");
    }

    let package_config = transformer_text_config_from_package(model_dir)?;
    let layer_types = if let Some(layer_types) = package_config
        .get("layer_types")
        .filter(|value| !value.is_null())
    {
        let layer_types = layer_types
            .as_array()
            .context("DeepSeek-V4 layer_types must be an array or null")?;
        if layer_types.len() < config.num_layers {
            bail!(
                "DeepSeek-V4 layer_types has only {} entries for {} decoder layers",
                layer_types.len(),
                config.num_layers
            );
        }
        layer_types
            .iter()
            .take(config.num_layers)
            .map(|value| {
                value
                    .as_str()
                    .map(str::to_owned)
                    .context("DeepSeek-V4 layer_types entries must be strings")
            })
            .collect::<Result<Vec<_>>>()?
    } else if let Some(compress_ratios) = package_config
        .get("compress_ratios")
        .filter(|value| !value.is_null())
    {
        let compress_ratios = compress_ratios
            .as_array()
            .context("DeepSeek-V4 compress_ratios must be an array or null")?;
        if compress_ratios.len() < config.num_layers {
            bail!(
                "DeepSeek-V4 compress_ratios has only {} entries for {} decoder layers",
                compress_ratios.len(),
                config.num_layers
            );
        }
        compress_ratios
            .iter()
            .take(config.num_layers)
            .map(|value| match value.as_u64() {
                Some(0) => Ok("sliding_attention".to_owned()),
                Some(4) => Ok("compressed_sparse_attention".to_owned()),
                Some(128) => Ok("heavily_compressed_attention".to_owned()),
                Some(other) => {
                    bail!("unsupported DeepSeek-V4 compress ratio {other}; expected 0, 4, or 128")
                }
                None => bail!("DeepSeek-V4 compress_ratios entries must be integers"),
            })
            .collect::<Result<Vec<_>>>()?
    } else {
        bail!("DeepSeek-V4 checkpoint config is missing layer_types/compress_ratios");
    };

    let compress_rate = package_config
        .get("compress_rates")
        .and_then(serde_json::Value::as_object)
        .and_then(|rates| rates.get("heavily_compressed_attention"))
        .and_then(serde_json::Value::as_u64)
        .or_else(|| {
            package_config
                .get("compress_rate_hca")
                .and_then(serde_json::Value::as_u64)
        })
        .unwrap_or(128) as usize;
    if compress_rate == 0 || config.head_dim == 0 {
        bail!("DeepSeek-V4 HCA compress_rate and head_dim must be positive");
    }

    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context(
        "DeepSeek-V4 checkpoint is missing embed_tokens under a supported text-backbone prefix",
    )?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };

    let mut compressors = Vec::with_capacity(config.num_layers);
    for (layer, layer_type) in layer_types.iter().enumerate() {
        if layer_type != "heavily_compressed_attention" {
            compressors.push(None);
            continue;
        }
        let p = backbone_name(&format!("layers.{layer}.self_attn.compressor"));
        compressors.push(Some(HostDeepseekV4HcaCompressor {
            kv_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.kv_proj.weight"),
                    &[config.head_dim, config.hidden_size],
                )?,
                bias: None,
            },
            gate_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.gate_proj.weight"),
                    &[config.head_dim, config.hidden_size],
                )?,
                bias: None,
            },
            position_bias: store.take_expected(
                &format!("{p}.position_bias"),
                &[compress_rate, config.head_dim],
            )?,
            kv_norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.kv_norm.weight"), &[config.head_dim])?,
                bias: Vec::new(),
            },
            compress_rate,
            head_dim: config.head_dim,
        }));
    }
    Ok(compressors)
}

fn load_kimi_attn_res_stack(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<HostKimiAttnResStack>> {
    if config.architecture != VulkanTransformerArchitecture::KimiLinear {
        return Ok(None);
    }
    let package_config = transformer_text_config_from_package(model_dir)?;
    let Some(block_size_value) = package_config
        .get("attn_res_block_size")
        .filter(|value| !value.is_null())
    else {
        return Ok(None);
    };
    let block_size = block_size_value
        .as_u64()
        .map(|value| value as usize)
        .context("KimiLinear attn_res_block_size must be a positive integer or null")?;
    if block_size == 0 {
        bail!("KimiLinear attn_res_block_size must be positive when specified");
    }
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = ["model", "model.language_model", "model.text_model", "language_model", ""]
        .into_iter()
        .find(|prefix| {
            let name = if prefix.is_empty() {
                "embed_tokens.weight".to_owned()
            } else {
                format!("{prefix}.embed_tokens.weight")
            };
            store.contains(&name)
        })
        .context("Kimi AttnRes checkpoint is missing embed_tokens under a supported text-backbone prefix")?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };
    let d = config.hidden_size;
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = backbone_name(&format!("layers.{layer}"));
        layers.push(HostKimiAttnResLayer {
            self_attention: HostKimiAttnRes {
                norm: HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.self_attention_res_norm.weight"), &[d])?,
                    bias: Vec::new(),
                },
                proj: HostLinear {
                    weight: store.take_expected(&format!("{p}.self_attention_res_proj.weight"), &[1, d])?,
                    bias: None,
                },
            },
            mlp: HostKimiAttnRes {
                norm: HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.mlp_res_norm.weight"), &[d])?,
                    bias: Vec::new(),
                },
                proj: HostLinear {
                    weight: store.take_expected(&format!("{p}.mlp_res_proj.weight"), &[1, d])?,
                    bias: None,
                },
            },
        });
    }
    let output = HostKimiAttnRes {
        norm: HostLayerNorm {
            weight: store.take_expected(&backbone_name("output_attn_res_norm.weight"), &[d])?,
            bias: Vec::new(),
        },
        proj: HostLinear {
            weight: store.take_expected(&backbone_name("output_attn_res_proj.weight"), &[1, d])?,
            bias: None,
        },
    };
    Ok(Some(HostKimiAttnResStack { block_size, layers, output }))
}

fn load_mla_attentions(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<HostMlaAttention>> {
    if !matches!(
        config.architecture,
        VulkanTransformerArchitecture::DeepseekV2
            | VulkanTransformerArchitecture::MiniCpm3
            | VulkanTransformerArchitecture::DeepseekV3
            | VulkanTransformerArchitecture::Axk1
            | VulkanTransformerArchitecture::Mistral4
            | VulkanTransformerArchitecture::Youtu
            | VulkanTransformerArchitecture::LongCatFlash
            | VulkanTransformerArchitecture::KimiLinear
    ) {
        bail!("MLA loader requires a DeepSeek-V2/V3, MiniCPM3, Mistral 4, Youtu, LongCat-Flash, or KimiLinear config");
    }

    let package_config = transformer_text_config_from_package(model_dir)?;
    let usize_field = |name: &str| -> Result<usize> {
        package_config
            .get(name)
            .and_then(serde_json::Value::as_u64)
            .map(|value| value as usize)
            .with_context(|| format!("MLA config is missing integer {name:?}"))
    };
    let qk_nope_head_dim = usize_field("qk_nope_head_dim")?;
    let qk_rope_head_dim = usize_field("qk_rope_head_dim")?;
    let v_head_dim = usize_field("v_head_dim")?;
    let kv_lora_rank = usize_field("kv_lora_rank")?;
    let q_lora_rank = package_config
        .get("q_lora_rank")
        .filter(|value| !value.is_null())
        .and_then(serde_json::Value::as_u64)
        .map(|value| value as usize);
    let attention_bias = package_config
        .get("attention_bias")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let qk_head_dim = qk_nope_head_dim
        .checked_add(qk_rope_head_dim)
        .context("MLA Q/K head width overflow")?;
    let q_width = config
        .num_heads
        .checked_mul(qk_head_dim)
        .context("MLA query width overflow")?;
    let kv_expanded_width = config
        .num_heads
        .checked_mul(
            qk_nope_head_dim
                .checked_add(v_head_dim)
                .context("MLA expanded KV head width overflow")?,
        )
        .context("MLA expanded KV width overflow")?;
    let compressed_width = kv_lora_rank
        .checked_add(qk_rope_head_dim)
        .context("MLA compressed KV width overflow")?;

    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context("MLA checkpoint is missing embed_tokens under a supported text-backbone prefix")?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };

    let attention_layer_indices = if config.architecture == VulkanTransformerArchitecture::KimiLinear
    {
        (0..config.num_layers)
            .filter(|layer| !config.layer_uses_linear_attention(*layer))
            .collect::<Vec<_>>()
    } else {
        (0..config.num_layers).collect::<Vec<_>>()
    };
    let attention_count = attention_layer_indices.len();
    let q_latent_scale = if config.architecture == VulkanTransformerArchitecture::LongCatFlash {
        let rank = q_lora_rank.context("LongCat-Flash requires a non-null q_lora_rank")?;
        (config.hidden_size as f32 / rank as f32).sqrt()
    } else {
        1.0
    };
    let kv_latent_scale = if config.architecture == VulkanTransformerArchitecture::LongCatFlash {
        (config.hidden_size as f32 / kv_lora_rank as f32).sqrt()
    } else {
        1.0
    };
    let mut attentions = Vec::with_capacity(attention_count);
    for (attention_index, layer_index) in attention_layer_indices.into_iter().enumerate() {
        let p = if config.architecture == VulkanTransformerArchitecture::LongCatFlash {
            let layer = attention_index / 2;
            let sublayer = attention_index % 2;
            backbone_name(&format!("layers.{layer}.self_attn.{sublayer}"))
        } else {
            backbone_name(&format!("layers.{layer_index}.self_attn"))
        };
        let (q_proj, q_a_proj, q_a_norm, q_b_proj) = if let Some(rank) = q_lora_rank {
            (
                None,
                Some(HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.q_a_proj.weight"),
                        &[rank, config.hidden_size],
                    )?,
                    bias: if attention_bias {
                        Some(store.take_expected(&format!("{p}.q_a_proj.bias"), &[rank])?)
                    } else {
                        None
                    },
                }),
                Some(HostLayerNorm {
                    weight: store.take_expected(&format!("{p}.q_a_layernorm.weight"), &[rank])?,
                    bias: Vec::new(),
                }),
                Some(HostLinear {
                    weight: store
                        .take_expected(&format!("{p}.q_b_proj.weight"), &[q_width, rank])?,
                    bias: None,
                }),
            )
        } else {
            (
                Some(HostLinear {
                    weight: store.take_expected(
                        &format!("{p}.q_proj.weight"),
                        &[q_width, config.hidden_size],
                    )?,
                    bias: None,
                }),
                None,
                None,
                None,
            )
        };
        attentions.push(HostMlaAttention {
            q_proj,
            q_a_proj,
            q_a_norm,
            q_b_proj,
            kv_a_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.kv_a_proj_with_mqa.weight"),
                    &[compressed_width, config.hidden_size],
                )?,
                bias: if attention_bias {
                    Some(store.take_expected(
                        &format!("{p}.kv_a_proj_with_mqa.bias"),
                        &[compressed_width],
                    )?)
                } else {
                    None
                },
            },
            kv_a_norm: HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.kv_a_layernorm.weight"), &[kv_lora_rank])?,
                bias: Vec::new(),
            },
            kv_b_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.kv_b_proj.weight"),
                    &[kv_expanded_width, kv_lora_rank],
                )?,
                bias: None,
            },
            q_lora_rank,
            kv_lora_rank,
            qk_nope_head_dim,
            qk_rope_head_dim,
            v_head_dim,
            q_latent_scale,
            kv_latent_scale,
        });
    }
    Ok(attentions)
}

fn load_dsa_indexers(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<Option<HostDsaIndexer>>>> {
    let package_config = transformer_text_config_from_package(model_dir)?;
    let model_type = package_config
        .get("model_type")
        .and_then(serde_json::Value::as_str);
    let (full_indexer_layers, interleaved_pairs, default_num_heads, family_name) = match model_type
    {
        Some("deepseek_v32") => (
            vec![true; config.num_layers],
            false,
            64usize,
            "DeepSeek-V3.2",
        ),
        Some("glm_moe_dsa") => (
            VulkanTransformerConfig::glm_moe_dsa_full_indexer_layers(
                &package_config,
                config.num_layers,
            )?,
            true,
            32usize,
            "GLM-MoE-DSA",
        ),
        _ => return Ok(None),
    };
    if config.architecture != VulkanTransformerArchitecture::DeepseekV3 {
        bail!("{family_name} DSA indexer requires the normalized DeepSeek-V3 graph");
    }

    let positive = |name: &str| -> Result<usize> {
        package_config
            .get(name)
            .and_then(serde_json::Value::as_u64)
            .map(|value| value as usize)
            .filter(|value| *value != 0)
            .with_context(|| format!("{family_name} {name} must be a positive integer"))
    };
    let num_heads = package_config
        .get("index_n_heads")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(default_num_heads as u64) as usize;
    let head_dim = package_config
        .get("index_head_dim")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(128) as usize;
    let top_k = package_config
        .get("index_topk")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2_048) as usize;
    let rotary_dim = positive("qk_rope_head_dim")?;
    let q_lora_rank = positive("q_lora_rank")?;
    if num_heads == 0 || head_dim == 0 || top_k == 0 || rotary_dim > head_dim {
        bail!("{family_name} DSA indexer dimensions are invalid");
    }
    let q_width = num_heads
        .checked_mul(head_dim)
        .with_context(|| format!("{family_name} indexer query width overflow"))?;

    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .with_context(|| format!("{family_name} checkpoint is missing the text backbone"))?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };

    let mut indexers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        if !full_indexer_layers[layer] {
            indexers.push(None);
            continue;
        }
        let p = backbone_name(&format!("layers.{layer}.self_attn.indexer"));
        indexers.push(Some(HostDsaIndexer {
            wq_b: HostLinear {
                weight: store
                    .take_expected(&format!("{p}.wq_b.weight"), &[q_width, q_lora_rank])?,
                bias: None,
            },
            wk: HostLinear {
                weight: store
                    .take_expected(&format!("{p}.wk.weight"), &[head_dim, config.hidden_size])?,
                bias: None,
            },
            k_norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.k_norm.weight"), &[head_dim])?,
                bias: store.take_expected(&format!("{p}.k_norm.bias"), &[head_dim])?,
            },
            weights_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.weights_proj.weight"),
                    &[num_heads, config.hidden_size],
                )?,
                bias: None,
            },
            q_lora_rank,
            num_heads,
            head_dim,
            rotary_dim,
            top_k,
            interleaved_pairs,
        }));
    }
    Ok(Some(indexers))
}

fn load_qwen4_qsa_indexers(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<Option<HostQwen4QsaIndexer>>>> {
    if config.architecture != VulkanTransformerArchitecture::Qwen4Exp {
        return Ok(None);
    }
    let package_config = transformer_text_config_from_package(model_dir)?;
    let qsa_fields = [
        "indexer_n_heads",
        "indexer_kv_heads",
        "indexer_head_dim",
        "indexer_budget",
        "indexer_compress_ratio",
    ];
    if !qsa_fields.iter().any(|name| {
        package_config
            .get(*name)
            .is_some_and(|value| !value.is_null())
    }) {
        return Ok(None);
    }
    let positive = |name: &str| -> Result<usize> {
        package_config
            .get(name)
            .and_then(serde_json::Value::as_u64)
            .and_then(|value| usize::try_from(value).ok())
            .filter(|value| *value != 0)
            .with_context(|| format!("Qwen4-Exp {name} must be a positive integer"))
    };
    let num_heads = positive("indexer_n_heads")?;
    let kv_heads = positive("indexer_kv_heads")?;
    let head_dim = positive("indexer_head_dim")?;
    let token_budget = positive("indexer_budget")?;
    let compress_ratio = positive("indexer_compress_ratio")?;
    if kv_heads != 1 {
        bail!("Qwen4-Exp QSA requires indexer_kv_heads=1, got {kv_heads}");
    }
    if !token_budget.is_multiple_of(compress_ratio) {
        bail!(
            "Qwen4-Exp indexer_budget={token_budget} must be divisible by indexer_compress_ratio={compress_ratio}"
        );
    }
    let rotary_dim = config.rotary_dim;
    if rotary_dim == 0 || rotary_dim > head_dim {
        bail!("Qwen4-Exp QSA rotary_dim={rotary_dim} must be in 1..={head_dim}");
    }
    let packed_width = num_heads
        .checked_add(kv_heads)
        .and_then(|heads| heads.checked_mul(head_dim))
        .context("Qwen4-Exp QSA packed projection width overflow")?;

    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context("Qwen4-Exp checkpoint is missing its text backbone")?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };

    let mut indexers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        if config.layer_uses_linear_attention(layer) {
            indexers.push(None);
            continue;
        }
        let p = backbone_name(&format!("layers.{layer}.self_attn.indexer"));
        indexers.push(Some(HostQwen4QsaIndexer {
            index_qk_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.index_qk_proj.weight"),
                    &[packed_width, config.hidden_size],
                )?,
                bias: None,
            },
            q_norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.q_layernorm.weight"), &[head_dim])?,
                bias: Vec::new(),
            },
            k_norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.k_layernorm.weight"), &[head_dim])?,
                bias: Vec::new(),
            },
            num_heads,
            head_dim,
            rotary_dim,
            token_budget,
            compress_ratio,
            // Qwen's rotate_half convention pairs the two rotary halves,
            // matching the non-interleaved/NeoX layout in the native kernel.
            interleaved_pairs: false,
        }));
    }
    Ok(Some(indexers))
}

fn load_minimax_m3_indexers(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<Option<HostMiniMaxM3Indexer>>>> {
    if config.architecture != VulkanTransformerArchitecture::MiniMaxM3VLText {
        return Ok(None);
    }
    let package_config = transformer_text_config_from_package(model_dir)?;
    let model_type = package_config
        .get("model_type")
        .and_then(serde_json::Value::as_str);
    if model_type != Some("minimax_m3_vl_text") {
        return Ok(None);
    }
    let sparse_config = package_config
        .get("sparse_attention_config")
        .filter(|value| !value.is_null())
        .and_then(serde_json::Value::as_object);
    let positive = |flat: &str, legacy: &str, default: u64| -> Result<usize> {
        package_config
            .get(flat)
            .and_then(serde_json::Value::as_u64)
            .or_else(|| {
                sparse_config
                    .and_then(|config| config.get(legacy))
                    .and_then(serde_json::Value::as_u64)
            })
            .unwrap_or(default)
            .try_into()
            .ok()
            .filter(|value: &usize| *value != 0)
            .with_context(|| format!("MiniMax-M3 {flat} must be a positive integer"))
    };
    let num_heads = positive("index_n_heads", "sparse_num_index_heads", 4)?;
    let head_dim = positive("index_head_dim", "sparse_index_dim", 128)?;
    let block_size = positive("index_block_size", "sparse_block_size", 128)?;
    let topk_blocks = positive("index_topk_blocks", "sparse_topk_blocks", 16)?;
    let local_blocks = package_config
        .get("index_local_blocks")
        .and_then(serde_json::Value::as_u64)
        .or_else(|| {
            sparse_config
                .and_then(|config| config.get("sparse_local_block"))
                .and_then(serde_json::Value::as_u64)
        })
        .unwrap_or(1) as usize;
    if num_heads != config.num_key_value_heads {
        bail!(
            "MiniMax-M3 index_n_heads={num_heads} must equal num_key_value_heads={} for GQA sparse routing",
            config.num_key_value_heads
        );
    }
    if config.rotary_dim > head_dim {
        bail!(
            "MiniMax-M3 rotary_dim={} exceeds index_head_dim={head_dim}",
            config.rotary_dim
        );
    }

    let sparse_layers = if let Some(layer_types) = package_config
        .get("layer_types")
        .filter(|value| !value.is_null())
    {
        let layer_types = layer_types
            .as_array()
            .context("MiniMax-M3 layer_types must be an array or null")?;
        if layer_types.len() != config.num_layers {
            bail!(
                "MiniMax-M3 layer_types has {} entries for {} decoder layers",
                layer_types.len(),
                config.num_layers
            );
        }
        layer_types
            .iter()
            .enumerate()
            .map(|(index, layer_type)| match layer_type.as_str() {
                Some("minimax_m3_sparse") => Ok(true),
                Some("full_attention") => Ok(false),
                Some(other) => bail!(
                    "unsupported MiniMax-M3 layer_types[{index}]={other:?}; expected full_attention or minimax_m3_sparse"
                ),
                None => bail!("MiniMax-M3 layer_types[{index}] must be a string"),
            })
            .collect::<Result<Vec<_>>>()?
    } else if let Some(frequency) = sparse_config
        .and_then(|config| config.get("sparse_attention_freq"))
        .filter(|value| !value.is_null())
    {
        let frequency = frequency
            .as_array()
            .context("MiniMax-M3 sparse_attention_freq must be an array or null")?;
        if frequency.len() != config.num_layers {
            bail!(
                "MiniMax-M3 sparse_attention_freq has {} entries for {} decoder layers",
                frequency.len(),
                config.num_layers
            );
        }
        frequency
            .iter()
            .enumerate()
            .map(|(index, flag)| {
                flag.as_bool()
                    .or_else(|| {
                        flag.as_u64()
                            .filter(|value| *value <= 1)
                            .map(|value| value != 0)
                    })
                    .with_context(|| {
                        format!(
                            "MiniMax-M3 sparse_attention_freq[{index}] must be a boolean/0/1 value"
                        )
                    })
            })
            .collect::<Result<Vec<_>>>()?
    } else {
        vec![false; config.num_layers]
    };
    if !sparse_layers.iter().copied().any(|sparse| sparse) {
        return Ok(None);
    }

    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let backbone_prefix = [
        "model",
        "model.language_model",
        "model.text_model",
        "language_model",
        "",
    ]
    .into_iter()
    .find(|prefix| {
        let name = if prefix.is_empty() {
            "embed_tokens.weight".to_owned()
        } else {
            format!("{prefix}.embed_tokens.weight")
        };
        store.contains(&name)
    })
    .context("MiniMax-M3 checkpoint is missing the text backbone")?;
    let backbone_name = |suffix: &str| {
        if backbone_prefix.is_empty() {
            suffix.to_owned()
        } else {
            format!("{backbone_prefix}.{suffix}")
        }
    };
    let q_width = num_heads
        .checked_mul(head_dim)
        .context("MiniMax-M3 indexer query width overflow")?;
    let mut indexers = Vec::with_capacity(config.num_layers);
    for (layer, sparse) in sparse_layers.into_iter().enumerate() {
        if !sparse {
            indexers.push(None);
            continue;
        }
        let p = backbone_name(&format!("layers.{layer}.self_attn.indexer"));
        indexers.push(Some(HostMiniMaxM3Indexer {
            q_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.q_proj.weight"),
                    &[q_width, config.hidden_size],
                )?,
                bias: None,
            },
            k_proj: HostLinear {
                weight: store.take_expected(
                    &format!("{p}.k_proj.weight"),
                    &[head_dim, config.hidden_size],
                )?,
                bias: None,
            },
            q_norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.q_norm.weight"), &[head_dim])?,
                bias: Vec::new(),
            },
            k_norm: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.k_norm.weight"), &[head_dim])?,
                bias: Vec::new(),
            },
            num_heads,
            head_dim,
            rotary_dim: config.rotary_dim,
            block_size,
            topk_blocks,
            local_blocks,
            interleaved_pairs: config.rope_interleaved_pairs(),
        }));
    }
    Ok(Some(indexers))
}

fn deepseek_v4_hash_moe_mask(
    package_config: &serde_json::Value,
    num_layers: usize,
) -> Result<Option<Vec<bool>>> {
    if package_config
        .get("model_type")
        .and_then(serde_json::Value::as_str)
        != Some("deepseek_v4")
    {
        return Ok(None);
    }
    if let Some(layer_types) = package_config
        .get("mlp_layer_types")
        .filter(|value| !value.is_null())
    {
        let layer_types = layer_types
            .as_array()
            .context("DeepSeek-V4 mlp_layer_types must be an array or null")?;
        if layer_types.len() < num_layers {
            bail!(
                "DeepSeek-V4 mlp_layer_types has only {} entries for {num_layers} decoder layers",
                layer_types.len()
            );
        }
        return layer_types
            .iter()
            .take(num_layers)
            .enumerate()
            .map(|(layer, kind)| match kind.as_str() {
                Some("hash_moe") => Ok(true),
                Some("moe") => Ok(false),
                Some(kind) => bail!(
                    "DeepSeek-V4 mlp_layer_types[{layer}] must be hash_moe or moe, got {kind:?}"
                ),
                None => bail!("DeepSeek-V4 mlp_layer_types[{layer}] must be a string"),
            })
            .collect::<Result<Vec<_>>>()
            .map(Some);
    }
    let num_hash_layers = package_config
        .get("num_hash_layers")
        .filter(|value| !value.is_null())
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(3) as usize;
    Ok(Some(
        (0..num_layers)
            .map(|layer| layer < num_hash_layers.min(num_layers))
            .collect(),
    ))
}

fn architecture_uses_packed_moe_loader(architecture: VulkanTransformerArchitecture) -> bool {
    matches!(
        architecture,
        VulkanTransformerArchitecture::Mixtral
            | VulkanTransformerArchitecture::Phimoe
            | VulkanTransformerArchitecture::Llama4Text
            | VulkanTransformerArchitecture::AriaText
            | VulkanTransformerArchitecture::Afmoe
            | VulkanTransformerArchitecture::Laguna
            | VulkanTransformerArchitecture::HyV3
            | VulkanTransformerArchitecture::Qwen2Moe
            | VulkanTransformerArchitecture::Qwen3Moe
            | VulkanTransformerArchitecture::Qwen3Next
            | VulkanTransformerArchitecture::Qwen35Moe
            | VulkanTransformerArchitecture::Qwen4Exp
            | VulkanTransformerArchitecture::Dots1
            | VulkanTransformerArchitecture::Mellum
            | VulkanTransformerArchitecture::GptOss
            | VulkanTransformerArchitecture::Cohere2Moe
            | VulkanTransformerArchitecture::GraniteMoe
            | VulkanTransformerArchitecture::GraniteMoeShared
            | VulkanTransformerArchitecture::GraniteMoeSwa
            | VulkanTransformerArchitecture::Olmoe
            | VulkanTransformerArchitecture::FlexOlmo
            | VulkanTransformerArchitecture::MiniMaxM2
            | VulkanTransformerArchitecture::MiniMaxM3VLText
            | VulkanTransformerArchitecture::Ernie45Moe
            | VulkanTransformerArchitecture::HunYuanMoeV1
            | VulkanTransformerArchitecture::ExaoneMoe
            | VulkanTransformerArchitecture::Glm4Moe
            | VulkanTransformerArchitecture::SolarOpen
            | VulkanTransformerArchitecture::MiMoV2Flash
            | VulkanTransformerArchitecture::DeepseekV2
            | VulkanTransformerArchitecture::DeepseekV3
            | VulkanTransformerArchitecture::Glm5Next
            | VulkanTransformerArchitecture::DeepseekV4
            | VulkanTransformerArchitecture::Axk1
            | VulkanTransformerArchitecture::Mistral4
            | VulkanTransformerArchitecture::KimiLinear
    )
}

fn load_mixtral_moe_layers(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<HostMoeLayer>> {
    if !architecture_uses_packed_moe_loader(config.architecture) {
        bail!(
            "packed MoE loader requires a supported sparse-MoE architecture, including KimiLinear"
        );
    }
    let moe = config
        .moe
        .as_ref()
        .context("Mixtral config is missing MoE parameters")?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    // Most packed-MoE loaders need only the already-validated native config
    // passed by the caller. Re-reading config.json here made those loaders
    // unnecessarily depend on a complete package even when operating on an
    // already-resolved config (for example fixture/model-store consumers).
    // Keep the raw package read fail-closed only for families whose checkpoint
    // layout still depends on fields that are intentionally not duplicated in
    // VulkanTransformerConfig.
    let package_config = if matches!(
        config.architecture,
        VulkanTransformerArchitecture::AriaText
            | VulkanTransformerArchitecture::HyV3
            | VulkanTransformerArchitecture::Ernie45Moe
            | VulkanTransformerArchitecture::DeepseekV4
            | VulkanTransformerArchitecture::KimiLinear
    ) {
        transformer_text_config_from_package(model_dir)?
    } else {
        serde_json::Value::Null
    };
    let kimi_routed_hidden = if config.architecture == VulkanTransformerArchitecture::KimiLinear {
        package_config
            .get("routed_expert_hidden_size")
            .filter(|value| !value.is_null())
            .map(|value| {
                value
                    .as_u64()
                    .and_then(|value| usize::try_from(value).ok())
                    .filter(|value| *value != 0)
                    .context("KimiLinear routed_expert_hidden_size must be a positive integer or null")
            })
            .transpose()?
    } else {
        None
    };
    let kimi_latent_moe_use_norm = if config.architecture
        == VulkanTransformerArchitecture::KimiLinear
    {
        match package_config.get("latent_moe_use_norm") {
            Some(value) if !value.is_null() => value
                .as_bool()
                .context("KimiLinear latent_moe_use_norm must be a boolean or null")?,
            _ => false,
        }
    } else {
        false
    };
    if kimi_latent_moe_use_norm && kimi_routed_hidden.is_none() {
        bail!("KimiLinear latent_moe_use_norm=true requires routed_expert_hidden_size");
    }
    let deepseek_v4_hash_layers = deepseek_v4_hash_moe_mask(&package_config, config.num_layers)?;
    let aria_mlp_bias = if config.architecture == VulkanTransformerArchitecture::AriaText {
        package_config
            .get("mlp_bias")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
    } else {
        false
    };
    let hy_v3_mlp_bias = if config.architecture == VulkanTransformerArchitecture::HyV3 {
        package_config
            .get("mlp_bias")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
    } else {
        false
    };
    let ernie_use_bias = if config.architecture == VulkanTransformerArchitecture::Ernie45Moe {
        package_config
            .get("use_bias")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
    } else {
        false
    };
    let mut layers = Vec::with_capacity(
        (0..config.num_layers)
            .filter(|&layer| config.layer_uses_moe(layer))
            .count(),
    );
    for layer in 0..config.num_layers {
        if !config.layer_uses_moe(layer) {
            continue;
        }
        let p = format!("model.layers.{layer}");
        let granite_packed_moe = matches!(
            config.architecture,
            VulkanTransformerArchitecture::GraniteMoe
                | VulkanTransformerArchitecture::GraniteMoeShared
                | VulkanTransformerArchitecture::GraniteMoeSwa
        );
        let current_router = if config.architecture == VulkanTransformerArchitecture::KimiLinear {
            format!("{p}.block_sparse_moe.gate.weight")
        } else if config.architecture == VulkanTransformerArchitecture::Llama4Text {
            format!("{p}.feed_forward.router.weight")
        } else if config.architecture == VulkanTransformerArchitecture::Afmoe {
            format!("{p}.mlp.router.gate.weight")
        } else if config.architecture == VulkanTransformerArchitecture::HunYuanMoeV1 {
            format!("{p}.mlp.gate.wg.weight")
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::AriaText | VulkanTransformerArchitecture::GptOss
        ) {
            format!("{p}.mlp.router.weight")
        } else if granite_packed_moe {
            format!("{p}.block_sparse_moe.router.weight")
        } else {
            format!("{p}.mlp.gate.weight")
        };
        let legacy_router = format!("{p}.block_sparse_moe.gate.weight");
        let router = HostLinear {
            weight: if store.contains(&current_router) {
                store.take_expected(&current_router, &[moe.num_experts, d])?
            } else {
                store.take_expected(&legacy_router, &[moe.num_experts, d])?
            },
            bias: if config.architecture == VulkanTransformerArchitecture::GptOss {
                Some(store.take_expected(&format!("{p}.mlp.router.bias"), &[moe.num_experts])?)
            } else {
                None
            },
        };
        let router_correction_bias_name = match config.architecture {
            VulkanTransformerArchitecture::KimiLinear => {
                format!("{p}.block_sparse_moe.gate.e_score_correction_bias")
            }
            VulkanTransformerArchitecture::Afmoe => format!("{p}.mlp.expert_bias"),
            VulkanTransformerArchitecture::HyV3 | VulkanTransformerArchitecture::MiniMaxM2 => {
                format!("{p}.mlp.e_score_correction_bias")
            }
            VulkanTransformerArchitecture::Ernie45Moe => {
                format!("{p}.mlp.gate.moe_statics.e_score_correction_bias")
            }
            _ => format!("{p}.mlp.gate.e_score_correction_bias"),
        };
        let router_correction_bias = if store.contains(&router_correction_bias_name) {
            if config.architecture == VulkanTransformerArchitecture::Ernie45Moe {
                store.take_expected(&router_correction_bias_name, &[1, moe.num_experts])?
            } else {
                store.take_expected(&router_correction_bias_name, &[moe.num_experts])?
            }
        } else {
            vec![0.0; moe.num_experts]
        };
        let (current_gate_up, current_down) =
            if config.architecture == VulkanTransformerArchitecture::Llama4Text {
                (
                    format!("{p}.feed_forward.experts.gate_up_proj"),
                    format!("{p}.feed_forward.experts.down_proj"),
                )
            } else if config.architecture == VulkanTransformerArchitecture::AriaText {
                (
                    format!("{p}.mlp.experts.fc1.weight"),
                    format!("{p}.mlp.experts.fc2.weight"),
                )
            } else if granite_packed_moe {
                (
                    format!("{p}.block_sparse_moe.experts.gate_up_proj"),
                    format!("{p}.block_sparse_moe.experts.down_proj"),
                )
            } else {
                (
                    format!("{p}.mlp.experts.gate_up_proj"),
                    format!("{p}.mlp.experts.down_proj"),
                )
            };
        let mut experts = Vec::with_capacity(moe.num_experts.saturating_sub(1));
        let mut owned_expert0 = None;
        if config.architecture == VulkanTransformerArchitecture::KimiLinear {
            let routed_hidden = kimi_routed_hidden.unwrap_or(d);
            let mut load_expert = |expert_index: usize| -> Result<HostMoeExpert> {
                let expert = format!("{p}.block_sparse_moe.experts.{expert_index}");
                Ok(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: store.take_expected(
                            &format!("{expert}.w1.weight"),
                            &[i, routed_hidden],
                        )?,
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: store.take_expected(
                            &format!("{expert}.w3.weight"),
                            &[i, routed_hidden],
                        )?,
                        bias: None,
                    },
                    down: HostLinear {
                        weight: store.take_expected(
                            &format!("{expert}.w2.weight"),
                            &[routed_hidden, i],
                        )?,
                        bias: None,
                    },
                })
            };
            owned_expert0 = Some(load_expert(0)?);
            for expert_index in 1..moe.num_experts {
                experts.push(load_expert(expert_index)?);
            }
        } else if config.architecture == VulkanTransformerArchitecture::Llama4Text {
            let gate_up = store.take_expected(&current_gate_up, &[moe.num_experts, d, 2 * i])?;
            let down = store.take_expected(&current_down, &[moe.num_experts, i, d])?;
            let gate_up_stride = d * 2 * i;
            let down_stride = i * d;
            let split = i * d;
            for expert_index in 1..moe.num_experts {
                let gate_up_base = expert_index * gate_up_stride;
                let down_base = expert_index * down_stride;
                let packed = transpose(
                    &gate_up[gate_up_base..gate_up_base + gate_up_stride],
                    d,
                    2 * i,
                );
                experts.push(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: packed[..split].to_vec(),
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: packed[split..].to_vec(),
                        bias: None,
                    },
                    down: HostLinear {
                        weight: transpose(&down[down_base..down_base + down_stride], i, d),
                        bias: None,
                    },
                });
            }
        } else if config.architecture == VulkanTransformerArchitecture::AriaText {
            let fc1 = store.take_expected(&current_gate_up, &[moe.num_experts, d, 2 * i])?;
            let fc2 = store.take_expected(&current_down, &[moe.num_experts, i, d])?;
            let fc1_stride = d * 2 * i;
            let fc2_stride = i * d;
            let split = i * d;
            for expert_index in 1..moe.num_experts {
                let fc1_base = expert_index * fc1_stride;
                let fc2_base = expert_index * fc2_stride;
                let packed = transpose(&fc1[fc1_base..fc1_base + fc1_stride], d, 2 * i);
                experts.push(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: packed[..split].to_vec(),
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: packed[split..].to_vec(),
                        bias: None,
                    },
                    down: HostLinear {
                        weight: transpose(&fc2[fc2_base..fc2_base + fc2_stride], i, d),
                        bias: None,
                    },
                });
            }
        } else if config.architecture == VulkanTransformerArchitecture::GptOss {
            let gate_up = store.take_expected(&current_gate_up, &[moe.num_experts, d, 2 * i])?;
            let gate_up_bias = store.take_expected(
                &format!("{p}.mlp.experts.gate_up_proj_bias"),
                &[moe.num_experts, 2 * i],
            )?;
            let down = store.take_expected(&current_down, &[moe.num_experts, i, d])?;
            let down_bias = store.take_expected(
                &format!("{p}.mlp.experts.down_proj_bias"),
                &[moe.num_experts, d],
            )?;
            let gate_up_stride = d * 2 * i;
            let gate_up_bias_stride = 2 * i;
            let down_stride = i * d;
            for expert_index in 1..moe.num_experts {
                let gate_up_base = expert_index * gate_up_stride;
                let gate_up_bias_base = expert_index * gate_up_bias_stride;
                let down_base = expert_index * down_stride;
                let down_bias_base = expert_index * d;
                let (gate_weight, up_weight) = gpt_oss_deinterleave_gate_up(
                    &gate_up[gate_up_base..gate_up_base + gate_up_stride],
                    d,
                    i,
                )?;
                let (gate_bias, up_bias) = gpt_oss_deinterleave_gate_up_bias(
                    &gate_up_bias[gate_up_bias_base..gate_up_bias_base + gate_up_bias_stride],
                    i,
                )?;
                experts.push(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: gate_weight,
                        bias: Some(gate_bias),
                    }),
                    up: HostLinear {
                        weight: up_weight,
                        bias: Some(up_bias),
                    },
                    down: HostLinear {
                        weight: transpose(&down[down_base..down_base + down_stride], i, d),
                        bias: Some(down_bias[down_bias_base..down_bias_base + d].to_vec()),
                    },
                });
            }
        } else if store.contains(&current_gate_up) {
            let gate_up = store.take_expected(&current_gate_up, &[moe.num_experts, 2 * i, d])?;
            let down = store.take_expected(&current_down, &[moe.num_experts, d, i])?;
            let gate_up_stride = 2 * i * d;
            let split = i * d;
            let down_stride = d * i;
            for expert_index in 1..moe.num_experts {
                let gate_up_base = expert_index * gate_up_stride;
                let down_base = expert_index * down_stride;
                experts.push(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: gate_up[gate_up_base..gate_up_base + split].to_vec(),
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: gate_up[gate_up_base + split..gate_up_base + gate_up_stride]
                            .to_vec(),
                        bias: None,
                    },
                    down: HostLinear {
                        weight: down[down_base..down_base + down_stride].to_vec(),
                        bias: None,
                    },
                });
            }
        } else {
            for expert_index in 1..moe.num_experts {
                let hf_expert = format!("{p}.mlp.experts.{expert_index}");
                let hf_gate = format!("{hf_expert}.gate_proj.weight");
                if store.contains(&hf_gate) {
                    experts.push(HostMoeExpert {
                        gate: Some(HostLinear {
                            weight: store.take_expected(&hf_gate, &[i, d])?,
                            bias: None,
                        }),
                        up: HostLinear {
                            weight: store
                                .take_expected(&format!("{hf_expert}.up_proj.weight"), &[i, d])?,
                            bias: None,
                        },
                        down: HostLinear {
                            weight: store
                                .take_expected(&format!("{hf_expert}.down_proj.weight"), &[d, i])?,
                            bias: None,
                        },
                    });
                } else {
                    let expert = format!("{p}.block_sparse_moe.experts.{expert_index}");
                    experts.push(HostMoeExpert {
                        gate: Some(HostLinear {
                            weight: store.take_expected(&format!("{expert}.w1.weight"), &[i, d])?,
                            bias: None,
                        }),
                        up: HostLinear {
                            weight: store.take_expected(&format!("{expert}.w3.weight"), &[i, d])?,
                            bias: None,
                        },
                        down: HostLinear {
                            weight: store.take_expected(&format!("{expert}.w2.weight"), &[d, i])?,
                            bias: None,
                        },
                    });
                }
            }
        }
        let (shared_expert, shared_expert_gate) = if config.architecture
            == VulkanTransformerArchitecture::KimiLinear
        {
            let shared_i = moe.shared_expert_intermediate_size;
            if shared_i == 0 {
                (None, None)
            } else {
                (
                    Some(HostMoeExpert {
                        gate: Some(HostLinear {
                            weight: store.take_expected(
                                &format!("{p}.block_sparse_moe.shared_experts.gate_proj.weight"),
                                &[shared_i, d],
                            )?,
                            bias: None,
                        }),
                        up: HostLinear {
                            weight: store.take_expected(
                                &format!("{p}.block_sparse_moe.shared_experts.up_proj.weight"),
                                &[shared_i, d],
                            )?,
                            bias: None,
                        },
                        down: HostLinear {
                            weight: store.take_expected(
                                &format!("{p}.block_sparse_moe.shared_experts.down_proj.weight"),
                                &[d, shared_i],
                            )?,
                            bias: None,
                        },
                    }),
                    None,
                )
            }
        } else if config.architecture == VulkanTransformerArchitecture::Llama4Text
        {
            let shared_i = moe.shared_expert_intermediate_size;
            (
                Some(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.feed_forward.shared_expert.gate_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.feed_forward.shared_expert.up_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: None,
                    },
                    down: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.feed_forward.shared_expert.down_proj.weight"),
                            &[d, shared_i],
                        )?,
                        bias: None,
                    },
                }),
                None,
            )
        } else if config.architecture == VulkanTransformerArchitecture::MiniMaxM3VLText {
            let shared_i = moe.shared_expert_intermediate_size;
            let gate_up = store.take_expected(
                &format!("{p}.mlp.shared_experts.gate_up_proj.weight"),
                &[2 * shared_i, d],
            )?;
            let split = shared_i * d;
            (
                Some(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: gate_up[..split].to_vec(),
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: gate_up[split..].to_vec(),
                        bias: None,
                    },
                    down: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_experts.down_proj.weight"),
                            &[d, shared_i],
                        )?,
                        bias: None,
                    },
                }),
                None,
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::AriaText
                | VulkanTransformerArchitecture::Afmoe
                | VulkanTransformerArchitecture::Laguna
                | VulkanTransformerArchitecture::HyV3
        ) || (config.architecture == VulkanTransformerArchitecture::Cohere2Moe
            && moe.shared_expert_intermediate_size > 0)
            || (config.architecture == VulkanTransformerArchitecture::Ernie45Moe
                && moe.shared_expert_intermediate_size > 0)
        {
            let shared_i = moe.shared_expert_intermediate_size;
            let bias = |store: &mut Gpt2TensorStore,
                        name: String,
                        len: usize|
             -> Result<Option<Vec<f32>>> {
                if (config.architecture == VulkanTransformerArchitecture::AriaText && aria_mlp_bias)
                    || (config.architecture == VulkanTransformerArchitecture::HyV3
                        && hy_v3_mlp_bias)
                    || (config.architecture == VulkanTransformerArchitecture::Ernie45Moe
                        && ernie_use_bias)
                {
                    Ok(Some(store.take_expected(&name, &[len])?))
                } else {
                    Ok(None)
                }
            };
            (
                Some(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_experts.gate_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: bias(
                            &mut store,
                            format!("{p}.mlp.shared_experts.gate_proj.bias"),
                            shared_i,
                        )?,
                    }),
                    up: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_experts.up_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: bias(
                            &mut store,
                            format!("{p}.mlp.shared_experts.up_proj.bias"),
                            shared_i,
                        )?,
                    },
                    down: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_experts.down_proj.weight"),
                            &[d, shared_i],
                        )?,
                        bias: bias(
                            &mut store,
                            format!("{p}.mlp.shared_experts.down_proj.bias"),
                            d,
                        )?,
                    },
                }),
                None,
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::Qwen2Moe
                | VulkanTransformerArchitecture::Qwen3Next
                | VulkanTransformerArchitecture::Qwen35Moe
                | VulkanTransformerArchitecture::Qwen4Exp
        ) {
            let shared_i = moe.shared_expert_intermediate_size;
            (
                Some(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_expert.gate_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_expert.up_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: None,
                    },
                    down: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_expert.down_proj.weight"),
                            &[d, shared_i],
                        )?,
                        bias: None,
                    },
                }),
                Some(HostLinear {
                    weight: store
                        .take_expected(&format!("{p}.mlp.shared_expert_gate.weight"), &[1, d])?,
                    bias: None,
                }),
            )
        } else if config.architecture == VulkanTransformerArchitecture::HunYuanMoeV1 {
            let shared_i = moe.shared_expert_intermediate_size;
            (
                Some(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_mlp.gate_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_mlp.up_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: None,
                    },
                    down: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_mlp.down_proj.weight"),
                            &[d, shared_i],
                        )?,
                        bias: None,
                    },
                }),
                None,
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::SolarOpen
                | VulkanTransformerArchitecture::Dots1
                | VulkanTransformerArchitecture::Glm4Moe
                | VulkanTransformerArchitecture::DeepseekV3
                | VulkanTransformerArchitecture::Glm5Next
                | VulkanTransformerArchitecture::DeepseekV4
                | VulkanTransformerArchitecture::Axk1
                | VulkanTransformerArchitecture::Mistral4
        ) {
            let shared_i = moe.shared_expert_intermediate_size;
            (
                Some(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_experts.gate_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_experts.up_proj.weight"),
                            &[shared_i, d],
                        )?,
                        bias: None,
                    },
                    down: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.mlp.shared_experts.down_proj.weight"),
                            &[d, shared_i],
                        )?,
                        bias: None,
                    },
                }),
                None,
            )
        } else if matches!(
            config.architecture,
            VulkanTransformerArchitecture::GraniteMoeShared
                | VulkanTransformerArchitecture::GraniteMoeSwa
        ) && moe.shared_expert_intermediate_size > 0
        {
            let shared_i = moe.shared_expert_intermediate_size;
            let packed = store.take_expected(
                &format!("{p}.shared_mlp.input_linear.weight"),
                &[2 * shared_i, d],
            )?;
            let split = shared_i * d;
            (
                Some(HostMoeExpert {
                    gate: Some(HostLinear {
                        weight: packed[..split].to_vec(),
                        bias: None,
                    }),
                    up: HostLinear {
                        weight: packed[split..].to_vec(),
                        bias: None,
                    },
                    down: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.shared_mlp.output_linear.weight"),
                            &[d, shared_i],
                        )?,
                        bias: None,
                    },
                }),
                None,
            )
        } else {
            (None, None)
        };
        let latent = if config.architecture == VulkanTransformerArchitecture::KimiLinear {
            if let Some(routed_hidden) = kimi_routed_hidden {
                Some(HostMoeLatent {
                    hidden_size: routed_hidden,
                    down_proj: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.block_sparse_moe.routed_expert_down_proj.weight"),
                            &[routed_hidden, d],
                        )?,
                        bias: None,
                    },
                    norm: if kimi_latent_moe_use_norm {
                        Some(HostLayerNorm {
                            weight: store.take_expected(
                                &format!("{p}.block_sparse_moe.routed_expert_norm.weight"),
                                &[routed_hidden],
                            )?,
                            bias: Vec::new(),
                        })
                    } else {
                        None
                    },
                    up_proj: HostLinear {
                        weight: store.take_expected(
                            &format!("{p}.block_sparse_moe.routed_expert_up_proj.weight"),
                            &[d, routed_hidden],
                        )?,
                        bias: None,
                    },
                })
            } else {
                None
            }
        } else {
            None
        };
        let hash_router = if deepseek_v4_hash_layers
            .as_ref()
            .is_some_and(|mask| mask[layer])
        {
            let vocab_size = package_config
                .get("vocab_size")
                .and_then(serde_json::Value::as_u64)
                .map(|value| value as usize)
                .filter(|value| *value != 0)
                .context("DeepSeek-V4 vocab_size must be a positive integer")?;
            let tid2eid_name = format!("{p}.mlp.gate.tid2eid");
            let tid2eid =
                load_transformer_u32_tensor(model_dir, &tid2eid_name, &[vocab_size, moe.top_k])?;
            Some(HostMoeHashRouter {
                vocab_size,
                top_k: moe.top_k,
                tid2eid,
            })
        } else {
            None
        };
        layers.push(HostMoeLayer {
            router,
            router_correction_bias,
            hash_router,
            expert_capacity: 0,
            owned_expert0,
            identity_expert_start: moe.num_experts,
            experts,
            shared_expert,
            shared_expert_gate,
            latent,
        });
    }
    Ok(layers)
}

fn load_afmoe_attention_gates(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<HostLinear>> {
    if config.architecture != VulkanTransformerArchitecture::Afmoe {
        bail!("AFMoE attention-gate loader requires an AFMoE graph");
    }
    let d = config.hidden_size;
    let q = config.query_hidden_size();
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let mut gates = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        gates.push(HostLinear {
            weight: store.take_expected(
                &format!("model.layers.{layer}.self_attn.gate_proj.weight"),
                &[q, d],
            )?,
            bias: None,
        });
    }
    Ok(gates)
}

fn load_laguna_attention_gates(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<HostLinear>> {
    if config.architecture != VulkanTransformerArchitecture::Laguna {
        bail!("Laguna attention-gate loader requires a Laguna graph");
    }
    let value = transformer_text_config_from_package(model_dir)?;
    let heads_per_layer = VulkanTransformerConfig::laguna_attention_heads_per_layer(
        &value,
        config.num_layers,
        config.num_heads,
        config.num_key_value_heads,
    )?;
    let gate_per_head = VulkanTransformerConfig::laguna_attention_gate_per_head(&value)?;
    let d = config.hidden_size;
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    let mut gates = Vec::with_capacity(config.num_layers);
    for (layer, num_heads) in heads_per_layer.into_iter().enumerate() {
        let output_dim = if gate_per_head {
            num_heads
        } else {
            num_heads
                .checked_mul(config.head_dim)
                .context("Laguna attention gate width overflow")?
        };
        gates.push(HostLinear {
            weight: store.take_expected(
                &format!("model.layers.{layer}.self_attn.g_proj.weight"),
                &[output_dim, d],
            )?,
            bias: None,
        });
    }
    Ok(gates)
}

fn load_dbrx_moe_layers(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<HostMoeLayer>> {
    if config.architecture != VulkanTransformerArchitecture::Dbrx {
        bail!("DBRX MoE loader requires a DBRX graph");
    }
    let moe = config
        .moe
        .as_ref()
        .context("DBRX config is missing MoE parameters")?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let packed_rows = moe
        .num_experts
        .checked_mul(i)
        .context("DBRX packed expert row count overflow")?;
    let expert_stride = i
        .checked_mul(d)
        .context("DBRX expert tensor stride overflow")?;
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("transformer.blocks.{layer}.ffn");
        let router = HostLinear {
            weight: store
                .take_expected(&format!("{p}.router.layer.weight"), &[moe.num_experts, d])?,
            bias: None,
        };
        let experts_prefix = format!("{p}.experts.mlp");
        let w1 = store.take_expected(&format!("{experts_prefix}.w1"), &[packed_rows, d])?;
        let v1 = store.take_expected(&format!("{experts_prefix}.v1"), &[packed_rows, d])?;
        let w2 = store.take_expected(&format!("{experts_prefix}.w2"), &[packed_rows, d])?;
        let mut experts = Vec::with_capacity(moe.num_experts.saturating_sub(1));
        for expert_index in 1..moe.num_experts {
            let base = expert_index
                .checked_mul(expert_stride)
                .context("DBRX expert tensor offset overflow")?;
            let end = base + expert_stride;
            experts.push(HostMoeExpert {
                gate: Some(HostLinear {
                    weight: w1[base..end].to_vec(),
                    bias: None,
                }),
                up: HostLinear {
                    weight: v1[base..end].to_vec(),
                    bias: None,
                },
                down: HostLinear {
                    weight: transpose(&w2[base..end], i, d),
                    bias: None,
                },
            });
        }
        layers.push(HostMoeLayer {
            router,
            router_correction_bias: vec![0.0; moe.num_experts],
            hash_router: None,
            expert_capacity: 0,
            owned_expert0: None,
            identity_expert_start: moe.num_experts,
            experts,
            shared_expert: None,
            shared_expert_gate: None,
            latent: None,
        });
    }
    Ok(layers)
}

fn load_esmc_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    if config.architecture != VulkanTransformerArchitecture::Esmc {
        bail!("ESMC checkpoint loader requires an ESMC graph");
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let q = config.query_hidden_size();
    let kv = config.key_value_hidden_size();
    if q != d || kv != d {
        bail!("ESMC requires full-width MHA Q/K/V projections");
    }
    let package_config: serde_json::Value = serde_json::from_slice(
        &fs::read(model_dir.join("config.json")).context("reading ESMC config.json")?,
    )
    .context("decoding ESMC config.json")?;
    let attention_bias = package_config
        .get("attention_bias")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let mlp_bias = package_config
        .get("mlp_bias")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let token_embedding =
        store.take_expected("esmc.embed_tokens.weight", &[config.vocab_size, d])?;
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("esmc.layers.{layer}");
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.input_layernorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.input_layernorm.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(HostLinear {
                weight: store.take_expected(&format!("{p}.self_attn.q_proj.weight"), &[d, d])?,
                bias: if attention_bias {
                    Some(store.take_expected(&format!("{p}.self_attn.q_proj.bias"), &[d])?)
                } else {
                    None
                },
            }),
            k_proj: Some(HostLinear {
                weight: store.take_expected(&format!("{p}.self_attn.k_proj.weight"), &[d, d])?,
                bias: if attention_bias {
                    Some(store.take_expected(&format!("{p}.self_attn.k_proj.bias"), &[d])?)
                } else {
                    None
                },
            }),
            v_proj: Some(HostLinear {
                weight: store.take_expected(&format!("{p}.self_attn.v_proj.weight"), &[d, d])?,
                bias: if attention_bias {
                    Some(store.take_expected(&format!("{p}.self_attn.v_proj.bias"), &[d])?)
                } else {
                    None
                },
            }),
            q_norm: Some(HostLayerNorm {
                weight: store.take_expected(&format!("{p}.self_attn.q_norm.weight"), &[d])?,
                bias: Vec::new(),
            }),
            k_norm: Some(HostLayerNorm {
                weight: store.take_expected(&format!("{p}.self_attn.k_norm.weight"), &[d])?,
                bias: Vec::new(),
            }),
            c_proj: HostLinear {
                weight: store.take_expected(&format!("{p}.self_attn.o_proj.weight"), &[d, d])?,
                bias: if attention_bias {
                    Some(store.take_expected(&format!("{p}.self_attn.o_proj.bias"), &[d])?)
                } else {
                    None
                },
            },
            ln2: HostLayerNorm {
                weight: store
                    .take_expected(&format!("{p}.post_attention_layernorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.post_attention_layernorm.bias"), &[d])?,
            },
            c_fc: HostLinear {
                weight: store.take_expected(&format!("{p}.mlp.up_proj.weight"), &[i, d])?,
                bias: if mlp_bias {
                    Some(store.take_expected(&format!("{p}.mlp.up_proj.bias"), &[i])?)
                } else {
                    None
                },
            },
            c_gate: Some(HostLinear {
                weight: store.take_expected(&format!("{p}.mlp.gate_proj.weight"), &[i, d])?,
                bias: if mlp_bias {
                    Some(store.take_expected(&format!("{p}.mlp.gate_proj.bias"), &[i])?)
                } else {
                    None
                },
            }),
            c_mlp_proj: HostLinear {
                weight: store.take_expected(&format!("{p}.mlp.down_proj.weight"), &[d, i])?,
                bias: if mlp_bias {
                    Some(store.take_expected(&format!("{p}.mlp.down_proj.bias"), &[d])?)
                } else {
                    None
                },
            },
            xielu: None,
        });
    }
    let final_norm = HostLayerNorm {
        weight: store.take_expected("esmc.norm.weight", &[d])?,
        bias: Vec::new(),
    };
    let prediction_head = HostPredictionHead {
        dense: HostLinear {
            weight: store.take_expected("lm_head.dense.weight", &[d, d])?,
            bias: Some(store.take_expected("lm_head.dense.bias", &[d])?),
        },
        activation_function: "gelu".to_owned(),
        norm: HostLayerNorm {
            weight: store.take_expected("lm_head.layer_norm.weight", &[d])?,
            bias: store.take_expected("lm_head.layer_norm.bias", &[d])?,
        },
    };
    let decoder = store.take_expected("lm_head.decoder.weight", &[config.vocab_size, d])?;
    let has_lm_head_alias = config.tie_word_embeddings;
    let lm_head = if config.tie_word_embeddings {
        if decoder != token_embedding {
            bail!(
                "ESMC package declares tied word embeddings but lm_head.decoder.weight differs from esmc.embed_tokens.weight"
            );
        }
        None
    } else {
        Some(decoder)
    };
    let lm_head_bias = Some(store.take_expected("lm_head.decoder.bias", &[config.vocab_size])?);
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: None,
        embedding_norm: None,
        layers,
        final_norm,
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_esm_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    if config.architecture != VulkanTransformerArchitecture::Esm {
        bail!("ESM checkpoint loader requires an ESM graph");
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    if config.query_hidden_size() != d || config.key_value_hidden_size() != d {
        bail!("ESM requires full-width multi-head Q/K/V projections");
    }
    let config_path = model_dir.join("config.json");
    let package_config: serde_json::Value = serde_json::from_slice(
        &fs::read(&config_path).with_context(|| format!("reading {}", config_path.display()))?,
    )
    .with_context(|| format!("decoding {}", config_path.display()))?;

    let token_embedding = store.take_expected(
        "esm.embeddings.word_embeddings.weight",
        &[config.vocab_size, d],
    )?;
    let position_embedding = if config.rotary_dim == 0 {
        Some(store.take_expected(
            "esm.embeddings.position_embeddings.weight",
            &[config.max_position_embeddings, d],
        )?)
    } else {
        None
    };
    let embedding_norm = if package_config
        .get("emb_layer_norm_before")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        Some(HostLayerNorm {
            weight: store.take_expected("esm.embeddings.layer_norm.weight", &[d])?,
            bias: store.take_expected("esm.embeddings.layer_norm.bias", &[d])?,
        })
    } else {
        None
    };

    let linear = |store: &mut Gpt2TensorStore, name: &str, out: usize, input: usize| {
        Ok::<HostLinear, anyhow::Error>(HostLinear {
            weight: store.take_expected(&format!("{name}.weight"), &[out, input])?,
            bias: Some(store.take_expected(&format!("{name}.bias"), &[out])?),
        })
    };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("esm.encoder.layer.{layer}");
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.attention.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.attention.LayerNorm.bias"), &[d])?,
            },
            c_attn: None,
            q_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.query"),
                d,
                d,
            )?),
            k_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.key"),
                d,
                d,
            )?),
            v_proj: Some(linear(
                &mut store,
                &format!("{p}.attention.self.value"),
                d,
                d,
            )?),
            q_norm: None,
            k_norm: None,
            c_proj: linear(&mut store, &format!("{p}.attention.output.dense"), d, d)?,
            ln2: HostLayerNorm {
                weight: store.take_expected(&format!("{p}.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.LayerNorm.bias"), &[d])?,
            },
            c_fc: linear(&mut store, &format!("{p}.intermediate.dense"), i, d)?,
            c_gate: None,
            c_mlp_proj: linear(&mut store, &format!("{p}.output.dense"), d, i)?,
            xielu: None,
        });
    }

    let final_norm = HostLayerNorm {
        weight: store.take_expected("esm.encoder.emb_layer_norm_after.weight", &[d])?,
        bias: store.take_expected("esm.encoder.emb_layer_norm_after.bias", &[d])?,
    };
    let prediction_head = HostPredictionHead {
        dense: linear(&mut store, "lm_head.dense", d, d)?,
        activation_function: "gelu".to_owned(),
        norm: HostLayerNorm {
            weight: store.take_expected("lm_head.layer_norm.weight", &[d])?,
            bias: store.take_expected("lm_head.layer_norm.bias", &[d])?,
        },
    };
    let has_lm_head_alias = config.tie_word_embeddings && store.contains("lm_head.decoder.weight");
    let lm_head = if config.tie_word_embeddings {
        if has_lm_head_alias {
            let alias = store.take_expected("lm_head.decoder.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!(
                    "ESM package declares tied word embeddings but lm_head.decoder.weight differs from esm.embeddings.word_embeddings.weight"
                );
            }
        }
        None
    } else {
        Some(store.take_expected("lm_head.decoder.weight", &[config.vocab_size, d])?)
    };
    let lm_head_bias = if store.contains("lm_head.bias") {
        Some(store.take_expected("lm_head.bias", &[config.vocab_size])?)
    } else if store.contains("lm_head.decoder.bias") {
        Some(store.take_expected("lm_head.decoder.bias", &[config.vocab_size])?)
    } else {
        bail!("ESM package is missing lm_head.bias")
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding,
        embedding_norm,
        layers,
        final_norm,
        prediction_head: Some(prediction_head),
        has_lm_head_alias,
        lm_head,
        lm_head_bias,
    })
}

fn load_esm_cross_attention_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Option<Vec<HostCrossAttention>>> {
    if config.architecture != VulkanTransformerArchitecture::Esm
        || !bert_family_cross_attention_enabled(model_dir)?
    {
        return Ok(None);
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let linear = |store: &mut Gpt2TensorStore, name: &str| -> Result<HostLinear> {
        Ok(HostLinear {
            weight: store.take_expected(&format!("{name}.weight"), &[d, d])?,
            bias: Some(store.take_expected(&format!("{name}.bias"), &[d])?),
        })
    };
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("esm.encoder.layer.{layer}.crossattention");
        layers.push(HostCrossAttention {
            q_proj: linear(&mut store, &format!("{p}.self.query"))?,
            k_proj: linear(&mut store, &format!("{p}.self.key"))?,
            v_proj: linear(&mut store, &format!("{p}.self.value"))?,
            out_proj: linear(&mut store, &format!("{p}.output.dense"))?,
            norm: HostLayerNorm {
                // ESM is pre-LN at the cross-attention site.
                weight: store.take_expected(&format!("{p}.LayerNorm.weight"), &[d])?,
                bias: store.take_expected(&format!("{p}.LayerNorm.bias"), &[d])?,
            },
            post_norm: None,
        });
    }
    Ok(Some(layers))
}

fn load_transformer_attention_sinks(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<Vec<f32>>> {
    if !matches!(
        config.architecture,
        VulkanTransformerArchitecture::GraniteSwa
            | VulkanTransformerArchitecture::GraniteMoeSwa
            | VulkanTransformerArchitecture::GptOss
    ) {
        bail!("attention-sink loading requires a GraniteSWA-family or GPT-OSS config");
    }
    let mut store = Gpt2TensorStore::load(model_dir)?;
    (0..config.num_layers)
        .map(|layer| {
            store.take_expected(
                &format!("model.layers.{layer}.self_attn.sinks"),
                &[config.num_heads],
            )
        })
        .collect()
}

fn load_mimo_v2_flash_attention_sinks(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<Vec<Option<Vec<f32>>>> {
    if config.architecture != VulkanTransformerArchitecture::MiMoV2Flash {
        bail!("MiMo-V2-Flash attention-sink loading requires a MiMo-V2-Flash config");
    }
    let value = transformer_text_config_from_package(model_dir)?;
    let layer_types =
        VulkanTransformerConfig::mimo_v2_flash_layer_types(&value, config.num_layers)?;
    let mut store = load_llama_layout_tensor_store(model_dir)?;
    layer_types
        .iter()
        .enumerate()
        .map(|(layer, layer_type)| {
            if layer_type == "sliding_attention" {
                Ok(Some(store.take_expected(
                    &format!("model.layers.{layer}.self_attn.sinks"),
                    &[config.num_heads],
                )?))
            } else {
                Ok(None)
            }
        })
        .collect()
}

fn load_phi3_weights(
    model_dir: &Path,
    config: &VulkanTransformerConfig,
) -> Result<HostTransformerWeights> {
    let mut store = Gpt2TensorStore::load(model_dir)?;
    let d = config.hidden_size;
    let i = config.intermediate_size;
    let q = config.query_hidden_size();
    let kv = config.key_value_hidden_size();
    let fused_qkv = q + 2 * kv;
    let token_embedding =
        store.take_expected("model.embed_tokens.weight", &[config.vocab_size, d])?;
    let mut layers = Vec::with_capacity(config.num_layers);
    for layer in 0..config.num_layers {
        let p = format!("model.layers.{layer}");
        let ln1 = HostLayerNorm {
            weight: store.take_expected(&format!("{p}.input_layernorm.weight"), &[d])?,
            bias: Vec::new(),
        };
        let c_attn = HostLinear {
            weight: store
                .take_expected(&format!("{p}.self_attn.qkv_proj.weight"), &[fused_qkv, d])?,
            bias: None,
        };
        let c_proj = HostLinear {
            weight: store.take_expected(&format!("{p}.self_attn.o_proj.weight"), &[d, d])?,
            bias: None,
        };
        let ln2 = HostLayerNorm {
            weight: store.take_expected(&format!("{p}.post_attention_layernorm.weight"), &[d])?,
            bias: Vec::new(),
        };
        let gate_up = store.take_expected(&format!("{p}.mlp.gate_up_proj.weight"), &[2 * i, d])?;
        let split = i * d;
        let c_gate = HostLinear {
            weight: gate_up[..split].to_vec(),
            bias: None,
        };
        let c_fc = HostLinear {
            weight: gate_up[split..].to_vec(),
            bias: None,
        };
        let c_mlp_proj = HostLinear {
            weight: store.take_expected(&format!("{p}.mlp.down_proj.weight"), &[d, i])?,
            bias: None,
        };
        layers.push(HostTransformerLayer {
            post_attention_norm: None,
            post_mlp_norm: None,
            ln1,
            c_attn: Some(c_attn),
            q_proj: None,
            k_proj: None,
            v_proj: None,
            q_norm: None,
            k_norm: None,
            c_proj,
            ln2,
            c_fc,
            c_gate: Some(c_gate),
            c_mlp_proj,
            xielu: None,
        });
    }
    let final_norm = HostLayerNorm {
        weight: store.take_expected("model.norm.weight", &[d])?,
        bias: Vec::new(),
    };
    let has_lm_head_alias = store.contains("lm_head.weight") && config.tie_word_embeddings;
    let lm_head = if config.tie_word_embeddings {
        if store.contains("lm_head.weight") {
            let alias = store.take_expected("lm_head.weight", &[config.vocab_size, d])?;
            if alias != token_embedding {
                bail!("Phi-3 tied lm_head.weight differs from model.embed_tokens.weight");
            }
        }
        None
    } else {
        Some(store.take_expected("lm_head.weight", &[config.vocab_size, d])?)
    };
    Ok(HostTransformerWeights {
        token_embedding,
        position_embedding: None,
        embedding_norm: None,
        layers,
        final_norm,
        prediction_head: None,
        has_lm_head_alias,
        lm_head,
        lm_head_bias: None,
    })
}

