impl TransformerLayerTape {
    fn new(
        device: &VulkanDevice,
        rows: usize,
        hidden: usize,
        intermediate: usize,
        query_hidden: usize,
        key_hidden: usize,
        value_hidden: usize,
        attention_hidden: usize,
    ) -> Result<Self> {
        let hd = rows
            .checked_mul(hidden)
            .context("Transformer hidden tape overflow")?;
        let q = rows
            .checked_mul(query_hidden)
            .context("Transformer query tape overflow")?;
        let key = rows
            .checked_mul(key_hidden)
            .context("Transformer key tape overflow")?;
        let value = rows
            .checked_mul(value_hidden)
            .context("Transformer value tape overflow")?;
        let attention = rows
            .checked_mul(attention_hidden)
            .context("Transformer attention-output tape overflow")?;
        let qkv = rows
            .checked_mul(
                query_hidden
                    .checked_add(key_hidden)
                    .and_then(|width| width.checked_add(value_hidden))
                    .context("Transformer QKV width overflow")?,
            )
            .context("Transformer QKV tape overflow")?;
        let mlp = rows
            .checked_mul(intermediate)
            .context("Transformer MLP tape overflow")?;
        Ok(Self {
            ln1: GpuBuffer::zeros_f32(device, hd)?,
            ln1_mean: GpuBuffer::zeros_f32(device, rows)?,
            ln1_rstd: GpuBuffer::zeros_f32(device, rows)?,
            qkv: GpuBuffer::zeros_f32(device, qkv)?,
            qkv_clipped: GpuBuffer::zeros_f32(device, qkv)?,
            q_preclip: GpuBuffer::zeros_f32(device, q)?,
            k_preclip: GpuBuffer::zeros_f32(device, key)?,
            v_preclip: GpuBuffer::zeros_f32(device, value)?,
            q: GpuBuffer::zeros_f32(device, q)?,
            k: GpuBuffer::zeros_f32(device, key)?,
            v: GpuBuffer::zeros_f32(device, value)?,
            q_norm: GpuBuffer::zeros_f32(device, q)?,
            k_norm: GpuBuffer::zeros_f32(device, key)?,
            v_norm: GpuBuffer::zeros_f32(device, value)?,
            // Q/K normalization is per attention head. These stats buffers are
            // deliberately over-allocated to the corresponding activation
            // length so every supported head geometry fits without a second
            // tape allocation policy.
            q_norm_mean: GpuBuffer::zeros_f32(device, q)?,
            q_norm_rstd: GpuBuffer::zeros_f32(device, q)?,
            k_norm_mean: GpuBuffer::zeros_f32(device, key)?,
            k_norm_rstd: GpuBuffer::zeros_f32(device, key)?,
            v_norm_mean: GpuBuffer::zeros_f32(device, value)?,
            v_norm_rstd: GpuBuffer::zeros_f32(device, value)?,
            q_rotary: GpuBuffer::zeros_f32(device, q)?,
            k_rotary: GpuBuffer::zeros_f32(device, key)?,
            v_rotary: GpuBuffer::zeros_f32(device, value)?,
            v_rotary_scratch: GpuBuffer::zeros_f32(device, value)?,
            attention: GpuBuffer::zeros_f32(device, attention)?,
            attention_gate_pre: GpuBuffer::zeros_f32(device, attention)?,
            attention_gate_values: GpuBuffer::zeros_f32(device, attention)?,
            attention_gated: GpuBuffer::zeros_f32(device, attention)?,
            attention_projection: GpuBuffer::zeros_f32(device, hd)?,
            attention_projection_dropout: GpuBuffer::zeros_f32(device, hd)?,
            post_attention_norm: GpuBuffer::zeros_f32(device, hd)?,
            post_attention_norm_mean: GpuBuffer::zeros_f32(device, rows)?,
            post_attention_norm_rstd: GpuBuffer::zeros_f32(device, rows)?,
            kimi_attention_input: GpuBuffer::zeros_f32(device, hd)?,
            residual1: GpuBuffer::zeros_f32(device, hd)?,
            kimi_mlp_input: GpuBuffer::zeros_f32(device, hd)?,
            ln2: GpuBuffer::zeros_f32(device, hd)?,
            ln2_mean: GpuBuffer::zeros_f32(device, rows)?,
            ln2_rstd: GpuBuffer::zeros_f32(device, rows)?,
            mlp_pre: GpuBuffer::zeros_f32(device, mlp)?,
            mlp_gate_pre: GpuBuffer::zeros_f32(device, mlp)?,
            mlp_activation: GpuBuffer::zeros_f32(device, mlp)?,
            mlp_product: GpuBuffer::zeros_f32(device, mlp)?,
            mlp_activation_dropout: GpuBuffer::zeros_f32(device, mlp)?,
            mlp_output: GpuBuffer::zeros_f32(device, hd)?,
            mlp_output_dropout: GpuBuffer::zeros_f32(device, hd)?,
            post_mlp_norm: GpuBuffer::zeros_f32(device, hd)?,
            post_mlp_norm_mean: GpuBuffer::zeros_f32(device, rows)?,
            post_mlp_norm_rstd: GpuBuffer::zeros_f32(device, rows)?,
            output: GpuBuffer::zeros_f32(device, hd)?,
            grad_mlp_activation: GpuBuffer::zeros_f32(device, mlp)?,
            grad_mlp_activation_pre_dropout: GpuBuffer::zeros_f32(device, mlp)?,
            grad_mlp_gate_activation: GpuBuffer::zeros_f32(device, mlp)?,
            grad_mlp_gate_pre: GpuBuffer::zeros_f32(device, mlp)?,
            grad_mlp_pre: GpuBuffer::zeros_f32(device, mlp)?,
            grad_ln2_up: GpuBuffer::zeros_f32(device, hd)?,
            grad_ln2_gate: GpuBuffer::zeros_f32(device, hd)?,
            grad_ln2: GpuBuffer::zeros_f32(device, hd)?,
            grad_residual1_mlp: GpuBuffer::zeros_f32(device, hd)?,
            grad_residual1: GpuBuffer::zeros_f32(device, hd)?,
            grad_mlp_residual_branch: GpuBuffer::zeros_f32(device, hd)?,
            grad_post_mlp_norm: GpuBuffer::zeros_f32(device, hd)?,
            grad_mlp_output: GpuBuffer::zeros_f32(device, hd)?,
            grad_attention_residual_branch: GpuBuffer::zeros_f32(device, hd)?,
            grad_post_attention_norm: GpuBuffer::zeros_f32(device, hd)?,
            grad_attention_projection: GpuBuffer::zeros_f32(device, hd)?,
            grad_attention: GpuBuffer::zeros_f32(device, attention)?,
            grad_attention_ungated: GpuBuffer::zeros_f32(device, attention)?,
            grad_attention_gate_values: GpuBuffer::zeros_f32(device, attention)?,
            grad_attention_gate_pre: GpuBuffer::zeros_f32(device, attention)?,
            grad_attention_gate_input: GpuBuffer::zeros_f32(device, hd)?,
            grad_attention_linear_input: GpuBuffer::zeros_f32(device, hd)?,
            grad_kimi_attention_input: GpuBuffer::zeros_f32(device, hd)?,
            grad_kimi_mlp_input: GpuBuffer::zeros_f32(device, hd)?,
            grad_q: GpuBuffer::zeros_f32(device, q)?,
            grad_k: GpuBuffer::zeros_f32(device, key)?,
            grad_v: GpuBuffer::zeros_f32(device, value)?,
            grad_q_preclip: GpuBuffer::zeros_f32(device, q)?,
            grad_k_preclip: GpuBuffer::zeros_f32(device, key)?,
            grad_v_preclip: GpuBuffer::zeros_f32(device, value)?,
            grad_q_norm: GpuBuffer::zeros_f32(device, q)?,
            grad_k_norm: GpuBuffer::zeros_f32(device, key)?,
            grad_v_norm: GpuBuffer::zeros_f32(device, value)?,
            grad_q_rotary: GpuBuffer::zeros_f32(device, q)?,
            grad_k_rotary: GpuBuffer::zeros_f32(device, key)?,
            grad_v_rotary: GpuBuffer::zeros_f32(device, value)?,
            grad_qkv: GpuBuffer::zeros_f32(device, qkv)?,
            grad_qkv_preclip: GpuBuffer::zeros_f32(device, qkv)?,
            grad_ln1_q: GpuBuffer::zeros_f32(device, hd)?,
            grad_ln1_k: GpuBuffer::zeros_f32(device, hd)?,
            grad_ln1_v: GpuBuffer::zeros_f32(device, hd)?,
            grad_ln1_qk: GpuBuffer::zeros_f32(device, hd)?,
            grad_ln1: GpuBuffer::zeros_f32(device, hd)?,
            grad_input_attention: GpuBuffer::zeros_f32(device, hd)?,
            grad_input: GpuBuffer::zeros_f32(device, hd)?,
        })
    }
}

struct CrossAttentionTape {
    normalized_query: GpuBuffer,
    q: GpuBuffer,
    q_scaled: GpuBuffer,
    k: GpuBuffer,
    v: GpuBuffer,
    attention: GpuBuffer,
    projection: GpuBuffer,
    post_projection_norm: GpuBuffer,
    projection_dropout: GpuBuffer,
    residual: GpuBuffer,
    output: GpuBuffer,
    norm_mean: GpuBuffer,
    norm_rstd: GpuBuffer,
    post_norm_mean: GpuBuffer,
    post_norm_rstd: GpuBuffer,
    grad_normalized_query: GpuBuffer,
    grad_output: GpuBuffer,
    grad_post_projection_norm: GpuBuffer,
    grad_projection: GpuBuffer,
    grad_attention: GpuBuffer,
    grad_q: GpuBuffer,
    grad_q_scaled: GpuBuffer,
    grad_k: GpuBuffer,
    grad_v: GpuBuffer,
    grad_query_attention: GpuBuffer,
    grad_query_input: GpuBuffer,
    grad_encoder_k: GpuBuffer,
    grad_encoder_v: GpuBuffer,
    grad_encoder_input: GpuBuffer,
}

impl CrossAttentionTape {
    fn new(
        device: &VulkanDevice,
        query_rows: usize,
        key_value_rows: usize,
        hidden: usize,
        attention_hidden: usize,
        key_value_hidden: usize,
        encoder_hidden: usize,
    ) -> Result<Self> {
        let query_len = query_rows
            .checked_mul(hidden)
            .context("Transformer cross-attention query tape overflow")?;
        let attention_query_len = query_rows
            .checked_mul(attention_hidden)
            .context("Transformer cross-attention projected-query tape overflow")?;
        let key_value_len = key_value_rows
            .checked_mul(key_value_hidden)
            .context("Transformer cross-attention key/value tape overflow")?;
        let encoder_len = key_value_rows
            .checked_mul(encoder_hidden)
            .context("Transformer cross-attention encoder tape overflow")?;
        Ok(Self {
            normalized_query: GpuBuffer::zeros_f32(device, query_len)?,
            q: GpuBuffer::zeros_f32(device, attention_query_len)?,
            q_scaled: GpuBuffer::zeros_f32(device, attention_query_len)?,
            k: GpuBuffer::zeros_f32(device, key_value_len)?,
            v: GpuBuffer::zeros_f32(device, key_value_len)?,
            attention: GpuBuffer::zeros_f32(device, attention_query_len)?,
            projection: GpuBuffer::zeros_f32(device, query_len)?,
            post_projection_norm: GpuBuffer::zeros_f32(device, query_len)?,
            projection_dropout: GpuBuffer::zeros_f32(device, query_len)?,
            residual: GpuBuffer::zeros_f32(device, query_len)?,
            output: GpuBuffer::zeros_f32(device, query_len)?,
            norm_mean: GpuBuffer::zeros_f32(device, query_rows)?,
            norm_rstd: GpuBuffer::zeros_f32(device, query_rows)?,
            post_norm_mean: GpuBuffer::zeros_f32(device, query_rows)?,
            post_norm_rstd: GpuBuffer::zeros_f32(device, query_rows)?,
            grad_normalized_query: GpuBuffer::zeros_f32(device, query_len)?,
            grad_output: GpuBuffer::zeros_f32(device, query_len)?,
            grad_post_projection_norm: GpuBuffer::zeros_f32(device, query_len)?,
            grad_projection: GpuBuffer::zeros_f32(device, query_len)?,
            grad_attention: GpuBuffer::zeros_f32(device, attention_query_len)?,
            grad_q: GpuBuffer::zeros_f32(device, attention_query_len)?,
            grad_q_scaled: GpuBuffer::zeros_f32(device, attention_query_len)?,
            grad_k: GpuBuffer::zeros_f32(device, key_value_len)?,
            grad_v: GpuBuffer::zeros_f32(device, key_value_len)?,
            grad_query_attention: GpuBuffer::zeros_f32(device, query_len)?,
            grad_query_input: GpuBuffer::zeros_f32(device, query_len)?,
            grad_encoder_k: GpuBuffer::zeros_f32(device, encoder_len)?,
            grad_encoder_v: GpuBuffer::zeros_f32(device, encoder_len)?,
            grad_encoder_input: GpuBuffer::zeros_f32(device, encoder_len)?,
        })
    }
}

struct VulkanCrossAttention {
    layer_index: u32,
    hidden_size: usize,
    num_heads: usize,
    num_key_value_heads: usize,
    head_dim: usize,
    encoder_hidden_size: usize,
    attention_dropout: f32,
    output_dropout: f32,
    query_scale: f32,
    attention_scale: f32,
    attention_softcap: f32,
    pre_norm: bool,
    q_proj: VulkanLinear,
    k_proj: VulkanLinear,
    v_proj: VulkanLinear,
    out_proj: VulkanLinear,
    norm: VulkanLayerNorm,
    post_norm: Option<VulkanLayerNorm>,
    sink: GpuBuffer,
    grad_sink: GpuBuffer,
    tape: CrossAttentionTape,
}

impl VulkanCrossAttention {
    fn new(
        device: &VulkanDevice,
        hidden: usize,
        num_heads: usize,
        num_key_value_heads: usize,
        head_dim: usize,
        layer_norm_eps: f32,
        rms_norm: bool,
        rms_norm_weight_offset: f32,
        attention_dropout: f32,
        output_dropout: f32,
        query_scale: f32,
        attention_scale: f32,
        attention_softcap: f32,
        pre_norm: bool,
        query_rows: usize,
        key_value_rows: usize,
        layer_index: usize,
        host: HostCrossAttention,
    ) -> Result<Self> {
        if num_heads == 0 || num_key_value_heads == 0 || head_dim == 0 {
            bail!("Transformer cross-attention head counts/head_dim must be positive");
        }
        if !num_heads.is_multiple_of(num_key_value_heads) {
            bail!(
                "Transformer cross-attention num_heads={num_heads} must be divisible by num_key_value_heads={num_key_value_heads}"
            );
        }
        let attention_hidden = num_heads
            .checked_mul(head_dim)
            .context("Transformer cross-attention projection width overflow")?;
        let key_value_hidden = num_key_value_heads
            .checked_mul(head_dim)
            .context("Transformer cross-attention K/V projection width overflow")?;
        let encoder_hidden_size = host.encoder_hidden_size(key_value_hidden)?;
        let make_linear = |input_dim: usize,
                           output_dim: usize,
                           host: HostLinear|
         -> Result<VulkanLinear> {
            match host.bias {
                Some(bias) => VulkanLinear::new(device, input_dim, output_dim, &host.weight, &bias),
                None => VulkanLinear::new_no_bias(device, input_dim, output_dim, &host.weight),
            }
        };
        let norm = if rms_norm {
            VulkanLayerNorm::new_rms(
                device,
                hidden,
                layer_norm_eps,
                &host.norm.weight,
                rms_norm_weight_offset,
            )?
        } else if host.norm.bias.is_empty() {
            VulkanLayerNorm::new_no_bias(device, hidden, layer_norm_eps, &host.norm.weight)?
        } else {
            VulkanLayerNorm::new(
                device,
                hidden,
                layer_norm_eps,
                &host.norm.weight,
                &host.norm.bias,
            )?
        };
        let post_norm = host
            .post_norm
            .map(|host| {
                if rms_norm {
                    VulkanLayerNorm::new_rms(
                        device,
                        hidden,
                        layer_norm_eps,
                        &host.weight,
                        rms_norm_weight_offset,
                    )
                } else if host.bias.is_empty() {
                    VulkanLayerNorm::new_no_bias(device, hidden, layer_norm_eps, &host.weight)
                } else {
                    VulkanLayerNorm::new(device, hidden, layer_norm_eps, &host.weight, &host.bias)
                }
            })
            .transpose()?;
        Ok(Self {
            layer_index: layer_index as u32,
            hidden_size: hidden,
            num_heads,
            num_key_value_heads,
            head_dim,
            encoder_hidden_size,
            attention_dropout,
            output_dropout,
            query_scale,
            attention_scale,
            attention_softcap,
            pre_norm,
            q_proj: make_linear(hidden, attention_hidden, host.q_proj)?,
            k_proj: make_linear(encoder_hidden_size, key_value_hidden, host.k_proj)?,
            v_proj: make_linear(encoder_hidden_size, key_value_hidden, host.v_proj)?,
            out_proj: make_linear(attention_hidden, hidden, host.out_proj)?,
            norm,
            post_norm,
            sink: GpuBuffer::zeros_f32(device, num_heads)?,
            grad_sink: GpuBuffer::zeros_f32(device, num_heads)?,
            tape: CrossAttentionTape::new(
                device,
                query_rows,
                key_value_rows,
                hidden,
                attention_hidden,
                key_value_hidden,
                encoder_hidden_size,
            )?,
        })
    }

    fn replicate_shared_base(
        &self,
        device: &VulkanDevice,
        query_rows: usize,
        key_value_rows: usize,
        layer_index: usize,
    ) -> Result<Self> {
        let attention_hidden = self
            .num_heads
            .checked_mul(self.head_dim)
            .context("replicated cross-attention width overflow")?;
        let key_value_hidden = self
            .num_key_value_heads
            .checked_mul(self.head_dim)
            .context("replicated cross-attention K/V width overflow")?;
        Ok(Self {
            layer_index: layer_index as u32,
            hidden_size: self.hidden_size,
            num_heads: self.num_heads,
            num_key_value_heads: self.num_key_value_heads,
            head_dim: self.head_dim,
            encoder_hidden_size: self.encoder_hidden_size,
            attention_dropout: self.attention_dropout,
            output_dropout: self.output_dropout,
            query_scale: self.query_scale,
            attention_scale: self.attention_scale,
            attention_softcap: self.attention_softcap,
            pre_norm: self.pre_norm,
            q_proj: self.q_proj.replicate_shared_base()?,
            k_proj: self.k_proj.replicate_shared_base()?,
            v_proj: self.v_proj.replicate_shared_base()?,
            out_proj: self.out_proj.replicate_shared_base()?,
            norm: self.norm.replicate_shared_base(),
            post_norm: self
                .post_norm
                .as_ref()
                .map(VulkanLayerNorm::replicate_shared_base),
            // Cross-attention currently binds inert sink buffers. Give every
            // replica its own scratch identity just like PEFT's cloned module.
            sink: GpuBuffer::zeros_f32(device, self.num_heads)?,
            grad_sink: GpuBuffer::zeros_f32(device, self.num_heads)?,
            tape: CrossAttentionTape::new(
                device,
                query_rows,
                key_value_rows,
                self.hidden_size,
                attention_hidden,
                key_value_hidden,
                self.encoder_hidden_size,
            )?,
        })
    }

    fn freeze_base_parameters(&mut self) {
        self.q_proj.freeze_base();
        self.k_proj.freeze_base();
        self.v_proj.freeze_base();
        self.out_proj.freeze_base();
        self.norm.freeze();
        if let Some(norm) = self.post_norm.as_mut() {
            norm.freeze();
        }
    }

    fn enable_bias_training(&mut self) {
        self.q_proj.enable_bias_training();
        self.k_proj.enable_bias_training();
        self.v_proj.enable_bias_training();
        self.out_proj.enable_bias_training();
        self.norm.enable_bias_training();
        if let Some(norm) = self.post_norm.as_mut() {
            norm.enable_bias_training();
        }
    }

    fn record_forward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        query_input: &GpuBuffer,
        encoder_hidden: &GpuBuffer,
        query_mask: &GpuBuffer,
        encoder_mask: &GpuBuffer,
        alibi_scratch: &GpuBuffer,
        batch_size: usize,
        query_seq_len: usize,
        key_value_seq_len: usize,
        rng_step: u32,
        rng_seed: u32,
        training: bool,
    ) -> Result<()> {
        let query_rows = batch_size * query_seq_len;
        let key_value_rows = batch_size * key_value_seq_len;
        let hidden = self.hidden_size;
        let attention_hidden = self.num_heads * self.head_dim;
        let attention_query = if self.pre_norm {
            self.norm.record_forward(
                commands,
                kernels,
                query_input,
                &self.tape.normalized_query,
                &self.tape.norm_mean,
                &self.tape.norm_rstd,
                query_rows,
            )?;
            &self.tape.normalized_query
        } else {
            query_input
        };
        record_transformer_linear_forward(
            &self.q_proj,
            commands,
            kernels,
            attention_query,
            &self.tape.q,
            query_rows,
            training,
            rng_step,
            rng_seed,
        )?;
        let q = if self.query_scale != 1.0 {
            let push = ScalePush {
                len: (query_rows * attention_hidden) as u32,
                scale: self.query_scale,
            };
            kernels.scale_copy.record_dispatch(
                commands,
                &[&self.tape.q, &self.tape.q_scaled],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(query_rows * attention_hidden, 256), 1, 1],
            )?;
            &self.tape.q_scaled
        } else {
            &self.tape.q
        };
        record_transformer_linear_forward(
            &self.k_proj,
            commands,
            kernels,
            encoder_hidden,
            &self.tape.k,
            key_value_rows,
            training,
            rng_step,
            rng_seed,
        )?;
        record_transformer_linear_forward(
            &self.v_proj,
            commands,
            kernels,
            encoder_hidden,
            &self.tape.v,
            key_value_rows,
            training,
            rng_step,
            rng_seed,
        )?;
        let push = AttentionPush {
            batch_size: batch_size as u32,
            query_seq_len: query_seq_len as u32,
            key_value_seq_len: key_value_seq_len as u32,
            query_hidden_size: attention_hidden as u32,
            value_hidden_size: attention_hidden as u32,
            num_heads: self.num_heads as u32,
            num_key_value_heads: self.num_key_value_heads as u32,
            window_size: 0,
            scale: self.attention_scale,
            value_scale: 1.0,
            softcap: self.attention_softcap,
            alibi_mode: 0,
            alibi_bias_max: 0.0,
            dropout_p: self.attention_dropout,
            rng_step,
            rng_site: TRANSFORMER_CROSS_ATTENTION_PROB_DROPOUT_SITE.wrapping_add(self.layer_index),
            rng_seed,
            has_sink: 0,
            causal: 0,
            relative_bias_mode: 0,
            relative_bias_num_buckets: 0,
            relative_bias_max_distance: 0,
            query_position_offset: 0,
            has_sparse_mask: 0,
            compressed_key_count: 0,
            compressed_key_rate: 0,
            paged_kv: 0,
            kv_page_size: 1,
            kv_page_table_stride: 1,
        };
        kernels.attention_forward.record_dispatch(
            commands,
            &[
                q,
                &self.tape.k,
                &self.tape.v,
                query_mask,
                encoder_mask,
                alibi_scratch,
                &self.tape.attention,
                &self.sink,
                &self.sink,
                query_mask,
                query_mask,
            ],
            bytemuck::bytes_of(&push),
            [
                query_seq_len as u32,
                self.num_heads as u32,
                batch_size as u32,
            ],
        )?;
        record_transformer_linear_forward(
            &self.out_proj,
            commands,
            kernels,
            &self.tape.attention,
            &self.tape.projection,
            query_rows,
            training,
            rng_step,
            rng_seed,
        )?;
        let projection = if let Some(post_norm) = self.post_norm.as_ref() {
            post_norm.record_forward(
                commands,
                kernels,
                &self.tape.projection,
                &self.tape.post_projection_norm,
                &self.tape.post_norm_mean,
                &self.tape.post_norm_rstd,
                query_rows,
            )?;
            &self.tape.post_projection_norm
        } else {
            &self.tape.projection
        };
        let projection = if self.output_dropout > 0.0 {
            record_transformer_dropout(
                commands,
                kernels,
                projection,
                &self.tape.projection_dropout,
                self.output_dropout,
                rng_step,
                TRANSFORMER_CROSS_ATTENTION_OUTPUT_DROPOUT_SITE.wrapping_add(self.layer_index),
                rng_seed,
                query_rows * hidden,
            )?;
            &self.tape.projection_dropout
        } else {
            &self.tape.projection
        };
        record_add(
            commands,
            kernels,
            query_input,
            projection,
            &self.tape.residual,
            query_rows * hidden,
        )?;
        if self.pre_norm {
            commands.copy_f32(&self.tape.residual, &self.tape.output, query_rows * hidden)
        } else {
            self.norm.record_forward(
                commands,
                kernels,
                &self.tape.residual,
                &self.tape.output,
                &self.tape.norm_mean,
                &self.tape.norm_rstd,
                query_rows,
            )
        }
    }

    fn record_backward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        query_input: &GpuBuffer,
        encoder_hidden: &GpuBuffer,
        query_mask: &GpuBuffer,
        encoder_mask: &GpuBuffer,
        alibi_scratch: &GpuBuffer,
        grad_output: &GpuBuffer,
        batch_size: usize,
        query_seq_len: usize,
        key_value_seq_len: usize,
        rng_step: u32,
        rng_seed: u32,
    ) -> Result<()> {
        let query_rows = batch_size * query_seq_len;
        let key_value_rows = batch_size * key_value_seq_len;
        let hidden = self.hidden_size;
        let attention_hidden = self.num_heads * self.head_dim;
        let grad_residual = if self.pre_norm {
            grad_output
        } else {
            self.norm.record_backward(
                commands,
                kernels,
                &self.tape.residual,
                grad_output,
                &self.tape.norm_mean,
                &self.tape.norm_rstd,
                &self.tape.grad_output,
                query_rows,
            )?;
            &self.tape.grad_output
        };
        let grad_post_projection = if self.output_dropout > 0.0 {
            record_transformer_dropout(
                commands,
                kernels,
                grad_residual,
                &self.tape.grad_post_projection_norm,
                self.output_dropout,
                rng_step,
                TRANSFORMER_CROSS_ATTENTION_OUTPUT_DROPOUT_SITE.wrapping_add(self.layer_index),
                rng_seed,
                query_rows * hidden,
            )?;
            &self.tape.grad_post_projection_norm
        } else {
            grad_residual
        };
        let grad_projection = if let Some(post_norm) = self.post_norm.as_ref() {
            post_norm.record_backward(
                commands,
                kernels,
                &self.tape.projection,
                grad_post_projection,
                &self.tape.post_norm_mean,
                &self.tape.post_norm_rstd,
                &self.tape.grad_projection,
                query_rows,
            )?;
            &self.tape.grad_projection
        } else {
            grad_post_projection
        };
        self.out_proj.record_backward(
            commands,
            kernels,
            &self.tape.attention,
            grad_projection,
            &self.tape.grad_attention,
            query_rows,
        )?;
        let push = AttentionPush {
            batch_size: batch_size as u32,
            query_seq_len: query_seq_len as u32,
            key_value_seq_len: key_value_seq_len as u32,
            query_hidden_size: attention_hidden as u32,
            value_hidden_size: attention_hidden as u32,
            num_heads: self.num_heads as u32,
            num_key_value_heads: self.num_key_value_heads as u32,
            window_size: 0,
            scale: self.attention_scale,
            value_scale: 1.0,
            softcap: self.attention_softcap,
            alibi_mode: 0,
            alibi_bias_max: 0.0,
            dropout_p: self.attention_dropout,
            rng_step,
            rng_site: TRANSFORMER_CROSS_ATTENTION_PROB_DROPOUT_SITE.wrapping_add(self.layer_index),
            rng_seed,
            has_sink: 0,
            causal: 0,
            relative_bias_mode: 0,
            relative_bias_num_buckets: 0,
            relative_bias_max_distance: 0,
            query_position_offset: 0,
            has_sparse_mask: 0,
            compressed_key_count: 0,
            compressed_key_rate: 0,
            paged_kv: 0,
            kv_page_size: 1,
            kv_page_table_stride: 1,
        };
        kernels.attention_backward.record_dispatch(
            commands,
            &[
                if self.query_scale != 1.0 {
                    &self.tape.q_scaled
                } else {
                    &self.tape.q
                },
                &self.tape.k,
                &self.tape.v,
                query_mask,
                encoder_mask,
                alibi_scratch,
                &self.tape.grad_attention,
                if self.query_scale != 1.0 {
                    &self.tape.grad_q_scaled
                } else {
                    &self.tape.grad_q
                },
                &self.tape.grad_k,
                &self.tape.grad_v,
                &self.sink,
                &self.grad_sink,
                &self.sink,
                &self.grad_sink,
                query_mask,
            ],
            bytemuck::bytes_of(&push),
            [self.num_heads as u32, batch_size as u32, 1],
        )?;
        let attention_query = if self.pre_norm {
            &self.tape.normalized_query
        } else {
            query_input
        };
        let grad_attention_query = if self.pre_norm {
            &self.tape.grad_normalized_query
        } else {
            &self.tape.grad_query_attention
        };
        let grad_q = if self.query_scale != 1.0 {
            let push = ScalePush {
                len: (query_rows * attention_hidden) as u32,
                scale: self.query_scale,
            };
            kernels.scale_copy.record_dispatch(
                commands,
                &[&self.tape.grad_q_scaled, &self.tape.grad_q],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(query_rows * attention_hidden, 256), 1, 1],
            )?;
            &self.tape.grad_q
        } else {
            &self.tape.grad_q
        };
        self.q_proj.record_backward(
            commands,
            kernels,
            attention_query,
            grad_q,
            grad_attention_query,
            query_rows,
        )?;
        self.k_proj.record_backward(
            commands,
            kernels,
            encoder_hidden,
            &self.tape.grad_k,
            &self.tape.grad_encoder_k,
            key_value_rows,
        )?;
        self.v_proj.record_backward(
            commands,
            kernels,
            encoder_hidden,
            &self.tape.grad_v,
            &self.tape.grad_encoder_v,
            key_value_rows,
        )?;
        if self.pre_norm {
            self.norm.record_backward(
                commands,
                kernels,
                query_input,
                &self.tape.grad_normalized_query,
                &self.tape.norm_mean,
                &self.tape.norm_rstd,
                &self.tape.grad_query_attention,
                query_rows,
            )?;
        }
        record_add(
            commands,
            kernels,
            grad_residual,
            &self.tape.grad_query_attention,
            &self.tape.grad_query_input,
            query_rows * hidden,
        )?;
        record_add(
            commands,
            kernels,
            &self.tape.grad_encoder_k,
            &self.tape.grad_encoder_v,
            &self.tape.grad_encoder_input,
            key_value_rows * self.encoder_hidden_size,
        )
    }

    fn record_step(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        step: u32,
        hyper: AdamWHyperParams,
    ) -> Result<()> {
        self.q_proj.record_step(commands, kernels, step, hyper)?;
        self.k_proj.record_step(commands, kernels, step, hyper)?;
        self.v_proj.record_step(commands, kernels, step, hyper)?;
        self.out_proj.record_step(commands, kernels, step, hyper)?;
        self.norm.record_step(commands, kernels, step, hyper)?;
        if let Some(norm) = self.post_norm.as_ref() {
            norm.record_step(commands, kernels, step, hyper)?;
        }
        Ok(())
    }
}

struct VulkanMoeExpert {
    gate: Option<VulkanLinear>,
    up: VulkanLinear,
    down: VulkanLinear,
}

struct VulkanKimiAttnRes {
    norm: VulkanLayerNorm,
    proj: VulkanLinear,
    hidden: usize,
}

struct VulkanKimiAttnResLayer {
    self_attention: VulkanKimiAttnRes,
    mlp: VulkanKimiAttnRes,
}

/// Model-level Kimi K3 residual stream state.
///
/// Moonshot's AttnRes topology is not a local two-branch residual: selected
/// decoder boundaries archive the *pre-attention* prefix, and every later
/// mixer can attend over all archived prefixes plus the current prefix.  Keep
/// those anchors at graph scope so the ordinary Transformer layer tape remains
/// unchanged for every non-Kimi architecture.
struct VulkanKimiAttnResStack {
    block_size: usize,
    layers: Vec<VulkanKimiAttnResLayer>,
    output: VulkanKimiAttnRes,
    workspace: VulkanKimiAttnResWorkspace,
    block_residuals: Vec<GpuBuffer>,
    grad_block_residuals: Vec<GpuBuffer>,
    output_hidden: GpuBuffer,
    grad_output_prefix: GpuBuffer,
}

/// Scratch storage shared by all Kimi AttnRes parameter sets in one graph.
///
/// Production K3 has an AttnRes pair on every decoder layer, but the operator
/// is executed serially. Keeping these tensors on the parameter object would
/// multiply an O(rows * sources * hidden) tape by the layer count. A single
/// graph-owned workspace is sufficient because backward deterministically
/// recomputes the operator's forward intermediates before consuming them.
struct VulkanKimiAttnResWorkspace {
    max_rows: usize,
    max_sources: usize,
    hidden: usize,
    candidates: GpuBuffer,
    grad_candidates: GpuBuffer,
    normalized: GpuBuffer,
    norm_mean: GpuBuffer,
    norm_rstd: GpuBuffer,
    scores: GpuBuffer,
    probabilities: GpuBuffer,
    grad_probabilities: GpuBuffer,
    grad_scores: GpuBuffer,
    grad_normalized: GpuBuffer,
    grad_candidates_score: GpuBuffer,
    grad_candidates_direct: GpuBuffer,
    recompute_output: GpuBuffer,
    source_grad_scratch: GpuBuffer,
}

struct VulkanMoe {
    router: VulkanLinear,
    router_correction_bias: GpuBuffer,
    hash_router_tid2eid: Option<GpuBuffer>,
    hash_router_vocab_size: usize,
    owned_expert0: Option<VulkanMoeExpert>,
    identity_expert_start: usize,
    experts: Vec<VulkanMoeExpert>,
    shared_expert: Option<VulkanMoeExpert>,
    shared_expert_gate: Option<VulkanLinear>,
    latent_down_proj: Option<VulkanLinear>,
    latent_norm: Option<VulkanLayerNorm>,
    latent_up_proj: Option<VulkanLinear>,
    routed_hidden: usize,
    situ_beta: f32,
    situ_linear_beta: Option<f32>,
    shared_intermediate: usize,
    shared_expert_combination_scale: f32,
    num_experts: usize,
    top_k: usize,
    normalize_top_k: bool,
    router_score_function: VulkanMoeRouterScoreFunction,
    router_logit_softcapping: f32,
    routed_scaling_factor: f32,
    router_group_count: usize,
    router_topk_group: usize,
    expert_capacity: usize,
    router_jitter_noise: f32,
    jittered_input: Option<GpuBuffer>,
    routing_logits: GpuBuffer,
    routing_weights: GpuBuffer,
    grad_routing_weights: GpuBuffer,
    grad_router_logits: GpuBuffer,
    grad_router_input: GpuBuffer,
    shared_gate_logits: GpuBuffer,
    shared_gate_values: GpuBuffer,
    grad_shared_gate_values: GpuBuffer,
    grad_shared_gate_logits: GpuBuffer,
    gate_pre: GpuBuffer,
    up_pre: GpuBuffer,
    activation: GpuBuffer,
    product: GpuBuffer,
    expert_output: GpuBuffer,
    grad_expert_output: GpuBuffer,
    grad_product: GpuBuffer,
    grad_gate_activation: GpuBuffer,
    grad_gate_pre: GpuBuffer,
    grad_up_pre: GpuBuffer,
    grad_input_gate: GpuBuffer,
    grad_input_up: GpuBuffer,
    grad_expert_input: GpuBuffer,
    scaled_grad_output: GpuBuffer,
    grad_sum_a: GpuBuffer,
    grad_sum_b: GpuBuffer,
    latent_input: Option<GpuBuffer>,
    latent_output: Option<GpuBuffer>,
    latent_norm_output: Option<GpuBuffer>,
    latent_norm_mean: Option<GpuBuffer>,
    latent_norm_rstd: Option<GpuBuffer>,
    grad_latent_after_norm: Option<GpuBuffer>,
    grad_latent_output: Option<GpuBuffer>,
    grad_latent_hidden: Option<GpuBuffer>,
}

impl VulkanKimiAttnRes {
    fn new(
        device: &VulkanDevice,
        hidden: usize,
        norm_eps: f32,
        host: HostKimiAttnRes,
    ) -> Result<Self> {
        if hidden == 0 {
            bail!("Kimi AttnRes requires a positive hidden size");
        }
        if !host.norm.bias.is_empty() {
            bail!("Kimi AttnRes norm must be RMSNorm without bias");
        }
        if host.proj.bias.is_some() || host.proj.weight.len() != hidden {
            bail!("Kimi AttnRes score projection geometry mismatch");
        }
        Ok(Self {
            norm: VulkanLayerNorm::new_rms(device, hidden, norm_eps, &host.norm.weight, 0.0)?,
            proj: VulkanLinear::new_no_bias(device, hidden, 1, &host.proj.weight)?,
            hidden,
        })
    }

    fn record_forward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        workspace: &VulkanKimiAttnResWorkspace,
        candidates: &GpuBuffer,
        output: &GpuBuffer,
        rows: usize,
        sources: usize,
    ) -> Result<()> {
        workspace.validate_shape(rows, sources, self.hidden)?;
        let items = rows * sources;
        self.norm.record_forward(
            commands,
            kernels,
            candidates,
            &workspace.normalized,
            &workspace.norm_mean,
            &workspace.norm_rstd,
            items,
        )?;
        self.proj.record_forward(
            commands,
            kernels,
            &workspace.normalized,
            &workspace.scores,
            items,
        )?;
        let push = KimiAttnResPush {
            rows: rows as u32,
            sources: sources as u32,
            dim: self.hidden as u32,
        };
        kernels.kimi_attn_res_softmax.record_dispatch(
            commands,
            &[&workspace.scores, &workspace.probabilities],
            bytemuck::bytes_of(&push),
            [div_ceil_u32(rows, 64), 1, 1],
        )?;
        kernels.kimi_attn_res_mix.record_dispatch(
            commands,
            &[candidates, &workspace.probabilities, output],
            bytemuck::bytes_of(&push),
            [div_ceil_u32(self.hidden, 16), div_ceil_u32(rows, 16), 1],
        )
    }

    fn record_backward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        workspace: &VulkanKimiAttnResWorkspace,
        candidates: &GpuBuffer,
        grad_output: &GpuBuffer,
        grad_candidates: &GpuBuffer,
        rows: usize,
        sources: usize,
    ) -> Result<()> {
        // The graph shares one workspace across every layer. Recompute the
        // forward statistics/probabilities immediately before reverse-mode so
        // backward never depends on scratch left behind by a later layer.
        self.record_forward(
            commands,
            kernels,
            workspace,
            candidates,
            &workspace.recompute_output,
            rows,
            sources,
        )?;
        let items = rows * sources;
        let values = items * self.hidden;
        let push = KimiAttnResPush {
            rows: rows as u32,
            sources: sources as u32,
            dim: self.hidden as u32,
        };
        kernels.kimi_attn_res_mix_backward_prob.record_dispatch(
            commands,
            &[candidates, grad_output, &workspace.grad_probabilities],
            bytemuck::bytes_of(&push),
            [div_ceil_u32(items, 64), 1, 1],
        )?;
        kernels.kimi_attn_res_softmax_backward.record_dispatch(
            commands,
            &[
                &workspace.probabilities,
                &workspace.grad_probabilities,
                &workspace.grad_scores,
            ],
            bytemuck::bytes_of(&push),
            [div_ceil_u32(rows, 64), 1, 1],
        )?;
        self.proj.record_backward(
            commands,
            kernels,
            &workspace.normalized,
            &workspace.grad_scores,
            &workspace.grad_normalized,
            items,
        )?;
        self.norm.record_backward(
            commands,
            kernels,
            candidates,
            &workspace.grad_normalized,
            &workspace.norm_mean,
            &workspace.norm_rstd,
            &workspace.grad_candidates_score,
            items,
        )?;
        kernels.kimi_attn_res_mix_backward_candidate.record_dispatch(
            commands,
            &[
                &workspace.probabilities,
                grad_output,
                &workspace.grad_candidates_direct,
            ],
            bytemuck::bytes_of(&push),
            [div_ceil_u32(values, 256), 1, 1],
        )?;
        record_add(
            commands,
            kernels,
            &workspace.grad_candidates_score,
            &workspace.grad_candidates_direct,
            grad_candidates,
            values,
        )
    }

    fn record_step(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        step: u32,
        hyper: AdamWHyperParams,
    ) -> Result<()> {
        self.norm.record_step(commands, kernels, step, hyper)?;
        self.proj.record_step(commands, kernels, step, hyper)
    }
}

impl VulkanKimiAttnResWorkspace {
    fn new(device: &VulkanDevice, rows: usize, max_sources: usize, hidden: usize) -> Result<Self> {
        if rows == 0 || max_sources == 0 || hidden == 0 {
            bail!("Kimi AttnRes workspace requires positive rows, sources, and hidden size");
        }
        let items = rows
            .checked_mul(max_sources)
            .context("Kimi AttnRes item overflow")?;
        let values = items
            .checked_mul(hidden)
            .context("Kimi AttnRes tape overflow")?;
        Ok(Self {
            max_rows: rows,
            max_sources,
            hidden,
            candidates: GpuBuffer::zeros_f32(device, values)?,
            grad_candidates: GpuBuffer::zeros_f32(device, values)?,
            normalized: GpuBuffer::zeros_f32(device, values)?,
            norm_mean: GpuBuffer::zeros_f32(device, items)?,
            norm_rstd: GpuBuffer::zeros_f32(device, items)?,
            scores: GpuBuffer::zeros_f32(device, items)?,
            probabilities: GpuBuffer::zeros_f32(device, items)?,
            grad_probabilities: GpuBuffer::zeros_f32(device, items)?,
            grad_scores: GpuBuffer::zeros_f32(device, items)?,
            grad_normalized: GpuBuffer::zeros_f32(device, values)?,
            grad_candidates_score: GpuBuffer::zeros_f32(device, values)?,
            grad_candidates_direct: GpuBuffer::zeros_f32(device, values)?,
            recompute_output: GpuBuffer::zeros_f32(device, rows * hidden)?,
            source_grad_scratch: GpuBuffer::zeros_f32(device, rows * hidden)?,
        })
    }

    fn validate_shape(&self, rows: usize, sources: usize, hidden: usize) -> Result<()> {
        if rows == 0
            || rows > self.max_rows
            || sources == 0
            || sources > self.max_sources
            || hidden != self.hidden
        {
            bail!("Kimi AttnRes shape exceeds allocated capacity");
        }
        Ok(())
    }

    fn record_pack_candidates(
        &self,
        commands: &mut vulkan::ComputeBatch,
        sources: &[&GpuBuffer],
        current: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<usize> {
        let source_count = sources
            .len()
            .checked_add(1)
            .context("Kimi AttnRes source-count overflow")?;
        self.validate_shape(rows, source_count, hidden)?;
        let len = rows
            .checked_mul(hidden)
            .context("Kimi AttnRes source size overflow")?;
        for (source_index, source) in sources.iter().enumerate() {
            commands.copy_f32_range(source, 0, &self.candidates, source_index * len, len)?;
        }
        commands.copy_f32_range(current, 0, &self.candidates, sources.len() * len, len)?;
        Ok(source_count)
    }

    fn record_accumulate_source_gradient(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        source_index: usize,
        destination: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<()> {
        self.validate_shape(rows, source_index + 1, hidden)?;
        let len = rows
            .checked_mul(hidden)
            .context("Kimi AttnRes gradient source size overflow")?;
        commands.copy_f32_range(
            &self.grad_candidates,
            source_index * len,
            &self.source_grad_scratch,
            0,
            len,
        )?;
        record_add(
            commands,
            kernels,
            destination,
            &self.source_grad_scratch,
            destination,
            len,
        )
    }

    fn record_copy_current_gradient(
        &self,
        commands: &mut vulkan::ComputeBatch,
        source_count: usize,
        destination: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<()> {
        self.validate_shape(rows, source_count, hidden)?;
        let len = rows
            .checked_mul(hidden)
            .context("Kimi AttnRes current-gradient size overflow")?;
        commands.copy_f32_range(
            &self.grad_candidates,
            (source_count - 1) * len,
            destination,
            0,
            len,
        )
    }
}

impl VulkanKimiAttnResStack {
    fn new(
        device: &VulkanDevice,
        rows: usize,
        hidden: usize,
        norm_eps: f32,
        host: HostKimiAttnResStack,
    ) -> Result<Self> {
        if host.block_size == 0 {
            bail!("Kimi AttnRes block size must be positive");
        }
        if host.layers.is_empty() {
            bail!("Kimi AttnRes stack requires at least one decoder layer");
        }
        let boundary_count = host.layers.len().div_ceil(host.block_size);
        let max_sources = boundary_count
            .checked_add(1)
            .context("Kimi AttnRes source-count overflow")?;
        let hidden_len = rows
            .checked_mul(hidden)
            .context("Kimi AttnRes hidden-buffer overflow")?;
        let mut layers = Vec::with_capacity(host.layers.len());
        for layer in host.layers {
            layers.push(VulkanKimiAttnResLayer {
                self_attention: VulkanKimiAttnRes::new(
                    device,
                    hidden,
                    norm_eps,
                    layer.self_attention,
                )?,
                mlp: VulkanKimiAttnRes::new(device, hidden, norm_eps, layer.mlp)?,
            });
        }
        let output = VulkanKimiAttnRes::new(device, hidden, norm_eps, host.output)?;
        let mut block_residuals = Vec::with_capacity(boundary_count);
        let mut grad_block_residuals = Vec::with_capacity(boundary_count);
        for _ in 0..boundary_count {
            block_residuals.push(GpuBuffer::zeros_f32(device, hidden_len)?);
            grad_block_residuals.push(GpuBuffer::zeros_f32(device, hidden_len)?);
        }
        Ok(Self {
            block_size: host.block_size,
            layers,
            output,
            workspace: VulkanKimiAttnResWorkspace::new(device, rows, max_sources, hidden)?,
            block_residuals,
            grad_block_residuals,
            output_hidden: GpuBuffer::zeros_f32(device, hidden_len)?,
            grad_output_prefix: GpuBuffer::zeros_f32(device, hidden_len)?,
        })
    }

    fn boundary_source_index(&self, layer_index: usize) -> Option<usize> {
        layer_index
            .is_multiple_of(self.block_size)
            .then_some(layer_index / self.block_size)
    }

    fn archived_before_count(&self, layer_index: usize) -> Result<usize> {
        if layer_index >= self.layers.len() {
            bail!("Kimi AttnRes layer index {layer_index} is outside the residual stack");
        }
        Ok(layer_index.div_ceil(self.block_size))
    }

    fn archived_after_count(&self, layer_index: usize) -> Result<usize> {
        let before = self.archived_before_count(layer_index)?;
        Ok(before + usize::from(self.boundary_source_index(layer_index).is_some()))
    }

    fn source_refs(&self, count: usize) -> Result<Vec<&GpuBuffer>> {
        if count > self.block_residuals.len() {
            bail!("Kimi AttnRes requested {count} archived sources beyond graph capacity");
        }
        Ok(self.block_residuals[..count].iter().collect())
    }

    /// Prepare the hidden state consumed by the layer's input RMSNorm and, at
    /// a block boundary, archive the original prefix for all later mixers.
    /// Returns true when `mixed_output` contains the attention input.
    fn record_attention_forward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        layer_index: usize,
        input: &GpuBuffer,
        mixed_output: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<bool> {
        let before = self.archived_before_count(layer_index)?;
        if let Some(source_index) = self.boundary_source_index(layer_index) {
            let len = rows
                .checked_mul(hidden)
                .context("Kimi AttnRes boundary size overflow")?;
            commands.copy_f32(input, &self.block_residuals[source_index], len)?;
        }
        if before == 0 {
            return Ok(false);
        }
        let sources = self.source_refs(before)?;
        let source_count = self
            .workspace
            .record_pack_candidates(commands, &sources, input, rows, hidden)?;
        self.layers[layer_index].self_attention.record_forward(
            commands,
            kernels,
            &self.workspace,
            &self.workspace.candidates,
            mixed_output,
            rows,
            source_count,
        )?;
        Ok(true)
    }

    fn record_mlp_forward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        layer_index: usize,
        prefix_sum: &GpuBuffer,
        mixed_output: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<()> {
        let archived = self.archived_after_count(layer_index)?;
        let sources = self.source_refs(archived)?;
        let source_count = self.workspace.record_pack_candidates(
            commands,
            &sources,
            prefix_sum,
            rows,
            hidden,
        )?;
        self.layers[layer_index].mlp.record_forward(
            commands,
            kernels,
            &self.workspace,
            &self.workspace.candidates,
            mixed_output,
            rows,
            source_count,
        )
    }

    fn record_output_forward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        prefix_sum: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<&GpuBuffer> {
        let sources = self.source_refs(self.block_residuals.len())?;
        let source_count = self.workspace.record_pack_candidates(
            commands,
            &sources,
            prefix_sum,
            rows,
            hidden,
        )?;
        self.output.record_forward(
            commands,
            kernels,
            &self.workspace,
            &self.workspace.candidates,
            &self.output_hidden,
            rows,
            source_count,
        )?;
        Ok(&self.output_hidden)
    }

    fn record_begin_backward(&self, commands: &mut vulkan::ComputeBatch, rows: usize, hidden: usize) -> Result<()> {
        let len = rows
            .checked_mul(hidden)
            .context("Kimi AttnRes gradient size overflow")?;
        for grad in &self.grad_block_residuals {
            commands.fill_zero_f32(grad, len)?;
        }
        Ok(())
    }

    fn accumulate_archived_gradients(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        archived: usize,
        rows: usize,
        hidden: usize,
    ) -> Result<()> {
        for source_index in 0..archived {
            self.workspace.record_accumulate_source_gradient(
                commands,
                kernels,
                source_index,
                &self.grad_block_residuals[source_index],
                rows,
                hidden,
            )?;
        }
        Ok(())
    }

    fn record_output_backward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        prefix_sum: &GpuBuffer,
        grad_output: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<&GpuBuffer> {
        self.record_begin_backward(commands, rows, hidden)?;
        let archived = self.block_residuals.len();
        let sources = self.source_refs(archived)?;
        let source_count = self.workspace.record_pack_candidates(
            commands,
            &sources,
            prefix_sum,
            rows,
            hidden,
        )?;
        self.output.record_backward(
            commands,
            kernels,
            &self.workspace,
            &self.workspace.candidates,
            grad_output,
            &self.workspace.grad_candidates,
            rows,
            source_count,
        )?;
        self.accumulate_archived_gradients(commands, kernels, archived, rows, hidden)?;
        self.workspace.record_copy_current_gradient(
            commands,
            source_count,
            &self.grad_output_prefix,
            rows,
            hidden,
        )?;
        Ok(&self.grad_output_prefix)
    }

    fn record_mlp_backward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        layer_index: usize,
        prefix_sum: &GpuBuffer,
        grad_mixed: &GpuBuffer,
        grad_current: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<()> {
        let archived = self.archived_after_count(layer_index)?;
        let sources = self.source_refs(archived)?;
        let source_count = self.workspace.record_pack_candidates(
            commands,
            &sources,
            prefix_sum,
            rows,
            hidden,
        )?;
        self.layers[layer_index].mlp.record_backward(
            commands,
            kernels,
            &self.workspace,
            &self.workspace.candidates,
            grad_mixed,
            &self.workspace.grad_candidates,
            rows,
            source_count,
        )?;
        self.accumulate_archived_gradients(commands, kernels, archived, rows, hidden)?;
        self.workspace.record_copy_current_gradient(
            commands,
            source_count,
            grad_current,
            rows,
            hidden,
        )
    }

    /// Backpropagate the self-attention AttnRes mixer. Returns true when the
    /// supplied destination was populated from a mixer; layer 0 has no prior
    /// archived source and therefore bypasses this operator exactly as HF.
    fn record_attention_backward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        layer_index: usize,
        input: &GpuBuffer,
        grad_mixed: &GpuBuffer,
        grad_current: &GpuBuffer,
        rows: usize,
        hidden: usize,
    ) -> Result<bool> {
        let archived = self.archived_before_count(layer_index)?;
        if archived == 0 {
            return Ok(false);
        }
        let sources = self.source_refs(archived)?;
        let source_count = self.workspace.record_pack_candidates(
            commands,
            &sources,
            input,
            rows,
            hidden,
        )?;
        self.layers[layer_index].self_attention.record_backward(
            commands,
            kernels,
            &self.workspace,
            &self.workspace.candidates,
            grad_mixed,
            &self.workspace.grad_candidates,
            rows,
            source_count,
        )?;
        self.accumulate_archived_gradients(commands, kernels, archived, rows, hidden)?;
        self.workspace.record_copy_current_gradient(
            commands,
            source_count,
            grad_current,
            rows,
            hidden,
        )?;
        Ok(true)
    }

    fn record_step(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        step: u32,
        hyper: AdamWHyperParams,
    ) -> Result<()> {
        for layer in &self.layers {
            layer.self_attention.record_step(commands, kernels, step, hyper)?;
            layer.mlp.record_step(commands, kernels, step, hyper)?;
        }
        self.output.record_step(commands, kernels, step, hyper)
    }
}

impl VulkanMoe {
    fn record_jittered_input<'a>(
        &'a self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        input: &'a GpuBuffer,
        len: usize,
        site: u32,
        step: u32,
        seed: u32,
    ) -> Result<&'a GpuBuffer> {
        let Some(output) = self.jittered_input.as_ref() else {
            return Ok(input);
        };
        self.record_jitter(commands, kernels, input, output, len, site, step, seed)?;
        Ok(output)
    }

    fn record_jitter(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        input: &GpuBuffer,
        output: &GpuBuffer,
        len: usize,
        site: u32,
        step: u32,
        seed: u32,
    ) -> Result<()> {
        let push = UniformJitterPush {
            len: u32::try_from(len).context("MoE jitter input exceeds u32 addressing")?,
            seed,
            // Separate from the activation-dropout site and its expert keys.
            site: site ^ 0x9000_0000,
            step,
            amplitude: self.router_jitter_noise,
        };
        kernels.uniform_jitter.record_dispatch(
            commands,
            &[input, output],
            bytemuck::bytes_of(&push),
            [div_ceil_u32(len, 256), 1, 1],
        )
    }

    fn new(
        device: &VulkanDevice,
        rows: usize,
        hidden: usize,
        intermediate: usize,
        config: &VulkanTransformerMoeConfig,
        norm_eps: f32,
        situ_beta: f32,
        situ_linear_beta: Option<f32>,
        host: HostMoeLayer,
    ) -> Result<Self> {
        let HostMoeLayer {
            router: host_router,
            router_correction_bias: host_router_correction_bias,
            hash_router: host_hash_router,
            expert_capacity,
            owned_expert0: host_owned_expert0,
            identity_expert_start,
            experts: host_experts,
            shared_expert: host_shared_expert,
            shared_expert_gate: host_shared_expert_gate,
            latent: host_latent,
        } = host;
        if identity_expert_start == 0 || identity_expert_start > config.num_experts {
            bail!(
                "routed MoE identity-expert boundary {identity_expert_start} must be in 1..={} ",
                config.num_experts
            );
        }
        if host_experts.len() + 1 != identity_expert_start {
            bail!(
                "routed MoE host table has {} ordinary experts, expected {} before the identity-expert boundary",
                host_experts.len() + 1,
                identity_expert_start
            );
        }
        if host_router_correction_bias.len() != config.num_experts {
            bail!(
                "routed MoE correction-bias table has {} entries, expected {}",
                host_router_correction_bias.len(),
                config.num_experts
            );
        }
        let (hash_router_tid2eid, hash_router_vocab_size) = if let Some(hash) = host_hash_router {
            if hash.top_k != config.top_k {
                bail!(
                    "Hash-MoE routing table has top_k={}, expected configured top_k={}",
                    hash.top_k,
                    config.top_k
                );
            }
            if !config.normalize_top_k {
                bail!("Hash-MoE requires normalized selected routing weights");
            }
            if !matches!(
                config.router_score_function,
                VulkanMoeRouterScoreFunction::Softmax
                    | VulkanMoeRouterScoreFunction::SigmoidGrouped
                    | VulkanMoeRouterScoreFunction::SqrtSoftplus
            ) {
                bail!(
                    "Hash-MoE does not support router score function {:?}",
                    config.router_score_function
                );
            }
            let expected = hash
                .vocab_size
                .checked_mul(hash.top_k)
                .context("Hash-MoE tid2eid size overflow")?;
            if hash.tid2eid.len() != expected {
                bail!(
                    "Hash-MoE tid2eid has {} entries, expected {}x{}={expected}",
                    hash.tid2eid.len(),
                    hash.vocab_size,
                    hash.top_k
                );
            }
            for (token, experts) in hash.tid2eid.chunks_exact(hash.top_k).enumerate() {
                for (slot, &expert) in experts.iter().enumerate() {
                    if expert as usize >= config.num_experts {
                        bail!(
                            "Hash-MoE tid2eid[{token}][{slot}]={expert} is outside 0..{}",
                            config.num_experts
                        );
                    }
                    if experts[..slot].contains(&expert) {
                        bail!("Hash-MoE tid2eid[{token}] contains duplicate expert id {expert}");
                    }
                }
            }
            (
                Some(GpuBuffer::from_u32(device, &hash.tid2eid)?),
                hash.vocab_size,
            )
        } else {
            (None, 0)
        };
        if host_shared_expert_gate.is_some() && host_shared_expert.is_none() {
            bail!("routed MoE shared-expert gate requires shared-expert parameters");
        }
        if config.shared_expert_intermediate_size == 0 && host_shared_expert.is_some() {
            bail!("routed MoE graph unexpectedly contains a shared expert with zero shared width");
        }
        if config.shared_expert_intermediate_size != 0 && host_shared_expert.is_none() {
            bail!("routed MoE graph is missing its configured shared-expert parameters");
        }
        let make = |input_dim: usize, output_dim: usize, linear: HostLinear| match linear.bias {
            Some(bias) => VulkanLinear::new(device, input_dim, output_dim, &linear.weight, &bias),
            None => VulkanLinear::new_no_bias(device, input_dim, output_dim, &linear.weight),
        };
        let router = match host_router.bias {
            Some(bias) => VulkanLinear::new(
                device,
                hidden,
                config.num_experts,
                &host_router.weight,
                &bias,
            )?,
            None => {
                VulkanLinear::new_no_bias(device, hidden, config.num_experts, &host_router.weight)?
            }
        };
        let routed_hidden = host_latent
            .as_ref()
            .map(|latent| latent.hidden_size)
            .unwrap_or(hidden);
        if routed_hidden == 0 {
            bail!("routed MoE latent hidden size must be positive");
        }
        let mut experts = Vec::with_capacity(host_experts.len());
        for expert in host_experts {
            experts.push(VulkanMoeExpert {
                gate: expert
                    .gate
                    .map(|gate| make(routed_hidden, intermediate, gate))
                    .transpose()?,
                up: make(routed_hidden, intermediate, expert.up)?,
                down: make(intermediate, routed_hidden, expert.down)?,
            });
        }
        let owned_expert0 = host_owned_expert0
            .map(|expert| -> Result<VulkanMoeExpert> {
                Ok(VulkanMoeExpert {
                    gate: expert
                        .gate
                        .map(|gate| make(routed_hidden, intermediate, gate))
                        .transpose()?,
                    up: make(routed_hidden, intermediate, expert.up)?,
                    down: make(intermediate, routed_hidden, expert.down)?,
                })
            })
            .transpose()?;
        let shared_intermediate = config.shared_expert_intermediate_size;
        let shared_expert = host_shared_expert
            .map(|expert| -> Result<VulkanMoeExpert> {
                Ok(VulkanMoeExpert {
                    gate: Some(make(
                        hidden,
                        shared_intermediate,
                        expert
                            .gate
                            .context("shared routed-MoE expert is missing its gate projection")?,
                    )?),
                    up: make(hidden, shared_intermediate, expert.up)?,
                    down: make(shared_intermediate, hidden, expert.down)?,
                })
            })
            .transpose()?;
        let shared_expert_gate = host_shared_expert_gate
            .map(|gate| make(hidden, 1, gate))
            .transpose()?;
        let (latent_down_proj, latent_norm, latent_up_proj) = match host_latent {
            Some(latent) => {
                let down = make(hidden, routed_hidden, latent.down_proj)?;
                let norm = latent
                    .norm
                    .map(|norm| {
                        if !norm.bias.is_empty() {
                            bail!("Stable LatentMoE routed_expert_norm must be RMSNorm without bias");
                        }
                        VulkanLayerNorm::new_rms(device, routed_hidden, norm_eps, &norm.weight, 0.0)
                    })
                    .transpose()?;
                let up = make(routed_hidden, hidden, latent.up_proj)?;
                (Some(down), norm, Some(up))
            }
            None => (None, None, None),
        };
        let routing = rows
            .checked_mul(config.num_experts)
            .context("Mixtral routing tape overflow")?;
        let hidden_len = rows
            .checked_mul(hidden)
            .context("Mixtral hidden tape overflow")?;
        let routed_hidden_len = rows
            .checked_mul(routed_hidden)
            .context("routed MoE latent hidden tape overflow")?;
        let hidden_workspace_len = hidden_len.max(routed_hidden_len);
        let has_latent = latent_down_proj.is_some();
        let workspace_intermediate = intermediate.max(shared_intermediate);
        let intermediate_len = rows
            .checked_mul(workspace_intermediate)
            .context("Mixtral expert tape overflow")?;
        Ok(Self {
            router,
            router_correction_bias: GpuBuffer::from_f32(device, &host_router_correction_bias)?,
            hash_router_tid2eid,
            hash_router_vocab_size,
            owned_expert0,
            identity_expert_start,
            experts,
            shared_expert,
            shared_expert_gate,
            latent_down_proj,
            latent_norm,
            latent_up_proj,
            routed_hidden,
            situ_beta,
            situ_linear_beta,
            shared_intermediate,
            shared_expert_combination_scale: config.shared_expert_combination_scale,
            num_experts: config.num_experts,
            top_k: config.top_k,
            normalize_top_k: config.normalize_top_k,
            router_score_function: config.router_score_function,
            router_logit_softcapping: config.router_logit_softcapping,
            routed_scaling_factor: config.routed_scaling_factor,
            router_group_count: config.router_group_count,
            router_topk_group: config.router_topk_group,
            expert_capacity,
            router_jitter_noise: config.router_jitter_noise,
            jittered_input: if config.router_jitter_noise > 0.0 {
                Some(GpuBuffer::zeros_f32(device, hidden_len)?)
            } else {
                None
            },
            routing_logits: GpuBuffer::zeros_f32(device, routing)?,
            routing_weights: GpuBuffer::zeros_f32(device, routing)?,
            grad_routing_weights: GpuBuffer::zeros_f32(device, routing)?,
            grad_router_logits: GpuBuffer::zeros_f32(device, routing)?,
            grad_router_input: GpuBuffer::zeros_f32(device, hidden_len)?,
            shared_gate_logits: GpuBuffer::zeros_f32(device, rows)?,
            shared_gate_values: GpuBuffer::zeros_f32(device, rows)?,
            grad_shared_gate_values: GpuBuffer::zeros_f32(device, rows)?,
            grad_shared_gate_logits: GpuBuffer::zeros_f32(device, rows)?,
            gate_pre: GpuBuffer::zeros_f32(device, intermediate_len)?,
            up_pre: GpuBuffer::zeros_f32(device, intermediate_len)?,
            activation: GpuBuffer::zeros_f32(device, intermediate_len)?,
            product: GpuBuffer::zeros_f32(device, intermediate_len)?,
            expert_output: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_expert_output: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_product: GpuBuffer::zeros_f32(device, intermediate_len)?,
            grad_gate_activation: GpuBuffer::zeros_f32(device, intermediate_len)?,
            grad_gate_pre: GpuBuffer::zeros_f32(device, intermediate_len)?,
            grad_up_pre: GpuBuffer::zeros_f32(device, intermediate_len)?,
            grad_input_gate: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_input_up: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_expert_input: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            scaled_grad_output: GpuBuffer::zeros_f32(device, hidden_len)?,
            grad_sum_a: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_sum_b: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            latent_input: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            latent_output: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            latent_norm_output: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            latent_norm_mean: has_latent
                .then(|| GpuBuffer::zeros_f32(device, rows))
                .transpose()?,
            latent_norm_rstd: has_latent
                .then(|| GpuBuffer::zeros_f32(device, rows))
                .transpose()?,
            grad_latent_after_norm: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            grad_latent_output: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            grad_latent_hidden: has_latent
                .then(|| GpuBuffer::zeros_f32(device, hidden_len))
                .transpose()?,
        })
    }

    fn replicate_shared_base(
        &self,
        device: &VulkanDevice,
        rows: usize,
        hidden: usize,
        intermediate: usize,
    ) -> Result<Self> {
        let clone_expert = |expert: &VulkanMoeExpert| -> Result<VulkanMoeExpert> {
            Ok(VulkanMoeExpert {
                gate: expert
                    .gate
                    .as_ref()
                    .map(VulkanLinear::replicate_shared_base)
                    .transpose()?,
                up: expert.up.replicate_shared_base()?,
                down: expert.down.replicate_shared_base()?,
            })
        };
        let experts = self
            .experts
            .iter()
            .map(clone_expert)
            .collect::<Result<Vec<_>>>()?;
        let owned_expert0 = self.owned_expert0.as_ref().map(clone_expert).transpose()?;
        let shared_expert = self.shared_expert.as_ref().map(clone_expert).transpose()?;
        let shared_expert_gate = self
            .shared_expert_gate
            .as_ref()
            .map(VulkanLinear::replicate_shared_base)
            .transpose()?;
        let latent_down_proj = self
            .latent_down_proj
            .as_ref()
            .map(VulkanLinear::replicate_shared_base)
            .transpose()?;
        let latent_norm = self.latent_norm.as_ref().map(VulkanLayerNorm::replicate_shared_base);
        let latent_up_proj = self
            .latent_up_proj
            .as_ref()
            .map(VulkanLinear::replicate_shared_base)
            .transpose()?;
        let routing = rows
            .checked_mul(self.num_experts)
            .context("replicated MoE routing tape overflow")?;
        let hidden_len = rows
            .checked_mul(hidden)
            .context("replicated MoE hidden tape overflow")?;
        let routed_hidden_len = rows
            .checked_mul(self.routed_hidden)
            .context("replicated routed MoE latent hidden tape overflow")?;
        let hidden_workspace_len = hidden_len.max(routed_hidden_len);
        let has_latent = latent_down_proj.is_some();
        let intermediate_len = rows
            .checked_mul(intermediate.max(self.shared_intermediate))
            .context("replicated MoE expert tape overflow")?;
        Ok(Self {
            router: self.router.replicate_shared_base()?,
            router_correction_bias: self.router_correction_bias.clone(),
            hash_router_tid2eid: self.hash_router_tid2eid.clone(),
            hash_router_vocab_size: self.hash_router_vocab_size,
            owned_expert0,
            identity_expert_start: self.identity_expert_start,
            experts,
            shared_expert,
            shared_expert_gate,
            latent_down_proj,
            latent_norm,
            latent_up_proj,
            routed_hidden: self.routed_hidden,
            situ_beta: self.situ_beta,
            situ_linear_beta: self.situ_linear_beta,
            shared_intermediate: self.shared_intermediate,
            shared_expert_combination_scale: self.shared_expert_combination_scale,
            num_experts: self.num_experts,
            top_k: self.top_k,
            normalize_top_k: self.normalize_top_k,
            router_score_function: self.router_score_function,
            router_logit_softcapping: self.router_logit_softcapping,
            routed_scaling_factor: self.routed_scaling_factor,
            router_group_count: self.router_group_count,
            router_topk_group: self.router_topk_group,
            expert_capacity: self.expert_capacity,
            router_jitter_noise: self.router_jitter_noise,
            jittered_input: if self.router_jitter_noise > 0.0 {
                Some(GpuBuffer::zeros_f32(device, hidden_len)?)
            } else {
                None
            },
            routing_logits: GpuBuffer::zeros_f32(device, routing)?,
            routing_weights: GpuBuffer::zeros_f32(device, routing)?,
            grad_routing_weights: GpuBuffer::zeros_f32(device, routing)?,
            grad_router_logits: GpuBuffer::zeros_f32(device, routing)?,
            grad_router_input: GpuBuffer::zeros_f32(device, hidden_len)?,
            shared_gate_logits: GpuBuffer::zeros_f32(device, rows)?,
            shared_gate_values: GpuBuffer::zeros_f32(device, rows)?,
            grad_shared_gate_values: GpuBuffer::zeros_f32(device, rows)?,
            grad_shared_gate_logits: GpuBuffer::zeros_f32(device, rows)?,
            gate_pre: GpuBuffer::zeros_f32(device, intermediate_len)?,
            up_pre: GpuBuffer::zeros_f32(device, intermediate_len)?,
            activation: GpuBuffer::zeros_f32(device, intermediate_len)?,
            product: GpuBuffer::zeros_f32(device, intermediate_len)?,
            expert_output: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_expert_output: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_product: GpuBuffer::zeros_f32(device, intermediate_len)?,
            grad_gate_activation: GpuBuffer::zeros_f32(device, intermediate_len)?,
            grad_gate_pre: GpuBuffer::zeros_f32(device, intermediate_len)?,
            grad_up_pre: GpuBuffer::zeros_f32(device, intermediate_len)?,
            grad_input_gate: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_input_up: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_expert_input: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            scaled_grad_output: GpuBuffer::zeros_f32(device, hidden_len)?,
            grad_sum_a: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            grad_sum_b: GpuBuffer::zeros_f32(device, hidden_workspace_len)?,
            latent_input: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            latent_output: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            latent_norm_output: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            latent_norm_mean: has_latent
                .then(|| GpuBuffer::zeros_f32(device, rows))
                .transpose()?,
            latent_norm_rstd: has_latent
                .then(|| GpuBuffer::zeros_f32(device, rows))
                .transpose()?,
            grad_latent_after_norm: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            grad_latent_output: has_latent
                .then(|| GpuBuffer::zeros_f32(device, routed_hidden_len))
                .transpose()?,
            grad_latent_hidden: has_latent
                .then(|| GpuBuffer::zeros_f32(device, hidden_len))
                .transpose()?,
        })
    }

    fn freeze_base_parameters(&mut self) {
        self.router.freeze_base();
        if let Some(expert) = self.owned_expert0.as_mut() {
            if let Some(gate) = expert.gate.as_mut() {
                gate.freeze_base();
            }
            expert.up.freeze_base();
            expert.down.freeze_base();
        }
        for expert in &mut self.experts {
            if let Some(gate) = expert.gate.as_mut() {
                gate.freeze_base();
            }
            expert.up.freeze_base();
            expert.down.freeze_base();
        }
        if let Some(expert) = self.shared_expert.as_mut() {
            if let Some(gate) = expert.gate.as_mut() {
                gate.freeze_base();
            }
            expert.up.freeze_base();
            expert.down.freeze_base();
        }
        if let Some(gate) = self.shared_expert_gate.as_mut() {
            gate.freeze_base();
        }
        if let Some(proj) = self.latent_down_proj.as_mut() {
            proj.freeze_base();
        }
        if let Some(norm) = self.latent_norm.as_mut() {
            norm.freeze();
        }
        if let Some(proj) = self.latent_up_proj.as_mut() {
            proj.freeze_base();
        }
    }

    fn enable_bias_training(&mut self) {
        self.router.enable_bias_training();
        if let Some(expert) = self.owned_expert0.as_mut() {
            if let Some(gate) = expert.gate.as_mut() {
                gate.enable_bias_training();
            }
            expert.up.enable_bias_training();
            expert.down.enable_bias_training();
        }
        for expert in &mut self.experts {
            if let Some(gate) = expert.gate.as_mut() {
                gate.enable_bias_training();
            }
            expert.up.enable_bias_training();
            expert.down.enable_bias_training();
        }
        if let Some(expert) = self.shared_expert.as_mut() {
            if let Some(gate) = expert.gate.as_mut() {
                gate.enable_bias_training();
            }
            expert.up.enable_bias_training();
            expert.down.enable_bias_training();
        }
        if let Some(gate) = self.shared_expert_gate.as_mut() {
            gate.enable_bias_training();
        }
        if let Some(proj) = self.latent_down_proj.as_mut() {
            proj.enable_bias_training();
        }
        if let Some(norm) = self.latent_norm.as_mut() {
            norm.enable_bias_training();
        }
        if let Some(proj) = self.latent_up_proj.as_mut() {
            proj.enable_bias_training();
        }
    }

    fn record_expert_forward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        activation_function: &str,
        input: &GpuBuffer,
        gate: Option<&VulkanLinear>,
        up: &VulkanLinear,
        down: &VulkanLinear,
        rows: usize,
        intermediate: usize,
        activation_dropout: f32,
        dropout_site: u32,
        training: bool,
        rng_step: u32,
        rng_seed: u32,
    ) -> Result<()> {
        record_transformer_linear_forward(
            up,
            commands,
            kernels,
            input,
            &self.up_pre,
            rows,
            training,
            rng_step,
            rng_seed,
        )?;
        let activation_push = LenPush {
            len: (rows * intermediate) as u32,
        };
        if let Some(gate) = gate {
            record_transformer_linear_forward(
                gate,
                commands,
                kernels,
                input,
                &self.gate_pre,
                rows,
                training,
                rng_step,
                rng_seed,
            )?;
        }
        if activation_function == "gpt_oss_swiglu" {
            if gate.is_none() {
                bail!("GPT-OSS SwiGLU expert is missing its gate projection");
            }
            kernels.gpt_oss_swiglu_forward.record_dispatch(
                commands,
                &[&self.gate_pre, &self.up_pre, &self.product],
                bytemuck::bytes_of(&activation_push),
                [div_ceil_u32(rows * intermediate, 256), 1, 1],
            )?;
            return record_transformer_linear_forward(
                down,
                commands,
                kernels,
                &self.product,
                &self.expert_output,
                rows,
                training,
                rng_step,
                rng_seed,
            );
        }
        if activation_function == "deepseek_v4_swiglu" {
            if gate.is_none() {
                bail!("DeepSeek-V4 SwiGLU expert is missing its gate projection");
            }
            let clamp_push = ClampPush {
                len: (rows * intermediate) as u32,
                limit: DEEPSEEK_V4_SWIGLU_LIMIT,
            };
            kernels.deepseek_v4_swiglu_forward.record_dispatch(
                commands,
                &[&self.gate_pre, &self.up_pre, &self.product],
                bytemuck::bytes_of(&clamp_push),
                [div_ceil_u32(rows * intermediate, 256), 1, 1],
            )?;
            return record_transformer_linear_forward(
                down,
                commands,
                kernels,
                &self.product,
                &self.expert_output,
                rows,
                training,
                rng_step,
                rng_seed,
            );
        }
        if activation_function == "situ" {
            if gate.is_none() {
                bail!("SiTU MoE expert is missing its gate projection");
            }
            let situ_push = SituPush {
                len: (rows * intermediate) as u32,
                beta: self.situ_beta,
                linear_beta: self.situ_linear_beta.unwrap_or(0.0),
                use_linear_beta: u32::from(self.situ_linear_beta.is_some()),
            };
            kernels.situ_forward.record_dispatch(
                commands,
                &[&self.gate_pre, &self.up_pre, &self.product],
                bytemuck::bytes_of(&situ_push),
                [div_ceil_u32(rows * intermediate, 256), 1, 1],
            )?;
            return record_transformer_linear_forward(
                down,
                commands,
                kernels,
                &self.product,
                &self.expert_output,
                rows,
                training,
                rng_step,
                rng_seed,
            );
        }
        let activation = match activation_function {
            "silu" => &kernels.silu_forward,
            "relu" => &kernels.relu_forward,
            "relu2" => &kernels.relu2_forward,
            "gelu" => &kernels.gelu_erf_forward,
            _ => &kernels.gelu_tanh_forward,
        };
        let activation_input = if gate.is_some() {
            &self.gate_pre
        } else {
            &self.up_pre
        };
        activation.record_dispatch(
            commands,
            &[activation_input, &self.activation],
            bytemuck::bytes_of(&activation_push),
            [div_ceil_u32(rows * intermediate, 256), 1, 1],
        )?;
        let projection_input = if gate.is_some() {
            kernels.elementwise_mul_forward.record_dispatch(
                commands,
                &[&self.activation, &self.up_pre, &self.product],
                bytemuck::bytes_of(&activation_push),
                [div_ceil_u32(rows * intermediate, 256), 1, 1],
            )?;
            &self.product
        } else if training && activation_dropout > 0.0 {
            // SwitchTransformersDenseActDense applies dropout after the
            // activation and before `wo`; reuse the product tape as the
            // dropped activation because dense experts do not need a gated
            // elementwise-product tape.
            record_transformer_dropout(
                commands,
                kernels,
                &self.activation,
                &self.product,
                activation_dropout,
                rng_step,
                dropout_site,
                rng_seed,
                rows * intermediate,
            )?;
            &self.product
        } else {
            &self.activation
        };
        record_transformer_linear_forward(
            down,
            commands,
            kernels,
            projection_input,
            &self.expert_output,
            rows,
            training,
            rng_step,
            rng_seed,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn record_forward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        activation_function: &str,
        input: &GpuBuffer,
        token_ids: Option<&GpuBuffer>,
        expert0_gate: Option<&VulkanLinear>,
        expert0_up: &VulkanLinear,
        expert0_down: &VulkanLinear,
        output: &GpuBuffer,
        rows: usize,
        hidden: usize,
        intermediate: usize,
        activation_dropout: f32,
        dropout_site: u32,
        capacity_group_size: usize,
        training: bool,
        rng_step: u32,
        rng_seed: u32,
    ) -> Result<()> {
        // HF's FP32 Mixtral, MiniMax-M2, DBRX and Switch paths multiply the
        // shared MLP input in-place: both routing and expert projections see
        // jitter. Keep our normalization tape intact for its backward pass.
        let input = if training {
            self.record_jittered_input(
                commands,
                kernels,
                input,
                rows * hidden,
                dropout_site,
                rng_step,
                rng_seed,
            )?
        } else {
            input
        };
        self.router
            .record_forward(commands, kernels, input, &self.routing_logits, rows)?;
        if let Some(tid2eid) = self.hash_router_tid2eid.as_ref() {
            let token_ids = token_ids.context("Hash-MoE forward requires token ids")?;
            let router_push = MoeHashRouterPush {
                rows: rows as u32,
                experts: self.num_experts as u32,
                top_k: self.top_k as u32,
                vocab_size: self.hash_router_vocab_size as u32,
                routed_scaling_factor: self.routed_scaling_factor,
                score_function: self.router_score_function as u32,
            };
            kernels.moe_hash_router.record_dispatch(
                commands,
                &[
                    &self.routing_logits,
                    token_ids,
                    tid2eid,
                    &self.routing_weights,
                ],
                bytemuck::bytes_of(&router_push),
                [div_ceil_u32(rows, 64), 1, 1],
            )?;
        } else {
            let router_push = MoeRouterTopKPush {
                rows: rows as u32,
                experts: self.num_experts as u32,
                top_k: self.top_k as u32,
                normalize_top_k: u32::from(self.normalize_top_k),
                score_function: self.router_score_function as u32,
                group_count: self.router_group_count as u32,
                topk_group: self.router_topk_group as u32,
                routed_scaling_factor: self.routed_scaling_factor,
                expert_capacity: self.expert_capacity as u32,
                capacity_group_size: capacity_group_size as u32,
                router_logit_softcapping: self.router_logit_softcapping,
            };
            kernels.moe_router_topk.record_dispatch(
                commands,
                &[
                    &self.routing_logits,
                    &self.router_correction_bias,
                    &self.routing_weights,
                ],
                bytemuck::bytes_of(&router_push),
                [div_ceil_u32(rows, 64), 1, 1],
            )?;
        }
        let (routed_input, routed_output) = if let Some(down_proj) = self.latent_down_proj.as_ref() {
            let latent_input = self
                .latent_input
                .as_ref()
                .context("Stable LatentMoE is missing its routed input tape")?;
            record_transformer_linear_forward(
                down_proj,
                commands,
                kernels,
                input,
                latent_input,
                rows,
                training,
                rng_step,
                rng_seed,
            )?;
            (
                latent_input,
                self.latent_output
                    .as_ref()
                    .context("Stable LatentMoE is missing its routed output tape")?,
            )
        } else {
            (input, output)
        };
        let routed_hidden = self.routed_hidden;
        for expert_index in 0..self.num_experts {
            if expert_index >= self.identity_expert_start {
                let copy_push = ScalePush {
                    len: (rows * routed_hidden) as u32,
                    scale: 1.0,
                };
                kernels.scale_copy.record_dispatch(
                    commands,
                    &[routed_input, &self.expert_output],
                    bytemuck::bytes_of(&copy_push),
                    [div_ceil_u32(rows * routed_hidden, 256), 1, 1],
                )?;
                let push = MoeWeightedAccumulatePush {
                    rows: rows as u32,
                    dim: routed_hidden as u32,
                    experts: self.num_experts as u32,
                    expert: expert_index as u32,
                    first: u32::from(expert_index == 0),
                };
                kernels.moe_weighted_accumulate.record_dispatch(
                    commands,
                    &[&self.expert_output, &self.routing_weights, routed_output],
                    bytemuck::bytes_of(&push),
                    [div_ceil_u32(routed_hidden, 16), div_ceil_u32(rows, 16), 1],
                )?;
                continue;
            }
            let (gate, up, down) = if expert_index == 0 {
                if let Some(expert) = self.owned_expert0.as_ref() {
                    (expert.gate.as_ref(), &expert.up, &expert.down)
                } else {
                    (expert0_gate, expert0_up, expert0_down)
                }
            } else {
                let expert = &self.experts[expert_index - 1];
                (expert.gate.as_ref(), &expert.up, &expert.down)
            };
            self.record_expert_forward(
                commands,
                kernels,
                activation_function,
                routed_input,
                gate,
                up,
                down,
                rows,
                intermediate,
                activation_dropout,
                dropout_site.wrapping_add((expert_index as u32).wrapping_mul(0x0001_0000)),
                training,
                rng_step,
                rng_seed,
            )?;
            let push = MoeWeightedAccumulatePush {
                rows: rows as u32,
                dim: routed_hidden as u32,
                experts: self.num_experts as u32,
                expert: expert_index as u32,
                first: u32::from(expert_index == 0),
            };
            kernels.moe_weighted_accumulate.record_dispatch(
                commands,
                &[&self.expert_output, &self.routing_weights, routed_output],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(routed_hidden, 16), div_ceil_u32(rows, 16), 1],
            )?;
        }
        if let Some(up_proj) = self.latent_up_proj.as_ref() {
            let latent_output = self
                .latent_output
                .as_ref()
                .context("Stable LatentMoE is missing its routed output tape")?;
            let projection_input = if let Some(norm) = self.latent_norm.as_ref() {
                let norm_output = self
                    .latent_norm_output
                    .as_ref()
                    .context("Stable LatentMoE is missing its norm output tape")?;
                norm.record_forward(
                    commands,
                    kernels,
                    latent_output,
                    norm_output,
                    self.latent_norm_mean
                        .as_ref()
                        .context("Stable LatentMoE is missing its norm mean tape")?,
                    self.latent_norm_rstd
                        .as_ref()
                        .context("Stable LatentMoE is missing its norm rstd tape")?,
                    rows,
                )?;
                norm_output
            } else {
                latent_output
            };
            record_transformer_linear_forward(
                up_proj,
                commands,
                kernels,
                projection_input,
                output,
                rows,
                training,
                rng_step,
                rng_seed,
            )?;
        }
        if let Some(shared_expert) = self.shared_expert.as_ref() {
            if let Some(shared_gate) = self.shared_expert_gate.as_ref() {
                shared_gate.record_forward(
                    commands,
                    kernels,
                    input,
                    &self.shared_gate_logits,
                    rows,
                )?;
                let gate_push = LenPush { len: rows as u32 };
                kernels.sigmoid_forward.record_dispatch(
                    commands,
                    &[&self.shared_gate_logits, &self.shared_gate_values],
                    bytemuck::bytes_of(&gate_push),
                    [div_ceil_u32(rows, 256), 1, 1],
                )?;
            }
            self.record_expert_forward(
                commands,
                kernels,
                activation_function,
                input,
                shared_expert.gate.as_ref(),
                &shared_expert.up,
                &shared_expert.down,
                rows,
                self.shared_intermediate,
                0.0,
                dropout_site.wrapping_add(0x7fff_0000),
                training,
                rng_step,
                rng_seed,
            )?;
            let shared_output = if self.shared_expert_gate.is_some() {
                record_row_scale(
                    commands,
                    kernels,
                    &self.expert_output,
                    &self.shared_gate_values,
                    &self.grad_expert_output,
                    rows,
                    hidden,
                )?;
                &self.grad_expert_output
            } else {
                &self.expert_output
            };
            record_add(
                commands,
                kernels,
                output,
                shared_output,
                &self.grad_sum_a,
                rows * hidden,
            )?;
            let copy_push = ScalePush {
                len: (rows * hidden) as u32,
                scale: self.shared_expert_combination_scale,
            };
            kernels.scale_copy.record_dispatch(
                commands,
                &[&self.grad_sum_a, output],
                bytemuck::bytes_of(&copy_push),
                [div_ceil_u32(rows * hidden, 256), 1, 1],
            )?;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn record_backward(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        activation_function: &str,
        input: &GpuBuffer,
        expert0_gate: Option<&VulkanLinear>,
        expert0_up: &VulkanLinear,
        expert0_down: &VulkanLinear,
        grad_output: &GpuBuffer,
        grad_input: &GpuBuffer,
        rows: usize,
        hidden: usize,
        intermediate: usize,
        activation_dropout: f32,
        dropout_site: u32,
        rng_step: u32,
        rng_seed: u32,
    ) -> Result<()> {
        let effective_grad_output =
            if self.shared_expert.is_some() && self.shared_expert_combination_scale != 1.0 {
                let copy_push = ScalePush {
                    len: (rows * hidden) as u32,
                    scale: self.shared_expert_combination_scale,
                };
                kernels.scale_copy.record_dispatch(
                    commands,
                    &[grad_output, &self.scaled_grad_output],
                    bytemuck::bytes_of(&copy_push),
                    [div_ceil_u32(rows * hidden, 256), 1, 1],
                )?;
                &self.scaled_grad_output
            } else {
                grad_output
            };
        let input = self.record_jittered_input(
            commands,
            kernels,
            input,
            rows * hidden,
            dropout_site,
            rng_step,
            rng_seed,
        )?;
        let routed_input = if let Some(down_proj) = self.latent_down_proj.as_ref() {
            let latent_input = self
                .latent_input
                .as_ref()
                .context("Stable LatentMoE is missing its routed input tape")?;
            record_transformer_linear_forward(
                down_proj,
                commands,
                kernels,
                input,
                latent_input,
                rows,
                true,
                rng_step,
                rng_seed,
            )?;
            latent_input
        } else {
            input
        };
        let routed_grad_output = if let Some(up_proj) = self.latent_up_proj.as_ref() {
            let latent_output = self
                .latent_output
                .as_ref()
                .context("Stable LatentMoE is missing its routed output tape")?;
            let projection_input = self.latent_norm_output.as_ref().unwrap_or(latent_output);
            let grad_after_norm = self
                .grad_latent_after_norm
                .as_ref()
                .context("Stable LatentMoE is missing its post-norm gradient tape")?;
            up_proj.record_backward(
                commands,
                kernels,
                projection_input,
                effective_grad_output,
                grad_after_norm,
                rows,
            )?;
            if let Some(norm) = self.latent_norm.as_ref() {
                let grad_latent_output = self
                    .grad_latent_output
                    .as_ref()
                    .context("Stable LatentMoE is missing its routed gradient tape")?;
                norm.record_backward(
                    commands,
                    kernels,
                    latent_output,
                    grad_after_norm,
                    self.latent_norm_mean
                        .as_ref()
                        .context("Stable LatentMoE is missing its norm mean tape")?,
                    self.latent_norm_rstd
                        .as_ref()
                        .context("Stable LatentMoE is missing its norm rstd tape")?,
                    grad_latent_output,
                    rows,
                )?;
                grad_latent_output
            } else {
                grad_after_norm
            }
        } else {
            effective_grad_output
        };
        let routed_hidden = self.routed_hidden;
        let activation_push = LenPush {
            len: (rows * intermediate) as u32,
        };
        for expert_index in 0..self.num_experts {
            let expert_dropout_site =
                dropout_site.wrapping_add((expert_index as u32).wrapping_mul(0x0001_0000));
            if expert_index >= self.identity_expert_start {
                let copy_push = ScalePush {
                    len: (rows * routed_hidden) as u32,
                    scale: 1.0,
                };
                kernels.scale_copy.record_dispatch(
                    commands,
                    &[routed_input, &self.expert_output],
                    bytemuck::bytes_of(&copy_push),
                    [div_ceil_u32(rows * routed_hidden, 256), 1, 1],
                )?;
                let expert_push = MoeExpertPush {
                    rows: rows as u32,
                    dim: routed_hidden as u32,
                    experts: self.num_experts as u32,
                    expert: expert_index as u32,
                };
                kernels.moe_row_dot.record_dispatch(
                    commands,
                    &[
                        routed_grad_output,
                        &self.expert_output,
                        &self.grad_routing_weights,
                    ],
                    bytemuck::bytes_of(&expert_push),
                    [div_ceil_u32(rows, 64), 1, 1],
                )?;
                kernels.moe_row_scale.record_dispatch(
                    commands,
                    &[
                        routed_grad_output,
                        &self.routing_weights,
                        &self.grad_expert_output,
                    ],
                    bytemuck::bytes_of(&expert_push),
                    [div_ceil_u32(routed_hidden, 16), div_ceil_u32(rows, 16), 1],
                )?;
                kernels.scale_copy.record_dispatch(
                    commands,
                    &[&self.grad_expert_output, &self.grad_expert_input],
                    bytemuck::bytes_of(&copy_push),
                    [div_ceil_u32(rows * routed_hidden, 256), 1, 1],
                )?;
                if expert_index == 0 {
                    kernels.scale_copy.record_dispatch(
                        commands,
                        &[&self.grad_expert_input, &self.grad_sum_a],
                        bytemuck::bytes_of(&copy_push),
                        [div_ceil_u32(rows * routed_hidden, 256), 1, 1],
                    )?;
                } else if expert_index % 2 == 1 {
                    record_add(
                        commands,
                        kernels,
                        &self.grad_sum_a,
                        &self.grad_expert_input,
                        &self.grad_sum_b,
                        rows * routed_hidden,
                    )?;
                } else {
                    record_add(
                        commands,
                        kernels,
                        &self.grad_sum_b,
                        &self.grad_expert_input,
                        &self.grad_sum_a,
                        rows * routed_hidden,
                    )?;
                }
                continue;
            }
            let (gate, up, down) = if expert_index == 0 {
                if let Some(expert) = self.owned_expert0.as_ref() {
                    (expert.gate.as_ref(), &expert.up, &expert.down)
                } else {
                    (expert0_gate, expert0_up, expert0_down)
                }
            } else {
                let expert = &self.experts[expert_index - 1];
                (expert.gate.as_ref(), &expert.up, &expert.down)
            };
            self.record_expert_forward(
                commands,
                kernels,
                activation_function,
                routed_input,
                gate,
                up,
                down,
                rows,
                intermediate,
                activation_dropout,
                expert_dropout_site,
                true,
                rng_step,
                rng_seed,
            )?;
            let expert_push = MoeExpertPush {
                rows: rows as u32,
                dim: routed_hidden as u32,
                experts: self.num_experts as u32,
                expert: expert_index as u32,
            };
            kernels.moe_row_dot.record_dispatch(
                commands,
                &[
                    routed_grad_output,
                    &self.expert_output,
                    &self.grad_routing_weights,
                ],
                bytemuck::bytes_of(&expert_push),
                [div_ceil_u32(rows, 64), 1, 1],
            )?;
            kernels.moe_row_scale.record_dispatch(
                commands,
                &[
                    routed_grad_output,
                    &self.routing_weights,
                    &self.grad_expert_output,
                ],
                bytemuck::bytes_of(&expert_push),
                [div_ceil_u32(routed_hidden, 16), div_ceil_u32(rows, 16), 1],
            )?;
            let down_input = if gate.is_some() || activation_dropout > 0.0 {
                &self.product
            } else {
                &self.activation
            };
            down.record_backward(
                commands,
                kernels,
                down_input,
                &self.grad_expert_output,
                &self.grad_product,
                rows,
            )?;
            if gate.is_none() {
                // Switch experts are ordinary DenseActDense blocks. Backprop
                // through the activation dropout (using the same canonical
                // RNG reservation as forward), then the activation and `wi`.
                let grad_activation = if activation_dropout > 0.0 {
                    record_transformer_dropout(
                        commands,
                        kernels,
                        &self.grad_product,
                        &self.grad_gate_activation,
                        activation_dropout,
                        rng_step,
                        expert_dropout_site,
                        rng_seed,
                        rows * intermediate,
                    )?;
                    &self.grad_gate_activation
                } else {
                    &self.grad_product
                };
                let activation_backward = match activation_function {
                    "silu" => &kernels.silu_backward,
                    "relu" => &kernels.relu_backward,
                    "relu2" => &kernels.relu2_backward,
                    "gelu" => &kernels.gelu_erf_backward,
                    _ => &kernels.gelu_tanh_backward,
                };
                let activation_bindings = if activation_function == "silu" {
                    [grad_activation, &self.up_pre, &self.grad_up_pre]
                } else {
                    [&self.up_pre, grad_activation, &self.grad_up_pre]
                };
                activation_backward.record_dispatch(
                    commands,
                    &activation_bindings,
                    bytemuck::bytes_of(&activation_push),
                    [div_ceil_u32(rows * intermediate, 256), 1, 1],
                )?;
                up.record_backward(
                    commands,
                    kernels,
                    routed_input,
                    &self.grad_up_pre,
                    &self.grad_expert_input,
                    rows,
                )?;
            } else if activation_function == "gpt_oss_swiglu" {
                kernels.gpt_oss_swiglu_backward.record_dispatch(
                    commands,
                    &[
                        &self.grad_product,
                        &self.gate_pre,
                        &self.up_pre,
                        &self.grad_gate_pre,
                        &self.grad_up_pre,
                    ],
                    bytemuck::bytes_of(&activation_push),
                    [div_ceil_u32(rows * intermediate, 256), 1, 1],
                )?;
            } else if activation_function == "deepseek_v4_swiglu" {
                let clamp_push = ClampPush {
                    len: (rows * intermediate) as u32,
                    limit: DEEPSEEK_V4_SWIGLU_LIMIT,
                };
                kernels.deepseek_v4_swiglu_backward.record_dispatch(
                    commands,
                    &[
                        &self.grad_product,
                        &self.gate_pre,
                        &self.up_pre,
                        &self.grad_gate_pre,
                        &self.grad_up_pre,
                    ],
                    bytemuck::bytes_of(&clamp_push),
                    [div_ceil_u32(rows * intermediate, 256), 1, 1],
                )?;
            } else if activation_function == "situ" {
                let situ_push = SituPush {
                    len: (rows * intermediate) as u32,
                    beta: self.situ_beta,
                    linear_beta: self.situ_linear_beta.unwrap_or(0.0),
                    use_linear_beta: u32::from(self.situ_linear_beta.is_some()),
                };
                kernels.situ_backward.record_dispatch(
                    commands,
                    &[
                        &self.grad_product,
                        &self.gate_pre,
                        &self.up_pre,
                        &self.grad_gate_pre,
                        &self.grad_up_pre,
                    ],
                    bytemuck::bytes_of(&situ_push),
                    [div_ceil_u32(rows * intermediate, 256), 1, 1],
                )?;
            } else {
                kernels.elementwise_mul_backward.record_dispatch(
                    commands,
                    &[
                        &self.grad_product,
                        &self.activation,
                        &self.up_pre,
                        &self.grad_gate_activation,
                        &self.grad_up_pre,
                    ],
                    bytemuck::bytes_of(&activation_push),
                    [div_ceil_u32(rows * intermediate, 256), 1, 1],
                )?;
                let activation_backward = match activation_function {
                    "silu" => &kernels.silu_backward,
                    "relu" => &kernels.relu_backward,
                    "relu2" => &kernels.relu2_backward,
                    "gelu" => &kernels.gelu_erf_backward,
                    _ => &kernels.gelu_tanh_backward,
                };
                let activation_bindings = if activation_function == "silu" {
                    [
                        &self.grad_gate_activation,
                        &self.gate_pre,
                        &self.grad_gate_pre,
                    ]
                } else {
                    [
                        &self.gate_pre,
                        &self.grad_gate_activation,
                        &self.grad_gate_pre,
                    ]
                };
                activation_backward.record_dispatch(
                    commands,
                    &activation_bindings,
                    bytemuck::bytes_of(&activation_push),
                    [div_ceil_u32(rows * intermediate, 256), 1, 1],
                )?;
            }
            if let Some(gate) = gate {
                gate.record_backward(
                    commands,
                    kernels,
                    routed_input,
                    &self.grad_gate_pre,
                    &self.grad_input_gate,
                    rows,
                )?;
                up.record_backward(
                    commands,
                    kernels,
                    routed_input,
                    &self.grad_up_pre,
                    &self.grad_input_up,
                    rows,
                )?;
                record_add(
                    commands,
                    kernels,
                    &self.grad_input_gate,
                    &self.grad_input_up,
                    &self.grad_expert_input,
                    rows * routed_hidden,
                )?;
            }
            if expert_index == 0 {
                let copy_push = ScalePush {
                    len: (rows * routed_hidden) as u32,
                    scale: 1.0,
                };
                kernels.scale_copy.record_dispatch(
                    commands,
                    &[&self.grad_expert_input, &self.grad_sum_a],
                    bytemuck::bytes_of(&copy_push),
                    [div_ceil_u32(rows * routed_hidden, 256), 1, 1],
                )?;
            } else if expert_index % 2 == 1 {
                record_add(
                    commands,
                    kernels,
                    &self.grad_sum_a,
                    &self.grad_expert_input,
                    &self.grad_sum_b,
                    rows * routed_hidden,
                )?;
            } else {
                record_add(
                    commands,
                    kernels,
                    &self.grad_sum_b,
                    &self.grad_expert_input,
                    &self.grad_sum_a,
                    rows * routed_hidden,
                )?;
            }
        }
        let router_push = MoeRouterBackwardPush {
            rows: rows as u32,
            experts: self.num_experts as u32,
            normalize_top_k: u32::from(self.normalize_top_k),
            score_function: self.router_score_function as u32,
            routed_scaling_factor: self.routed_scaling_factor,
            router_logit_softcapping: self.router_logit_softcapping,
        };
        kernels.moe_router_backward.record_dispatch(
            commands,
            &[
                &self.routing_weights,
                &self.grad_routing_weights,
                &self.routing_logits,
                &self.grad_router_logits,
            ],
            bytemuck::bytes_of(&router_push),
            [div_ceil_u32(rows, 64), 1, 1],
        )?;
        self.router.record_backward(
            commands,
            kernels,
            input,
            &self.grad_router_logits,
            &self.grad_router_input,
            rows,
        )?;
        let expert_sum = if self.num_experts % 2 == 0 {
            &self.grad_sum_b
        } else {
            &self.grad_sum_a
        };
        let expert_sum = if let Some(proj) = self.latent_down_proj.as_ref() {
            let grad_hidden = self
                .grad_latent_hidden
                .as_ref()
                .context("Stable LatentMoE is missing its hidden gradient tape")?;
            proj.record_backward(commands, kernels, input, expert_sum, grad_hidden, rows)?;
            grad_hidden
        } else {
            expert_sum
        };
        record_add(
            commands,
            kernels,
            expert_sum,
            &self.grad_router_input,
            grad_input,
            rows * hidden,
        )?;
        if let Some(shared_expert) = self.shared_expert.as_ref() {
            let shared_intermediate = self.shared_intermediate;
            self.record_expert_forward(
                commands,
                kernels,
                activation_function,
                input,
                shared_expert.gate.as_ref(),
                &shared_expert.up,
                &shared_expert.down,
                rows,
                shared_intermediate,
                0.0,
                0,
                true,
                rng_step,
                rng_seed,
            )?;
            if self.shared_expert_gate.is_some() {
                record_row_scale(
                    commands,
                    kernels,
                    effective_grad_output,
                    &self.shared_gate_values,
                    &self.grad_expert_output,
                    rows,
                    hidden,
                )?;
                let shared_gate_push = MoeExpertPush {
                    rows: rows as u32,
                    dim: hidden as u32,
                    experts: 1,
                    expert: 0,
                };
                kernels.moe_row_dot.record_dispatch(
                    commands,
                    &[
                        effective_grad_output,
                        &self.expert_output,
                        &self.grad_shared_gate_values,
                    ],
                    bytemuck::bytes_of(&shared_gate_push),
                    [div_ceil_u32(rows, 64), 1, 1],
                )?;
                let gate_push = LenPush { len: rows as u32 };
                kernels.sigmoid_backward.record_dispatch(
                    commands,
                    &[
                        &self.grad_shared_gate_values,
                        &self.shared_gate_logits,
                        &self.grad_shared_gate_logits,
                    ],
                    bytemuck::bytes_of(&gate_push),
                    [div_ceil_u32(rows, 256), 1, 1],
                )?;
            } else {
                let copy_push = ScalePush {
                    len: (rows * hidden) as u32,
                    scale: 1.0,
                };
                kernels.scale_copy.record_dispatch(
                    commands,
                    &[effective_grad_output, &self.grad_expert_output],
                    bytemuck::bytes_of(&copy_push),
                    [div_ceil_u32(rows * hidden, 256), 1, 1],
                )?;
            }
            shared_expert.down.record_backward(
                commands,
                kernels,
                if shared_expert.gate.is_some() {
                    &self.product
                } else {
                    &self.activation
                },
                &self.grad_expert_output,
                &self.grad_product,
                rows,
            )?;
            let activation_push = LenPush {
                len: (rows * shared_intermediate) as u32,
            };
            if let Some(gate) = shared_expert.gate.as_ref() {
                if activation_function == "gpt_oss_swiglu" {
                    kernels.gpt_oss_swiglu_backward.record_dispatch(
                        commands,
                        &[
                            &self.grad_product,
                            &self.gate_pre,
                            &self.up_pre,
                            &self.grad_gate_pre,
                            &self.grad_up_pre,
                        ],
                        bytemuck::bytes_of(&activation_push),
                        [div_ceil_u32(rows * shared_intermediate, 256), 1, 1],
                    )?;
                } else if activation_function == "deepseek_v4_swiglu" {
                    let clamp_push = ClampPush {
                        len: (rows * shared_intermediate) as u32,
                        limit: DEEPSEEK_V4_SWIGLU_LIMIT,
                    };
                    kernels.deepseek_v4_swiglu_backward.record_dispatch(
                        commands,
                        &[
                            &self.grad_product,
                            &self.gate_pre,
                            &self.up_pre,
                            &self.grad_gate_pre,
                            &self.grad_up_pre,
                        ],
                        bytemuck::bytes_of(&clamp_push),
                        [div_ceil_u32(rows * shared_intermediate, 256), 1, 1],
                    )?;
                } else if activation_function == "situ" {
                    let situ_push = SituPush {
                        len: (rows * shared_intermediate) as u32,
                        beta: self.situ_beta,
                        linear_beta: self.situ_linear_beta.unwrap_or(0.0),
                        use_linear_beta: u32::from(self.situ_linear_beta.is_some()),
                    };
                    kernels.situ_backward.record_dispatch(
                        commands,
                        &[
                            &self.grad_product,
                            &self.gate_pre,
                            &self.up_pre,
                            &self.grad_gate_pre,
                            &self.grad_up_pre,
                        ],
                        bytemuck::bytes_of(&situ_push),
                        [div_ceil_u32(rows * shared_intermediate, 256), 1, 1],
                    )?;
                } else {
                    kernels.elementwise_mul_backward.record_dispatch(
                        commands,
                        &[
                            &self.grad_product,
                            &self.activation,
                            &self.up_pre,
                            &self.grad_gate_activation,
                            &self.grad_up_pre,
                        ],
                        bytemuck::bytes_of(&activation_push),
                        [div_ceil_u32(rows * shared_intermediate, 256), 1, 1],
                    )?;
                    let activation_backward = match activation_function {
                        "silu" => &kernels.silu_backward,
                        "relu" => &kernels.relu_backward,
                        "relu2" => &kernels.relu2_backward,
                        "gelu" => &kernels.gelu_erf_backward,
                        _ => &kernels.gelu_tanh_backward,
                    };
                    let activation_bindings = if activation_function == "silu" {
                        [
                            &self.grad_gate_activation,
                            &self.gate_pre,
                            &self.grad_gate_pre,
                        ]
                    } else {
                        [
                            &self.gate_pre,
                            &self.grad_gate_activation,
                            &self.grad_gate_pre,
                        ]
                    };
                    activation_backward.record_dispatch(
                        commands,
                        &activation_bindings,
                        bytemuck::bytes_of(&activation_push),
                        [div_ceil_u32(rows * shared_intermediate, 256), 1, 1],
                    )?;
                }
                gate.record_backward(
                    commands,
                    kernels,
                    input,
                    &self.grad_gate_pre,
                    &self.grad_input_gate,
                    rows,
                )?;
                shared_expert.up.record_backward(
                    commands,
                    kernels,
                    input,
                    &self.grad_up_pre,
                    &self.grad_input_up,
                    rows,
                )?;
                record_add(
                    commands,
                    kernels,
                    &self.grad_input_gate,
                    &self.grad_input_up,
                    &self.grad_expert_input,
                    rows * hidden,
                )?;
            } else {
                let activation_backward = match activation_function {
                    "silu" => &kernels.silu_backward,
                    "relu" => &kernels.relu_backward,
                    "relu2" => &kernels.relu2_backward,
                    "gelu" => &kernels.gelu_erf_backward,
                    _ => &kernels.gelu_tanh_backward,
                };
                let activation_bindings = if activation_function == "silu" {
                    [&self.grad_product, &self.up_pre, &self.grad_up_pre]
                } else {
                    [&self.up_pre, &self.grad_product, &self.grad_up_pre]
                };
                activation_backward.record_dispatch(
                    commands,
                    &activation_bindings,
                    bytemuck::bytes_of(&activation_push),
                    [div_ceil_u32(rows * shared_intermediate, 256), 1, 1],
                )?;
                shared_expert.up.record_backward(
                    commands,
                    kernels,
                    input,
                    &self.grad_up_pre,
                    &self.grad_expert_input,
                    rows,
                )?;
            }
            let shared_input_grad = if let Some(shared_gate) = self.shared_expert_gate.as_ref() {
                shared_gate.record_backward(
                    commands,
                    kernels,
                    input,
                    &self.grad_shared_gate_logits,
                    &self.grad_router_input,
                    rows,
                )?;
                record_add(
                    commands,
                    kernels,
                    &self.grad_expert_input,
                    &self.grad_router_input,
                    &self.grad_sum_a,
                    rows * hidden,
                )?;
                &self.grad_sum_a
            } else {
                &self.grad_expert_input
            };
            record_add(
                commands,
                kernels,
                grad_input,
                shared_input_grad,
                &self.grad_sum_b,
                rows * hidden,
            )?;
            let copy_push = ScalePush {
                len: (rows * hidden) as u32,
                scale: 1.0,
            };
            kernels.scale_copy.record_dispatch(
                commands,
                &[&self.grad_sum_b, grad_input],
                bytemuck::bytes_of(&copy_push),
                [div_ceil_u32(rows * hidden, 256), 1, 1],
            )?;
        }
        if self.jittered_input.is_some() {
            self.record_jitter(
                commands,
                kernels,
                grad_input,
                grad_input,
                rows * hidden,
                dropout_site,
                rng_step,
                rng_seed,
            )?;
        }
        Ok(())
    }

    fn record_step(
        &self,
        commands: &mut vulkan::ComputeBatch,
        kernels: &TransformerKernels,
        step: u32,
        hyper: AdamWHyperParams,
    ) -> Result<()> {
        self.router.record_step(commands, kernels, step, hyper)?;
        if let Some(expert) = self.owned_expert0.as_ref() {
            if let Some(gate) = expert.gate.as_ref() {
                gate.record_step(commands, kernels, step, hyper)?;
            }
            expert.up.record_step(commands, kernels, step, hyper)?;
            expert.down.record_step(commands, kernels, step, hyper)?;
        }
        for expert in &self.experts {
            if let Some(gate) = expert.gate.as_ref() {
                gate.record_step(commands, kernels, step, hyper)?;
            }
            expert.up.record_step(commands, kernels, step, hyper)?;
            expert.down.record_step(commands, kernels, step, hyper)?;
        }
        if let Some(expert) = self.shared_expert.as_ref() {
            if let Some(gate) = expert.gate.as_ref() {
                gate.record_step(commands, kernels, step, hyper)?;
            }
            expert.up.record_step(commands, kernels, step, hyper)?;
            expert.down.record_step(commands, kernels, step, hyper)?;
        }
        if let Some(gate) = self.shared_expert_gate.as_ref() {
            gate.record_step(commands, kernels, step, hyper)?;
        }
        if let Some(proj) = self.latent_down_proj.as_ref() {
            proj.record_step(commands, kernels, step, hyper)?;
        }
        if let Some(norm) = self.latent_norm.as_ref() {
            norm.record_step(commands, kernels, step, hyper)?;
        }
        if let Some(proj) = self.latent_up_proj.as_ref() {
            proj.record_step(commands, kernels, step, hyper)?;
        }
        Ok(())
    }
}

