    /// Structured encoder-context generation with the source token ids needed
    /// by HF's encoder-side repetition/no-repeat processors.
    pub fn generate_output_with_encoder_input_ids_and_hidden_states(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_input_ids: &[u32],
        encoder_hidden_states: &[f32],
        encoder_attention_mask: &[f32],
    ) -> Result<VulkanTransformerGenerationOutput> {
        let mut request_config = config.clone();
        request_config.encoder_input_ids = Some(encoder_input_ids.to_vec());
        self.generate_output_with_context(
            prompt,
            &request_config,
            Some(encoder_hidden_states),
            Some(encoder_attention_mask),
        )
    }

    /// Context-aware structured generation for decoder graphs with fixed
    /// external encoder hidden states.
    pub fn generate_output_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<VulkanTransformerGenerationOutput> {
        config.validate()?;
        let prepared_prompt =
            self.prepare_generation_prompt(prompt, config, encoder_hidden_states)?;
        self.validate_generation_request(&prepared_prompt, config)?;
        self.validate_generation_encoder_processor_inputs(config, encoder_hidden_states)?;
        let mut output = if config.num_beams > 1 {
            self.generate_beam_output_full_prefix_with_context(
                &prepared_prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
            )?
        } else {
            let mut sequences = Vec::with_capacity(config.num_return_sequences);
            let generation_started = Instant::now();
            for sequence_index in 0..config.num_return_sequences {
                let mut sequence_config = config.clone();
                sequence_config.num_return_sequences = 1;
                sequence_config.seed = config.seed.wrapping_add(sequence_index as u64);
                sequence_config.max_time =
                    generation_remaining_max_time(config.max_time, generation_started);
                sequences.push(self.generate_single_output_full_prefix_with_context(
                    &prepared_prompt,
                    &sequence_config,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?);
            }
            VulkanTransformerGenerationOutput { sequences }
        };

        // Some generation modes (beam, constrained/group beam, contrastive,
        // and assisted generation) finalize hypotheses through mode-specific
        // control flow rather than the ordinary per-token collector. Replay
        // the finalized path only when hidden states were requested and that
        // mode did not already collect them. This keeps token selection and
        // scores untouched while exposing the same prompt-prefill / one-row
        // cached shape contract used by the non-beam path.
        if config.return_dict_in_generate && config.output_hidden_states {
            for sequence in &mut output.sequences {
                if sequence.hidden_states.is_none() {
                    sequence.hidden_states =
                        Some(self.generation_hidden_state_trace_for_sequence(
                            &sequence.sequence,
                            sequence.prompt_length,
                            config.use_cache,
                            encoder_hidden_states,
                            encoder_attention_mask,
                        )?);
                }
            }
        }
        if config.return_dict_in_generate && config.output_attentions {
            for sequence in &mut output.sequences {
                let (attentions, cross_attentions) = self.generation_attention_trace_for_sequence(
                    &sequence.sequence,
                    sequence.prompt_length,
                    config.use_cache,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                sequence.attentions = Some(attentions);
                sequence.cross_attentions = cross_attentions;
            }
        }
        Ok(output)
    }

    /// Same-tokenizer assisted generation using a separate Vulkan Transformer
    /// as the draft model. This mirrors Hugging Face's `assistant_model`
    /// surface while keeping tokenization outside the native graph API.
    pub fn generate_ids_with_assistant_model(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
    ) -> Result<Vec<u32>> {
        self.generate_ids_with_assistant_model_and_context(
            prompt,
            config,
            assistant_model,
            None,
            None,
        )
    }

    /// Context-aware counterpart of `generate_ids_with_assistant_model`.
    /// Encoder state is shared with the assistant when its graph also owns
    /// cross-attention, matching same-tokenizer encoder-context assistance.
    pub fn generate_ids_with_assistant_model_and_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<u32>> {
        let output = self.generate_output_with_assistant_model_and_context(
            prompt,
            config,
            assistant_model,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        output
            .sequences
            .into_iter()
            .next()
            .map(|sequence| sequence.generated_ids().to_vec())
            .context("assistant-model generation produced no sequence")
    }

    /// Structured same-tokenizer assisted generation with a separate Vulkan
    /// assistant model.
    pub fn generate_output_with_assistant_model(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
    ) -> Result<VulkanTransformerGenerationOutput> {
        self.generate_output_with_assistant_model_and_context(
            prompt,
            config,
            assistant_model,
            None,
            None,
        )
    }

    /// Structured external-assistant generation with optional encoder context.
    pub fn generate_output_with_assistant_model_and_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<VulkanTransformerGenerationOutput> {
        config.validate()?;
        let prepared_prompt =
            self.prepare_generation_prompt(prompt, config, encoder_hidden_states)?;
        self.validate_generation_request(&prepared_prompt, config)?;
        self.validate_generation_encoder_processor_inputs(config, encoder_hidden_states)?;
        self.validate_external_assistant_generation_request(
            &prepared_prompt,
            config,
            assistant_model,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;

        let mut sequence = self.generate_external_assistant_output_with_context(
            assistant_model,
            &prepared_prompt,
            config,
            encoder_hidden_states,
            encoder_attention_mask,
            |_| Ok(()),
        )?;
        if config.return_dict_in_generate && config.output_hidden_states {
            sequence.hidden_states = Some(self.generation_hidden_state_trace_for_sequence(
                &sequence.sequence,
                sequence.prompt_length,
                config.use_cache,
                encoder_hidden_states,
                encoder_attention_mask,
            )?);
        }
        if config.return_dict_in_generate && config.output_attentions {
            let (attentions, cross_attentions) = self.generation_attention_trace_for_sequence(
                &sequence.sequence,
                sequence.prompt_length,
                config.use_cache,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            sequence.attentions = Some(attentions);
            sequence.cross_attentions = cross_attentions;
        }
        Ok(VulkanTransformerGenerationOutput {
            sequences: vec![sequence],
        })
    }

    /// Stream continuation tokens produced with a separate same-tokenizer
    /// assistant model.
    pub fn generate_ids_streaming_with_assistant_model<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
        on_token: F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        self.generate_ids_streaming_with_assistant_model_and_context(
            prompt,
            config,
            assistant_model,
            None,
            None,
            on_token,
        )
    }

    /// Context-aware streaming external-assistant generation.
    pub fn generate_ids_streaming_with_assistant_model_and_context<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        on_token: F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        config.validate()?;
        let prepared_prompt =
            self.prepare_generation_prompt(prompt, config, encoder_hidden_states)?;
        self.validate_generation_request(&prepared_prompt, config)?;
        self.validate_generation_encoder_processor_inputs(config, encoder_hidden_states)?;
        self.validate_external_assistant_generation_request(
            &prepared_prompt,
            config,
            assistant_model,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        let output = self.generate_external_assistant_output_with_context(
            assistant_model,
            &prepared_prompt,
            config,
            encoder_hidden_states,
            encoder_attention_mask,
            on_token,
        )?;
        Ok(output.generated_ids().to_vec())
    }

    /// Serial batch compatibility surface for same-tokenizer external
    /// assistant-model generation. Each prompt receives a disjoint sampling
    /// seed, matching the ordinary Vulkan batch generation contract.
    pub fn generate_batch_ids_with_assistant_model(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
    ) -> Result<Vec<Vec<u32>>> {
        self.generate_batch_ids_with_assistant_model_and_context(
            prompts,
            config,
            assistant_model,
            None,
            None,
        )
    }

    /// Context-aware serial batch external-assistant generation.
    pub fn generate_batch_ids_with_assistant_model_and_context(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
        encoder_hidden_states: Option<&[Vec<f32>]>,
        encoder_attention_masks: Option<&[Vec<f32>]>,
    ) -> Result<Vec<Vec<u32>>> {
        config.validate()?;
        if let Some(encoder_hidden_states) = encoder_hidden_states {
            if encoder_hidden_states.len() != prompts.len() {
                bail!(
                    "batched encoder hidden states contain {} items for {} prompts",
                    encoder_hidden_states.len(),
                    prompts.len()
                );
            }
        } else if encoder_attention_masks.is_some() {
            bail!("batched encoder attention masks were supplied without encoder hidden states");
        }
        if let Some(encoder_attention_masks) = encoder_attention_masks {
            if encoder_attention_masks.len() != prompts.len() {
                bail!(
                    "batched encoder attention masks contain {} items for {} prompts",
                    encoder_attention_masks.len(),
                    prompts.len()
                );
            }
        }

        let generation_started = Instant::now();
        prompts
            .iter()
            .enumerate()
            .map(|(batch_index, prompt)| {
                let mut batch_config = config.clone();
                batch_config
                    .specialize_decoder_start_token_for_batch(batch_index, prompts.len())?;
                batch_config.seed = config.seed.wrapping_add(batch_index as u64);
                batch_config.max_time =
                    generation_remaining_max_time(config.max_time, generation_started);
                let encoder_hidden =
                    encoder_hidden_states.map(|batch| batch[batch_index].as_slice());
                let encoder_mask =
                    encoder_attention_masks.map(|batch| batch[batch_index].as_slice());
                self.generate_ids_with_assistant_model_and_context(
                    prompt,
                    &batch_config,
                    assistant_model,
                    encoder_hidden,
                    encoder_mask,
                )
                .map_err(|error| anyhow!("generating assisted batch item {batch_index}: {error:#}"))
            })
            .collect()
    }

    /// Structured serial batch counterpart of
    /// `generate_batch_ids_with_assistant_model`.
    pub fn generate_batch_output_with_assistant_model(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
    ) -> Result<Vec<VulkanTransformerGenerationOutput>> {
        self.generate_batch_output_with_assistant_model_and_context(
            prompts,
            config,
            assistant_model,
            None,
            None,
        )
    }

    /// Context-aware structured serial batch external-assistant generation.
    pub fn generate_batch_output_with_assistant_model_and_context(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
        encoder_hidden_states: Option<&[Vec<f32>]>,
        encoder_attention_masks: Option<&[Vec<f32>]>,
    ) -> Result<Vec<VulkanTransformerGenerationOutput>> {
        config.validate()?;
        if let Some(encoder_hidden_states) = encoder_hidden_states {
            if encoder_hidden_states.len() != prompts.len() {
                bail!(
                    "batched encoder hidden states contain {} items for {} prompts",
                    encoder_hidden_states.len(),
                    prompts.len()
                );
            }
        } else if encoder_attention_masks.is_some() {
            bail!("batched encoder attention masks were supplied without encoder hidden states");
        }
        if let Some(encoder_attention_masks) = encoder_attention_masks {
            if encoder_attention_masks.len() != prompts.len() {
                bail!(
                    "batched encoder attention masks contain {} items for {} prompts",
                    encoder_attention_masks.len(),
                    prompts.len()
                );
            }
        }

        let generation_started = Instant::now();
        prompts
            .iter()
            .enumerate()
            .map(|(batch_index, prompt)| {
                let mut batch_config = config.clone();
                batch_config
                    .specialize_decoder_start_token_for_batch(batch_index, prompts.len())?;
                batch_config.seed = config.seed.wrapping_add(batch_index as u64);
                batch_config.max_time =
                    generation_remaining_max_time(config.max_time, generation_started);
                let encoder_hidden =
                    encoder_hidden_states.map(|batch| batch[batch_index].as_slice());
                let encoder_mask =
                    encoder_attention_masks.map(|batch| batch[batch_index].as_slice());
                self.generate_output_with_assistant_model_and_context(
                    prompt,
                    &batch_config,
                    assistant_model,
                    encoder_hidden,
                    encoder_mask,
                )
                .map_err(|error| {
                    anyhow!("generating structured assisted batch item {batch_index}: {error:#}")
                })
            })
            .collect()
    }

    /// Generate continuations for a batch of prompts while preserving the
    /// `num_return_sequences` dimension for every batch item.
    ///
    /// The current Vulkan generation executor is optimized around a
    /// single-request graph, so this compatibility API schedules batch items
    /// serially on that graph. Sampling assigns each batch item a disjoint
    /// deterministic seed range so identical prompts do not accidentally
    /// share the same random stream.
    pub fn generate_batch_sequences_ids(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<Vec<Vec<u32>>>> {
        self.generate_batch_sequences_ids_with_context(prompts, config, None, None)
    }

    /// Structured counterpart of `generate_batch_sequences_ids`. Each batch
    /// item receives its own HF-style generation container and the same
    /// deterministic seed partition used by the continuation-only batch API.
    pub fn generate_batch_output(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<VulkanTransformerGenerationOutput>> {
        self.generate_batch_output_with_context(prompts, config, None, None)
    }

    /// Context-aware structured batch generation. Encoder state/mask arrays
    /// follow the prompt batch dimension exactly as in
    /// `generate_batch_sequences_ids_with_context`.
    pub fn generate_batch_output_with_context(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[Vec<f32>]>,
        encoder_attention_masks: Option<&[Vec<f32>]>,
    ) -> Result<Vec<VulkanTransformerGenerationOutput>> {
        config.validate()?;
        if let Some(encoder_hidden_states) = encoder_hidden_states {
            if encoder_hidden_states.len() != prompts.len() {
                bail!(
                    "batched encoder hidden states contain {} items for {} prompts",
                    encoder_hidden_states.len(),
                    prompts.len()
                );
            }
        } else if encoder_attention_masks.is_some() {
            bail!("batched encoder attention masks were supplied without encoder hidden states");
        }
        if let Some(encoder_attention_masks) = encoder_attention_masks {
            if encoder_attention_masks.len() != prompts.len() {
                bail!(
                    "batched encoder attention masks contain {} items for {} prompts",
                    encoder_attention_masks.len(),
                    prompts.len()
                );
            }
        }

        let stream_width = config.num_return_sequences.max(config.num_beams).max(1) as u64;
        let generation_started = Instant::now();
        prompts
            .iter()
            .enumerate()
            .map(|(batch_index, prompt)| {
                let mut batch_config = config.clone();
                batch_config
                    .specialize_decoder_start_token_for_batch(batch_index, prompts.len())?;
                batch_config.seed = config
                    .seed
                    .wrapping_add((batch_index as u64).wrapping_mul(stream_width));
                batch_config.max_time =
                    generation_remaining_max_time(config.max_time, generation_started);
                let encoder_hidden =
                    encoder_hidden_states.map(|batch| batch[batch_index].as_slice());
                let encoder_mask =
                    encoder_attention_masks.map(|batch| batch[batch_index].as_slice());
                self.generate_output_with_context(
                    prompt,
                    &batch_config,
                    encoder_hidden,
                    encoder_mask,
                )
                .map_err(|error| {
                    anyhow!("generating structured batch item {batch_index}: {error:#}")
                })
            })
            .collect()
    }

    /// Batch generation with one fixed encoder context per prompt. The outer
    /// encoder arrays follow the prompt batch dimension; each hidden-state
    /// entry is flattened `[encoder_sequence, encoder_hidden]`, and each mask
    /// entry is `[encoder_sequence]`.
    ///
    /// This keeps the public compatibility batching surface useful for
    /// encoder-decoder models even while the underlying generation graph
    /// remains batch-1. Every prompt/context pair is scheduled serially and
    /// receives the same disjoint deterministic seed range as decoder-only
    /// batched generation.
    pub fn generate_batch_sequences_ids_with_context(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[Vec<f32>]>,
        encoder_attention_masks: Option<&[Vec<f32>]>,
    ) -> Result<Vec<Vec<Vec<u32>>>> {
        config.validate()?;
        if let Some(encoder_hidden_states) = encoder_hidden_states {
            if encoder_hidden_states.len() != prompts.len() {
                bail!(
                    "batched encoder hidden states contain {} items for {} prompts",
                    encoder_hidden_states.len(),
                    prompts.len()
                );
            }
        } else if encoder_attention_masks.is_some() {
            bail!("batched encoder attention masks were supplied without encoder hidden states");
        }
        if let Some(encoder_attention_masks) = encoder_attention_masks {
            if encoder_attention_masks.len() != prompts.len() {
                bail!(
                    "batched encoder attention masks contain {} items for {} prompts",
                    encoder_attention_masks.len(),
                    prompts.len()
                );
            }
        }

        if config.continuous_batching_config.is_some() {
            if encoder_hidden_states.is_some() || encoder_attention_masks.is_some() {
                bail!(
                    "Vulkan paged continuous batching currently supports decoder-only generation without external encoder context"
                );
            }
            return self.generate_batch_sequences_ids_continuous_paged(prompts, config);
        }

        let stream_width = config.num_return_sequences.max(config.num_beams).max(1) as u64;
        let generation_started = Instant::now();
        prompts
            .iter()
            .enumerate()
            .map(|(batch_index, prompt)| {
                let mut batch_config = config.clone();
                batch_config
                    .specialize_decoder_start_token_for_batch(batch_index, prompts.len())?;
                batch_config.seed = config
                    .seed
                    .wrapping_add((batch_index as u64).wrapping_mul(stream_width));
                batch_config.max_time =
                    generation_remaining_max_time(config.max_time, generation_started);
                let encoder_hidden =
                    encoder_hidden_states.map(|batch| batch[batch_index].as_slice());
                let encoder_mask =
                    encoder_attention_masks.map(|batch| batch[batch_index].as_slice());
                self.generate_sequences_ids_with_context(
                    prompt,
                    &batch_config,
                    encoder_hidden,
                    encoder_mask,
                )
                .map_err(|error| anyhow!("generating batch item {batch_index}: {error:#}"))
            })
            .collect()
    }

    fn generate_batch_sequences_ids_continuous_paged(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<Vec<Vec<u32>>>> {
        config.validate_supported_generation_mode()?;
        if !config.uses_paged_kv_cache() {
            bail!("Vulkan continuous batching requires cache_implementation=\"paged\"");
        }
        if !config.use_cache {
            bail!("Vulkan continuous batching requires use_cache=true");
        }
        if config.num_beams != 1 || config.num_return_sequences != 1 {
            bail!(
                "Vulkan paged continuous batching currently requires num_beams=1 and num_return_sequences=1"
            );
        }
        if !matches!(
            config.generation_mode(),
            VulkanTransformerGenerationMode::GreedySearch | VulkanTransformerGenerationMode::Sample
        ) {
            bail!(
                "Vulkan paged continuous batching currently supports greedy or multinomial sampling generation"
            );
        }
        if prompts.is_empty() {
            return Ok(Vec::new());
        }

        let max_active = config.continuous_batching_max_requests(prompts.len())?;
        let stream_width = config.num_return_sequences.max(config.num_beams).max(1) as u64;
        let generation_started = Instant::now();
        let mut prepared = Vec::with_capacity(prompts.len());
        for (batch_index, prompt) in prompts.iter().enumerate() {
            let mut request_config = config.clone();
            request_config.continuous_batching_config = None;
            request_config.specialize_decoder_start_token_for_batch(batch_index, prompts.len())?;
            request_config.seed = config
                .seed
                .wrapping_add((batch_index as u64).wrapping_mul(stream_width));
            // One scheduler clock governs the whole continuously batched call,
            // so retain the caller's original max_time budget here instead of
            // subtracting elapsed time and then measuring from the same start.
            request_config.max_time = config.max_time;
            let prepared_prompt = self.prepare_generation_prompt(prompt, &request_config, None)?;
            self.validate_generation_request(&prepared_prompt, &request_config)
                .with_context(|| format!("validating continuous batch item {batch_index}"))?;
            self.validate_generation_encoder_processor_inputs(&request_config, None)
                .with_context(|| {
                    format!("validating continuous batch item {batch_index} processors")
                })?;
            prepared.push((prepared_prompt, request_config));
        }

        let initial_pages = prepared
            .iter()
            .take(max_active)
            .map(|(prompt, _)| prompt.len().div_ceil(GENERATION_KV_PAGE_TOKENS))
            .sum::<usize>()
            .max(1);
        let shared_arenas = self.generation_shared_paged_kv_arenas(initial_pages)?;
        let mut results = vec![None::<Vec<Vec<u32>>>; prompts.len()];
        let mut active = Vec::<VulkanGenerationContinuousRequest>::with_capacity(max_active);
        let mut next_request = 0usize;

        while next_request < prepared.len() || !active.is_empty() {
            while active.len() < max_active && next_request < prepared.len() {
                let batch_index = next_request;
                let (prompt, request_config) = &prepared[batch_index];
                let requested = request_config.effective_max_new_tokens(prompt.len(), self.seq_len);
                if requested == 0 {
                    results[batch_index] = Some(vec![Vec::new()]);
                    next_request += 1;
                    continue;
                }
                let (logits, cache) = self
                    .generation_prefill_kv_cache_with_policy_and_arenas(
                        prompt,
                        true,
                        Some(&shared_arenas),
                    )
                    .with_context(|| format!("prefilling continuous batch item {batch_index}"))?;
                active.push(VulkanGenerationContinuousRequest {
                    batch_index,
                    config: request_config.clone(),
                    sequence: prompt.clone(),
                    generated: Vec::with_capacity(requested),
                    logits,
                    cache,
                    requested,
                });
                next_request += 1;
            }

            let mut survivors = Vec::with_capacity(active.len());
            for mut request in active.drain(..) {
                let step = request.generated.len();
                let scores = self.generation_processed_non_beam_scores_with_cfg(
                    &request.logits,
                    &request.sequence,
                    &request.config,
                    step,
                    step + 1 == request.requested,
                    None,
                    None,
                )?;
                let next_token = if request.config.do_sample {
                    generation_sample_processed_scores(&scores, request.config.seed, step as u64)?
                } else {
                    generation_argmax(&scores)?
                };
                request.generated.push(next_token);
                request.sequence.push(next_token);
                let finished = step + 1 >= request.requested
                    || request.config.should_stop_sequence(&request.sequence)
                    || generation_max_time_reached(generation_started, &request.config);
                if finished {
                    results[request.batch_index] = Some(vec![request.generated]);
                    // Dropping `request.cache` here immediately decrements the
                    // shared arena refcounts, making its pages available to the
                    // surviving requests before their grouped decode and to the
                    // next waiting request before the following scheduling round.
                    continue;
                }
                survivors.push(request);
            }
            active = survivors;

            if !active.is_empty() {
                let decode_steps = active
                    .iter()
                    .map(|request| {
                        Ok((
                            *request
                                .sequence
                                .last()
                                .context("continuous batch survivor has an empty sequence")?,
                            &request.cache,
                            request.sequence.len() - 1,
                        ))
                    })
                    .collect::<Result<Vec<_>>>()?;
                let next_logits = self
                    .generation_cached_step_logits_continuous_paged(&decode_steps)
                    .with_context(|| {
                        format!(
                            "decoding one continuous paged scheduling round for {} active request(s)",
                            active.len()
                        )
                    })?;
                for (request, logits) in active.iter_mut().zip(next_logits) {
                    request.logits = logits;
                }
            }
        }

        results
            .into_iter()
            .enumerate()
            .map(|(batch_index, result)| {
                result.with_context(|| {
                    format!("continuous batch item {batch_index} completed without a result")
                })
            })
            .collect()
    }

    /// Convenience wrapper for the common encoder-decoder case where every
    /// source example supplies both encoder hidden states and an attention
    /// mask.
    pub fn generate_batch_sequences_ids_with_encoder_hidden_states(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: &[Vec<f32>],
        encoder_attention_masks: &[Vec<f32>],
    ) -> Result<Vec<Vec<Vec<u32>>>> {
        self.generate_batch_sequences_ids_with_context(
            prompts,
            config,
            Some(encoder_hidden_states),
            Some(encoder_attention_masks),
        )
    }

    /// Backward-compatible single-result projection of
    /// `generate_batch_sequences_ids`, analogous to `generate_ids`.
    pub fn generate_batch_ids(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<Vec<u32>>> {
        self.generate_batch_ids_with_context(prompts, config, None, None)
    }

    /// Backward-compatible single-result projection of context-aware batch
    /// generation.
    pub fn generate_batch_ids_with_context(
        &self,
        prompts: &[Vec<u32>],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[Vec<f32>]>,
        encoder_attention_masks: Option<&[Vec<f32>]>,
    ) -> Result<Vec<Vec<u32>>> {
        self.generate_batch_sequences_ids_with_context(
            prompts,
            config,
            encoder_hidden_states,
            encoder_attention_masks,
        )?
        .into_iter()
        .map(|sequences| {
            sequences
                .into_iter()
                .next()
                .context("generation produced no sequences for batch item")
        })
        .collect()
    }

    /// Generation for a decoder with fixed external encoder context.
    pub fn generate_ids_with_encoder_hidden_states(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: &[f32],
        encoder_attention_mask: &[f32],
    ) -> Result<Vec<u32>> {
        self.generate_ids_with_context(
            prompt,
            config,
            Some(encoder_hidden_states),
            Some(encoder_attention_mask),
        )
    }

    /// Encoder-context generation with source ids for encoder-side logits
    /// processors such as `encoder_repetition_penalty` and
    /// `encoder_no_repeat_ngram_size`.
    pub fn generate_ids_with_encoder_input_ids_and_hidden_states(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_input_ids: &[u32],
        encoder_hidden_states: &[f32],
        encoder_attention_mask: &[f32],
    ) -> Result<Vec<u32>> {
        let mut request_config = config.clone();
        request_config.encoder_input_ids = Some(encoder_input_ids.to_vec());
        self.generate_ids_with_context(
            prompt,
            &request_config,
            Some(encoder_hidden_states),
            Some(encoder_attention_mask),
        )
    }

    /// Multi-return counterpart of
    /// `generate_ids_with_encoder_input_ids_and_hidden_states`.
    pub fn generate_sequences_ids_with_encoder_input_ids_and_hidden_states(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_input_ids: &[u32],
        encoder_hidden_states: &[f32],
        encoder_attention_mask: &[f32],
    ) -> Result<Vec<Vec<u32>>> {
        let mut request_config = config.clone();
        request_config.encoder_input_ids = Some(encoder_input_ids.to_vec());
        self.generate_sequences_ids_with_context(
            prompt,
            &request_config,
            Some(encoder_hidden_states),
            Some(encoder_attention_mask),
        )
    }

    /// Fully explicit generation surface. External encoder hidden states may
    /// be supplied without an encoder mask, matching HF's all-visible default.
    pub fn generate_ids_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<u32>> {
        let sequences = self.generate_sequences_ids_with_context(
            prompt,
            config,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        sequences
            .into_iter()
            .next()
            .context("generation produced no sequences")
    }

    pub fn generate_sequences_ids_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<Vec<u32>>> {
        config.validate()?;
        let prepared_prompt =
            self.prepare_generation_prompt(prompt, config, encoder_hidden_states)?;
        self.validate_generation_request(&prepared_prompt, config)?;
        self.validate_generation_encoder_processor_inputs(config, encoder_hidden_states)?;
        if config.num_beams > 1 {
            self.generate_beam_sequences_with_context(
                &prepared_prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
            )
        } else {
            let mut sequences = Vec::with_capacity(config.num_return_sequences);
            let generation_started = Instant::now();
            for sequence_index in 0..config.num_return_sequences {
                let mut sequence_config = config.clone();
                sequence_config.num_return_sequences = 1;
                // Keep stream zero byte-for-byte compatible with the existing
                // deterministic path while assigning each additional sampled
                // return sequence an independent Philox key.
                sequence_config.seed = config.seed.wrapping_add(sequence_index as u64);
                sequence_config.max_time =
                    generation_remaining_max_time(config.max_time, generation_started);
                sequences.push(self.generate_single_beam_ids_with_context(
                    &prepared_prompt,
                    &sequence_config,
                    encoder_hidden_states,
                    encoder_attention_mask,
                    |_| Ok(()),
                )?);
            }
            Ok(sequences)
        }
    }

    /// Stream each committed token to `on_token` while returning the same
    /// generated token vector as `generate_ids`. Streaming is supported for
    /// greedy and sampling modes; beam search cannot expose stable token
    /// commitments until hypothesis selection has completed.
    pub fn generate_ids_streaming<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        on_token: F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        self.generate_ids_streaming_with_context(prompt, config, None, None, on_token)
    }

    /// Context-aware single-result streaming generation. This is the streaming
    /// counterpart of `generate_ids_with_context` and permits decoder graphs
    /// with external encoder hidden states without changing the legacy API.
    pub fn generate_ids_streaming_with_context<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        mut on_token: F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        config.validate()?;
        let prepared_prompt =
            self.prepare_generation_prompt(prompt, config, encoder_hidden_states)?;
        self.validate_generation_request(&prepared_prompt, config)?;
        self.validate_generation_encoder_processor_inputs(config, encoder_hidden_states)?;
        if config.num_beams != 1 {
            bail!("streaming generation currently requires num_beams=1");
        }
        if config.num_return_sequences != 1 {
            bail!(
                "generate_ids_streaming requires num_return_sequences=1; use generate_sequences_ids_streaming for multiple sampled sequences"
            );
        }
        self.generate_single_beam_ids_with_context(
            &prepared_prompt,
            config,
            encoder_hidden_states,
            encoder_attention_mask,
            &mut on_token,
        )
    }

    /// Streaming generation for a decoder with fixed external encoder context.
    pub fn generate_ids_streaming_with_encoder_hidden_states<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: &[f32],
        encoder_attention_mask: &[f32],
        on_token: F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        self.generate_ids_streaming_with_context(
            prompt,
            config,
            Some(encoder_hidden_states),
            Some(encoder_attention_mask),
            on_token,
        )
    }

    /// Stream sampled/greedy generation for every requested return sequence.
    /// The callback receives `(sequence_index, token_id)`, allowing callers to
    /// maintain one streamer state per expanded HF-style return sequence.
    /// Beam streaming remains unsupported, matching the current Transformers
    /// restriction that streamers cannot be used with beam search.
    pub fn generate_sequences_ids_streaming<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        on_token: F,
    ) -> Result<Vec<Vec<u32>>>
    where
        F: FnMut(usize, u32) -> Result<()>,
    {
        self.generate_sequences_ids_streaming_with_context(prompt, config, None, None, on_token)
    }

    /// Context-aware multi-return streaming generation. The encoder context is
    /// shared by all expanded return sequences for the source prompt, matching
    /// Hugging Face's expansion semantics for encoder outputs.
    pub fn generate_sequences_ids_streaming_with_context<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        mut on_token: F,
    ) -> Result<Vec<Vec<u32>>>
    where
        F: FnMut(usize, u32) -> Result<()>,
    {
        config.validate()?;
        let prepared_prompt =
            self.prepare_generation_prompt(prompt, config, encoder_hidden_states)?;
        self.validate_generation_request(&prepared_prompt, config)?;
        self.validate_generation_encoder_processor_inputs(config, encoder_hidden_states)?;
        if config.num_beams != 1 {
            bail!("streaming generation currently requires num_beams=1");
        }

        let mut sequences = Vec::with_capacity(config.num_return_sequences);
        let generation_started = Instant::now();
        for sequence_index in 0..config.num_return_sequences {
            let mut sequence_config = config.clone();
            sequence_config.num_return_sequences = 1;
            sequence_config.seed = config.seed.wrapping_add(sequence_index as u64);
            sequence_config.max_time =
                generation_remaining_max_time(config.max_time, generation_started);
            sequences.push(self.generate_single_beam_ids_with_context(
                &prepared_prompt,
                &sequence_config,
                encoder_hidden_states,
                encoder_attention_mask,
                |token| on_token(sequence_index, token),
            )?);
        }
        Ok(sequences)
    }

    /// Multi-return streaming convenience wrapper for a decoder with fixed
    /// external encoder context.
    pub fn generate_sequences_ids_streaming_with_encoder_hidden_states<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: &[f32],
        encoder_attention_mask: &[f32],
        on_token: F,
    ) -> Result<Vec<Vec<u32>>>
    where
        F: FnMut(usize, u32) -> Result<()>,
    {
        self.generate_sequences_ids_streaming_with_context(
            prompt,
            config,
            Some(encoder_hidden_states),
            Some(encoder_attention_mask),
            on_token,
        )
    }

    fn prepare_tokenizer_aware_generation(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        tokenizer: &Tokenizer,
        encoder_hidden_states: Option<&[f32]>,
    ) -> Result<(Vec<u32>, VulkanTransformerGenerationConfig)> {
        let mut prepared_config = config.clone();
        prepared_config.prepare_stop_strings(tokenizer)?;
        let mut prepared_prompt =
            self.prepare_generation_prompt(prompt, &prepared_config, encoder_hidden_states)?;
        if prepared_config.token_healing {
            prepared_prompt =
                self.heal_prompt_tokens(&prepared_prompt, tokenizer, &prepared_config)?;
            // Healing is a pre-generation transform. Clear the request flag so
            // the ordinary executor does not reject an operation already
            // completed by this tokenizer-aware preparation path.
            prepared_config.token_healing = false;
        }
        Ok((prepared_prompt, prepared_config))
    }

    fn heal_prompt_tokens(
        &self,
        prompt: &[u32],
        tokenizer: &Tokenizer,
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<u32>> {
        if prompt.is_empty() {
            return Ok(Vec::new());
        }

        // HF strips decoded prompt whitespace and re-tokenizes before healing.
        let decoded = tokenizer
            .decode(prompt, true)
            .map_err(|error| anyhow!("decoding prompt for token healing: {error}"))?;
        let encoding = tokenizer
            .encode(decoded.trim(), true)
            .map_err(|error| anyhow!("re-tokenizing prompt for token healing: {error}"))?;
        let mut input_ids = encoding.get_ids().to_vec();
        if input_ids.is_empty() {
            return Ok(input_ids);
        }

        let pad_token_id = config.pad_token_id.context(
            "token_healing requires pad_token_id in the generation/model special-token configuration",
        )?;
        if let Some(bos_token_id) = config.bos_token_id {
            for token in &mut input_ids {
                if *token == bos_token_id {
                    *token = pad_token_id;
                }
            }
        }

        let tail_id = *input_ids
            .last()
            .context("token healing re-tokenization produced an empty prompt")?;
        let tail_text = tokenizer
            .decode(&[tail_id], false)
            .map_err(|error| anyhow!("decoding token-healing tail token: {error}"))?;
        let space_token = tokenizer
            .encode(" ", false)
            .ok()
            .and_then(|encoding| encoding.get_tokens().first().cloned());
        let tail_token = space_token
            .as_deref()
            .filter(|space_token| !space_token.is_empty())
            .map(|space_token| tail_text.replace(' ', space_token))
            .unwrap_or(tail_text);

        let vocab = tokenizer.get_vocab(true);
        let mut alternatives = vocab
            .iter()
            .filter_map(|(token, &token_id)| token.starts_with(&tail_token).then_some(token_id))
            .collect::<Vec<_>>();
        alternatives.sort_unstable();
        alternatives.dedup();
        if alternatives.len() <= 1 {
            return Ok(input_ids);
        }

        let mut sequence_bias = alternatives
            .into_iter()
            .map(|token_id| (vec![token_id], 10.0f32))
            .collect::<Vec<_>>();
        if let Some((_, bias)) = sequence_bias
            .iter_mut()
            .find(|(token_ids, _)| token_ids.as_slice() == [tail_id])
        {
            // HF slightly favors the original token to avoid overly aggressive
            // replacements such as a short prefix always growing longer.
            *bias += 1.0;
        }

        let mut trimmed_ids = input_ids[..input_ids.len() - 1].to_vec();
        if trimmed_ids.is_empty() {
            return Ok(input_ids);
        }
        let non_pad_tokens = input_ids
            .iter()
            .filter(|&&token| token != pad_token_id)
            .count();
        if non_pad_tokens == 1 {
            let bos_token_id = config
                .bos_token_id
                .context("token_healing a single non-padding token requires bos_token_id")?;
            if let Some(last) = trimmed_ids.last_mut() {
                *last = bos_token_id;
            }
        }

        let healing_config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(1),
            max_length: None,
            sequence_bias,
            pad_token_id: Some(pad_token_id),
            token_healing: false,
            ..VulkanTransformerGenerationConfig::default()
        };
        let replacement = self.generate_ids(&trimmed_ids, &healing_config)?;
        let replacement = replacement
            .first()
            .copied()
            .context("token healing failed to generate a replacement tail token")?;
        trimmed_ids.push(replacement);
        Ok(trimmed_ids)
    }

    /// Prepare the token prefix that Hugging Face's `generate()` would feed
    /// into the autoregressive decoder. This intentionally happens at the
    /// public generation boundary so every decoding mode, structured-output
    /// path, streamer, and cache/reference executor observes the same prefix.
    fn prepare_generation_prompt(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
    ) -> Result<Vec<u32>> {
        let encoder_decoder_generation = encoder_hidden_states.is_some()
            && (self.config.architecture.uses_encoder_decoder_generation()
                || config.decoder_start_token_id.is_some());

        if encoder_decoder_generation {
            let decoder_start = match config.decoder_start_token_id.as_ref() {
                Some(decoder_start) => decoder_start.for_single_request()?,
                None => config.bos_token_id.context(
                    "decoder_start_token_id or bos_token_id has to be defined for encoder-decoder generation",
                )?,
            };
            if prompt.first().copied() == Some(decoder_start) {
                return Ok(prompt.to_vec());
            }
            let mut prepared = Vec::with_capacity(prompt.len().saturating_add(1));
            prepared.push(decoder_start);
            prepared.extend_from_slice(prompt);
            return Ok(prepared);
        }

        // Decoder-only HF generation uses BOS when no input ids were supplied.
        // Treat an empty slice as that omitted-input case while preserving the
        // existing explicit-prompt behavior for every non-empty caller.
        if prompt.is_empty() {
            if let Some(bos_token_id) = config.bos_token_id {
                return Ok(vec![bos_token_id]);
            }
        }
        Ok(prompt.to_vec())
    }

    fn validate_generation_request(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<()> {
        config.validate_supported_generation_mode()?;
        if !self.causal_attention {
            bail!(
                "autoregressive generation is unavailable for bidirectional {:?} Transformer architecture",
                self.config.architecture
            );
        }
        if self.batch_size != 1 {
            bail!("generation currently requires a batch_size=1 Transformer graph");
        }
        if prompt.is_empty() {
            bail!("generation prompt must contain at least one token");
        }
        if prompt.len() > self.seq_len {
            bail!(
                "generation prompt has {} tokens but graph context is {}",
                prompt.len(),
                self.seq_len
            );
        }
        if config.use_cache && config.uses_static_cache_policy() {
            if let Some(max_cache_len) = config.max_cache_len {
                let requested_len = prompt
                    .len()
                    .saturating_add(config.effective_max_new_tokens(prompt.len(), self.seq_len));
                if requested_len > max_cache_len {
                    bail!(
                        "static generation max_cache_len {max_cache_len} is smaller than requested sequence length {requested_len}"
                    );
                }
            }
        }
        if config.uses_paged_kv_cache() {
            if !self.supports_generation_kv_cache() {
                bail!(
                    "cache_implementation=\"paged\" is unavailable for the {:?} generation topology; use the default/contiguous cache for this model",
                    self.config.architecture
                );
            }
            if !self.layers.iter().any(|layer| {
                layer.deepseek_v4_attention.is_none() && layer.qwen_gated_delta.is_none()
            }) {
                bail!(
                    "cache_implementation=\"paged\" has no paged K/V attention layers in the {:?} generation graph; use the model's native cache topology instead",
                    self.config.architecture
                );
            }
        }
        if let Some(assistant_early_exit) = config.assistant_early_exit {
            if assistant_early_exit == 0 || assistant_early_exit > self.layers.len() {
                bail!(
                    "generation assistant_early_exit {assistant_early_exit} must be in 1..={} for this Transformer graph",
                    self.layers.len()
                );
            }
        }
        for &token in prompt {
            if token as usize >= self.config.vocab_size {
                bail!(
                    "generation prompt token {token} is outside vocabulary size {}",
                    self.config.vocab_size
                );
            }
        }
        if let Some(encoder_input_ids) = config.encoder_input_ids.as_deref() {
            for &token in encoder_input_ids {
                if token as usize >= self.config.vocab_size {
                    bail!(
                        "generation encoder input token {token} is outside vocabulary size {}",
                        self.config.vocab_size
                    );
                }
            }
        }
        for &eos in &config.eos_token_ids {
            if eos as usize >= self.config.vocab_size {
                bail!(
                    "eos token {eos} is outside vocabulary size {}",
                    self.config.vocab_size
                );
            }
        }
        if config.generation_mode() == VulkanTransformerGenerationMode::ContrastiveSearch
            && config.top_k > self.config.vocab_size
        {
            bail!(
                "contrastive generation top_k {} exceeds vocabulary size {}",
                config.top_k,
                self.config.vocab_size
            );
        }
        for (field, tokens) in [
            ("suppress_tokens", config.suppress_tokens.as_slice()),
            (
                "begin_suppress_tokens",
                config.begin_suppress_tokens.as_slice(),
            ),
            (
                "forced_eos_token_id",
                config.forced_eos_token_ids.as_slice(),
            ),
        ] {
            for &token in tokens {
                if token as usize >= self.config.vocab_size {
                    bail!(
                        "generation {field} token {token} is outside vocabulary size {}",
                        self.config.vocab_size
                    );
                }
            }
        }
        for (field, token) in [
            ("pad_token_id", config.pad_token_id),
            ("bos_token_id", config.bos_token_id),
        ] {
            if let Some(token) = token {
                if token as usize >= self.config.vocab_size {
                    bail!(
                        "generation {field} {token} is outside vocabulary size {}",
                        self.config.vocab_size
                    );
                }
            }
        }
        if let Some(decoder_start_token_id) = config.decoder_start_token_id.as_ref() {
            for &token in decoder_start_token_id.ids() {
                if token as usize >= self.config.vocab_size {
                    bail!(
                        "generation decoder_start_token_id {token} is outside vocabulary size {}",
                        self.config.vocab_size
                    );
                }
            }
        }
        if let Some(token) = config.forced_bos_token_id {
            if token as usize >= self.config.vocab_size {
                bail!(
                    "generation forced_bos_token_id {token} is outside vocabulary size {}",
                    self.config.vocab_size
                );
            }
        }
        for (sequence_index, sequence) in config.bad_words_ids.iter().enumerate() {
            for &token in sequence {
                if token as usize >= self.config.vocab_size {
                    bail!(
                        "generation bad_words_ids[{sequence_index}] token {token} is outside vocabulary size {}",
                        self.config.vocab_size
                    );
                }
            }
        }
        Ok(())
    }

    fn validate_external_assistant_generation_request(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        assistant_model: &VulkanTransformer,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<()> {
        if !matches!(
            config.generation_mode(),
            VulkanTransformerGenerationMode::GreedySearch | VulkanTransformerGenerationMode::Sample
        ) {
            bail!("external assistant-model generation requires a greedy or sampling base mode");
        }
        if config.num_return_sequences != 1 {
            bail!(
                "num_return_sequences has to be 1 when doing assisted generate, but is {}",
                config.num_return_sequences
            );
        }
        if !config.use_cache {
            bail!("assisted generate requires use_cache=true");
        }
        if self.config.vocab_size != assistant_model.config.vocab_size {
            bail!(
                "same-tokenizer assisted generation requires matching target/assistant vocab sizes; target={} assistant={}",
                self.config.vocab_size,
                assistant_model.config.vocab_size
            );
        }
        if !assistant_model.causal_attention {
            bail!("assistant model must support causal autoregressive generation");
        }
        if assistant_model.batch_size != 1 {
            bail!("assistant model generation currently requires batch_size=1");
        }
        if prompt.len() > assistant_model.seq_len {
            bail!(
                "generation prompt has {} tokens but assistant graph context is {}",
                prompt.len(),
                assistant_model.seq_len
            );
        }
        if assistant_model.encoder_seq_len.is_some() && encoder_hidden_states.is_none() {
            bail!("cross-attention assistant model requires encoder hidden states");
        }
        for &token in prompt {
            if token as usize >= assistant_model.config.vocab_size {
                bail!(
                    "generation prompt token {token} is outside assistant vocabulary size {}",
                    assistant_model.config.vocab_size
                );
            }
        }
        assistant_model.validate_encoder_context(encoder_hidden_states, encoder_attention_mask)?;
        Ok(())
    }

    fn validate_generation_encoder_processor_inputs(
        &self,
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
    ) -> Result<()> {
        let uses_encoder_processors =
            config.encoder_repetition_penalty != 1.0 || config.encoder_no_repeat_ngram_size != 0;
        if uses_encoder_processors
            && encoder_hidden_states.is_some()
            && config.encoder_input_ids.is_none()
        {
            bail!(
                "encoder-side generation processors with external encoder hidden states require encoder input ids; use an encoder-input-aware generation wrapper"
            );
        }
        Ok(())
    }

    fn generation_last_logits(
        &self,
        prefix: &[u32],
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<f32>> {
        let attention_mask = vec![1.0f32; prefix.len()];
        self.generation_last_logits_with_attention_mask(
            prefix,
            &attention_mask,
            encoder_hidden_states,
            encoder_attention_mask,
        )
    }

    fn generation_last_logits_with_attention_mask(
        &self,
        prefix: &[u32],
        prefix_attention_mask: &[f32],
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<f32>> {
        if prefix.is_empty() || prefix.len() > self.seq_len {
            bail!(
                "generation prefix length {} is outside graph context",
                prefix.len()
            );
        }
        if prefix_attention_mask.len() != prefix.len() {
            bail!(
                "generation attention mask length {} does not match prefix length {}",
                prefix_attention_mask.len(),
                prefix.len()
            );
        }
        let mut tokens = vec![0u32; self.seq_len];
        tokens[..prefix.len()].copy_from_slice(prefix);
        let mut attention_mask = vec![0.0f32; self.seq_len];
        attention_mask[..prefix.len()].copy_from_slice(prefix_attention_mask);
        let logits = self.forward_logits_with_context(
            &tokens,
            None,
            &attention_mask,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        let row_start = (prefix.len() - 1) * self.config.vocab_size;
        Ok(logits[row_start..row_start + self.config.vocab_size].to_vec())
    }

    fn generation_classifier_free_guidance_unconditional_logits(
        &self,
        history: &[u32],
        config: &VulkanTransformerGenerationConfig,
        step: usize,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<f32>> {
        let prompt_len = history
            .len()
            .checked_sub(step)
            .context("CFG generation step exceeds sequence history")?;
        if prompt_len == 0 {
            bail!("CFG generation requires a non-empty conditional prompt");
        }

        let mut unconditional_ids = config
            .negative_prompt_ids
            .clone()
            .unwrap_or_else(|| vec![history[prompt_len - 1]]);
        let unconditional_prompt_len = unconditional_ids.len();
        unconditional_ids.extend_from_slice(&history[prompt_len..]);
        if unconditional_ids.len() > self.seq_len {
            bail!(
                "CFG unconditional prefix length {} exceeds graph context {}",
                unconditional_ids.len(),
                self.seq_len
            );
        }

        let mut unconditional_attention_mask = config
            .negative_prompt_attention_mask
            .clone()
            .unwrap_or_else(|| vec![1.0; unconditional_prompt_len]);
        unconditional_attention_mask.resize(unconditional_ids.len(), 1.0);
        self.generation_last_logits_with_attention_mask(
            &unconditional_ids,
            &unconditional_attention_mask,
            encoder_hidden_states,
            encoder_attention_mask,
        )
    }

    fn generation_processed_non_beam_scores_with_cfg(
        &self,
        logits: &[f32],
        history: &[u32],
        config: &VulkanTransformerGenerationConfig,
        step: usize,
        is_last_step: bool,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<f32>> {
        let Some(guidance_scale) = config.guidance_scale.filter(|scale| *scale != 1.0) else {
            return generation_processed_non_beam_scores(
                logits,
                history,
                config,
                step,
                is_last_step,
            );
        };
        let unconditional_logits = self.generation_classifier_free_guidance_unconditional_logits(
            history,
            config,
            step,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        let guided_scores = generation_classifier_free_guidance_scores(
            logits,
            &unconditional_logits,
            guidance_scale,
        )?;
        generation_processed_non_beam_scores_from_initial_scores(
            guided_scores,
            history,
            config,
            step,
            is_last_step,
        )
    }

    fn generation_beam_processed_log_probs_with_cfg(
        &self,
        logits: &[f32],
        history: &[u32],
        config: &VulkanTransformerGenerationConfig,
        step: usize,
        is_last_step: bool,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<f32>> {
        let Some(guidance_scale) = config.guidance_scale.filter(|scale| *scale != 1.0) else {
            return generation_beam_processed_log_probs(
                logits,
                history,
                config,
                step,
                is_last_step,
            );
        };
        let unconditional_logits = self.generation_classifier_free_guidance_unconditional_logits(
            history,
            config,
            step,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        let guided_log_probs = generation_classifier_free_guidance_scores(
            logits,
            &unconditional_logits,
            guidance_scale,
        )?;
        generation_beam_processed_log_probs_from_log_probs(
            guided_log_probs,
            history,
            config,
            step,
            is_last_step,
        )
    }

    fn generation_last_logits_with_layer_count(
        &self,
        prefix: &[u32],
        active_layer_count: usize,
    ) -> Result<Vec<f32>> {
        self.generation_last_logits_with_layer_count_and_context(
            prefix,
            active_layer_count,
            None,
            None,
        )
    }

    fn generation_last_logits_with_layer_count_and_context(
        &self,
        prefix: &[u32],
        active_layer_count: usize,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<f32>> {
        if prefix.is_empty() || prefix.len() > self.seq_len {
            bail!(
                "generation prefix length {} is outside graph context",
                prefix.len()
            );
        }
        let mut tokens = vec![0u32; self.seq_len];
        tokens[..prefix.len()].copy_from_slice(prefix);
        let mut attention_mask = vec![0.0f32; self.seq_len];
        attention_mask[..prefix.len()].fill(1.0);
        let (logits, _) = self.forward_logits_with_context_and_roc_bert_ids_and_layer_count(
            &tokens,
            None,
            None,
            None,
            None,
            &attention_mask,
            encoder_hidden_states,
            encoder_attention_mask,
            active_layer_count,
        )?;
        let row_start = (prefix.len() - 1) * self.config.vocab_size;
        Ok(logits[row_start..row_start + self.config.vocab_size].to_vec())
    }

    /// Read the hidden-state tensors left resident by the immediately preceding
    /// full-prefix generation forward. This is readback only: the model math
    /// remains exactly the same Vulkan execution used for logits.
    fn generation_hidden_states_for_last_forward(
        &self,
        prefix_len: usize,
        use_cache: bool,
        generation_step: usize,
    ) -> Result<Vec<VulkanTransformerGenerationHiddenState>> {
        if prefix_len == 0 || prefix_len > self.seq_len {
            bail!("generation hidden-state prefix length {prefix_len} is outside graph context");
        }

        // Match HF generation's observable shape contract: the prefill call
        // exposes the complete prompt, then cached decoding exposes only the
        // newly evaluated row. The Vulkan executor may internally rerun the
        // prefix for correctness, but the structured result should not leak
        // that implementation detail.
        let output_rows = if use_cache && generation_step > 0 {
            1
        } else {
            prefix_len
        };
        let first_output_row = prefix_len - output_rows;

        let read_state = |buffer: &GpuBuffer,
                          hidden_size: usize|
         -> Result<VulkanTransformerGenerationHiddenState> {
            let active_values = buffer.read_f32(prefix_len * hidden_size)?;
            let start = first_output_row * hidden_size;
            let end = start + output_rows * hidden_size;
            Ok(VulkanTransformerGenerationHiddenState {
                rows: output_rows,
                hidden_size,
                values: active_values[start..end].to_vec(),
            })
        };

        let mut states = Vec::with_capacity(self.layers.len() + 1);
        let embedding_state = if self.config.architecture == VulkanTransformerArchitecture::Esm {
            &self.input_hidden_dropout
        } else {
            &self.input_hidden
        };
        states.push(read_state(embedding_state, self.config.hidden_size)?);

        // HF exposes the input to each block and then the final normalized
        // decoder state. Layer i's output is therefore the state before layer
        // i+1; the raw last-layer output is replaced by the terminal
        // norm/projection state in the final slot.
        for layer in self.layers.iter().take(self.layers.len().saturating_sub(1)) {
            states.push(read_state(&layer.tape.output, self.config.hidden_size)?);
        }

        let (final_state, final_width) = if self.output_project.is_some() {
            (
                &self.output_project_output,
                self.config.effective_embedding_size(),
            )
        } else if self.config.uses_final_norm() {
            (&self.final_norm_output, self.config.hidden_size)
        } else {
            (
                &self
                    .layers
                    .last()
                    .context("Transformer has no layers")?
                    .tape
                    .output,
                self.config.hidden_size,
            )
        };
        states.push(read_state(final_state, final_width)?);
        Ok(states)
    }

    /// Reconstruct the decoder hidden-state trace for a finalized generated
    /// sequence. This is intentionally a read-only replay through the same
    /// Vulkan full-prefix forward used as the numerical reference path for
    /// generation. It is used for modes whose search algorithm does not keep
    /// every intermediate activation resident until final hypotheses are
    /// known (beam variants, contrastive search, and assisted generation).
    fn generation_hidden_state_trace_for_sequence(
        &self,
        sequence: &[u32],
        prompt_length: usize,
        use_cache: bool,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<Vec<VulkanTransformerGenerationHiddenState>>> {
        if prompt_length == 0 || prompt_length > sequence.len() {
            bail!(
                "generation hidden-state trace prompt length {prompt_length} is invalid for sequence length {}",
                sequence.len()
            );
        }
        let generated = sequence.len() - prompt_length;
        let mut trace = Vec::with_capacity(generated);
        for generation_step in 0..generated {
            let prefix_len = prompt_length + generation_step;
            self.generation_last_logits(
                &sequence[..prefix_len],
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            trace.push(self.generation_hidden_states_for_last_forward(
                prefix_len,
                use_cache,
                generation_step,
            )?);
        }
        Ok(trace)
    }

    /// Reconstruct self- and cross-attention probabilities from the exact Q/K
    /// tensors consumed by the immediately preceding full-prefix Vulkan
    /// forward. This intentionally mirrors `transformer_attention_forward`
    /// on the host so requesting diagnostic tensors does not alter the model's
    /// execution graph or token-selection numerics.
    fn generation_attentions_for_last_forward(
        &self,
        prefix_len: usize,
        use_cache: bool,
        generation_step: usize,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<(
        Vec<VulkanTransformerGenerationAttention>,
        Vec<VulkanTransformerGenerationAttention>,
    )> {
        if prefix_len == 0 || prefix_len > self.seq_len {
            bail!("generation attention prefix length {prefix_len} is outside graph context");
        }
        let output_rows = if use_cache && generation_step > 0 {
            1
        } else {
            prefix_len
        };
        let first_output_query = prefix_len - output_rows;
        let query_hidden = self.config.query_hidden_size();
        let key_hidden = self.config.key_value_hidden_size();
        let self_key_mask = vec![1.0f32; prefix_len];
        let mut self_attentions = Vec::with_capacity(self.layers.len());
        let mut cross_attentions = Vec::new();

        for (layer_index, layer) in self.layers.iter().enumerate() {
            let (q_buffer, k_buffer) = layer.generation_attention_query_key_buffers(&self.config);
            let q_values = q_buffer.read_f32(prefix_len * query_hidden)?;
            let k_values = k_buffer.read_f32(prefix_len * key_hidden)?;
            let relative_bias = self
                .relative_attention_bias_for_layer(layer_index)
                .map(|parameter| {
                    parameter
                        .values
                        .read_f32(self.relative_attention_num_buckets * self.config.num_heads)
                })
                .transpose()?;
            let sink_values = if layer.has_attention_sink {
                Some(
                    layer
                        .attention_sink
                        .values
                        .read_f32(self.config.num_heads)?,
                )
            } else {
                None
            };
            self_attentions.push(generation_attention_probabilities_from_qk(
                &q_values,
                &k_values,
                prefix_len,
                first_output_query,
                prefix_len,
                self.config.num_heads,
                self.config.num_key_value_heads,
                self.config.head_dim,
                self.config.attention_scale_for_layer(layer_index),
                self.config.attention_logit_softcapping.unwrap_or(0.0),
                self.causal_attention,
                layer.attention_window,
                self.config.alibi_mode(),
                self.config.alibi_bias_max,
                relative_bias.as_deref(),
                self.relative_attention_num_buckets,
                self.relative_attention_max_distance,
                sink_values.as_deref(),
                &self_key_mask,
            )?);

            if let (Some(cross_attention), Some(encoder_attention_mask)) =
                (layer.cross_attention.as_ref(), encoder_attention_mask)
            {
                let encoder_seq_len = self.encoder_seq_len.context(
                    "cross-attention generation graph is missing encoder sequence length",
                )?;
                if encoder_attention_mask.len() != encoder_seq_len {
                    bail!(
                        "generation encoder attention mask has {} values, expected {encoder_seq_len}",
                        encoder_attention_mask.len()
                    );
                }
                let attention_hidden = cross_attention.num_heads * cross_attention.head_dim;
                let q_buffer = if cross_attention.query_scale != 1.0 {
                    &cross_attention.tape.q_scaled
                } else {
                    &cross_attention.tape.q
                };
                let q_values = q_buffer.read_f32(prefix_len * attention_hidden)?;
                let k_values = cross_attention
                    .tape
                    .k
                    .read_f32(encoder_seq_len * attention_hidden)?;
                cross_attentions.push(generation_attention_probabilities_from_qk(
                    &q_values,
                    &k_values,
                    prefix_len,
                    first_output_query,
                    encoder_seq_len,
                    cross_attention.num_heads,
                    cross_attention.num_heads,
                    cross_attention.head_dim,
                    cross_attention.attention_scale,
                    0.0,
                    false,
                    0,
                    0,
                    0.0,
                    None,
                    0,
                    0,
                    None,
                    encoder_attention_mask,
                )?);
            }
        }
        Ok((self_attentions, cross_attentions))
    }

    fn generation_attention_trace_for_sequence(
        &self,
        sequence: &[u32],
        prompt_length: usize,
        use_cache: bool,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<(
        Vec<Vec<VulkanTransformerGenerationAttention>>,
        Option<Vec<Vec<VulkanTransformerGenerationAttention>>>,
    )> {
        if prompt_length == 0 || prompt_length > sequence.len() {
            bail!(
                "generation attention trace prompt length {prompt_length} is invalid for sequence length {}",
                sequence.len()
            );
        }
        let generated = sequence.len() - prompt_length;
        let has_cross_attention = encoder_hidden_states.is_some()
            && self
                .layers
                .iter()
                .any(|layer| layer.cross_attention.is_some());
        let mut self_trace = Vec::with_capacity(generated);
        let mut cross_trace = has_cross_attention.then(|| Vec::with_capacity(generated));
        for generation_step in 0..generated {
            let prefix_len = prompt_length + generation_step;
            self.generation_last_logits(
                &sequence[..prefix_len],
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            let (self_attentions, cross_attentions) = self.generation_attentions_for_last_forward(
                prefix_len,
                use_cache,
                generation_step,
                encoder_attention_mask,
            )?;
            self_trace.push(self_attentions);
            if let Some(trace) = cross_trace.as_mut() {
                trace.push(cross_attentions);
            }
        }
        Ok((self_trace, cross_trace))
    }

    /// Run one full-prefix target forward for an assisted-generation draft and
    /// return the logits that predict every draft token plus the target model's
    /// correction/bonus token. With an empty draft this is the ordinary next
    /// token row.
    fn generation_assisted_target_logits(
        &self,
        history: &[u32],
        draft: &[u32],
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<Vec<f32>>> {
        if history.is_empty() {
            bail!("assisted generation requires a non-empty history");
        }
        if history.len() + draft.len() > self.seq_len {
            bail!(
                "assisted speculative prefix has {} tokens but graph context is {}",
                history.len() + draft.len(),
                self.seq_len
            );
        }
        if draft.is_empty() {
            return Ok(vec![self.generation_last_logits(
                history,
                encoder_hidden_states,
                encoder_attention_mask,
            )?]);
        }

        let mut speculative = history.to_vec();
        speculative.extend_from_slice(draft);
        let mut tokens = vec![0u32; self.seq_len];
        tokens[..speculative.len()].copy_from_slice(&speculative);
        let mut attention_mask = vec![0.0f32; self.seq_len];
        attention_mask[..speculative.len()].fill(1.0);
        let logits = self.forward_logits_with_context(
            &tokens,
            None,
            &attention_mask,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;

        let first_row = history.len() - 1;
        let last_row = speculative.len() - 1;
        (first_row..=last_row)
            .map(|row| {
                let start = row * self.config.vocab_size;
                Ok(logits[start..start + self.config.vocab_size].to_vec())
            })
            .collect()
    }

    fn generation_last_logits_and_decoder_hidden(
        &self,
        prefix: &[u32],
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<(Vec<f32>, Vec<f32>, usize)> {
        if prefix.is_empty() || prefix.len() > self.seq_len {
            bail!(
                "generation prefix length {} is outside graph context",
                prefix.len()
            );
        }
        let mut tokens = vec![0u32; self.seq_len];
        tokens[..prefix.len()].copy_from_slice(prefix);
        let mut attention_mask = vec![0.0f32; self.seq_len];
        attention_mask[..prefix.len()].fill(1.0);
        let (logits, hidden) = self.forward_logits_and_last_hidden_state_with_context(
            &tokens,
            None,
            &attention_mask,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        let hidden_size = if self.output_project.is_some() {
            self.config.effective_embedding_size()
        } else {
            self.config.hidden_size
        };
        let logits_row = (prefix.len() - 1) * self.config.vocab_size;
        Ok((
            logits[logits_row..logits_row + self.config.vocab_size].to_vec(),
            hidden[..prefix.len() * hidden_size].to_vec(),
            hidden_size,
        ))
    }

    fn supports_generation_kv_cache(&self) -> bool {
        self.config.architecture.supports_generation_kv_cache()
            && self.batch_size == 1
            && self.token_type_embedding.is_none()
            && self.auxiliary_embedding.is_none()
            && self.roc_bert_embedding_frontend.is_none()
            && self.embedding_norm.is_none()
            && self.embedding_project.is_none()
            && self.output_project.is_none()
            && self.prediction_head.is_none()
            && self
                .layers
                .iter()
                .all(|layer| layer.cross_attention.is_none())
    }

    fn generation_prefill_kv_cache(
        &self,
        prefix: &[u32],
    ) -> Result<(Vec<f32>, VulkanGenerationKvCache)> {
        self.generation_prefill_kv_cache_with_policy(prefix, false)
    }

    fn generation_prefill_kv_cache_with_policy(
        &self,
        prefix: &[u32],
        use_paged_kv: bool,
    ) -> Result<(Vec<f32>, VulkanGenerationKvCache)> {
        self.generation_prefill_kv_cache_with_policy_and_arenas(prefix, use_paged_kv, None)
    }

    fn generation_shared_paged_kv_arenas(
        &self,
        initial_pages: usize,
    ) -> Result<Vec<Option<Arc<VulkanGenerationPagedKvArena>>>> {
        self.layers
            .iter()
            .map(|layer| {
                if layer.deepseek_v4_attention.is_none() && layer.qwen_gated_delta.is_none() {
                    VulkanGenerationPagedKvArena::new(
                        &self.device,
                        layer.key_hidden_size,
                        layer.value_hidden_size,
                        initial_pages.max(1),
                    )
                    .map(Some)
                } else {
                    Ok(None)
                }
            })
            .collect()
    }

    fn generation_prefill_kv_cache_with_policy_and_arenas(
        &self,
        prefix: &[u32],
        use_paged_kv: bool,
        shared_paged_arenas: Option<&[Option<Arc<VulkanGenerationPagedKvArena>>]>,
    ) -> Result<(Vec<f32>, VulkanGenerationKvCache)> {
        if let Some(arenas) = shared_paged_arenas {
            if arenas.len() != self.layers.len() {
                bail!(
                    "generation shared paged KV arena count {} does not match Transformer layer count {}",
                    arenas.len(),
                    self.layers.len()
                );
            }
        }
        let logits = self.generation_last_logits(prefix, None, None)?;
        let layers =
            self.layers
                .iter()
                .enumerate()
                .map(|(layer_index, layer)| {
                    let paged_kv = if use_paged_kv
                        && layer.deepseek_v4_attention.is_none()
                        && layer.qwen_gated_delta.is_none()
                    {
                        Some(if let Some(arenas) = shared_paged_arenas {
                            let arena = arenas[layer_index].as_ref().with_context(|| {
                                format!(
                                    "generation shared paged KV arena is missing for layer {layer_index}"
                                )
                            })?;
                            VulkanGenerationPagedKvCache::new_in_arena(
                                Arc::clone(arena),
                                self.seq_len,
                                prefix.len(),
                            )?
                        } else {
                            VulkanGenerationPagedKvCache::new(
                                &self.device,
                                layer.key_hidden_size,
                                layer.value_hidden_size,
                                self.seq_len,
                                prefix.len(),
                            )?
                        })
                    } else {
                        None
                    };
                    Ok(VulkanGenerationLayerKvCache {
                        key: if paged_kv.is_some() {
                            GpuBuffer::zeros_f32(&self.device, 1)?
                        } else {
                            GpuBuffer::zeros_f32(
                                &self.device,
                                self.seq_len
                                    * layer
                                        .deepseek_v4_attention
                                        .as_ref()
                                        .map(|attention| attention.head_dim)
                                        .unwrap_or(layer.key_hidden_size),
                            )?
                        },
                        value: if paged_kv.is_some() {
                            GpuBuffer::zeros_f32(&self.device, 1)?
                        } else {
                            GpuBuffer::zeros_f32(
                                &self.device,
                                self.seq_len
                                    * layer
                                        .deepseek_v4_attention
                                        .as_ref()
                                        .map(|attention| attention.head_dim)
                                        .unwrap_or(layer.value_hidden_size),
                            )?
                        },
                        paged_kv,
                        deepseek_v4_attention_input: layer
                            .deepseek_v4_attention
                            .as_ref()
                            .map(|_| {
                                GpuBuffer::zeros_f32(
                                    &self.device,
                                    self.seq_len * self.config.hidden_size,
                                )
                            })
                            .transpose()?,
                        indexer_key: layer
                            .generation_indexer_cache_width()
                            .map(|width| GpuBuffer::zeros_f32(&self.device, self.seq_len * width))
                            .transpose()?,
                        qwen_gated_delta_conv_state: layer
                            .qwen_gated_delta
                            .as_ref()
                            .map(|gated_delta| {
                                GpuBuffer::zeros_f32(
                                    &self.device,
                                    gated_delta.generation_conv_state_len(),
                                )
                            })
                            .transpose()?,
                        qwen_gated_delta_recurrent_state: layer
                            .qwen_gated_delta
                            .as_ref()
                            .map(|gated_delta| {
                                GpuBuffer::zeros_f32(
                                    &self.device,
                                    gated_delta.generation_recurrent_state_len()?,
                                )
                            })
                            .transpose()?,
                        qwen4_ple_conv_state: layer
                            .qwen4_ple
                            .as_ref()
                            .map(|ple| -> Result<GpuBuffer> {
                                GpuBuffer::zeros_f32(
                                    &self.device,
                                    ple.generation_conv_state_len()?.max(1),
                                )
                            })
                            .transpose()?,
                        qwen4_ple_ngram_history: layer.qwen4_ple.as_ref().map(|ple| {
                            Mutex::new(ple.generation_ngram_history_from_prefix(prefix))
                        }),
                    })
                })
                .collect::<Result<Vec<_>>>()?;
        let cache = VulkanGenerationKvCache {
            layers,
            attention_mask: GpuBuffer::zeros_f32(&self.device, self.seq_len)?,
            alibi_positions: GpuBuffer::zeros_f32(&self.device, self.seq_len)?,
        };

        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        let visible_mask = vec![1.0f32; prefix.len()];
        commands.upload_f32(&cache.attention_mask, &visible_mask)?;
        for (layer, layer_cache) in self.layers.iter().zip(cache.layers.iter()) {
            if let Some(deepseek_v4) = layer.deepseek_v4_attention.as_ref() {
                commands.copy_f32(
                    &deepseek_v4.tape.kv_rotary,
                    &layer_cache.key,
                    prefix.len() * deepseek_v4.head_dim,
                )?;
                commands.copy_f32(
                    &deepseek_v4.tape.kv_rotary,
                    &layer_cache.value,
                    prefix.len() * deepseek_v4.head_dim,
                )?;
                commands.copy_f32(
                    &layer.tape.ln1,
                    layer_cache.deepseek_v4_attention_input.as_ref().context(
                        "DeepSeek-V4 prefill cache is missing its pre-attention hidden history",
                    )?,
                    prefix.len() * self.config.hidden_size,
                )?;
            } else if let Some(gated_delta) = layer.qwen_gated_delta.as_ref() {
                gated_delta.record_generation_prefill_cache(
                    &mut commands,
                    &self.kernels,
                    layer_cache
                        .qwen_gated_delta_conv_state
                        .as_ref()
                        .context("Qwen Gated DeltaNet prefill cache is missing Conv1D state")?,
                    layer_cache
                        .qwen_gated_delta_recurrent_state
                        .as_ref()
                        .context("Qwen Gated DeltaNet prefill cache is missing recurrent state")?,
                    prefix.len(),
                )?;
            } else if let Some(paged) = layer_cache.paged_kv.as_ref() {
                paged.record_prefill_from_sources(
                    &mut commands,
                    layer.generation_attention_key_source(&self.config),
                    layer.generation_attention_value_source(),
                    0,
                    prefix.len(),
                )?;
            } else {
                commands.copy_f32(
                    layer.generation_attention_key_source(&self.config),
                    &layer_cache.key,
                    prefix.len() * layer.key_hidden_size,
                )?;
                commands.copy_f32(
                    layer.generation_attention_value_source(),
                    &layer_cache.value,
                    prefix.len() * layer.value_hidden_size,
                )?;
            }
            match (&layer.qwen4_ple, &layer_cache.qwen4_ple_conv_state) {
                (Some(ple), Some(conv_state)) => {
                    ple.record_generation_prefill_cache(&mut commands, conv_state, prefix.len())?
                }
                (None, None) => {}
                _ => bail!("generation Qwen4 PLE cache topology does not match Transformer layer"),
            }
            match (
                layer.generation_indexer_key_source(),
                layer.generation_indexer_cache_width(),
                &layer_cache.indexer_key,
            ) {
                (Some(source), Some(width), Some(indexer_cache)) => {
                    commands.copy_f32(source, indexer_cache, prefix.len() * width)?
                }
                (None, None, None) => {}
                _ => {
                    bail!("generation indexer cache topology does not match Transformer layer")
                }
            }
        }
        commands.submit()?;
        Ok((logits, cache))
    }

    fn generation_clone_kv_cache_prefix(
        &self,
        source: &VulkanGenerationKvCache,
        prefix_len: usize,
    ) -> Result<VulkanGenerationKvCache> {
        if prefix_len > self.seq_len {
            bail!(
                "generation KV cache clone prefix {prefix_len} exceeds graph context {}",
                self.seq_len
            );
        }
        if source.layers.len() != self.layers.len() {
            bail!("generation KV cache layer count does not match Transformer graph");
        }
        let layers = self
            .layers
            .iter()
            .zip(source.layers.iter())
            .map(|(layer, source_layer)| {
                let paged_kv = source_layer
                    .paged_kv
                    .as_ref()
                    .map(|paged| paged.clone_prefix(prefix_len))
                    .transpose()?;
                Ok(VulkanGenerationLayerKvCache {
                    key: if paged_kv.is_some() {
                        GpuBuffer::zeros_f32(&self.device, 1)?
                    } else {
                        GpuBuffer::zeros_f32(
                            &self.device,
                            self.seq_len
                                * layer
                                    .deepseek_v4_attention
                                    .as_ref()
                                    .map(|attention| attention.head_dim)
                                    .unwrap_or(layer.key_hidden_size),
                        )?
                    },
                    value: if paged_kv.is_some() {
                        GpuBuffer::zeros_f32(&self.device, 1)?
                    } else {
                        GpuBuffer::zeros_f32(
                            &self.device,
                            self.seq_len
                                * layer
                                    .deepseek_v4_attention
                                    .as_ref()
                                    .map(|attention| attention.head_dim)
                                    .unwrap_or(layer.value_hidden_size),
                        )?
                    },
                    paged_kv,
                    deepseek_v4_attention_input: layer
                        .deepseek_v4_attention
                        .as_ref()
                        .map(|_| {
                            GpuBuffer::zeros_f32(
                                &self.device,
                                self.seq_len * self.config.hidden_size,
                            )
                        })
                        .transpose()?,
                    indexer_key: layer
                        .generation_indexer_cache_width()
                        .map(|width| GpuBuffer::zeros_f32(&self.device, self.seq_len * width))
                        .transpose()?,
                    qwen_gated_delta_conv_state: layer
                        .qwen_gated_delta
                        .as_ref()
                        .map(|gated_delta| {
                            GpuBuffer::zeros_f32(
                                &self.device,
                                gated_delta.generation_conv_state_len(),
                            )
                        })
                        .transpose()?,
                    qwen_gated_delta_recurrent_state: layer
                        .qwen_gated_delta
                        .as_ref()
                        .map(|gated_delta| {
                            GpuBuffer::zeros_f32(
                                &self.device,
                                gated_delta.generation_recurrent_state_len()?,
                            )
                        })
                        .transpose()?,
                    qwen4_ple_conv_state: layer
                        .qwen4_ple
                        .as_ref()
                        .map(|ple| -> Result<GpuBuffer> {
                            GpuBuffer::zeros_f32(
                                &self.device,
                                ple.generation_conv_state_len()?.max(1),
                            )
                        })
                        .transpose()?,
                    qwen4_ple_ngram_history: layer
                        .qwen4_ple
                        .as_ref()
                        .map(|_| Mutex::new(Vec::new())),
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let cache = VulkanGenerationKvCache {
            layers,
            attention_mask: GpuBuffer::zeros_f32(&self.device, self.seq_len)?,
            alibi_positions: GpuBuffer::zeros_f32(&self.device, self.seq_len)?,
        };
        if prefix_len == 0 {
            return Ok(cache);
        }

        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        for ((model_layer, source_layer), destination_layer) in self
            .layers
            .iter()
            .zip(source.layers.iter())
            .zip(cache.layers.iter())
        {
            let key_cache_width = model_layer
                .deepseek_v4_attention
                .as_ref()
                .map(|attention| attention.head_dim)
                .unwrap_or(model_layer.key_hidden_size);
            let value_cache_width = model_layer
                .deepseek_v4_attention
                .as_ref()
                .map(|attention| attention.head_dim)
                .unwrap_or(model_layer.value_hidden_size);
            let key_len = prefix_len
                .checked_mul(key_cache_width)
                .context("generation key-cache clone length overflow")?;
            let value_len = prefix_len
                .checked_mul(value_cache_width)
                .context("generation value-cache clone length overflow")?;
            match (&source_layer.paged_kv, &destination_layer.paged_kv) {
                (Some(_), Some(_)) => {}
                (None, None) => {
                    commands.copy_f32_range(
                        &source_layer.key,
                        0,
                        &destination_layer.key,
                        0,
                        key_len,
                    )?;
                    commands.copy_f32_range(
                        &source_layer.value,
                        0,
                        &destination_layer.value,
                        0,
                        value_len,
                    )?;
                }
                _ => bail!("generation paged KV cache topology does not match Transformer layer"),
            }
            match (
                &source_layer.deepseek_v4_attention_input,
                &destination_layer.deepseek_v4_attention_input,
            ) {
                (Some(source_history), Some(destination_history)) => {
                    let hidden_len = prefix_len
                        .checked_mul(self.config.hidden_size)
                        .context("DeepSeek-V4 hidden-history cache clone length overflow")?;
                    commands.copy_f32_range(
                        source_history,
                        0,
                        destination_history,
                        0,
                        hidden_len,
                    )?;
                }
                (None, None) => {}
                _ => {
                    bail!("DeepSeek-V4 generation cache topology does not match Transformer layer")
                }
            }
            match (
                model_layer.generation_indexer_cache_width(),
                &source_layer.indexer_key,
                &destination_layer.indexer_key,
            ) {
                (Some(width), Some(source_indexer), Some(destination_indexer)) => {
                    let indexer_len = prefix_len
                        .checked_mul(width)
                        .context("generation indexer-cache clone length overflow")?;
                    commands.copy_f32_range(
                        source_indexer,
                        0,
                        destination_indexer,
                        0,
                        indexer_len,
                    )?;
                }
                (None, None, None) => {}
                _ => {
                    bail!("generation indexer cache topology does not match Transformer layer")
                }
            }
            match (
                &model_layer.qwen_gated_delta,
                &source_layer.qwen_gated_delta_conv_state,
                &source_layer.qwen_gated_delta_recurrent_state,
                &destination_layer.qwen_gated_delta_conv_state,
                &destination_layer.qwen_gated_delta_recurrent_state,
            ) {
                (
                    Some(gated_delta),
                    Some(source_conv),
                    Some(source_recurrent),
                    Some(destination_conv),
                    Some(destination_recurrent),
                ) => {
                    commands.copy_f32(
                        source_conv,
                        destination_conv,
                        gated_delta.generation_conv_state_len(),
                    )?;
                    commands.copy_f32(
                        source_recurrent,
                        destination_recurrent,
                        gated_delta.generation_recurrent_state_len()?,
                    )?;
                }
                (None, None, None, None, None) => {}
                _ => {
                    bail!("generation Qwen Gated DeltaNet cache topology does not match Transformer layer")
                }
            }
            match (
                &model_layer.qwen4_ple,
                &source_layer.qwen4_ple_conv_state,
                &destination_layer.qwen4_ple_conv_state,
            ) {
                (Some(ple), Some(source_conv), Some(destination_conv)) => {
                    let len = ple.generation_conv_state_len()?;
                    if len != 0 {
                        commands.copy_f32(source_conv, destination_conv, len)?;
                    }
                }
                (None, None, None) => {}
                _ => bail!("generation Qwen4 PLE cache topology does not match Transformer layer"),
            }
            match (
                &model_layer.qwen4_ple,
                &source_layer.qwen4_ple_ngram_history,
                &destination_layer.qwen4_ple_ngram_history,
            ) {
                (Some(_), Some(source_history), Some(destination_history)) => {
                    let source_history = source_history.lock().map_err(|_| {
                        anyhow!("Qwen4 PLE generation n-gram history mutex is poisoned")
                    })?;
                    let mut destination_history = destination_history.lock().map_err(|_| {
                        anyhow!("Qwen4 PLE generation n-gram history mutex is poisoned")
                    })?;
                    destination_history.clone_from(&source_history);
                }
                (None, None, None) => {}
                _ => bail!(
                    "generation Qwen4 PLE n-gram cache topology does not match Transformer layer"
                ),
            }
        }
        commands.copy_f32_range(
            &source.attention_mask,
            0,
            &cache.attention_mask,
            0,
            prefix_len,
        )?;
        commands.copy_f32_range(
            &source.alibi_positions,
            0,
            &cache.alibi_positions,
            0,
            prefix_len,
        )?;
        commands.submit()?;
        Ok(cache)
    }

    fn prepare_generation_cached_step(
        &self,
        token: u32,
        cache: &VulkanGenerationKvCache,
        position: usize,
    ) -> Result<()> {
        if position >= self.seq_len {
            bail!(
                "generation cache position {position} is outside graph context {}",
                self.seq_len
            );
        }
        if cache.layers.len() != self.layers.len() {
            bail!("generation KV cache layer count does not match Transformer graph");
        }
        if token as usize >= self.config.vocab_size {
            bail!(
                "generation token {token} is outside vocabulary size {}",
                self.config.vocab_size
            );
        }

        // Resolve the logical destination page before recording the layer
        // command stream. This is where beam-prefix sharing turns into COW:
        // only a shared tail page is duplicated, while fully shared prefix
        // pages remain aliased across hypotheses. Any arena growth completes
        // before the main step batch captures buffer descriptors.
        for layer_cache in &cache.layers {
            if let Some(paged) = layer_cache.paged_kv.as_ref() {
                paged.prepare_write(position)?;
            }
        }
        Ok(())
    }

    fn record_generation_cached_step_logits_prepared(
        &self,
        commands: &mut vulkan::ComputeBatch,
        token: u32,
        cache: &VulkanGenerationKvCache,
        position: usize,
    ) -> Result<()> {
        let mut commands = commands;
        let mut eval_config = self.config.clone();
        eval_config.attention_dropout = 0.0;
        eval_config.attention_output_dropout = 0.0;
        eval_config.mlp_output_dropout = 0.0;
        eval_config.activation_dropout = 0.0;
        eval_config.embedding_dropout = 0.0;

        commands.upload_u32(&self.token_ids, &[token])?;
        let visible_mask = vec![1.0f32; position + 1];
        commands.upload_f32(&cache.attention_mask, &visible_mask)?;
        self.token_embedding.record_forward(
            &mut commands,
            1,
            &self.token_ids,
            &self.token_embedding_output,
        )?;
        if let Some(position_embedding) = self.position_embedding.as_ref() {
            let position_push = PositionPush {
                rows_or_batch: 1,
                seq_len: 1,
                dim: eval_config.hidden_size as u32,
                position_offset: position as u32,
            };
            self.kernels.position_add.record_dispatch(
                &mut commands,
                &[
                    &self.token_embedding_output,
                    &position_embedding.values,
                    &self.input_hidden,
                ],
                bytemuck::bytes_of(&position_push),
                [div_ceil_u32(eval_config.hidden_size, 16), 1, 1],
            )?;
        } else {
            let copy_push = ScalePush {
                len: eval_config.hidden_size as u32,
                scale: eval_config.token_embedding_scale(),
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[&self.token_embedding_output, &self.input_hidden],
                bytemuck::bytes_of(&copy_push),
                [div_ceil_u32(eval_config.hidden_size, 256), 1, 1],
            )?;
        }

        let deepseek_v4_initial_input = if let (Some(hc_mult), Some(hyper)) = (
            self.deepseek_v4_hyper_head
                .as_ref()
                .map(|head| head.hc_mult)
                .or(self.glm5_hc_mult),
            self.deepseek_v4_initial_hyper.as_ref(),
        ) {
            let push = Qwen4HyperPush {
                rows: 1,
                hidden_size: eval_config.hidden_size as u32,
                hc_count: hc_mult as u32,
            };
            self.kernels.qwen4_repeat_streams.record_dispatch(
                &mut commands,
                &[&self.input_hidden, hyper],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(eval_config.hidden_size * hc_mult, 256), 1, 1],
            )?;
            Some(hyper)
        } else {
            None
        };

        let qwen4_initial_input = if let (Some(mixer), Some(hyper)) = (
            self.qwen4_final_mixer.as_ref(),
            self.qwen4_initial_hyper.as_ref(),
        ) {
            let push = Qwen4HyperPush {
                rows: 1,
                hidden_size: eval_config.hidden_size as u32,
                hc_count: mixer.hc_count as u32,
            };
            self.kernels.qwen4_repeat_streams.record_dispatch(
                &mut commands,
                &[&self.input_hidden, hyper],
                bytemuck::bytes_of(&push),
                [
                    div_ceil_u32(eval_config.hidden_size * mixer.hc_count, 256),
                    1,
                    1,
                ],
            )?;
            Some(hyper)
        } else {
            None
        };

        for layer_index in 0..self.layers.len() {
            self.layers[layer_index].prepare_qwen4_ple_generation_embedding(
                &mut commands,
                token,
                &cache.layers[layer_index],
            )?;
            let input = if layer_index == 0 {
                deepseek_v4_initial_input
                    .or(qwen4_initial_input)
                    .unwrap_or(&self.input_hidden)
            } else {
                self.layers[layer_index - 1].forward_output()
            };
            let shared_dsa_sparse_mask = self.shared_dsa_sparse_mask_for_layer(layer_index)?;
            self.layers[layer_index].record_forward_with_cross_attention(
                &mut commands,
                &self.kernels,
                &eval_config,
                true,
                input,
                Some(&self.token_ids),
                &cache.attention_mask,
                &cache.alibi_positions,
                self.relative_attention_bias_for_layer(layer_index),
                self.relative_attention_num_buckets,
                self.relative_attention_max_distance,
                None,
                None,
                0,
                1,
                1,
                self.step,
                self.dropout_seed,
                false,
                Some((&cache.layers[layer_index], &cache.attention_mask, position)),
                self.kimi_attn_res.as_ref(),
                shared_dsa_sparse_mask,
            )?;
            self.record_longcat_pair_forward_merge(&mut commands, layer_index, 1)?;
        }

        let final_prefix = self
            .layers
            .last()
            .context("Transformer has no layers")?
            .forward_output();
        let final_input = if let Some(stack) = self.kimi_attn_res.as_ref() {
            stack.record_output_forward(
                &mut commands,
                &self.kernels,
                final_prefix,
                1,
                eval_config.hidden_size,
            )?
        } else {
            final_prefix
        };
        let terminal_hidden = if let Some(head) = self.deepseek_v4_hyper_head.as_ref() {
            head.record_forward_rows(&mut commands, &self.kernels, final_input, 1)?;
            if eval_config.uses_final_norm() {
                self.final_norm.record_forward(
                    &mut commands,
                    &self.kernels,
                    head.output(),
                    &self.final_norm_output,
                    &self.final_norm_mean,
                    &self.final_norm_rstd,
                    1,
                )?;
                &self.final_norm_output
            } else {
                head.output()
            }
        } else if let Some(hc_mult) = self.glm5_hc_mult {
            if !eval_config.uses_final_norm() {
                bail!("GLM-5 mHC terminal mean requires the final RMSNorm");
            }
            let mean = self
                .glm5_terminal_mean
                .as_ref()
                .context("GLM-5 mHC graph is missing its terminal mean buffer")?;
            let push = Qwen4HyperPush {
                rows: 1,
                hidden_size: eval_config.hidden_size as u32,
                hc_count: hc_mult as u32,
            };
            self.kernels.qwen4_stream_mean.record_dispatch(
                &mut commands,
                &[final_input, mean],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(eval_config.hidden_size, 16), 1, 1],
            )?;
            self.final_norm.record_forward(
                &mut commands,
                &self.kernels,
                mean,
                &self.final_norm_output,
                &self.final_norm_mean,
                &self.final_norm_rstd,
                1,
            )?;
            &self.final_norm_output
        } else if let Some(mixer) = self.qwen4_final_mixer.as_ref() {
            mixer.record_forward(
                &mut commands,
                &self.kernels,
                final_input,
                &self.final_norm_output,
                None,
            )?;
            &self.final_norm_output
        } else if eval_config.uses_final_norm() {
            self.final_norm.record_forward(
                &mut commands,
                &self.kernels,
                final_input,
                &self.final_norm_output,
                &self.final_norm_mean,
                &self.final_norm_rstd,
                1,
            )?;
            &self.final_norm_output
        } else {
            final_input
        };
        let projection_logits = self.raw_logits.as_ref().unwrap_or(&self.logits);
        if let Some(lm_head) = self.lm_head.as_ref() {
            lm_head.record_forward(
                &mut commands,
                &self.kernels,
                terminal_hidden,
                projection_logits,
                1,
            )?;
        } else {
            let lm_push = LinearPush {
                rows: 1,
                input_dim: eval_config.hidden_size as u32,
                output_dim: eval_config.vocab_size as u32,
            };
            self.kernels.linear_forward.record_dispatch(
                &mut commands,
                &[
                    terminal_hidden,
                    self.shared_embedding.weight_buffer(),
                    projection_logits,
                ],
                bytemuck::bytes_of(&lm_push),
                [div_ceil_u32(eval_config.vocab_size, 16), 1, 1],
            )?;
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                let bias_push = BiasPush {
                    rows: 1,
                    dim: eval_config.vocab_size as u32,
                };
                self.kernels.bias_add.record_dispatch(
                    &mut commands,
                    &[projection_logits, &lm_head_bias.values],
                    bytemuck::bytes_of(&bias_push),
                    [div_ceil_u32(eval_config.vocab_size, 256), 1, 1],
                )?;
            }
        }
        if let Some(cap) = eval_config.final_logit_softcapping {
            let raw_logits = self
                .raw_logits
                .as_ref()
                .context("logit soft-capping requires raw-logit storage")?;
            let scratch = self
                .logit_postprocess_scratch
                .as_ref()
                .context("logit soft-capping requires scratch storage")?;
            let scale_into_tanh = ScalePush {
                len: eval_config.vocab_size as u32,
                scale: eval_config.logits_multiplier / cap,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[raw_logits, scratch],
                bytemuck::bytes_of(&scale_into_tanh),
                [div_ceil_u32(eval_config.vocab_size, 256), 1, 1],
            )?;
            let tanh_push = LenPush {
                len: eval_config.vocab_size as u32,
            };
            self.kernels.tanh_forward.record_dispatch(
                &mut commands,
                &[scratch, raw_logits],
                bytemuck::bytes_of(&tanh_push),
                [div_ceil_u32(eval_config.vocab_size, 256), 1, 1],
            )?;
            let scale_out = ScalePush {
                len: eval_config.vocab_size as u32,
                scale: cap,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[raw_logits, &self.logits],
                bytemuck::bytes_of(&scale_out),
                [div_ceil_u32(eval_config.vocab_size, 256), 1, 1],
            )?;
        } else if let Some(raw_logits) = self.raw_logits.as_ref() {
            let push = ScalePush {
                len: eval_config.vocab_size as u32,
                scale: eval_config.logits_multiplier,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[raw_logits, &self.logits],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(eval_config.vocab_size, 256), 1, 1],
            )?;
        }
        Ok(())
    }

    fn generation_cached_step_logits(
        &self,
        token: u32,
        cache: &VulkanGenerationKvCache,
        position: usize,
    ) -> Result<Vec<f32>> {
        self.prepare_generation_cached_step(token, cache, position)?;
        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        self.record_generation_cached_step_logits_prepared(&mut commands, token, cache, position)?;
        commands.submit()?;
        self.logits.read_f32(self.config.vocab_size)
    }

    fn generation_cached_step_logits_continuous_paged(
        &self,
        steps: &[(u32, &VulkanGenerationKvCache, usize)],
    ) -> Result<Vec<Vec<f32>>> {
        if steps.is_empty() {
            return Ok(Vec::new());
        }

        let first_cache = steps[0].1;
        for (layer_index, first_layer) in first_cache.layers.iter().enumerate() {
            let Some(first_paged) = first_layer.paged_kv.as_ref() else {
                continue;
            };
            for (_, cache, _) in steps.iter().skip(1) {
                let paged = cache
                    .layers
                    .get(layer_index)
                    .and_then(|layer| layer.paged_kv.as_ref())
                    .with_context(|| {
                        format!("continuous paged KV batch is missing paged layer {layer_index}")
                    })?;
                if !Arc::ptr_eq(&first_paged.arena, &paged.arena) {
                    bail!(
                        "continuous paged KV layer {layer_index} does not share one global physical arena"
                    );
                }
            }
        }
        if !first_cache
            .layers
            .iter()
            .any(|layer| layer.paged_kv.is_some())
        {
            bail!("continuous paged KV decode has no paged K/V attention layers");
        }

        // Resolve every logical destination before recording any descriptors.
        // A prepare may grow a shared arena, so all growth must complete before
        // the command batch captures the arena buffers used by every request.
        for &(token, cache, position) in steps {
            self.prepare_generation_cached_step(token, cache, position)?;
        }

        let vocab_size = self.config.vocab_size;
        let logits_len = vocab_size
            .checked_mul(steps.len())
            .context("continuous paged KV logits buffer size overflow")?;
        let batched_logits = GpuBuffer::zeros_f32(&self.device, logits_len)?;
        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        for (request_index, &(token, cache, position)) in steps.iter().enumerate() {
            self.record_generation_cached_step_logits_prepared(
                &mut commands,
                token,
                cache,
                position,
            )?;
            commands.copy_f32_range(
                &self.logits,
                0,
                &batched_logits,
                request_index * vocab_size,
                vocab_size,
            )?;
        }
        commands.submit()?;

        let flat = batched_logits.read_f32(logits_len)?;
        Ok(flat
            .chunks_exact(vocab_size)
            .map(|logits| logits.to_vec())
            .collect())
    }

    fn generate_single_output_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<VulkanTransformerGenerationSequenceOutput> {
        if config.generation_mode() == VulkanTransformerGenerationMode::AssistedGeneration {
            if config.assistant_early_exit.is_some() {
                return self.generate_early_exit_assisted_output(
                    prompt,
                    config,
                    encoder_hidden_states,
                    encoder_attention_mask,
                    |_| Ok(()),
                );
            }
            return self.generate_prompt_lookup_assisted_output_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
                |_| Ok(()),
            );
        }
        if config.generation_mode() == VulkanTransformerGenerationMode::ContrastiveSearch {
            return self.generate_contrastive_output_full_prefix_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
            );
        }
        if config.generation_mode() == VulkanTransformerGenerationMode::DolaGeneration {
            return self.generate_dola_output_full_prefix_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
            );
        }
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        let collect_scores = config.return_dict_in_generate && config.output_scores;
        let collect_logits = config.return_dict_in_generate && config.output_logits;
        let collect_hidden_states = config.return_dict_in_generate && config.output_hidden_states;
        let mut sequence = prompt.to_vec();
        let mut scores_output = collect_scores.then(|| Vec::with_capacity(requested));
        let mut logits_output = collect_logits.then(|| Vec::with_capacity(requested));
        let mut hidden_states_output = collect_hidden_states.then(|| Vec::with_capacity(requested));
        let generation_started = Instant::now();

        for step in 0..requested {
            let logits = self.generation_last_logits(
                &sequence,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            if let Some(output) = hidden_states_output.as_mut() {
                output.push(self.generation_hidden_states_for_last_forward(
                    sequence.len(),
                    config.use_cache,
                    step,
                )?);
            }
            let scores = self.generation_processed_non_beam_scores_with_cfg(
                &logits,
                &sequence,
                config,
                step,
                step + 1 == requested,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            if let Some(output) = logits_output.as_mut() {
                output.push(logits.clone());
            }
            if let Some(output) = scores_output.as_mut() {
                output.push(scores.clone());
            }
            let next_token = if config.do_sample {
                generation_sample_processed_scores(&scores, config.seed, step as u64)?
            } else {
                generation_argmax(&scores)?
            };
            sequence.push(next_token);
            if config.should_stop_sequence(&sequence)
                || generation_max_time_reached(generation_started, config)
            {
                break;
            }
        }

        Ok(VulkanTransformerGenerationSequenceOutput {
            sequence,
            prompt_length: prompt.len(),
            scores: scores_output,
            logits: logits_output,
            hidden_states: hidden_states_output,
            attentions: None,
            cross_attentions: None,
            sequence_score: None,
            beam_indices: None,
        })
    }

    fn generation_prompt_lookup_assisted_step_with_context(
        &self,
        sequence: &[u32],
        prompt_len: usize,
        config: &VulkanTransformerGenerationConfig,
        generated_count: usize,
        requested: usize,
        sample_index_base: u64,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<(Vec<u32>, Vec<Vec<f32>>, Vec<Vec<f32>>, usize)> {
        if generated_count >= requested {
            return Ok((Vec::new(), Vec::new(), Vec::new(), 0));
        }
        let max_total_len = prompt_len.saturating_add(requested).min(self.seq_len);
        let draft = generation_prompt_lookup_candidates(
            sequence,
            prompt_len,
            max_total_len,
            self.config.vocab_size,
            config,
        )?;
        let raw_rows = self.generation_assisted_target_logits(
            sequence,
            &draft,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        if raw_rows.is_empty() {
            bail!("prompt lookup target forward produced no logits rows");
        }

        let mut processed_rows = Vec::with_capacity(raw_rows.len());
        let mut selected_tokens = Vec::with_capacity(raw_rows.len());
        let mut candidate_history = sequence.to_vec();
        for (row_index, logits) in raw_rows.iter().enumerate() {
            let absolute_step = generated_count + row_index;
            let scores = self.generation_processed_non_beam_scores_with_cfg(
                logits,
                &candidate_history,
                config,
                absolute_step,
                absolute_step + 1 >= requested,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            let token = if config.do_sample {
                generation_sample_processed_scores(
                    &scores,
                    config.seed,
                    sample_index_base.wrapping_add(row_index as u64),
                )?
            } else {
                generation_argmax(&scores)?
            };
            processed_rows.push(scores);
            selected_tokens.push(token);
            if row_index < draft.len() {
                candidate_history.push(draft[row_index]);
            }
        }

        let mut matches = 0usize;
        while matches < draft.len()
            && matches < selected_tokens.len().saturating_sub(1)
            && draft[matches] == selected_tokens[matches]
        {
            matches += 1;
        }
        let remaining = requested.saturating_sub(generated_count);
        let accepted_len = (matches + 1).min(remaining).min(selected_tokens.len());
        Ok((
            selected_tokens[..accepted_len].to_vec(),
            raw_rows[..accepted_len].to_vec(),
            processed_rows[..accepted_len].to_vec(),
            raw_rows.len(),
        ))
    }

    fn generate_prompt_lookup_assisted_output_with_context<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        mut on_token: F,
    ) -> Result<VulkanTransformerGenerationSequenceOutput>
    where
        F: FnMut(u32) -> Result<()>,
    {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        let collect_scores = config.return_dict_in_generate && config.output_scores;
        let collect_logits = config.return_dict_in_generate && config.output_logits;
        let mut sequence = prompt.to_vec();
        let mut scores_output = collect_scores.then(|| Vec::with_capacity(requested));
        let mut logits_output = collect_logits.then(|| Vec::with_capacity(requested));
        let generation_started = Instant::now();
        let mut generated_count = 0usize;
        let mut sample_index = 0u64;

        while generated_count < requested {
            let (accepted, logits, scores, sampled_rows) = self
                .generation_prompt_lookup_assisted_step_with_context(
                    &sequence,
                    prompt.len(),
                    config,
                    generated_count,
                    requested,
                    sample_index,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
            if accepted.is_empty() {
                break;
            }
            if config.do_sample {
                // HF samples every target row in the speculative forward,
                // including rows after the first mismatch. Keep a distinct
                // RNG slot for all of those draws so rejected drafts still
                // advance the deterministic stream.
                sample_index = sample_index.wrapping_add(sampled_rows as u64);
            }
            if let Some(output) = logits_output.as_mut() {
                output.extend(logits);
            }
            if let Some(output) = scores_output.as_mut() {
                output.extend(scores);
            }

            let mut should_stop = false;
            for token in accepted {
                sequence.push(token);
                generated_count += 1;
                on_token(token)?;
                if config.should_stop_sequence(&sequence) || generated_count >= requested {
                    should_stop = true;
                    break;
                }
            }
            if should_stop || generation_max_time_reached(generation_started, config) {
                break;
            }
        }

        Ok(VulkanTransformerGenerationSequenceOutput {
            sequence,
            prompt_length: prompt.len(),
            scores: scores_output,
            logits: logits_output,
            hidden_states: None,
            attentions: None,
            cross_attentions: None,
            sequence_score: None,
            beam_indices: None,
        })
    }

    fn generation_external_assistant_candidates(
        &self,
        assistant_model: &VulkanTransformer,
        sequence: &[u32],
        config: &VulkanTransformerGenerationConfig,
        generated_count: usize,
        requested: usize,
        candidate_budget: usize,
        mut sample_index: u64,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<(Vec<u32>, Vec<Vec<f32>>, u64)> {
        let remaining = requested.saturating_sub(generated_count);
        let target_context_remaining = self.seq_len.saturating_sub(sequence.len());
        let assistant_context_remaining = assistant_model.seq_len.saturating_sub(sequence.len());
        let max_candidates = candidate_budget
            .min(remaining.saturating_sub(1))
            .min(target_context_remaining.saturating_sub(1))
            .min(assistant_context_remaining);
        let mut history = sequence.to_vec();
        let mut draft = Vec::with_capacity(max_candidates);
        let mut candidate_scores = Vec::with_capacity(max_candidates);

        for draft_index in 0..max_candidates {
            let logits = assistant_model.generation_last_logits(
                &history,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            let absolute_step = generated_count + draft_index;
            let scores = self.generation_processed_non_beam_scores_with_cfg(
                &logits,
                &history,
                config,
                absolute_step,
                absolute_step + 1 >= requested,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            let token = if config.do_sample {
                let token = generation_sample_processed_scores(&scores, config.seed, sample_index)?;
                sample_index = sample_index.wrapping_add(1);
                token
            } else {
                generation_argmax(&scores)?
            };
            let confidence = if config.assistant_confidence_threshold.is_some() {
                generation_probabilities(&scores)?
                    .get(token as usize)
                    .copied()
                    .context("assistant token is outside its probability vector")?
            } else {
                1.0
            };
            candidate_scores.push(scores);
            draft.push(token);
            history.push(token);

            if config.should_stop_sequence(&history)
                || config
                    .assistant_confidence_threshold
                    .is_some_and(|threshold| confidence < f64::from(threshold))
            {
                break;
            }
        }
        Ok((draft, candidate_scores, sample_index))
    }

    fn generation_external_assistant_step(
        &self,
        assistant_model: &VulkanTransformer,
        sequence: &[u32],
        config: &VulkanTransformerGenerationConfig,
        generated_count: usize,
        requested: usize,
        candidate_budget: usize,
        sample_index: u64,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<(Vec<u32>, Vec<Vec<f32>>, Vec<Vec<f32>>, usize, usize, u64)> {
        if generated_count >= requested {
            return Ok((Vec::new(), Vec::new(), Vec::new(), 0, 0, sample_index));
        }
        let (draft, candidate_scores, mut next_sample_index) = self
            .generation_external_assistant_candidates(
                assistant_model,
                sequence,
                config,
                generated_count,
                requested,
                candidate_budget,
                sample_index,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
        let raw_rows = self.generation_assisted_target_logits(
            sequence,
            &draft,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        if raw_rows.len() != draft.len() + 1 {
            bail!("assistant-model target forward produced invalid speculative logits geometry");
        }

        let mut processed_rows = Vec::with_capacity(raw_rows.len());
        let mut candidate_history = sequence.to_vec();
        for (row_index, logits) in raw_rows.iter().enumerate() {
            let absolute_step = generated_count + row_index;
            processed_rows.push(self.generation_processed_non_beam_scores_with_cfg(
                logits,
                &candidate_history,
                config,
                absolute_step,
                absolute_step + 1 >= requested,
                encoder_hidden_states,
                encoder_attention_mask,
            )?);
            if row_index < draft.len() {
                candidate_history.push(draft[row_index]);
            }
        }

        let candidate_is_done = if draft.is_empty() {
            false
        } else {
            let mut candidate_history = sequence.to_vec();
            candidate_history.extend_from_slice(&draft);
            config.should_stop_sequence(&candidate_history)
        };
        let (mut accepted, mut matches) = if config.do_sample {
            let (accepted, matches, updated_sample_index) = generation_speculative_sample(
                &draft,
                &candidate_scores,
                &processed_rows,
                candidate_is_done,
                config.assistant_ensemble_weight,
                config.seed,
                next_sample_index,
            )?;
            next_sample_index = updated_sample_index;
            (accepted, matches)
        } else {
            let selected_tokens = processed_rows
                .iter()
                .enumerate()
                .map(|(row_index, scores)| {
                    if row_index < draft.len() {
                        if let Some(weight) = config.assistant_ensemble_weight {
                            return generation_ensemble_argmax(
                                scores,
                                &candidate_scores[row_index],
                                weight,
                            );
                        }
                    }
                    generation_argmax(scores)
                })
                .collect::<Result<Vec<_>>>()?;
            let mut matches = 0usize;
            while matches < draft.len()
                && matches < selected_tokens.len().saturating_sub(1)
                && draft[matches] == selected_tokens[matches]
            {
                matches += 1;
            }
            if candidate_is_done && matches == draft.len() && !draft.is_empty() {
                (draft.clone(), matches - 1)
            } else {
                (selected_tokens[..matches + 1].to_vec(), matches)
            }
        };

        let remaining = requested.saturating_sub(generated_count);
        if accepted.len() > remaining {
            accepted.truncate(remaining);
            matches = accepted.len().saturating_sub(1);
        }
        let accepted_len = accepted.len();
        Ok((
            accepted,
            raw_rows[..accepted_len].to_vec(),
            processed_rows[..accepted_len].to_vec(),
            matches,
            draft.len(),
            next_sample_index,
        ))
    }

    fn generate_external_assistant_output_with_context<F>(
        &self,
        assistant_model: &VulkanTransformer,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        mut on_token: F,
    ) -> Result<VulkanTransformerGenerationSequenceOutput>
    where
        F: FnMut(u32) -> Result<()>,
    {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        let collect_scores = config.return_dict_in_generate && config.output_scores;
        let collect_logits = config.return_dict_in_generate && config.output_logits;
        let mut sequence = prompt.to_vec();
        let mut scores_output = collect_scores.then(|| Vec::with_capacity(requested));
        let mut logits_output = collect_logits.then(|| Vec::with_capacity(requested));
        let generation_started = Instant::now();
        let mut generated_count = 0usize;
        let mut sample_index = 0u64;
        let mut candidate_budget = config.num_assistant_tokens;

        while generated_count < requested {
            let (accepted, logits, scores, matches, candidate_length, next_sample_index) = self
                .generation_external_assistant_step(
                    assistant_model,
                    &sequence,
                    config,
                    generated_count,
                    requested,
                    candidate_budget,
                    sample_index,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
            sample_index = next_sample_index;
            if accepted.is_empty() {
                break;
            }
            if matches!(
                config.num_assistant_tokens_schedule.as_str(),
                "heuristic" | "heuristic_transient"
            ) {
                candidate_budget = if matches == candidate_length {
                    candidate_budget.saturating_add(2)
                } else {
                    candidate_budget.saturating_sub(1).max(1)
                };
            }
            if let Some(output) = logits_output.as_mut() {
                output.extend(logits);
            }
            if let Some(output) = scores_output.as_mut() {
                output.extend(scores);
            }

            let mut should_stop = false;
            for token in accepted {
                sequence.push(token);
                generated_count += 1;
                on_token(token)?;
                if config.should_stop_sequence(&sequence) || generated_count >= requested {
                    should_stop = true;
                    break;
                }
            }
            if should_stop || generation_max_time_reached(generation_started, config) {
                break;
            }
        }

        Ok(VulkanTransformerGenerationSequenceOutput {
            sequence,
            prompt_length: prompt.len(),
            scores: scores_output,
            logits: logits_output,
            hidden_states: None,
            attentions: None,
            cross_attentions: None,
            sequence_score: None,
            beam_indices: None,
        })
    }

