    /// Project one already-computed decoder hidden row through the model's
    /// output embedding exactly as Hugging Face's DoLa generator calls
    /// `model.get_output_embeddings()(hidden_state)`. This intentionally skips
    /// terminal model-level logit scaling/soft-capping: those transformations
    /// are present in the mature `outputs.logits`, but the upstream premature
    /// branch invokes the output embedding module directly.
    fn generation_project_dola_hidden(&self, hidden: &[f32]) -> Result<Vec<f32>> {
        let expected_input_dim = self
            .lm_head
            .as_ref()
            .map(|head| head.input_dim)
            .unwrap_or_else(|| self.shared_embedding.context_dim());
        if hidden.len() != expected_input_dim {
            bail!(
                "DoLa premature hidden width {} does not match output embedding input width {expected_input_dim}",
                hidden.len()
            );
        }

        let input = GpuBuffer::from_f32(&self.device, hidden)?;
        let output = GpuBuffer::zeros_f32(&self.device, self.config.vocab_size)?;
        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        if let Some(lm_head) = self.lm_head.as_ref() {
            lm_head.record_forward(&mut commands, &self.kernels, &input, &output, 1)?;
        } else {
            let push = LinearPush {
                rows: 1,
                input_dim: expected_input_dim as u32,
                output_dim: self.config.vocab_size as u32,
            };
            self.kernels.linear_forward.record_dispatch(
                &mut commands,
                &[&input, self.shared_embedding.weight_buffer(), &output],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(self.config.vocab_size, 16), 1, 1],
            )?;
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                let bias_push = BiasPush {
                    rows: 1,
                    dim: self.config.vocab_size as u32,
                };
                self.kernels.bias_add.record_dispatch(
                    &mut commands,
                    &[&output, &lm_head_bias.values],
                    bytemuck::bytes_of(&bias_push),
                    [div_ceil_u32(self.config.vocab_size, 256), 1, 1],
                )?;
            }
        }
        commands.submit()?;
        output.read_f32(self.config.vocab_size)
    }

    fn generation_dola_step_with_context(
        &self,
        sequence: &[u32],
        config: &VulkanTransformerGenerationConfig,
        candidate_layers: &[usize],
        step: usize,
        is_last_step: bool,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<(u32, Vec<f32>, Vec<f32>)> {
        if encoder_hidden_states.is_some() || encoder_attention_mask.is_some() {
            bail!("DoLa decoding is only available for decoder-only models");
        }
        let final_logits = self.generation_last_logits(sequence, None, None)?;
        let hidden_states =
            self.generation_hidden_states_for_last_forward(sequence.len(), config.use_cache, step)?;
        let mut candidate_logits = Vec::with_capacity(candidate_layers.len());
        for &layer_index in candidate_layers {
            let hidden_state = hidden_states.get(layer_index).with_context(|| {
                format!(
                    "DoLa premature layer {layer_index} is unavailable from {} hidden-state slots",
                    hidden_states.len()
                )
            })?;
            if hidden_state.rows == 0 {
                bail!("DoLa premature layer {layer_index} returned no hidden-state rows");
            }
            let row_start = (hidden_state.rows - 1) * hidden_state.hidden_size;
            let row_end = row_start + hidden_state.hidden_size;
            candidate_logits.push((
                layer_index,
                self.generation_project_dola_hidden(&hidden_state.values[row_start..row_end])?,
            ));
        }

        let contrast_logits = generation_dola_select_contrast(&candidate_logits, &final_logits)?;
        let scores = self.generation_processed_non_beam_scores_with_cfg(
            &contrast_logits,
            sequence,
            config,
            step,
            is_last_step,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        let next_token = if config.do_sample {
            generation_sample_processed_scores(&scores, config.seed, step as u64)?
        } else {
            generation_argmax(&scores)?
        };
        Ok((next_token, final_logits, scores))
    }

    fn generate_dola_output_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<VulkanTransformerGenerationSequenceOutput> {
        if encoder_hidden_states.is_some() || encoder_attention_mask.is_some() {
            bail!("DoLa decoding is only available for decoder-only models");
        }
        let dola_layers = config
            .dola_layers
            .as_ref()
            .context("DoLa generation requires dola_layers")?;
        let candidate_layers = generation_dola_candidate_layers(
            dola_layers,
            self.config.num_layers,
            self.config.tie_word_embeddings,
        )?;
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        let collect_scores = config.return_dict_in_generate && config.output_scores;
        let collect_logits = config.return_dict_in_generate && config.output_logits;
        let mut sequence = prompt.to_vec();
        let mut scores_output = collect_scores.then(|| Vec::with_capacity(requested));
        let mut logits_output = collect_logits.then(|| Vec::with_capacity(requested));
        let generation_started = Instant::now();

        for step in 0..requested {
            let (next_token, logits, scores) = self.generation_dola_step_with_context(
                &sequence,
                config,
                &candidate_layers,
                step,
                step + 1 == requested,
                None,
                None,
            )?;
            if let Some(output) = logits_output.as_mut() {
                // HF DoLa exposes the mature model logits, not the contrasted
                // distribution, through `output_logits`.
                output.push(logits);
            }
            if let Some(output) = scores_output.as_mut() {
                output.push(scores);
            }
            sequence.push(next_token);
            if config.should_stop_sequence(&sequence)
                || generation_max_time_reached(generation_started, config)
            {
                break;
            }
        }

        Ok(VulkanTransformerGenerationSequenceOutput {
            sequence,
            prompt_length: prompt.len(),
            scores: scores_output,
            logits: logits_output,
            hidden_states: None,
            attentions: None,
            cross_attentions: None,
            sequence_score: None,
            beam_indices: None,
        })
    }

    fn generate_dola_ids_with_context<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        requested: usize,
        mut on_token: F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        if encoder_hidden_states.is_some() || encoder_attention_mask.is_some() {
            bail!("DoLa decoding is only available for decoder-only models");
        }
        let dola_layers = config
            .dola_layers
            .as_ref()
            .context("DoLa generation requires dola_layers")?;
        let candidate_layers = generation_dola_candidate_layers(
            dola_layers,
            self.config.num_layers,
            self.config.tie_word_embeddings,
        )?;
        let mut sequence = prompt.to_vec();
        let mut generated = Vec::with_capacity(requested);
        let generation_started = Instant::now();
        for step in 0..requested {
            let (next_token, _, _) = self.generation_dola_step_with_context(
                &sequence,
                config,
                &candidate_layers,
                step,
                step + 1 == requested,
                None,
                None,
            )?;
            generated.push(next_token);
            sequence.push(next_token);
            on_token(next_token)?;
            if config.should_stop_sequence(&sequence)
                || generation_max_time_reached(generation_started, config)
            {
                break;
            }
        }
        Ok(generated)
    }

    fn generation_contrastive_step_with_context(
        &self,
        sequence: &[u32],
        config: &VulkanTransformerGenerationConfig,
        step: usize,
        is_last_step: bool,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<(u32, Vec<f32>, Vec<f32>)> {
        let penalty_alpha = config
            .penalty_alpha
            .filter(|value| *value > 0.0)
            .context("contrastive generation requires penalty_alpha > 0")?;
        let (logits, context_hidden, hidden_size) = self
            .generation_last_logits_and_decoder_hidden(
                sequence,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
        let scores = self.generation_processed_non_beam_scores_with_cfg(
            &logits,
            sequence,
            config,
            step,
            is_last_step,
            encoder_hidden_states,
            encoder_attention_mask,
        )?;
        let recalled = generation_contrastive_top_k(&scores, config.top_k)?;
        let mut candidates = Vec::with_capacity(recalled.len());
        for (token, probability) in recalled {
            let mut candidate_sequence = sequence.to_vec();
            candidate_sequence.push(token);
            let (_, candidate_hidden, candidate_hidden_size) = self
                .generation_last_logits_and_decoder_hidden(
                    &candidate_sequence,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
            if candidate_hidden_size != hidden_size {
                bail!(
                    "contrastive generation hidden-state width changed between candidate forwards"
                );
            }
            let row_start = (candidate_sequence.len() - 1) * hidden_size;
            candidates.push((
                token,
                probability,
                candidate_hidden[row_start..row_start + hidden_size].to_vec(),
            ));
        }
        let next_token = generation_select_contrastive_candidate(
            &context_hidden,
            hidden_size,
            &candidates,
            penalty_alpha,
        )?;
        Ok((next_token, logits, scores))
    }

    fn generate_contrastive_output_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<VulkanTransformerGenerationSequenceOutput> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        let collect_scores = config.return_dict_in_generate && config.output_scores;
        let collect_logits = config.return_dict_in_generate && config.output_logits;
        let mut sequence = prompt.to_vec();
        let mut scores_output = collect_scores.then(|| Vec::with_capacity(requested));
        let mut logits_output = collect_logits.then(|| Vec::with_capacity(requested));
        let generation_started = Instant::now();

        for step in 0..requested {
            let (next_token, logits, scores) = self.generation_contrastive_step_with_context(
                &sequence,
                config,
                step,
                step + 1 == requested,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            if let Some(output) = logits_output.as_mut() {
                output.push(logits);
            }
            if let Some(output) = scores_output.as_mut() {
                output.push(scores);
            }
            sequence.push(next_token);
            if config.should_stop_sequence(&sequence)
                || generation_max_time_reached(generation_started, config)
            {
                break;
            }
        }

        Ok(VulkanTransformerGenerationSequenceOutput {
            sequence,
            prompt_length: prompt.len(),
            scores: scores_output,
            logits: logits_output,
            hidden_states: None,
            attentions: None,
            cross_attentions: None,
            sequence_score: None,
            beam_indices: None,
        })
    }

    fn generate_contrastive_ids_with_context<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        requested: usize,
        mut on_token: F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        let mut sequence = prompt.to_vec();
        let mut generated = Vec::with_capacity(requested);
        let generation_started = Instant::now();
        for step in 0..requested {
            let (next_token, _, _) = self.generation_contrastive_step_with_context(
                &sequence,
                config,
                step,
                step + 1 == requested,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            generated.push(next_token);
            sequence.push(next_token);
            on_token(next_token)?;
            if config.should_stop_sequence(&sequence)
                || generation_max_time_reached(generation_started, config)
            {
                break;
            }
        }
        Ok(generated)
    }

    fn generate_single_beam_ids_with_kv_cache<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        requested: usize,
        on_token: &mut F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        if requested == 0 {
            return Ok(Vec::new());
        }
        let (mut logits, cache) =
            self.generation_prefill_kv_cache_with_policy(prompt, config.uses_paged_kv_cache())?;
        let mut sequence = prompt.to_vec();
        let mut generated = Vec::with_capacity(requested);
        let generation_started = Instant::now();
        for step in 0..requested {
            let scores = self.generation_processed_non_beam_scores_with_cfg(
                &logits,
                &sequence,
                config,
                step,
                step + 1 == requested,
                None,
                None,
            )?;
            let next_token = if config.do_sample {
                generation_sample_processed_scores(&scores, config.seed, step as u64)?
            } else {
                generation_argmax(&scores)?
            };
            generated.push(next_token);
            sequence.push(next_token);
            on_token(next_token)?;
            if config.should_stop_sequence(&sequence)
                || generation_max_time_reached(generation_started, config)
            {
                break;
            }
            if step + 1 < requested {
                logits =
                    self.generation_cached_step_logits(next_token, &cache, sequence.len() - 1)?;
            }
        }
        Ok(generated)
    }

    fn generate_single_beam_ids_with_context<F>(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        mut on_token: F,
    ) -> Result<Vec<u32>>
    where
        F: FnMut(u32) -> Result<()>,
    {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        if config.generation_mode() == VulkanTransformerGenerationMode::AssistedGeneration {
            if config.assistant_early_exit.is_some() {
                let output = self.generate_early_exit_assisted_output(
                    prompt,
                    config,
                    encoder_hidden_states,
                    encoder_attention_mask,
                    &mut on_token,
                )?;
                return Ok(output.generated_ids().to_vec());
            }
            let output = self.generate_prompt_lookup_assisted_output_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
                &mut on_token,
            )?;
            return Ok(output.generated_ids().to_vec());
        }
        if config.generation_mode() == VulkanTransformerGenerationMode::ContrastiveSearch {
            return self.generate_contrastive_ids_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
                requested,
                &mut on_token,
            );
        }
        if config.generation_mode() == VulkanTransformerGenerationMode::DolaGeneration {
            return self.generate_dola_ids_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
                requested,
                &mut on_token,
            );
        }
        if config.use_cache
            && self.supports_generation_kv_cache()
            && encoder_hidden_states.is_none()
            && encoder_attention_mask.is_none()
        {
            return self.generate_single_beam_ids_with_kv_cache(
                prompt,
                config,
                requested,
                &mut on_token,
            );
        }
        let mut sequence = prompt.to_vec();
        let mut generated = Vec::with_capacity(requested);
        let generation_started = Instant::now();
        for step in 0..requested {
            let logits = self.generation_last_logits(
                &sequence,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            let scores = self.generation_processed_non_beam_scores_with_cfg(
                &logits,
                &sequence,
                config,
                step,
                step + 1 == requested,
                encoder_hidden_states,
                encoder_attention_mask,
            )?;
            let next_token = if config.do_sample {
                generation_sample_processed_scores(&scores, config.seed, step as u64)?
            } else {
                generation_argmax(&scores)?
            };
            generated.push(next_token);
            sequence.push(next_token);
            on_token(next_token)?;
            if config.should_stop_sequence(&sequence)
                || generation_max_time_reached(generation_started, config)
            {
                break;
            }
        }
        Ok(generated)
    }

    fn generate_beam_ids_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<u32>> {
        self.generate_beam_sequences_with_context(
            prompt,
            config,
            encoder_hidden_states,
            encoder_attention_mask,
        )?
        .into_iter()
        .next()
        .context("beam search produced no hypotheses")
    }

    fn generate_beam_sequences_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<Vec<u32>>> {
        if config.generation_mode() == VulkanTransformerGenerationMode::ConstrainedBeamSearch {
            if config.use_cache
                && self.supports_generation_kv_cache()
                && encoder_hidden_states.is_none()
                && encoder_attention_mask.is_none()
            {
                return self.generate_constrained_beam_sequences_with_kv_cache(prompt, config);
            }
            return self.generate_constrained_beam_sequences_full_prefix_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
            );
        }
        if config.generation_mode() == VulkanTransformerGenerationMode::GroupBeamSearch {
            if config.use_cache
                && self.supports_generation_kv_cache()
                && encoder_hidden_states.is_none()
                && encoder_attention_mask.is_none()
            {
                return self.generate_group_beam_sequences_with_kv_cache(prompt, config);
            }
            return self.generate_group_beam_sequences_full_prefix_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
            );
        }
        if config.use_cache
            && self.supports_generation_kv_cache()
            && encoder_hidden_states.is_none()
            && encoder_attention_mask.is_none()
        {
            return self.generate_beam_sequences_with_kv_cache(prompt, config);
        }
        self.generate_beam_sequences_full_prefix_with_context(
            prompt,
            config,
            encoder_hidden_states,
            encoder_attention_mask,
        )
    }

    fn generate_constrained_beam_sequences_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<Vec<u32>>> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        if requested == 0 {
            return Ok(vec![Vec::new(); config.num_return_sequences]);
        }
        let constraints = generation_force_constraints_from_config(config)?;
        let mut active = vec![VulkanGenerationBeam {
            tokens: prompt.to_vec(),
            score: 0.0,
        }];
        let mut completed = Vec::new();
        let generation_started = Instant::now();

        for step in 0..requested {
            let mut histories = Vec::with_capacity(active.len());
            let mut accumulated_scores = Vec::with_capacity(active.len());
            let mut processed_scores = Vec::with_capacity(active.len());
            for beam in &active {
                let logits = self.generation_last_logits(
                    &beam.tokens,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                let scores = self.generation_beam_processed_log_probs_with_cfg(
                    &logits,
                    &beam.tokens,
                    config,
                    step,
                    step + 1 == requested,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                histories.push(beam.tokens.clone());
                accumulated_scores.push(beam.score);
                processed_scores.push(scores);
            }

            let (selected, finished) = generation_select_constrained_beam_step(
                &histories,
                &accumulated_scores,
                &processed_scores,
                &constraints,
                config,
                step,
            )?;
            for candidate in finished {
                let mut beam = VulkanGenerationBeam {
                    tokens: active[candidate.parent_index].tokens.clone(),
                    score: candidate.score,
                };
                beam.tokens.push(candidate.token);
                completed.push(beam);
            }
            generation_trim_completed_beams(
                &mut completed,
                prompt.len(),
                config.num_beams,
                config.length_penalty,
            );

            let mut next = Vec::with_capacity(selected.len());
            for candidate in selected {
                let mut beam = VulkanGenerationBeam {
                    tokens: active[candidate.parent_index].tokens.clone(),
                    score: candidate.score,
                };
                beam.tokens.push(candidate.token);
                next.push(beam);
            }
            active = next;

            if active.is_empty()
                || generation_max_time_reached(generation_started, config)
                || generation_beam_should_stop(
                    active.iter(),
                    &completed,
                    prompt.len(),
                    requested,
                    config,
                )
            {
                break;
            }
        }

        generation_finalize_constrained_beams(completed, active, prompt.len(), &constraints, config)
    }

    fn generate_constrained_beam_sequences_with_kv_cache(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<Vec<u32>>> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        if requested == 0 {
            return Ok(vec![Vec::new(); config.num_return_sequences]);
        }
        let constraints = generation_force_constraints_from_config(config)?;
        let (logits, cache) =
            self.generation_prefill_kv_cache_with_policy(prompt, config.uses_paged_kv_cache())?;
        let mut active = vec![VulkanGenerationCachedBeam {
            beam: VulkanGenerationBeam {
                tokens: prompt.to_vec(),
                score: 0.0,
            },
            logits,
            cache,
        }];
        let mut completed = Vec::new();
        let generation_started = Instant::now();

        for step in 0..requested {
            let histories = active
                .iter()
                .map(|cached| cached.beam.tokens.clone())
                .collect::<Vec<_>>();
            let accumulated_scores = active
                .iter()
                .map(|cached| cached.beam.score)
                .collect::<Vec<_>>();
            let mut processed_scores = Vec::with_capacity(active.len());
            for cached in &active {
                processed_scores.push(self.generation_beam_processed_log_probs_with_cfg(
                    &cached.logits,
                    &cached.beam.tokens,
                    config,
                    step,
                    step + 1 == requested,
                    None,
                    None,
                )?);
            }

            let (selected, finished) = generation_select_constrained_beam_step(
                &histories,
                &accumulated_scores,
                &processed_scores,
                &constraints,
                config,
                step,
            )?;
            for candidate in finished {
                let mut beam = VulkanGenerationBeam {
                    tokens: active[candidate.parent_index].beam.tokens.clone(),
                    score: candidate.score,
                };
                beam.tokens.push(candidate.token);
                completed.push(beam);
            }
            generation_trim_completed_beams(
                &mut completed,
                prompt.len(),
                config.num_beams,
                config.length_penalty,
            );

            let mut pending = Vec::with_capacity(selected.len());
            for candidate in selected {
                let mut beam = VulkanGenerationBeam {
                    tokens: active[candidate.parent_index].beam.tokens.clone(),
                    score: candidate.score,
                };
                beam.tokens.push(candidate.token);
                pending.push((candidate.parent_index, beam));
            }

            let stop_after_selection = pending.is_empty()
                || step + 1 >= requested
                || generation_max_time_reached(generation_started, config)
                || generation_beam_should_stop(
                    pending.iter().map(|(_, beam)| beam),
                    &completed,
                    prompt.len(),
                    requested,
                    config,
                );
            if stop_after_selection {
                let active_beams = pending.into_iter().map(|(_, beam)| beam).collect();
                return generation_finalize_constrained_beams(
                    completed,
                    active_beams,
                    prompt.len(),
                    &constraints,
                    config,
                );
            }

            let mut next_active = Vec::with_capacity(pending.len());
            for (parent_index, beam) in pending {
                let parent = &active[parent_index];
                let cache =
                    self.generation_clone_kv_cache_prefix(&parent.cache, parent.beam.tokens.len())?;
                let token = *beam
                    .tokens
                    .last()
                    .context("constrained-beam candidate has no terminal token")?;
                let logits = self.generation_cached_step_logits(
                    token,
                    &cache,
                    beam.tokens.len().saturating_sub(1),
                )?;
                next_active.push(VulkanGenerationCachedBeam {
                    beam,
                    logits,
                    cache,
                });
            }
            active = next_active;
        }

        generation_finalize_constrained_beams(
            completed,
            active.into_iter().map(|cached| cached.beam).collect(),
            prompt.len(),
            &constraints,
            config,
        )
    }

    fn generate_group_beam_sequences_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<Vec<u32>>> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        if requested == 0 {
            return Ok(vec![Vec::new(); config.num_return_sequences]);
        }
        let num_groups = config
            .num_beam_groups
            .filter(|groups| *groups > 1)
            .context("group beam search requires num_beam_groups > 1")?;
        let group_width = config.num_beams / num_groups;
        let diversity_penalty = config.diversity_penalty.unwrap_or(0.0);
        let mut active_groups = (0..num_groups)
            .map(|_| {
                vec![VulkanGenerationBeam {
                    tokens: prompt.to_vec(),
                    score: 0.0,
                }]
            })
            .collect::<Vec<_>>();
        let mut completed_groups = (0..num_groups)
            .map(|_| Vec::<VulkanGenerationBeam>::new())
            .collect::<Vec<_>>();
        let generation_started = Instant::now();

        for step in 0..requested {
            let mut previous_group_tokens = Vec::<u32>::with_capacity(config.num_beams);
            let mut next_groups = (0..num_groups)
                .map(|_| Vec::<VulkanGenerationBeam>::new())
                .collect::<Vec<_>>();

            for group_index in 0..num_groups {
                if active_groups[group_index].is_empty() {
                    continue;
                }
                let mut candidates = Vec::new();
                for (parent_index, beam) in active_groups[group_index].iter().enumerate() {
                    let logits = self.generation_last_logits(
                        &beam.tokens,
                        encoder_hidden_states,
                        encoder_attention_mask,
                    )?;
                    let mut log_probs = self.generation_beam_processed_log_probs_with_cfg(
                        &logits,
                        &beam.tokens,
                        config,
                        step,
                        step + 1 == requested,
                        encoder_hidden_states,
                        encoder_attention_mask,
                    )?;
                    generation_apply_hamming_diversity(
                        &mut log_probs,
                        &previous_group_tokens,
                        diversity_penalty,
                    );
                    for (token, log_probability) in log_probs
                        .iter()
                        .copied()
                        .enumerate()
                        .filter(|(_, score)| score.is_finite())
                    {
                        let token =
                            u32::try_from(token).context("generation token index exceeds u32")?;
                        candidates.push(VulkanGenerationBeamCandidate {
                            parent_index,
                            token,
                            score: beam.score + f64::from(log_probability),
                            finished: config.should_stop_after_token(&beam.tokens, token),
                        });
                    }
                }

                let selected = generation_select_beam_candidates_for_width(
                    candidates,
                    config,
                    step,
                    group_width,
                )?;
                let mut next = Vec::new();
                for (selection_index, candidate) in selected.into_iter().enumerate() {
                    let parent = &active_groups[group_index][candidate.parent_index];
                    let mut beam = VulkanGenerationBeam {
                        tokens: parent.tokens.clone(),
                        score: candidate.score,
                    };
                    beam.tokens.push(candidate.token);
                    if candidate.finished {
                        if selection_index < group_width {
                            completed_groups[group_index].push(beam);
                        }
                    } else {
                        next.push(beam);
                    }
                }
                next.sort_by(|left, right| {
                    right
                        .score
                        .total_cmp(&left.score)
                        .then_with(|| left.tokens.cmp(&right.tokens))
                });
                next.truncate(group_width);
                generation_trim_completed_beams(
                    &mut completed_groups[group_index],
                    prompt.len(),
                    group_width,
                    config.length_penalty,
                );

                previous_group_tokens
                    .extend(next.iter().filter_map(|beam| beam.tokens.last().copied()));
                let group_done = next.is_empty()
                    || generation_beam_should_stop_for_width(
                        next.iter(),
                        &completed_groups[group_index],
                        prompt.len(),
                        requested,
                        group_width,
                        config,
                    );
                if !group_done {
                    next_groups[group_index] = next;
                }
            }

            active_groups = next_groups;
            let stop_after_step = step + 1 >= requested
                || generation_max_time_reached(generation_started, config)
                || active_groups.iter().all(Vec::is_empty);
            if stop_after_step {
                for group_index in 0..num_groups {
                    completed_groups[group_index].append(&mut active_groups[group_index]);
                    generation_trim_completed_beams(
                        &mut completed_groups[group_index],
                        prompt.len(),
                        group_width,
                        config.length_penalty,
                    );
                }
                break;
            }
        }

        let completed = completed_groups.into_iter().flatten().collect::<Vec<_>>();
        generation_finalize_beams(completed, prompt.len(), config)
    }

    fn generate_group_beam_sequences_with_kv_cache(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<Vec<u32>>> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        if requested == 0 {
            return Ok(vec![Vec::new(); config.num_return_sequences]);
        }
        let num_groups = config
            .num_beam_groups
            .filter(|groups| *groups > 1)
            .context("group beam search requires num_beam_groups > 1")?;
        let group_width = config.num_beams / num_groups;
        let diversity_penalty = config.diversity_penalty.unwrap_or(0.0);
        let (initial_logits, initial_cache) =
            self.generation_prefill_kv_cache_with_policy(prompt, config.uses_paged_kv_cache())?;
        let mut original_cache = Some(initial_cache);
        let mut active_groups = Vec::with_capacity(num_groups);
        for group_index in 0..num_groups {
            let cache = if group_index + 1 == num_groups {
                original_cache
                    .take()
                    .context("missing initial group-beam KV cache")?
            } else {
                self.generation_clone_kv_cache_prefix(
                    original_cache
                        .as_ref()
                        .context("missing initial group-beam KV cache")?,
                    prompt.len(),
                )?
            };
            active_groups.push(vec![VulkanGenerationCachedBeam {
                beam: VulkanGenerationBeam {
                    tokens: prompt.to_vec(),
                    score: 0.0,
                },
                logits: initial_logits.clone(),
                cache,
            }]);
        }
        let mut completed_groups = (0..num_groups)
            .map(|_| Vec::<VulkanGenerationBeam>::new())
            .collect::<Vec<_>>();
        let generation_started = Instant::now();

        for step in 0..requested {
            let mut previous_group_tokens = Vec::<u32>::with_capacity(config.num_beams);
            let mut pending_groups = (0..num_groups)
                .map(|_| Vec::<(usize, VulkanGenerationBeam)>::new())
                .collect::<Vec<_>>();

            for group_index in 0..num_groups {
                if active_groups[group_index].is_empty() {
                    continue;
                }
                let mut candidates = Vec::new();
                for (parent_index, cached_beam) in active_groups[group_index].iter().enumerate() {
                    let mut log_probs = self.generation_beam_processed_log_probs_with_cfg(
                        &cached_beam.logits,
                        &cached_beam.beam.tokens,
                        config,
                        step,
                        step + 1 == requested,
                        None,
                        None,
                    )?;
                    generation_apply_hamming_diversity(
                        &mut log_probs,
                        &previous_group_tokens,
                        diversity_penalty,
                    );
                    for (token, log_probability) in log_probs
                        .iter()
                        .copied()
                        .enumerate()
                        .filter(|(_, score)| score.is_finite())
                    {
                        let token =
                            u32::try_from(token).context("generation token index exceeds u32")?;
                        candidates.push(VulkanGenerationBeamCandidate {
                            parent_index,
                            token,
                            score: cached_beam.beam.score + f64::from(log_probability),
                            finished: config
                                .should_stop_after_token(&cached_beam.beam.tokens, token),
                        });
                    }
                }

                let selected = generation_select_beam_candidates_for_width(
                    candidates,
                    config,
                    step,
                    group_width,
                )?;
                let mut next = Vec::new();
                for (selection_index, candidate) in selected.into_iter().enumerate() {
                    let parent = &active_groups[group_index][candidate.parent_index];
                    let mut beam = VulkanGenerationBeam {
                        tokens: parent.beam.tokens.clone(),
                        score: candidate.score,
                    };
                    beam.tokens.push(candidate.token);
                    if candidate.finished {
                        if selection_index < group_width {
                            completed_groups[group_index].push(beam);
                        }
                    } else {
                        next.push((candidate.parent_index, beam));
                    }
                }
                next.sort_by(|(_, left), (_, right)| {
                    right
                        .score
                        .total_cmp(&left.score)
                        .then_with(|| left.tokens.cmp(&right.tokens))
                });
                next.truncate(group_width);
                generation_trim_completed_beams(
                    &mut completed_groups[group_index],
                    prompt.len(),
                    group_width,
                    config.length_penalty,
                );
                previous_group_tokens.extend(
                    next.iter()
                        .filter_map(|(_, beam)| beam.tokens.last().copied()),
                );
                let group_done = next.is_empty()
                    || generation_beam_should_stop_for_width(
                        next.iter().map(|(_, beam)| beam),
                        &completed_groups[group_index],
                        prompt.len(),
                        requested,
                        group_width,
                        config,
                    );
                if !group_done {
                    pending_groups[group_index] = next;
                }
            }

            let stop_after_step = step + 1 >= requested
                || generation_max_time_reached(generation_started, config)
                || pending_groups.iter().all(Vec::is_empty);
            if stop_after_step {
                for group_index in 0..num_groups {
                    completed_groups[group_index]
                        .extend(pending_groups[group_index].drain(..).map(|(_, beam)| beam));
                    generation_trim_completed_beams(
                        &mut completed_groups[group_index],
                        prompt.len(),
                        group_width,
                        config.length_penalty,
                    );
                }
                break;
            }

            let mut next_active_groups = (0..num_groups)
                .map(|_| Vec::<VulkanGenerationCachedBeam>::new())
                .collect::<Vec<_>>();
            for group_index in 0..num_groups {
                for (parent_index, beam) in pending_groups[group_index].drain(..) {
                    let parent = &active_groups[group_index][parent_index];
                    let cache = self.generation_clone_kv_cache_prefix(
                        &parent.cache,
                        parent.beam.tokens.len(),
                    )?;
                    let token = *beam
                        .tokens
                        .last()
                        .context("group-beam candidate has no terminal token")?;
                    let logits = self.generation_cached_step_logits(
                        token,
                        &cache,
                        beam.tokens.len().saturating_sub(1),
                    )?;
                    next_active_groups[group_index].push(VulkanGenerationCachedBeam {
                        beam,
                        logits,
                        cache,
                    });
                }
            }
            active_groups = next_active_groups;
        }

        let completed = completed_groups.into_iter().flatten().collect::<Vec<_>>();
        generation_finalize_beams(completed, prompt.len(), config)
    }

    fn generate_beam_ids_with_kv_cache(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<u32>> {
        self.generate_beam_sequences_with_kv_cache(prompt, config)?
            .into_iter()
            .next()
            .context("beam search produced no hypotheses")
    }

    fn generate_beam_sequences_with_kv_cache(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
    ) -> Result<Vec<Vec<u32>>> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        if requested == 0 {
            return Ok(vec![Vec::new(); config.num_return_sequences]);
        }
        let (logits, cache) =
            self.generation_prefill_kv_cache_with_policy(prompt, config.uses_paged_kv_cache())?;
        let mut active = vec![VulkanGenerationCachedBeam {
            beam: VulkanGenerationBeam {
                tokens: prompt.to_vec(),
                score: 0.0,
            },
            logits,
            cache,
        }];
        let mut completed = Vec::new();
        let generation_started = Instant::now();

        for step in 0..requested {
            let mut candidates = Vec::new();
            for (parent_index, cached_beam) in active.iter().enumerate() {
                let log_probs = self.generation_beam_processed_log_probs_with_cfg(
                    &cached_beam.logits,
                    &cached_beam.beam.tokens,
                    config,
                    step,
                    step + 1 == requested,
                    None,
                    None,
                )?;
                for (token, log_probability) in log_probs
                    .iter()
                    .copied()
                    .enumerate()
                    .filter(|(_, score)| score.is_finite())
                {
                    let token =
                        u32::try_from(token).context("generation token index exceeds u32")?;
                    candidates.push(VulkanGenerationBeamCandidate {
                        parent_index,
                        token,
                        score: cached_beam.beam.score + f64::from(log_probability),
                        finished: config.should_stop_after_token(&cached_beam.beam.tokens, token),
                    });
                }
            }

            let selected = generation_select_beam_candidates(candidates, config, step)?;
            let mut next = Vec::new();
            for (selection_index, candidate) in selected.into_iter().enumerate() {
                let parent = &active[candidate.parent_index];
                let mut beam = VulkanGenerationBeam {
                    tokens: parent.beam.tokens.clone(),
                    score: candidate.score,
                };
                beam.tokens.push(candidate.token);
                if candidate.finished {
                    // HF only promotes a finished sequence when it appears in
                    // the leading num_beams candidate slots. Extra candidates
                    // exist solely to preserve enough non-EOS continuations.
                    if selection_index < config.num_beams {
                        completed.push(beam);
                    }
                } else {
                    next.push((candidate.parent_index, beam));
                }
            }
            next.sort_by(|(_, left), (_, right)| {
                right
                    .score
                    .total_cmp(&left.score)
                    .then_with(|| left.tokens.cmp(&right.tokens))
            });
            next.truncate(config.num_beams);

            let stop_after_selection = next.is_empty()
                || step + 1 >= requested
                || generation_max_time_reached(generation_started, config)
                || generation_beam_should_stop(
                    next.iter().map(|(_, beam)| beam),
                    &completed,
                    prompt.len(),
                    requested,
                    config,
                );
            if stop_after_selection {
                completed.extend(next.into_iter().map(|(_, beam)| beam));
                break;
            }

            let mut next_active = Vec::with_capacity(next.len());
            for (parent_index, beam) in next {
                let parent = &active[parent_index];
                let cache =
                    self.generation_clone_kv_cache_prefix(&parent.cache, parent.beam.tokens.len())?;
                let token = *beam
                    .tokens
                    .last()
                    .context("beam-search candidate has no terminal token")?;
                let logits = self.generation_cached_step_logits(
                    token,
                    &cache,
                    beam.tokens.len().saturating_sub(1),
                )?;
                next_active.push(VulkanGenerationCachedBeam {
                    beam,
                    logits,
                    cache,
                });
            }
            active = next_active;
        }

        if completed.is_empty() {
            completed.extend(active.into_iter().map(|cached| cached.beam));
        }
        generation_finalize_beams(completed, prompt.len(), config)
    }

    fn generate_beam_ids_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<u32>> {
        self.generate_beam_sequences_full_prefix_with_context(
            prompt,
            config,
            encoder_hidden_states,
            encoder_attention_mask,
        )?
        .into_iter()
        .next()
        .context("beam search produced no hypotheses")
    }

    fn generate_beam_sequences_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<Vec<u32>>> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        if requested == 0 {
            return Ok(vec![Vec::new(); config.num_return_sequences]);
        }
        let mut active = vec![VulkanGenerationBeam {
            tokens: prompt.to_vec(),
            score: 0.0,
        }];
        let mut completed = Vec::new();
        let generation_started = Instant::now();

        for step in 0..requested {
            let mut candidates = Vec::new();
            for (parent_index, beam) in active.iter().enumerate() {
                let logits = self.generation_last_logits(
                    &beam.tokens,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                let log_probs = self.generation_beam_processed_log_probs_with_cfg(
                    &logits,
                    &beam.tokens,
                    config,
                    step,
                    step + 1 == requested,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                for (token, log_probability) in log_probs
                    .iter()
                    .copied()
                    .enumerate()
                    .filter(|(_, score)| score.is_finite())
                {
                    let token =
                        u32::try_from(token).context("generation token index exceeds u32")?;
                    candidates.push(VulkanGenerationBeamCandidate {
                        parent_index,
                        token,
                        score: beam.score + f64::from(log_probability),
                        finished: config.should_stop_after_token(&beam.tokens, token),
                    });
                }
            }

            let selected = generation_select_beam_candidates(candidates, config, step)?;
            let mut next = Vec::new();
            for (selection_index, candidate) in selected.into_iter().enumerate() {
                let parent = &active[candidate.parent_index];
                let mut beam = VulkanGenerationBeam {
                    tokens: parent.tokens.clone(),
                    score: candidate.score,
                };
                beam.tokens.push(candidate.token);
                if candidate.finished {
                    if selection_index < config.num_beams {
                        completed.push(beam);
                    }
                } else {
                    next.push(beam);
                }
            }
            next.sort_by(|left, right| {
                right
                    .score
                    .total_cmp(&left.score)
                    .then_with(|| left.tokens.cmp(&right.tokens))
            });
            next.truncate(config.num_beams);
            active = next;

            if active.is_empty()
                || generation_max_time_reached(generation_started, config)
                || generation_beam_should_stop(
                    active.iter(),
                    &completed,
                    prompt.len(),
                    requested,
                    config,
                )
            {
                break;
            }
        }

        completed.extend(active);
        generation_finalize_beams(completed, prompt.len(), config)
    }

    fn generate_group_beam_output_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<VulkanTransformerGenerationOutput> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        let collect_scores = config.return_dict_in_generate && config.output_scores;
        let collect_logits = config.return_dict_in_generate && config.output_logits;
        if requested == 0 {
            return Ok(VulkanTransformerGenerationOutput {
                sequences: (0..config.num_return_sequences)
                    .map(|_| VulkanTransformerGenerationSequenceOutput {
                        sequence: prompt.to_vec(),
                        prompt_length: prompt.len(),
                        scores: collect_scores.then(Vec::new),
                        logits: collect_logits.then(Vec::new),
                        hidden_states: None,
                        attentions: None,
                        cross_attentions: None,
                        sequence_score: collect_scores.then_some(0.0),
                        beam_indices: collect_scores.then(Vec::new),
                    })
                    .collect(),
            });
        }

        let num_groups = config
            .num_beam_groups
            .filter(|groups| *groups > 1)
            .context("group beam search requires num_beam_groups > 1")?;
        let group_width = config.num_beams / num_groups;
        let diversity_penalty = config.diversity_penalty.unwrap_or(0.0);
        let mut active_groups = (0..num_groups)
            .map(|_| {
                vec![VulkanGenerationTraceBeam {
                    tokens: prompt.to_vec(),
                    score: 0.0,
                    scores: Vec::new(),
                    logits: Vec::new(),
                    beam_indices: Vec::new(),
                }]
            })
            .collect::<Vec<_>>();
        let mut completed_groups = (0..num_groups)
            .map(|_| Vec::<VulkanGenerationTraceBeam>::new())
            .collect::<Vec<_>>();
        let generation_started = Instant::now();

        for step in 0..requested {
            let mut previous_group_tokens = Vec::<u32>::with_capacity(config.num_beams);
            let mut next_groups = (0..num_groups)
                .map(|_| Vec::<VulkanGenerationTraceBeam>::new())
                .collect::<Vec<_>>();

            for group_index in 0..num_groups {
                if active_groups[group_index].is_empty() {
                    continue;
                }
                let mut step_logits = Vec::with_capacity(active_groups[group_index].len());
                let mut step_scores = Vec::with_capacity(active_groups[group_index].len());
                let mut candidates = Vec::new();
                for (parent_index, beam) in active_groups[group_index].iter().enumerate() {
                    let logits = self.generation_last_logits(
                        &beam.tokens,
                        encoder_hidden_states,
                        encoder_attention_mask,
                    )?;
                    let mut scores = self.generation_beam_processed_log_probs_with_cfg(
                        &logits,
                        &beam.tokens,
                        config,
                        step,
                        step + 1 == requested,
                        encoder_hidden_states,
                        encoder_attention_mask,
                    )?;
                    generation_apply_hamming_diversity(
                        &mut scores,
                        &previous_group_tokens,
                        diversity_penalty,
                    );
                    for (token, log_probability) in scores
                        .iter()
                        .copied()
                        .enumerate()
                        .filter(|(_, score)| score.is_finite())
                    {
                        let token =
                            u32::try_from(token).context("generation token index exceeds u32")?;
                        candidates.push(VulkanGenerationBeamCandidate {
                            parent_index,
                            token,
                            score: beam.score + f64::from(log_probability),
                            finished: config.should_stop_after_token(&beam.tokens, token),
                        });
                    }
                    step_logits.push(logits);
                    step_scores.push(scores);
                }

                let selected = generation_select_beam_candidates_for_width(
                    candidates,
                    config,
                    step,
                    group_width,
                )?;
                let mut next = Vec::new();
                for (selection_index, candidate) in selected.into_iter().enumerate() {
                    let parent = &active_groups[group_index][candidate.parent_index];
                    let mut beam = parent.clone();
                    beam.score = candidate.score;
                    beam.tokens.push(candidate.token);
                    if collect_scores {
                        beam.scores
                            .push(step_scores[candidate.parent_index].clone());
                        beam.beam_indices
                            .push(group_index * group_width + candidate.parent_index);
                    }
                    if collect_logits {
                        beam.logits
                            .push(step_logits[candidate.parent_index].clone());
                    }
                    if candidate.finished {
                        if selection_index < group_width {
                            completed_groups[group_index].push(beam);
                        }
                    } else {
                        next.push(beam);
                    }
                }
                next.sort_by(|left, right| {
                    right
                        .score
                        .total_cmp(&left.score)
                        .then_with(|| left.tokens.cmp(&right.tokens))
                });
                next.truncate(group_width);
                generation_trim_completed_trace_beams(
                    &mut completed_groups[group_index],
                    prompt.len(),
                    group_width,
                    config.length_penalty,
                );
                previous_group_tokens
                    .extend(next.iter().filter_map(|beam| beam.tokens.last().copied()));

                let running = next
                    .iter()
                    .map(|beam| VulkanGenerationBeam {
                        tokens: beam.tokens.clone(),
                        score: beam.score,
                    })
                    .collect::<Vec<_>>();
                let finished = completed_groups[group_index]
                    .iter()
                    .map(|beam| VulkanGenerationBeam {
                        tokens: beam.tokens.clone(),
                        score: beam.score,
                    })
                    .collect::<Vec<_>>();
                let group_done = next.is_empty()
                    || generation_beam_should_stop_for_width(
                        running.iter(),
                        &finished,
                        prompt.len(),
                        requested,
                        group_width,
                        config,
                    );
                if !group_done {
                    next_groups[group_index] = next;
                }
            }

            active_groups = next_groups;
            let stop_after_step = step + 1 >= requested
                || generation_max_time_reached(generation_started, config)
                || active_groups.iter().all(Vec::is_empty);
            if stop_after_step {
                for group_index in 0..num_groups {
                    completed_groups[group_index].append(&mut active_groups[group_index]);
                    generation_trim_completed_trace_beams(
                        &mut completed_groups[group_index],
                        prompt.len(),
                        group_width,
                        config.length_penalty,
                    );
                }
                break;
            }
        }

        let mut completed = completed_groups.into_iter().flatten().collect::<Vec<_>>();
        completed.sort_by(|left, right| {
            right
                .normalized_score(prompt.len(), config.length_penalty)
                .total_cmp(&left.normalized_score(prompt.len(), config.length_penalty))
                .then_with(|| left.tokens.cmp(&right.tokens))
        });
        completed.truncate(config.num_return_sequences);
        if completed.len() < config.num_return_sequences {
            bail!(
                "group beam search produced {} hypotheses, fewer than num_return_sequences {}",
                completed.len(),
                config.num_return_sequences
            );
        }

        Ok(VulkanTransformerGenerationOutput {
            sequences: completed
                .into_iter()
                .map(|beam| {
                    let normalized_score =
                        beam.normalized_score(prompt.len(), config.length_penalty);
                    VulkanTransformerGenerationSequenceOutput {
                        sequence: beam.tokens,
                        prompt_length: prompt.len(),
                        scores: collect_scores.then_some(beam.scores),
                        logits: collect_logits.then_some(beam.logits),
                        hidden_states: None,
                        attentions: None,
                        cross_attentions: None,
                        sequence_score: collect_scores.then_some(normalized_score),
                        beam_indices: collect_scores.then_some(beam.beam_indices),
                    }
                })
                .collect(),
        })
    }

    fn generate_beam_output_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<VulkanTransformerGenerationOutput> {
        if config.generation_mode() == VulkanTransformerGenerationMode::ConstrainedBeamSearch {
            return self.generate_constrained_beam_output_full_prefix_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
            );
        }
        if config.generation_mode() == VulkanTransformerGenerationMode::GroupBeamSearch {
            return self.generate_group_beam_output_full_prefix_with_context(
                prompt,
                config,
                encoder_hidden_states,
                encoder_attention_mask,
            );
        }
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        let collect_scores = config.return_dict_in_generate && config.output_scores;
        let collect_logits = config.return_dict_in_generate && config.output_logits;
        if requested == 0 {
            return Ok(VulkanTransformerGenerationOutput {
                sequences: (0..config.num_return_sequences)
                    .map(|_| VulkanTransformerGenerationSequenceOutput {
                        sequence: prompt.to_vec(),
                        prompt_length: prompt.len(),
                        scores: collect_scores.then(Vec::new),
                        logits: collect_logits.then(Vec::new),
                        hidden_states: None,
                        attentions: None,
                        cross_attentions: None,
                        sequence_score: collect_scores.then_some(0.0),
                        beam_indices: collect_scores.then(Vec::new),
                    })
                    .collect(),
            });
        }

        // The structured path deliberately uses the full-prefix reference
        // executor. This makes raw logits and processed scores directly
        // inspectable while the existing continuation-only beam APIs retain
        // the optimized KV-cache path where supported.
        let mut active = vec![VulkanGenerationTraceBeam {
            tokens: prompt.to_vec(),
            score: 0.0,
            scores: Vec::new(),
            logits: Vec::new(),
            beam_indices: Vec::new(),
        }];
        let mut completed = Vec::<VulkanGenerationTraceBeam>::new();
        let generation_started = Instant::now();

        for step in 0..requested {
            let mut step_logits = Vec::with_capacity(active.len());
            let mut step_scores = Vec::with_capacity(active.len());
            let mut candidates = Vec::new();
            for (parent_index, beam) in active.iter().enumerate() {
                let logits = self.generation_last_logits(
                    &beam.tokens,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                let scores = self.generation_beam_processed_log_probs_with_cfg(
                    &logits,
                    &beam.tokens,
                    config,
                    step,
                    step + 1 == requested,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                for (token, log_probability) in scores
                    .iter()
                    .copied()
                    .enumerate()
                    .filter(|(_, score)| score.is_finite())
                {
                    let token =
                        u32::try_from(token).context("generation token index exceeds u32")?;
                    candidates.push(VulkanGenerationBeamCandidate {
                        parent_index,
                        token,
                        score: beam.score + f64::from(log_probability),
                        finished: config.should_stop_after_token(&beam.tokens, token),
                    });
                }
                step_logits.push(logits);
                step_scores.push(scores);
            }

            let selected = generation_select_beam_candidates(candidates, config, step)?;
            let mut next = Vec::new();
            for (selection_index, candidate) in selected.into_iter().enumerate() {
                let parent = &active[candidate.parent_index];
                let mut beam = parent.clone();
                beam.score = candidate.score;
                beam.tokens.push(candidate.token);
                if collect_scores {
                    beam.scores
                        .push(step_scores[candidate.parent_index].clone());
                    beam.beam_indices.push(candidate.parent_index);
                }
                if collect_logits {
                    beam.logits
                        .push(step_logits[candidate.parent_index].clone());
                }
                if candidate.finished {
                    if selection_index < config.num_beams {
                        completed.push(beam);
                    }
                } else {
                    next.push(beam);
                }
            }
            next.sort_by(|left, right| {
                right
                    .score
                    .total_cmp(&left.score)
                    .then_with(|| left.tokens.cmp(&right.tokens))
            });
            next.truncate(config.num_beams);
            active = next;

            let stop =
                if active.is_empty() || generation_max_time_reached(generation_started, config) {
                    true
                } else {
                    let running = active
                        .iter()
                        .map(|beam| VulkanGenerationBeam {
                            tokens: beam.tokens.clone(),
                            score: beam.score,
                        })
                        .collect::<Vec<_>>();
                    let finished = completed
                        .iter()
                        .map(|beam| VulkanGenerationBeam {
                            tokens: beam.tokens.clone(),
                            score: beam.score,
                        })
                        .collect::<Vec<_>>();
                    generation_beam_should_stop(
                        running.iter(),
                        &finished,
                        prompt.len(),
                        requested,
                        config,
                    )
                };
            if stop {
                break;
            }
        }

        completed.extend(active);
        completed.sort_by(|left, right| {
            right
                .normalized_score(prompt.len(), config.length_penalty)
                .total_cmp(&left.normalized_score(prompt.len(), config.length_penalty))
                .then_with(|| left.tokens.cmp(&right.tokens))
        });
        completed.truncate(config.num_return_sequences);
        if completed.len() < config.num_return_sequences {
            bail!(
                "beam search produced {} hypotheses, fewer than num_return_sequences {}",
                completed.len(),
                config.num_return_sequences
            );
        }

        Ok(VulkanTransformerGenerationOutput {
            sequences: completed
                .into_iter()
                .map(|beam| {
                    let normalized_score =
                        beam.normalized_score(prompt.len(), config.length_penalty);
                    VulkanTransformerGenerationSequenceOutput {
                        sequence: beam.tokens,
                        prompt_length: prompt.len(),
                        scores: collect_scores.then_some(beam.scores),
                        logits: collect_logits.then_some(beam.logits),
                        hidden_states: None,
                        attentions: None,
                        cross_attentions: None,
                        sequence_score: collect_scores.then_some(normalized_score),
                        beam_indices: collect_scores.then_some(beam.beam_indices),
                    }
                })
                .collect(),
        })
    }

    fn generate_constrained_beam_output_full_prefix_with_context(
        &self,
        prompt: &[u32],
        config: &VulkanTransformerGenerationConfig,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<VulkanTransformerGenerationOutput> {
        let requested = config.effective_max_new_tokens(prompt.len(), self.seq_len);
        let collect_scores = config.return_dict_in_generate && config.output_scores;
        let collect_logits = config.return_dict_in_generate && config.output_logits;
        if requested == 0 {
            return Ok(VulkanTransformerGenerationOutput {
                sequences: (0..config.num_return_sequences)
                    .map(|_| VulkanTransformerGenerationSequenceOutput {
                        sequence: prompt.to_vec(),
                        prompt_length: prompt.len(),
                        scores: collect_scores.then(Vec::new),
                        logits: collect_logits.then(Vec::new),
                        hidden_states: None,
                        attentions: None,
                        cross_attentions: None,
                        sequence_score: collect_scores.then_some(0.0),
                        beam_indices: collect_scores.then(Vec::new),
                    })
                    .collect(),
            });
        }

        let constraints = generation_force_constraints_from_config(config)?;
        let mut active = vec![VulkanGenerationTraceBeam {
            tokens: prompt.to_vec(),
            score: 0.0,
            scores: Vec::new(),
            logits: Vec::new(),
            beam_indices: Vec::new(),
        }];
        let mut completed = Vec::<VulkanGenerationTraceBeam>::new();
        let generation_started = Instant::now();

        for step in 0..requested {
            let histories = active
                .iter()
                .map(|beam| beam.tokens.clone())
                .collect::<Vec<_>>();
            let accumulated_scores = active.iter().map(|beam| beam.score).collect::<Vec<_>>();
            let mut step_logits = Vec::with_capacity(active.len());
            let mut step_scores = Vec::with_capacity(active.len());
            for beam in &active {
                let logits = self.generation_last_logits(
                    &beam.tokens,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                let scores = self.generation_beam_processed_log_probs_with_cfg(
                    &logits,
                    &beam.tokens,
                    config,
                    step,
                    step + 1 == requested,
                    encoder_hidden_states,
                    encoder_attention_mask,
                )?;
                step_logits.push(logits);
                step_scores.push(scores);
            }

            let (selected, finished) = generation_select_constrained_beam_step(
                &histories,
                &accumulated_scores,
                &step_scores,
                &constraints,
                config,
                step,
            )?;

            for candidate in finished {
                let parent = &active[candidate.parent_index];
                let mut beam = parent.clone();
                beam.score = candidate.score;
                beam.tokens.push(candidate.token);
                if collect_scores {
                    beam.scores
                        .push(step_scores[candidate.parent_index].clone());
                    beam.beam_indices.push(candidate.parent_index);
                }
                if collect_logits {
                    beam.logits
                        .push(step_logits[candidate.parent_index].clone());
                }
                completed.push(beam);
            }
            generation_trim_completed_trace_beams(
                &mut completed,
                prompt.len(),
                config.num_beams,
                config.length_penalty,
            );

            let mut next = Vec::with_capacity(selected.len());
            for candidate in selected {
                let parent = &active[candidate.parent_index];
                let mut beam = parent.clone();
                beam.score = candidate.score;
                beam.tokens.push(candidate.token);
                if collect_scores {
                    beam.scores
                        .push(step_scores[candidate.parent_index].clone());
                    beam.beam_indices.push(candidate.parent_index);
                }
                if collect_logits {
                    beam.logits
                        .push(step_logits[candidate.parent_index].clone());
                }
                next.push(beam);
            }
            active = next;

            let stop =
                if active.is_empty() || generation_max_time_reached(generation_started, config) {
                    true
                } else {
                    let running = active
                        .iter()
                        .map(|beam| VulkanGenerationBeam {
                            tokens: beam.tokens.clone(),
                            score: beam.score,
                        })
                        .collect::<Vec<_>>();
                    let finished = completed
                        .iter()
                        .map(|beam| VulkanGenerationBeam {
                            tokens: beam.tokens.clone(),
                            score: beam.score,
                        })
                        .collect::<Vec<_>>();
                    generation_beam_should_stop(
                        running.iter(),
                        &finished,
                        prompt.len(),
                        requested,
                        config,
                    )
                };
            if stop {
                break;
            }
        }

        let mut fallback = Vec::new();
        for beam in active {
            if generation_constraints_completed(&beam.tokens, &constraints) {
                completed.push(beam);
            } else {
                fallback.push(beam);
            }
        }
        let ranking = |left: &VulkanGenerationTraceBeam, right: &VulkanGenerationTraceBeam| {
            right
                .normalized_score(prompt.len(), config.length_penalty)
                .total_cmp(&left.normalized_score(prompt.len(), config.length_penalty))
                .then_with(|| left.tokens.cmp(&right.tokens))
        };
        completed.sort_by(ranking);
        fallback.sort_by(ranking);
        completed.truncate(config.num_return_sequences);
        if completed.len() < config.num_return_sequences {
            let missing = config.num_return_sequences - completed.len();
            completed.extend(fallback.into_iter().take(missing));
        }
        if completed.len() < config.num_return_sequences {
            bail!(
                "constrained beam search produced {} hypotheses, fewer than num_return_sequences {}",
                completed.len(),
                config.num_return_sequences
            );
        }

        Ok(VulkanTransformerGenerationOutput {
            sequences: completed
                .into_iter()
                .map(|beam| {
                    let normalized_score =
                        beam.normalized_score(prompt.len(), config.length_penalty);
                    VulkanTransformerGenerationSequenceOutput {
                        sequence: beam.tokens,
                        prompt_length: prompt.len(),
                        scores: collect_scores.then_some(beam.scores),
                        logits: collect_logits.then_some(beam.logits),
                        hidden_states: None,
                        attentions: None,
                        cross_attentions: None,
                        sequence_score: collect_scores.then_some(normalized_score),
                        beam_indices: collect_scores.then_some(beam.beam_indices),
                    }
                })
                .collect(),
        })
    }

    /// Backward-compatible greedy generation helper.
    pub fn generate_greedy_ids(
        &self,
        prompt: &[u32],
        max_new_tokens: usize,
        eos_token_id: Option<u32>,
    ) -> Result<Vec<u32>> {
        self.generate_greedy_ids_with_context(prompt, max_new_tokens, eos_token_id, None, None)
    }

    /// Greedy generation for a decoder with external encoder context. The
    /// encoder hidden states and mask remain fixed while the decoder prefix is
    /// rerun for each generated token.
    pub fn generate_greedy_ids_with_encoder_hidden_states(
        &self,
        prompt: &[u32],
        max_new_tokens: usize,
        eos_token_id: Option<u32>,
        encoder_hidden_states: &[f32],
        encoder_attention_mask: &[f32],
    ) -> Result<Vec<u32>> {
        self.generate_greedy_ids_with_context(
            prompt,
            max_new_tokens,
            eos_token_id,
            Some(encoder_hidden_states),
            Some(encoder_attention_mask),
        )
    }

    /// Fully explicit backward-compatible greedy-generation surface.
    pub fn generate_greedy_ids_with_context(
        &self,
        prompt: &[u32],
        max_new_tokens: usize,
        eos_token_id: Option<u32>,
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
    ) -> Result<Vec<u32>> {
        let config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(max_new_tokens),
            max_length: None,
            top_k: 0,
            eos_token_ids: eos_token_id.into_iter().collect(),
            ..VulkanTransformerGenerationConfig::default()
        };
        self.generate_ids_with_context(
            prompt,
            &config,
            encoder_hidden_states,
            encoder_attention_mask,
        )
    }

    pub fn train_step(
        &mut self,
        input_ids: &[u32],
        targets: &[u32],
        attention_mask: &[f32],
        loss_weights: &[f32],
        hyper: AdamWHyperParams,
    ) -> Result<VulkanTransformerStepResult> {
        self.train_step_with_token_type_ids(
            input_ids,
            None,
            targets,
            attention_mask,
            loss_weights,
            hyper,
        )
    }

    /// Training variant that exposes BERT's token-type/segment IDs while
    /// retaining the legacy all-zero default through `train_step`.
    pub fn train_step_with_token_type_ids(
        &mut self,
        input_ids: &[u32],
        token_type_ids: Option<&[u32]>,
        targets: &[u32],
        attention_mask: &[f32],
        loss_weights: &[f32],
        hyper: AdamWHyperParams,
    ) -> Result<VulkanTransformerStepResult> {
        self.train_step_with_context(
            input_ids,
            token_type_ids,
            targets,
            attention_mask,
            loss_weights,
            None,
            None,
            hyper,
        )
    }

    /// Train a decoder graph with external encoder hidden states. The decoder
    /// updates its own parameters and records the summed gradient with respect
    /// to the supplied encoder hidden states for `encoder_hidden_gradient()`.
    pub fn train_step_with_encoder_hidden_states(
        &mut self,
        input_ids: &[u32],
        targets: &[u32],
        attention_mask: &[f32],
        loss_weights: &[f32],
        encoder_hidden_states: &[f32],
        encoder_attention_mask: &[f32],
        hyper: AdamWHyperParams,
    ) -> Result<VulkanTransformerStepResult> {
        self.train_step_with_context(
            input_ids,
            None,
            targets,
            attention_mask,
            loss_weights,
            Some(encoder_hidden_states),
            Some(encoder_attention_mask),
            hyper,
        )
    }

    /// Fully explicit training surface. Cross-attention is active only when
    /// encoder hidden states are supplied; an omitted encoder mask means every
    /// encoder position is visible.
    pub fn train_step_with_context(
        &mut self,
        input_ids: &[u32],
        token_type_ids: Option<&[u32]>,
        targets: &[u32],
        attention_mask: &[f32],
        loss_weights: &[f32],
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        hyper: AdamWHyperParams,
    ) -> Result<VulkanTransformerStepResult> {
        self.train_step_with_context_and_roc_bert_ids(
            input_ids,
            None,
            None,
            None,
            token_type_ids,
            targets,
            attention_mask,
            loss_weights,
            encoder_hidden_states,
            encoder_attention_mask,
            hyper,
        )
    }

    /// Train ERNIE with its optional Hugging Face `task_type_ids` stream.
    /// `None` selects task id zero when the package has `use_task_id=true`.
    pub fn train_step_with_task_type_ids(
        &mut self,
        input_ids: &[u32],
        token_type_ids: Option<&[u32]>,
        task_type_ids: Option<&[u32]>,
        targets: &[u32],
        attention_mask: &[f32],
        loss_weights: &[f32],
        hyper: AdamWHyperParams,
    ) -> Result<VulkanTransformerStepResult> {
        if self.config.architecture != VulkanTransformerArchitecture::Ernie {
            bail!("train_step_with_task_type_ids requires an ERNIE graph");
        }
        self.train_step_with_context_and_roc_bert_ids(
            input_ids,
            None,
            None,
            task_type_ids,
            token_type_ids,
            targets,
            attention_mask,
            loss_weights,
            None,
            None,
            hyper,
        )
    }

    /// Train XLM/Flaubert with Hugging Face's optional `langs` stream. The
    /// optional `token_type_ids` stream is also supported and intentionally
    /// reuses the word embedding table, matching the Python implementation.
    pub fn train_step_with_language_ids(
        &mut self,
        input_ids: &[u32],
        language_ids: Option<&[u32]>,
        token_type_ids: Option<&[u32]>,
        targets: &[u32],
        attention_mask: &[f32],
        loss_weights: &[f32],
        hyper: AdamWHyperParams,
    ) -> Result<VulkanTransformerStepResult> {
        if !matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::Xlm | VulkanTransformerArchitecture::Flaubert
        ) {
            bail!("train_step_with_language_ids requires an XLM or Flaubert graph");
        }
        self.train_step_with_context_and_roc_bert_ids(
            input_ids,
            None,
            None,
            language_ids,
            token_type_ids,
            targets,
            attention_mask,
            loss_weights,
            None,
            None,
            hyper,
        )
    }

    /// RoCBert training surface matching Hugging Face's auxiliary embedding
    /// inputs while preserving the same optimizer and cross-attention contract
    /// as train_step_with_context.
    pub fn train_step_with_roc_bert_ids(
        &mut self,
        input_ids: &[u32],
        input_shape_ids: Option<&[u32]>,
        input_pronunciation_ids: Option<&[u32]>,
        token_type_ids: Option<&[u32]>,
        targets: &[u32],
        attention_mask: &[f32],
        loss_weights: &[f32],
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        hyper: AdamWHyperParams,
    ) -> Result<VulkanTransformerStepResult> {
        if self.config.architecture != VulkanTransformerArchitecture::RoCBert {
            bail!("train_step_with_roc_bert_ids requires a RoCBert graph");
        }
        self.train_step_with_context_and_roc_bert_ids(
            input_ids,
            input_shape_ids,
            input_pronunciation_ids,
            None,
            token_type_ids,
            targets,
            attention_mask,
            loss_weights,
            encoder_hidden_states,
            encoder_attention_mask,
            hyper,
        )
    }

    fn train_step_with_context_and_roc_bert_ids(
        &mut self,
        input_ids: &[u32],
        input_shape_ids: Option<&[u32]>,
        input_pronunciation_ids: Option<&[u32]>,
        auxiliary_ids: Option<&[u32]>,
        token_type_ids: Option<&[u32]>,
        targets: &[u32],
        attention_mask: &[f32],
        loss_weights: &[f32],
        encoder_hidden_states: Option<&[f32]>,
        encoder_attention_mask: Option<&[f32]>,
        hyper: AdamWHyperParams,
    ) -> Result<VulkanTransformerStepResult> {
        hyper.validate()?;
        if input_ids.len() != self.rows
            || targets.len() != self.rows
            || attention_mask.len() != self.rows
            || loss_weights.len() != self.rows
        {
            bail!(
                "Transformer batch arrays must all have exactly {} rows",
                self.rows
            );
        }
        if let Some(&bad) = input_ids
            .iter()
            .find(|&&token| token as usize >= self.config.vocab_size)
        {
            bail!(
                "input token {bad} is outside vocabulary size {}",
                self.config.vocab_size
            );
        }
        self.validate_roberta_position_ids(input_ids)?;
        if let Some(&bad) = targets
            .iter()
            .find(|&&token| token != u32::MAX && token as usize >= self.config.vocab_size)
        {
            bail!(
                "target token {bad} is outside vocabulary size {}",
                self.config.vocab_size
            );
        }
        if attention_mask
            .iter()
            .chain(loss_weights)
            .any(|value| !value.is_finite())
        {
            bail!("attention mask/loss weights contain non-finite values");
        }
        let encoder_seq_len =
            self.validate_encoder_context(encoder_hidden_states, encoder_attention_mask)?;
        if let Some(frontend) = self.roc_bert_embedding_frontend.as_ref() {
            frontend.validate_ids(self.rows, input_shape_ids, input_pronunciation_ids)?;
        } else if input_shape_ids.is_some() || input_pronunciation_ids.is_some() {
            bail!(
                "{} does not define RoCBert shape/pronunciation embeddings",
                self.config.architecture.model_type()
            );
        }
        let xlm_word_token_types = matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::Xlm | VulkanTransformerArchitecture::Flaubert
        );
        if let Some(token_type_ids) = token_type_ids {
            if token_type_ids.len() != self.rows {
                bail!(
                    "Transformer token_type_ids must have exactly {} rows",
                    self.rows
                );
            }
            let token_type_vocab_size = if let Some(embedding) = self.token_type_embedding.as_ref()
            {
                embedding.vocab_size()
            } else if xlm_word_token_types {
                self.config.vocab_size
            } else {
                bail!(
                    "{} does not define token_type embeddings",
                    self.config.architecture.model_type()
                );
            };
            if let Some(&bad) = token_type_ids
                .iter()
                .find(|&&id| id as usize >= token_type_vocab_size)
            {
                bail!(
                    "token type id {bad} is outside token type vocabulary size {}",
                    token_type_vocab_size
                );
            }
        }
        let auxiliary_stream_active = match self.config.architecture {
            VulkanTransformerArchitecture::Ernie => self.auxiliary_embedding.is_some(),
            VulkanTransformerArchitecture::Xlm | VulkanTransformerArchitecture::Flaubert => {
                auxiliary_ids.is_some()
            }
            _ => false,
        };
        if let Some(auxiliary_ids) = auxiliary_ids {
            if auxiliary_ids.len() != self.rows {
                bail!(
                    "Transformer auxiliary ids must have exactly {} rows",
                    self.rows
                );
            }
            let embedding = self.auxiliary_embedding.as_ref().with_context(|| {
                format!(
                    "{} does not define the requested auxiliary embedding",
                    self.config.architecture.model_type()
                )
            })?;
            if let Some(&bad) = auxiliary_ids
                .iter()
                .find(|&&id| id as usize >= embedding.vocab_size())
            {
                bail!(
                    "auxiliary id {bad} is outside auxiliary vocabulary size {}",
                    embedding.vocab_size()
                );
            }
        }
        let token_type_stream_active = self.token_type_embedding.is_some()
            || (xlm_word_token_types && token_type_ids.is_some());
        let has_supervised_weight = targets
            .iter()
            .zip(loss_weights)
            .any(|(&target, &weight)| target != u32::MAX && weight > 0.0);
        if !has_supervised_weight {
            bail!("Transformer batch has no positive supervised loss weight");
        }
        let supervised_tokens = targets
            .iter()
            .zip(loss_weights)
            .filter(|(target, weight)| **target != u32::MAX && **weight > 0.0)
            .count();
        let next_step = self
            .step
            .checked_add(1)
            .context("Transformer AdamW step overflow")?;
        let active_layers = self
            .layers
            .iter()
            .map(|layer| {
                transformer_layer_is_active(
                    self.layerdrop,
                    self.dropout_seed,
                    next_step,
                    layer.layer_index,
                )
            })
            .collect::<Result<Vec<_>>>()?;
        let embedding_size = self.config.effective_embedding_size();

        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        commands.enable_watchdog_submission_slicing();
        commands.upload_u32(&self.token_ids, input_ids)?;
        commands.upload_u32(&self.targets, targets)?;
        commands.upload_f32(&self.attention_mask, attention_mask)?;
        commands.upload_f32(&self.loss_weights, loss_weights)?;
        if encoder_seq_len > 0 {
            commands.upload_f32(
                self.encoder_hidden
                    .as_ref()
                    .context("cross-attention graph is missing encoder hidden storage")?,
                encoder_hidden_states.expect("validated encoder hidden states"),
            )?;
            let encoder_mask = self
                .encoder_attention_mask
                .as_ref()
                .context("cross-attention graph is missing encoder mask storage")?;
            if let Some(encoder_attention_mask) = encoder_attention_mask {
                commands.upload_f32(encoder_mask, encoder_attention_mask)?;
            } else {
                commands.fill_f32(encoder_mask, self.encoder_rows, 1.0)?;
            }
        }
        let implicit_token_type_ids = vec![0u32; self.rows];
        if token_type_stream_active {
            let token_type_ids = token_type_ids.unwrap_or(&implicit_token_type_ids);
            commands.upload_u32(&self.token_type_ids, token_type_ids)?;
            if let Some(token_type_embedding) = self.token_type_embedding.as_ref() {
                token_type_embedding.record_forward(
                    &mut commands,
                    self.rows,
                    &self.token_type_ids,
                    &self.token_type_embedding_output,
                )?;
            } else {
                self.token_embedding.record_forward(
                    &mut commands,
                    self.rows,
                    &self.token_type_ids,
                    &self.token_type_embedding_output,
                )?;
            }
        }
        if auxiliary_stream_active {
            let implicit_auxiliary_ids = vec![0u32; self.rows];
            let auxiliary_ids = auxiliary_ids.unwrap_or(&implicit_auxiliary_ids);
            commands.upload_u32(&self.auxiliary_ids, auxiliary_ids)?;
            self.auxiliary_embedding
                .as_ref()
                .context("active Transformer auxiliary stream is missing its embedding table")?
                .record_forward(
                    &mut commands,
                    self.rows,
                    &self.auxiliary_ids,
                    &self.auxiliary_embedding_output,
                )?;
        }
        if self.config.uses_mask_relative_alibi_positions() {
            let alibi_push = AlibiPositionsPush {
                batch_size: self.batch_size as u32,
                seq_len: self.seq_len as u32,
            };
            self.kernels.alibi_positions.record_dispatch(
                &mut commands,
                &[&self.attention_mask, &self.alibi_positions],
                bytemuck::bytes_of(&alibi_push),
                [self.batch_size as u32, 1, 1],
            )?;
        }
        let peft_mode = self.lora_config.is_some();
        let peft_bias_all = self
            .lora_config
            .as_ref()
            .is_some_and(|config| config.bias.eq_ignore_ascii_case("all"));
        let peft_saves_lm_head = self
            .lora_config
            .as_ref()
            .is_some_and(|config| config.saves_module("lm_head") && !config.inference_mode);
        let peft_saves_prediction_head_norm = self.prediction_head.is_some()
            && self.lora_config.as_ref().is_some_and(|config| {
                if config.inference_mode {
                    return false;
                }
                let prediction_base = match self.config.architecture {
                    VulkanTransformerArchitecture::Electra => Some("generator_predictions"),
                    VulkanTransformerArchitecture::RemBert => Some("cls.predictions"),
                    VulkanTransformerArchitecture::Bert
                    | VulkanTransformerArchitecture::Ernie
                    | VulkanTransformerArchitecture::MegatronBert
                    | VulkanTransformerArchitecture::RoFormer => Some("cls.predictions.transform"),
                    _ => None,
                };
                prediction_base
                    .is_some_and(|base| config.saves_module(&format!("{base}.LayerNorm")))
            });
        let peft_saves_input_embedding = self.lora_saved_embedding_module.is_some()
            && self
                .lora_config
                .as_ref()
                .is_some_and(|config| !config.inference_mode);
        let peft_ties_saved_embedding_to_lm_head = peft_saves_input_embedding
            && self.config.tie_word_embeddings
            && self
                .lora_config
                .as_ref()
                .is_some_and(VulkanTransformerLoraConfig::requests_saved_embedding_lm_head_tie);
        let peft_trainable_tokens_active = !self.lora_trainable_token_rows.is_empty()
            && self
                .lora_config
                .as_ref()
                .is_some_and(|config| !config.inference_mode);
        if !peft_mode || peft_saves_input_embedding || peft_trainable_tokens_active {
            self.shared_embedding.record_zero_grad(&mut commands)?;
        }
        if !peft_mode {
            if let Some(relative_attention_bias) = self.relative_attention_bias.as_ref() {
                commands
                    .fill_zero_f32(&relative_attention_bias.grad, relative_attention_bias.len)?;
            }
            for relative_attention_bias in &self.per_layer_relative_attention_bias {
                commands
                    .fill_zero_f32(&relative_attention_bias.grad, relative_attention_bias.len)?;
            }
            if let Some(token_type_embedding) = self.token_type_embedding.as_ref() {
                token_type_embedding.record_zero_grad(&mut commands)?;
            }
            if auxiliary_stream_active {
                self.auxiliary_embedding
                    .as_ref()
                    .context("active Transformer auxiliary stream is missing its embedding table")?
                    .record_zero_grad(&mut commands)?;
            }
            if let Some(frontend) = self.roc_bert_embedding_frontend.as_ref() {
                frontend.record_zero_grad(&mut commands)?;
            }
        }

        self.token_embedding.record_forward(
            &mut commands,
            self.rows,
            &self.token_ids,
            &self.token_embedding_output,
        )?;
        let token_embedding_source =
            if let Some(scales) = self.esm_token_dropout_scales(input_ids, attention_mask)? {
                let scale_buffer = self
                    .esm_token_scales
                    .as_ref()
                    .context("ESM token-dropout graph is missing row-scale storage")?;
                commands.upload_f32(scale_buffer, &scales)?;
                record_row_scale(
                    &mut commands,
                    &self.kernels,
                    &self.token_embedding_output,
                    scale_buffer,
                    &self.embedding_composed_with_type,
                    self.rows,
                    embedding_size,
                )?;
                &self.embedding_composed_with_type
            } else {
                &self.token_embedding_output
            };
        let token_embedding_source = if let Some(frontend) = self
            .roc_bert_embedding_frontend
            .as_ref()
            .filter(|frontend| frontend.concat_input)
        {
            frontend.record_concat_forward(
                &mut commands,
                &self.kernels,
                token_embedding_source,
                input_shape_ids,
                input_pronunciation_ids,
                self.rows,
            )?
        } else {
            token_embedding_source
        };
        let token_embedding_source = if self
            .config
            .architecture
            .token_scale_before_embedding_composition()
            && self.config.token_embedding_scale() != 1.0
        {
            let scale_push = ScalePush {
                len: (self.rows * embedding_size) as u32,
                scale: self.config.token_embedding_scale(),
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[token_embedding_source, &self.embedding_dropout_output],
                bytemuck::bytes_of(&scale_push),
                [div_ceil_u32(self.rows * embedding_size, 256), 1, 1],
            )?;
            &self.embedding_dropout_output
        } else {
            token_embedding_source
        };
        if let Some(embedding_norm) = self.embedding_norm.as_ref() {
            if self.config.architecture.embedding_norm_before_positions() {
                let position_embedding = self
                    .position_embedding
                    .as_ref()
                    .context("BlenderbotSmall graph is missing learned position embeddings")?;
                embedding_norm.record_forward(
                    &mut commands,
                    &self.kernels,
                    &self.token_embedding_output,
                    &self.embedding_composed,
                    &self.embedding_norm_mean,
                    &self.embedding_norm_rstd,
                    self.rows,
                )?;
                let position_push = PositionPush {
                    rows_or_batch: self.rows as u32,
                    seq_len: self.seq_len as u32,
                    dim: self.config.hidden_size as u32,
                    position_offset: 0,
                };
                self.kernels.position_add.record_dispatch(
                    &mut commands,
                    &[
                        &self.embedding_composed,
                        &position_embedding.values,
                        &self.input_hidden,
                    ],
                    bytemuck::bytes_of(&position_push),
                    [
                        div_ceil_u32(self.config.hidden_size, 16),
                        div_ceil_u32(self.rows, 16),
                        1,
                    ],
                )?;
            } else {
                let base_norm_input =
                    if let Some(position_embedding) = self.position_embedding.as_ref() {
                        if self.config.architecture.uses_roberta_position_ids() {
                            let position_push = self.roberta_position_push()?;
                            self.kernels.roberta_position_add.record_dispatch(
                                &mut commands,
                                &[
                                    token_embedding_source,
                                    &position_embedding.values,
                                    &self.token_ids,
                                    &self.embedding_composed,
                                ],
                                bytemuck::bytes_of(&position_push),
                                [
                                    div_ceil_u32(self.config.hidden_size, 16),
                                    div_ceil_u32(self.rows, 16),
                                    1,
                                ],
                            )?;
                        } else if matches!(
                            self.config.architecture,
                            VulkanTransformerArchitecture::Bart
                                | VulkanTransformerArchitecture::MBart
                                | VulkanTransformerArchitecture::PLBart
                                | VulkanTransformerArchitecture::Mvp
                        ) {
                            let position_push = OffsetPositionPush {
                                rows_or_batch: self.rows as u32,
                                seq_len: self.seq_len as u32,
                                dim: self.config.hidden_size as u32,
                                offset: 2,
                                embedding_scale: self.config.token_embedding_scale(),
                            };
                            self.kernels.offset_position_add.record_dispatch(
                                &mut commands,
                                &[
                                    token_embedding_source,
                                    &position_embedding.values,
                                    &self.embedding_composed,
                                ],
                                bytemuck::bytes_of(&position_push),
                                [
                                    div_ceil_u32(self.config.hidden_size, 16),
                                    div_ceil_u32(self.rows, 16),
                                    1,
                                ],
                            )?;
                        } else {
                            let position_push = PositionPush {
                                rows_or_batch: self.rows as u32,
                                seq_len: self.seq_len as u32,
                                dim: embedding_size as u32,
                                position_offset: 0,
                            };
                            self.kernels.position_add.record_dispatch(
                                &mut commands,
                                &[
                                    token_embedding_source,
                                    &position_embedding.values,
                                    &self.embedding_composed,
                                ],
                                bytemuck::bytes_of(&position_push),
                                [
                                    div_ceil_u32(embedding_size, 16),
                                    div_ceil_u32(self.rows, 16),
                                    1,
                                ],
                            )?;
                        }
                        &self.embedding_composed
                    } else {
                        token_embedding_source
                    };
                let norm_input = if token_type_stream_active {
                    record_add(
                        &mut commands,
                        &self.kernels,
                        base_norm_input,
                        &self.token_type_embedding_output,
                        &self.embedding_composed_with_type,
                        self.rows * embedding_size,
                    )?;
                    &self.embedding_composed_with_type
                } else {
                    base_norm_input
                };
                let norm_input = if auxiliary_stream_active {
                    record_add(
                        &mut commands,
                        &self.kernels,
                        norm_input,
                        &self.auxiliary_embedding_output,
                        &self.embedding_composed_with_aux,
                        self.rows * embedding_size,
                    )?;
                    &self.embedding_composed_with_aux
                } else {
                    norm_input
                };
                let norm_input = if self.config.architecture.embedding_dropout_before_norm()
                    && self.config.embedding_dropout > 0.0
                {
                    record_transformer_dropout(
                        &mut commands,
                        &self.kernels,
                        norm_input,
                        &self.input_hidden_dropout,
                        self.config.embedding_dropout,
                        next_step,
                        TRANSFORMER_EMBEDDING_DROPOUT_SITE,
                        self.dropout_seed,
                        self.rows * embedding_size,
                    )?;
                    &self.input_hidden_dropout
                } else {
                    norm_input
                };
                let norm_output = if self.embedding_project.is_some() {
                    &self.embedding_norm_output
                } else {
                    &self.input_hidden
                };
                embedding_norm.record_forward(
                    &mut commands,
                    &self.kernels,
                    norm_input,
                    norm_output,
                    &self.embedding_norm_mean,
                    &self.embedding_norm_rstd,
                    self.rows,
                )?;
                if let Some(embedding_project) = self.embedding_project.as_ref() {
                    let project_input = if self.config.embedding_dropout > 0.0 {
                        record_transformer_dropout(
                            &mut commands,
                            &self.kernels,
                            norm_output,
                            &self.embedding_dropout_output,
                            self.config.embedding_dropout,
                            next_step,
                            TRANSFORMER_EMBEDDING_DROPOUT_SITE,
                            self.dropout_seed,
                            self.rows * embedding_size,
                        )?;
                        &self.embedding_dropout_output
                    } else {
                        norm_output
                    };
                    embedding_project.record_forward(
                        &mut commands,
                        &self.kernels,
                        project_input,
                        &self.input_hidden,
                        self.rows,
                    )?;
                }
            }
        } else if let Some(position_embedding) = self.position_embedding.as_ref() {
            if self.config.architecture.uses_roberta_position_ids() {
                let position_push = self.roberta_position_push()?;
                self.kernels.roberta_position_add.record_dispatch(
                    &mut commands,
                    &[
                        token_embedding_source,
                        &position_embedding.values,
                        &self.token_ids,
                        &self.input_hidden,
                    ],
                    bytemuck::bytes_of(&position_push),
                    [
                        div_ceil_u32(self.config.hidden_size, 16),
                        div_ceil_u32(self.rows, 16),
                        1,
                    ],
                )?;
            } else if matches!(
                self.config.architecture,
                VulkanTransformerArchitecture::BioGpt
                    | VulkanTransformerArchitecture::Xglm
                    | VulkanTransformerArchitecture::Ctrl
                    | VulkanTransformerArchitecture::Marian
                    | VulkanTransformerArchitecture::Blenderbot
                    | VulkanTransformerArchitecture::Pegasus
                    | VulkanTransformerArchitecture::BigBirdPegasus
                    | VulkanTransformerArchitecture::PegasusX
            ) {
                let position_push = OffsetPositionPush {
                    rows_or_batch: self.rows as u32,
                    seq_len: self.seq_len as u32,
                    dim: self.config.hidden_size as u32,
                    offset: if matches!(
                        self.config.architecture,
                        VulkanTransformerArchitecture::Ctrl
                            | VulkanTransformerArchitecture::Marian
                            | VulkanTransformerArchitecture::Blenderbot
                            | VulkanTransformerArchitecture::Pegasus
                            | VulkanTransformerArchitecture::BigBirdPegasus
                            | VulkanTransformerArchitecture::PegasusX
                    ) {
                        0
                    } else {
                        2
                    },
                    embedding_scale: self.config.token_embedding_scale(),
                };
                self.kernels.offset_position_add.record_dispatch(
                    &mut commands,
                    &[
                        &self.token_embedding_output,
                        &position_embedding.values,
                        &self.input_hidden,
                    ],
                    bytemuck::bytes_of(&position_push),
                    [
                        div_ceil_u32(self.config.hidden_size, 16),
                        div_ceil_u32(self.rows, 16),
                        1,
                    ],
                )?;
            } else if self.config.architecture == VulkanTransformerArchitecture::Opt {
                let opt_token_embedding_source =
                    if let Some(embedding_project) = self.embedding_project.as_ref() {
                        embedding_project.record_forward(
                            &mut commands,
                            &self.kernels,
                            token_embedding_source,
                            &self.input_hidden_dropout,
                            self.rows,
                        )?;
                        &self.input_hidden_dropout
                    } else {
                        token_embedding_source
                    };
                let position_push = OptPositionPush {
                    batch_size: self.batch_size as u32,
                    seq_len: self.seq_len as u32,
                    dim: self.config.hidden_size as u32,
                    table_rows: (self.config.max_position_embeddings + 2) as u32,
                    offset: 2,
                };
                self.kernels.opt_position_add.record_dispatch(
                    &mut commands,
                    &[
                        opt_token_embedding_source,
                        &position_embedding.values,
                        &self.attention_mask,
                        &self.input_hidden,
                    ],
                    bytemuck::bytes_of(&position_push),
                    [
                        div_ceil_u32(self.config.hidden_size, 16),
                        div_ceil_u32(self.rows, 16),
                        1,
                    ],
                )?;
            } else {
                let position_push = PositionPush {
                    rows_or_batch: self.rows as u32,
                    seq_len: self.seq_len as u32,
                    dim: self.config.hidden_size as u32,
                    position_offset: 0,
                };
                self.kernels.position_add.record_dispatch(
                    &mut commands,
                    &[
                        &self.token_embedding_output,
                        &position_embedding.values,
                        &self.input_hidden,
                    ],
                    bytemuck::bytes_of(&position_push),
                    [
                        div_ceil_u32(self.config.hidden_size, 16),
                        div_ceil_u32(self.rows, 16),
                        1,
                    ],
                )?;
            }
        } else {
            let embedding_scale = self.config.token_embedding_scale();
            let copy_push = ScalePush {
                len: (self.rows * self.config.hidden_size) as u32,
                scale: embedding_scale,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[token_embedding_source, &self.input_hidden],
                bytemuck::bytes_of(&copy_push),
                [div_ceil_u32(self.rows * self.config.hidden_size, 256), 1, 1],
            )?;
        }

        if self.config.embedding_dropout > 0.0
            && self.embedding_project.is_none()
            && !self.config.architecture.embedding_dropout_before_norm()
        {
            record_transformer_dropout(
                &mut commands,
                &self.kernels,
                &self.input_hidden,
                &self.input_hidden_dropout,
                self.config.embedding_dropout,
                next_step,
                TRANSFORMER_EMBEDDING_DROPOUT_SITE,
                self.dropout_seed,
                self.rows * self.config.hidden_size,
            )?;
        }

        if let Some(frontend) = self
            .roc_bert_embedding_frontend
            .as_ref()
            .filter(|frontend| !frontend.concat_input)
        {
            let base = if self.config.embedding_dropout > 0.0 && self.embedding_project.is_none() {
                &self.input_hidden_dropout
            } else {
                &self.input_hidden
            };
            if let Some(average) = frontend.record_nonconcat_forward(
                &mut commands,
                &self.kernels,
                base,
                input_shape_ids,
                input_pronunciation_ids,
                self.rows,
            )? {
                let destination =
                    if self.config.embedding_dropout > 0.0 && self.embedding_project.is_none() {
                        &self.input_hidden_dropout
                    } else {
                        &self.input_hidden
                    };
                commands.copy_f32(average, destination, self.rows * self.config.hidden_size)?;
            }
        }

        if self.config.architecture == VulkanTransformerArchitecture::Esm {
            let source = if self.config.embedding_dropout > 0.0 && self.embedding_project.is_none()
            {
                &self.input_hidden_dropout
            } else {
                &self.input_hidden
            };
            record_row_scale(
                &mut commands,
                &self.kernels,
                source,
                &self.attention_mask,
                &self.embedding_dropout_output,
                self.rows,
                self.config.hidden_size,
            )?;
        }

        let layer0_standard_input =
            if self.config.architecture == VulkanTransformerArchitecture::Esm {
                &self.embedding_dropout_output
            } else if self.config.embedding_dropout > 0.0
                && self.embedding_project.is_none()
                && !self.config.architecture.embedding_dropout_before_norm()
            {
                &self.input_hidden_dropout
            } else {
                &self.input_hidden
            };
        let deepseek_v4_initial_input = if let (Some(hc_mult), Some(hyper)) = (
            self.deepseek_v4_hyper_head
                .as_ref()
                .map(|head| head.hc_mult)
                .or(self.glm5_hc_mult),
            self.deepseek_v4_initial_hyper.as_ref(),
        ) {
            let push = Qwen4HyperPush {
                rows: self.rows as u32,
                hidden_size: self.config.hidden_size as u32,
                hc_count: hc_mult as u32,
            };
            self.kernels.qwen4_repeat_streams.record_dispatch(
                &mut commands,
                &[layer0_standard_input, hyper],
                bytemuck::bytes_of(&push),
                [
                    div_ceil_u32(self.rows * self.config.hidden_size * hc_mult, 256),
                    1,
                    1,
                ],
            )?;
            Some(hyper)
        } else {
            None
        };
        let qwen4_initial_input = if let (Some(mixer), Some(hyper)) = (
            self.qwen4_final_mixer.as_ref(),
            self.qwen4_initial_hyper.as_ref(),
        ) {
            let push = Qwen4HyperPush {
                rows: self.rows as u32,
                hidden_size: self.config.hidden_size as u32,
                hc_count: mixer.hc_count as u32,
            };
            self.kernels.qwen4_repeat_streams.record_dispatch(
                &mut commands,
                &[layer0_standard_input, hyper],
                bytemuck::bytes_of(&push),
                [
                    div_ceil_u32(self.rows * self.config.hidden_size * mixer.hc_count, 256),
                    1,
                    1,
                ],
            )?;
            Some(hyper)
        } else {
            None
        };

        for layer_index in 0..self.layers.len() {
            let input = if layer_index == 0 {
                deepseek_v4_initial_input
                    .or(qwen4_initial_input)
                    .unwrap_or(layer0_standard_input)
            } else {
                self.layers[layer_index - 1].forward_output()
            };
            if active_layers[layer_index] {
                self.layers[layer_index].prepare_qwen4_ple_embeddings(
                    &mut commands,
                    input_ids,
                    attention_mask,
                )?;
                let shared_dsa_sparse_mask = self.shared_dsa_sparse_mask_for_layer(layer_index)?;
                self.layers[layer_index].record_forward_with_cross_attention(
                    &mut commands,
                    &self.kernels,
                    &self.config,
                    self.causal_attention,
                    input,
                    Some(&self.token_ids),
                    &self.attention_mask,
                    &self.alibi_positions,
                    self.relative_attention_bias_for_layer(layer_index),
                    self.relative_attention_num_buckets,
                    self.relative_attention_max_distance,
                    self.encoder_hidden.as_ref(),
                    self.encoder_attention_mask.as_ref(),
                    encoder_seq_len,
                    self.batch_size,
                    self.seq_len,
                    next_step,
                    self.dropout_seed,
                    true,
                    None,
                    self.kimi_attn_res.as_ref(),
                    shared_dsa_sparse_mask,
                )?;
                self.record_longcat_pair_forward_merge(&mut commands, layer_index, self.rows)?;
            } else {
                let output_width =
                    if let Some(hyper) = self.layers[layer_index].deepseek_v4_ffn_hc.as_ref() {
                        self.config
                            .hidden_size
                            .checked_mul(hyper.hc_mult)
                            .context("DeepSeek-V4 skipped-layer output width overflow")?
                    } else {
                        self.layers[layer_index]
                            .qwen4_mlp_hyper_connection
                            .as_ref()
                            .map(|hyper| hyper.hc_hidden_size)
                            .unwrap_or(self.config.hidden_size)
                    };
                let copy_push = ScalePush {
                    len: (self.rows * output_width) as u32,
                    scale: 1.0,
                };
                self.kernels.scale_copy.record_dispatch(
                    &mut commands,
                    &[input, self.layers[layer_index].forward_output()],
                    bytemuck::bytes_of(&copy_push),
                    [div_ceil_u32(self.rows * output_width, 256), 1, 1],
                )?;
            }
            commands.watchdog_checkpoint()?;
        }
        let final_prefix = self
            .layers
            .last()
            .context("Transformer has no layers")?
            .forward_output();
        let final_input = if let Some(stack) = self.kimi_attn_res.as_ref() {
            stack.record_output_forward(
                &mut commands,
                &self.kernels,
                final_prefix,
                self.rows,
                self.config.hidden_size,
            )?
        } else {
            final_prefix
        };
        let terminal_hidden = if let Some(head) = self.deepseek_v4_hyper_head.as_ref() {
            head.record_forward(&mut commands, &self.kernels, final_input)?;
            if self.config.uses_final_norm() {
                self.final_norm.record_forward(
                    &mut commands,
                    &self.kernels,
                    head.output(),
                    &self.final_norm_output,
                    &self.final_norm_mean,
                    &self.final_norm_rstd,
                    self.rows,
                )?;
                &self.final_norm_output
            } else {
                head.output()
            }
        } else if let Some(hc_mult) = self.glm5_hc_mult {
            if !self.config.uses_final_norm() {
                bail!("GLM-5 mHC terminal mean requires the final RMSNorm");
            }
            let mean = self
                .glm5_terminal_mean
                .as_ref()
                .context("GLM-5 mHC graph is missing its terminal mean buffer")?;
            let push = Qwen4HyperPush {
                rows: self.rows as u32,
                hidden_size: self.config.hidden_size as u32,
                hc_count: hc_mult as u32,
            };
            self.kernels.qwen4_stream_mean.record_dispatch(
                &mut commands,
                &[final_input, mean],
                bytemuck::bytes_of(&push),
                [
                    div_ceil_u32(self.config.hidden_size, 16),
                    div_ceil_u32(self.rows, 16),
                    1,
                ],
            )?;
            self.final_norm.record_forward(
                &mut commands,
                &self.kernels,
                mean,
                &self.final_norm_output,
                &self.final_norm_mean,
                &self.final_norm_rstd,
                self.rows,
            )?;
            &self.final_norm_output
        } else if let Some(mixer) = self.qwen4_final_mixer.as_ref() {
            mixer.record_forward(
                &mut commands,
                &self.kernels,
                final_input,
                &self.final_norm_output,
                None,
            )?;
            &self.final_norm_output
        } else if self.config.uses_final_norm() {
            self.final_norm.record_forward(
                &mut commands,
                &self.kernels,
                final_input,
                &self.final_norm_output,
                &self.final_norm_mean,
                &self.final_norm_rstd,
                self.rows,
            )?;
            &self.final_norm_output
        } else {
            final_input
        };
        let decoder_output = if let Some(output_project) = self.output_project.as_ref() {
            output_project.record_forward(
                &mut commands,
                &self.kernels,
                terminal_hidden,
                &self.output_project_output,
                self.rows,
            )?;
            &self.output_project_output
        } else {
            terminal_hidden
        };
        let projection_input = if let Some(prediction_head) = self.prediction_head.as_ref() {
            prediction_head.record_forward(
                &mut commands,
                &self.kernels,
                decoder_output,
                self.rows,
            )?;
            &prediction_head.output
        } else {
            decoder_output
        };
        let lm_input_dim = self
            .prediction_head
            .as_ref()
            .map(|head| head.output_dim)
            .unwrap_or_else(|| {
                if self.output_project.is_some() {
                    self.config.effective_embedding_size()
                } else {
                    self.config.hidden_size
                }
            });
        let lm_push = LinearPush {
            rows: self.rows as u32,
            input_dim: lm_input_dim as u32,
            output_dim: self.config.vocab_size as u32,
        };
        let projection_logits = self.raw_logits.as_ref().unwrap_or(&self.logits);
        if let Some(lm_head) = self.lm_head.as_ref() {
            lm_head.record_forward(
                &mut commands,
                &self.kernels,
                projection_input,
                projection_logits,
                self.rows,
            )?;
        } else {
            self.kernels.linear_forward.record_dispatch(
                &mut commands,
                &[
                    projection_input,
                    self.shared_embedding.weight_buffer(),
                    projection_logits,
                ],
                bytemuck::bytes_of(&lm_push),
                [
                    div_ceil_u32(self.config.vocab_size, 16),
                    div_ceil_u32(self.rows, 16),
                    1,
                ],
            )?;
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                let bias_push = BiasPush {
                    rows: self.rows as u32,
                    dim: self.config.vocab_size as u32,
                };
                self.kernels.bias_add.record_dispatch(
                    &mut commands,
                    &[projection_logits, &lm_head_bias.values],
                    bytemuck::bytes_of(&bias_push),
                    [div_ceil_u32(self.rows * self.config.vocab_size, 256), 1, 1],
                )?;
            }
        }
        if let Some(cap) = self.config.final_logit_softcapping {
            let raw_logits = self
                .raw_logits
                .as_ref()
                .context("logit soft-capping requires raw-logit storage")?;
            let scratch = self
                .logit_postprocess_scratch
                .as_ref()
                .context("logit soft-capping requires scratch storage")?;
            let len = self.rows * self.config.vocab_size;
            let scale_into_tanh = ScalePush {
                len: len as u32,
                scale: self.config.logits_multiplier / cap,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[raw_logits, scratch],
                bytemuck::bytes_of(&scale_into_tanh),
                [div_ceil_u32(len, 256), 1, 1],
            )?;
            let tanh_push = LenPush { len: len as u32 };
            self.kernels.tanh_forward.record_dispatch(
                &mut commands,
                &[scratch, raw_logits],
                bytemuck::bytes_of(&tanh_push),
                [div_ceil_u32(len, 256), 1, 1],
            )?;
            let scale_out = ScalePush {
                len: len as u32,
                scale: cap,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[raw_logits, &self.logits],
                bytemuck::bytes_of(&scale_out),
                [div_ceil_u32(len, 256), 1, 1],
            )?;
        } else if let Some(raw_logits) = self.raw_logits.as_ref() {
            let push = ScalePush {
                len: (self.rows * self.config.vocab_size) as u32,
                scale: self.config.logits_multiplier,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[raw_logits, &self.logits],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(self.rows * self.config.vocab_size, 256), 1, 1],
            )?;
        }
        let ce_push = CrossEntropyPush {
            rows: self.rows as u32,
            vocab_size: self.config.vocab_size as u32,
        };
        self.kernels.cross_entropy.record_dispatch(
            &mut commands,
            &[
                &self.logits,
                &self.targets,
                &self.loss_weights,
                &self.grad_logits,
                &self.row_loss,
            ],
            bytemuck::bytes_of(&ce_push),
            [self.rows as u32, 1, 1],
        )?;

        let grad_lm_logits = if let Some(cap) = self.config.final_logit_softcapping {
            let raw_logits = self
                .raw_logits
                .as_ref()
                .context("logit soft-capping requires raw-logit storage")?;
            let scratch = self
                .logit_postprocess_scratch
                .as_ref()
                .context("logit soft-capping requires scratch storage")?;
            let grad_raw_logits = self
                .grad_raw_logits
                .as_ref()
                .context("logit soft-capping requires raw-logit gradient storage")?;
            let len = self.rows * self.config.vocab_size;
            let output_scale = ScalePush {
                len: len as u32,
                scale: cap,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[&self.grad_logits, grad_raw_logits],
                bytemuck::bytes_of(&output_scale),
                [div_ceil_u32(len, 256), 1, 1],
            )?;
            let tanh_push = LenPush { len: len as u32 };
            self.kernels.tanh_backward.record_dispatch(
                &mut commands,
                &[grad_raw_logits, scratch, raw_logits],
                bytemuck::bytes_of(&tanh_push),
                [div_ceil_u32(len, 256), 1, 1],
            )?;
            let input_scale = ScalePush {
                len: len as u32,
                scale: self.config.logits_multiplier / cap,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[raw_logits, grad_raw_logits],
                bytemuck::bytes_of(&input_scale),
                [div_ceil_u32(len, 256), 1, 1],
            )?;
            grad_raw_logits
        } else if let Some(grad_raw_logits) = self.grad_raw_logits.as_ref() {
            let push = ScalePush {
                len: (self.rows * self.config.vocab_size) as u32,
                scale: self.config.logits_multiplier,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[&self.grad_logits, grad_raw_logits],
                bytemuck::bytes_of(&push),
                [div_ceil_u32(self.rows * self.config.vocab_size, 256), 1, 1],
            )?;
            grad_raw_logits
        } else {
            &self.grad_logits
        };
        let terminal_mixer_active = self.deepseek_v4_hyper_head.is_some()
            || self.qwen4_final_mixer.is_some()
            || self.kimi_attn_res.is_some()
            || self.config.uses_final_norm();
        let grad_projection_input = if let Some(prediction_head) = self.prediction_head.as_ref() {
            &prediction_head.grad_output
        } else if self.output_project.is_some() {
            &self.grad_output_project_output
        } else if terminal_mixer_active {
            &self.grad_final_norm_output
        } else {
            &self.grad_final_norm_input
        };

        if let Some(lm_head) = self.lm_head.as_ref() {
            lm_head.record_backward(
                &mut commands,
                &self.kernels,
                projection_input,
                grad_lm_logits,
                grad_projection_input,
                self.rows,
            )?;
        } else {
            if !peft_mode || peft_bias_all {
                if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                    let bias_push = BiasPush {
                        rows: self.rows as u32,
                        dim: self.config.vocab_size as u32,
                    };
                    self.kernels.bias_grad.record_dispatch(
                        &mut commands,
                        &[grad_lm_logits, &lm_head_bias.grad],
                        bytemuck::bytes_of(&bias_push),
                        [div_ceil_u32(self.config.vocab_size, 256), 1, 1],
                    )?;
                }
            }
            if !peft_mode || peft_trainable_tokens_active || peft_ties_saved_embedding_to_lm_head {
                self.kernels.linear_weight_grad.record_dispatch(
                    &mut commands,
                    &[projection_input, grad_lm_logits, &self.lm_weight_grad],
                    bytemuck::bytes_of(&lm_push),
                    [
                        div_ceil_u32(lm_input_dim, 16),
                        div_ceil_u32(self.config.vocab_size, 16),
                        1,
                    ],
                )?;
                self.shared_embedding
                    .record_accumulate_gradient(&mut commands, &self.lm_weight_grad)?;
            }
            self.kernels.linear_input_grad.record_dispatch(
                &mut commands,
                &[
                    grad_lm_logits,
                    self.shared_embedding.weight_buffer(),
                    grad_projection_input,
                ],
                bytemuck::bytes_of(&lm_push),
                [
                    div_ceil_u32(lm_input_dim, 16),
                    div_ceil_u32(self.rows, 16),
                    1,
                ],
            )?;
        }
        if let Some(prediction_head) = self.prediction_head.as_ref() {
            prediction_head.record_backward(
                &mut commands,
                &self.kernels,
                decoder_output,
                if terminal_mixer_active {
                    &self.grad_final_norm_output
                } else {
                    &self.grad_final_norm_input
                },
                self.rows,
            )?;
        }
        if let Some(output_project) = self.output_project.as_ref() {
            output_project.record_backward(
                &mut commands,
                &self.kernels,
                terminal_hidden,
                &self.grad_output_project_output,
                if terminal_mixer_active {
                    &self.grad_final_norm_output
                } else {
                    &self.grad_final_norm_input
                },
                self.rows,
            )?;
        }
        if let Some(head) = self.deepseek_v4_hyper_head.as_ref() {
            let head_grad_output = if self.config.uses_final_norm() {
                self.final_norm.record_backward(
                    &mut commands,
                    &self.kernels,
                    head.output(),
                    &self.grad_final_norm_output,
                    &self.final_norm_mean,
                    &self.final_norm_rstd,
                    &self.grad_final_norm_input,
                    self.rows,
                )?;
                &self.grad_final_norm_input
            } else {
                &self.grad_final_norm_output
            };
            head.record_backward(
                &mut commands,
                &self.kernels,
                final_input,
                head_grad_output,
                self.deepseek_v4_grad_final_hyper
                    .as_ref()
                    .context("DeepSeek-V4 hyper head is missing final hyper-gradient storage")?,
            )?;
        } else if let Some(hc_mult) = self.glm5_hc_mult {
            let mean = self
                .glm5_terminal_mean
                .as_ref()
                .context("GLM-5 mHC graph is missing its terminal mean buffer")?;
            self.final_norm.record_backward(
                &mut commands,
                &self.kernels,
                mean,
                &self.grad_final_norm_output,
                &self.final_norm_mean,
                &self.final_norm_rstd,
                &self.grad_final_norm_input,
                self.rows,
            )?;
            let grad_hyper = self
                .deepseek_v4_grad_final_hyper
                .as_ref()
                .context("GLM-5 mHC graph is missing final hyper-gradient storage")?;
            let push = Qwen4HyperPush {
                rows: self.rows as u32,
                hidden_size: self.config.hidden_size as u32,
                hc_count: hc_mult as u32,
            };
            self.kernels.qwen4_stream_mean_backward.record_dispatch(
                &mut commands,
                &[&self.grad_final_norm_input, grad_hyper],
                bytemuck::bytes_of(&push),
                [
                    div_ceil_u32(self.rows * self.config.hidden_size * hc_mult, 256),
                    1,
                    1,
                ],
            )?;
        } else if let Some(mixer) = self.qwen4_final_mixer.as_ref() {
            mixer.record_backward(
                &mut commands,
                &self.kernels,
                final_input,
                &self.grad_final_norm_output,
                None,
                self.qwen4_grad_final_hyper
                    .as_ref()
                    .context("Qwen4 final mixer is missing hyper-gradient storage")?,
            )?;
        } else if self.config.uses_final_norm() {
            self.final_norm.record_backward(
                &mut commands,
                &self.kernels,
                final_input,
                &self.grad_final_norm_output,
                &self.final_norm_mean,
                &self.final_norm_rstd,
                &self.grad_final_norm_input,
                self.rows,
            )?;
        }
        let kimi_final_prefix_grad = if let Some(stack) = self.kimi_attn_res.as_ref() {
            if self.deepseek_v4_hyper_head.is_some()
                || self.glm5_hc_mult.is_some()
                || self.qwen4_final_mixer.is_some()
            {
                bail!("Kimi AttnRes cannot be combined with another terminal residual mixer");
            }
            let grad_attn_res_output = if self.config.uses_final_norm() {
                &self.grad_final_norm_input
            } else {
                &self.grad_final_norm_output
            };
            Some(stack.record_output_backward(
                &mut commands,
                &self.kernels,
                final_prefix,
                grad_attn_res_output,
                self.rows,
                self.config.hidden_size,
            )?)
        } else {
            None
        };

        for layer_index in (0..self.layers.len()).rev() {
            let input = if layer_index == 0 {
                deepseek_v4_initial_input
                    .or(qwen4_initial_input)
                    .unwrap_or(layer0_standard_input)
            } else {
                self.layers[layer_index - 1].forward_output()
            };
            let grad_output = if layer_index + 1 == self.layers.len() {
                kimi_final_prefix_grad
                    .or(self.deepseek_v4_grad_final_hyper
                    .as_ref()
                    .or(self.qwen4_grad_final_hyper.as_ref()))
                    .unwrap_or(&self.grad_final_norm_input)
            } else {
                self.layers[layer_index + 1].backward_input_gradient()
            };
            if active_layers[layer_index] {
                self.record_longcat_pair_backward_fanout(
                    &mut commands,
                    layer_index,
                    grad_output,
                    self.rows,
                )?;
            }
            if active_layers[layer_index] {
                let shared_dsa_sparse_mask = self.shared_dsa_sparse_mask_for_layer(layer_index)?;
                self.layers[layer_index].record_backward_with_cross_attention(
                    &mut commands,
                    &self.kernels,
                    &self.config,
                    self.causal_attention,
                    input,
                    &self.attention_mask,
                    &self.alibi_positions,
                    self.relative_attention_bias_for_layer(layer_index),
                    self.relative_attention_num_buckets,
                    self.relative_attention_max_distance,
                    self.encoder_hidden.as_ref(),
                    self.encoder_attention_mask.as_ref(),
                    encoder_seq_len,
                    grad_output,
                    self.batch_size,
                    self.seq_len,
                    next_step,
                    self.dropout_seed,
                    self.kimi_attn_res.as_ref(),
                    shared_dsa_sparse_mask,
                )?;
            } else {
                let input_width =
                    if let Some(hyper) = self.layers[layer_index].deepseek_v4_attn_hc.as_ref() {
                        self.config
                            .hidden_size
                            .checked_mul(hyper.hc_mult)
                            .context("DeepSeek-V4 skipped-layer input width overflow")?
                    } else {
                        self.layers[layer_index]
                            .qwen4_attn_hyper_connection
                            .as_ref()
                            .map(|hyper| hyper.hc_hidden_size)
                            .unwrap_or(self.config.hidden_size)
                    };
                let copy_push = ScalePush {
                    len: (self.rows * input_width) as u32,
                    scale: 1.0,
                };
                self.kernels.scale_copy.record_dispatch(
                    &mut commands,
                    &[
                        grad_output,
                        self.layers[layer_index].backward_input_gradient(),
                    ],
                    bytemuck::bytes_of(&copy_push),
                    [div_ceil_u32(self.rows * input_width, 256), 1, 1],
                )?;
                if let Some(encoder_grad) = self.layers[layer_index].cross_encoder_grad() {
                    commands.fill_zero_f32(
                        encoder_grad,
                        self.encoder_rows * self.encoder_hidden_size,
                    )?;
                }
            }
            commands.watchdog_checkpoint()?;
        }
        self.record_encoder_hidden_gradient_sum(&mut commands, encoder_seq_len)?;
        let layer0_backward_grad = if let Some(hc_mult) = self
            .deepseek_v4_hyper_head
            .as_ref()
            .map(|head| head.hc_mult)
            .or(self.glm5_hc_mult)
        {
            let push = Qwen4HyperPush {
                rows: self.rows as u32,
                hidden_size: self.config.hidden_size as u32,
                hc_count: hc_mult as u32,
            };
            self.kernels.qwen4_stream_mean.record_dispatch(
                &mut commands,
                &[
                    self.layers[0].backward_input_gradient(),
                    &self.grad_input_hidden,
                ],
                bytemuck::bytes_of(&push),
                [
                    div_ceil_u32(self.config.hidden_size, 16),
                    div_ceil_u32(self.rows, 16),
                    1,
                ],
            )?;
            let sum_push = ScalePush {
                len: (self.rows * self.config.hidden_size) as u32,
                scale: hc_mult as f32,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[&self.grad_input_hidden, &self.grad_final_norm_input],
                bytemuck::bytes_of(&sum_push),
                [div_ceil_u32(self.rows * self.config.hidden_size, 256), 1, 1],
            )?;
            &self.grad_final_norm_input
        } else if let Some(mixer) = self.qwen4_final_mixer.as_ref() {
            let push = Qwen4HyperPush {
                rows: self.rows as u32,
                hidden_size: self.config.hidden_size as u32,
                hc_count: mixer.hc_count as u32,
            };
            self.kernels.qwen4_stream_mean.record_dispatch(
                &mut commands,
                &[
                    self.layers[0].backward_input_gradient(),
                    &self.grad_input_hidden,
                ],
                bytemuck::bytes_of(&push),
                [
                    div_ceil_u32(self.config.hidden_size, 16),
                    div_ceil_u32(self.rows, 16),
                    1,
                ],
            )?;
            let sum_push = ScalePush {
                len: (self.rows * self.config.hidden_size) as u32,
                scale: mixer.hc_count as f32,
            };
            self.kernels.scale_copy.record_dispatch(
                &mut commands,
                &[&self.grad_input_hidden, &self.grad_final_norm_input],
                bytemuck::bytes_of(&sum_push),
                [div_ceil_u32(self.rows * self.config.hidden_size, 256), 1, 1],
            )?;
            &self.grad_final_norm_input
        } else {
            self.layers[0].backward_input_gradient()
        };
        if !peft_mode || peft_saves_input_embedding || peft_trainable_tokens_active {
            let embedding_output_grad = if let Some(frontend) = self
                .roc_bert_embedding_frontend
                .as_ref()
                .filter(|frontend| !frontend.concat_input)
            {
                frontend.record_nonconcat_backward(
                    &mut commands,
                    &self.kernels,
                    layer0_backward_grad,
                    input_shape_ids,
                    input_pronunciation_ids,
                    self.rows,
                )?
            } else {
                layer0_backward_grad
            };
            let input_grad = if let Some(embedding_project) = self
                .embedding_project
                .as_ref()
                .filter(|_| self.config.architecture != VulkanTransformerArchitecture::Opt)
            {
                let project_input = if self.config.embedding_dropout > 0.0 {
                    &self.embedding_dropout_output
                } else {
                    &self.embedding_norm_output
                };
                embedding_project.record_backward(
                    &mut commands,
                    &self.kernels,
                    project_input,
                    embedding_output_grad,
                    &self.grad_embedding_project_input,
                    self.rows,
                )?;
                if self.config.embedding_dropout > 0.0 {
                    record_transformer_dropout(
                        &mut commands,
                        &self.kernels,
                        &self.grad_embedding_project_input,
                        &self.grad_embedding_dropout_input,
                        self.config.embedding_dropout,
                        next_step,
                        TRANSFORMER_EMBEDDING_DROPOUT_SITE,
                        self.dropout_seed,
                        self.rows * embedding_size,
                    )?;
                    &self.grad_embedding_dropout_input
                } else {
                    &self.grad_embedding_project_input
                }
            } else if self.config.embedding_dropout > 0.0
                && !self.config.architecture.embedding_dropout_before_norm()
            {
                record_transformer_dropout(
                    &mut commands,
                    &self.kernels,
                    embedding_output_grad,
                    &self.grad_input_hidden,
                    self.config.embedding_dropout,
                    next_step,
                    TRANSFORMER_EMBEDDING_DROPOUT_SITE,
                    self.dropout_seed,
                    self.rows * self.config.hidden_size,
                )?;
                &self.grad_input_hidden
            } else {
                embedding_output_grad
            };
            let input_grad = if self.config.architecture == VulkanTransformerArchitecture::Esm {
                record_row_scale(
                    &mut commands,
                    &self.kernels,
                    input_grad,
                    &self.attention_mask,
                    &self.grad_input_hidden,
                    self.rows,
                    self.config.hidden_size,
                )?;
                &self.grad_input_hidden
            } else {
                input_grad
            };
            let token_embedding_grad = if let Some(embedding_norm) = self.embedding_norm.as_ref() {
                if self.config.architecture.embedding_norm_before_positions() {
                    if let Some(position_embedding) = self
                        .position_embedding
                        .as_ref()
                        .filter(|_| self.position_embeddings_trainable)
                    {
                        commands.fill_zero_f32(&position_embedding.grad, position_embedding.len)?;
                        let position_grad_push = PositionPush {
                            rows_or_batch: self.batch_size as u32,
                            seq_len: self.seq_len as u32,
                            dim: self.config.hidden_size as u32,
                            position_offset: 0,
                        };
                        self.kernels.position_grad.record_dispatch(
                            &mut commands,
                            &[input_grad, &position_embedding.grad],
                            bytemuck::bytes_of(&position_grad_push),
                            [
                                div_ceil_u32(self.config.hidden_size, 16),
                                div_ceil_u32(self.seq_len, 16),
                                1,
                            ],
                        )?;
                    }
                    embedding_norm.record_backward(
                        &mut commands,
                        &self.kernels,
                        &self.token_embedding_output,
                        input_grad,
                        &self.embedding_norm_mean,
                        &self.embedding_norm_rstd,
                        &self.grad_token_embedding_output,
                        self.rows,
                    )?;
                    &self.grad_token_embedding_output
                } else {
                    let composed_norm_input = if auxiliary_stream_active {
                        &self.embedding_composed_with_aux
                    } else if token_type_stream_active {
                        &self.embedding_composed_with_type
                    } else if self.position_embedding.is_some() {
                        &self.embedding_composed
                    } else {
                        &self.token_embedding_output
                    };
                    let norm_input = if self.config.architecture.embedding_dropout_before_norm()
                        && self.config.embedding_dropout > 0.0
                    {
                        &self.input_hidden_dropout
                    } else {
                        composed_norm_input
                    };
                    embedding_norm.record_backward(
                        &mut commands,
                        &self.kernels,
                        norm_input,
                        input_grad,
                        &self.embedding_norm_mean,
                        &self.embedding_norm_rstd,
                        &self.grad_token_embedding_output,
                        self.rows,
                    )?;
                    let embedding_component_grad =
                        if self.config.architecture.embedding_dropout_before_norm()
                            && self.config.embedding_dropout > 0.0
                        {
                            record_transformer_dropout(
                                &mut commands,
                                &self.kernels,
                                &self.grad_token_embedding_output,
                                &self.grad_input_hidden,
                                self.config.embedding_dropout,
                                next_step,
                                TRANSFORMER_EMBEDDING_DROPOUT_SITE,
                                self.dropout_seed,
                                self.rows * embedding_size,
                            )?;
                            &self.grad_input_hidden
                        } else {
                            &self.grad_token_embedding_output
                        };
                    if let Some(position_embedding) = self
                        .position_embedding
                        .as_ref()
                        .filter(|_| self.position_embeddings_trainable)
                    {
                        commands.fill_zero_f32(&position_embedding.grad, position_embedding.len)?;
                        if self.config.architecture.uses_roberta_position_ids() {
                            let position_grad_push = self.roberta_position_push()?;
                            self.kernels.roberta_position_grad.record_dispatch(
                                &mut commands,
                                &[
                                    embedding_component_grad,
                                    &self.token_ids,
                                    &position_embedding.grad,
                                ],
                                bytemuck::bytes_of(&position_grad_push),
                                [
                                    div_ceil_u32(self.config.hidden_size, 16),
                                    div_ceil_u32(self.config.max_position_embeddings, 16),
                                    1,
                                ],
                            )?;
                        } else if matches!(
                            self.config.architecture,
                            VulkanTransformerArchitecture::Bart
                                | VulkanTransformerArchitecture::MBart
                                | VulkanTransformerArchitecture::PLBart
                                | VulkanTransformerArchitecture::Mvp
                        ) {
                            let position_grad_push = OffsetPositionPush {
                                rows_or_batch: self.batch_size as u32,
                                seq_len: self.seq_len as u32,
                                dim: self.config.hidden_size as u32,
                                offset: 2,
                                embedding_scale: self.config.token_embedding_scale(),
                            };
                            self.kernels.offset_position_grad.record_dispatch(
                                &mut commands,
                                &[embedding_component_grad, &position_embedding.grad],
                                bytemuck::bytes_of(&position_grad_push),
                                [
                                    div_ceil_u32(self.config.hidden_size, 16),
                                    div_ceil_u32(self.seq_len, 16),
                                    1,
                                ],
                            )?;
                        } else {
                            let position_grad_push = PositionPush {
                                rows_or_batch: self.batch_size as u32,
                                seq_len: self.seq_len as u32,
                                dim: embedding_size as u32,
                                position_offset: 0,
                            };
                            self.kernels.position_grad.record_dispatch(
                                &mut commands,
                                &[embedding_component_grad, &position_embedding.grad],
                                bytemuck::bytes_of(&position_grad_push),
                                [
                                    div_ceil_u32(embedding_size, 16),
                                    div_ceil_u32(self.seq_len, 16),
                                    1,
                                ],
                            )?;
                        }
                    }
                    if matches!(
                        self.config.architecture,
                        VulkanTransformerArchitecture::Bart
                            | VulkanTransformerArchitecture::MBart
                            | VulkanTransformerArchitecture::PLBart
                            | VulkanTransformerArchitecture::Mvp
                    ) {
                        let embedding_scale = self.config.token_embedding_scale();
                        if embedding_scale == 1.0 {
                            embedding_component_grad
                        } else {
                            let copy_push = ScalePush {
                                len: (self.rows * self.config.hidden_size) as u32,
                                scale: embedding_scale,
                            };
                            self.kernels.scale_copy.record_dispatch(
                                &mut commands,
                                &[embedding_component_grad, &self.grad_input_hidden],
                                bytemuck::bytes_of(&copy_push),
                                [div_ceil_u32(self.rows * self.config.hidden_size, 256), 1, 1],
                            )?;
                            &self.grad_input_hidden
                        }
                    } else {
                        embedding_component_grad
                    }
                }
            } else {
                if let Some(position_embedding) = self.position_embedding.as_ref() {
                    if self.position_embeddings_trainable {
                        commands.fill_zero_f32(&position_embedding.grad, position_embedding.len)?;
                        if self.config.architecture == VulkanTransformerArchitecture::BioGpt {
                            let position_grad_push = OffsetPositionPush {
                                rows_or_batch: self.batch_size as u32,
                                seq_len: self.seq_len as u32,
                                dim: self.config.hidden_size as u32,
                                offset: 2,
                                embedding_scale: self.config.token_embedding_scale(),
                            };
                            self.kernels.offset_position_grad.record_dispatch(
                                &mut commands,
                                &[input_grad, &position_embedding.grad],
                                bytemuck::bytes_of(&position_grad_push),
                                [
                                    div_ceil_u32(self.config.hidden_size, 16),
                                    div_ceil_u32(self.seq_len, 16),
                                    1,
                                ],
                            )?;
                        } else if self.config.architecture == VulkanTransformerArchitecture::Opt {
                            let position_grad_push = OptPositionPush {
                                batch_size: self.batch_size as u32,
                                seq_len: self.seq_len as u32,
                                dim: self.config.hidden_size as u32,
                                table_rows: (self.config.max_position_embeddings + 2) as u32,
                                offset: 2,
                            };
                            self.kernels.opt_position_grad.record_dispatch(
                                &mut commands,
                                &[input_grad, &self.attention_mask, &position_embedding.grad],
                                bytemuck::bytes_of(&position_grad_push),
                                [
                                    div_ceil_u32(self.config.hidden_size, 16),
                                    div_ceil_u32(self.config.max_position_embeddings + 2, 16),
                                    1,
                                ],
                            )?;
                        } else {
                            let position_grad_push = PositionPush {
                                rows_or_batch: self.batch_size as u32,
                                seq_len: self.seq_len as u32,
                                dim: self.config.hidden_size as u32,
                                position_offset: 0,
                            };
                            self.kernels.position_grad.record_dispatch(
                                &mut commands,
                                &[input_grad, &position_embedding.grad],
                                bytemuck::bytes_of(&position_grad_push),
                                [
                                    div_ceil_u32(self.config.hidden_size, 16),
                                    div_ceil_u32(self.seq_len, 16),
                                    1,
                                ],
                            )?;
                        }
                    }
                }
                if let Some(embedding_project) = self
                    .embedding_project
                    .as_ref()
                    .filter(|_| self.config.architecture == VulkanTransformerArchitecture::Opt)
                {
                    embedding_project.record_backward(
                        &mut commands,
                        &self.kernels,
                        &self.token_embedding_output,
                        input_grad,
                        &self.grad_embedding_project_input,
                        self.rows,
                    )?;
                    &self.grad_embedding_project_input
                } else {
                    let embedding_scale = self.config.token_embedding_scale();
                    if embedding_scale == 1.0 {
                        input_grad
                    } else {
                        let copy_push = ScalePush {
                            len: (self.rows * self.config.hidden_size) as u32,
                            scale: embedding_scale,
                        };
                        self.kernels.scale_copy.record_dispatch(
                            &mut commands,
                            &[input_grad, &self.grad_token_embedding_output],
                            bytemuck::bytes_of(&copy_push),
                            [div_ceil_u32(self.rows * self.config.hidden_size, 256), 1, 1],
                        )?;
                        &self.grad_token_embedding_output
                    }
                }
            };
            let token_embedding_grad = if let Some(scale_buffer) = self.esm_token_scales.as_ref() {
                record_row_scale(
                    &mut commands,
                    &self.kernels,
                    token_embedding_grad,
                    scale_buffer,
                    &self.grad_embedding_dropout_input,
                    self.rows,
                    embedding_size,
                )?;
                &self.grad_embedding_dropout_input
            } else {
                token_embedding_grad
            };
            let word_embedding_grad = if let Some(frontend) = self
                .roc_bert_embedding_frontend
                .as_ref()
                .filter(|frontend| frontend.concat_input)
            {
                frontend.record_concat_backward(
                    &mut commands,
                    &self.kernels,
                    &self.token_embedding_output,
                    token_embedding_grad,
                    self.rows,
                )?
            } else {
                token_embedding_grad
            };
            let word_embedding_grad = if self
                .config
                .architecture
                .token_scale_before_embedding_composition()
                && self.config.token_embedding_scale() != 1.0
            {
                let scale_push = ScalePush {
                    len: (self.rows * embedding_size) as u32,
                    scale: self.config.token_embedding_scale(),
                };
                self.kernels.scale_copy.record_dispatch(
                    &mut commands,
                    &[word_embedding_grad, &self.grad_embedding_dropout_input],
                    bytemuck::bytes_of(&scale_push),
                    [div_ceil_u32(self.rows * embedding_size, 256), 1, 1],
                )?;
                &self.grad_embedding_dropout_input
            } else {
                word_embedding_grad
            };
            self.token_embedding.record_backward_accumulate(
                &mut commands,
                self.rows,
                &self.token_ids,
                word_embedding_grad,
            )?;
            if let Some(token_type_embedding) = self.token_type_embedding.as_ref() {
                if !peft_mode {
                    token_type_embedding.record_backward_accumulate(
                        &mut commands,
                        self.rows,
                        &self.token_type_ids,
                        token_embedding_grad,
                    )?;
                }
            } else if xlm_word_token_types && token_type_stream_active {
                self.token_embedding.record_backward_accumulate(
                    &mut commands,
                    self.rows,
                    &self.token_type_ids,
                    token_embedding_grad,
                )?;
            }
            if auxiliary_stream_active && !peft_mode {
                self.auxiliary_embedding
                    .as_ref()
                    .context("active Transformer auxiliary stream is missing its embedding table")?
                    .record_backward_accumulate(
                        &mut commands,
                        self.rows,
                        &self.auxiliary_ids,
                        token_embedding_grad,
                    )?;
            }
            if !peft_mode {
                if let Some(position_embedding) = self
                    .position_embedding
                    .as_ref()
                    .filter(|_| self.position_embeddings_trainable)
                {
                    position_embedding.record_step(
                        &mut commands,
                        &self.kernels,
                        next_step,
                        hyper,
                    )?;
                }
            }
            if let Some(embedding_norm) = self.embedding_norm.as_ref() {
                embedding_norm.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
            if let Some(embedding_project) = self.embedding_project.as_ref() {
                embedding_project.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
            if let Some(output_project) = self.output_project.as_ref() {
                output_project.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
            if !peft_mode {
                if let Some(token_type_embedding) = self.token_type_embedding.as_ref() {
                    let token_type_step = token_type_embedding
                        .shared_parameter()
                        .record_step(&mut commands, hyper)?;
                    if token_type_step != next_step {
                        bail!(
                            "token type embedding optimizer step {token_type_step} diverged from Transformer step {next_step}"
                        );
                    }
                }
                if auxiliary_stream_active {
                    let auxiliary_step = self
                        .auxiliary_embedding
                        .as_ref()
                        .context(
                            "active Transformer auxiliary stream is missing its embedding table",
                        )?
                        .shared_parameter()
                        .record_step(&mut commands, hyper)?;
                    if auxiliary_step != next_step {
                        bail!(
                            "auxiliary embedding optimizer step {auxiliary_step} diverged from Transformer step {next_step}"
                        );
                    }
                }
                if let Some(frontend) = self.roc_bert_embedding_frontend.as_ref() {
                    frontend.record_step(
                        &mut commands,
                        &self.kernels,
                        next_step,
                        hyper,
                        input_shape_ids,
                        input_pronunciation_ids,
                    )?;
                }
            }
        } else if peft_bias_all
            && matches!(
                self.config.architecture,
                VulkanTransformerArchitecture::Bert
                    | VulkanTransformerArchitecture::RemBert
                    | VulkanTransformerArchitecture::Electra
                    | VulkanTransformerArchitecture::Ernie
                    | VulkanTransformerArchitecture::RoFormer
            )
        {
            // PEFT bias="all" keeps the embedding tables and factorized
            // projection weights frozen, but trains the embedding LayerNorm
            // bias and (for RemBERT/ELECTRA/factorized RoFormer) the projection
            // bias. The ordinary PEFT fast path skips embedding backprop
            // entirely, so run only the minimal gradient chain needed to reach
            // those biases and stop before embedding-table accumulation.
            let embedding_output_grad = layer0_backward_grad;
            let norm_grad = if let Some(embedding_project) = self.embedding_project.as_ref() {
                let project_input = if self.config.embedding_dropout > 0.0 {
                    &self.embedding_dropout_output
                } else {
                    &self.embedding_norm_output
                };
                embedding_project.record_backward(
                    &mut commands,
                    &self.kernels,
                    project_input,
                    embedding_output_grad,
                    &self.grad_embedding_project_input,
                    self.rows,
                )?;
                if self.config.embedding_dropout > 0.0 {
                    record_transformer_dropout(
                        &mut commands,
                        &self.kernels,
                        &self.grad_embedding_project_input,
                        &self.grad_embedding_dropout_input,
                        self.config.embedding_dropout,
                        next_step,
                        TRANSFORMER_EMBEDDING_DROPOUT_SITE,
                        self.dropout_seed,
                        self.rows * embedding_size,
                    )?;
                    &self.grad_embedding_dropout_input
                } else {
                    &self.grad_embedding_project_input
                }
            } else if self.config.embedding_dropout > 0.0 {
                record_transformer_dropout(
                    &mut commands,
                    &self.kernels,
                    embedding_output_grad,
                    &self.grad_input_hidden,
                    self.config.embedding_dropout,
                    next_step,
                    TRANSFORMER_EMBEDDING_DROPOUT_SITE,
                    self.dropout_seed,
                    self.rows * self.config.hidden_size,
                )?;
                &self.grad_input_hidden
            } else {
                embedding_output_grad
            };
            let norm_input = if auxiliary_stream_active {
                &self.embedding_composed_with_aux
            } else if token_type_stream_active {
                &self.embedding_composed_with_type
            } else if self.position_embedding.is_some() {
                &self.embedding_composed
            } else {
                &self.token_embedding_output
            };
            let embedding_norm = self
                .embedding_norm
                .as_ref()
                .context("BERT bias=\"all\" graph is missing embedding LayerNorm")?;
            embedding_norm.record_backward(
                &mut commands,
                &self.kernels,
                norm_input,
                norm_grad,
                &self.embedding_norm_mean,
                &self.embedding_norm_rstd,
                &self.grad_token_embedding_output,
                self.rows,
            )?;
            embedding_norm.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            if let Some(embedding_project) = self.embedding_project.as_ref() {
                embedding_project.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
        }
        for (layer, active) in self.layers.iter().zip(&active_layers) {
            if *active {
                layer.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
            commands.watchdog_checkpoint()?;
        }
        if let Some(stack) = self.kimi_attn_res.as_ref() {
            stack.record_step(&mut commands, &self.kernels, next_step, hyper)?;
        }
        if let Some(head) = self.deepseek_v4_hyper_head.as_ref() {
            head.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            if self.config.uses_final_norm() {
                self.final_norm
                    .record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
        } else if let Some(mixer) = self.qwen4_final_mixer.as_ref() {
            mixer.record_step(&mut commands, &self.kernels, next_step, hyper)?;
        } else if self.config.uses_final_norm() {
            self.final_norm
                .record_step(&mut commands, &self.kernels, next_step, hyper)?;
        }
        if !peft_mode || peft_saves_lm_head || peft_bias_all {
            if let Some(lm_head) = self.lm_head.as_ref() {
                lm_head.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
        }
        if !peft_mode || peft_bias_all {
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                lm_head_bias.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
        }
        if !peft_mode || peft_bias_all || peft_saves_prediction_head_norm {
            if let Some(prediction_head) = self.prediction_head.as_ref() {
                prediction_head.record_step(&mut commands, &self.kernels, next_step, hyper)?;
            }
        }
        if !peft_mode {
            if let Some(relative_attention_bias) = self.relative_attention_bias.as_ref() {
                relative_attention_bias.record_step(
                    &mut commands,
                    &self.kernels,
                    next_step,
                    hyper,
                )?;
            }
            for relative_attention_bias in &self.per_layer_relative_attention_bias {
                relative_attention_bias.record_step(
                    &mut commands,
                    &self.kernels,
                    next_step,
                    hyper,
                )?;
            }
            let mut tied_hyper = hyper;
            tied_hyper.weight_decay = hyper.weight_decay;
            let tied_step = self
                .shared_embedding
                .record_step(&mut commands, tied_hyper)?;
            if tied_step != next_step {
                bail!(
                    "tied embedding optimizer step {tied_step} diverged from Transformer step {next_step}"
                );
            }
        } else if peft_saves_input_embedding {
            let tied_step = self.shared_embedding.record_step(&mut commands, hyper)?;
            if tied_step != next_step {
                bail!(
                    "saved input-embedding optimizer step {tied_step} diverged from Transformer step {next_step}"
                );
            }
        } else if peft_trainable_tokens_active {
            let tied_step = self.shared_embedding.record_step_rows(
                &mut commands,
                hyper,
                &self.lora_trainable_token_rows,
            )?;
            if tied_step != next_step {
                bail!(
                    "trainable-token embedding optimizer step {tied_step} diverged from Transformer step {next_step}"
                );
            }
        }
        self.loss_sum_reducer
            .record_sum(&mut commands, &self.row_loss, self.rows)?;
        commands.submit()?;
        for (layer, active) in self.layers.iter().zip(&active_layers) {
            if *active {
                layer.finish_qwen4_ple_sparse_embedding_step(next_step, hyper)?;
            }
        }
        self.step = next_step;
        let loss = self.loss_sum_reducer.read_sum()?;
        Ok(VulkanTransformerStepResult {
            loss,
            step: self.step,
            supervised_tokens,
        })
    }

    fn openai_gpt_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::OpenAiGpt {
            bail!("OpenAI GPT parameter export requires an OpenAI GPT graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.tokens_embed.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "transformer.positions_embed.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings, d],
                self.position_embedding
                    .as_ref()
                    .context("OpenAI GPT graph is missing its learned position embedding")?
                    .read()?,
            ),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.h.{index}");
            values.insert(
                format!("{p}.ln_1.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(format!("{p}.ln_1.bias"), (vec![d], layer.ln1.bias.read()?));
            values.insert(
                format!("{p}.attn.c_attn.weight"),
                (
                    vec![d, 3 * d],
                    transpose(
                        &layer
                            .c_attn
                            .as_ref()
                            .context("OpenAI GPT layer is missing c_attn")?
                            .weight
                            .read()?,
                        3 * d,
                        d,
                    ),
                ),
            );
            values.insert(
                format!("{p}.attn.c_attn.bias"),
                (
                    vec![3 * d],
                    layer
                        .c_attn
                        .as_ref()
                        .context("OpenAI GPT layer is missing c_attn")?
                        .bias
                        .read()?,
                ),
            );
            values.insert(
                format!("{p}.attn.c_proj.weight"),
                (vec![d, d], transpose(&layer.c_proj.weight.read()?, d, d)),
            );
            values.insert(
                format!("{p}.attn.c_proj.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.ln_2.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(format!("{p}.ln_2.bias"), (vec![d], layer.ln2.bias.read()?));
            values.insert(
                format!("{p}.mlp.c_fc.weight"),
                (vec![d, i], transpose(&layer.c_fc.weight.read()?, i, d)),
            );
            values.insert(
                format!("{p}.mlp.c_fc.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.c_proj.weight"),
                (
                    vec![i, d],
                    transpose(&layer.c_mlp_proj.weight.read()?, d, i),
                ),
            );
            values.insert(
                format!("{p}.mlp.c_proj.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn bert_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if !matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::Bert
                | VulkanTransformerArchitecture::RoCBert
                | VulkanTransformerArchitecture::RemBert
                | VulkanTransformerArchitecture::Electra
                | VulkanTransformerArchitecture::Ernie
                | VulkanTransformerArchitecture::MegatronBert
                | VulkanTransformerArchitecture::RoFormer
        ) {
            bail!(
                "BERT-like parameter export requires a BERT/RoCBert/RemBERT/ELECTRA/ERNIE/Megatron-BERT/RoFormer graph"
            );
        }
        let megatron_bert = self.config.architecture == VulkanTransformerArchitecture::MegatronBert;
        let roformer = self.config.architecture == VulkanTransformerArchitecture::RoFormer;
        let electra = self.config.architecture == VulkanTransformerArchitecture::Electra;
        let rembert = self.config.architecture == VulkanTransformerArchitecture::RemBert;
        let base = self
            .config
            .architecture
            .bert_family_base_prefix()
            .context("BERT-like parameter export requires a BERT-family checkpoint prefix")?;
        let d = self.config.hidden_size;
        let e = self.config.effective_embedding_size();
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            format!("{base}.embeddings.word_embeddings.weight"),
            (vec![self.config.vocab_size, e], token_embedding.clone()),
        );
        if !roformer {
            values.insert(
                format!("{base}.embeddings.position_embeddings.weight"),
                (
                    vec![self.config.max_position_embeddings, e],
                    self.position_embedding
                        .as_ref()
                        .context("BERT-like graph is missing its learned position embedding")?
                        .read()?,
                ),
            );
        }
        let token_type_embedding = self
            .token_type_embedding
            .as_ref()
            .context("BERT-like graph is missing its token type embedding")?;
        values.insert(
            format!("{base}.embeddings.token_type_embeddings.weight"),
            (
                vec![token_type_embedding.vocab_size(), e],
                token_type_embedding.weights()?,
            ),
        );
        if self.config.architecture == VulkanTransformerArchitecture::Ernie {
            if let Some(auxiliary_embedding) = self.auxiliary_embedding.as_ref() {
                values.insert(
                    "ernie.embeddings.task_type_embeddings.weight".to_owned(),
                    (
                        vec![auxiliary_embedding.vocab_size(), e],
                        auxiliary_embedding.weights()?,
                    ),
                );
            }
        }
        if !megatron_bert {
            let embedding_norm = self
                .embedding_norm
                .as_ref()
                .context("BERT-like graph is missing its embedding LayerNorm")?;
            values.insert(
                format!("{base}.embeddings.LayerNorm.weight"),
                (vec![e], embedding_norm.weight.read()?),
            );
            values.insert(
                format!("{base}.embeddings.LayerNorm.bias"),
                (vec![e], embedding_norm.bias.read()?),
            );
        }
        if e != d {
            let embedding_project = self
                .embedding_project
                .as_ref()
                .context("factorized BERT-like graph is missing its embedding projection")?;
            let projection_base = if rembert {
                format!("{base}.encoder.embedding_hidden_mapping_in")
            } else {
                format!("{base}.embeddings_project")
            };
            values.insert(
                format!("{projection_base}.weight"),
                (vec![d, e], embedding_project.weight.read()?),
            );
            values.insert(
                format!("{projection_base}.bias"),
                (vec![d], embedding_project.bias.read()?),
            );
        }
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("{base}.encoder.layer.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("BERT-like layer is missing query projection")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("BERT-like layer is missing key projection")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("BERT-like layer is missing value projection")?;
            for (name, linear) in [
                (format!("{p}.attention.self.query"), q_proj),
                (format!("{p}.attention.self.key"), k_proj),
                (format!("{p}.attention.self.value"), v_proj),
            ] {
                values.insert(
                    format!("{name}.weight"),
                    (vec![d, d], linear.weight.read()?),
                );
                values.insert(format!("{name}.bias"), (vec![d], linear.bias.read()?));
            }
            values.insert(
                format!("{p}.attention.output.dense.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.attention.output.dense.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            let attention_norm = if megatron_bert {
                format!("{p}.attention.ln")
            } else {
                format!("{p}.attention.output.LayerNorm")
            };
            values.insert(
                format!("{attention_norm}.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{attention_norm}.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            if let Some(cross_attention) = layer.cross_attention.as_ref() {
                for (name, linear) in [
                    (
                        format!("{p}.crossattention.self.query"),
                        &cross_attention.q_proj,
                    ),
                    (
                        format!("{p}.crossattention.self.key"),
                        &cross_attention.k_proj,
                    ),
                    (
                        format!("{p}.crossattention.self.value"),
                        &cross_attention.v_proj,
                    ),
                ] {
                    values.insert(
                        format!("{name}.weight"),
                        (vec![d, d], linear.weight.read()?),
                    );
                    values.insert(format!("{name}.bias"), (vec![d], linear.bias.read()?));
                }
                values.insert(
                    format!("{p}.crossattention.output.dense.weight"),
                    (vec![d, d], cross_attention.out_proj.weight.read()?),
                );
                values.insert(
                    format!("{p}.crossattention.output.dense.bias"),
                    (vec![d], cross_attention.out_proj.bias.read()?),
                );
                values.insert(
                    if megatron_bert {
                        format!("{p}.crossattention.ln.weight")
                    } else {
                        format!("{p}.crossattention.output.LayerNorm.weight")
                    },
                    (vec![d], cross_attention.norm.weight.read()?),
                );
                values.insert(
                    if megatron_bert {
                        format!("{p}.crossattention.ln.bias")
                    } else {
                        format!("{p}.crossattention.output.LayerNorm.bias")
                    },
                    (vec![d], cross_attention.norm.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.intermediate.dense.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.intermediate.dense.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.output.dense.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.output.dense.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
            let mlp_norm = if megatron_bert {
                format!("{p}.ln")
            } else {
                format!("{p}.output.LayerNorm")
            };
            values.insert(
                format!("{mlp_norm}.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{mlp_norm}.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }
        if megatron_bert {
            values.insert(
                format!("{base}.encoder.ln.weight"),
                (vec![d], self.final_norm.weight.read()?),
            );
            values.insert(
                format!("{base}.encoder.ln.bias"),
                (vec![d], self.final_norm.bias.read()?),
            );
        }
        let prediction_head = self
            .prediction_head
            .as_ref()
            .context("BERT-like graph is missing its MLM prediction transform")?;
        let o = prediction_head.output_dim;
        let prediction_base = if electra {
            "generator_predictions"
        } else if rembert {
            "cls.predictions"
        } else {
            "cls.predictions.transform"
        };
        values.insert(
            format!("{prediction_base}.dense.weight"),
            (vec![o, d], prediction_head.dense.weight.read()?),
        );
        values.insert(
            format!("{prediction_base}.dense.bias"),
            (vec![o], prediction_head.dense.bias.read()?),
        );
        values.insert(
            format!("{prediction_base}.LayerNorm.weight"),
            (vec![o], prediction_head.norm.weight.read()?),
        );
        values.insert(
            format!("{prediction_base}.LayerNorm.bias"),
            (vec![o], prediction_head.norm.bias.read()?),
        );
        let decoder_weight_name = if electra {
            "generator_lm_head.weight"
        } else {
            "cls.predictions.decoder.weight"
        };
        let decoder_bias_name = if electra {
            "generator_lm_head.bias"
        } else {
            "cls.predictions.decoder.bias"
        };
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                decoder_weight_name.to_owned(),
                (vec![self.config.vocab_size, o], lm_head.weight.read()?),
            );
            let bias = lm_head.bias.read()?;
            values.insert(
                decoder_bias_name.to_owned(),
                (vec![self.config.vocab_size], bias.clone()),
            );
            if !electra && !rembert {
                values.insert(
                    "cls.predictions.bias".to_owned(),
                    (vec![self.config.vocab_size], bias),
                );
            }
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    decoder_weight_name.to_owned(),
                    (vec![self.config.vocab_size, o], token_embedding),
                );
            }
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                let bias = lm_head_bias.read()?;
                values.insert(
                    decoder_bias_name.to_owned(),
                    (vec![self.config.vocab_size], bias.clone()),
                );
                if !electra && !rembert {
                    values.insert(
                        "cls.predictions.bias".to_owned(),
                        (vec![self.config.vocab_size], bias),
                    );
                }
            }
        }
        Ok(values)
    }

    fn albert_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Albert {
            bail!("ALBERT parameter export requires an ALBERT graph");
        }
        let topology = self
            .albert_topology
            .as_ref()
            .context("ALBERT graph is missing its physical layer topology")?;
        if topology.logical_to_physical.len() != self.layers.len() {
            bail!(
                "ALBERT topology contains {} logical uses for {} runtime layers",
                topology.logical_to_physical.len(),
                self.layers.len()
            );
        }

        let d = self.config.hidden_size;
        let e = self.config.effective_embedding_size();
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "albert.embeddings.word_embeddings.weight".to_owned(),
            (vec![self.config.vocab_size, e], token_embedding.clone()),
        );
        values.insert(
            "albert.embeddings.position_embeddings.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings, e],
                self.position_embedding
                    .as_ref()
                    .context("ALBERT graph is missing its position embedding")?
                    .read()?,
            ),
        );
        let token_type_embedding = self
            .token_type_embedding
            .as_ref()
            .context("ALBERT graph is missing its token type embedding")?;
        values.insert(
            "albert.embeddings.token_type_embeddings.weight".to_owned(),
            (
                vec![token_type_embedding.vocab_size(), e],
                token_type_embedding.weights()?,
            ),
        );
        let embedding_norm = self
            .embedding_norm
            .as_ref()
            .context("ALBERT graph is missing its embedding LayerNorm")?;
        values.insert(
            "albert.embeddings.LayerNorm.weight".to_owned(),
            (vec![e], embedding_norm.weight.read()?),
        );
        values.insert(
            "albert.embeddings.LayerNorm.bias".to_owned(),
            (vec![e], embedding_norm.bias.read()?),
        );
        let embedding_project = self
            .embedding_project
            .as_ref()
            .context("ALBERT graph is missing embedding_hidden_mapping_in")?;
        values.insert(
            "albert.encoder.embedding_hidden_mapping_in.weight".to_owned(),
            (vec![d, e], embedding_project.weight.read()?),
        );
        values.insert(
            "albert.encoder.embedding_hidden_mapping_in.bias".to_owned(),
            (vec![d], embedding_project.bias.read()?),
        );

        let physical_count = topology.physical_layer_count()?;
        for physical in 0..physical_count {
            let logical = topology
                .logical_to_physical
                .iter()
                .position(|&candidate| candidate == physical)
                .with_context(|| format!("ALBERT physical layer {physical} has no logical use"))?;
            let layer = &self.layers[logical];
            let (group, inner) = topology.physical_coordinates(physical)?;
            let p = format!("albert.encoder.albert_layer_groups.{group}.albert_layers.{inner}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("ALBERT layer is missing query projection")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("ALBERT layer is missing key projection")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("ALBERT layer is missing value projection")?;
            for (name, linear) in [
                (format!("{p}.attention.query"), q_proj),
                (format!("{p}.attention.key"), k_proj),
                (format!("{p}.attention.value"), v_proj),
                (format!("{p}.attention.dense"), &layer.c_proj),
            ] {
                values.insert(
                    format!("{name}.weight"),
                    (
                        vec![linear.output_dim, linear.input_dim],
                        linear.weight.read()?,
                    ),
                );
                if linear.has_bias {
                    values.insert(
                        format!("{name}.bias"),
                        (vec![linear.output_dim], linear.bias.read()?),
                    );
                }
            }
            values.insert(
                format!("{p}.attention.LayerNorm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.attention.LayerNorm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            values.insert(
                format!("{p}.ffn.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(format!("{p}.ffn.bias"), (vec![i], layer.c_fc.bias.read()?));
            values.insert(
                format!("{p}.ffn_output.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.ffn_output.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.full_layer_layer_norm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.full_layer_layer_norm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }

        let prediction_head = self
            .prediction_head
            .as_ref()
            .context("ALBERT graph is missing its MLM prediction head")?;
        if prediction_head.output_dim != e {
            bail!(
                "ALBERT prediction head outputs {}, expected embedding_size={e}",
                prediction_head.output_dim
            );
        }
        values.insert(
            "predictions.dense.weight".to_owned(),
            (vec![e, d], prediction_head.dense.weight.read()?),
        );
        values.insert(
            "predictions.dense.bias".to_owned(),
            (vec![e], prediction_head.dense.bias.read()?),
        );
        values.insert(
            "predictions.LayerNorm.weight".to_owned(),
            (vec![e], prediction_head.norm.weight.read()?),
        );
        values.insert(
            "predictions.LayerNorm.bias".to_owned(),
            (vec![e], prediction_head.norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "predictions.decoder.weight".to_owned(),
                (vec![self.config.vocab_size, e], lm_head.weight.read()?),
            );
            if lm_head.has_bias {
                let bias = lm_head.bias.read()?;
                values.insert(
                    "predictions.bias".to_owned(),
                    (vec![self.config.vocab_size], bias.clone()),
                );
                values.insert(
                    "predictions.decoder.bias".to_owned(),
                    (vec![self.config.vocab_size], bias),
                );
            }
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    "predictions.decoder.weight".to_owned(),
                    (vec![self.config.vocab_size, e], token_embedding),
                );
            }
            if let Some(bias) = self.lm_head_bias.as_ref() {
                let bias = bias.read()?;
                values.insert(
                    "predictions.bias".to_owned(),
                    (vec![self.config.vocab_size], bias.clone()),
                );
                values.insert(
                    "predictions.decoder.bias".to_owned(),
                    (vec![self.config.vocab_size], bias),
                );
            }
        }
        Ok(values)
    }

    fn roc_bert_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::RoCBert {
            bail!("RoCBert parameter export requires a RoCBert graph");
        }
        let mut values = self.bert_parameter_tensors()?;
        let frontend = self
            .roc_bert_embedding_frontend
            .as_ref()
            .context("RoCBert graph is missing its auxiliary embedding frontend")?;
        values.insert(
            "roc_bert.embeddings.shape_embed.weight".to_owned(),
            (
                vec![
                    frontend.shape_embedding.vocab_size(),
                    frontend.shape_embedding.dim(),
                ],
                frontend.shape_embedding.weights()?,
            ),
        );
        values.insert(
            "roc_bert.embeddings.pronunciation_embed.weight".to_owned(),
            (
                vec![
                    frontend.pronunciation_embedding.vocab_size(),
                    frontend.pronunciation_embedding.dim(),
                ],
                frontend.pronunciation_embedding.weights()?,
            ),
        );
        if frontend.concat_input {
            let word = frontend
                .map_word
                .as_ref()
                .context("RoCBert concat_input=true is missing map_inputs_layer word block")?;
            let word_weight = word.weight.read()?;
            let shape_weight = frontend
                .map_shape
                .as_ref()
                .map(|linear| linear.weight.read())
                .transpose()?;
            let pronunciation_weight = frontend
                .map_pronunciation
                .as_ref()
                .map(|linear| linear.weight.read())
                .transpose()?;
            let shape_dim = if frontend.enable_shape {
                frontend.shape_embedding.dim()
            } else {
                0
            };
            let pronunciation_dim = if frontend.enable_pronunciation {
                frontend.pronunciation_embedding.dim()
            } else {
                0
            };
            let input_dim = self
                .config
                .hidden_size
                .checked_add(shape_dim)
                .and_then(|dim| dim.checked_add(pronunciation_dim))
                .context("RoCBert map_inputs_layer export dimension overflow")?;
            let mut combined = Vec::with_capacity(self.config.hidden_size * input_dim);
            for row in 0..self.config.hidden_size {
                let word_start = row * self.config.hidden_size;
                combined.extend_from_slice(
                    &word_weight[word_start..word_start + self.config.hidden_size],
                );
                if let Some(shape_weight) = shape_weight.as_ref() {
                    let start = row * shape_dim;
                    combined.extend_from_slice(&shape_weight[start..start + shape_dim]);
                }
                if let Some(pronunciation_weight) = pronunciation_weight.as_ref() {
                    let start = row * pronunciation_dim;
                    combined
                        .extend_from_slice(&pronunciation_weight[start..start + pronunciation_dim]);
                }
            }
            values.insert(
                "roc_bert.embeddings.map_inputs_layer.weight".to_owned(),
                (vec![self.config.hidden_size, input_dim], combined),
            );
            values.insert(
                "roc_bert.embeddings.map_inputs_layer.bias".to_owned(),
                (vec![self.config.hidden_size], word.bias.read()?),
            );
        }
        Ok(values)
    }

    fn nomic_bert_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::NomicBert {
            bail!("Nomic BERT parameter export requires a Nomic BERT graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let q = self.config.query_hidden_size();
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "nomic_bert.embeddings.word_embeddings.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        let token_type_embedding = self
            .token_type_embedding
            .as_ref()
            .context("Nomic BERT graph is missing its token type embedding")?;
        values.insert(
            "nomic_bert.embeddings.token_type_embeddings.weight".to_owned(),
            (
                vec![token_type_embedding.vocab_size(), d],
                token_type_embedding.weights()?,
            ),
        );
        let embedding_norm = self
            .embedding_norm
            .as_ref()
            .context("Nomic BERT graph is missing its embedding LayerNorm")?;
        values.insert(
            "nomic_bert.embeddings.LayerNorm.weight".to_owned(),
            (vec![d], embedding_norm.weight.read()?),
        );
        values.insert(
            "nomic_bert.embeddings.LayerNorm.bias".to_owned(),
            (vec![d], embedding_norm.bias.read()?),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("nomic_bert.layers.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("Nomic BERT layer is missing q_proj")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("Nomic BERT layer is missing k_proj")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("Nomic BERT layer is missing v_proj")?;
            for (name, projection) in [("q_proj", q_proj), ("k_proj", k_proj), ("v_proj", v_proj)] {
                values.insert(
                    format!("{p}.self_attn.{name}.weight"),
                    (vec![q, d], projection.weight.read()?),
                );
            }
            values.insert(
                format!("{p}.self_attn.o_proj.weight"),
                (vec![d, q], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            let gate = layer
                .c_gate
                .as_ref()
                .context("Nomic BERT layer is missing gate_proj")?;
            values.insert(
                format!("{p}.mlp.gate_proj.weight"),
                (vec![i, d], gate.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.up_proj.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.down_proj.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.post_mlp_layernorm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.post_mlp_layernorm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }
        let prediction_head = self
            .prediction_head
            .as_ref()
            .context("Nomic BERT graph is missing its MLM prediction transform")?;
        values.insert(
            "cls.predictions.transform.dense.weight".to_owned(),
            (vec![d, d], prediction_head.dense.weight.read()?),
        );
        values.insert(
            "cls.predictions.transform.dense.bias".to_owned(),
            (vec![d], prediction_head.dense.bias.read()?),
        );
        values.insert(
            "cls.predictions.transform.layer_norm.weight".to_owned(),
            (vec![d], prediction_head.norm.weight.read()?),
        );
        values.insert(
            "cls.predictions.transform.layer_norm.bias".to_owned(),
            (vec![d], prediction_head.norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "cls.predictions.decoder.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
            if lm_head.has_bias {
                let bias = lm_head.bias.read()?;
                values.insert(
                    "cls.predictions.decoder.bias".to_owned(),
                    (vec![self.config.vocab_size], bias.clone()),
                );
                values.insert(
                    "cls.predictions.bias".to_owned(),
                    (vec![self.config.vocab_size], bias),
                );
            }
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    "cls.predictions.decoder.weight".to_owned(),
                    (vec![self.config.vocab_size, d], token_embedding),
                );
            }
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                let bias = lm_head_bias.read()?;
                values.insert(
                    "cls.predictions.decoder.bias".to_owned(),
                    (vec![self.config.vocab_size], bias.clone()),
                );
                values.insert(
                    "cls.predictions.bias".to_owned(),
                    (vec![self.config.vocab_size], bias),
                );
            }
        }
        Ok(values)
    }

    fn jina_embeddings_v3_parameter_tensors(
        &self,
    ) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::JinaEmbeddingsV3 {
            bail!("Jina Embeddings v3 parameter export requires a Jina Embeddings v3 graph");
        }
        let d = self.config.hidden_size;
        let q = self.config.query_hidden_size();
        let kv = self.config.key_value_hidden_size();
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "roberta.embeddings.word_embeddings.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        let token_type_embedding = self
            .token_type_embedding
            .as_ref()
            .context("Jina Embeddings v3 graph is missing its token type embedding")?;
        values.insert(
            "roberta.embeddings.token_type_embeddings.weight".to_owned(),
            (
                vec![token_type_embedding.vocab_size(), d],
                token_type_embedding.weights()?,
            ),
        );
        let embedding_norm = self
            .embedding_norm
            .as_ref()
            .context("Jina Embeddings v3 graph is missing its embedding LayerNorm")?;
        values.insert(
            "roberta.embeddings.LayerNorm.weight".to_owned(),
            (vec![d], embedding_norm.weight.read()?),
        );
        values.insert(
            "roberta.embeddings.LayerNorm.bias".to_owned(),
            (vec![d], embedding_norm.bias.read()?),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let i = self.config.layer_intermediate_size(index);
            let p = format!("roberta.layers.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("Jina Embeddings v3 layer is missing q_proj")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("Jina Embeddings v3 layer is missing k_proj")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("Jina Embeddings v3 layer is missing v_proj")?;
            for (name, projection, out) in [
                ("q_proj", q_proj, q),
                ("k_proj", k_proj, kv),
                ("v_proj", v_proj, kv),
            ] {
                values.insert(
                    format!("{p}.self_attn.{name}.weight"),
                    (vec![out, d], projection.weight.read()?),
                );
                values.insert(
                    format!("{p}.self_attn.{name}.bias"),
                    (vec![out], projection.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.self_attn.o_proj.weight"),
                (vec![d, q], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.self_attn.o_proj.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.fc1.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.fc1.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.fc2.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.fc2.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.post_mlp_layernorm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.post_mlp_layernorm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }
        let prediction_head = self
            .prediction_head
            .as_ref()
            .context("Jina Embeddings v3 graph is missing its MLM prediction transform")?;
        values.insert(
            "lm_head.dense.weight".to_owned(),
            (vec![d, d], prediction_head.dense.weight.read()?),
        );
        values.insert(
            "lm_head.dense.bias".to_owned(),
            (vec![d], prediction_head.dense.bias.read()?),
        );
        values.insert(
            "lm_head.layer_norm.weight".to_owned(),
            (vec![d], prediction_head.norm.weight.read()?),
        );
        values.insert(
            "lm_head.layer_norm.bias".to_owned(),
            (vec![d], prediction_head.norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.decoder.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
            if lm_head.has_bias {
                let bias = lm_head.bias.read()?;
                values.insert(
                    "lm_head.decoder.bias".to_owned(),
                    (vec![self.config.vocab_size], bias.clone()),
                );
                values.insert(
                    "lm_head.bias".to_owned(),
                    (vec![self.config.vocab_size], bias),
                );
            }
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    "lm_head.decoder.weight".to_owned(),
                    (vec![self.config.vocab_size, d], token_embedding),
                );
            }
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                let bias = lm_head_bias.read()?;
                values.insert(
                    "lm_head.decoder.bias".to_owned(),
                    (vec![self.config.vocab_size], bias.clone()),
                );
                values.insert(
                    "lm_head.bias".to_owned(),
                    (vec![self.config.vocab_size], bias),
                );
            }
        }
        Ok(values)
    }

    fn roberta_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if !self.config.architecture.uses_roberta_position_ids() {
            bail!("RoBERTa-like parameter export requires a padding-aware BERT-family graph");
        }
        let base =
            self.config.architecture.bert_family_base_prefix().context(
                "RoBERTa-like parameter export requires a BERT-family checkpoint prefix",
            )?;
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let pre_layer_norm = matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::RobertaPreLayerNorm
                | VulkanTransformerArchitecture::XlmRobertaXL
        );
        let xlm_roberta_xl =
            self.config.architecture == VulkanTransformerArchitecture::XlmRobertaXL;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            format!("{base}.embeddings.word_embeddings.weight"),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            format!("{base}.embeddings.position_embeddings.weight"),
            (
                vec![self.config.max_position_embeddings, d],
                self.position_embedding
                    .as_ref()
                    .context("RoBERTa graph is missing its learned position embedding")?
                    .read()?,
            ),
        );
        let token_type_embedding = self
            .token_type_embedding
            .as_ref()
            .context("RoBERTa graph is missing its token type embedding")?;
        values.insert(
            format!("{base}.embeddings.token_type_embeddings.weight"),
            (
                vec![token_type_embedding.vocab_size(), d],
                token_type_embedding.weights()?,
            ),
        );
        if !xlm_roberta_xl {
            let embedding_norm = self
                .embedding_norm
                .as_ref()
                .context("RoBERTa graph is missing its embedding LayerNorm")?;
            values.insert(
                format!("{base}.embeddings.LayerNorm.weight"),
                (vec![d], embedding_norm.weight.read()?),
            );
            values.insert(
                format!("{base}.embeddings.LayerNorm.bias"),
                (vec![d], embedding_norm.bias.read()?),
            );
        }
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("{base}.encoder.layer.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("RoBERTa layer is missing query projection")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("RoBERTa layer is missing key projection")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("RoBERTa layer is missing value projection")?;
            for (name, linear) in [
                (format!("{p}.attention.self.query"), q_proj),
                (format!("{p}.attention.self.key"), k_proj),
                (format!("{p}.attention.self.value"), v_proj),
            ] {
                values.insert(
                    format!("{name}.weight"),
                    (vec![d, d], linear.weight.read()?),
                );
                values.insert(format!("{name}.bias"), (vec![d], linear.bias.read()?));
            }
            values.insert(
                format!("{p}.attention.output.dense.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.attention.output.dense.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            let attention_norm = if xlm_roberta_xl {
                format!("{p}.attention.self_attn_layer_norm")
            } else if pre_layer_norm {
                format!("{p}.attention.LayerNorm")
            } else {
                format!("{p}.attention.output.LayerNorm")
            };
            values.insert(
                format!("{attention_norm}.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{attention_norm}.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            if let Some(cross_attention) = layer.cross_attention.as_ref() {
                let cross = format!("{p}.crossattention");
                for (name, linear) in [
                    (format!("{cross}.self.query"), &cross_attention.q_proj),
                    (format!("{cross}.self.key"), &cross_attention.k_proj),
                    (format!("{cross}.self.value"), &cross_attention.v_proj),
                    (format!("{cross}.output.dense"), &cross_attention.out_proj),
                ] {
                    values.insert(
                        format!("{name}.weight"),
                        (vec![d, d], linear.weight.read()?),
                    );
                    values.insert(format!("{name}.bias"), (vec![d], linear.bias.read()?));
                }
                let cross_norm = if xlm_roberta_xl {
                    format!("{cross}.self_attn_layer_norm")
                } else if pre_layer_norm {
                    format!("{cross}.LayerNorm")
                } else {
                    format!("{cross}.output.LayerNorm")
                };
                values.insert(
                    format!("{cross_norm}.weight"),
                    (vec![d], cross_attention.norm.weight.read()?),
                );
                values.insert(
                    format!("{cross_norm}.bias"),
                    (vec![d], cross_attention.norm.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.intermediate.dense.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.intermediate.dense.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.output.dense.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.output.dense.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
            let mlp_norm = if xlm_roberta_xl {
                format!("{p}.LayerNorm")
            } else if pre_layer_norm {
                format!("{p}.intermediate.LayerNorm")
            } else {
                format!("{p}.output.LayerNorm")
            };
            values.insert(
                format!("{mlp_norm}.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{mlp_norm}.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }
        if xlm_roberta_xl {
            values.insert(
                format!("{base}.encoder.LayerNorm.weight"),
                (vec![d], self.final_norm.weight.read()?),
            );
            values.insert(
                format!("{base}.encoder.LayerNorm.bias"),
                (vec![d], self.final_norm.bias.read()?),
            );
        } else if pre_layer_norm {
            values.insert(
                format!("{base}.LayerNorm.weight"),
                (vec![d], self.final_norm.weight.read()?),
            );
            values.insert(
                format!("{base}.LayerNorm.bias"),
                (vec![d], self.final_norm.bias.read()?),
            );
        }
        let prediction_head = self
            .prediction_head
            .as_ref()
            .context("RoBERTa graph is missing its MLM prediction transform")?;
        values.insert(
            "lm_head.dense.weight".to_owned(),
            (vec![d, d], prediction_head.dense.weight.read()?),
        );
        values.insert(
            "lm_head.dense.bias".to_owned(),
            (vec![d], prediction_head.dense.bias.read()?),
        );
        values.insert(
            "lm_head.layer_norm.weight".to_owned(),
            (vec![d], prediction_head.norm.weight.read()?),
        );
        values.insert(
            "lm_head.layer_norm.bias".to_owned(),
            (vec![d], prediction_head.norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.decoder.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
            let bias = lm_head.bias.read()?;
            values.insert(
                "lm_head.bias".to_owned(),
                (vec![self.config.vocab_size], bias.clone()),
            );
            values.insert(
                "lm_head.decoder.bias".to_owned(),
                (vec![self.config.vocab_size], bias),
            );
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    "lm_head.decoder.weight".to_owned(),
                    (vec![self.config.vocab_size, d], token_embedding),
                );
            }
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                let bias = lm_head_bias.read()?;
                values.insert(
                    "lm_head.bias".to_owned(),
                    (vec![self.config.vocab_size], bias.clone()),
                );
                values.insert(
                    "lm_head.decoder.bias".to_owned(),
                    (vec![self.config.vocab_size], bias),
                );
            }
        }
        Ok(values)
    }

    fn bert_generation_parameter_tensors(
        &self,
    ) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::BertGeneration {
            bail!("BertGeneration parameter export requires a BertGeneration graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "bert.embeddings.word_embeddings.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "bert.embeddings.position_embeddings.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings, d],
                self.position_embedding
                    .as_ref()
                    .context("BertGeneration graph is missing its learned position embedding")?
                    .read()?,
            ),
        );
        let embedding_norm = self
            .embedding_norm
            .as_ref()
            .context("BertGeneration graph is missing its embedding LayerNorm")?;
        values.insert(
            "bert.embeddings.LayerNorm.weight".to_owned(),
            (vec![d], embedding_norm.weight.read()?),
        );
        values.insert(
            "bert.embeddings.LayerNorm.bias".to_owned(),
            (vec![d], embedding_norm.bias.read()?),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("bert.encoder.layer.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("BertGeneration layer is missing query projection")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("BertGeneration layer is missing key projection")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("BertGeneration layer is missing value projection")?;
            for (name, linear) in [
                (format!("{p}.attention.self.query"), q_proj),
                (format!("{p}.attention.self.key"), k_proj),
                (format!("{p}.attention.self.value"), v_proj),
            ] {
                values.insert(
                    format!("{name}.weight"),
                    (vec![d, d], linear.weight.read()?),
                );
                values.insert(format!("{name}.bias"), (vec![d], linear.bias.read()?));
            }
            values.insert(
                format!("{p}.attention.output.dense.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.attention.output.dense.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.attention.output.LayerNorm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.attention.output.LayerNorm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            if let Some(cross_attention) = layer.cross_attention.as_ref() {
                for (name, linear) in [
                    (
                        format!("{p}.crossattention.self.query"),
                        &cross_attention.q_proj,
                    ),
                    (
                        format!("{p}.crossattention.self.key"),
                        &cross_attention.k_proj,
                    ),
                    (
                        format!("{p}.crossattention.self.value"),
                        &cross_attention.v_proj,
                    ),
                ] {
                    values.insert(
                        format!("{name}.weight"),
                        (vec![d, d], linear.weight.read()?),
                    );
                    values.insert(format!("{name}.bias"), (vec![d], linear.bias.read()?));
                }
                values.insert(
                    format!("{p}.crossattention.output.dense.weight"),
                    (vec![d, d], cross_attention.out_proj.weight.read()?),
                );
                values.insert(
                    format!("{p}.crossattention.output.dense.bias"),
                    (vec![d], cross_attention.out_proj.bias.read()?),
                );
                values.insert(
                    format!("{p}.crossattention.output.LayerNorm.weight"),
                    (vec![d], cross_attention.norm.weight.read()?),
                );
                values.insert(
                    format!("{p}.crossattention.output.LayerNorm.bias"),
                    (vec![d], cross_attention.norm.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.intermediate.dense.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.intermediate.dense.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.output.dense.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.output.dense.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.output.LayerNorm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.output.LayerNorm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.decoder.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
            values.insert(
                "lm_head.bias".to_owned(),
                (vec![self.config.vocab_size], lm_head.bias.read()?),
            );
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    "lm_head.decoder.weight".to_owned(),
                    (vec![self.config.vocab_size, d], token_embedding),
                );
            }
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                values.insert(
                    "lm_head.bias".to_owned(),
                    (vec![self.config.vocab_size], lm_head_bias.read()?),
                );
            }
        }
        Ok(values)
    }

    fn distilbert_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::DistilBert {
            bail!("DistilBERT parameter export requires a DistilBERT graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "distilbert.embeddings.word_embeddings.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "distilbert.embeddings.position_embeddings.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings, d],
                self.position_embedding
                    .as_ref()
                    .context("DistilBERT graph is missing its learned position embedding")?
                    .read()?,
            ),
        );
        let embedding_norm = self
            .embedding_norm
            .as_ref()
            .context("DistilBERT graph is missing its embedding LayerNorm")?;
        values.insert(
            "distilbert.embeddings.LayerNorm.weight".to_owned(),
            (vec![d], embedding_norm.weight.read()?),
        );
        values.insert(
            "distilbert.embeddings.LayerNorm.bias".to_owned(),
            (vec![d], embedding_norm.bias.read()?),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("distilbert.transformer.layer.{index}");
            for (name, linear) in [
                (
                    format!("{p}.attention.q_lin"),
                    layer
                        .q_proj
                        .as_ref()
                        .context("DistilBERT layer is missing q_lin")?,
                ),
                (
                    format!("{p}.attention.k_lin"),
                    layer
                        .k_proj
                        .as_ref()
                        .context("DistilBERT layer is missing k_lin")?,
                ),
                (
                    format!("{p}.attention.v_lin"),
                    layer
                        .v_proj
                        .as_ref()
                        .context("DistilBERT layer is missing v_lin")?,
                ),
                (format!("{p}.attention.out_lin"), &layer.c_proj),
            ] {
                values.insert(
                    format!("{name}.weight"),
                    (vec![d, d], linear.weight.read()?),
                );
                values.insert(format!("{name}.bias"), (vec![d], linear.bias.read()?));
            }
            values.insert(
                format!("{p}.sa_layer_norm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.sa_layer_norm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            values.insert(
                format!("{p}.ffn.lin1.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.ffn.lin1.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.ffn.lin2.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.ffn.lin2.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.output_layer_norm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.output_layer_norm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }
        let prediction_head = self
            .prediction_head
            .as_ref()
            .context("DistilBERT graph is missing its MLM prediction head")?;
        values.insert(
            "vocab_transform.weight".to_owned(),
            (vec![d, d], prediction_head.dense.weight.read()?),
        );
        values.insert(
            "vocab_transform.bias".to_owned(),
            (vec![d], prediction_head.dense.bias.read()?),
        );
        values.insert(
            "vocab_layer_norm.weight".to_owned(),
            (vec![d], prediction_head.norm.weight.read()?),
        );
        values.insert(
            "vocab_layer_norm.bias".to_owned(),
            (vec![d], prediction_head.norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "vocab_projector.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
            values.insert(
                "vocab_projector.bias".to_owned(),
                (vec![self.config.vocab_size], lm_head.bias.read()?),
            );
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    "vocab_projector.weight".to_owned(),
                    (vec![self.config.vocab_size, d], token_embedding),
                );
            }
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                values.insert(
                    "vocab_projector.bias".to_owned(),
                    (vec![self.config.vocab_size], lm_head_bias.read()?),
                );
            }
        }
        Ok(values)
    }

    fn xlm_family_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if !matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::Xlm | VulkanTransformerArchitecture::Flaubert
        ) {
            bail!("XLM-family parameter export requires an XLM or Flaubert graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.embeddings.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "transformer.position_embeddings.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings, d],
                self.position_embedding
                    .as_ref()
                    .context("XLM-family graph is missing its learned position embedding")?
                    .read()?,
            ),
        );
        if let Some(auxiliary_embedding) = self.auxiliary_embedding.as_ref() {
            values.insert(
                "transformer.lang_embeddings.weight".to_owned(),
                (
                    vec![auxiliary_embedding.vocab_size(), d],
                    auxiliary_embedding.weights()?,
                ),
            );
        }
        let embedding_norm = self
            .embedding_norm
            .as_ref()
            .context("XLM-family graph is missing its embedding LayerNorm")?;
        values.insert(
            "transformer.layer_norm_emb.weight".to_owned(),
            (vec![d], embedding_norm.weight.read()?),
        );
        values.insert(
            "transformer.layer_norm_emb.bias".to_owned(),
            (vec![d], embedding_norm.bias.read()?),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let attention = format!("transformer.attentions.{index}");
            let ffn = format!("transformer.ffns.{index}");
            for (name, linear) in [
                (
                    format!("{attention}.q_lin"),
                    layer
                        .q_proj
                        .as_ref()
                        .context("XLM-family layer is missing q_lin")?,
                ),
                (
                    format!("{attention}.k_lin"),
                    layer
                        .k_proj
                        .as_ref()
                        .context("XLM-family layer is missing k_lin")?,
                ),
                (
                    format!("{attention}.v_lin"),
                    layer
                        .v_proj
                        .as_ref()
                        .context("XLM-family layer is missing v_lin")?,
                ),
                (format!("{attention}.out_lin"), &layer.c_proj),
            ] {
                values.insert(
                    format!("{name}.weight"),
                    (vec![d, d], linear.weight.read()?),
                );
                values.insert(format!("{name}.bias"), (vec![d], linear.bias.read()?));
            }
            values.insert(
                format!("transformer.layer_norm1.{index}.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("transformer.layer_norm1.{index}.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            values.insert(
                format!("{ffn}.lin1.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{ffn}.lin1.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{ffn}.lin2.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{ffn}.lin2.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
            values.insert(
                format!("transformer.layer_norm2.{index}.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("transformer.layer_norm2.{index}.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "pred_layer.proj.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
            values.insert(
                "pred_layer.proj.bias".to_owned(),
                (vec![self.config.vocab_size], lm_head.bias.read()?),
            );
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    "pred_layer.proj.weight".to_owned(),
                    (vec![self.config.vocab_size, d], token_embedding),
                );
            }
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                values.insert(
                    "pred_layer.proj.bias".to_owned(),
                    (vec![self.config.vocab_size], lm_head_bias.read()?),
                );
            }
        }
        Ok(values)
    }

    fn gpt2_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if !matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::Gpt2 | VulkanTransformerArchitecture::GptSw3
        ) {
            bail!("GPT-2 parameter export requires a GPT-2 graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.wte.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "transformer.wpe.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings, d],
                self.position_embedding
                    .as_ref()
                    .context("GPT-2 graph is missing its learned position embedding")?
                    .read()?,
            ),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.h.{index}");
            values.insert(
                format!("{p}.ln_1.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(format!("{p}.ln_1.bias"), (vec![d], layer.ln1.bias.read()?));
            values.insert(
                format!("{p}.attn.c_attn.weight"),
                (
                    vec![d, 3 * d],
                    transpose(
                        &layer
                            .c_attn
                            .as_ref()
                            .context("GPT-2 layer is missing c_attn")?
                            .weight
                            .read()?,
                        3 * d,
                        d,
                    ),
                ),
            );
            values.insert(
                format!("{p}.attn.c_attn.bias"),
                (
                    vec![3 * d],
                    layer
                        .c_attn
                        .as_ref()
                        .context("GPT-2 layer is missing c_attn")?
                        .bias
                        .read()?,
                ),
            );
            values.insert(
                format!("{p}.attn.c_proj.weight"),
                (vec![d, d], transpose(&layer.c_proj.weight.read()?, d, d)),
            );
            values.insert(
                format!("{p}.attn.c_proj.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            if let Some(cross_attention) = layer.cross_attention.as_ref() {
                if !cross_attention.q_proj.has_bias
                    || !cross_attention.k_proj.has_bias
                    || !cross_attention.v_proj.has_bias
                    || !cross_attention.out_proj.has_bias
                    || !cross_attention.norm.has_bias
                {
                    bail!("GPT-2 cross-attention layer {index} is missing a required bias");
                }

                values.insert(
                    format!("{p}.ln_cross_attn.weight"),
                    (vec![d], cross_attention.norm.weight.read()?),
                );
                values.insert(
                    format!("{p}.ln_cross_attn.bias"),
                    (vec![d], cross_attention.norm.bias.read()?),
                );
                values.insert(
                    format!("{p}.crossattention.q_attn.weight"),
                    (
                        vec![d, d],
                        transpose(&cross_attention.q_proj.weight.read()?, d, d),
                    ),
                );
                values.insert(
                    format!("{p}.crossattention.q_attn.bias"),
                    (vec![d], cross_attention.q_proj.bias.read()?),
                );

                let mut kv_weight = cross_attention.k_proj.weight.read()?;
                kv_weight.extend(cross_attention.v_proj.weight.read()?);
                values.insert(
                    format!("{p}.crossattention.c_attn.weight"),
                    (vec![d, 2 * d], transpose(&kv_weight, 2 * d, d)),
                );
                let mut kv_bias = cross_attention.k_proj.bias.read()?;
                kv_bias.extend(cross_attention.v_proj.bias.read()?);
                values.insert(
                    format!("{p}.crossattention.c_attn.bias"),
                    (vec![2 * d], kv_bias),
                );
                values.insert(
                    format!("{p}.crossattention.c_proj.weight"),
                    (
                        vec![d, d],
                        transpose(&cross_attention.out_proj.weight.read()?, d, d),
                    ),
                );
                values.insert(
                    format!("{p}.crossattention.c_proj.bias"),
                    (vec![d], cross_attention.out_proj.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.ln_2.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(format!("{p}.ln_2.bias"), (vec![d], layer.ln2.bias.read()?));
            values.insert(
                format!("{p}.mlp.c_fc.weight"),
                (vec![d, i], transpose(&layer.c_fc.weight.read()?, i, d)),
            );
            values.insert(
                format!("{p}.mlp.c_fc.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.c_proj.weight"),
                (
                    vec![i, d],
                    transpose(&layer.c_mlp_proj.weight.read()?, d, i),
                ),
            );
            values.insert(
                format!("{p}.mlp.c_proj.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        values.insert(
            "transformer.ln_f.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "transformer.ln_f.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn gpt_bigcode_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::GptBigCode {
            bail!("GPT-BigCode parameter export requires a GPT-BigCode graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let q = self.config.query_hidden_size();
        let kv = self.config.key_value_hidden_size();
        let fused_qkv = q + 2 * kv;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.wte.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "transformer.wpe.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings, d],
                self.position_embedding
                    .as_ref()
                    .context("GPT-BigCode graph is missing its learned position embedding")?
                    .read()?,
            ),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.h.{index}");
            let c_attn = layer
                .c_attn
                .as_ref()
                .context("GPT-BigCode layer is missing c_attn")?;
            values.insert(
                format!("{p}.ln_1.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(format!("{p}.ln_1.bias"), (vec![d], layer.ln1.bias.read()?));
            let c_attn_weight = c_attn.weight.read()?;
            let c_attn_bias = c_attn.bias.read()?;
            let (c_attn_weight, c_attn_bias) =
                if self.config.num_key_value_heads == self.config.num_heads {
                    (
                        contiguous_qkv_to_gpt_neox(&c_attn_weight, d, self.config.num_heads, d)?,
                        contiguous_qkv_to_gpt_neox(&c_attn_bias, d, self.config.num_heads, 1)?,
                    )
                } else {
                    (c_attn_weight, c_attn_bias)
                };
            values.insert(
                format!("{p}.attn.c_attn.weight"),
                (vec![fused_qkv, d], c_attn_weight),
            );
            values.insert(
                format!("{p}.attn.c_attn.bias"),
                (vec![fused_qkv], c_attn_bias),
            );
            values.insert(
                format!("{p}.attn.c_proj.weight"),
                (vec![d, q], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.attn.c_proj.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.ln_2.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(format!("{p}.ln_2.bias"), (vec![d], layer.ln2.bias.read()?));
            values.insert(
                format!("{p}.mlp.c_fc.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.c_fc.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.c_proj.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.c_proj.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        values.insert(
            "transformer.ln_f.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "transformer.ln_f.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn falcon_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Falcon {
            bail!("Falcon parameter export requires a Falcon graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let q = self.config.query_hidden_size();
        let kv = self.config.key_value_hidden_size();
        let fused_qkv = q + 2 * kv;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.word_embeddings.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.h.{index}");
            let c_attn = layer
                .c_attn
                .as_ref()
                .context("Falcon layer is missing query_key_value")?;
            values.insert(
                format!("{p}.self_attention.query_key_value.weight"),
                (
                    vec![fused_qkv, d],
                    contiguous_qkv_to_falcon(
                        &c_attn.weight.read()?,
                        d,
                        self.config.num_heads,
                        self.config.num_key_value_heads,
                        d,
                    )?,
                ),
            );
            if c_attn.has_bias {
                values.insert(
                    format!("{p}.self_attention.query_key_value.bias"),
                    (
                        vec![fused_qkv],
                        contiguous_qkv_to_falcon(
                            &c_attn.bias.read()?,
                            d,
                            self.config.num_heads,
                            self.config.num_key_value_heads,
                            1,
                        )?,
                    ),
                );
            }
            values.insert(
                format!("{p}.self_attention.dense.weight"),
                (vec![d, q], layer.c_proj.weight.read()?),
            );
            if layer.c_proj.has_bias {
                values.insert(
                    format!("{p}.self_attention.dense.bias"),
                    (vec![d], layer.c_proj.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.mlp.dense_h_to_4h.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            if layer.c_fc.has_bias {
                values.insert(
                    format!("{p}.mlp.dense_h_to_4h.bias"),
                    (vec![i], layer.c_fc.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.mlp.dense_4h_to_h.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            if layer.c_mlp_proj.has_bias {
                values.insert(
                    format!("{p}.mlp.dense_4h_to_h.bias"),
                    (vec![d], layer.c_mlp_proj.bias.read()?),
                );
            }
            if self.config.shared_pre_norm {
                values.insert(
                    format!("{p}.input_layernorm.weight"),
                    (vec![d], layer.ln1.weight.read()?),
                );
                values.insert(
                    format!("{p}.input_layernorm.bias"),
                    (vec![d], layer.ln1.bias.read()?),
                );
            } else if self.config.parallel_residual {
                values.insert(
                    format!("{p}.ln_attn.weight"),
                    (vec![d], layer.ln1.weight.read()?),
                );
                values.insert(
                    format!("{p}.ln_attn.bias"),
                    (vec![d], layer.ln1.bias.read()?),
                );
                values.insert(
                    format!("{p}.ln_mlp.weight"),
                    (vec![d], layer.ln2.weight.read()?),
                );
                values.insert(
                    format!("{p}.ln_mlp.bias"),
                    (vec![d], layer.ln2.bias.read()?),
                );
            } else {
                values.insert(
                    format!("{p}.input_layernorm.weight"),
                    (vec![d], layer.ln1.weight.read()?),
                );
                values.insert(
                    format!("{p}.input_layernorm.bias"),
                    (vec![d], layer.ln1.bias.read()?),
                );
                values.insert(
                    format!("{p}.post_attention_layernorm.weight"),
                    (vec![d], layer.ln2.weight.read()?),
                );
                values.insert(
                    format!("{p}.post_attention_layernorm.bias"),
                    (vec![d], layer.ln2.bias.read()?),
                );
            }
        }
        values.insert(
            "transformer.ln_f.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "transformer.ln_f.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn bloom_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Bloom {
            bail!("BLOOM parameter export requires a BLOOM graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.word_embeddings.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        let embedding_norm = self
            .embedding_norm
            .as_ref()
            .context("BLOOM graph is missing word_embeddings_layernorm")?;
        values.insert(
            "transformer.word_embeddings_layernorm.weight".to_owned(),
            (vec![d], embedding_norm.weight.read()?),
        );
        values.insert(
            "transformer.word_embeddings_layernorm.bias".to_owned(),
            (vec![d], embedding_norm.bias.read()?),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.h.{index}");
            let c_attn = layer
                .c_attn
                .as_ref()
                .context("BLOOM layer is missing query_key_value")?;
            values.insert(
                format!("{p}.input_layernorm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.input_layernorm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            values.insert(
                format!("{p}.self_attention.query_key_value.weight"),
                (
                    vec![3 * d, d],
                    contiguous_qkv_to_gpt_neox(
                        &c_attn.weight.read()?,
                        d,
                        self.config.num_heads,
                        d,
                    )?,
                ),
            );
            values.insert(
                format!("{p}.self_attention.query_key_value.bias"),
                (
                    vec![3 * d],
                    contiguous_qkv_to_gpt_neox(&c_attn.bias.read()?, d, self.config.num_heads, 1)?,
                ),
            );
            values.insert(
                format!("{p}.self_attention.dense.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.self_attention.dense.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_h_to_4h.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_h_to_4h.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_4h_to_h.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_4h_to_h.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        values.insert(
            "transformer.ln_f.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "transformer.ln_f.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn mpt_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Mpt {
            bail!("MPT parameter export requires an MPT graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.wte.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.blocks.{index}");
            let c_attn = layer.c_attn.as_ref().context("MPT layer is missing Wqkv")?;
            values.insert(
                format!("{p}.norm_1.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.attn.Wqkv.weight"),
                (vec![3 * d, d], c_attn.weight.read()?),
            );
            values.insert(
                format!("{p}.attn.out_proj.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.norm_2.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.ffn.up_proj.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.ffn.down_proj.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
        }
        values.insert(
            "transformer.norm_f.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn dbrx_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Dbrx {
            bail!("DBRX parameter export requires a DBRX graph");
        }
        let moe_config = self
            .config
            .moe
            .as_ref()
            .context("DBRX graph is missing MoE configuration")?;
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let q = self.config.query_hidden_size();
        let kv = self.config.key_value_hidden_size();
        let fused_qkv = q + 2 * kv;
        let packed_rows = moe_config
            .num_experts
            .checked_mul(i)
            .context("DBRX packed expert row count overflow")?;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.wte.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding),
        );

        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.blocks.{index}");
            let c_attn = layer
                .c_attn
                .as_ref()
                .context("DBRX layer is missing Wqkv")?;
            let expert0_gate = layer
                .c_gate
                .as_ref()
                .context("DBRX layer is missing expert 0 w1 projection")?;
            let moe = layer
                .moe
                .as_ref()
                .context("DBRX layer is missing native MoE parameters")?;
            if moe.num_experts != moe_config.num_experts || moe.experts.len() + 1 != moe.num_experts
            {
                bail!(
                    "DBRX layer {index} expert geometry is inconsistent: graph={}, configured={}, stored={}",
                    moe.num_experts,
                    moe_config.num_experts,
                    moe.experts.len() + 1
                );
            }
            if moe.router.has_bias {
                bail!("DBRX layer {index} router must be bias-free");
            }

            values.insert(
                format!("{p}.norm_attn_norm.norm_1.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.norm_attn_norm.attn.Wqkv.weight"),
                (vec![fused_qkv, d], c_attn.weight.read()?),
            );
            values.insert(
                format!("{p}.norm_attn_norm.attn.out_proj.weight"),
                (vec![d, q], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.norm_attn_norm.norm_2.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.ffn.router.layer.weight"),
                (vec![moe.num_experts, d], moe.router.weight.read()?),
            );

            let mut w1 = Vec::with_capacity(packed_rows * d);
            let mut v1 = Vec::with_capacity(packed_rows * d);
            let mut w2 = Vec::with_capacity(packed_rows * d);
            w1.extend(expert0_gate.weight.read()?);
            v1.extend(layer.c_fc.weight.read()?);
            w2.extend(transpose(&layer.c_mlp_proj.weight.read()?, d, i));
            for expert in &moe.experts {
                let gate = expert
                    .gate
                    .as_ref()
                    .context("DBRX routed expert is missing its w1 projection")?;
                if gate.has_bias || expert.up.has_bias || expert.down.has_bias {
                    bail!("DBRX layer {index} experts must be bias-free");
                }
                w1.extend(gate.weight.read()?);
                v1.extend(expert.up.weight.read()?);
                w2.extend(transpose(&expert.down.weight.read()?, d, i));
            }
            values.insert(
                format!("{p}.ffn.experts.mlp.w1"),
                (vec![packed_rows, d], w1),
            );
            values.insert(
                format!("{p}.ffn.experts.mlp.v1"),
                (vec![packed_rows, d], v1),
            );
            values.insert(
                format!("{p}.ffn.experts.mlp.w2"),
                (vec![packed_rows, d], w2),
            );
        }

        values.insert(
            "transformer.norm_f.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        let lm_head = self
            .lm_head
            .as_ref()
            .context("DBRX graph is missing its untied lm_head")?;
        values.insert(
            "lm_head.weight".to_owned(),
            (vec![self.config.vocab_size, d], lm_head.weight.read()?),
        );
        Ok(values)
    }

    fn gpt_neo_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::GptNeo {
            bail!("GPT-Neo parameter export requires a GPT-Neo graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.wte.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "transformer.wpe.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings, d],
                self.position_embedding
                    .as_ref()
                    .context("GPT-Neo graph is missing its learned position embedding")?
                    .read()?,
            ),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.h.{index}");
            values.insert(
                format!("{p}.ln_1.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(format!("{p}.ln_1.bias"), (vec![d], layer.ln1.bias.read()?));
            let attn = format!("{p}.attn.attention");
            values.insert(
                format!("{attn}.q_proj.weight"),
                (
                    vec![d, d],
                    layer
                        .q_proj
                        .as_ref()
                        .context("GPT-Neo layer is missing q_proj")?
                        .weight
                        .read()?,
                ),
            );
            values.insert(
                format!("{attn}.k_proj.weight"),
                (
                    vec![d, d],
                    layer
                        .k_proj
                        .as_ref()
                        .context("GPT-Neo layer is missing k_proj")?
                        .weight
                        .read()?,
                ),
            );
            values.insert(
                format!("{attn}.v_proj.weight"),
                (
                    vec![d, d],
                    layer
                        .v_proj
                        .as_ref()
                        .context("GPT-Neo layer is missing v_proj")?
                        .weight
                        .read()?,
                ),
            );
            values.insert(
                format!("{attn}.out_proj.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{attn}.out_proj.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.ln_2.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(format!("{p}.ln_2.bias"), (vec![d], layer.ln2.bias.read()?));
            values.insert(
                format!("{p}.mlp.c_fc.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.c_fc.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.c_proj.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.c_proj.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        values.insert(
            "transformer.ln_f.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "transformer.ln_f.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn gpt_neox_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        let (root, japanese) = match self.config.architecture {
            VulkanTransformerArchitecture::GptNeoX => ("gpt_neox", false),
            VulkanTransformerArchitecture::GptNeoXJapanese => ("gpt_neox_japanese", true),
            _ => bail!("GPT-NeoX parameter export requires a GPT-NeoX family graph"),
        };
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            format!("{root}.embed_in.weight"),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("{root}.layers.{index}");
            values.insert(
                format!("{p}.input_layernorm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.input_layernorm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            values.insert(
                format!("{p}.attention.query_key_value.weight"),
                (
                    vec![3 * d, d],
                    contiguous_qkv_to_gpt_neox(
                        &layer
                            .c_attn
                            .as_ref()
                            .context("GPT-NeoX layer is missing c_attn")?
                            .weight
                            .read()?,
                        d,
                        self.config.num_heads,
                        d,
                    )?,
                ),
            );
            if !japanese {
                values.insert(
                    format!("{p}.attention.query_key_value.bias"),
                    (
                        vec![3 * d],
                        contiguous_qkv_to_gpt_neox(
                            &layer
                                .c_attn
                                .as_ref()
                                .context("GPT-NeoX layer is missing c_attn")?
                                .bias
                                .read()?,
                            d,
                            self.config.num_heads,
                            1,
                        )?,
                    ),
                );
            }
            values.insert(
                format!("{p}.attention.dense.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            if japanese {
                if layer.c_proj.has_bias {
                    values.insert(
                        format!("{p}.attention.dense_bias"),
                        (vec![d], layer.c_proj.bias.read()?),
                    );
                }
            } else {
                values.insert(
                    format!("{p}.attention.dense.bias"),
                    (vec![d], layer.c_proj.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.post_attention_layernorm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_h_to_4h.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            if !japanese {
                values.insert(
                    format!("{p}.mlp.dense_h_to_4h.bias"),
                    (vec![i], layer.c_fc.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.mlp.dense_4h_to_h.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            if !japanese {
                values.insert(
                    format!("{p}.mlp.dense_4h_to_h.bias"),
                    (vec![d], layer.c_mlp_proj.bias.read()?),
                );
            }
        }
        values.insert(
            format!("{root}.final_layer_norm.weight"),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            format!("{root}.final_layer_norm.bias"),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "embed_out.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "embed_out.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn persimmon_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Persimmon {
            bail!("Persimmon parameter export requires a Persimmon graph");
        }
        let d = self.config.hidden_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "model.embed_tokens.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let i = self.config.layer_intermediate_size(index);
            let p = format!("model.layers.{index}");
            values.insert(
                format!("{p}.input_layernorm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.input_layernorm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            let qkv = layer
                .c_attn
                .as_ref()
                .context("Persimmon layer is missing query_key_value")?;
            values.insert(
                format!("{p}.self_attn.query_key_value.weight"),
                (
                    vec![3 * d, d],
                    contiguous_qkv_to_gpt_neox(&qkv.weight.read()?, d, self.config.num_heads, d)?,
                ),
            );
            values.insert(
                format!("{p}.self_attn.query_key_value.bias"),
                (
                    vec![3 * d],
                    contiguous_qkv_to_gpt_neox(&qkv.bias.read()?, d, self.config.num_heads, 1)?,
                ),
            );
            if let (Some(q_norm), Some(k_norm)) = (layer.q_norm.as_ref(), layer.k_norm.as_ref()) {
                for (name, norm) in [("q_layernorm", q_norm), ("k_layernorm", k_norm)] {
                    values.insert(
                        format!("{p}.self_attn.{name}.weight"),
                        (vec![self.config.head_dim], norm.weight.read()?),
                    );
                    if norm.has_bias {
                        values.insert(
                            format!("{p}.self_attn.{name}.bias"),
                            (vec![self.config.head_dim], norm.bias.read()?),
                        );
                    }
                }
            }
            values.insert(
                format!("{p}.self_attn.dense.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.self_attn.dense.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.post_attention_layernorm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_h_to_4h.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_h_to_4h.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_4h_to_h.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.mlp.dense_4h_to_h.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        values.insert(
            "model.final_layernorm.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "model.final_layernorm.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn t5_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if !self.config.architecture.is_t5_family() {
            bail!("T5-family parameter export requires a T5/MT5 graph");
        }
        let d = self.config.hidden_size;
        let a = self.config.query_hidden_size();
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "shared.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "decoder.embed_tokens.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let self_prefix = format!("decoder.block.{index}.layer.0");
            let self_attention = format!("{self_prefix}.SelfAttention");
            values.insert(
                format!("{self_prefix}.layer_norm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            for (name, projection) in [
                (
                    "q",
                    layer
                        .q_proj
                        .as_ref()
                        .context("T5 layer is missing self-attention q")?,
                ),
                (
                    "k",
                    layer
                        .k_proj
                        .as_ref()
                        .context("T5 layer is missing self-attention k")?,
                ),
                (
                    "v",
                    layer
                        .v_proj
                        .as_ref()
                        .context("T5 layer is missing self-attention v")?,
                ),
            ] {
                values.insert(
                    format!("{self_attention}.{name}.weight"),
                    (vec![a, d], projection.weight.read()?),
                );
            }
            values.insert(
                format!("{self_attention}.o.weight"),
                (vec![d, a], layer.c_proj.weight.read()?),
            );
            if index == 0 || self.config.architecture == VulkanTransformerArchitecture::UMT5 {
                let relative_attention_bias = self
                    .relative_attention_bias_for_layer(index)
                    .context("T5-family graph is missing relative attention bias")?;
                values.insert(
                    format!("{self_attention}.relative_attention_bias.weight"),
                    (
                        vec![self.relative_attention_num_buckets, self.config.num_heads],
                        relative_attention_bias.read()?,
                    ),
                );
            }

            let cross = layer
                .cross_attention
                .as_ref()
                .context("T5 decoder layer is missing cross-attention")?;
            let cross_prefix = format!("decoder.block.{index}.layer.1");
            let cross_attention = format!("{cross_prefix}.EncDecAttention");
            values.insert(
                format!("{cross_prefix}.layer_norm.weight"),
                (vec![d], cross.norm.weight.read()?),
            );
            values.insert(
                format!("{cross_attention}.q.weight"),
                (vec![a, d], cross.q_proj.weight.read()?),
            );
            values.insert(
                format!("{cross_attention}.k.weight"),
                (
                    vec![a, cross.encoder_hidden_size],
                    cross.k_proj.weight.read()?,
                ),
            );
            values.insert(
                format!("{cross_attention}.v.weight"),
                (
                    vec![a, cross.encoder_hidden_size],
                    cross.v_proj.weight.read()?,
                ),
            );
            values.insert(
                format!("{cross_attention}.o.weight"),
                (vec![d, a], cross.out_proj.weight.read()?),
            );

            let ff_prefix = format!("decoder.block.{index}.layer.2");
            values.insert(
                format!("{ff_prefix}.layer_norm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            if self.config.architecture == VulkanTransformerArchitecture::SwitchTransformers {
                let mlp = format!("{ff_prefix}.mlp");
                if self.config.layer_uses_moe(index) {
                    let moe = layer
                        .moe
                        .as_ref()
                        .context("Switch Transformers sparse layer is missing MoE parameters")?;
                    values.insert(
                        format!("{mlp}.router.classifier.weight"),
                        (vec![moe.num_experts, d], moe.router.weight.read()?),
                    );
                    if moe.router.has_bias {
                        values.insert(
                            format!("{mlp}.router.classifier.bias"),
                            (vec![moe.num_experts], moe.router.bias.read()?),
                        );
                    }
                    values.insert(
                        format!("{mlp}.experts.expert_0.wi.weight"),
                        (vec![i, d], layer.c_fc.weight.read()?),
                    );
                    values.insert(
                        format!("{mlp}.experts.expert_0.wo.weight"),
                        (vec![d, i], layer.c_mlp_proj.weight.read()?),
                    );
                    for (expert_offset, expert) in moe.experts.iter().enumerate() {
                        let expert_index = expert_offset + 1;
                        values.insert(
                            format!("{mlp}.experts.expert_{expert_index}.wi.weight"),
                            (vec![i, d], expert.up.weight.read()?),
                        );
                        values.insert(
                            format!("{mlp}.experts.expert_{expert_index}.wo.weight"),
                            (vec![d, i], expert.down.weight.read()?),
                        );
                    }
                } else {
                    values.insert(
                        format!("{mlp}.wi.weight"),
                        (vec![i, d], layer.c_fc.weight.read()?),
                    );
                    values.insert(
                        format!("{mlp}.wo.weight"),
                        (vec![d, i], layer.c_mlp_proj.weight.read()?),
                    );
                }
            } else {
                let dense = format!("{ff_prefix}.DenseReluDense");
                if let Some(gate) = layer.c_gate.as_ref() {
                    values.insert(
                        format!("{dense}.wi_0.weight"),
                        (vec![i, d], gate.weight.read()?),
                    );
                    values.insert(
                        format!("{dense}.wi_1.weight"),
                        (vec![i, d], layer.c_fc.weight.read()?),
                    );
                } else {
                    values.insert(
                        format!("{dense}.wi.weight"),
                        (vec![i, d], layer.c_fc.weight.read()?),
                    );
                }
                values.insert(
                    format!("{dense}.wo.weight"),
                    (vec![d, i], layer.c_mlp_proj.weight.read()?),
                );
            }
        }
        values.insert(
            "decoder.final_layer_norm.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn bart_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if !matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::TrOCR
                | VulkanTransformerArchitecture::Bart
                | VulkanTransformerArchitecture::MBart
                | VulkanTransformerArchitecture::Marian
                | VulkanTransformerArchitecture::Fsmt
                | VulkanTransformerArchitecture::PLBart
                | VulkanTransformerArchitecture::Mvp
                | VulkanTransformerArchitecture::Blenderbot
                | VulkanTransformerArchitecture::BlenderbotSmall
                | VulkanTransformerArchitecture::Pegasus
                | VulkanTransformerArchitecture::M2M100
                | VulkanTransformerArchitecture::BigBirdPegasus
                | VulkanTransformerArchitecture::PegasusX
        ) {
            bail!(
                "BART-layout parameter export requires a supported BART-style seq2seq decoder graph"
            );
        }
        let family_name = match self.config.architecture {
            VulkanTransformerArchitecture::Bart => "BART",
            VulkanTransformerArchitecture::MBart => "MBART",
            VulkanTransformerArchitecture::Marian => "Marian",
            VulkanTransformerArchitecture::Fsmt => "FSMT",
            VulkanTransformerArchitecture::PLBart => "PLBART",
            VulkanTransformerArchitecture::Mvp => "MVP",
            VulkanTransformerArchitecture::Blenderbot => "Blenderbot",
            VulkanTransformerArchitecture::BlenderbotSmall => "BlenderbotSmall",
            VulkanTransformerArchitecture::Pegasus => "PEGASUS",
            VulkanTransformerArchitecture::M2M100 => "M2M100",
            VulkanTransformerArchitecture::BigBirdPegasus => "BigBirdPegasus",
            VulkanTransformerArchitecture::PegasusX => "PEGASUS-X",
            _ => unreachable!("validated BART-layout export architecture"),
        };
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "model.decoder.embed_tokens.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        if !matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::Marian
                | VulkanTransformerArchitecture::M2M100
                | VulkanTransformerArchitecture::PegasusX
        ) {
            let position_rows = if self.config.architecture == VulkanTransformerArchitecture::Fsmt {
                let position_values = self
                    .position_embedding
                    .as_ref()
                    .context("FSMT graph is missing sinusoidal position embeddings")?
                    .read()?;
                if position_values.len() % d != 0 {
                    bail!("FSMT position embedding storage is not divisible by hidden size");
                }
                position_values.len() / d
            } else if matches!(
                self.config.architecture,
                VulkanTransformerArchitecture::Blenderbot
                    | VulkanTransformerArchitecture::BlenderbotSmall
                    | VulkanTransformerArchitecture::Pegasus
                    | VulkanTransformerArchitecture::BigBirdPegasus
            ) {
                self.config.max_position_embeddings
            } else {
                self.config.max_position_embeddings + 2
            };
            values.insert(
                "model.decoder.embed_positions.weight".to_owned(),
                (
                    vec![position_rows, d],
                    self.position_embedding
                        .as_ref()
                        .with_context(|| {
                            format!("{family_name} graph is missing position embeddings")
                        })?
                        .read()?,
                ),
            );
            if matches!(
                self.config.architecture,
                VulkanTransformerArchitecture::Bart
                    | VulkanTransformerArchitecture::MBart
                    | VulkanTransformerArchitecture::PLBart
                    | VulkanTransformerArchitecture::Mvp
                    | VulkanTransformerArchitecture::BlenderbotSmall
            ) {
                let embedding_norm = self.embedding_norm.as_ref().with_context(|| {
                    format!("{family_name} graph is missing embedding LayerNorm")
                })?;
                values.insert(
                    "model.decoder.layernorm_embedding.weight".to_owned(),
                    (vec![d], embedding_norm.weight.read()?),
                );
                values.insert(
                    "model.decoder.layernorm_embedding.bias".to_owned(),
                    (vec![d], embedding_norm.bias.read()?),
                );
            }
        }
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("model.decoder.layers.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .with_context(|| format!("{family_name} layer is missing q_proj"))?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .with_context(|| format!("{family_name} layer is missing k_proj"))?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .with_context(|| format!("{family_name} layer is missing v_proj"))?;
            for (name, projection) in [("q_proj", q_proj), ("k_proj", k_proj), ("v_proj", v_proj)] {
                values.insert(
                    format!("{p}.self_attn.{name}.weight"),
                    (vec![d, d], projection.weight.read()?),
                );
                if projection.has_bias {
                    values.insert(
                        format!("{p}.self_attn.{name}.bias"),
                        (vec![d], projection.bias.read()?),
                    );
                }
            }
            values.insert(
                format!("{p}.self_attn.out_proj.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            if layer.c_proj.has_bias {
                values.insert(
                    format!("{p}.self_attn.out_proj.bias"),
                    (vec![d], layer.c_proj.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.self_attn_layer_norm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.self_attn_layer_norm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            if let Some(cross_attention) = layer.cross_attention.as_ref() {
                for (name, projection) in [
                    ("q_proj", &cross_attention.q_proj),
                    ("k_proj", &cross_attention.k_proj),
                    ("v_proj", &cross_attention.v_proj),
                    ("out_proj", &cross_attention.out_proj),
                ] {
                    values.insert(
                        format!("{p}.encoder_attn.{name}.weight"),
                        (vec![d, d], projection.weight.read()?),
                    );
                    if projection.has_bias {
                        values.insert(
                            format!("{p}.encoder_attn.{name}.bias"),
                            (vec![d], projection.bias.read()?),
                        );
                    }
                }
                values.insert(
                    format!("{p}.encoder_attn_layer_norm.weight"),
                    (vec![d], cross_attention.norm.weight.read()?),
                );
                values.insert(
                    format!("{p}.encoder_attn_layer_norm.bias"),
                    (vec![d], cross_attention.norm.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.fc1.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(format!("{p}.fc1.bias"), (vec![i], layer.c_fc.bias.read()?));
            values.insert(
                format!("{p}.fc2.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.fc2.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.final_layer_norm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.final_layer_norm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
        }
        if matches!(
            self.config.architecture,
            VulkanTransformerArchitecture::MBart
                | VulkanTransformerArchitecture::Blenderbot
                | VulkanTransformerArchitecture::Pegasus
                | VulkanTransformerArchitecture::M2M100
                | VulkanTransformerArchitecture::PegasusX
        ) {
            values.insert(
                "model.decoder.layer_norm.weight".to_owned(),
                (vec![d], self.final_norm.weight.read()?),
            );
            values.insert(
                "model.decoder.layer_norm.bias".to_owned(),
                (vec![d], self.final_norm.bias.read()?),
            );
        } else if self.config.architecture == VulkanTransformerArchitecture::BigBirdPegasus {
            values.insert(
                "model.decoder.layernorm_embedding.weight".to_owned(),
                (vec![d], self.final_norm.weight.read()?),
            );
            values.insert(
                "model.decoder.layernorm_embedding.bias".to_owned(),
                (vec![d], self.final_norm.bias.read()?),
            );
        }
        if self.config.architecture == VulkanTransformerArchitecture::Fsmt {
            if let Some(lm_head) = self.lm_head.as_ref() {
                values.insert(
                    "model.decoder.output_projection.weight".to_owned(),
                    (vec![self.config.vocab_size, d], lm_head.weight.read()?),
                );
            } else if self.source_has_lm_head_alias {
                values.insert(
                    "model.decoder.output_projection.weight".to_owned(),
                    (vec![self.config.vocab_size, d], token_embedding),
                );
            }
        } else if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        if let Some(bias) = self.lm_head_bias.as_ref() {
            values.insert(
                "final_logits_bias".to_owned(),
                (vec![1, self.config.vocab_size], bias.read()?),
            );
        }
        Ok(values)
    }

    fn opt_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Opt {
            bail!("OPT parameter export requires an OPT graph");
        }
        let d = self.config.hidden_size;
        let e = self.config.effective_embedding_size();
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "model.decoder.embed_tokens.weight".to_owned(),
            (vec![self.config.vocab_size, e], token_embedding.clone()),
        );
        values.insert(
            "model.decoder.embed_positions.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings + 2, d],
                self.position_embedding
                    .as_ref()
                    .context("OPT graph is missing learned position embeddings")?
                    .read()?,
            ),
        );
        if e != d {
            let embedding_project = self
                .embedding_project
                .as_ref()
                .context("projected OPT graph is missing project_in")?;
            let output_project = self
                .output_project
                .as_ref()
                .context("projected OPT graph is missing project_out")?;
            values.insert(
                "model.decoder.project_in.weight".to_owned(),
                (vec![d, e], embedding_project.weight.read()?),
            );
            values.insert(
                "model.decoder.project_out.weight".to_owned(),
                (vec![e, d], output_project.weight.read()?),
            );
        }
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("model.decoder.layers.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("OPT layer is missing q_proj")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("OPT layer is missing k_proj")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("OPT layer is missing v_proj")?;
            if self.config.layer_norm_elementwise_affine {
                values.insert(
                    format!("{p}.self_attn_layer_norm.weight"),
                    (vec![d], layer.ln1.weight.read()?),
                );
                values.insert(
                    format!("{p}.self_attn_layer_norm.bias"),
                    (vec![d], layer.ln1.bias.read()?),
                );
            }
            for (name, projection) in [("q_proj", q_proj), ("k_proj", k_proj), ("v_proj", v_proj)] {
                values.insert(
                    format!("{p}.self_attn.{name}.weight"),
                    (vec![d, d], projection.weight.read()?),
                );
                if projection.has_bias {
                    values.insert(
                        format!("{p}.self_attn.{name}.bias"),
                        (vec![d], projection.bias.read()?),
                    );
                }
            }
            values.insert(
                format!("{p}.self_attn.out_proj.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            if layer.c_proj.has_bias {
                values.insert(
                    format!("{p}.self_attn.out_proj.bias"),
                    (vec![d], layer.c_proj.bias.read()?),
                );
            }
            if self.config.layer_norm_elementwise_affine {
                values.insert(
                    format!("{p}.final_layer_norm.weight"),
                    (vec![d], layer.ln2.weight.read()?),
                );
                values.insert(
                    format!("{p}.final_layer_norm.bias"),
                    (vec![d], layer.ln2.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.fc1.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            if layer.c_fc.has_bias {
                values.insert(format!("{p}.fc1.bias"), (vec![i], layer.c_fc.bias.read()?));
            }
            values.insert(
                format!("{p}.fc2.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            if layer.c_mlp_proj.has_bias {
                values.insert(
                    format!("{p}.fc2.bias"),
                    (vec![d], layer.c_mlp_proj.bias.read()?),
                );
            }
        }
        if self.config.layer_norm_elementwise_affine && self.config.uses_final_norm() {
            values.insert(
                "model.decoder.final_layer_norm.weight".to_owned(),
                (vec![d], self.final_norm.weight.read()?),
            );
            values.insert(
                "model.decoder.final_layer_norm.bias".to_owned(),
                (vec![d], self.final_norm.bias.read()?),
            );
        }
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, e], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, e], token_embedding),
            );
        }
        Ok(values)
    }

    fn biogpt_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::BioGpt {
            bail!("BioGPT parameter export requires a BioGPT graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "biogpt.embed_tokens.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        values.insert(
            "biogpt.embed_positions.weight".to_owned(),
            (
                vec![self.config.max_position_embeddings + 2, d],
                self.position_embedding
                    .as_ref()
                    .context("BioGPT graph is missing learned position embeddings")?
                    .read()?,
            ),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("biogpt.layers.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("BioGPT layer is missing q_proj")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("BioGPT layer is missing k_proj")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("BioGPT layer is missing v_proj")?;
            values.insert(
                format!("{p}.self_attn_layer_norm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.self_attn_layer_norm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            for (name, projection) in [("q_proj", q_proj), ("k_proj", k_proj), ("v_proj", v_proj)] {
                values.insert(
                    format!("{p}.self_attn.{name}.weight"),
                    (vec![d, d], projection.weight.read()?),
                );
                values.insert(
                    format!("{p}.self_attn.{name}.bias"),
                    (vec![d], projection.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.self_attn.out_proj.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.self_attn.out_proj.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            if let Some(cross_attention) = layer.cross_attention.as_ref() {
                for (name, projection) in [
                    ("q_proj", &cross_attention.q_proj),
                    ("k_proj", &cross_attention.k_proj),
                    ("v_proj", &cross_attention.v_proj),
                    ("out_proj", &cross_attention.out_proj),
                ] {
                    values.insert(
                        format!("{p}.encoder_attn.{name}.weight"),
                        (vec![d, d], projection.weight.read()?),
                    );
                    values.insert(
                        format!("{p}.encoder_attn.{name}.bias"),
                        (vec![d], projection.bias.read()?),
                    );
                }
                values.insert(
                    format!("{p}.encoder_attn_layer_norm.weight"),
                    (vec![d], cross_attention.norm.weight.read()?),
                );
                values.insert(
                    format!("{p}.encoder_attn_layer_norm.bias"),
                    (vec![d], cross_attention.norm.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.final_layer_norm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.final_layer_norm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
            values.insert(
                format!("{p}.fc1.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(format!("{p}.fc1.bias"), (vec![i], layer.c_fc.bias.read()?));
            values.insert(
                format!("{p}.fc2.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.fc2.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        values.insert(
            "biogpt.layer_norm.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "biogpt.layer_norm.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "output_projection.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "output_projection.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        Ok(values)
    }

    fn xglm_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Xglm {
            bail!("XGLM parameter export requires an XGLM graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "model.embed_tokens.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("model.layers.{index}");
            let q_proj = layer
                .q_proj
                .as_ref()
                .context("XGLM layer is missing q_proj")?;
            let k_proj = layer
                .k_proj
                .as_ref()
                .context("XGLM layer is missing k_proj")?;
            let v_proj = layer
                .v_proj
                .as_ref()
                .context("XGLM layer is missing v_proj")?;
            values.insert(
                format!("{p}.self_attn_layer_norm.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.self_attn_layer_norm.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            for (name, projection) in [("q_proj", q_proj), ("k_proj", k_proj), ("v_proj", v_proj)] {
                values.insert(
                    format!("{p}.self_attn.{name}.weight"),
                    (vec![d, d], projection.weight.read()?),
                );
                values.insert(
                    format!("{p}.self_attn.{name}.bias"),
                    (vec![d], projection.bias.read()?),
                );
            }
            values.insert(
                format!("{p}.self_attn.out_proj.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.self_attn.out_proj.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.final_layer_norm.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.final_layer_norm.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
            values.insert(
                format!("{p}.fc1.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(format!("{p}.fc1.bias"), (vec![i], layer.c_fc.bias.read()?));
            values.insert(
                format!("{p}.fc2.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.fc2.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        values.insert(
            "model.layer_norm.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "model.layer_norm.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
        } else if self.source_has_lm_head_alias {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], token_embedding),
            );
        }
        // XGLMSinusoidalPositionalEmbedding stores `weights` as a
        // non-persistent buffer, so there is deliberately no position tensor
        // in the exported Hugging Face state dict.
        Ok(values)
    }

    fn ctrl_parameter_tensors(&self) -> Result<BTreeMap<String, (Vec<usize>, Vec<f32>)>> {
        if self.config.architecture != VulkanTransformerArchitecture::Ctrl {
            bail!("CTRL parameter export requires a CTRL graph");
        }
        let d = self.config.hidden_size;
        let i = self.config.intermediate_size;
        let mut values = BTreeMap::new();
        let token_embedding = self.shared_embedding.weights()?;
        values.insert(
            "transformer.w.weight".to_owned(),
            (vec![self.config.vocab_size, d], token_embedding.clone()),
        );
        for (index, layer) in self.layers.iter().enumerate() {
            let p = format!("transformer.h.{index}");
            let attention = format!("{p}.multi_head_attention");
            let q_proj = layer.q_proj.as_ref().context("CTRL layer is missing Wq")?;
            let k_proj = layer.k_proj.as_ref().context("CTRL layer is missing Wk")?;
            let v_proj = layer.v_proj.as_ref().context("CTRL layer is missing Wv")?;
            values.insert(
                format!("{p}.layernorm1.weight"),
                (vec![d], layer.ln1.weight.read()?),
            );
            values.insert(
                format!("{p}.layernorm1.bias"),
                (vec![d], layer.ln1.bias.read()?),
            );
            values.insert(
                format!("{p}.layernorm2.weight"),
                (vec![d], layer.ln2.weight.read()?),
            );
            values.insert(
                format!("{p}.layernorm2.bias"),
                (vec![d], layer.ln2.bias.read()?),
            );
            for (name, projection) in [("Wq", q_proj), ("Wk", k_proj), ("Wv", v_proj)] {
                values.insert(
                    format!("{attention}.{name}.weight"),
                    (vec![d, d], projection.weight.read()?),
                );
                values.insert(
                    format!("{attention}.{name}.bias"),
                    (vec![d], projection.bias.read()?),
                );
            }
            values.insert(
                format!("{attention}.dense.weight"),
                (vec![d, d], layer.c_proj.weight.read()?),
            );
            values.insert(
                format!("{attention}.dense.bias"),
                (vec![d], layer.c_proj.bias.read()?),
            );
            values.insert(
                format!("{p}.ffn.0.weight"),
                (vec![i, d], layer.c_fc.weight.read()?),
            );
            values.insert(
                format!("{p}.ffn.0.bias"),
                (vec![i], layer.c_fc.bias.read()?),
            );
            values.insert(
                format!("{p}.ffn.2.weight"),
                (vec![d, i], layer.c_mlp_proj.weight.read()?),
            );
            values.insert(
                format!("{p}.ffn.2.bias"),
                (vec![d], layer.c_mlp_proj.bias.read()?),
            );
        }
        values.insert(
            "transformer.layernorm.weight".to_owned(),
            (vec![d], self.final_norm.weight.read()?),
        );
        values.insert(
            "transformer.layernorm.bias".to_owned(),
            (vec![d], self.final_norm.bias.read()?),
        );
        if let Some(lm_head) = self.lm_head.as_ref() {
            values.insert(
                "lm_head.weight".to_owned(),
                (vec![self.config.vocab_size, d], lm_head.weight.read()?),
            );
            values.insert(
                "lm_head.bias".to_owned(),
                (vec![self.config.vocab_size], lm_head.bias.read()?),
            );
        } else {
            if self.source_has_lm_head_alias {
                values.insert(
                    "lm_head.weight".to_owned(),
                    (vec![self.config.vocab_size, d], token_embedding),
                );
            }
            if let Some(lm_head_bias) = self.lm_head_bias.as_ref() {
                values.insert(
                    "lm_head.bias".to_owned(),
                    (vec![self.config.vocab_size], lm_head_bias.read()?),
                );
            }
        }
        // CTRL's sinusoidal `pos_encoding` is a non-persistent buffer in the
        // Hugging Face implementation, so it is intentionally omitted here.
        Ok(values)
    }

