    fn tiny_qwen4_peft_vulkan_graph(device: VulkanDevice) -> Result<VulkanTransformer> {
        let mut graph = tiny_qwen_hybrid_moe_vulkan_graph(
            device.clone(),
            VulkanTransformerArchitecture::Qwen35Moe,
        )?;
        graph.config = VulkanTransformerConfig::from_hf_value(&tiny_qwen4_exp_config())?;

        let d = graph.config.hidden_size;
        let hc_count = 2usize;
        let hc_lowrank = 4usize;
        let hc_hidden_size = d * hc_count;
        let make_residual = |marker: f32, use_combine: bool| {
            let norm_weight = vec![marker; hc_hidden_size];
            let down = vec![marker + 0.01; hc_lowrank * hc_hidden_size];
            let up = vec![marker + 0.02; hc_hidden_size * hc_lowrank];
            let inject = use_combine.then(|| vec![marker + 0.03; hc_count * hc_hidden_size]);
            VulkanQwen4GatedResidual::new(
                &device,
                graph.rows,
                d,
                hc_count,
                hc_lowrank,
                graph.config.layer_norm_eps,
                &norm_weight,
                &down,
                &up,
                inject.as_deref(),
            )
        };

        let layout = Qwen4PleNgramLayout::new(graph.config.vocab_size, 2, 1, 11, 0, 0x5144)?;
        let ple_embed_dim = 4usize;
        let embedding_head_dim = ple_embed_dim / layout.ngram_heads();
        let embedding_len = layout
            .total_vocab_size
            .checked_mul(embedding_head_dim)
            .context("tiny Qwen4 PLE embedding size overflow")?;
        let ple_host = HostQwen4Ple {
            ple_embed_dim,
            conv_kernel_size: 2,
            eos_token_id: 0,
            embedding_name: "model.layers.0.ple.ple_embedding.ngram_embedding.weight".to_owned(),
            // This PEFT fixture never gathers PLE embedding rows; it only needs
            // the source geometry so the PLE Linear modules can be constructed.
            embedding_source: HostFloatTensorSource {
                path: PathBuf::from("qwen4-peft-fixture-unused.safetensors"),
                shape: vec![layout.total_vocab_size, embedding_head_dim],
                dtype: Dtype::F32,
                data_start: 0,
                byte_len: embedding_len * std::mem::size_of::<f32>(),
            },
            layout,
            key_proj: HostLinear {
                weight: vec![0.81; hc_hidden_size * ple_embed_dim],
                bias: None,
            },
            value_proj: HostLinear {
                weight: vec![0.82; d * ple_embed_dim],
                bias: None,
            },
            norm_key: vec![0.83; hc_hidden_size],
            norm_query: vec![0.84; hc_hidden_size],
            norm_conv: vec![0.85; hc_hidden_size],
            conv_weight: vec![0.86; hc_hidden_size * 2],
        };

        let layer = graph
            .layers
            .first_mut()
            .context("tiny Qwen4 PEFT graph is missing layer 0")?;
        layer.qwen4_ple = Some(VulkanQwen4Ple::from_host(
            &device,
            graph.rows,
            graph.batch_size,
            graph.seq_len,
            d,
            hc_count,
            graph.config.layer_norm_eps,
            ple_host,
        )?);
        layer.qwen4_attn_hyper_connection = Some(make_residual(0.71, true)?);
        layer.qwen4_mlp_hyper_connection = Some(make_residual(0.75, true)?);
        graph.qwen4_final_mixer = Some(make_residual(0.79, false)?);
        Ok(graph)
    }

