    fn tiny_mimo_v2_flash_vulkan_graph(device: VulkanDevice) -> Result<VulkanTransformer> {
        let value = tiny_mimo_v2_flash_config();
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let q = config.query_hidden_size();
        let v_head_dim = VulkanTransformerConfig::mimo_v2_flash_v_head_dim(&value)?;
        let layer_types =
            VulkanTransformerConfig::mimo_v2_flash_layer_types(&value, config.num_layers)?;
        let moe_config = config
            .moe
            .as_ref()
            .context("tiny MiMo-V2-Flash config is missing MoE metadata")?;
        let num_experts = moe_config.num_experts;
        let linear = |input_dim: usize, output_dim: usize, value: f32| HostLinear {
            weight: vec![value; input_dim * output_dim],
            bias: None,
        };
        let rms_norm = |value: f32| HostLayerNorm {
            weight: vec![value; d],
            bias: Vec::new(),
        };

        let layers = (0..config.num_layers)
            .map(|layer_index| -> Result<HostTransformerLayer> {
                let base = 0.01 * (layer_index + 1) as f32;
                let i = config.layer_intermediate_size(layer_index);
                let layer_num_key_value_heads = if layer_types[layer_index] == "sliding_attention" {
                    config
                        .num_key_value_heads
                        .checked_mul(2)
                        .context("tiny MiMo-V2-Flash sliding KV-head count overflow")?
                } else {
                    config.num_key_value_heads
                };
                let key_width = layer_num_key_value_heads * config.head_dim;
                let value_width = layer_num_key_value_heads * v_head_dim;
                let attention_width = config.num_heads * v_head_dim;
                Ok(HostTransformerLayer {
                    post_attention_norm: None,
                    post_mlp_norm: None,
                    ln1: rms_norm(1.0 + base),
                    c_attn: None,
                    q_proj: Some(linear(d, q, base + 0.01)),
                    k_proj: Some(linear(d, key_width, base + 0.02)),
                    v_proj: Some(linear(d, value_width, base + 0.03)),
                    q_norm: None,
                    k_norm: None,
                    c_proj: linear(attention_width, d, base + 0.04),
                    ln2: rms_norm(1.0 + base + 0.05),
                    c_fc: linear(d, i, base + 0.06),
                    c_gate: Some(linear(d, i, base + 0.07)),
                    c_mlp_proj: linear(i, d, base + 0.08),
                    xielu: None,
                })
            })
            .collect::<Result<Vec<_>>>()?;

        let sparse_layer = (0..config.num_layers)
            .find(|&layer| config.layer_uses_moe(layer))
            .context("tiny MiMo-V2-Flash fixture is missing its sparse layer")?;
        let sparse_i = config.layer_intermediate_size(sparse_layer);
        let host_moe = HostMoeLayer {
            router: linear(d, num_experts, 0.31),
            router_correction_bias: vec![0.32, 0.33, 0.34],
            hash_router: None,
            expert_capacity: 0,
            owned_expert0: None,
            identity_expert_start: num_experts,
            experts: (1..num_experts)
                .map(|expert| {
                    let base = 0.40 + 0.05 * expert as f32;
                    HostMoeExpert {
                        gate: Some(linear(d, sparse_i, base + 0.01)),
                        up: linear(d, sparse_i, base + 0.02),
                        down: linear(sparse_i, d, base + 0.03),
                    }
                })
                .collect(),
            shared_expert: None,
            shared_expert_gate: None,
            latent: None,
        };
        let host = HostTransformerWeights {
            token_embedding: vec![0.01; config.vocab_size * d],
            position_embedding: None,
            embedding_norm: None,
            layers,
            final_norm: rms_norm(1.03),
            prediction_head: None,
            has_lm_head_alias: false,
            lm_head: Some(vec![0.02; config.vocab_size * d]),
            lm_head_bias: None,
        };
        let rotary_layers = vec![
            TransformerRotaryLayerSpec {
                enabled: true,
                rotary_dim: config.rotary_dim,
                rotary_emb_base: 5_000_000.0,
                rope_scaling: VulkanRopeScaling::default(),
            },
            TransformerRotaryLayerSpec {
                enabled: true,
                rotary_dim: config.rotary_dim,
                rotary_emb_base: 10_000.0,
                rope_scaling: VulkanRopeScaling::default(),
            },
        ];
        let attention_sinks = Some(vec![None, Some(vec![0.71, 0.72, 0.73, 0.74])]);
        VulkanTransformer::new(
            device,
            config,
            None,
            1,
            8,
            0,
            true,
            host,
            rotary_layers,
            attention_sinks,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            false,
            0.0,
            None,
            None,
            None,
            None,
            None,
            Some(vec![host_moe]),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        )
    }

