    fn write_tiny_bart_layout_checkpoint(
        test_dir: &Path,
        value: &serde_json::Value,
        include_embedding_norm: bool,
        include_terminal_norm: bool,
    ) -> Result<VulkanTransformerConfig> {
        let config = VulkanTransformerConfig::from_hf_value(value)?;
        let d = config.hidden_size;
        let i = config.intermediate_size;
        fs::create_dir_all(test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(value)?)?;

        let token_embedding = vec![0.01; config.vocab_size * d];
        let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
        tensors.push((
            "model.decoder.embed_tokens.weight".to_owned(),
            vec![config.vocab_size, d],
            token_embedding.clone(),
        ));
        if config.architecture == VulkanTransformerArchitecture::Fsmt {
            tensors.push((
                "model.decoder.output_projection.weight".to_owned(),
                vec![config.vocab_size, d],
                vec![0.19; config.vocab_size * d],
            ));
        } else {
            tensors.push((
                "lm_head.weight".to_owned(),
                vec![config.vocab_size, d],
                token_embedding,
            ));
        }
        let mut add = |name: &str, shape: Vec<usize>, fill: f32| {
            let len = shape.iter().product();
            tensors.push((name.to_owned(), shape, vec![fill; len]));
        };
        if !config.architecture.uses_fixed_sinusoidal_positions() {
            let position_rows = if matches!(
                config.architecture,
                VulkanTransformerArchitecture::Blenderbot
                    | VulkanTransformerArchitecture::BlenderbotSmall
                    | VulkanTransformerArchitecture::Pegasus
                    | VulkanTransformerArchitecture::BigBirdPegasus
            ) {
                config.max_position_embeddings
            } else {
                config.max_position_embeddings + 2
            };
            add(
                "model.decoder.embed_positions.weight",
                vec![position_rows, d],
                0.02,
            );
        }
        if include_embedding_norm {
            add("model.decoder.layernorm_embedding.weight", vec![d], 1.0);
            add("model.decoder.layernorm_embedding.bias", vec![d], 0.0);
        }
        let attention_has_bias = match config.architecture {
            VulkanTransformerArchitecture::BigBirdPegasus => value
                .get("use_bias")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            VulkanTransformerArchitecture::PegasusX => false,
            _ => true,
        };
        let p = "model.decoder.layers.0";
        for (name, fill) in [
            ("q_proj", 0.03),
            ("k_proj", 0.04),
            ("v_proj", 0.05),
            ("out_proj", 0.06),
        ] {
            add(&format!("{p}.self_attn.{name}.weight"), vec![d, d], fill);
            if attention_has_bias {
                add(&format!("{p}.self_attn.{name}.bias"), vec![d], fill + 0.1);
            }
        }
        add(&format!("{p}.self_attn_layer_norm.weight"), vec![d], 1.1);
        add(&format!("{p}.self_attn_layer_norm.bias"), vec![d], 0.11);
        for (name, fill) in [
            ("q_proj", 0.13),
            ("k_proj", 0.14),
            ("v_proj", 0.15),
            ("out_proj", 0.16),
        ] {
            add(&format!("{p}.encoder_attn.{name}.weight"), vec![d, d], fill);
            if attention_has_bias {
                add(
                    &format!("{p}.encoder_attn.{name}.bias"),
                    vec![d],
                    fill + 0.1,
                );
            }
        }
        add(&format!("{p}.encoder_attn_layer_norm.weight"), vec![d], 1.2);
        add(&format!("{p}.encoder_attn_layer_norm.bias"), vec![d], 0.12);
        add(&format!("{p}.fc1.weight"), vec![i, d], 0.17);
        add(&format!("{p}.fc1.bias"), vec![i], 0.27);
        add(&format!("{p}.fc2.weight"), vec![d, i], 0.18);
        add(&format!("{p}.fc2.bias"), vec![d], 0.28);
        add(&format!("{p}.final_layer_norm.weight"), vec![d], 1.3);
        add(&format!("{p}.final_layer_norm.bias"), vec![d], 0.13);
        if include_terminal_norm {
            let prefix = if config.architecture == VulkanTransformerArchitecture::BigBirdPegasus {
                "model.decoder.layernorm_embedding"
            } else {
                "model.decoder.layer_norm"
            };
            add(&format!("{prefix}.weight"), vec![d], 1.4);
            add(&format!("{prefix}.bias"), vec![d], 0.14);
        }

        if config.architecture.supports_native_dense_text_encoder() {
            let encoder_layers = value
                .get("encoder_layers")
                .and_then(serde_json::Value::as_u64)
                .context("tiny seq2seq config is missing encoder_layers")?
                as usize;
            let encoder_ffn_dim = value
                .get("encoder_ffn_dim")
                .and_then(serde_json::Value::as_u64)
                .context("tiny seq2seq config is missing encoder_ffn_dim")?
                as usize;
            add(
                "model.encoder.embed_tokens.weight",
                vec![config.vocab_size, d],
                0.011,
            );
            if !config.architecture.uses_fixed_sinusoidal_positions() {
                let position_rows =
                    if config.architecture == VulkanTransformerArchitecture::Blenderbot {
                        config.max_position_embeddings
                    } else {
                        config.max_position_embeddings + 2
                    };
                add(
                    "model.encoder.embed_positions.weight",
                    vec![position_rows, d],
                    0.021,
                );
            }
            if !matches!(
                config.architecture,
                VulkanTransformerArchitecture::Blenderbot
                    | VulkanTransformerArchitecture::Pegasus
                    | VulkanTransformerArchitecture::M2M100
            ) {
                add("model.encoder.layernorm_embedding.weight", vec![d], 1.01);
                add("model.encoder.layernorm_embedding.bias", vec![d], 0.01);
            }
            for layer in 0..encoder_layers {
                let p = format!("model.encoder.layers.{layer}");
                let layer_offset = layer as f32 * 0.001;
                for (name, fill) in [
                    ("q_proj", 0.031),
                    ("k_proj", 0.041),
                    ("v_proj", 0.051),
                    ("out_proj", 0.061),
                ] {
                    add(
                        &format!("{p}.self_attn.{name}.weight"),
                        vec![d, d],
                        fill + layer_offset,
                    );
                    add(
                        &format!("{p}.self_attn.{name}.bias"),
                        vec![d],
                        fill + 0.1 + layer_offset,
                    );
                }
                add(
                    &format!("{p}.self_attn_layer_norm.weight"),
                    vec![d],
                    1.11 + layer_offset,
                );
                add(
                    &format!("{p}.self_attn_layer_norm.bias"),
                    vec![d],
                    0.111 + layer_offset,
                );
                add(
                    &format!("{p}.fc1.weight"),
                    vec![encoder_ffn_dim, d],
                    0.171 + layer_offset,
                );
                add(
                    &format!("{p}.fc1.bias"),
                    vec![encoder_ffn_dim],
                    0.271 + layer_offset,
                );
                add(
                    &format!("{p}.fc2.weight"),
                    vec![d, encoder_ffn_dim],
                    0.181 + layer_offset,
                );
                add(&format!("{p}.fc2.bias"), vec![d], 0.281 + layer_offset);
                add(
                    &format!("{p}.final_layer_norm.weight"),
                    vec![d],
                    1.31 + layer_offset,
                );
                add(
                    &format!("{p}.final_layer_norm.bias"),
                    vec![d],
                    0.131 + layer_offset,
                );
            }
            if matches!(
                config.architecture,
                VulkanTransformerArchitecture::MBart
                    | VulkanTransformerArchitecture::Blenderbot
                    | VulkanTransformerArchitecture::Pegasus
                    | VulkanTransformerArchitecture::M2M100
            ) {
                add("model.encoder.layer_norm.weight", vec![d], 1.41);
                add("model.encoder.layer_norm.bias", vec![d], 0.141);
            }
        }

        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;
        Ok(config)
    }

