    #[test]
    fn mpt_contract_parses_biasless_fused_qkv_exact_gelu_and_alibi() {
        let config =
            VulkanTransformerConfig::from_hf_value(&tiny_mpt_config()).expect("MPT config");
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Mpt);
        assert_eq!(config.hidden_size, 16);
        assert_eq!(config.num_layers, 2);
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 4);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.intermediate_size, 64);
        assert_eq!(config.max_position_embeddings, 8);
        assert_eq!(config.activation_function, "gelu");
        assert!(config.tie_word_embeddings);
        assert_eq!(config.architecture.alibi_mode(), 2);
        assert!(config.architecture.uses_alibi_attention());
        assert!(!config.architecture.uses_mask_relative_alibi_positions());
        assert!(!config.architecture.uses_rotary_attention());
        assert!(!config.architecture.uses_split_qkv());

        let mut dropout = tiny_mpt_config();
        dropout["resid_pdrop"] = serde_json::json!(0.2);
        dropout["emb_pdrop"] = serde_json::json!(0.3);
        dropout["attn_config"]["attn_pdrop"] = serde_json::json!(0.1);
        let config =
            VulkanTransformerConfig::from_hf_value(&dropout).expect("MPT effective dropout config");
        assert_eq!(config.attention_dropout, 0.1);
        assert_eq!(config.attention_output_dropout, 0.1);
        assert_eq!(config.mlp_output_dropout, 0.1);
        assert_eq!(config.embedding_dropout, 0.0);

        let mut qk_ln = tiny_mpt_config();
        qk_ln["attn_config"]["qk_ln"] = serde_json::json!(true);
        let config = VulkanTransformerConfig::from_hf_value(&qk_ln)
            .expect("current Hugging Face MPT retains qk_ln as a schema-only field");
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Mpt);
        assert_eq!(config.attention_multiplier, None);

        let mut legacy_schema = tiny_mpt_config();
        legacy_schema["attn_config"]["prefix_lm"] = serde_json::json!(true);
        legacy_schema["attn_config"]["attn_uses_sequence_id"] = serde_json::json!(true);
        legacy_schema["expansion_ratio"] = serde_json::json!(7);
        legacy_schema["embedding_fraction"] = serde_json::json!(0.25);
        let config = VulkanTransformerConfig::from_hf_value(&legacy_schema)
            .expect("current Hugging Face MPT schema-only legacy fields");
        assert_eq!(config.intermediate_size, config.hidden_size * 4);

        let mut malformed_qk_ln = tiny_mpt_config();
        malformed_qk_ln["attn_config"]["qk_ln"] = serde_json::json!("yes");
        let error = VulkanTransformerConfig::from_hf_value(&malformed_qk_ln)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("qk_ln must be a boolean"),
            "unexpected error: {error}"
        );

        let mut custom_scale = tiny_mpt_config();
        custom_scale["attn_config"]["softmax_scale"] = serde_json::json!(0.25);
        let config = VulkanTransformerConfig::from_hf_value(&custom_scale)
            .expect("MPT custom softmax scale");
        assert_eq!(config.attention_multiplier, Some(0.25));
        assert_eq!(config.attention_scale(), 0.25);

        let mut clipped = tiny_mpt_config();
        clipped["attn_config"]["clip_qkv"] = serde_json::json!(3.5);
        let config = VulkanTransformerConfig::from_hf_value(&clipped).expect("MPT QKV clipping");
        assert_eq!(config.qkv_clip, Some(3.5));

        let mut unclipped_zero = tiny_mpt_config();
        unclipped_zero["attn_config"]["clip_qkv"] = serde_json::json!(0.0);
        let config = VulkanTransformerConfig::from_hf_value(&unclipped_zero)
            .expect("MPT zero QKV clip is inactive like Hugging Face");
        assert_eq!(config.qkv_clip, None);

        let mut invalid_scale = tiny_mpt_config();
        invalid_scale["attn_config"]["softmax_scale"] = serde_json::json!(0.0);
        let error = VulkanTransformerConfig::from_hf_value(&invalid_scale)
            .unwrap_err()
            .to_string();
        assert!(error.contains("softmax_scale must be finite and > 0"));

        let mut custom_alibi = tiny_mpt_config();
        custom_alibi["attn_config"]["alibi_bias_max"] = serde_json::json!(4);
        let config = VulkanTransformerConfig::from_hf_value(&custom_alibi)
            .expect("MPT custom ALiBi bias maximum");
        assert_eq!(config.alibi_bias_max, 4.0);
    }

