    #[test]
    fn gpt2_and_gpt_bigcode_contracts_support_unscaled_attention() {
        let mut gpt2 = tiny_gpt2_config();
        gpt2["scale_attn_weights"] = serde_json::json!(false);
        gpt2["reorder_and_upcast_attn"] = serde_json::json!(true);
        let gpt2 = VulkanTransformerConfig::from_hf_value(&gpt2)
            .expect("unscaled FP32 GPT-2 attention config");
        assert_eq!(gpt2.attention_multiplier, Some(1.0));
        assert_eq!(gpt2.attention_scale(), 1.0);

        let mut inverse_layer = tiny_gpt2_config();
        inverse_layer["scale_attn_by_inverse_layer_idx"] = serde_json::json!(true);
        let inverse_layer = VulkanTransformerConfig::from_hf_value(&inverse_layer)
            .expect("GPT-2 inverse-layer attention scaling config");
        assert!(inverse_layer.scale_attn_by_inverse_layer_idx);
        assert_eq!(
            inverse_layer.attention_scale_for_layer(0),
            inverse_layer.attention_scale()
        );
        assert_eq!(
            inverse_layer.attention_scale_for_layer(1),
            inverse_layer.attention_scale() / 2.0
        );

        let mut gpt_bigcode = tiny_gpt_bigcode_config();
        gpt_bigcode["scale_attn_weights"] = serde_json::json!(false);
        let gpt_bigcode = VulkanTransformerConfig::from_hf_value(&gpt_bigcode)
            .expect("unscaled GPT-BigCode attention config");
        assert_eq!(gpt_bigcode.attention_multiplier, Some(1.0));
        assert_eq!(gpt_bigcode.attention_scale(), 1.0);

        let mut malformed = tiny_gpt2_config();
        malformed["reorder_and_upcast_attn"] = serde_json::json!(1);
        let error = VulkanTransformerConfig::from_hf_value(&malformed)
            .unwrap_err()
            .to_string();
        assert!(error.contains("reorder_and_upcast_attn must be a boolean"));
    }

