    #[test]
    fn olmo2_contract_maps_post_sublayer_rmsnorm_and_full_projection_qk_norm() {
        let config =
            VulkanTransformerConfig::from_hf_value(&tiny_olmo2_config()).expect("OLMo2 config");
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Olmo2);
        assert_eq!(config.architecture.model_type(), "olmo2");
        assert_eq!(config.layer_norm_eps, 1.0e-5);
        assert_eq!(config.activation_function, "silu");
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 2);
        assert_eq!(config.query_hidden_size(), 16);
        assert_eq!(config.key_value_hidden_size(), 8);
        assert!(!config.tie_word_embeddings);
        assert!(config.architecture.uses_llama_layout());
        assert!(config.architecture.uses_rms_norm());
        assert!(config.architecture.uses_gated_mlp());
        assert!(config.architecture.uses_rotary_attention());
        assert!(config.architecture.supports_grouped_query_attention());
        // Current Transformers OLMo2 deletes OLMo's input pre-norm and applies
        // RMSNorm only to each attention/MLP branch output before the residual
        // add. Keep this distinct from Gemma-style sandwich (pre+post) norms.
        assert!(config.architecture.uses_post_sublayer_norm());
        assert!(!config.architecture.uses_pre_and_post_sublayer_norm());
        assert!(config.architecture.uses_rms_qk_norm());
        assert!(config.architecture.uses_full_projection_qk_norm());
        assert!(!config.architecture.uses_post_rope_qk_norm());
    }

