        assert!(config.architecture.clips_qkv_after_qk_norm());
        assert!(config.architecture.uses_gated_mlp());
        assert!(config.architecture.uses_rotary_attention());
        assert!(config.architecture.supports_grouped_query_attention());
        assert!(!config.architecture.uses_post_rope_qk_norm());

        let moe = config.moe.as_ref().expect("OLMoE routing config");
        assert_eq!(moe.num_experts, 3);
        assert_eq!(moe.top_k, 2);
        assert!(!moe.normalize_top_k);
