    #[test]
    fn exaone4_contract_maps_post_norm_qk_norm_and_hybrid_rope_schedule() {
        let value = tiny_exaone4_config();
        let config = VulkanTransformerConfig::from_hf_value(&value).expect("EXAONE-4 config");
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Exaone4);
        assert_eq!(config.architecture.model_type(), "exaone4");
        assert_eq!(config.layer_norm_eps, 1.0e-5);
        assert_eq!(config.activation_function, "silu");
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 2);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.attention_windows, vec![4, 0, 4, 0]);
        assert!(config.architecture.uses_llama_layout());
        assert!(config.architecture.uses_rms_norm());
        assert!(config.architecture.uses_gated_mlp());
        assert!(config.architecture.uses_rotary_attention());
        assert!(config.architecture.supports_grouped_query_attention());
        assert!(config.architecture.uses_post_sublayer_norm());
        assert!(config.architecture.uses_rms_qk_norm());
        assert!(!config.architecture.uses_full_projection_qk_norm());
        assert_eq!(
            VulkanTransformerConfig::exaone4_sliding_layers(&value, 4)
                .expect("EXAONE-4 rotary/local schedule"),
            vec![true, false, true, false]
        );

        let mut implicit = tiny_exaone4_config();
        implicit
            .as_object_mut()
            .expect("EXAONE-4 object")
            .remove("layer_types");
        let implicit =
            VulkanTransformerConfig::from_hf_value(&implicit).expect("EXAONE-4 implicit pattern");
        assert_eq!(implicit.attention_windows, vec![4, 0, 4, 0]);

        let mut no_sliding = tiny_exaone4_config();
        no_sliding["sliding_window"] = serde_json::Value::Null;
        no_sliding
            .as_object_mut()
            .expect("EXAONE-4 object")
            .remove("layer_types");
        let no_sliding = VulkanTransformerConfig::from_hf_value(&no_sliding)
            .expect("EXAONE-4 global RoPE config");
        assert_eq!(no_sliding.attention_windows, vec![0, 0, 0, 0]);

        let mut legacy_45 = tiny_exaone4_config();
        legacy_45["model_type"] = serde_json::json!("exaone4_5_text");
        let legacy_45 = VulkanTransformerConfig::from_hf_value(&legacy_45)
            .expect("legacy EXAONE-4.5 text model type");
        assert_eq!(
            legacy_45.architecture,
            VulkanTransformerArchitecture::Exaone4
        );
        assert_eq!(legacy_45.attention_windows, config.attention_windows);
        assert_eq!(legacy_45.head_dim, config.head_dim);
    }

    #[test]
    fn olmo2_checkpoint_loader_reads_post_sublayer_and_full_projection_qk_norms() -> Result<()> {
        let mut value = tiny_olmo2_config();
        value["num_hidden_layers"] = serde_json::json!(1);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let i = config.intermediate_size;
        let q = config.query_hidden_size();
        let kv = config.key_value_hidden_size();
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-olmo2-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

        let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
        let mut add = |name: &str, shape: Vec<usize>, fill: f32| {
            let len = shape.iter().product();
            tensors.push((name.to_owned(), shape, vec![fill; len]));
        };
        add(
            "model.embed_tokens.weight",
            vec![config.vocab_size, d],
            0.01,
        );
        add("model.layers.0.self_attn.q_proj.weight", vec![q, d], 0.02);
        add("model.layers.0.self_attn.k_proj.weight", vec![kv, d], 0.03);
        add("model.layers.0.self_attn.v_proj.weight", vec![kv, d], 0.04);
        add("model.layers.0.self_attn.o_proj.weight", vec![d, q], 0.05);
        add("model.layers.0.self_attn.q_norm.weight", vec![q], 1.25);
        add("model.layers.0.self_attn.k_norm.weight", vec![kv], 1.5);
        add(
            "model.layers.0.post_attention_layernorm.weight",
            vec![d],
            1.75,
        );
        add("model.layers.0.mlp.gate_proj.weight", vec![i, d], 0.06);
        add("model.layers.0.mlp.up_proj.weight", vec![i, d], 0.07);
        add("model.layers.0.mlp.down_proj.weight", vec![d, i], 0.08);
        add(
            "model.layers.0.post_feedforward_layernorm.weight",
            vec![d],
            2.0,
        );
        add("model.norm.weight", vec![d], 2.25);
        add("lm_head.weight", vec![config.vocab_size, d], 0.09);

        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let host = load_llama_weights(&test_dir, &config)?;
        let layer = &host.layers[0];
        assert_eq!(layer.ln1.weight[0], 1.75);
        assert_eq!(layer.ln2.weight[0], 2.0);
        assert_eq!(layer.q_norm.as_ref().unwrap().weight.len(), q);
        assert_eq!(layer.k_norm.as_ref().unwrap().weight.len(), kv);
        assert_eq!(layer.q_norm.as_ref().unwrap().weight[0], 1.25);
        assert_eq!(layer.k_norm.as_ref().unwrap().weight[0], 1.5);
        assert!(layer.q_norm.as_ref().unwrap().bias.is_empty());
        assert!(layer.k_norm.as_ref().unwrap().bias.is_empty());
        assert!(layer.q_proj.as_ref().unwrap().bias.is_none());
        assert!(layer.k_proj.as_ref().unwrap().bias.is_none());
        assert!(layer.v_proj.as_ref().unwrap().bias.is_none());
        assert!(layer.c_proj.bias.is_none());
        assert!(layer.c_gate.as_ref().unwrap().bias.is_none());
        assert!(layer.c_fc.bias.is_none());
        assert!(layer.c_mlp_proj.bias.is_none());
        assert_eq!(host.final_norm.weight[0], 2.25);
        assert!(host.lm_head.is_some());
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

