    #[test]
    fn bart_seq2seq_facade_encodes_source_ids_and_matches_explicit_context_generation() -> Result<()>
    {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut value = tiny_bart_config();
        value["encoder_layers"] = serde_json::json!(1);
        value["decoder_layers"] = serde_json::json!(1);
        value["dropout"] = serde_json::json!(0.0);
        value["attention_dropout"] = serde_json::json!(0.0);
        value["activation_dropout"] = serde_json::json!(0.0);
        value["scale_embedding"] = serde_json::json!(false);
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-bart-seq2seq-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        let config = write_tiny_bart_layout_checkpoint(&test_dir, &value, true, false)?;
        let model = VulkanSeq2SeqTransformer::from_hf_package(device, &test_dir, 3, 5)?;
        assert_eq!(
            model.config().architecture,
            VulkanTransformerArchitecture::Bart
        );
        assert!(!model.encoder().uses_causal_attention());
        assert!(model.decoder().uses_causal_attention());
        assert_eq!(model.encoder().seq_len(), 3);
        assert_eq!(model.decoder().seq_len(), 5);
        assert_eq!(model.decoder().encoder_seq_len(), Some(3));

        let source = [3_u32, 5, 1];
        let source_mask = [1.0_f32, 1.0, 0.0];
        let encoder_hidden = model.encode(&source, Some(&source_mask))?;
        assert_eq!(encoder_hidden.len(), source.len() * config.hidden_size);
        assert!(encoder_hidden.iter().all(|value| value.is_finite()));
        let all_visible = [1.0_f32; 3];
        assert_eq!(
            model.encode(&source, None)?,
            model.encode(&source, Some(&all_visible))?
        );

        let generation_config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(2),
            decoder_start_token_id: Some(VulkanTransformerDecoderStartTokenId::Single(2)),
            bos_token_id: Some(0),
            eos_token_ids: Vec::new(),
            ..VulkanTransformerGenerationConfig::default()
        };
        let explicit = model
            .decoder()
            .generate_sequences_ids_with_encoder_input_ids_and_hidden_states(
                &[],
                &generation_config,
                &source,
                &encoder_hidden,
                &source_mask,
            )?;
        let direct =
            model.generate_sequences_ids(&source, Some(&source_mask), &generation_config)?;
        assert_eq!(direct, explicit);
        assert_eq!(
            model.generate_ids(&source, Some(&source_mask), &generation_config)?,
            direct[0]
        );

        let mut streamed = vec![Vec::<u32>::new(); generation_config.num_return_sequences];
        let streamed_result = model.generate_sequences_ids_streaming(
            &source,
            Some(&source_mask),
            &generation_config,
            |sequence_index, token| {
                streamed[sequence_index].push(token);
                Ok(())
            },
        )?;
        assert_eq!(streamed_result, direct);
        assert_eq!(streamed, direct);

        let structured_config = VulkanTransformerGenerationConfig {
            output_attentions: true,
            output_hidden_states: true,
            return_dict_in_generate: true,
            ..generation_config.clone()
        };
        let output = model.generate_output(&source, Some(&source_mask), &structured_config)?;
        assert_eq!(output.sequences.len(), 1);
        assert_eq!(output.sequences[0].generated_ids(), direct[0]);
        assert!(output.sequences[0].attentions.is_some());
        assert!(output.sequences[0].cross_attentions.is_some());
        assert!(output.sequences[0].hidden_states.is_some());

        let decoder_ids = [2_u32, 7, 9, 4, 6];
        let decoder_mask = [1.0_f32; 5];
        let logits =
            model.forward_logits(&source, Some(&source_mask), &decoder_ids, &decoder_mask)?;
        assert_eq!(logits.len(), decoder_ids.len() * config.vocab_size);
        assert!(logits.iter().all(|value| value.is_finite()));

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

