    #[test]
    fn transformer_layerdrop_sampling_is_deterministic_and_non_degenerate() -> Result<()> {
        let first = (1..=64)
            .map(|step| transformer_layer_is_active(0.5, 0x1234_5678, step, 3))
            .collect::<Result<Vec<_>>>()?;
        let second = (1..=64)
            .map(|step| transformer_layer_is_active(0.5, 0x1234_5678, step, 3))
            .collect::<Result<Vec<_>>>()?;
        assert_eq!(first, second);
        assert!(first.iter().any(|active| *active));
        assert!(first.iter().any(|active| !*active));
        assert!(transformer_layer_is_active(0.0, 0, 1, 0)?);
        Ok(())
    }

    #[test]
    fn transformer_layerdrop_package_reads_hf_family_specific_fields() -> Result<()> {
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-layerdrop-config-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;

        let mut marian = tiny_bart_config();
        marian["model_type"] = serde_json::json!("marian");
        marian["decoder_layerdrop"] = serde_json::json!(0.11);

        let mut opt = tiny_opt_config();
        opt["layerdrop"] = serde_json::json!(0.12);

        let mut biogpt = tiny_biogpt_config();
        biogpt["layerdrop"] = serde_json::json!(0.13);

        let mut xglm = tiny_xglm_config();
        xglm["layerdrop"] = serde_json::json!(0.14);

        let mut flaubert = tiny_flaubert_config();
        flaubert["layerdrop"] = serde_json::json!(0.15);

        for (value, architecture, expected) in [
            (marian, VulkanTransformerArchitecture::Marian, 0.11f32),
            (opt, VulkanTransformerArchitecture::Opt, 0.12f32),
            (biogpt, VulkanTransformerArchitecture::BioGpt, 0.13f32),
            (xglm, VulkanTransformerArchitecture::Xglm, 0.14f32),
            (flaubert, VulkanTransformerArchitecture::Flaubert, 0.15f32),
        ] {
            let config = VulkanTransformerConfig::from_hf_value(&value)?;
            assert_eq!(config.architecture, architecture);
            fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;
            let actual = transformer_layerdrop_for_package(&test_dir, &config)?;
            assert!((actual - expected).abs() < 1.0e-6);
        }

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn opt_contract_parses_pre_layernorm_learned_positions_and_split_qkv() {
        let config =
            VulkanTransformerConfig::from_hf_value(&tiny_opt_config()).expect("OPT config");
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Opt);
        assert_eq!(config.hidden_size, 16);
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 4);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.intermediate_size, 28);
        assert_eq!(config.max_position_embeddings, 8);
        assert_eq!(config.activation_function, "relu");
        assert!(config.tie_word_embeddings);
        assert!(config.layer_norm_elementwise_affine);
        assert!(!config.uses_parameter_free_layer_norm());
        assert_eq!(config.rotary_dim, 0);
        assert!(config.architecture.uses_split_qkv());

        let mut affine_free = tiny_opt_config();
        affine_free["layer_norm_elementwise_affine"] = serde_json::json!(false);
        let affine_free = VulkanTransformerConfig::from_hf_value(&affine_free)
            .expect("OPT affine-free LayerNorm config should be accepted");
        assert!(!affine_free.layer_norm_elementwise_affine);
        assert!(affine_free.uses_parameter_free_layer_norm());

        let mut projected = tiny_opt_config();
        projected["word_embed_proj_dim"] = serde_json::json!(12);
        let projected = VulkanTransformerConfig::from_hf_value(&projected)
            .expect("projected OPT embedding config should be accepted");
        assert_eq!(projected.effective_embedding_size(), 12);
        assert!(projected.uses_final_norm());

        let mut post_norm = tiny_opt_config();
        post_norm["do_layer_norm_before"] = serde_json::json!(false);
        let post_norm = VulkanTransformerConfig::from_hf_value(&post_norm)
            .expect("post-LayerNorm OPT config should be accepted");
        assert!(post_norm.use_post_norm);
        assert!(post_norm.uses_post_residual_norm());
        assert!(!post_norm.uses_final_norm());

        let mut removed_final_norm = tiny_opt_config();
        removed_final_norm["_remove_final_layer_norm"] = serde_json::json!(true);
        let removed_final_norm = VulkanTransformerConfig::from_hf_value(&removed_final_norm)
            .expect("legacy OPT config without terminal LayerNorm should be accepted");
        assert!(removed_final_norm.remove_final_norm);
        assert!(!removed_final_norm.use_post_norm);
        assert!(!removed_final_norm.uses_post_residual_norm());
        assert!(!removed_final_norm.uses_final_norm());

        let mut layerdrop = tiny_opt_config();
        layerdrop["layerdrop"] = serde_json::json!(0.1);
        let layerdrop = VulkanTransformerConfig::from_hf_value(&layerdrop)
            .expect("OPT LayerDrop config should be accepted");
        assert_eq!(layerdrop.architecture, VulkanTransformerArchitecture::Opt);
    }

    #[test]
    fn opt_checkpoint_loader_synthesizes_affine_free_layer_norms() -> Result<()> {
        let mut value = tiny_opt_config();
        value["num_hidden_layers"] = serde_json::json!(1);
        value["layer_norm_elementwise_affine"] = serde_json::json!(false);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let i = config.intermediate_size;
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-opt-affine-free-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

        let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
        let mut add = |name: &str, shape: Vec<usize>, fill: f32| {
            let len = shape.iter().product();
            tensors.push((name.to_owned(), shape, vec![fill; len]));
        };
        add(
            "model.decoder.embed_tokens.weight",
            vec![config.vocab_size, d],
            0.01,
        );
        add(
            "model.decoder.embed_positions.weight",
            vec![config.max_position_embeddings + 2, d],
            0.02,
        );
        for (name, fill) in [
            ("q_proj", 0.03),
            ("k_proj", 0.04),
            ("v_proj", 0.05),
            ("out_proj", 0.06),
        ] {
            add(
                &format!("model.decoder.layers.0.self_attn.{name}.weight"),
                vec![d, d],
                fill,
            );
            add(
                &format!("model.decoder.layers.0.self_attn.{name}.bias"),
                vec![d],
                fill + 0.1,
            );
        }
        add("model.decoder.layers.0.fc1.weight", vec![i, d], 0.07);
        add("model.decoder.layers.0.fc1.bias", vec![i], 0.17);
        add("model.decoder.layers.0.fc2.weight", vec![d, i], 0.08);
        add("model.decoder.layers.0.fc2.bias", vec![d], 0.18);

        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let host = load_opt_weights(&test_dir, &config)?;
        let layer = &host.layers[0];
        assert_eq!(layer.ln1.weight, vec![1.0; d]);
        assert!(layer.ln1.bias.is_empty());
        assert_eq!(layer.ln2.weight, vec![1.0; d]);
        assert!(layer.ln2.bias.is_empty());
        assert_eq!(host.final_norm.weight, vec![1.0; d]);
        assert!(host.final_norm.bias.is_empty());
        assert_eq!(
            layer.q_proj.as_ref().unwrap().bias.as_ref().unwrap()[0],
            0.13
        );
        assert_eq!(layer.c_fc.bias.as_ref().unwrap()[0], 0.17);
        assert!(host.lm_head.is_none());
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

