    #[test]
    fn ctrl_checkpoint_loader_synthesizes_positions_and_reads_hf_weights() -> Result<()> {
        let mut value = tiny_ctrl_config();
        value["n_layer"] = serde_json::json!(1);
        value["resid_pdrop"] = serde_json::json!(0.0);
        value["embd_pdrop"] = serde_json::json!(0.0);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let i = config.intermediate_size;
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-ctrl-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

        let token_embedding = vec![0.01; config.vocab_size * d];
        let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
        tensors.push((
            "transformer.w.weight".to_owned(),
            vec![config.vocab_size, d],
            token_embedding.clone(),
        ));
        tensors.push((
            "lm_head.weight".to_owned(),
            vec![config.vocab_size, d],
            token_embedding,
        ));
        let mut add = |name: &str, shape: Vec<usize>, fill: f32| {
            let len = shape.iter().product();
            tensors.push((name.to_owned(), shape, vec![fill; len]));
        };
        add("transformer.h.0.layernorm1.weight", vec![d], 1.0);
        add("transformer.h.0.layernorm1.bias", vec![d], 0.0);
        add("transformer.h.0.layernorm2.weight", vec![d], 1.1);
        add("transformer.h.0.layernorm2.bias", vec![d], 0.1);
        for (name, fill) in [("Wq", 0.03), ("Wk", 0.04), ("Wv", 0.05)] {
            add(
                &format!("transformer.h.0.multi_head_attention.{name}.weight"),
                vec![d, d],
                fill,
            );
            add(
                &format!("transformer.h.0.multi_head_attention.{name}.bias"),
                vec![d],
                fill + 0.1,
            );
        }
        add(
            "transformer.h.0.multi_head_attention.dense.weight",
            vec![d, d],
            0.06,
        );
        add(
            "transformer.h.0.multi_head_attention.dense.bias",
            vec![d],
            0.16,
        );
        add("transformer.h.0.ffn.0.weight", vec![i, d], 0.07);
        add("transformer.h.0.ffn.0.bias", vec![i], 0.17);
        add("transformer.h.0.ffn.2.weight", vec![d, i], 0.08);
        add("transformer.h.0.ffn.2.bias", vec![d], 0.18);
        add("transformer.layernorm.weight", vec![d], 1.2);
        add("transformer.layernorm.bias", vec![d], 0.2);
        add("lm_head.bias", vec![config.vocab_size], 0.19);

        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let host = load_ctrl_weights(&test_dir, &config)?;
        let positions = host.position_embedding.as_ref().unwrap();
        assert_eq!(positions.len(), config.max_position_embeddings * d);
        assert_eq!(&positions[..d / 2], &vec![0.0; d / 2]);
        assert_eq!(&positions[d / 2..d], &vec![1.0; d / 2]);
        let second_position = &positions[d..2 * d];
        assert!((second_position[0] - 1.0_f32.sin()).abs() < 1.0e-6);
        assert!((second_position[d.div_ceil(2)] - 1.0_f32.cos()).abs() < 1.0e-6);
        assert_eq!(
            host.layers[0]
                .q_proj
                .as_ref()
                .unwrap()
                .bias
                .as_ref()
                .unwrap()[0],
            0.13
        );
        assert_eq!(host.layers[0].c_proj.bias.as_ref().unwrap()[0], 0.16);
        assert_eq!(host.layers[0].c_fc.bias.as_ref().unwrap()[0], 0.17);
        assert_eq!(host.layers[0].c_mlp_proj.bias.as_ref().unwrap()[0], 0.18);
        assert_eq!(host.final_norm.weight[0], 1.2);
        assert!(host.has_lm_head_alias);
        assert!(host.lm_head.is_none());
        assert_eq!(host.lm_head_bias.as_ref().unwrap()[0], 0.19);
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

