    #[test]
    fn nomic_bert_checkpoint_loader_preserves_hf_tensor_layout() -> Result<()> {
        let mut value = tiny_nomic_bert_config();
        value["num_hidden_layers"] = serde_json::json!(1);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos_vulkan_nomic_bert_loader_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(
            test_dir.join("config.json"),
            serde_json::to_vec_pretty(&value)?,
        )?;

        let d = config.hidden_size;
        let i = config.intermediate_size;
        let q = config.query_hidden_size();
        let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
        let mut add = |name: &str, shape: Vec<usize>, fill: f32| {
            let len = shape.iter().product();
            tensors.push((name.to_owned(), shape, vec![fill; len]));
        };
        add(
            "nomic_bert.embeddings.word_embeddings.weight",
            vec![config.vocab_size, d],
            0.01,
        );
        add(
            "nomic_bert.embeddings.token_type_embeddings.weight",
            vec![2, d],
            0.02,
        );
        add("nomic_bert.embeddings.LayerNorm.weight", vec![d], 1.0);
        add("nomic_bert.embeddings.LayerNorm.bias", vec![d], 0.03);
        for (name, fill) in [("q_proj", 0.11), ("k_proj", 0.12), ("v_proj", 0.13)] {
            add(
                &format!("nomic_bert.layers.0.self_attn.{name}.weight"),
                vec![q, d],
                fill,
            );
        }
        add(
            "nomic_bert.layers.0.self_attn.o_proj.weight",
            vec![d, q],
            0.14,
        );
        add(
            "nomic_bert.layers.0.post_attention_layernorm.weight",
            vec![d],
            1.1,
        );
        add(
            "nomic_bert.layers.0.post_attention_layernorm.bias",
            vec![d],
            0.15,
        );
        add("nomic_bert.layers.0.mlp.gate_proj.weight", vec![i, d], 0.21);
        add("nomic_bert.layers.0.mlp.up_proj.weight", vec![i, d], 0.22);
        add("nomic_bert.layers.0.mlp.down_proj.weight", vec![d, i], 0.23);
        add(
            "nomic_bert.layers.0.post_mlp_layernorm.weight",
            vec![d],
            1.2,
        );
        add("nomic_bert.layers.0.post_mlp_layernorm.bias", vec![d], 0.24);
        add("cls.predictions.transform.dense.weight", vec![d, d], 0.31);
        add("cls.predictions.transform.dense.bias", vec![d], 0.32);
        add("cls.predictions.transform.layer_norm.weight", vec![d], 1.3);
        add("cls.predictions.transform.layer_norm.bias", vec![d], 0.33);
        add(
            "cls.predictions.decoder.weight",
            vec![config.vocab_size, d],
            0.01,
        );
        add("cls.predictions.bias", vec![config.vocab_size], 0.34);
        add(
            "cls.predictions.decoder.bias",
            vec![config.vocab_size],
            0.34,
        );

        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let host = load_nomic_bert_weights(&test_dir, &config)?;
        assert!(host.position_embedding.is_none());
        assert_eq!(host.embedding_norm.as_ref().unwrap().bias[0], 0.03);
        assert_eq!(host.layers.len(), 1);
        let layer = &host.layers[0];
        assert_eq!(layer.q_proj.as_ref().unwrap().weight[0], 0.11);
        assert!(layer.q_proj.as_ref().unwrap().bias.is_none());
        assert_eq!(layer.k_proj.as_ref().unwrap().weight[0], 0.12);
        assert_eq!(layer.v_proj.as_ref().unwrap().weight[0], 0.13);
        assert_eq!(layer.c_proj.weight[0], 0.14);
        assert!(layer.c_proj.bias.is_none());
        assert_eq!(layer.ln1.weight[0], 1.1);
        assert_eq!(layer.c_gate.as_ref().unwrap().weight[0], 0.21);
        assert_eq!(layer.c_fc.weight[0], 0.22);
        assert_eq!(layer.c_mlp_proj.weight[0], 0.23);
        assert_eq!(layer.ln2.bias[0], 0.24);
        assert_eq!(host.final_norm.weight[0], 1.0);
        assert_eq!(host.final_norm.bias[0], 0.0);
        assert_eq!(host.prediction_head.as_ref().unwrap().norm.weight[0], 1.3);
        assert!(host.has_lm_head_alias);
        assert!(host.lm_head.is_none());
        assert_eq!(host.lm_head_bias.as_ref().unwrap()[0], 0.34);
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn roformer_contract_maps_interleaved_full_head_rope_and_decoder_cross_attention() -> Result<()>
    {
        let value = tiny_roformer_config();
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        assert_eq!(config.architecture, VulkanTransformerArchitecture::RoFormer);
        assert_eq!(config.architecture.model_type(), "roformer");
        assert_eq!(config.hidden_size, 16);
        assert_eq!(config.intermediate_size, 28);
        assert_eq!(config.num_layers, 2);
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.rotary_dim, config.head_dim);
        assert_eq!(config.rotary_emb_base, 10_000.0);
        assert!(!config.rope_scaling.rotate_values);
        assert!(config.architecture.uses_rotary_attention());
        assert!(config.architecture.uses_interleaved_rope());
        assert!(config.architecture.uses_post_residual_norm());
        assert!(!config.architecture.uses_final_norm());
        assert!(config.architecture.uses_split_qkv());
        assert_eq!(
            config.architecture.bert_family_base_prefix(),
            Some("roformer")
        );
        assert_eq!(config.architecture.default_lora_target_module(), "query");
        assert!(!config.uses_causal_attention());

        let mut decoder = value.clone();
        decoder["is_decoder"] = serde_json::json!(true);
        decoder["add_cross_attention"] = serde_json::json!(true);
        let decoder_config = VulkanTransformerConfig::from_hf_value(&decoder)?;
        assert!(decoder_config.uses_causal_attention());

        let mut rotary_value = value.clone();
        rotary_value["rotary_value"] = serde_json::json!(true);
        let rotary_value_config = VulkanTransformerConfig::from_hf_value(&rotary_value)?;
        assert!(rotary_value_config.rope_scaling.rotate_values);
        assert!(rotary_value_config.architecture.uses_rotary_attention());
        assert!(rotary_value_config.architecture.uses_interleaved_rope());

        let mut projected = value;
        projected["embedding_size"] = serde_json::json!(8);
        let projected_config = VulkanTransformerConfig::from_hf_value(&projected)?;
        assert_eq!(projected_config.embedding_size, 8);
        assert_eq!(projected_config.effective_embedding_size(), 8);
        assert_eq!(projected_config.hidden_size, 16);
        Ok(())
    }

    #[test]
    fn bert_generation_contract_maps_decoder_cross_attention_and_package_causality() -> Result<()> {
        let value = tiny_bert_generation_config();
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        assert_eq!(
            config.architecture,
            VulkanTransformerArchitecture::BertGeneration
        );
        assert_eq!(config.architecture.model_type(), "bert-generation");
        assert_eq!(config.hidden_size, 16);
        assert_eq!(config.intermediate_size, 28);
        assert_eq!(config.num_layers, 2);
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 4);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.max_position_embeddings, 8);
        assert_eq!(config.layer_norm_eps, 1.0e-12);
        assert_eq!(config.activation_function, "gelu");
        assert_eq!(config.attention_dropout, 0.1);
        assert_eq!(config.attention_output_dropout, 0.2);
        assert_eq!(config.mlp_output_dropout, 0.2);
        assert_eq!(config.embedding_dropout, 0.2);
        assert!(config.tie_word_embeddings);
        assert!(config.architecture.uses_post_residual_norm());
        assert!(!config.architecture.uses_final_norm());
        assert!(config.architecture.uses_split_qkv());
        assert_eq!(config.architecture.default_lora_target_module(), "query");

        let mut invalid = value.clone();
        invalid["is_decoder"] = serde_json::json!(false);
        let error = VulkanTransformerConfig::from_hf_value(&invalid)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("add_cross_attention=true requires is_decoder=true"),
            "unexpected error: {error}"
        );

        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-bert-generation-config-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;
        assert!(bert_generation_is_decoder(&test_dir)?);
        assert!(bert_generation_cross_attention_enabled(&test_dir)?);

        let mut encoder = value;
        encoder["is_decoder"] = serde_json::json!(false);
        encoder["add_cross_attention"] = serde_json::json!(false);
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&encoder)?)?;
        assert!(!bert_generation_is_decoder(&test_dir)?);
        assert!(!bert_generation_cross_attention_enabled(&test_dir)?);
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

