    #[test]
    fn roberta_family_contract_maps_padding_aware_positions_and_mlm_stack() -> Result<()> {
        for (value, architecture, model_type) in [
            (
                tiny_roberta_config(),
                VulkanTransformerArchitecture::Roberta,
                "roberta",
            ),
            (
                tiny_camembert_config(),
                VulkanTransformerArchitecture::Camembert,
                "camembert",
            ),
            (
                tiny_xlm_roberta_config(),
                VulkanTransformerArchitecture::XlmRoberta,
                "xlm-roberta",
            ),
            (
                tiny_data2vec_text_config(),
                VulkanTransformerArchitecture::Data2VecText,
                "data2vec-text",
            ),
        ] {
            let config = VulkanTransformerConfig::from_hf_value(&value)?;
            assert_eq!(config.architecture, architecture);
            assert_eq!(config.architecture.model_type(), model_type);
            assert_eq!(config.hidden_size, 16);
            assert_eq!(config.intermediate_size, 28);
            assert_eq!(config.num_layers, 2);
            assert_eq!(config.num_heads, 4);
            assert_eq!(config.num_key_value_heads, 4);
            assert_eq!(config.head_dim, 4);
            assert_eq!(config.max_position_embeddings, 10);
            assert_eq!(config.layer_norm_eps, 1.0e-5);
            assert_eq!(config.activation_function, "gelu");
            assert_eq!(config.attention_dropout, 0.1);
            assert_eq!(config.attention_output_dropout, 0.2);
            assert_eq!(config.mlp_output_dropout, 0.2);
            assert_eq!(config.embedding_dropout, 0.2);
            assert!(config.tie_word_embeddings);
            assert!(!config.uses_causal_attention());
            assert!(config.architecture.uses_post_residual_norm());
            assert!(!config.architecture.uses_final_norm());
            assert!(config.architecture.uses_split_qkv());
            assert!(config.architecture.uses_roberta_position_ids());
            assert_eq!(config.architecture.default_lora_target_module(), "query");
            assert_eq!(
                transformer_token_embedding_padding_idx_from_value(&value, &config)?,
                Some(1)
            );
        }

        for mut decoder in [
            tiny_roberta_config(),
            tiny_roberta_prelayernorm_config(),
            tiny_camembert_config(),
            tiny_xlm_roberta_config(),
            tiny_xlm_roberta_xl_config(),
            tiny_data2vec_text_config(),
        ] {
            decoder["is_decoder"] = serde_json::json!(true);
            decoder["add_cross_attention"] = serde_json::json!(true);
            let decoder_config = VulkanTransformerConfig::from_hf_value(&decoder)?;
            assert!(decoder_config.uses_causal_attention());
        }

        let mut invalid_cross_attention = tiny_roberta_config();
        invalid_cross_attention["add_cross_attention"] = serde_json::json!(true);
        let error = VulkanTransformerConfig::from_hf_value(&invalid_cross_attention)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("requires is_decoder=true"),
            "unexpected error: {error}"
        );

        let mut missing_padding = tiny_xlm_roberta_config();
        missing_padding
            .as_object_mut()
            .unwrap()
            .remove("pad_token_id");
        let error = VulkanTransformerConfig::from_hf_value(&missing_padding)
            .unwrap_err()
            .to_string();
        assert!(error.contains("pad_token_id"), "unexpected error: {error}");

        Ok(())
    }

    #[test]
    fn roberta_family_cross_attention_loader_matches_hf_norm_layouts() -> Result<()> {
        for (mut value, expected_norm_suffix) in [
            (tiny_roberta_config(), "output.LayerNorm"),
            (tiny_roberta_prelayernorm_config(), "LayerNorm"),
            (tiny_xlm_roberta_xl_config(), "self_attn_layer_norm"),
        ] {
            value["num_hidden_layers"] = serde_json::json!(1);
            value["is_decoder"] = serde_json::json!(true);
            value["add_cross_attention"] = serde_json::json!(true);
            let config = VulkanTransformerConfig::from_hf_value(&value)?;
            let d = config.hidden_size;
            let base = config
                .architecture
                .bert_family_base_prefix()
                .context("RoBERTa-family test config is missing base prefix")?;
            let test_dir = std::env::temp_dir().join(format!(
                "hierarchos-vulkan-roberta-cross-attention-{}-{}-{}",
                config.architecture.model_type().replace(['/', '\\'], "-"),
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)?
                    .as_nanos()
            ));
            fs::create_dir_all(&test_dir)?;
            fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

            let p = format!("{base}.encoder.layer.0.crossattention");
            let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
            let add = |tensors: &mut Vec<(String, Vec<usize>, Vec<f32>)>,
                       name: String,
                       shape: Vec<usize>,
                       fill: f32| {
                let len = shape.iter().product();
                tensors.push((name, shape, vec![fill; len]));
            };
            for (name, weight_fill, bias_fill) in [
                ("query", 0.11, 0.12),
                ("key", 0.21, 0.22),
                ("value", 0.31, 0.32),
            ] {
                add(
                    &mut tensors,
                    format!("{p}.self.{name}.weight"),
                    vec![d, d],
                    weight_fill,
                );
                add(
                    &mut tensors,
                    format!("{p}.self.{name}.bias"),
                    vec![d],
                    bias_fill,
                );
            }
            add(
                &mut tensors,
                format!("{p}.output.dense.weight"),
                vec![d, d],
                0.41,
            );
            add(
                &mut tensors,
                format!("{p}.output.dense.bias"),
                vec![d],
                0.42,
            );
            add(
                &mut tensors,
                format!("{p}.{expected_norm_suffix}.weight"),
                vec![d],
                1.25,
            );
            add(
                &mut tensors,
                format!("{p}.{expected_norm_suffix}.bias"),
                vec![d],
                0.25,
            );
            let owned = tensors
                .iter()
                .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
                .collect::<Vec<_>>();
            let views = owned
                .iter()
                .map(|(name, shape, bytes)| {
                    Ok((
                        name.as_str(),
                        TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                    ))
                })
                .collect::<Result<Vec<_>>>()?;
            serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

            let cross = load_roberta_family_cross_attention_weights(&test_dir, &config)?
                .context("RoBERTa-family decoder should load cross-attention")?;
            assert_eq!(cross.len(), 1);
            assert_eq!(cross[0].q_proj.weight[0], 0.11);
            assert_eq!(cross[0].k_proj.bias.as_ref().unwrap()[0], 0.22);
            assert_eq!(cross[0].v_proj.weight[0], 0.31);
            assert_eq!(cross[0].out_proj.bias.as_ref().unwrap()[0], 0.42);
            assert_eq!(cross[0].norm.weight[0], 1.25);
            assert_eq!(cross[0].norm.bias[0], 0.25);
            fs::remove_dir_all(&test_dir)?;
        }
        Ok(())
    }

