        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let host = load_roberta_weights(&test_dir, &config)?;
        let token_types = load_roberta_token_type_embedding(&test_dir, &config)?;
        assert_eq!(host.token_embedding[0], 0.01);
        assert_eq!(host.position_embedding.as_ref().unwrap()[0], 0.02);
        assert_eq!(token_types[0], 0.03);
        let layer = &host.layers[0];
