        assert_eq!(layer.c_proj.bias.as_ref().unwrap()[0], 0.52);
        assert_eq!(layer.ln2.bias[0], 0.62);
        assert_eq!(layer.c_fc.weight[0], 0.71);
        assert_eq!(layer.c_mlp_proj.bias.as_ref().unwrap()[0], 0.82);
