    #[test]
    fn esm_contract_matches_hf_encoder_decoder_and_rotary_modes() -> Result<()> {
        let config = VulkanTransformerConfig::from_hf_value(&tiny_esm_config())?;
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Esm);
        assert_eq!(config.hidden_size, 16);
        assert_eq!(config.intermediate_size, 32);
        assert_eq!(config.num_layers, 2);
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 4);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.rotary_dim, 0);
        assert_eq!(config.activation_function, "gelu");
        assert_eq!(config.embedding_dropout, 0.0);
        assert_eq!(config.attention_dropout, 0.1);
        assert_eq!(config.attention_output_dropout, 0.2);
        assert_eq!(config.mlp_output_dropout, 0.2);
        assert_eq!(config.attention_scale(), 1.0);
        assert_eq!(config.query_pre_attention_scale(), 0.5);
        assert!(!config.uses_causal_attention());
        assert!(config.architecture.uses_split_qkv());
        assert!(config.architecture.uses_final_norm());
        assert!(!config.architecture.uses_post_residual_norm());
        assert_eq!(config.architecture.bert_family_base_prefix(), Some("esm"));
        assert_eq!(config.architecture.default_lora_target_module(), "query");

        let mut rotary = tiny_esm_config();
        rotary["position_embedding_type"] = serde_json::json!("rotary");
        let rotary = VulkanTransformerConfig::from_hf_value(&rotary)?;
        assert_eq!(rotary.rotary_dim, rotary.head_dim);
        assert!(rotary.uses_rotary_attention());

        let mut decoder = tiny_esm_config();
        decoder["is_decoder"] = serde_json::json!(true);
        decoder["add_cross_attention"] = serde_json::json!(true);
        let decoder = VulkanTransformerConfig::from_hf_value(&decoder)?;
        assert!(decoder.uses_causal_attention());

        let mut invalid = tiny_esm_config();
        invalid["add_cross_attention"] = serde_json::json!(true);
        let error = VulkanTransformerConfig::from_hf_value(&invalid)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("requires is_decoder=true"),
            "unexpected error: {error}"
        );
        Ok(())
    }

    #[test]
    fn esm_token_dropout_scales_match_hf_mask_ratio_math() {
        let input_ids = [5u32, 32, 7, 1, 32, 9, 10, 11];
        let attention_mask = [1.0f32, 1.0, 1.0, 0.0, 1.0, 1.0, 1.0, 1.0];
        let scales = esm_token_dropout_row_scales(&input_ids, &attention_mask, 2, 4, 32);

        let first_scale = 0.88 / (1.0 - 1.0 / 3.0);
        let second_scale = 0.88 / (1.0 - 1.0 / 4.0);
        assert!((scales[0] - first_scale).abs() < 1.0e-6);
        assert_eq!(scales[1], 0.0);
        assert!((scales[2] - first_scale).abs() < 1.0e-6);
        assert!((scales[3] - first_scale).abs() < 1.0e-6);
        assert_eq!(scales[4], 0.0);
        for &scale in &scales[5..] {
            assert!((scale - second_scale).abs() < 1.0e-6);
        }
    }

    #[test]
    fn esmc_contract_maps_bidirectional_layernorm_qk_norm_and_residual_scaling() -> Result<()> {
        let value = tiny_esmc_config();
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Esmc);
        assert_eq!(config.architecture.model_type(), "esmc");
        assert_eq!(config.hidden_size, 16);
        assert_eq!(config.intermediate_size, 24);
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 4);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.layer_norm_eps, 1.0e-5);
        assert_eq!(config.activation_function, "silu");
        assert_eq!(config.residual_multiplier, 3.0);
        assert!(!config.architecture.uses_llama_layout());
        assert!(config.architecture.uses_split_qkv());
        assert!(config.architecture.uses_gated_mlp());
        assert!(config.architecture.uses_rotary_attention());
        assert!(!config.architecture.uses_rms_norm());
        assert!(config.architecture.uses_full_projection_qk_norm());
        assert!(!config.architecture.uses_causal_attention());
        assert_eq!(
            transformer_token_embedding_padding_idx_from_value(&value, &config)?,
            None
        );

        let mut biased = value;
        biased["attention_bias"] = serde_json::json!(true);
        biased["mlp_bias"] = serde_json::json!(true);
        VulkanTransformerConfig::from_hf_value(&biased)?;

        let mut invalid_gqa = tiny_esmc_config();
        invalid_gqa["num_key_value_heads"] = serde_json::json!(2);
        let error = VulkanTransformerConfig::from_hf_value(&invalid_gqa)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("grouped-query attention")
                || error.contains("num_key_value_heads == num_attention_heads"),
            "unexpected error: {error}"
        );
        Ok(())
    }

