    #[test]
    fn moe_jitter_replays_philox_and_backpropagates_through_router_and_experts() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let kernels = TransformerKernels::new(&device)?;
        let mut config = VulkanTransformerConfig::from_hf_value(&tiny_mixtral_config())?
            .moe
            .unwrap();
        config.num_experts = 2;
        config.top_k = 2;
        config.router_jitter_noise = 0.25;
        let linear = |weight: Vec<f32>| HostLinear { weight, bias: None };
        let expert0_gate = VulkanLinear::new_no_bias(&device, 2, 2, &[0.8, -0.2, 0.3, 0.7])?;
        let expert0_up = VulkanLinear::new_no_bias(&device, 2, 2, &[0.4, 0.2, -0.1, 0.6])?;
        let expert0_down = VulkanLinear::new_no_bias(&device, 2, 2, &[0.7, -0.3, 0.2, 0.5])?;
        let moe = VulkanMoe::new(
            &device,
            2,
            2,
            2,
            &config,
            1.0e-5,
            default_situ_beta(),
            None,
            HostMoeLayer {
                router: linear(vec![0.9, -0.4, -0.2, 0.6]),
                router_correction_bias: vec![0.0; 2],
                hash_router: None,
                expert_capacity: 0,
                owned_expert0: None,
                identity_expert_start: 2,
                experts: vec![HostMoeExpert {
                    gate: Some(linear(vec![-0.3, 0.8, 0.4, -0.2])),
                    up: linear(vec![0.5, -0.6, 0.2, 0.9]),
                    down: linear(vec![0.3, 0.6, -0.7, 0.2]),
                }],
                shared_expert: None,
                shared_expert_gate: None,
                latent: None,
            },
        )?;
        let values = [0.7_f32, -0.4, -0.3, 0.8];
        let input = GpuBuffer::from_f32(&device, &values)?;
        let output = GpuBuffer::zeros_f32(&device, 4)?;
        let grad_output_values = [0.6_f32, -0.2, 0.3, 0.9];
        let grad_output = GpuBuffer::from_f32(&device, &grad_output_values)?;
        let grad_input = GpuBuffer::zeros_f32(&device, 4)?;
        let site = TRANSFORMER_MLP_ACTIVATION_DROPOUT_SITE + 3;
        // Nonzero high counter bits exercise the Philox word-to-block carry.
        let step = 7;
        let seed = 193;
        let forward = |input: &GpuBuffer, training, rng_step| -> Result<Vec<f32>> {
            let mut commands = vulkan::ComputeBatch::new(&device)?;
            moe.record_forward(
                &mut commands,
                &kernels,
                "silu",
                input,
                None,
                Some(&expert0_gate),
                &expert0_up,
                &expert0_down,
                &output,
                2,
                2,
                2,
                0.0,
                site,
                2,
                training,
                rng_step,
                seed,
            )?;
            commands.submit()?;
            output.read_f32(4)
        };
        let trained = forward(&input, true, step)?;
        let jittered = moe.jittered_input.as_ref().unwrap().read_f32(4)?;
        for (index, (&value, &actual)) in values.iter().zip(&jittered).enumerate() {
            let word = hierarchos_canonical_philox_word(
                (u64::from(site ^ 0x9000_0000) << 32) | u64::from(seed),
                (u64::from(step) << 32) + index as u64,
            );
            let uniform = (word >> 8) as f32 / 16_777_216.0;
            let expected = value * (0.75 + 0.5 * uniform);
            assert!((actual - expected).abs() < 1.0e-7);
        }
        assert_eq!(
            input.read_f32(4)?,
            values,
            "normalization tape must survive jitter"
        );
        assert_eq!(
            trained,
            forward(&input, true, step)?,
            "replay must be deterministic"
        );
        assert_ne!(trained, forward(&input, true, step + 1)?);
        let eval = forward(&input, false, step)?;
        assert_eq!(eval, forward(&input, false, step + 1)?);
        assert_ne!(trained, eval);
        // Evaluation on the explicitly jittered input must equal training:
        // this catches applying noise only to routing or only to experts.
        let explicit = GpuBuffer::from_f32(&device, &jittered)?;
        let expected = forward(&explicit, false, step)?;
        for (&actual, &expected) in trained.iter().zip(&expected) {
            assert!((actual - expected).abs() < 1.0e-7);
        }
        forward(&input, true, step)?;
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        moe.record_backward(
            &mut commands,
            &kernels,
            "silu",
            &input,
            Some(&expert0_gate),
            &expert0_up,
            &expert0_down,
            &grad_output,
            &grad_input,
            2,
            2,
            2,
            0.0,
            site,
            step,
            seed,
        )?;
        commands.submit()?;
        let analytic = grad_input.read_f32(4)?;
        let epsilon = 0.001;
        for index in 0..values.len() {
            let mut plus = values;
            let mut minus = values;
            plus[index] += epsilon;
            minus[index] -= epsilon;
            let plus = forward(&GpuBuffer::from_f32(&device, &plus)?, true, step)?;
            let minus = forward(&GpuBuffer::from_f32(&device, &minus)?, true, step)?;
            let numerical: f32 = plus
                .iter()
                .zip(&minus)
                .zip(&grad_output_values)
                .map(|((&p, &m), &g)| (p - m) * g / (2.0 * epsilon))
                .sum();
            assert!(
                (analytic[index] - numerical).abs() < 2.0e-5,
                "jitter gradient {index}: analytic={} numerical={numerical}",
                analytic[index]
            );
        }
        Ok(())
    }

    #[test]
    fn kimi_linear_latent_moe_runs_situ_forward_and_backward_with_finite_difference() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let kernels = TransformerKernels::new(&device)?;
        let mut moe_config = VulkanTransformerConfig::from_hf_value(&tiny_kimi_linear_config())?
            .moe
            .context("tiny KimiLinear config is missing MoE metadata")?;
        moe_config.num_experts = 2;
        moe_config.top_k = 2;
        moe_config.shared_expert_intermediate_size = 0;
        moe_config.sparse_layer_mask.clear();

        let rows = 2usize;
        let hidden = 4usize;
        let routed_hidden = 2usize;
        let intermediate = 3usize;
        let linear = |weight: &[f32]| HostLinear {
            weight: weight.to_vec(),
            bias: None,
        };
        let expert0 = HostMoeExpert {
            gate: Some(linear(&[0.31, -0.22, 0.17, 0.28, -0.41, 0.36])),
            up: linear(&[-0.13, 0.27, 0.33, -0.19, 0.24, 0.11]),
            down: linear(&[0.21, -0.17, 0.08, 0.32, -0.29, 0.14]),
        };
        let expert1 = HostMoeExpert {
            gate: Some(linear(&[-0.26, 0.18, 0.39, 0.07, 0.16, -0.31])),
            up: linear(&[0.22, 0.09, -0.28, 0.34, 0.12, -0.25]),
            down: linear(&[-0.19, 0.27, 0.23, -0.11, 0.35, 0.06]),
        };
        let host = HostMoeLayer {
            router: linear(&[
                0.23, -0.31, 0.17, 0.09, -0.14, 0.26, 0.37, -0.21,
            ]),
            router_correction_bias: vec![0.07, -0.03],
            hash_router: None,
            expert_capacity: 0,
            owned_expert0: Some(expert0),
            identity_expert_start: 2,
            experts: vec![expert1],
            shared_expert: None,
            shared_expert_gate: None,
            latent: Some(HostMoeLatent {
                hidden_size: routed_hidden,
                down_proj: linear(&[
                    0.41, -0.16, 0.24, 0.08, -0.12, 0.35, -0.27, 0.19,
                ]),
                norm: Some(HostLayerNorm {
                    weight: vec![1.15, 0.85],
                    bias: Vec::new(),
                }),
                up_proj: linear(&[
                    0.29, -0.18, -0.11, 0.32, 0.25, 0.14, -0.21, 0.38,
                ]),
            }),
        };
        let moe = VulkanMoe::new(
            &device,
            rows,
            hidden,
            intermediate,
            &moe_config,
            1.0e-6,
            4.0,
            Some(25.0),
            host,
        )?;

        assert_eq!(moe.routed_hidden, routed_hidden);
        assert!(moe.latent_down_proj.is_some());
        assert!(moe.latent_norm.is_some());
        assert!(moe.latent_up_proj.is_some());

        let dummy_gate =
            VulkanLinear::new_no_bias(&device, routed_hidden, intermediate, &[0.0; 6])?;
        let dummy_up =
            VulkanLinear::new_no_bias(&device, routed_hidden, intermediate, &[0.0; 6])?;
        let dummy_down =
            VulkanLinear::new_no_bias(&device, intermediate, routed_hidden, &[0.0; 6])?;
        let input_values = [
            0.37_f32, -0.52, 0.18, 0.44, -0.21, 0.63, -0.35, 0.27,
        ];
        let grad_output_values = [0.41_f32, -0.23, 0.17, 0.36, -0.28, 0.19, 0.33, -0.14];
        let output = GpuBuffer::zeros_f32(&device, rows * hidden)?;
        let grad_output = GpuBuffer::from_f32(&device, &grad_output_values)?;
        let grad_input = GpuBuffer::zeros_f32(&device, rows * hidden)?;
        let site = TRANSFORMER_MLP_ACTIVATION_DROPOUT_SITE + 0x51;
        let step = 3u32;
        let seed = 0x4b49_4d49u32;

        let forward = |values: &[f32]| -> Result<Vec<f32>> {
            let input = GpuBuffer::from_f32(&device, values)?;
            let mut commands = vulkan::ComputeBatch::new(&device)?;
            moe.record_forward(
                &mut commands,
                &kernels,
                "situ",
                &input,
                None,
                Some(&dummy_gate),
                &dummy_up,
                &dummy_down,
                &output,
                rows,
                hidden,
                intermediate,
                0.0,
                site,
                2,
                true,
                step,
                seed,
            )?;
            commands.submit()?;
            output.read_f32(rows * hidden)
        };

        let actual_output = forward(&input_values)?;
        assert!(actual_output.iter().all(|value| value.is_finite()));
        assert!(actual_output.iter().any(|value| value.abs() > 1.0e-6));

        let input = GpuBuffer::from_f32(&device, &input_values)?;
        // Refresh the forward tape immediately before backward.
        let _ = forward(&input_values)?;
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        moe.record_backward(
            &mut commands,
            &kernels,
            "situ",
            &input,
            Some(&dummy_gate),
            &dummy_up,
            &dummy_down,
            &grad_output,
            &grad_input,
            rows,
            hidden,
            intermediate,
            0.0,
            site,
            step,
            seed,
        )?;
        commands.submit()?;
        let analytic = grad_input.read_f32(rows * hidden)?;
        assert!(analytic.iter().all(|value| value.is_finite()));
        assert!(analytic.iter().any(|value| value.abs() > 1.0e-6));

        let epsilon = 1.0e-3_f32;
        for index in 0..input_values.len() {
            let mut plus = input_values;
            let mut minus = input_values;
            plus[index] += epsilon;
            minus[index] -= epsilon;
            let plus_loss: f32 = forward(&plus)?
                .iter()
                .zip(&grad_output_values)
                .map(|(output, grad)| output * grad)
                .sum();
            let minus_loss: f32 = forward(&minus)?
                .iter()
                .zip(&grad_output_values)
                .map(|(output, grad)| output * grad)
                .sum();
            let numerical = (plus_loss - minus_loss) / (2.0 * epsilon);
            assert!(
                (analytic[index] - numerical).abs() <= 8.0e-3,
                "Kimi LatentMoE input gradient mismatch at {index}: analytic={} numerical={numerical}",
                analytic[index]
            );
        }
        Ok(())
    }

    #[test]
    fn kimi_linear_attn_res_matches_reference_and_finite_difference() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let kernels = TransformerKernels::new(&device)?;
        let rows = 2usize;
        let sources = 3usize;
        let hidden = 4usize;
        let eps = 1.0e-6_f32;
        let norm_weight = [1.13_f32, 0.87, 1.21, 0.94];
        let proj_weight = [0.31_f32, -0.27, 0.19, 0.42];
        let op = VulkanKimiAttnRes::new(
            &device,
            hidden,
            eps,
            HostKimiAttnRes {
                norm: HostLayerNorm {
                    weight: norm_weight.to_vec(),
                    bias: Vec::new(),
                },
                proj: HostLinear {
                    weight: proj_weight.to_vec(),
                    bias: None,
                },
            },
        )?;
        let workspace = VulkanKimiAttnResWorkspace::new(&device, rows, sources, hidden)?;
        let values = [
            0.37_f32, -0.52, 0.18, 0.44, -0.21, 0.63, -0.35, 0.27, 0.48, 0.11, -0.29, 0.56,
            -0.32, 0.24, 0.51, -0.17, 0.29, -0.46, 0.13, 0.62, 0.41, 0.07, -0.38, 0.22,
        ];
        let output = GpuBuffer::zeros_f32(&device, rows * hidden)?;
        let forward = |candidate_values: &[f32]| -> Result<Vec<f32>> {
            let candidates = GpuBuffer::from_f32(&device, candidate_values)?;
            let mut commands = vulkan::ComputeBatch::new(&device)?;
            op.record_forward(
                &mut commands,
                &kernels,
                &workspace,
                &candidates,
                &output,
                rows,
                sources,
            )?;
            commands.submit()?;
            output.read_f32(rows * hidden)
        };
        let actual = forward(&values)?;
        let mut expected = vec![0.0_f32; rows * hidden];
        for row in 0..rows {
            let mut scores = vec![0.0_f32; sources];
            for source in 0..sources {
                let base = (source * rows + row) * hidden;
                let variance = values[base..base + hidden]
                    .iter()
                    .map(|value| value * value)
                    .sum::<f32>()
                    / hidden as f32;
                let rstd = 1.0 / (variance + eps).sqrt();
                for col in 0..hidden {
                    scores[source] = (values[base + col] * rstd * norm_weight[col])
                        .mul_add(proj_weight[col], scores[source]);
                }
            }
            let maximum = scores.iter().copied().fold(f32::NEG_INFINITY, f32::max);
            let mut probs = scores
                .iter()
                .map(|score| (*score - maximum).exp())
                .collect::<Vec<_>>();
            let denominator: f32 = probs.iter().sum();
            for probability in &mut probs {
                *probability /= denominator;
            }
            for col in 0..hidden {
                for source in 0..sources {
                    let base = (source * rows + row) * hidden;
                    expected[row * hidden + col] =
                        probs[source].mul_add(values[base + col], expected[row * hidden + col]);
                }
            }
        }
        for (index, (&actual, &expected)) in actual.iter().zip(&expected).enumerate() {
            assert!(
                (actual - expected).abs() <= 5.0e-7,
                "Kimi AttnRes forward mismatch at {index}: actual={actual} expected={expected}"
            );
        }
        let probabilities = workspace.probabilities.read_f32(rows * sources)?;
        for row in 0..rows {
            let sum: f32 = (0..sources)
                .map(|source| probabilities[source * rows + row])
                .sum();
            assert!((sum - 1.0).abs() <= 2.0e-7);
        }

        let grad_output_values = [0.41_f32, -0.23, 0.17, 0.36, -0.28, 0.19, 0.33, -0.14];
        let candidates = GpuBuffer::from_f32(&device, &values)?;
        let grad_output = GpuBuffer::from_f32(&device, &grad_output_values)?;
        let grad_candidates = GpuBuffer::zeros_f32(&device, values.len())?;
        let _ = forward(&values)?;
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        op.record_backward(
            &mut commands,
            &kernels,
            &workspace,
            &candidates,
            &grad_output,
            &grad_candidates,
            rows,
            sources,
        )?;
        commands.submit()?;
        let analytic = grad_candidates.read_f32(values.len())?;
        let finite_difference_eps = 1.0e-3_f32;
        for index in 0..values.len() {
            let mut plus = values;
            let mut minus = values;
            plus[index] += finite_difference_eps;
            minus[index] -= finite_difference_eps;
            let plus_loss: f32 = forward(&plus)?
                .iter()
                .zip(&grad_output_values)
                .map(|(output, grad)| output * grad)
                .sum();
            let minus_loss: f32 = forward(&minus)?
                .iter()
                .zip(&grad_output_values)
                .map(|(output, grad)| output * grad)
                .sum();
            let numerical = (plus_loss - minus_loss) / (2.0 * finite_difference_eps);
            assert!(
                (analytic[index] - numerical).abs() <= 3.0e-4,
                "Kimi AttnRes input gradient mismatch at {index}: analytic={} numerical={numerical}",
                analytic[index]
            );
        }
        Ok(())
    }

    #[test]
    fn kimi_linear_attn_res_loader_reads_canonical_tensor_names() -> Result<()> {
        let mut value = tiny_kimi_linear_config();
        value["num_hidden_layers"] = serde_json::json!(2);
        value["linear_attn_config"]["kda_layers"] = serde_json::json!([1]);
        value["linear_attn_config"]["full_attn_layers"] = serde_json::json!([2]);
        value["attn_res_block_size"] = serde_json::json!(2);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-kimi-attn-res-loader-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

        let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
        tensors.push((
            "model.embed_tokens.weight".to_owned(),
            vec![config.vocab_size, d],
            vec![0.01; config.vocab_size * d],
        ));
        for layer in 0..config.num_layers {
            let p = format!("model.layers.{layer}");
            tensors.push((
                format!("{p}.self_attention_res_norm.weight"),
                vec![d],
                vec![1.0 + layer as f32 * 0.1; d],
            ));
            tensors.push((
                format!("{p}.self_attention_res_proj.weight"),
                vec![1, d],
                vec![0.2 + layer as f32 * 0.1; d],
            ));
            tensors.push((
                format!("{p}.mlp_res_norm.weight"),
                vec![d],
                vec![1.2 + layer as f32 * 0.1; d],
            ));
            tensors.push((
                format!("{p}.mlp_res_proj.weight"),
                vec![1, d],
                vec![0.4 + layer as f32 * 0.1; d],
            ));
        }
        tensors.push((
            "model.output_attn_res_norm.weight".to_owned(),
            vec![d],
            vec![1.4; d],
        ));
        tensors.push((
            "model.output_attn_res_proj.weight".to_owned(),
            vec![1, d],
            vec![0.6; d],
        ));
        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let stack = load_kimi_attn_res_stack(&test_dir, &config)?
            .context("Kimi AttnRes stack was not loaded")?;
        assert_eq!(stack.block_size, 2);
        assert_eq!(stack.layers.len(), 2);
        assert_eq!(stack.layers[0].self_attention.norm.weight[0], 1.0);
        assert_eq!(stack.layers[1].self_attention.proj.weight[0], 0.3);
        assert_eq!(stack.layers[0].mlp.norm.weight[0], 1.2);
        assert_eq!(stack.layers[1].mlp.proj.weight[0], 0.5);
        assert_eq!(stack.output.norm.weight[0], 1.4);
        assert_eq!(stack.output.proj.weight[0], 0.6);

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn kimi_linear_latent_moe_loader_reads_canonical_block_sparse_abi() -> Result<()> {
        let mut value = tiny_kimi_linear_config();
        value["num_hidden_layers"] = serde_json::json!(2);
        value["linear_attn_config"]["kda_layers"] = serde_json::json!([1]);
        value["linear_attn_config"]["full_attn_layers"] = serde_json::json!([2]);
        value["num_experts"] = serde_json::json!(2);
        value["num_experts_per_token"] = serde_json::json!(2);
        value["moe_intermediate_size"] = serde_json::json!(3);
        value["routed_expert_hidden_size"] = serde_json::json!(2);
        value["first_k_dense_replace"] = serde_json::json!(1);

        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let moe = config.moe.as_ref().context("tiny KimiLinear MoE config")?;
        assert_eq!(config.intermediate_size, 3);
        assert_eq!(moe.shared_expert_intermediate_size, 3);
        assert_eq!(moe.sparse_layer_mask, vec![false, true]);
        let d = config.hidden_size;
        let i = config.intermediate_size;
        let routed = 2usize;
        let shared_i = moe.shared_expert_intermediate_size;

        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-kimi-latent-moe-loader-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

        let p = "model.layers.1.block_sparse_moe";
        let mut owned: Vec<(String, Dtype, Vec<usize>, Vec<u8>)> = Vec::new();
        let mut push_f32 = |name: String, shape: Vec<usize>, values: Vec<f32>| {
            owned.push((name, Dtype::F32, shape, f32_le_bytes(&values)));
        };
        push_f32(
            format!("{p}.gate.weight"),
            vec![moe.num_experts, d],
            vec![0.11; moe.num_experts * d],
        );
        push_f32(
            format!("{p}.gate.e_score_correction_bias"),
            vec![moe.num_experts],
            vec![0.125, -0.25],
        );
        for expert in 0..moe.num_experts {
            let base = 0.2 + expert as f32 * 0.1;
            push_f32(
                format!("{p}.experts.{expert}.w1.weight"),
                vec![i, routed],
                vec![base + 0.01; i * routed],
            );
            push_f32(
                format!("{p}.experts.{expert}.w3.weight"),
                vec![i, routed],
                vec![base + 0.02; i * routed],
            );
            push_f32(
                format!("{p}.experts.{expert}.w2.weight"),
                vec![routed, i],
                vec![base + 0.03; routed * i],
            );
        }
        push_f32(
            format!("{p}.shared_experts.gate_proj.weight"),
            vec![shared_i, d],
            vec![0.51; shared_i * d],
        );
        push_f32(
            format!("{p}.shared_experts.up_proj.weight"),
            vec![shared_i, d],
            vec![0.52; shared_i * d],
        );
        push_f32(
            format!("{p}.shared_experts.down_proj.weight"),
            vec![d, shared_i],
            vec![0.53; d * shared_i],
        );
        push_f32(
            format!("{p}.routed_expert_down_proj.weight"),
            vec![routed, d],
            vec![0.71; routed * d],
        );
        push_f32(
            format!("{p}.routed_expert_norm.weight"),
            vec![routed],
            vec![1.1, 0.9],
        );
        push_f32(
            format!("{p}.routed_expert_up_proj.weight"),
            vec![d, routed],
            vec![0.81; d * routed],
        );
        drop(push_f32);

        let views = owned
            .iter()
            .map(|(name, dtype, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(*dtype, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let layers = load_mixtral_moe_layers(&test_dir, &config)?;
        assert_eq!(layers.len(), 1);
        let layer = &layers[0];
        assert_eq!(layer.router_correction_bias, vec![0.125, -0.25]);
        let expert0 = layer
            .owned_expert0
            .as_ref()
            .context("Kimi routed expert 0 must be owned by the MoE layer")?;
        assert!(expert0
            .gate
            .as_ref()
            .unwrap()
            .weight
            .iter()
            .all(|value| (*value - 0.21).abs() <= 1.0e-6));
        assert_eq!(layer.experts.len(), 1);
        assert!(layer.experts[0]
            .up
            .weight
            .iter()
            .all(|value| (*value - 0.32).abs() <= 1.0e-6));
        assert!(layer.shared_expert.is_some());
        let latent = layer
            .latent
            .as_ref()
            .context("Kimi Stable LatentMoE shell was not loaded")?;
        assert_eq!(latent.hidden_size, routed);
        assert_eq!(latent.down_proj.weight, vec![0.71; routed * d]);
        assert_eq!(latent.norm.as_ref().unwrap().weight, vec![1.1, 0.9]);
        assert_eq!(latent.up_proj.weight, vec![0.81; d * routed]);

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn moe_router_vulkan_matches_hf_scaled_softmax_forward_and_backward() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let kernels = TransformerKernels::new(&device)?;
        let rows = 1usize;
        let experts = 3usize;
        let routed_scaling_factor = 1.5_f32;

        let router_logits = GpuBuffer::from_f32(&device, &[0.0, 0.0, 0.0])?;
        let correction_bias = GpuBuffer::from_f32(&device, &[0.0, 0.0, 0.0])?;
        let routing_weights = GpuBuffer::zeros_f32(&device, rows * experts)?;
        let push = MoeRouterTopKPush {
            rows: rows as u32,
            experts: experts as u32,
            top_k: 2,
            normalize_top_k: 0,
            score_function: VulkanMoeRouterScoreFunction::Softmax as u32,
            group_count: 1,
            topk_group: 1,
            routed_scaling_factor,
            expert_capacity: 0,
            capacity_group_size: 1,
            router_logit_softcapping: 0.0,
        };
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        kernels.moe_router_topk.record_dispatch(
            &mut commands,
            &[&router_logits, &correction_bias, &routing_weights],
            bytemuck::bytes_of(&push),
            [1, 1, 1],
        )?;
        commands.submit()?;
        let actual = routing_weights.read_f32(rows * experts)?;
        let expected = [0.5_f32, 0.5, 0.0];
        for (index, (&actual, &expected)) in actual.iter().zip(&expected).enumerate() {
            assert!(
                (actual - expected).abs() <= 1.0e-6,
                "scaled full-softmax MoE routing mismatch at {index}: actual={actual} expected={expected}"
            );
        }

        let routing_weights = GpuBuffer::from_f32(&device, &[0.375, 1.125, 0.0])?;
        let grad_weights = GpuBuffer::from_f32(&device, &[2.0, -1.0, 5.0])?;
        let router_logits = GpuBuffer::from_f32(&device, &[0.0, 0.0, 0.0])?;
        let grad_logits = GpuBuffer::zeros_f32(&device, rows * experts)?;
        let push = MoeRouterBackwardPush {
            rows: rows as u32,
            experts: experts as u32,
            normalize_top_k: 1,
            score_function: VulkanMoeRouterScoreFunction::Softmax as u32,
            routed_scaling_factor,
            router_logit_softcapping: 0.0,
        };
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        kernels.moe_router_backward.record_dispatch(
            &mut commands,
            &[
                &routing_weights,
                &grad_weights,
                &router_logits,
                &grad_logits,
            ],
            bytemuck::bytes_of(&push),
            [1, 1, 1],
        )?;
        commands.submit()?;
        let actual = grad_logits.read_f32(rows * experts)?;
        let expected = [0.84375_f32, -0.84375, 0.0];
        for (index, (&actual, &expected)) in actual.iter().zip(&expected).enumerate() {
            assert!(
                (actual - expected).abs() <= 1.0e-6,
                "normalized MoE router gradient mismatch at {index}: actual={actual} expected={expected}"
            );
        }

        let routing_weights = GpuBuffer::from_f32(&device, &[0.5, 0.5, 0.0])?;
        let grad_weights = GpuBuffer::from_f32(&device, &[2.0, -1.0, 5.0])?;
        let router_logits = GpuBuffer::from_f32(&device, &[0.0, 0.0, 0.0])?;
        let grad_logits = GpuBuffer::zeros_f32(&device, rows * experts)?;
        let push = MoeRouterBackwardPush {
            rows: rows as u32,
            experts: experts as u32,
            normalize_top_k: 0,
            score_function: VulkanMoeRouterScoreFunction::Softmax as u32,
            routed_scaling_factor,
            router_logit_softcapping: 0.0,
        };
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        kernels.moe_router_backward.record_dispatch(
            &mut commands,
            &[
                &routing_weights,
                &grad_weights,
                &router_logits,
                &grad_logits,
            ],
            bytemuck::bytes_of(&push),
            [1, 1, 1],
        )?;
        commands.submit()?;
        let actual = grad_logits.read_f32(rows * experts)?;
        let expected = [5.0_f32 / 6.0, -2.0 / 3.0, -1.0 / 6.0];
        for (index, (&actual, &expected)) in actual.iter().zip(&expected).enumerate() {
            assert!(
                (actual - expected).abs() <= 2.0e-6,
                "full-softmax MoE router gradient mismatch at {index}: actual={actual} expected={expected}"
            );
        }
        Ok(())
    }

    #[test]
    fn moe_router_vulkan_matches_laguna_softcapped_sigmoid_forward_and_backward() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let kernels = TransformerKernels::new(&device)?;
        let logits = [-3.0_f32, 0.5, 4.0];
        let correction = [0.9_f32, 0.0, -0.1];
        let cap = 1.5_f32;
        let routed_scaling_factor = 1.25_f32;
        let score = |value: f32| {
            let capped = (value / cap).tanh() * cap;
            1.0 / (1.0 + (-capped).exp())
        };
        let scores = [score(logits[0]), score(logits[1]), score(logits[2])];
        let selected_sum = scores[0] + scores[2];
        let expected_weights = [
            routed_scaling_factor * scores[0] / selected_sum,
            0.0,
            routed_scaling_factor * scores[2] / selected_sum,
        ];

        let router_logits = GpuBuffer::from_f32(&device, &logits)?;
        let correction_bias = GpuBuffer::from_f32(&device, &correction)?;
        let routing_weights = GpuBuffer::zeros_f32(&device, 3)?;
        let push = MoeRouterTopKPush {
            rows: 1,
            experts: 3,
            top_k: 2,
            normalize_top_k: 1,
            score_function: VulkanMoeRouterScoreFunction::SigmoidGrouped as u32,
            group_count: 1,
            topk_group: 1,
            routed_scaling_factor,
            expert_capacity: 0,
            capacity_group_size: 1,
            router_logit_softcapping: cap,
        };
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        kernels.moe_router_topk.record_dispatch(
            &mut commands,
            &[&router_logits, &correction_bias, &routing_weights],
            bytemuck::bytes_of(&push),
            [1, 1, 1],
        )?;
        commands.submit()?;
        let actual_weights = routing_weights.read_f32(3)?;
        for (index, (&actual, &expected)) in
            actual_weights.iter().zip(&expected_weights).enumerate()
        {
            assert!(
                (actual - expected).abs() <= 2.0e-6,
                "Laguna softcapped sigmoid routing mismatch at {index}: actual={actual} expected={expected}"
            );
        }

        let grad_values = [0.7_f32, -1.1, 1.8];
        let grad_weights = GpuBuffer::from_f32(&device, &grad_values)?;
        let grad_logits = GpuBuffer::zeros_f32(&device, 3)?;
        let backward_push = MoeRouterBackwardPush {
            rows: 1,
            experts: 3,
            normalize_top_k: 1,
            score_function: VulkanMoeRouterScoreFunction::SigmoidGrouped as u32,
            routed_scaling_factor,
            router_logit_softcapping: cap,
        };
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        kernels.moe_router_backward.record_dispatch(
            &mut commands,
            &[
                &routing_weights,
                &grad_weights,
                &router_logits,
                &grad_logits,
            ],
            bytemuck::bytes_of(&backward_push),
            [1, 1, 1],
        )?;
        commands.submit()?;
        let actual_grad = grad_logits.read_f32(3)?;
        let weighted_grad = (expected_weights[0] / routed_scaling_factor) * grad_values[0]
            + (expected_weights[2] / routed_scaling_factor) * grad_values[2];
        let mut expected_grad = [0.0_f32; 3];
        for index in [0usize, 2usize] {
            let tanh_value = (logits[index] / cap).tanh();
            let grad_score =
                routed_scaling_factor * (grad_values[index] - weighted_grad) / selected_sum;
            expected_grad[index] = grad_score
                * scores[index]
                * (1.0 - scores[index])
                * (1.0 - tanh_value * tanh_value);
        }
        for (index, (&actual, &expected)) in actual_grad.iter().zip(&expected_grad).enumerate() {
            assert!(
                (actual - expected).abs() <= 3.0e-6,
                "Laguna softcapped sigmoid router gradient mismatch at {index}: actual={actual} expected={expected}"
            );
        }
        Ok(())
    }

    #[test]
    fn qwen_gated_delta_depthwise_causal_conv_matches_reference() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let kernels = TransformerKernels::new(&device)?;
        let batch_size = 1usize;
        let seq_len = 4usize;
        let channels = 2usize;
        let kernel_size = 3usize;
        let input = [0.25_f32, -0.5, 0.75, 0.125, -0.25, 1.0, 0.5, -0.75];
        let weights = [0.2_f32, -0.3, 0.7, -0.4, 0.5, 0.25];
        let mut expected = vec![0.0_f32; input.len()];
        for token in 0..seq_len {
            for channel in 0..channels {
                let mut sum = 0.0_f32;
                for tap in 0..kernel_size {
                    let source = token as isize + tap as isize - (kernel_size as isize - 1);
                    if source >= 0 {
                        sum += input[source as usize * channels + channel]
                            * weights[channel * kernel_size + tap];
                    }
                }
                expected[token * channels + channel] = sum / (1.0 + (-sum).exp());
            }
        }

        let input_gpu = GpuBuffer::from_f32(&device, &input)?;
        let weight_gpu = GpuBuffer::from_f32(&device, &weights)?;
        let output_gpu = GpuBuffer::zeros_f32(&device, input.len())?;
        let push = DepthwiseCausalConv1dPush {
            batch_size: batch_size as u32,
            seq_len: seq_len as u32,
            channels: channels as u32,
            kernel_size: kernel_size as u32,
            dilation: 1,
            activation: 1,
        };
        let mut commands = vulkan::ComputeBatch::new(&device)?;
        kernels.depthwise_causal_conv1d.record_dispatch(
            &mut commands,
            &[&input_gpu, &weight_gpu, &output_gpu],
            bytemuck::bytes_of(&push),
            [div_ceil_u32(input.len(), 256), 1, 1],
        )?;
        commands.submit()?;
        let actual = output_gpu.read_f32(input.len())?;
        for (index, (&actual, &expected)) in actual.iter().zip(&expected).enumerate() {
            assert!(
                (actual - expected).abs() <= 2.0e-6,
                "Qwen depthwise causal conv mismatch at {index}: actual={actual} expected={expected}"
            );
        }
        Ok(())
    }

