    #[test]
    fn tensor_store_row_gather_reads_only_requested_rows_in_requested_order() -> Result<()> {
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-row-gather-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        let tensor_name = "model.layers.0.ple.ple_embedding.ngram_embedding.weight";
        let values = (0..15).map(|value| value as f32 + 0.25).collect::<Vec<_>>();
        let bytes = f32_le_bytes(&values);
        let views = vec![(
            tensor_name,
            TensorView::new(Dtype::F32, vec![5, 3], &bytes)?,
        )];
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let mut store = Gpt2TensorStore::load(&test_dir)?;
        let source = store.take_expected_source(tensor_name, &[5, 3])?;
        assert_eq!(source.shape, vec![5, 3]);
        assert_eq!(source.byte_len, values.len() * std::mem::size_of::<f32>());
        let gathered = decode_transformer_float_source_rows(tensor_name, &source, &[4, 1, 4, 0])?;
        assert_eq!(
            gathered,
            vec![12.25, 13.25, 14.25, 3.25, 4.25, 5.25, 12.25, 13.25, 14.25, 0.25, 1.25, 2.25,]
        );
        let error = decode_transformer_float_source_rows(tensor_name, &source, &[5])
            .expect_err("out-of-range row gather should fail");
        assert!(error.to_string().contains("exceeds row count 5"));
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

