    #[test]
    fn gpt_oss_contract_matches_current_hf_attention_moe_and_yarn_defaults() {
        let config =
            VulkanTransformerConfig::from_hf_value(&tiny_gpt_oss_config()).expect("GPT-OSS config");
        assert_eq!(config.architecture, VulkanTransformerArchitecture::GptOss);
        assert_eq!(config.architecture.model_type(), "gpt_oss");
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 2);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.rotary_dim, 4);
        assert_eq!(config.rotary_emb_base, 150_000.0);
        assert_eq!(config.attention_windows, vec![4, 0]);
        assert_eq!(config.activation_function, "gpt_oss_swiglu");
        assert_eq!(config.layer_norm_eps, 1.0e-5);
        assert!(!config.tie_word_embeddings);
        assert_eq!(
            config.rope_scaling.scaling_type,
            VulkanRopeScalingType::Yarn
        );
        assert_eq!(config.rope_scaling.factor, 2.0);
        assert_eq!(config.rope_scaling.original_max_position_embeddings, 8);
        assert_eq!(config.rope_scaling.beta_fast, 32.0);
        assert_eq!(config.rope_scaling.beta_slow, 1.0);
        assert!(!config.rope_scaling.truncate);
        assert!(config.architecture.uses_llama_layout());
        assert!(config.architecture.uses_rms_norm());
        assert!(config.architecture.uses_gated_mlp());
        assert!(config.architecture.supports_grouped_query_attention());
        assert!(config.architecture.uses_configurable_attention_bias());
        assert!(config
            .architecture
            .uses_configurable_attention_output_bias());
        let moe = config.moe.as_ref().expect("GPT-OSS MoE config");
        assert_eq!(moe.num_experts, 3);
        assert_eq!(moe.top_k, 2);
        assert!(moe.normalize_top_k);
        assert_eq!(moe.router_aux_loss_coef, 0.001);

        let mut explicit_layers = tiny_gpt_oss_config();
        explicit_layers["layer_types"] = serde_json::json!(["full_attention", "sliding_attention"]);
        let explicit = VulkanTransformerConfig::from_hf_value(&explicit_layers)
            .expect("GPT-OSS explicit layer types");
        assert_eq!(explicit.attention_windows, vec![0, 4]);

        let mut invalid = tiny_gpt_oss_config();
        invalid["sliding_window"] = serde_json::Value::Null;
        invalid["layer_types"] = serde_json::json!(["sliding_attention", "full_attention"]);
        let error = VulkanTransformerConfig::from_hf_value(&invalid)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("requests sliding attention"),
            "unexpected error: {error}"
        );
    }

    #[test]
    fn gpt_oss_packed_expert_gate_up_layout_round_trips_hf_interleaving() -> Result<()> {
        let hidden_size = 4usize;
        let intermediate_size = 3usize;
        let gate = (0..hidden_size * intermediate_size)
            .map(|index| 10.0 + index as f32)
            .collect::<Vec<_>>();
        let up = (0..hidden_size * intermediate_size)
            .map(|index| 100.0 + index as f32)
            .collect::<Vec<_>>();
        let gate_bias = vec![1.0, 2.0, 3.0];
        let up_bias = vec![11.0, 12.0, 13.0];

        let packed = gpt_oss_interleave_gate_up(&gate, &up, hidden_size, intermediate_size)?;
        for input in 0..hidden_size {
            for output in 0..intermediate_size {
                let packed_base = input * 2 * intermediate_size + 2 * output;
                let linear_index = output * hidden_size + input;
                assert_eq!(packed[packed_base], gate[linear_index]);
                assert_eq!(packed[packed_base + 1], up[linear_index]);
            }
        }
        let (restored_gate, restored_up) =
            gpt_oss_deinterleave_gate_up(&packed, hidden_size, intermediate_size)?;
        assert_eq!(restored_gate, gate);
        assert_eq!(restored_up, up);

        let packed_bias = gpt_oss_interleave_gate_up_bias(&gate_bias, &up_bias, intermediate_size)?;
        assert_eq!(packed_bias, vec![1.0, 11.0, 2.0, 12.0, 3.0, 13.0]);
        let (restored_gate_bias, restored_up_bias) =
            gpt_oss_deinterleave_gate_up_bias(&packed_bias, intermediate_size)?;
        assert_eq!(restored_gate_bias, gate_bias);
        assert_eq!(restored_up_bias, up_bias);
        Ok(())
    }

