    #[test]
    fn afmoe_loaders_preserve_hf_router_expert_bias_packed_experts_shared_experts_and_attention_gate(
    ) -> Result<()> {
        let mut value = tiny_afmoe_config();
        value["num_hidden_layers"] = serde_json::json!(1);
        value["num_dense_layers"] = serde_json::json!(0);
        value["layer_types"] = serde_json::json!(["sliding_attention"]);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let q = config.query_hidden_size();
        let i = config.intermediate_size;
        let moe_config = config.moe.as_ref().context("missing AFMoE config")?;
        let experts = moe_config.num_experts;
        let shared_i = moe_config.shared_expert_intermediate_size;
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-afmoe-loader-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;

        let router = (0..experts * d)
            .map(|index| 0.01 * index as f32)
            .collect::<Vec<_>>();
        let expert_bias = (0..experts)
            .map(|index| -0.2 + 0.1 * index as f32)
            .collect::<Vec<_>>();
        let attention_gate = (0..q * d)
            .map(|index| 0.5 + 0.001 * index as f32)
            .collect::<Vec<_>>();
        let mut gate_up = Vec::with_capacity(experts * 2 * i * d);
        let mut down = Vec::with_capacity(experts * d * i);
        for expert in 0..experts {
            gate_up.extend(vec![310.0 + expert as f32; i * d]);
            gate_up.extend(vec![320.0 + expert as f32; i * d]);
            down.extend(vec![330.0 + expert as f32; d * i]);
        }
        let tensors = [
            (
                "model.layers.0.mlp.router.gate.weight".to_owned(),
                vec![experts, d],
                router.clone(),
            ),
            (
                "model.layers.0.mlp.expert_bias".to_owned(),
                vec![experts],
                expert_bias.clone(),
            ),
            (
                "model.layers.0.mlp.experts.gate_up_proj".to_owned(),
                vec![experts, 2 * i, d],
                gate_up,
            ),
            (
                "model.layers.0.mlp.experts.down_proj".to_owned(),
                vec![experts, d, i],
                down,
            ),
            (
                "model.layers.0.mlp.shared_experts.gate_proj.weight".to_owned(),
                vec![shared_i, d],
                vec![340.0; shared_i * d],
            ),
            (
                "model.layers.0.mlp.shared_experts.up_proj.weight".to_owned(),
                vec![shared_i, d],
                vec![350.0; shared_i * d],
            ),
            (
                "model.layers.0.mlp.shared_experts.down_proj.weight".to_owned(),
                vec![d, shared_i],
                vec![360.0; d * shared_i],
            ),
            (
                "model.layers.0.self_attn.gate_proj.weight".to_owned(),
                vec![q, d],
                attention_gate.clone(),
            ),
        ];
        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let layers = load_mixtral_moe_layers(&test_dir, &config)?;
        assert_eq!(layers.len(), 1);
        assert_eq!(layers[0].router.weight, router);
        assert_eq!(layers[0].router_correction_bias, expert_bias);
        assert_eq!(layers[0].experts.len(), experts - 1);
        for (stored_index, expert) in layers[0].experts.iter().enumerate() {
            let hf_index = stored_index + 1;
            assert_eq!(
                expert.gate.as_ref().expect("gated expert").weight[0],
                310.0 + hf_index as f32
            );
            assert_eq!(expert.up.weight[0], 320.0 + hf_index as f32);
            assert_eq!(expert.down.weight[0], 330.0 + hf_index as f32);
        }
        let shared = layers[0]
            .shared_expert
            .as_ref()
            .context("AFMoE shared experts were not loaded")?;
        assert_eq!(
            shared.gate.as_ref().expect("gated shared expert").weight[0],
            340.0
        );
        assert_eq!(shared.up.weight[0], 350.0);
        assert_eq!(shared.down.weight[0], 360.0);
        assert!(layers[0].shared_expert_gate.is_none());

        let gates = load_afmoe_attention_gates(&test_dir, &config)?;
        assert_eq!(gates.len(), 1);
        assert_eq!(gates[0].weight, attention_gate);
        assert!(gates[0].bias.is_none());

        fs::remove_dir_all(test_dir)?;
        Ok(())
    }

