    #[test]
    fn solar_open_loader_preserves_packed_experts_correction_bias_and_shared_expert() -> Result<()>
    {
        let mut value = tiny_solar_open_config();
        value["num_hidden_layers"] = serde_json::json!(1);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let i = config.intermediate_size;
        let moe_config = config
            .moe
            .as_ref()
            .context("missing Solar Open MoE config")?;
        let experts = moe_config.num_experts;
        let shared_i = moe_config.shared_expert_intermediate_size;
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-solar-open-loader-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(
            test_dir.join("config.json"),
            serde_json::to_vec_pretty(&value)?,
        )?;

        let router = (0..experts * d)
            .map(|index| 0.007 * index as f32)
            .collect::<Vec<_>>();
        let correction_bias = (0..experts)
            .map(|index| -0.25 + 0.125 * index as f32)
            .collect::<Vec<_>>();
        let mut gate_up = Vec::with_capacity(experts * 2 * i * d);
        let mut down = Vec::with_capacity(experts * d * i);
        for expert in 0..experts {
            gate_up.extend(vec![210.0 + expert as f32; i * d]);
            gate_up.extend(vec![220.0 + expert as f32; i * d]);
            down.extend(vec![230.0 + expert as f32; d * i]);
        }
        let tensors = [
            (
                "model.layers.0.mlp.gate.weight".to_owned(),
                vec![experts, d],
                router.clone(),
            ),
            (
                "model.layers.0.mlp.gate.e_score_correction_bias".to_owned(),
                vec![experts],
                correction_bias.clone(),
            ),
            (
                "model.layers.0.mlp.experts.gate_up_proj".to_owned(),
                vec![experts, 2 * i, d],
                gate_up,
            ),
            (
                "model.layers.0.mlp.experts.down_proj".to_owned(),
                vec![experts, d, i],
                down,
            ),
            (
                "model.layers.0.mlp.shared_experts.gate_proj.weight".to_owned(),
                vec![shared_i, d],
                vec![240.0; shared_i * d],
            ),
            (
                "model.layers.0.mlp.shared_experts.up_proj.weight".to_owned(),
                vec![shared_i, d],
                vec![250.0; shared_i * d],
            ),
            (
                "model.layers.0.mlp.shared_experts.down_proj.weight".to_owned(),
                vec![d, shared_i],
                vec![260.0; d * shared_i],
            ),
        ];
        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let layers = load_mixtral_moe_layers(&test_dir, &config)?;
        assert_eq!(layers.len(), 1);
        assert_eq!(layers[0].router.weight, router);
        assert_eq!(layers[0].router_correction_bias, correction_bias);
        assert_eq!(layers[0].experts.len(), experts - 1);
        assert_eq!(
            layers[0].experts[0]
                .gate
                .as_ref()
                .expect("gated expert")
                .weight[0],
            211.0
        );
        assert_eq!(layers[0].experts[0].up.weight[0], 221.0);
        assert_eq!(layers[0].experts[0].down.weight[0], 231.0);
        let shared = layers[0]
            .shared_expert
            .as_ref()
            .context("Solar Open shared expert was not loaded")?;
        assert_eq!(
            shared.gate.as_ref().expect("gated shared expert").weight[0],
            240.0
        );
        assert_eq!(shared.up.weight[0], 250.0);
        assert_eq!(shared.down.weight[0], 260.0);
        assert!(layers[0].shared_expert_gate.is_none());
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn solar_open_checkpoint_export_round_trips_grouped_moe_and_shared_experts() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_solar_open_vulkan_graph(device.clone())?;
        let expected = graph.hf_parameter_tensors()?;
        for name in [
            "model.layers.0.self_attn.q_proj.weight",
            "model.layers.0.self_attn.k_proj.weight",
            "model.layers.0.self_attn.v_proj.weight",
            "model.layers.0.self_attn.o_proj.weight",
            "model.layers.0.mlp.gate.weight",
            "model.layers.0.mlp.gate.e_score_correction_bias",
            "model.layers.0.mlp.experts.gate_up_proj",
            "model.layers.0.mlp.experts.down_proj",
            "model.layers.0.mlp.shared_experts.gate_proj.weight",
            "model.layers.0.mlp.shared_experts.up_proj.weight",
            "model.layers.0.mlp.shared_experts.down_proj.weight",
        ] {
            assert!(
                expected.contains_key(name),
                "Solar Open export map is missing {name}"
            );
        }

        let root = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-solar-open-export-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        let source_dir = root.join("source");
        let output_dir = root.join("output");
        fs::create_dir_all(&source_dir)?;
        fs::write(
            source_dir.join("config.json"),
            serde_json::to_vec_pretty(&tiny_solar_open_config())?,
        )?;

        graph.export_hf_package(&source_dir, &output_dir)?;
        let exported = Gpt2TensorStore::load(&output_dir)?.into_parameter_tensors()?;
        assert_eq!(exported, expected, "Solar Open exported tensors changed");

        let moe = load_mixtral_moe_layers(&output_dir, &graph.config)?;
        assert_eq!(moe.len(), graph.config.num_layers);
        assert_eq!(moe[0].router_correction_bias[0], 0.01);
        let shared = moe[0]
            .shared_expert
            .as_ref()
            .context("reloaded Solar Open package lost its shared experts")?;
        assert_eq!(
            shared
                .gate
                .as_ref()
                .context("reloaded Solar Open shared expert lost gate_proj")?
                .weight[0],
            0.22
        );
        assert_eq!(shared.up.weight[0], 0.23);
        assert!((shared.down.weight[0] - 0.24).abs() <= f32::EPSILON);

        let reloaded = VulkanTransformer::from_hf_package(device, &output_dir, 1, 8)?;
        assert_eq!(
            reloaded.hf_parameter_tensors()?,
            expected,
            "Solar Open full graph reload did not preserve the exported checkpoint"
        );
        fs::remove_dir_all(&root)?;
        Ok(())
    }

    #[test]
    fn solar_open_generation_kv_cache_matches_full_prefix_logits() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_solar_open_vulkan_graph(device)?;
        assert!(
            graph.supports_generation_kv_cache(),
            "Solar Open should use the native generation KV cache"
        );

        let prompt = [2_u32, 9, 4];
        let (prefill_logits, cache) = graph.generation_prefill_kv_cache(&prompt)?;
        let reference_prefill = graph.generation_last_logits(&prompt, None, None)?;
        for (index, (&cached, &reference)) in prefill_logits
            .iter()
            .zip(reference_prefill.iter())
            .enumerate()
        {
            assert!(
                (cached - reference).abs() <= 2.0e-5,
                "Solar Open prefill logit mismatch at vocab {index}: cached={cached} reference={reference}"
            );
        }

        let continuation = [6_u32, 12, 18];
        let mut prefix = prompt.to_vec();
        for &token in &continuation {
            let position = prefix.len();
            let cached = graph.generation_cached_step_logits(token, &cache, position)?;
            prefix.push(token);
            let reference = graph.generation_last_logits(&prefix, None, None)?;
            for (index, (&cached, &reference)) in cached.iter().zip(reference.iter()).enumerate() {
                assert!(
                    (cached - reference).abs() <= 4.0e-5,
                    "Solar Open cached logit mismatch at position {position}, vocab {index}: cached={cached} reference={reference}"
                );
            }
        }
        Ok(())
    }

