    #[test]
    fn qwen3_moe_contract_maps_standard_sparse_topology_and_router_semantics() {
        let config = VulkanTransformerConfig::from_hf_value(&tiny_qwen3_moe_config())
            .expect("Qwen3-MoE config");
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Qwen3Moe);
        assert_eq!(config.architecture.model_type(), "qwen3_moe");
        assert_eq!(config.hidden_size, 16);
        assert_eq!(config.intermediate_size, 24);
        assert_eq!(config.num_heads, 4);
        assert_eq!(config.num_key_value_heads, 2);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.rotary_dim, 4);
        assert_eq!(config.rotary_emb_base, 1_000_000.0);
        assert_eq!(config.attention_windows, vec![0, 0]);
        assert_eq!(config.activation_function, "silu");
        assert!(config.architecture.uses_llama_layout());
        assert!(config.architecture.uses_split_qkv());
        assert!(config.architecture.uses_rms_norm());
        assert!(config.architecture.uses_rms_qk_norm());
        assert!(config.architecture.uses_gated_mlp());
        assert!(config.architecture.supports_grouped_query_attention());
        let moe = config.moe.as_ref().expect("Qwen3-MoE routing config");
        assert_eq!(moe.num_experts, 3);
        assert_eq!(moe.top_k, 2);
        assert_eq!(moe.sparse_layer_mask, vec![true, true]);
        assert_eq!(moe.dense_intermediate_size, 40);
        assert!(!moe.normalize_top_k);
        assert_eq!(moe.router_aux_loss_coef, 0.001);

        let mut normalized = tiny_qwen3_moe_config();
        normalized["norm_topk_prob"] = serde_json::json!(true);
        let normalized = VulkanTransformerConfig::from_hf_value(&normalized)
            .expect("Qwen3-MoE normalized router config");
        assert!(normalized.moe.as_ref().unwrap().normalize_top_k);

        let mut hybrid = tiny_qwen3_moe_config();
        hybrid["decoder_sparse_step"] = serde_json::json!(2);
        let hybrid = VulkanTransformerConfig::from_hf_value(&hybrid)
            .expect("Qwen3-MoE alternating dense/sparse config");
        assert_eq!(
            hybrid.moe.as_ref().unwrap().sparse_layer_mask,
            vec![false, true]
        );
        assert_eq!(hybrid.layer_intermediate_size(0), 40);
        assert_eq!(hybrid.layer_intermediate_size(1), 24);

        let mut explicit_dense = tiny_qwen3_moe_config();
        explicit_dense["mlp_only_layers"] = serde_json::json!([0]);
        let explicit_dense = VulkanTransformerConfig::from_hf_value(&explicit_dense)
            .expect("Qwen3-MoE mlp_only_layers config");
        assert_eq!(
            explicit_dense.moe.as_ref().unwrap().sparse_layer_mask,
            vec![false, true]
        );

        let mut invalid_step = tiny_qwen3_moe_config();
        invalid_step["decoder_sparse_step"] = serde_json::json!(0);
        let error = VulkanTransformerConfig::from_hf_value(&invalid_step)
            .unwrap_err()
            .to_string();
        assert!(error.contains("decoder_sparse_step must be positive"));
    }

