    #[test]
    fn olmo_hybrid_loader_reads_independent_gated_delta_projections_and_beta_range() -> Result<()> {
        let mut value = tiny_olmo_hybrid_config();
        value["num_hidden_layers"] = serde_json::json!(2);
        value["layer_types"] = serde_json::json!(["linear_attention", "full_attention"]);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let key_heads = 2usize;
        let value_heads = 2usize;
        let key_head_dim = 4usize;
        let value_head_dim = 8usize;
        let key_dim = key_heads * key_head_dim;
        let value_dim = value_heads * value_head_dim;
        let conv_dim = 2 * key_dim + value_dim;
        let kernel = 4usize;

        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-olmo-hybrid-loader-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

        let tensors = vec![
            (
                "model.embed_tokens.weight".to_owned(),
                vec![config.vocab_size, d],
                vec![0.0; config.vocab_size * d],
            ),
            (
                "model.layers.0.linear_attn.q_proj.weight".to_owned(),
                vec![key_dim, d],
                vec![1.0; key_dim * d],
            ),
            (
                "model.layers.0.linear_attn.k_proj.weight".to_owned(),
                vec![key_dim, d],
                vec![2.0; key_dim * d],
            ),
            (
                "model.layers.0.linear_attn.v_proj.weight".to_owned(),
                vec![value_dim, d],
                vec![3.0; value_dim * d],
            ),
            (
                "model.layers.0.linear_attn.g_proj.weight".to_owned(),
                vec![value_dim, d],
                vec![4.0; value_dim * d],
            ),
            (
                "model.layers.0.linear_attn.b_proj.weight".to_owned(),
                vec![value_heads, d],
                vec![5.0; value_heads * d],
            ),
            (
                "model.layers.0.linear_attn.a_proj.weight".to_owned(),
                vec![value_heads, d],
                vec![6.0; value_heads * d],
            ),
            (
                "model.layers.0.linear_attn.conv1d.weight".to_owned(),
                vec![conv_dim, 1, kernel],
                vec![7.0; conv_dim * kernel],
            ),
            (
                "model.layers.0.linear_attn.dt_bias".to_owned(),
                vec![value_heads],
                vec![8.0; value_heads],
            ),
            (
                "model.layers.0.linear_attn.A_log".to_owned(),
                vec![value_heads],
                vec![9.0; value_heads],
            ),
            (
                "model.layers.0.linear_attn.o_norm.weight".to_owned(),
                vec![value_head_dim],
                vec![10.0; value_head_dim],
            ),
        ];
        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let layers = load_qwen_hybrid_gated_delta_nets(&test_dir, &config)?
            .context("missing OLMo Hybrid Gated DeltaNet layers")?;
        assert_eq!(layers.len(), 2);
        assert!(layers[1].is_none());
        let gdn = layers[0]
            .as_ref()
            .context("missing linear-attention layer")?;
        assert_eq!(gdn.conv_kernel_size, kernel);
        assert_eq!(gdn.num_key_heads, key_heads);
        assert_eq!(gdn.num_value_heads, value_heads);
        assert_eq!(gdn.key_head_dim, key_head_dim);
        assert_eq!(gdn.value_head_dim, value_head_dim);
        assert_eq!(gdn.beta_scale, 2.0);
        assert_eq!(gdn.norm_epsilon, 1.0e-5);
        assert_eq!(gdn.conv_weight[0], 7.0);
        assert_eq!(gdn.dt_bias[0], 8.0);
        assert_eq!(gdn.a_log[0], 9.0);
        assert_eq!(gdn.norm_weight[0], 10.0);
        match &gdn.projection {
            HostQwenGatedDeltaProjection::OlmoHybrid { q, k, v, z, b, a } => {
                assert_eq!(q.weight[0], 1.0);
                assert_eq!(k.weight[0], 2.0);
                assert_eq!(v.weight[0], 3.0);
                assert_eq!(z.weight[0], 4.0);
                assert_eq!(b.weight[0], 5.0);
                assert_eq!(a.weight[0], 6.0);
            }
            _ => panic!("OLMo Hybrid loader used the wrong Gated DeltaNet projection ABI"),
        }

        value["linear_allow_neg_eigval"] = serde_json::json!(false);
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;
        let no_negative = load_qwen_hybrid_gated_delta_nets(&test_dir, &config)?
            .context("missing OLMo Hybrid Gated DeltaNet layers")?;
        assert_eq!(
            no_negative[0]
                .as_ref()
                .context("missing linear-attention layer")?
                .beta_scale,
            1.0
        );

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

