    #[test]
    fn minimax_m2_loader_reads_full_qk_norms_packed_experts_and_correction_bias() -> Result<()> {
        let mut value = tiny_minimax_m2_config();
        value["num_hidden_layers"] = serde_json::json!(1);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let i = config.intermediate_size;
        let q = config.query_hidden_size();
        let kv = config.key_value_hidden_size();
        let experts = config
            .moe
            .as_ref()
            .context("missing MiniMaxM2 config")?
            .num_experts;
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-minimax-m2-loader-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

        let router = (0..experts * d)
            .map(|index| 0.006 * index as f32)
            .collect::<Vec<_>>();
        let correction_bias = (0..experts)
            .map(|index| 0.01 * index as f32)
            .collect::<Vec<_>>();
        let mut gate_up = Vec::with_capacity(experts * 2 * i * d);
        let mut down = Vec::with_capacity(experts * d * i);
        for expert in 0..experts {
            gate_up.extend(vec![130.0 + expert as f32; i * d]);
            gate_up.extend(vec![140.0 + expert as f32; i * d]);
            down.extend(vec![150.0 + expert as f32; d * i]);
        }

        let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
        let mut add = |name: &str, shape: Vec<usize>, fill: f32| {
            let len = shape.iter().product();
            tensors.push((name.to_owned(), shape, vec![fill; len]));
        };
        add(
            "model.embed_tokens.weight",
            vec![config.vocab_size, d],
            0.01,
        );
        add("model.layers.0.input_layernorm.weight", vec![d], 1.0);
        add("model.layers.0.self_attn.q_proj.weight", vec![q, d], 0.02);
        add("model.layers.0.self_attn.k_proj.weight", vec![kv, d], 0.03);
        add("model.layers.0.self_attn.v_proj.weight", vec![kv, d], 0.04);
        add("model.layers.0.self_attn.o_proj.weight", vec![d, q], 0.05);
        add("model.layers.0.self_attn.q_norm.weight", vec![q], 1.25);
        add("model.layers.0.self_attn.k_norm.weight", vec![kv], 1.5);
        add(
            "model.layers.0.post_attention_layernorm.weight",
            vec![d],
            1.75,
        );
        add("model.norm.weight", vec![d], 2.0);
        add("lm_head.weight", vec![config.vocab_size, d], 0.09);
        drop(add);
        tensors.push((
            "model.layers.0.mlp.gate.weight".to_owned(),
            vec![experts, d],
            router.clone(),
        ));
        tensors.push((
            "model.layers.0.mlp.e_score_correction_bias".to_owned(),
            vec![experts],
            correction_bias.clone(),
        ));
        tensors.push((
            "model.layers.0.mlp.experts.gate_up_proj".to_owned(),
            vec![experts, 2 * i, d],
            gate_up,
        ));
        tensors.push((
            "model.layers.0.mlp.experts.down_proj".to_owned(),
            vec![experts, d, i],
            down,
        ));

        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let host = load_llama_weights(&test_dir, &config)?;
        let layer = &host.layers[0];
        assert_eq!(layer.q_proj.as_ref().unwrap().weight.len(), q * d);
        assert_eq!(layer.k_proj.as_ref().unwrap().weight.len(), kv * d);
        assert_eq!(layer.q_norm.as_ref().unwrap().weight.len(), q);
        assert_eq!(layer.k_norm.as_ref().unwrap().weight.len(), kv);
        assert_eq!(layer.q_norm.as_ref().unwrap().weight[0], 1.25);
        assert_eq!(layer.k_norm.as_ref().unwrap().weight[0], 1.5);
        assert_eq!(layer.ln1.weight[0], 1.0);
        assert_eq!(layer.ln2.weight[0], 1.75);
        assert_eq!(layer.c_gate.as_ref().unwrap().weight[0], 130.0);
        assert_eq!(layer.c_fc.weight[0], 140.0);
        assert_eq!(layer.c_mlp_proj.weight[0], 150.0);

        let moe_layers = load_mixtral_moe_layers(&test_dir, &config)?;
        assert_eq!(moe_layers.len(), 1);
        assert_eq!(moe_layers[0].router.weight, router);
        assert_eq!(moe_layers[0].router_correction_bias, correction_bias);
        assert_eq!(moe_layers[0].experts.len(), experts - 1);
        assert_eq!(
            moe_layers[0].experts[0]
                .gate
                .as_ref()
                .expect("gated expert")
                .weight[0],
            131.0
        );
        assert_eq!(moe_layers[0].experts[0].up.weight[0], 141.0);
        assert_eq!(moe_layers[0].experts[0].down.weight[0], 151.0);
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

