    #[test]
    fn gpt_oss_moe_loader_reads_current_hf_interleaved_experts_router_and_biases() -> Result<()> {
        let mut value = tiny_gpt_oss_config();
        value["num_hidden_layers"] = serde_json::json!(1);
        value["layer_types"] = serde_json::json!(["full_attention"]);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let i = config.intermediate_size;
        let experts = config
            .moe
            .as_ref()
            .context("missing GPT-OSS MoE config")?
            .num_experts;
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-gpt-oss-moe-loader-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;

        let router = (0..experts * d)
            .map(|index| 0.001 * index as f32)
            .collect::<Vec<_>>();
        let router_bias = (0..experts)
            .map(|expert| 0.25 + expert as f32)
            .collect::<Vec<_>>();
        let mut gate_up = Vec::with_capacity(experts * d * 2 * i);
        let mut gate_up_bias = Vec::with_capacity(experts * 2 * i);
        let mut down = Vec::with_capacity(experts * i * d);
        let mut down_bias = Vec::with_capacity(experts * d);
        let mut expected_gate = Vec::with_capacity(experts);
        let mut expected_up = Vec::with_capacity(experts);
        let mut expected_gate_bias = Vec::with_capacity(experts);
        let mut expected_up_bias = Vec::with_capacity(experts);
        let mut expected_down = Vec::with_capacity(experts);
        let mut expected_down_bias = Vec::with_capacity(experts);
        for expert in 0..experts {
            let gate = (0..i * d)
                .map(|index| 10_000.0 * expert as f32 + 10.0 + index as f32)
                .collect::<Vec<_>>();
            let up = (0..i * d)
                .map(|index| 10_000.0 * expert as f32 + 100.0 + index as f32)
                .collect::<Vec<_>>();
            let gate_bias = (0..i)
                .map(|index| 1000.0 * expert as f32 + 1.0 + index as f32)
                .collect::<Vec<_>>();
            let up_bias = (0..i)
                .map(|index| 1000.0 * expert as f32 + 101.0 + index as f32)
                .collect::<Vec<_>>();
            let down_internal = (0..d * i)
                .map(|index| 10_000.0 * expert as f32 + 1000.0 + index as f32)
                .collect::<Vec<_>>();
            let down_bias_values = (0..d)
                .map(|index| 1000.0 * expert as f32 + 201.0 + index as f32)
                .collect::<Vec<_>>();

            gate_up.extend(gpt_oss_interleave_gate_up(&gate, &up, d, i)?);
            gate_up_bias.extend(gpt_oss_interleave_gate_up_bias(&gate_bias, &up_bias, i)?);
            down.extend(transpose(&down_internal, d, i));
            down_bias.extend(&down_bias_values);
            expected_gate.push(gate);
            expected_up.push(up);
            expected_gate_bias.push(gate_bias);
            expected_up_bias.push(up_bias);
            expected_down.push(down_internal);
            expected_down_bias.push(down_bias_values);
        }

        let tensors = [
            (
                "model.layers.0.mlp.router.weight".to_owned(),
                vec![experts, d],
                router.clone(),
            ),
            (
                "model.layers.0.mlp.router.bias".to_owned(),
                vec![experts],
                router_bias.clone(),
            ),
            (
                "model.layers.0.mlp.experts.gate_up_proj".to_owned(),
                vec![experts, d, 2 * i],
                gate_up,
            ),
            (
                "model.layers.0.mlp.experts.gate_up_proj_bias".to_owned(),
                vec![experts, 2 * i],
                gate_up_bias,
            ),
            (
                "model.layers.0.mlp.experts.down_proj".to_owned(),
                vec![experts, i, d],
                down,
            ),
            (
                "model.layers.0.mlp.experts.down_proj_bias".to_owned(),
                vec![experts, d],
                down_bias,
            ),
        ];
        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let layers = load_mixtral_moe_layers(&test_dir, &config)?;
        assert_eq!(layers.len(), 1);
        assert_eq!(layers[0].router.weight, router);
        assert_eq!(
            layers[0].router.bias.as_deref(),
            Some(router_bias.as_slice())
        );
        assert_eq!(layers[0].experts.len(), experts - 1);
        for (stored_index, expert) in layers[0].experts.iter().enumerate() {
            let hf_index = stored_index + 1;
            let gate = expert.gate.as_ref().expect("gated expert");
            assert_eq!(gate.weight, expected_gate[hf_index]);
            assert_eq!(
                gate.bias.as_deref(),
                Some(expected_gate_bias[hf_index].as_slice())
            );
            assert_eq!(expert.up.weight, expected_up[hf_index]);
            assert_eq!(
                expert.up.bias.as_deref(),
                Some(expected_up_bias[hf_index].as_slice())
            );
            assert_eq!(expert.down.weight, expected_down[hf_index]);
            assert_eq!(
                expert.down.bias.as_deref(),
                Some(expected_down_bias[hf_index].as_slice())
            );
        }
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

