    #[test]
    fn qwen2_checkpoint_loader_applies_attention_bias_only_to_qkv() -> Result<()> {
        for attention_bias in [true, false] {
            let mut value = tiny_qwen2_config();
            value["num_hidden_layers"] = serde_json::json!(1);
            value["layer_types"] = serde_json::json!(["full_attention"]);
            value["attention_bias"] = serde_json::json!(attention_bias);
            let config = VulkanTransformerConfig::from_hf_value(&value)?;
            let d = config.hidden_size;
            let i = config.intermediate_size;
            let q = config.query_hidden_size();
            let kv = config.key_value_hidden_size();
            let test_dir = std::env::temp_dir().join(format!(
                "hierarchos-vulkan-qwen2-qkv-bias-{}-{}-{}",
                attention_bias,
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)?
                    .as_nanos()
            ));
            fs::create_dir_all(&test_dir)?;
            fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

            let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
            let mut add = |name: &str, shape: Vec<usize>, fill: f32| {
                let len = shape.iter().product();
                tensors.push((name.to_owned(), shape, vec![fill; len]));
            };
            add(
                "model.embed_tokens.weight",
                vec![config.vocab_size, d],
                0.01,
            );
            add("model.layers.0.input_layernorm.weight", vec![d], 0.11);
            add("model.layers.0.self_attn.q_proj.weight", vec![q, d], 0.21);
            add("model.layers.0.self_attn.k_proj.weight", vec![kv, d], 0.22);
            add("model.layers.0.self_attn.v_proj.weight", vec![kv, d], 0.23);
            if attention_bias {
                add("model.layers.0.self_attn.q_proj.bias", vec![q], 0.31);
                add("model.layers.0.self_attn.k_proj.bias", vec![kv], 0.32);
                add("model.layers.0.self_attn.v_proj.bias", vec![kv], 0.33);
            }
            add("model.layers.0.self_attn.o_proj.weight", vec![d, q], 0.24);
            add(
                "model.layers.0.post_attention_layernorm.weight",
                vec![d],
                0.12,
            );
            add("model.layers.0.mlp.gate_proj.weight", vec![i, d], 0.41);
            add("model.layers.0.mlp.up_proj.weight", vec![i, d], 0.42);
            add("model.layers.0.mlp.down_proj.weight", vec![d, i], 0.43);
            add("model.norm.weight", vec![d], 0.51);
            add("lm_head.weight", vec![config.vocab_size, d], 0.61);

            let owned = tensors
                .iter()
                .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
                .collect::<Vec<_>>();
            let views = owned
                .iter()
                .map(|(name, shape, bytes)| {
                    Ok((
                        name.as_str(),
                        TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                    ))
                })
                .collect::<Result<Vec<_>>>()?;
            serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

            let host = load_llama_weights(&test_dir, &config)?;
            let layer = &host.layers[0];
            assert_eq!(
                layer.q_proj.as_ref().unwrap().bias.is_some(),
                attention_bias
            );
            assert_eq!(
                layer.k_proj.as_ref().unwrap().bias.is_some(),
                attention_bias
            );
            assert_eq!(
                layer.v_proj.as_ref().unwrap().bias.is_some(),
                attention_bias
            );
            assert!(layer.c_proj.bias.is_none());
            if attention_bias {
                assert_eq!(
                    layer.q_proj.as_ref().unwrap().bias.as_ref().unwrap()[0],
                    0.31
                );
                assert_eq!(
                    layer.k_proj.as_ref().unwrap().bias.as_ref().unwrap()[0],
                    0.32
                );
                assert_eq!(
                    layer.v_proj.as_ref().unwrap().bias.as_ref().unwrap()[0],
                    0.33
                );
            }
            fs::remove_dir_all(&test_dir)?;
        }
        Ok(())
    }

    #[test]
    fn qwen2_vl_text_contract_normalizes_nested_multimodal_config_and_mrope() {
        let text = serde_json::json!({
            "model_type": "qwen2_vl_text",
            "vocab_size": 41,
            "max_position_embeddings": 8,
            "hidden_size": 16,
            "intermediate_size": 32,
            "num_hidden_layers": 2,
            "num_attention_heads": 4,
            "num_key_value_heads": 2,
            "hidden_act": "silu",
            "rms_norm_eps": 1.0e-6,
            "attention_dropout": 0.0,
            "use_sliding_window": true,
            "sliding_window": 4,
            "max_window_layers": 1,
            "rope_scaling": {
                "type": "mrope",
                "rope_theta": 1_000_000.0,
                "mrope_section": [1, 1, 0]
            },
            "tie_word_embeddings": false
        });

        for value in [
            text.clone(),
            serde_json::json!({
                "model_type": "qwen2_vl",
                "text_config": text,
                "vision_config": {"model_type": "qwen2_vl_vision"}
            }),
        ] {
            let config = VulkanTransformerConfig::from_hf_value(&value)
                .expect("Qwen2-VL text-compatible config");
            assert_eq!(config.architecture, VulkanTransformerArchitecture::Qwen2);
            assert_eq!(config.num_heads, 4);
            assert_eq!(config.num_key_value_heads, 2);
            assert_eq!(config.rotary_emb_base, 1_000_000.0);
            assert_eq!(
                config.rope_scaling.scaling_type,
                VulkanRopeScalingType::None
            );
            assert_eq!(config.attention_windows, vec![0, 4]);
            assert_eq!(config.activation_function, "silu");
        }

        let qwen25 = serde_json::json!({
            "model_type": "qwen2_5_vl",
            "text_config": {
                "model_type": "qwen2_5_vl_text",
                "vocab_size": 41,
                "max_position_embeddings": 8,
                "hidden_size": 16,
                "intermediate_size": 32,
                "num_hidden_layers": 2,
                "num_attention_heads": 4,
                "num_key_value_heads": 2,
                "hidden_act": "silu",
                "rms_norm_eps": 1.0e-6,
                "attention_dropout": 0.0,
                "rope_parameters": {"rope_type": "default", "rope_theta": 1_000_000.0},
                "layer_types": ["full_attention", "full_attention"],
                "tie_word_embeddings": false
            }
        });
        let config =
            VulkanTransformerConfig::from_hf_value(&qwen25).expect("Qwen2.5-VL nested text config");
        assert_eq!(config.architecture, VulkanTransformerArchitecture::Qwen2);
        assert_eq!(config.rotary_emb_base, 1_000_000.0);
        assert_eq!(config.attention_windows, vec![0, 0]);
    }

