    #[test]
    fn minicpm3_yarn_attention_scale_matches_hf_mla_contract() {
        let mut value = tiny_minicpm3_config();
        value["rope_parameters"] = serde_json::json!({
            "rope_type": "yarn",
            "rope_theta": 10000.0,
            "factor": 4.0,
            "original_max_position_embeddings": 8,
            "beta_fast": 32.0,
            "beta_slow": 1.0,
            "mscale": 1.0,
            "mscale_all_dim": 1.0
        });
        let config = VulkanTransformerConfig::from_hf_value(&value).expect("MiniCPM3 YaRN config");
        assert_eq!(
            config.rope_scaling.scaling_type,
            VulkanRopeScalingType::Yarn
        );
        let mscale = 0.1 * 4.0_f32.ln() + 1.0;
        let expected = (1.0 / 8.0_f32.sqrt()) * mscale * mscale;
        assert!((config.attention_multiplier.unwrap() - expected).abs() < 1.0e-6);
        assert_eq!(config.rope_scaling.interleaved_pairs, Some(false));
    }

