        assert!(!rotary[1].enabled);
        assert!(rotary[2].enabled);
        assert!(!rotary[3].enabled);
        assert_eq!(rotary[0].rotary_emb_base, 20_000.0);
        assert_eq!(rotary[2].rotary_emb_base, 20_000.0);
        assert_eq!(
            rotary[0].rope_scaling.scaling_type,
            VulkanRopeScalingType::Linear
        );
