    #[test]
    fn starcoder2_contract_supports_scaling_dropout_and_biasless_layout() {
        let mut scaling = tiny_starcoder2_config();
        scaling["rope_scaling"] = serde_json::json!({"rope_type": "linear", "factor": 2.0});
        let config = VulkanTransformerConfig::from_hf_value(&scaling).expect("StarCoder2 scaling");
        assert_eq!(
            config.rope_scaling.scaling_type,
            VulkanRopeScalingType::Linear
        );
        assert_eq!(config.rope_scaling.factor, 2.0);

        let mut dropout = tiny_starcoder2_config();
        dropout["attention_dropout"] = serde_json::json!(0.1);
        dropout["residual_dropout"] = serde_json::json!(0.2);
        dropout["embedding_dropout"] = serde_json::json!(0.3);
        let config =
            VulkanTransformerConfig::from_hf_value(&dropout).expect("StarCoder2 dropout config");
        assert_eq!(config.attention_dropout, 0.1);
        assert_eq!(config.attention_output_dropout, 0.2);
        assert_eq!(config.mlp_output_dropout, 0.2);
        assert_eq!(config.embedding_dropout, 0.3);

        let mut biasless = tiny_starcoder2_config();
        biasless["use_bias"] = serde_json::json!(false);
        VulkanTransformerConfig::from_hf_value(&biasless).expect("biasless StarCoder2 config");

        let mut malformed = tiny_starcoder2_config();
        malformed["use_bias"] = serde_json::json!("false");
        let error = VulkanTransformerConfig::from_hf_value(&malformed)
            .unwrap_err()
            .to_string();
        assert!(error.contains("use_bias must be a boolean"));
    }

    #[test]
    fn starcoder2_checkpoint_loader_accepts_biasless_linear_layers() -> Result<()> {
        let mut value = tiny_starcoder2_config();
        value["num_hidden_layers"] = serde_json::json!(1);
        value["use_bias"] = serde_json::json!(false);
        value["tie_word_embeddings"] = serde_json::json!(false);
        let config = VulkanTransformerConfig::from_hf_value(&value)?;
        let d = config.hidden_size;
        let i = config.intermediate_size;
        let q = config.query_hidden_size();
        let kv = config.key_value_hidden_size();
        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-starcoder2-biasless-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        fs::create_dir_all(&test_dir)?;
        fs::write(test_dir.join("config.json"), serde_json::to_vec(&value)?)?;

        let mut tensors = Vec::<(String, Vec<usize>, Vec<f32>)>::new();
        let mut add = |name: &str, shape: Vec<usize>, fill: f32| {
            let len = shape.iter().product();
            tensors.push((name.to_owned(), shape, vec![fill; len]));
        };
        add(
            "model.embed_tokens.weight",
            vec![config.vocab_size, d],
            0.01,
        );
        add("model.layers.0.input_layernorm.weight", vec![d], 1.0);
        add("model.layers.0.input_layernorm.bias", vec![d], 0.0);
        add("model.layers.0.self_attn.q_proj.weight", vec![q, d], 0.02);
        add("model.layers.0.self_attn.k_proj.weight", vec![kv, d], 0.03);
        add("model.layers.0.self_attn.v_proj.weight", vec![kv, d], 0.04);
        add("model.layers.0.self_attn.o_proj.weight", vec![d, q], 0.05);
        add(
            "model.layers.0.post_attention_layernorm.weight",
            vec![d],
            1.0,
        );
        add("model.layers.0.post_attention_layernorm.bias", vec![d], 0.0);
        add("model.layers.0.mlp.c_fc.weight", vec![i, d], 0.06);
        add("model.layers.0.mlp.c_proj.weight", vec![d, i], 0.07);
        add("model.norm.weight", vec![d], 1.0);
        add("model.norm.bias", vec![d], 0.0);
        add("lm_head.weight", vec![config.vocab_size, d], 0.08);

        let owned = tensors
            .iter()
            .map(|(name, shape, values)| (name.clone(), shape.clone(), f32_le_bytes(values)))
            .collect::<Vec<_>>();
        let views = owned
            .iter()
            .map(|(name, shape, bytes)| {
                Ok((
                    name.as_str(),
                    TensorView::new(Dtype::F32, shape.clone(), bytes)?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        serialize_to_file(views, None, &test_dir.join(GPT2_SAFETENSORS_FILENAME))?;

        let host = load_starcoder2_weights(&test_dir, &config)?;
        let layer = &host.layers[0];
        assert!(layer.q_proj.as_ref().unwrap().bias.is_none());
        assert!(layer.k_proj.as_ref().unwrap().bias.is_none());
        assert!(layer.v_proj.as_ref().unwrap().bias.is_none());
        assert!(layer.c_proj.bias.is_none());
        assert!(layer.c_fc.bias.is_none());
        assert!(layer.c_mlp_proj.bias.is_none());
        assert!(host.lm_head.is_some());
        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn phi3_contract_parses_longrope_frequency_tables_and_hf_scaling() {
        let mut value = tiny_phi3_config();
        value["max_position_embeddings"] = serde_json::json!(32);
        value["rope_scaling"] = serde_json::json!({
            "type": "longrope",
            "short_factor": [1.0, 1.5],
            "long_factor": [2.0, 3.0]
        });
        let config = VulkanTransformerConfig::from_hf_value(&value).expect("Phi-3 LongRoPE");
        assert_eq!(
            config.rope_scaling.scaling_type,
            VulkanRopeScalingType::LongRope
        );
        assert_eq!(config.rope_scaling.factor, 4.0);
        assert_eq!(config.rope_scaling.original_max_position_embeddings, 8);
        assert_eq!(config.rope_scaling.short_factors, vec![1.0, 1.5]);
        assert_eq!(config.rope_scaling.long_factors, vec![2.0, 3.0]);
        let expected_attention_factor = (1.0_f32 + 4.0_f32.ln() / 8.0_f32.ln()).sqrt();
        assert!((config.rope_scaling.attention_factor - expected_attention_factor).abs() < 1.0e-6);
        assert_eq!(config.rope_scaling.kernel_type(), 6);

        for legacy_type in ["su", "yarn"] {
            let mut legacy = tiny_phi3_config();
            legacy["max_position_embeddings"] = serde_json::json!(32);
            legacy["rope_scaling"] = serde_json::json!({
                "type": legacy_type,
                "short_factor": [1.0, 1.0],
                "long_factor": [2.0, 2.0]
            });
            let legacy = VulkanTransformerConfig::from_hf_value(&legacy)
                .unwrap_or_else(|error| panic!("legacy Phi-3 {legacy_type} LongRoPE: {error}"));
            assert_eq!(
                legacy.rope_scaling.scaling_type,
                VulkanRopeScalingType::LongRope
            );
        }

        let mut invalid = tiny_phi3_config();
        invalid["rope_scaling"] = serde_json::json!({
            "type": "longrope",
            "short_factor": [1.0],
            "long_factor": [2.0]
        });
        let error = VulkanTransformerConfig::from_hf_value(&invalid)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("rotary_dim/2=2"),
            "unexpected error: {error}"
        );
    }

