    #[test]
    fn falcon_qkv_layout_round_trips_mqa_gqa_and_mha() -> Result<()> {
        for num_key_value_heads in [1usize, 2, 4] {
            let hidden_size = 16usize;
            let num_heads = 4usize;
            let input_dim = 3usize;
            let head_dim = hidden_size / num_heads;
            let fused = hidden_size + 2 * num_key_value_heads * head_dim;
            let values = (0..fused * input_dim)
                .map(|value| value as f32)
                .collect::<Vec<_>>();
            let contiguous = falcon_qkv_to_contiguous(
                &values,
                hidden_size,
                num_heads,
                num_key_value_heads,
                input_dim,
            )?;
            let restored = contiguous_qkv_to_falcon(
                &contiguous,
                hidden_size,
                num_heads,
                num_key_value_heads,
                input_dim,
            )?;
            assert_eq!(restored, values, "KV-head count {num_key_value_heads}");
        }
        Ok(())
    }

