    #[test]
    fn minimax_m3_vl_text_checkpoint_export_round_trips_lightning_indexer() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_minimax_m3_vl_text_vulkan_graph(device.clone())?;
        let expected = graph.hf_parameter_tensors()?;

        for (name, shape) in [
            (
                "model.layers.0.self_attn.indexer.q_proj.weight",
                vec![8, 16],
            ),
            (
                "model.layers.0.self_attn.indexer.k_proj.weight",
                vec![4, 16],
            ),
            ("model.layers.0.self_attn.indexer.q_norm.weight", vec![4]),
            ("model.layers.0.self_attn.indexer.k_norm.weight", vec![4]),
        ] {
            assert_eq!(
                expected
                    .get(name)
                    .with_context(|| format!("MiniMax-M3 export is missing {name}"))?
                    .0,
                shape
            );
        }
        assert!(
            !expected.contains_key("model.layers.1.self_attn.indexer.q_proj.weight"),
            "MiniMax-M3 full-attention layer must not export a Lightning Indexer"
        );
        for layer in 0..2 {
            assert!(
                expected.contains_key(&format!("model.layers.{layer}.mlp.gate_up_proj.weight")),
                "MiniMax-M3 dense MLP export is missing layer {layer} gate_up_proj"
            );
        }

        let root = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-minimax-m3-export-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        let source_dir = root.join("source");
        let output_dir = root.join("output");
        fs::create_dir_all(&source_dir)?;
        fs::write(
            source_dir.join("config.json"),
            serde_json::to_vec_pretty(&tiny_minimax_m3_vl_text_config())?,
        )?;

        graph.export_hf_package(&source_dir, &output_dir)?;
        let exported = Gpt2TensorStore::load(&output_dir)?.into_parameter_tensors()?;
        assert_eq!(
            exported, expected,
            "MiniMax-M3 exported tensors changed during package serialization"
        );

        let indexers = load_minimax_m3_indexers(&output_dir, &graph.config)?
            .context("reloaded MiniMax-M3 package lost its Lightning Indexer table")?;
        let indexer = indexers[0]
            .as_ref()
            .context("reloaded MiniMax-M3 sparse layer lost its Lightning Indexer")?;
        assert_eq!(indexer.q_proj.weight[0], 0.021);
        assert_eq!(indexer.k_proj.weight[0], 0.022);
        assert_eq!(indexer.q_norm.weight[0], 0.03);
        assert_eq!(indexer.k_norm.weight[0], 0.04);
        assert!(indexers[1].is_none());

        let reloaded = VulkanTransformer::from_hf_package(device, &output_dir, 1, 8)?;
        assert_eq!(
            reloaded.hf_parameter_tensors()?,
            expected,
            "MiniMax-M3 full graph reload did not preserve the exported checkpoint"
        );
        fs::remove_dir_all(&root)?;
        Ok(())
    }

