    #[test]
    fn lora_all_linear_round_trips_and_honors_peft_filters() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut graph = tiny_gpt2_vulkan_graph(device.clone())?;
        let mut config = VulkanTransformerLoraConfig::gpt2(2, 4, vec!["c_attn".to_owned()])?;
        config.target_modules.clear();
        // A scalar target_modules value is normally a full-match regex in
        // PEFT. "all-linear" is the one reserved selector that PEFT expands
        // to every Linear/Conv1D module. It is still a scalar value at config
        // validation time, so layer filters are rejected just like a regex.
        config.target_modules_regex = Some(PEFT_ALL_LINEAR_TARGET.to_owned());
        config.exclude_modules = vec!["mlp.c_proj".to_owned()];
        let mut invalid = config.clone();
        invalid.layers_to_transform = Some(vec![0]);
        invalid.layers_pattern = vec!["h".to_owned()];
        let error = invalid.validate().unwrap_err().to_string();
        assert!(error.contains("layers_to_transform"));
        config.validate()?;

        assert!(config.targets("transformer.h.0.attn.c_attn"));
        assert!(config.targets("transformer.h.0.attn.c_proj"));
        assert!(config.targets("transformer.h.0.mlp.c_fc"));
        assert!(!config.targets("transformer.h.0.mlp.c_proj"));
        assert!(config.targets("transformer.h.1.attn.c_attn"));
        assert_eq!(graph.enable_lora(config.clone(), 59)?, 6);
        assert!(graph.layers[0]
            .c_attn
            .as_ref()
            .context("tiny GPT-2 graph is missing c_attn")?
            .lora
            .is_some());
        assert!(graph.layers[0].c_proj.lora.is_some());
        assert!(graph.layers[0].c_fc.lora.is_some());
        assert!(graph.layers[0].c_mlp_proj.lora.is_none());
        assert!(graph.layers[1]
            .c_attn
            .as_ref()
            .context("tiny GPT-2 graph is missing c_attn")?
            .lora
            .is_some());
        assert!(graph
            .lm_head
            .as_ref()
            .is_none_or(|lm_head| lm_head.lora.is_none()));

        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-all-linear-roundtrip-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        graph.export_lora_adapter(&test_dir)?;
        let exported_config: serde_json::Value = serde_json::from_slice(&fs::read(
            test_dir.join(VULKAN_TRANSFORMER_ADAPTER_CONFIG_FILENAME),
        )?)?;
        assert_eq!(
            exported_config["target_modules"],
            serde_json::json!(PEFT_ALL_LINEAR_TARGET)
        );
        assert_eq!(
            exported_config["exclude_modules"],
            serde_json::json!(["mlp.c_proj"])
        );

        let mut reloaded = tiny_gpt2_vulkan_graph(device)?;
        assert_eq!(reloaded.load_lora_adapter(&test_dir)?, 6);
        let reloaded_config = reloaded
            .lora_config()
            .context("reloaded graph is missing LoRA config")?;
        assert!(reloaded_config.targets_all_linear());
        assert_eq!(
            reloaded_config.target_modules_regex.as_deref(),
            Some(PEFT_ALL_LINEAR_TARGET)
        );
        assert!(reloaded.layers[0]
            .c_attn
            .as_ref()
            .context("reloaded GPT-2 graph is missing c_attn")?
            .lora
            .is_some());
        assert!(reloaded.layers[0].c_proj.lora.is_some());
        assert!(reloaded.layers[0].c_fc.lora.is_some());
        assert!(reloaded.layers[0].c_mlp_proj.lora.is_none());
        assert!(reloaded.layers[1]
            .c_attn
            .as_ref()
            .context("reloaded GPT-2 graph is missing c_attn")?
            .lora
            .is_some());

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

