    #[test]
    fn llama4_packed_target_parameters_round_trip_through_peft_adapter_export() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };

        // The native Mixtral test fixture has the same split expert geometry
        // used by the Llama 4 packed-Parameter adapter bridge. Retagging the
        // already-built fixture keeps this test focused on the PEFT ABI rather
        // than duplicating the Llama 4 package loader fixture here.
        let mut graph = tiny_mixtral_vulkan_graph(device.clone())?;
        graph.config.architecture = VulkanTransformerArchitecture::Llama4Text;
        let mut config =
            VulkanTransformerLoraConfig::causal_lm(2, 4, vec!["q_proj".to_owned()], false)?;
        config.target_modules.clear();
        config.target_parameters = Some(vec!["gate_up_proj".to_owned(), "down_proj".to_owned()]);
        config.validate()?;
        assert_eq!(
            graph.enable_lora(config.clone(), 811)?,
            graph.layers.len() * 2
        );

        let set_b = |linear: &mut VulkanLinear, value: f32| -> Result<()> {
            let lora = linear
                .lora
                .as_mut()
                .context("target_parameters test linear is missing LoRA state")?;
            lora.b = TrainableParameter::new(
                &device,
                &vec![value; linear.output_dim * lora.rank],
                false,
            )?;
            Ok(())
        };
        for (layer_index, layer) in graph.layers.iter_mut().enumerate() {
            let base = 0.1 * (layer_index + 1) as f32;
            set_b(
                layer
                    .c_gate
                    .as_mut()
                    .context("Llama 4 expert 0 is missing gate projection")?,
                base + 0.01,
            )?;
            set_b(&mut layer.c_fc, base + 0.02)?;
            set_b(&mut layer.c_mlp_proj, base + 0.03)?;
            let moe = layer
                .moe
                .as_mut()
                .context("Llama 4 target_parameters test layer is missing MoE state")?;
            for (expert_index, expert) in moe.experts.iter_mut().enumerate() {
                let expert_base = base + 0.01 * (expert_index + 1) as f32;
                set_b(
                    expert
                        .gate
                        .as_mut()
                        .context("Llama 4 routed expert is missing gate projection")?,
                    expert_base + 0.04,
                )?;
                set_b(&mut expert.up, expert_base + 0.05)?;
                set_b(&mut expert.down, expert_base + 0.06)?;
            }
        }

        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)?
            .as_nanos();
        let first_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-llama4-target-parameters-first-{}-{unique}",
            std::process::id()
        ));
        let second_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-llama4-target-parameters-second-{}-{unique}",
            std::process::id()
        ));
        graph.export_lora_adapter(&first_dir)?;

        let exported_config: serde_json::Value = serde_json::from_slice(&fs::read(
            first_dir.join(VULKAN_TRANSFORMER_ADAPTER_CONFIG_FILENAME),
        )?)?;
        assert_eq!(
            exported_config["target_parameters"],
            serde_json::json!(["gate_up_proj", "down_proj"])
        );
        let first_weights = fs::read(first_dir.join(VULKAN_TRANSFORMER_ADAPTER_WEIGHTS_FILENAME))?;
        let tensors = SafeTensors::deserialize(&first_weights)?;
        for layer_index in 0..graph.layers.len() {
            let module = format!("model.layers.{layer_index}.feed_forward.experts");
            for key in [
                peft_parameter_lora_tensor_key(&module, true, 'A'),
                peft_parameter_lora_tensor_key(&module, true, 'B'),
                peft_parameter_lora_tensor_key(&module, false, 'A'),
                peft_parameter_lora_tensor_key(&module, false, 'B'),
            ] {
                assert!(
                    tensors.names().iter().any(|name| *name == key),
                    "packed target_parameters adapter is missing {key}"
                );
            }
        }

        let mut reloaded = tiny_mixtral_vulkan_graph(device)?;
        reloaded.config.architecture = VulkanTransformerArchitecture::Llama4Text;
        assert_eq!(
            reloaded.load_lora_adapter(&first_dir)?,
            reloaded.layers.len() * 2
        );
        reloaded.export_lora_adapter(&second_dir)?;
        assert_eq!(
            fs::read(first_dir.join(VULKAN_TRANSFORMER_ADAPTER_CONFIG_FILENAME))?,
            fs::read(second_dir.join(VULKAN_TRANSFORMER_ADAPTER_CONFIG_FILENAME))?
        );
        assert_eq!(
            first_weights,
            fs::read(second_dir.join(VULKAN_TRANSFORMER_ADAPTER_WEIGHTS_FILENAME))?
        );

        fs::remove_dir_all(&first_dir)?;
        fs::remove_dir_all(&second_dir)?;
        Ok(())
    }

