    #[test]
    fn bias_all_round_trips_every_gpt2_bias_through_peft_adapter_export() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut graph = tiny_gpt2_vulkan_graph(device.clone())?;
        let mut config = VulkanTransformerLoraConfig::gpt2(2, 4, vec!["c_attn".to_owned()])?;
        config.bias = "all".to_owned();
        assert_eq!(graph.enable_lora(config, 29)?, graph.layers.len());

        assert!(!graph.layers[0].ln1.trainable);
        assert!(graph.layers[0].ln1.train_bias);
        assert!(
            !graph.layers[0]
                .c_attn
                .as_ref()
                .context("tiny GPT-2 graph is missing c_attn")?
                .train_base
        );
        assert!(
            graph.layers[0]
                .c_attn
                .as_ref()
                .context("tiny GPT-2 graph is missing c_attn")?
                .train_bias
        );

        for (layer_index, layer) in graph.layers.iter_mut().enumerate() {
            let d = graph.config.hidden_size;
            let i = graph.config.intermediate_size;
            let fill = |len: usize, base: f32| {
                (0..len)
                    .map(|index| base + index as f32 * 0.0001)
                    .collect::<Vec<_>>()
            };
            let base = 2.0 + layer_index as f32;
            layer.ln1.bias = TrainableParameter::new(&device, &fill(d, base + 0.01), false)?;
            layer
                .c_attn
                .as_mut()
                .context("tiny GPT-2 graph is missing c_attn")?
                .bias = TrainableParameter::new(&device, &fill(3 * d, base + 0.02), false)?;
            layer.c_proj.bias = TrainableParameter::new(&device, &fill(d, base + 0.03), false)?;
            layer.ln2.bias = TrainableParameter::new(&device, &fill(d, base + 0.04), false)?;
            layer.c_fc.bias = TrainableParameter::new(&device, &fill(i, base + 0.05), false)?;
            layer.c_mlp_proj.bias = TrainableParameter::new(&device, &fill(d, base + 0.06), false)?;
        }
        graph.final_norm.bias =
            TrainableParameter::new(&device, &vec![9.25; graph.config.hidden_size], false)?;
        let expected_biases = graph
            .gpt2_parameter_tensors()?
            .into_iter()
            .filter(|(name, _)| name.ends_with(".bias"))
            .collect::<BTreeMap<_, _>>();

        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-lora-bias-all-roundtrip-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        graph.export_lora_adapter(&test_dir)?;
        let weights_path = test_dir.join(VULKAN_TRANSFORMER_ADAPTER_WEIGHTS_FILENAME);
        let bytes = fs::read(&weights_path)?;
        let tensors = SafeTensors::deserialize(&bytes)?;
        assert!(tensors
            .names()
            .iter()
            .any(|name| *name == "base_model.model.transformer.h.0.ln_1.bias"));
        assert!(tensors.names().iter().any(|name| {
            *name == "base_model.model.transformer.h.0.attn.c_attn.base_layer.bias"
        }));
        assert!(!tensors
            .names()
            .iter()
            .any(|name| { *name == "base_model.model.transformer.h.0.attn.c_attn.bias" }));
        assert!(tensors
            .names()
            .iter()
            .any(|name| *name == "base_model.model.transformer.ln_f.bias"));

        let mut reloaded = tiny_gpt2_vulkan_graph(device)?;
        assert_eq!(
            reloaded.load_lora_adapter(&test_dir)?,
            reloaded.layers.len()
        );
        let actual_biases = reloaded
            .gpt2_parameter_tensors()?
            .into_iter()
            .filter(|(name, _)| name.ends_with(".bias"))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(actual_biases, expected_biases);

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn bias_all_round_trips_every_bert_bias_with_current_peft_key_layout() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut graph = tiny_bert_vulkan_graph(device.clone())?;
        let mut config =
            VulkanTransformerLoraConfig::causal_lm(2, 4, vec!["query".to_owned()], false)?;
        config.task_type = "FEATURE_EXTRACTION".to_owned();
        config.bias = "all".to_owned();
        assert_eq!(graph.enable_lora(config, 47)?, graph.layers.len());

        assert!(
            graph
                .embedding_norm
                .as_ref()
                .context("tiny BERT graph is missing embedding LayerNorm")?
                .train_bias
        );
        assert!(
            graph.layers[0]
                .q_proj
                .as_ref()
                .context("tiny BERT graph is missing query projection")?
                .train_bias
        );
        assert!(graph.layers[0].ln1.train_bias);
        let prediction_head = graph
            .prediction_head
            .as_ref()
            .context("tiny BERT graph is missing prediction head")?;
        assert!(prediction_head.dense.train_bias);
        assert!(prediction_head.norm.train_bias);

        let fill = |len: usize, base: f32| {
            (0..len)
                .map(|index| base + index as f32 * 0.00011)
                .collect::<Vec<_>>()
        };
        let d = graph.config.hidden_size;
        let i = graph.config.intermediate_size;
        let e = graph.config.effective_embedding_size();
        graph
            .embedding_norm
            .as_mut()
            .context("tiny BERT graph is missing embedding LayerNorm")?
            .bias = TrainableParameter::new(&device, &fill(e, 1.01), false)?;
        for (layer_index, layer) in graph.layers.iter_mut().enumerate() {
            let base = 2.0 + layer_index as f32;
            layer
                .q_proj
                .as_mut()
                .context("tiny BERT graph is missing query projection")?
                .bias = TrainableParameter::new(&device, &fill(d, base + 0.01), false)?;
            layer
                .k_proj
                .as_mut()
                .context("tiny BERT graph is missing key projection")?
                .bias = TrainableParameter::new(&device, &fill(d, base + 0.02), false)?;
            layer
                .v_proj
                .as_mut()
                .context("tiny BERT graph is missing value projection")?
                .bias = TrainableParameter::new(&device, &fill(d, base + 0.03), false)?;
            layer.c_proj.bias = TrainableParameter::new(&device, &fill(d, base + 0.04), false)?;
            layer.ln1.bias = TrainableParameter::new(&device, &fill(d, base + 0.05), false)?;
            layer.c_fc.bias = TrainableParameter::new(&device, &fill(i, base + 0.06), false)?;
            layer.c_mlp_proj.bias = TrainableParameter::new(&device, &fill(d, base + 0.07), false)?;
            layer.ln2.bias = TrainableParameter::new(&device, &fill(d, base + 0.08), false)?;
        }
        let prediction_head = graph
            .prediction_head
            .as_mut()
            .context("tiny BERT graph is missing prediction head")?;
        prediction_head.dense.bias = TrainableParameter::new(&device, &fill(e, 7.01), false)?;
        prediction_head.norm.bias = TrainableParameter::new(&device, &fill(e, 7.02), false)?;
        *graph
            .lm_head_bias
            .as_mut()
            .context("tiny BERT graph is missing tied MLM decoder bias")? =
            TrainableParameter::new(&device, &fill(graph.config.vocab_size, 7.03), false)?;

        let expected_biases = graph
            .bert_parameter_tensors()?
            .into_iter()
            .filter(|(name, _)| name.ends_with(".bias"))
            .collect::<BTreeMap<_, _>>();

        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-lora-bias-all-bert-roundtrip-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        graph.export_lora_adapter(&test_dir)?;
        let weights_path = test_dir.join(VULKAN_TRANSFORMER_ADAPTER_WEIGHTS_FILENAME);
        let bytes = fs::read(&weights_path)?;
        let tensors = SafeTensors::deserialize(&bytes)?;
        let query_base_bias =
            "base_model.model.bert.encoder.layer.0.attention.self.query.base_layer.bias";
        assert!(tensors.names().iter().any(|name| *name == query_base_bias));
        assert!(!tensors.names().iter().any(|name| {
            *name == "base_model.model.bert.encoder.layer.0.attention.self.query.bias"
        }));
        assert!(tensors.names().iter().any(|name| {
            *name == "base_model.model.bert.encoder.layer.0.attention.self.key.bias"
        }));
        assert!(tensors
            .names()
            .iter()
            .any(|name| *name == "base_model.model.cls.predictions.bias"));
        assert!(tensors
            .names()
            .iter()
            .any(|name| *name == "base_model.model.cls.predictions.decoder.bias"));

        let mut reloaded = tiny_bert_vulkan_graph(device)?;
        assert_eq!(
            reloaded.load_lora_adapter(&test_dir)?,
            reloaded.layers.len()
        );
        let actual_biases = reloaded
            .bert_parameter_tensors()?
            .into_iter()
            .filter(|(name, _)| name.ends_with(".bias"))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(actual_biases, expected_biases);

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn bias_all_round_trips_rembert_electra_and_megatron_bert_topologies() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut rembert_decoder = tiny_rembert_config();
        rembert_decoder["is_decoder"] = serde_json::json!(true);
        rembert_decoder["add_cross_attention"] = serde_json::json!(true);
        for (case_index, value) in [
            rembert_decoder,
            tiny_electra_config(),
            tiny_megatron_bert_config(),
        ]
        .into_iter()
        .enumerate()
        {
            let model_type = value["model_type"]
                .as_str()
                .context("tiny BERT-family config is missing model_type")?
                .to_owned();
            let mut graph = tiny_bert_family_vulkan_graph(device.clone(), value.clone())?;
            let mut config =
                VulkanTransformerLoraConfig::causal_lm(2, 4, vec!["query".to_owned()], false)?;
            config.task_type = "FEATURE_EXTRACTION".to_owned();
            config.bias = "all".to_owned();
            let expected_targets = graph.count_lora_target_modules(&config)?;
            assert_eq!(
                graph.enable_lora(config, 71 + case_index as u64)?,
                expected_targets
            );

            let fill = |len: usize, base: f32| {
                (0..len)
                    .map(|index| base + index as f32 * 0.00009)
                    .collect::<Vec<_>>()
            };
            if let Some(embedding_norm) = graph.embedding_norm.as_mut() {
                assert!(!embedding_norm.trainable);
                assert!(embedding_norm.train_bias);
                embedding_norm.bias = TrainableParameter::new(
                    &device,
                    &fill(
                        embedding_norm.dim * embedding_norm.parameter_groups,
                        10.0 + case_index as f32,
                    ),
                    false,
                )?;
            }
            if let Some(embedding_project) = graph.embedding_project.as_mut() {
                assert!(!embedding_project.train_base);
                assert!(embedding_project.train_bias);
                embedding_project.bias = TrainableParameter::new(
                    &device,
                    &fill(embedding_project.output_dim, 11.0 + case_index as f32),
                    false,
                )?;
            }
            for (layer_index, layer) in graph.layers.iter_mut().enumerate() {
                let base = 20.0 + case_index as f32 * 10.0 + layer_index as f32;
                for (offset, projection) in [
                    layer
                        .q_proj
                        .as_mut()
                        .context("tiny BERT-family graph is missing query projection")?,
                    layer
                        .k_proj
                        .as_mut()
                        .context("tiny BERT-family graph is missing key projection")?,
                    layer
                        .v_proj
                        .as_mut()
                        .context("tiny BERT-family graph is missing value projection")?,
                ]
                .into_iter()
                .enumerate()
                {
                    projection.bias = TrainableParameter::new(
                        &device,
                        &fill(projection.output_dim, base + 0.01 + offset as f32 * 0.01),
                        false,
                    )?;
                }
                layer.c_proj.bias = TrainableParameter::new(
                    &device,
                    &fill(layer.c_proj.output_dim, base + 0.05),
                    false,
                )?;
                layer.ln1.bias = TrainableParameter::new(
                    &device,
                    &fill(layer.ln1.dim * layer.ln1.parameter_groups, base + 0.06),
                    false,
                )?;
                layer.c_fc.bias = TrainableParameter::new(
                    &device,
                    &fill(layer.c_fc.output_dim, base + 0.07),
                    false,
                )?;
                layer.c_mlp_proj.bias = TrainableParameter::new(
                    &device,
                    &fill(layer.c_mlp_proj.output_dim, base + 0.08),
                    false,
                )?;
                layer.ln2.bias = TrainableParameter::new(
                    &device,
                    &fill(layer.ln2.dim * layer.ln2.parameter_groups, base + 0.09),
                    false,
                )?;
                if let Some(cross_attention) = layer.cross_attention.as_mut() {
                    for (offset, projection) in [
                        &mut cross_attention.q_proj,
                        &mut cross_attention.k_proj,
                        &mut cross_attention.v_proj,
                        &mut cross_attention.out_proj,
                    ]
                    .into_iter()
                    .enumerate()
                    {
                        projection.bias = TrainableParameter::new(
                            &device,
                            &fill(projection.output_dim, base + 0.20 + offset as f32 * 0.01),
                            false,
                        )?;
                    }
                    cross_attention.norm.bias = TrainableParameter::new(
                        &device,
                        &fill(
                            cross_attention.norm.dim * cross_attention.norm.parameter_groups,
                            base + 0.24,
                        ),
                        false,
                    )?;
                }
            }
            if graph.config.architecture == VulkanTransformerArchitecture::MegatronBert {
                assert!(graph.final_norm.train_bias);
                graph.final_norm.bias = TrainableParameter::new(
                    &device,
                    &fill(
                        graph.final_norm.dim * graph.final_norm.parameter_groups,
                        50.0,
                    ),
                    false,
                )?;
            }
            let prediction_head = graph
                .prediction_head
                .as_mut()
                .context("tiny BERT-family graph is missing prediction head")?;
            prediction_head.dense.bias = TrainableParameter::new(
                &device,
                &fill(prediction_head.dense.output_dim, 51.0 + case_index as f32),
                false,
            )?;
            prediction_head.norm.bias = TrainableParameter::new(
                &device,
                &fill(
                    prediction_head.norm.dim * prediction_head.norm.parameter_groups,
                    52.0 + case_index as f32,
                ),
                false,
            )?;
            let decoder_bias = fill(graph.config.vocab_size, 53.0 + case_index as f32);
            if let Some(lm_head) = graph.lm_head.as_mut() {
                lm_head.bias = TrainableParameter::new(&device, &decoder_bias, false)?;
            } else {
                *graph
                    .lm_head_bias
                    .as_mut()
                    .context("tiny BERT-family graph is missing tied decoder bias")? =
                    TrainableParameter::new(&device, &decoder_bias, false)?;
            }

            let expected_biases = graph
                .bert_parameter_tensors()?
                .into_iter()
                .filter(|(name, _)| name.ends_with(".bias"))
                .collect::<BTreeMap<_, _>>();
            let test_dir = std::env::temp_dir().join(format!(
                "hierarchos-vulkan-lora-bias-all-{model_type}-roundtrip-{}-{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)?
                    .as_nanos()
            ));
            graph.export_lora_adapter(&test_dir)?;

            let mut reloaded = tiny_bert_family_vulkan_graph(device.clone(), value)?;
            assert_eq!(reloaded.load_lora_adapter(&test_dir)?, expected_targets);
            let actual_biases = reloaded
                .bert_parameter_tensors()?
                .into_iter()
                .filter(|(name, _)| name.ends_with(".bias"))
                .collect::<BTreeMap<_, _>>();
            assert_eq!(
                actual_biases, expected_biases,
                "{model_type} bias round-trip"
            );
            fs::remove_dir_all(&test_dir)?;
        }
        Ok(())
    }

    #[test]
    fn bias_all_round_trips_gpt_oss_attention_router_and_packed_expert_biases() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut graph = tiny_gpt_oss_vulkan_graph(device.clone())?;
        let mut config =
            VulkanTransformerLoraConfig::causal_lm(2, 4, vec!["q_proj".to_owned()], false)?;
        config.bias = "all".to_owned();
        let expected_targets = graph.count_lora_target_modules(&config)?;
        assert_eq!(graph.enable_lora(config, 83)?, expected_targets);

        let fill = |len: usize, base: f32| {
            (0..len)
                .map(|index| base + index as f32 * 0.00007)
                .collect::<Vec<_>>()
        };
        for (layer_index, layer) in graph.layers.iter_mut().enumerate() {
            let base = 60.0 + layer_index as f32 * 10.0;
            for (offset, projection) in [
                layer
                    .q_proj
                    .as_mut()
                    .context("tiny GPT-OSS graph is missing q_proj")?,
                layer
                    .k_proj
                    .as_mut()
                    .context("tiny GPT-OSS graph is missing k_proj")?,
                layer
                    .v_proj
                    .as_mut()
                    .context("tiny GPT-OSS graph is missing v_proj")?,
            ]
            .into_iter()
            .enumerate()
            {
                assert!(projection.train_bias);
                projection.bias = TrainableParameter::new(
                    &device,
                    &fill(projection.output_dim, base + 0.01 + offset as f32 * 0.01),
                    false,
                )?;
            }
            assert!(layer.c_proj.train_bias);
            layer.c_proj.bias = TrainableParameter::new(
                &device,
                &fill(layer.c_proj.output_dim, base + 0.04),
                false,
            )?;
            let gate0 = layer
                .c_gate
                .as_mut()
                .context("tiny GPT-OSS graph is missing expert-0 gate")?;
            assert!(gate0.train_bias);
            assert!(layer.c_fc.train_bias);
            assert!(layer.c_mlp_proj.train_bias);
            gate0.bias =
                TrainableParameter::new(&device, &fill(gate0.output_dim, base + 0.10), false)?;
            layer.c_fc.bias =
                TrainableParameter::new(&device, &fill(layer.c_fc.output_dim, base + 0.11), false)?;
            layer.c_mlp_proj.bias = TrainableParameter::new(
                &device,
                &fill(layer.c_mlp_proj.output_dim, base + 0.12),
                false,
            )?;

            let moe = layer
                .moe
                .as_mut()
                .context("tiny GPT-OSS graph is missing native MoE")?;
            assert!(moe.router.train_bias);
            moe.router.bias =
                TrainableParameter::new(&device, &fill(moe.router.output_dim, base + 0.20), false)?;
            for (expert_index, expert) in moe.experts.iter_mut().enumerate() {
                let expert_base = base + 1.0 + expert_index as f32;
                let gate = expert
                    .gate
                    .as_mut()
                    .context("tiny GPT-OSS routed expert is missing gate")?;
                assert!(gate.train_bias);
                assert!(expert.up.train_bias);
                assert!(expert.down.train_bias);
                gate.bias = TrainableParameter::new(
                    &device,
                    &fill(gate.output_dim, expert_base + 0.01),
                    false,
                )?;
                expert.up.bias = TrainableParameter::new(
                    &device,
                    &fill(expert.up.output_dim, expert_base + 0.02),
                    false,
                )?;
                expert.down.bias = TrainableParameter::new(
                    &device,
                    &fill(expert.down.output_dim, expert_base + 0.03),
                    false,
                )?;
            }
        }

        let expected_biases = graph
            .hf_parameter_tensors()?
            .into_iter()
            .filter(|(name, _)| name.contains("bias"))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(expected_biases.len(), graph.layers.len() * 7);

        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-lora-bias-all-gpt-oss-roundtrip-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        graph.export_lora_adapter(&test_dir)?;
        let weights_path = test_dir.join(VULKAN_TRANSFORMER_ADAPTER_WEIGHTS_FILENAME);
        let bytes = fs::read(&weights_path)?;
        let tensors = SafeTensors::deserialize(&bytes)?;
        for key in [
            "base_model.model.model.layers.0.self_attn.q_proj.base_layer.bias",
            "base_model.model.model.layers.0.mlp.router.bias",
            "base_model.model.model.layers.0.mlp.experts.gate_up_proj_bias",
            "base_model.model.model.layers.0.mlp.experts.down_proj_bias",
        ] {
            assert!(
                tensors.names().iter().any(|name| *name == key),
                "GPT-OSS adapter is missing {key}"
            );
        }

        let mut reloaded = tiny_gpt_oss_vulkan_graph(device)?;
        assert_eq!(reloaded.load_lora_adapter(&test_dir)?, expected_targets);
        let actual_biases = reloaded
            .hf_parameter_tensors()?
            .into_iter()
            .filter(|(name, _)| name.contains("bias"))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(actual_biases, expected_biases);

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

    #[test]
    fn bias_all_trains_gpt_oss_sparse_biases_without_base_weights() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut graph = tiny_gpt_oss_vulkan_graph(device)?;
        let mut config =
            VulkanTransformerLoraConfig::causal_lm(2, 4, vec!["q_proj".to_owned()], false)?;
        config.bias = "all".to_owned();
        graph.enable_lora(config, 89)?;

        let q_weight_before = graph.layers[0]
            .q_proj
            .as_ref()
            .context("tiny GPT-OSS graph is missing q_proj")?
            .weight
            .read()?;
        let q_bias_before = graph.layers[0]
            .q_proj
            .as_ref()
            .context("tiny GPT-OSS graph is missing q_proj")?
            .bias
            .read()?;
        let router_weight_before = graph.layers[0]
            .moe
            .as_ref()
            .context("tiny GPT-OSS graph is missing native MoE")?
            .router
            .weight
            .read()?;
        let router_bias_before = graph.layers[0]
            .moe
            .as_ref()
            .context("tiny GPT-OSS graph is missing native MoE")?
            .router
            .bias
            .read()?;
        let expert_weight_before = graph.layers[0]
            .c_gate
            .as_ref()
            .context("tiny GPT-OSS graph is missing expert-0 gate")?
            .weight
            .read()?;
        let packed_biases_before = graph
            .hf_parameter_tensors()?
            .remove("model.layers.0.mlp.experts.gate_up_proj_bias")
            .context("tiny GPT-OSS export is missing packed gate/up bias")?
            .1;

        let input_ids = [1, 2, 3, 4, 5, 6, 7, 8];
        let targets = [2, 3, 4, 5, 6, 7, 8, 9];
        let attention_mask = [1.0; 8];
        let loss_weights = [1.0; 8];
        let result = graph.train_step(
            &input_ids,
            &targets,
            &attention_mask,
            &loss_weights,
            AdamWHyperParams {
                lr: 5.0e-3,
                weight_decay: 0.0,
                ..AdamWHyperParams::default()
            },
        )?;
        assert!(
            result.loss.is_finite(),
            "GPT-OSS LoRA loss must remain finite"
        );

        let q_proj = graph.layers[0]
            .q_proj
            .as_ref()
            .context("tiny GPT-OSS graph lost q_proj")?;
        assert_eq!(q_proj.weight.read()?, q_weight_before);
        assert_ne!(q_proj.bias.read()?, q_bias_before);
        let moe = graph.layers[0]
            .moe
            .as_ref()
            .context("tiny GPT-OSS graph lost native MoE")?;
        assert_eq!(moe.router.weight.read()?, router_weight_before);
        assert_ne!(moe.router.bias.read()?, router_bias_before);
        assert_eq!(
            graph.layers[0]
                .c_gate
                .as_ref()
                .context("tiny GPT-OSS graph lost expert-0 gate")?
                .weight
                .read()?,
            expert_weight_before
        );
        let packed_biases_after = graph
            .hf_parameter_tensors()?
            .remove("model.layers.0.mlp.experts.gate_up_proj_bias")
            .context("tiny GPT-OSS export lost packed gate/up bias")?
            .1;
        assert_ne!(packed_biases_after, packed_biases_before);
        Ok(())
    }

    #[test]
    fn bias_all_trains_factorized_bert_projection_bias_without_base_weights() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        for (case_index, value) in [tiny_electra_config(), tiny_rembert_config()]
            .into_iter()
            .enumerate()
        {
            let model_type = value["model_type"]
                .as_str()
                .context("tiny factorized BERT-family config is missing model_type")?
                .to_owned();
            let mut graph = tiny_bert_family_vulkan_graph(device.clone(), value)?;
            let mut config =
                VulkanTransformerLoraConfig::causal_lm(2, 4, vec!["query".to_owned()], false)?;
            config.task_type = "FEATURE_EXTRACTION".to_owned();
            config.bias = "all".to_owned();
            graph.enable_lora(config, 79 + case_index as u64)?;

            let embedding_weight_before = graph.shared_embedding.weights()?;
            let projection = graph.embedding_project.as_ref().with_context(|| {
                format!("tiny {model_type} graph is missing embedding projection")
            })?;
            assert!(!projection.train_base);
            assert!(projection.train_bias);
            let projection_weight_before = projection.weight.read()?;
            let projection_bias_before = projection.bias.read()?;

            let input_ids = [1, 2, 3, 4, 5, 6, 7, 8];
            let targets = [2, 3, 4, 5, 6, 7, 8, 9];
            let attention_mask = [1.0; 8];
            let loss_weights = [1.0; 8];
            let result = graph.train_step(
                &input_ids,
                &targets,
                &attention_mask,
                &loss_weights,
                AdamWHyperParams {
                    lr: 5.0e-3,
                    weight_decay: 0.0,
                    ..AdamWHyperParams::default()
                },
            )?;
            assert!(
                result.loss.is_finite(),
                "{model_type} loss must remain finite"
            );

            let projection = graph
                .embedding_project
                .as_ref()
                .with_context(|| format!("tiny {model_type} graph lost embedding projection"))?;
            assert_eq!(
                projection.weight.read()?,
                projection_weight_before,
                "{model_type} frozen projection weight changed"
            );
            assert_ne!(
                projection.bias.read()?,
                projection_bias_before,
                "{model_type} projection bias did not train"
            );
            assert_eq!(
                graph.shared_embedding.weights()?,
                embedding_weight_before,
                "{model_type} frozen shared embedding changed"
            );
        }
        Ok(())
    }

    #[test]
    fn bias_all_trains_bert_embedding_prediction_and_decoder_biases_without_base_weights(
    ) -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut graph = tiny_bert_vulkan_graph(device)?;
        let mut config =
            VulkanTransformerLoraConfig::causal_lm(2, 4, vec!["query".to_owned()], false)?;
        config.task_type = "FEATURE_EXTRACTION".to_owned();
        config.bias = "all".to_owned();
        graph.enable_lora(config, 61)?;

        let embedding_weight_before = graph.shared_embedding.weights()?;
        let embedding_bias_before = graph
            .embedding_norm
            .as_ref()
            .context("tiny BERT graph is missing embedding LayerNorm")?
            .bias
            .read()?;
        let prediction_weight_before = graph
            .prediction_head
            .as_ref()
            .context("tiny BERT graph is missing prediction head")?
            .dense
            .weight
            .read()?;
        let prediction_bias_before = graph
            .prediction_head
            .as_ref()
            .context("tiny BERT graph is missing prediction head")?
            .dense
            .bias
            .read()?;
        let decoder_bias_before = graph
            .lm_head_bias
            .as_ref()
            .context("tiny BERT graph is missing tied MLM decoder bias")?
            .read()?;

        let input_ids = [1, 2, 3, 4, 5, 6, 7, 8];
        let targets = [2, 3, 4, 5, 6, 7, 8, 9];
        let attention_mask = [1.0; 8];
        let loss_weights = [1.0; 8];
        let result = graph.train_step(
            &input_ids,
            &targets,
            &attention_mask,
            &loss_weights,
            AdamWHyperParams {
                lr: 5.0e-3,
                weight_decay: 0.0,
                ..AdamWHyperParams::default()
            },
        )?;
        assert!(result.loss.is_finite());

        assert_eq!(graph.shared_embedding.weights()?, embedding_weight_before);
        assert_eq!(
            graph
                .prediction_head
                .as_ref()
                .context("tiny BERT graph is missing prediction head")?
                .dense
                .weight
                .read()?,
            prediction_weight_before
        );
        assert_ne!(
            graph
                .embedding_norm
                .as_ref()
                .context("tiny BERT graph is missing embedding LayerNorm")?
                .bias
                .read()?,
            embedding_bias_before
        );
        assert_ne!(
            graph
                .prediction_head
                .as_ref()
                .context("tiny BERT graph is missing prediction head")?
                .dense
                .bias
                .read()?,
            prediction_bias_before
        );
        assert_ne!(
            graph
                .lm_head_bias
                .as_ref()
                .context("tiny BERT graph is missing tied MLM decoder bias")?
                .read()?,
            decoder_bias_before
        );
        Ok(())
    }

    #[test]
    fn bias_all_round_trips_dense_jais2_attention_mlp_and_norm_biases() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut graph = tiny_jais2_vulkan_graph(device.clone())?;
        let mut config =
            VulkanTransformerLoraConfig::causal_lm(2, 4, vec!["q_proj".to_owned()], false)?;
        config.bias = "all".to_owned();
        assert_eq!(graph.enable_lora(config, 41)?, graph.layers.len());

        assert!(graph.layers[0].ln1.train_bias);
        assert!(graph.layers[0].ln2.train_bias);
        assert!(
            graph.layers[0]
                .q_proj
                .as_ref()
                .context("tiny Jais2 graph is missing q_proj")?
                .train_bias
        );
        assert!(graph.layers[0].c_fc.train_bias);
        assert!(graph.layers[0].c_mlp_proj.train_bias);
        assert!(graph.final_norm.train_bias);

        let fill = |len: usize, base: f32| {
            (0..len)
                .map(|index| base + index as f32 * 0.00013)
                .collect::<Vec<_>>()
        };
        let d = graph.config.hidden_size;
        let i = graph.config.intermediate_size;
        let q = graph.config.query_hidden_size();
        let kv = graph.config.key_value_hidden_size();
        for (layer_index, layer) in graph.layers.iter_mut().enumerate() {
            let base = 3.0 + layer_index as f32;
            layer.ln1.bias = TrainableParameter::new(&device, &fill(d, base + 0.01), false)?;
            layer
                .q_proj
                .as_mut()
                .context("tiny Jais2 graph is missing q_proj")?
                .bias = TrainableParameter::new(&device, &fill(q, base + 0.02), false)?;
            layer
                .k_proj
                .as_mut()
                .context("tiny Jais2 graph is missing k_proj")?
                .bias = TrainableParameter::new(&device, &fill(kv, base + 0.03), false)?;
            layer
                .v_proj
                .as_mut()
                .context("tiny Jais2 graph is missing v_proj")?
                .bias = TrainableParameter::new(&device, &fill(kv, base + 0.04), false)?;
            layer.c_proj.bias = TrainableParameter::new(&device, &fill(d, base + 0.05), false)?;
            layer.ln2.bias = TrainableParameter::new(&device, &fill(d, base + 0.06), false)?;
            layer.c_fc.bias = TrainableParameter::new(&device, &fill(i, base + 0.07), false)?;
            layer.c_mlp_proj.bias = TrainableParameter::new(&device, &fill(d, base + 0.08), false)?;
        }
        graph.final_norm.bias = TrainableParameter::new(&device, &fill(d, 8.25), false)?;

        let expected_biases = graph
            .llama_parameter_tensors()?
            .into_iter()
            .filter(|(name, _)| name.ends_with(".bias"))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(expected_biases.len(), graph.layers.len() * 8 + 1);

        let test_dir = std::env::temp_dir().join(format!(
            "hierarchos-vulkan-lora-bias-all-jais2-roundtrip-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_nanos()
        ));
        graph.export_lora_adapter(&test_dir)?;
        let weights_path = test_dir.join(VULKAN_TRANSFORMER_ADAPTER_WEIGHTS_FILENAME);
        let bytes = fs::read(&weights_path)?;
        let tensors = SafeTensors::deserialize(&bytes)?;
        let lora_config = graph
            .lora_config()
            .context("Jais2 graph is missing LoRA config")?;
        for name in expected_biases.keys() {
            let module = name
                .strip_suffix(".bias")
                .context("Jais2 expected bias lost .bias suffix")?;
            let adapter_name = if lora_config.targets(module) {
                peft_saved_lora_base_bias_tensor_key(module)
            } else {
                format!("base_model.model.{name}")
            };
            assert!(
                tensors
                    .names()
                    .iter()
                    .any(|candidate| *candidate == adapter_name),
                "adapter is missing {adapter_name}"
            );
        }

        let mut reloaded = tiny_jais2_vulkan_graph(device)?;
        assert_eq!(
            reloaded.load_lora_adapter(&test_dir)?,
            reloaded.layers.len()
        );
        let actual_biases = reloaded
            .llama_parameter_tensors()?
            .into_iter()
            .filter(|(name, _)| name.ends_with(".bias"))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(actual_biases, expected_biases);

        fs::remove_dir_all(&test_dir)?;
        Ok(())
    }

