        assert_eq!(reloaded.layers[0].ln1.bias.read()?, expected_layer_bias);
        assert_eq!(reloaded.final_norm.weight.read()?, expected_final_weight);
        assert_eq!(reloaded.final_norm.bias.read()?, expected_final_bias);

        fs::remove_dir_all(&test_dir)?;
