    #[test]
    fn generation_classifier_free_guidance_matches_hf_log_probability_formula() -> Result<()> {
        let conditional_logits = [1.5_f32, -0.25, 3.0, 0.75];
        let unconditional_logits = [-0.5_f32, 1.25, 0.5, 2.0];
        let scale = 1.75_f32;
        let conditional = generation_log_softmax(&conditional_logits)?;
        let unconditional = generation_log_softmax(&unconditional_logits)?;
        let guided = generation_classifier_free_guidance_scores(
            &conditional_logits,
            &unconditional_logits,
            scale,
        )?;
        for index in 0..guided.len() {
            let expected =
                unconditional[index] + scale * (conditional[index] - unconditional[index]);
            assert!((guided[index] - expected).abs() < 1.0e-6);
        }
        Ok(())
    }

    #[test]
    fn gpt2_cfg_scores_negative_prompt_and_cache_match_full_prefix() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        let prompt = [3_u32, 7, 11];
        let negative_prompt = [5_u32, 9];
        let negative_mask = [1.0_f32, 1.0];
        let config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(3),
            guidance_scale: Some(1.5),
            output_scores: true,
            output_logits: true,
            return_dict_in_generate: true,
            ..VulkanTransformerGenerationConfig::default()
        };

        let output = graph.generate_output_with_negative_prompt(
            &prompt,
            &config,
            &negative_prompt,
            Some(&negative_mask),
        )?;
        let sequence = output
            .sequences
            .first()
            .context("missing CFG output sequence")?;
        let conditional_logits = graph.generation_last_logits(&prompt, None, None)?;
        let unconditional_logits = graph.generation_last_logits_with_attention_mask(
            &negative_prompt,
            &negative_mask,
            None,
            None,
        )?;
        let expected_scores = generation_classifier_free_guidance_scores(
            &conditional_logits,
            &unconditional_logits,
            1.5,
        )?;
        let first_scores = sequence
            .scores
            .as_ref()
            .and_then(|scores| scores.first())
            .context("missing first CFG score row")?;
        assert_eq!(first_scores.len(), expected_scores.len());
        assert!(first_scores
            .iter()
            .zip(&expected_scores)
            .all(|(actual, expected)| (*actual - *expected).abs() < 1.0e-5));
        let first_logits = sequence
            .logits
            .as_ref()
            .and_then(|logits| logits.first())
            .context("missing first raw-logit row")?;
        assert_eq!(first_logits, &conditional_logits);

        let cached = graph.generate_ids_with_negative_prompt(
            &prompt,
            &config,
            &negative_prompt,
            Some(&negative_mask),
        )?;
        let full_prefix_config = VulkanTransformerGenerationConfig {
            use_cache: false,
            ..config.clone()
        };
        let full_prefix = graph.generate_ids_with_negative_prompt(
            &prompt,
            &full_prefix_config,
            &negative_prompt,
            Some(&negative_mask),
        )?;
        assert_eq!(cached, full_prefix);

        let beam_config = VulkanTransformerGenerationConfig {
            num_beams: 3,
            num_return_sequences: 2,
            output_scores: true,
            output_logits: true,
            ..config.clone()
        };
        let cached_beams = graph.generate_sequences_ids_with_negative_prompt(
            &prompt,
            &beam_config,
            &negative_prompt,
            Some(&negative_mask),
        )?;
        let full_prefix_beam_config = VulkanTransformerGenerationConfig {
            use_cache: false,
            ..beam_config.clone()
        };
        let full_prefix_beams = graph.generate_sequences_ids_with_negative_prompt(
            &prompt,
            &full_prefix_beam_config,
            &negative_prompt,
            Some(&negative_mask),
        )?;
        assert_eq!(cached_beams, full_prefix_beams);
        Ok(())
    }

