    #[test]
    fn hf_generation_config_accepts_scalar_eos_and_beam_sampling() -> Result<()> {
        let config = VulkanTransformerGenerationConfig::from_hf_value(&serde_json::json!({
            "eos_token_id": 7,
            "max_new_tokens": 4
        }))?;
        assert_eq!(config.eos_token_ids, vec![7]);

        let sampled_beams = VulkanTransformerGenerationConfig::from_hf_value(&serde_json::json!({
            "max_new_tokens": 4,
            "do_sample": true,
            "num_beams": 2,
            "temperature": 0.8,
            "top_k": 9,
            "top_p": 0.9,
            "seed": 123
        }))?;
        assert!(sampled_beams.do_sample);
        assert_eq!(sampled_beams.num_beams, 2);
        assert_eq!(sampled_beams.top_k, 9);
        assert!((sampled_beams.top_p - 0.9).abs() < 1.0e-6);
        assert_eq!(sampled_beams.seed, 123);

        let canonical_beam_search =
            VulkanTransformerGenerationConfig::from_hf_value(&serde_json::json!({
                "max_new_tokens": 4,
                "num_beams": 2,
                "early_stopping": "never"
            }))?;
        assert!(!canonical_beam_search.early_stopping);
        assert!(canonical_beam_search.early_stopping_never);

        let nullable_current_hf =
            VulkanTransformerGenerationConfig::from_hf_value(&serde_json::json!({
                    "max_new_tokens": 4,
                    "do_sample": null,
                    "use_cache": false,
                    "temperature": null,
                    "top_k": null,
                    "top_p": null,
                    "num_beams": null,
                    "early_stopping": null,
                "renormalize_logits": true,
                "remove_invalid_values": true,
                "exponential_decay_length_penalty": [5, 1.1],
                "seed": null
            }))?;
        assert!(!nullable_current_hf.do_sample);
        assert!(!nullable_current_hf.use_cache);
        assert_eq!(nullable_current_hf.temperature, 1.0);
        assert_eq!(nullable_current_hf.top_k, 50);
        assert_eq!(nullable_current_hf.top_p, 1.0);
        assert_eq!(nullable_current_hf.num_beams, 1);
        assert!(!nullable_current_hf.early_stopping);
        assert!(!nullable_current_hf.early_stopping_never);
        assert!(nullable_current_hf.renormalize_logits);
        assert!(nullable_current_hf.remove_invalid_values);
        assert_eq!(
            nullable_current_hf.exponential_decay_length_penalty,
            Some((5, 1.1))
        );
        Ok(())
    }

