    #[test]
    fn generation_mode_dispatch_matches_current_hf_generation_config() -> Result<()> {
        let cases = [
            (
                serde_json::json!({"max_new_tokens": 2}),
                VulkanTransformerGenerationMode::GreedySearch,
            ),
            (
                serde_json::json!({"max_new_tokens": 2, "do_sample": true}),
                VulkanTransformerGenerationMode::Sample,
            ),
            (
                serde_json::json!({"max_new_tokens": 2, "num_beams": 4}),
                VulkanTransformerGenerationMode::BeamSearch,
            ),
            (
                serde_json::json!({"max_new_tokens": 2, "num_beams": 4, "do_sample": true}),
                VulkanTransformerGenerationMode::BeamSample,
            ),
            (
                serde_json::json!({"max_new_tokens": 2, "top_k": 4, "penalty_alpha": 0.6}),
                VulkanTransformerGenerationMode::ContrastiveSearch,
            ),
            (
                serde_json::json!({
                    "max_new_tokens": 2,
                    "num_beams": 4,
                    "num_beam_groups": 2,
                    "diversity_penalty": 0.5
                }),
                VulkanTransformerGenerationMode::GroupBeamSearch,
            ),
            (
                serde_json::json!({
                    "max_new_tokens": 2,
                    "num_beams": 4,
                    "force_words_ids": [[7, 8]]
                }),
                VulkanTransformerGenerationMode::ConstrainedBeamSearch,
            ),
            (
                serde_json::json!({"max_new_tokens": 2, "prompt_lookup_num_tokens": 4}),
                VulkanTransformerGenerationMode::AssistedGeneration,
            ),
            (
                serde_json::json!({"max_new_tokens": 2, "dola_layers": "low"}),
                VulkanTransformerGenerationMode::DolaGeneration,
            ),
        ];
        for (value, expected) in cases {
            let config = VulkanTransformerGenerationConfig::from_hf_value(&value)?;
            assert_eq!(config.generation_mode(), expected, "config: {value}");
        }

        let assisted_wins_before_dola =
            VulkanTransformerGenerationConfig::from_hf_value(&serde_json::json!({
                "max_new_tokens": 2,
                "use_mtp": true,
                "dola_layers": [0, 1]
            }))?;
        assert_eq!(
            assisted_wins_before_dola.generation_mode(),
            VulkanTransformerGenerationMode::AssistedGeneration
        );
        Ok(())
    }

