    #[test]
    fn early_exit_generation_config_matches_hf_assistant_defaults_and_validation() -> Result<()> {
        let defaults = VulkanTransformerGenerationConfig::default();
        assert_eq!(defaults.num_assistant_tokens, 20);
        assert_eq!(defaults.num_assistant_tokens_schedule, "constant");
        assert_eq!(defaults.assistant_confidence_threshold, Some(0.4));
        assert_eq!(defaults.assistant_ensemble_weight, None);

        let config = VulkanTransformerGenerationConfig::from_hf_value(&serde_json::json!({
            "max_new_tokens": 5,
            "assistant_early_exit": 1,
            "num_assistant_tokens": 3,
            "num_assistant_tokens_schedule": "heuristic",
            "assistant_confidence_threshold": 0.25,
            "assistant_ensemble_weight": 0.35
        }))?;
        assert_eq!(config.assistant_early_exit, Some(1));
        assert_eq!(config.num_assistant_tokens, 3);
        assert_eq!(config.num_assistant_tokens_schedule, "heuristic");
        assert_eq!(config.assistant_confidence_threshold, Some(0.25));
        assert_eq!(config.assistant_ensemble_weight, Some(0.35));
        assert_eq!(
            config.generation_mode(),
            VulkanTransformerGenerationMode::AssistedGeneration
        );
        config.validate()?;
        config.validate_supported_generation_mode()?;

        for (invalid, expected) in [
            (
                VulkanTransformerGenerationConfig {
                    num_assistant_tokens: 0,
                    ..VulkanTransformerGenerationConfig::default()
                },
                "num_assistant_tokens must be positive",
            ),
            (
                VulkanTransformerGenerationConfig {
                    num_assistant_tokens_schedule: "adaptive-magic".to_owned(),
                    ..VulkanTransformerGenerationConfig::default()
                },
                "num_assistant_tokens_schedule",
            ),
            (
                VulkanTransformerGenerationConfig {
                    assistant_confidence_threshold: Some(1.5),
                    ..VulkanTransformerGenerationConfig::default()
                },
                "assistant_confidence_threshold",
            ),
            (
                VulkanTransformerGenerationConfig {
                    assistant_early_exit: Some(0),
                    ..VulkanTransformerGenerationConfig::default()
                },
                "assistant_early_exit must be positive",
            ),
            (
                VulkanTransformerGenerationConfig {
                    assistant_ensemble_weight: Some(0.0),
                    ..VulkanTransformerGenerationConfig::default()
                },
                "assistant_ensemble_weight",
            ),
            (
                VulkanTransformerGenerationConfig {
                    assistant_ensemble_weight: Some(1.0),
                    ..VulkanTransformerGenerationConfig::default()
                },
                "assistant_ensemble_weight",
            ),
        ] {
            let error = invalid.validate().expect_err(expected).to_string();
            assert!(error.contains(expected), "unexpected error: {error}");
        }

        let prompt_lookup_ensemble = VulkanTransformerGenerationConfig {
            prompt_lookup_num_tokens: Some(3),
            assistant_ensemble_weight: Some(0.5),
            ..VulkanTransformerGenerationConfig::default()
        };
        let error = prompt_lookup_ensemble
            .validate_supported_generation_mode()
            .expect_err("prompt lookup has no candidate logits to ensemble")
            .to_string();
        assert!(error.contains("not supported with prompt lookup decoding"));
        Ok(())
    }

    #[test]
    fn speculative_sampling_acceptance_and_correction_match_lossless_contract() -> Result<()> {
        let accepted = generation_speculative_sample(
            &[0],
            &[vec![10.0, -10.0]],
            &[vec![10.0, -10.0], vec![-10.0, 10.0]],
            false,
            None,
            7,
            0,
        )?;
        assert_eq!(accepted.0, vec![0, 1]);
        assert_eq!(accepted.1, 1);

        let rejected = generation_speculative_sample(
            &[0],
            &[vec![10.0, -10.0]],
            &[vec![-10.0, 10.0], vec![10.0, -10.0]],
            false,
            None,
            7,
            0,
        )?;
        assert_eq!(rejected.0, vec![1]);
        assert_eq!(rejected.1, 0);

        let ensembled = generation_speculative_sample(
            &[0],
            &[vec![10.0, -10.0]],
            &[vec![-10.0, 10.0], vec![-10.0, 10.0]],
            false,
            Some(0.01),
            7,
            0,
        )?;
        assert_eq!(ensembled.0, vec![0, 1]);
        assert_eq!(ensembled.1, 1);

        assert_eq!(
            generation_ensemble_argmax(&[-10.0, 10.0], &[10.0, -10.0], 0.25)?,
            0
        );
        assert_eq!(
            generation_ensemble_argmax(&[-10.0, 10.0], &[10.0, -10.0], 0.75)?,
            1
        );
        Ok(())
    }

    #[test]
    fn gpt2_early_exit_assisted_generation_matches_target_and_supports_sampling_outputs_and_streaming(
    ) -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        let prompt = [3_u32, 7, 11];

        let early_logits = graph.generation_last_logits_with_layer_count(&prompt, 1)?;
        let full_logits = graph.generation_last_logits(&prompt, None, None)?;
        assert_eq!(early_logits.len(), full_logits.len());
        assert!(
            early_logits
                .iter()
                .zip(&full_logits)
                .any(|(early, full)| (early - full).abs() > 1.0e-7),
            "the early-exit draft must actually stop before the final decoder layer"
        );

        let assisted = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(3),
            assistant_early_exit: Some(1),
            num_assistant_tokens: 2,
            num_assistant_tokens_schedule: "heuristic_transient".to_owned(),
            assistant_confidence_threshold: None,
            output_scores: true,
            output_logits: true,
            output_hidden_states: true,
            return_dict_in_generate: true,
            ..VulkanTransformerGenerationConfig::default()
        };
        assisted.validate()?;
        assisted.validate_supported_generation_mode()?;

        let reference = graph.generate_ids(
            &prompt,
            &VulkanTransformerGenerationConfig {
                max_new_tokens: assisted.max_new_tokens,
                use_cache: false,
                ..VulkanTransformerGenerationConfig::default()
            },
        )?;
        let generated = graph.generate_ids(&prompt, &assisted)?;
        assert_eq!(generated, reference);

        let output = graph.generate_output(&prompt, &assisted)?;
        assert_eq!(output.sequences.len(), 1);
        let sequence = &output.sequences[0];
        assert_eq!(sequence.generated_ids(), generated.as_slice());
        assert_eq!(
            sequence
                .scores
                .as_ref()
                .context("missing early-exit assisted scores")?
                .len(),
            generated.len()
        );
        assert_eq!(
            sequence
                .logits
                .as_ref()
                .context("missing early-exit assisted logits")?
                .len(),
            generated.len()
        );
        assert_eq!(
            sequence
                .hidden_states
                .as_ref()
                .context("missing early-exit hidden-state trace")?
                .len(),
            generated.len()
        );

        let mut streamed = Vec::new();
        let streaming = graph.generate_ids_streaming(&prompt, &assisted, |token| {
            streamed.push(token);
            Ok(())
        })?;
        assert_eq!(streaming, generated);
        assert_eq!(streamed, generated);

        let sampled = VulkanTransformerGenerationConfig {
            do_sample: true,
            top_k: 8,
            top_p: 0.9,
            seed: 991,
            assistant_confidence_threshold: Some(0.2),
            ..assisted.clone()
        };
        let sampled_once = graph.generate_ids(&prompt, &sampled)?;
        let sampled_twice = graph.generate_ids(&prompt, &sampled)?;
        assert_eq!(sampled_once, sampled_twice);
        assert!(!sampled_once.is_empty());
        assert!(sampled_once.len() <= 3);

        let invalid = VulkanTransformerGenerationConfig {
            assistant_early_exit: Some(3),
            ..assisted
        };
        let error = graph
            .generate_ids(&prompt, &invalid)
            .expect_err("assistant early exit cannot exceed the graph layer count")
            .to_string();
        assert!(
            error.contains("assistant_early_exit 3 must be in 1..=2"),
            "unexpected error: {error}"
        );
        Ok(())
    }

    #[test]
    fn gpt2_early_exit_assisted_generation_supports_encoder_context() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let encoder_seq_len = 3;
        let graph = tiny_gpt2_cross_attention_vulkan_graph(device, encoder_seq_len)?;
        let prompt = [3_u32, 7, 11];
        let hidden = graph.config().hidden_size;
        let encoder_hidden_states = (0..encoder_seq_len * hidden)
            .map(|index| ((index * 13 + 7) % 41) as f32 * 0.01 - 0.2)
            .collect::<Vec<_>>();
        let encoder_attention_mask = [1.0_f32, 1.0, 0.0];

        let alternate_encoder_hidden_states = vec![0.0_f32; encoder_seq_len * hidden];
        let early_with_alternate_context = graph
            .generation_last_logits_with_layer_count_and_context(
                &prompt,
                1,
                Some(&alternate_encoder_hidden_states),
                Some(&encoder_attention_mask),
            )?;
        let early_with_context = graph.generation_last_logits_with_layer_count_and_context(
            &prompt,
            1,
            Some(&encoder_hidden_states),
            Some(&encoder_attention_mask),
        )?;
        assert!(
            early_with_alternate_context
                .iter()
                .zip(&early_with_context)
                .any(|(alternate, with)| (alternate - with).abs() > 1.0e-7),
            "the early-exit draft forward must consume encoder cross-attention context"
        );

        let assisted = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(3),
            assistant_early_exit: Some(1),
            num_assistant_tokens: 2,
            output_scores: true,
            output_attentions: true,
            return_dict_in_generate: true,
            ..VulkanTransformerGenerationConfig::default()
        };
        let reference = graph.generate_ids_with_encoder_hidden_states(
            &prompt,
            &VulkanTransformerGenerationConfig {
                max_new_tokens: assisted.max_new_tokens,
                ..VulkanTransformerGenerationConfig::default()
            },
            &encoder_hidden_states,
            &encoder_attention_mask,
        )?;
        let generated = graph.generate_ids_with_encoder_hidden_states(
            &prompt,
            &assisted,
            &encoder_hidden_states,
            &encoder_attention_mask,
        )?;
        assert_eq!(generated, reference);

        let output = graph.generate_output_with_context(
            &prompt,
            &assisted,
            Some(&encoder_hidden_states),
            Some(&encoder_attention_mask),
        )?;
        let sequence = &output.sequences[0];
        assert_eq!(sequence.generated_ids(), generated.as_slice());
        assert_eq!(
            sequence
                .scores
                .as_ref()
                .context("missing encoder-context early-exit scores")?
                .len(),
            generated.len()
        );
        let cross_attentions = sequence
            .cross_attentions
            .as_ref()
            .context("missing encoder-context early-exit cross attentions")?;
        assert_eq!(cross_attentions.len(), generated.len());
        for step_attentions in cross_attentions {
            for attention in step_attentions {
                for head in 0..attention.num_heads {
                    for query in 0..attention.query_rows {
                        let base = (head * attention.query_rows + query) * attention.key_rows;
                        let row = &attention.values[base..base + attention.key_rows];
                        assert!(row[2].abs() < 1.0e-7, "masked encoder key must stay zero");
                    }
                }
            }
        }

        let mut streamed = Vec::new();
        let streaming = graph.generate_ids_streaming_with_encoder_hidden_states(
            &prompt,
            &assisted,
            &encoder_hidden_states,
            &encoder_attention_mask,
            |token| {
                streamed.push(token);
                Ok(())
            },
        )?;
        assert_eq!(streaming, generated);
        assert_eq!(streamed, generated);
        Ok(())
    }

    #[test]
    fn gpt2_external_assistant_model_matches_target_and_supports_sampling_outputs_and_streaming(
    ) -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let target = tiny_gpt2_vulkan_graph(device.clone())?;
        let assistant = tiny_gpt2_vulkan_graph(device)?;
        let prompt = [3_u32, 7, 11];
        let config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(4),
            num_assistant_tokens: 2,
            num_assistant_tokens_schedule: "heuristic_transient".to_owned(),
            assistant_confidence_threshold: None,
            output_scores: true,
            output_logits: true,
            output_hidden_states: true,
            output_attentions: true,
            return_dict_in_generate: true,
            ..VulkanTransformerGenerationConfig::default()
        };

        let reference = target.generate_ids(
            &prompt,
            &VulkanTransformerGenerationConfig {
                max_new_tokens: config.max_new_tokens,
                ..VulkanTransformerGenerationConfig::default()
            },
        )?;
        let generated = target.generate_ids_with_assistant_model(&prompt, &config, &assistant)?;
        assert_eq!(generated, reference);

        let output = target.generate_output_with_assistant_model(&prompt, &config, &assistant)?;
        assert_eq!(output.sequences.len(), 1);
        let sequence = &output.sequences[0];
        assert_eq!(sequence.generated_ids(), generated.as_slice());
        assert_eq!(
            sequence
                .scores
                .as_ref()
                .context("missing external-assistant scores")?
                .len(),
            generated.len()
        );
        assert_eq!(
            sequence
                .logits
                .as_ref()
                .context("missing external-assistant logits")?
                .len(),
            generated.len()
        );
        assert_eq!(
            sequence
                .hidden_states
                .as_ref()
                .context("missing external-assistant hidden states")?
                .len(),
            generated.len()
        );
        assert_eq!(
            sequence
                .attentions
                .as_ref()
                .context("missing external-assistant attentions")?
                .len(),
            generated.len()
        );

        let mut streamed = Vec::new();
        let streaming = target.generate_ids_streaming_with_assistant_model(
            &prompt,
            &config,
            &assistant,
            |token| {
                streamed.push(token);
                Ok(())
            },
        )?;
        assert_eq!(streaming, generated);
        assert_eq!(streamed, generated);

        let sampled = VulkanTransformerGenerationConfig {
            do_sample: true,
            top_k: 8,
            top_p: 0.9,
            seed: 4421,
            assistant_confidence_threshold: Some(0.2),
            output_attentions: false,
            ..config.clone()
        };
        let sampled_once =
            target.generate_ids_with_assistant_model(&prompt, &sampled, &assistant)?;
        let sampled_twice =
            target.generate_ids_with_assistant_model(&prompt, &sampled, &assistant)?;
        assert_eq!(sampled_once, sampled_twice);
        assert!(!sampled_once.is_empty());
        assert!(sampled_once.len() <= 4);

        let invalid_return_count = VulkanTransformerGenerationConfig {
            do_sample: true,
            num_return_sequences: 2,
            ..config.clone()
        };
        let error = target
            .generate_ids_with_assistant_model(&prompt, &invalid_return_count, &assistant)
            .expect_err("assisted generation must reject multiple return sequences")
            .to_string();
        assert!(error.contains("num_return_sequences has to be 1"));

        let no_cache = VulkanTransformerGenerationConfig {
            use_cache: false,
            ..config.clone()
        };
        let error = target
            .generate_ids_with_assistant_model(&prompt, &no_cache, &assistant)
            .expect_err("assisted generation requires cache semantics")
            .to_string();
        assert!(error.contains("use_cache=true"));

        let beam = VulkanTransformerGenerationConfig {
            num_beams: 2,
            ..config
        };
        let error = target
            .generate_ids_with_assistant_model(&prompt, &beam, &assistant)
            .expect_err("external assistance only extends greedy/sample modes")
            .to_string();
        assert!(error.contains("greedy or sampling base mode"));
        Ok(())
    }

