    #[test]
    fn dola_contrast_math_matches_relative_top_and_js_layer_selection() -> Result<()> {
        let final_logits = vec![3.0_f32, 1.5, 0.5, -1.0];
        let identical = final_logits.clone();
        let opposite = vec![-1.0_f32, 0.5, 1.5, 3.0];

        let identical_contrast =
            generation_dola_select_contrast(&[(1, identical.clone())], &final_logits)?;
        for value in identical_contrast {
            if value.is_finite() {
                assert!(
                    value.abs() <= 1.0e-6,
                    "identical distributions should have zero contrast"
                );
            }
        }

        let selected = generation_dola_select_contrast(
            &[(1, identical), (3, opposite.clone())],
            &final_logits,
        )?;
        let expected = generation_dola_select_contrast(&[(3, opposite)], &final_logits)?;
        assert_eq!(selected.len(), expected.len());
        for (actual, expected) in selected.iter().zip(&expected) {
            if expected.is_infinite() {
                assert_eq!(*actual, *expected);
            } else {
                assert!((actual - expected).abs() <= 1.0e-6);
            }
        }
        Ok(())
    }

    #[test]
    fn gpt2_dola_generation_supports_outputs_streaming_and_explicit_layers() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        let prompt = [3_u32, 7, 11];
        let config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(3),
            dola_layers: Some(serde_json::json!("low")),
            output_scores: true,
            output_logits: true,
            output_hidden_states: true,
            return_dict_in_generate: true,
            ..VulkanTransformerGenerationConfig::default()
        };
        config.validate()?;
        config.validate_supported_generation_mode()?;

        let generated = graph.generate_ids(&prompt, &config)?;
        let explicit = graph.generate_ids(
            &prompt,
            &VulkanTransformerGenerationConfig {
                dola_layers: Some(serde_json::json!([1])),
                ..config.clone()
            },
        )?;
        assert_eq!(generated, explicit);

        let output = graph.generate_output(&prompt, &config)?;
        assert_eq!(output.sequences.len(), 1);
        let sequence = &output.sequences[0];
        assert_eq!(sequence.generated_ids(), generated.as_slice());
        let scores = sequence.scores.as_ref().context("missing DoLa scores")?;
        let logits = sequence
            .logits
            .as_ref()
            .context("missing DoLa mature logits")?;
        let hidden_states = sequence
            .hidden_states
            .as_ref()
            .context("missing DoLa hidden-state trace")?;
        assert_eq!(scores.len(), generated.len());
        assert_eq!(logits.len(), generated.len());
        assert_eq!(hidden_states.len(), generated.len());

        let mut prefix = prompt.to_vec();
        for (step, token) in generated.iter().copied().enumerate() {
            let reference_logits = graph.generation_last_logits(&prefix, None, None)?;
            assert_eq!(logits[step].len(), reference_logits.len());
            for (actual, expected) in logits[step].iter().zip(reference_logits) {
                assert!((actual - expected).abs() <= 1.0e-5);
            }
            prefix.push(token);
        }

        let mut streamed = Vec::new();
        let streaming = graph.generate_ids_streaming(&prompt, &config, |token| {
            streamed.push(token);
            Ok(())
        })?;
        assert_eq!(streaming, generated);
        assert_eq!(streamed, generated);

        let encoder_error = graph
            .generate_ids_with_context(&prompt, &config, Some(&[0.0]), Some(&[1.0]))
            .expect_err("DoLa must reject encoder context")
            .to_string();
        assert!(
            encoder_error.contains("decoder-only"),
            "unexpected DoLa encoder error: {encoder_error}"
        );
        Ok(())
    }

    #[test]
    fn prompt_lookup_candidates_match_hf_longest_suffix_eos_and_open_ended_behavior() -> Result<()>
    {
        let base = VulkanTransformerGenerationConfig {
            prompt_lookup_num_tokens: Some(4),
            max_matching_ngram_size: Some(2),
            max_new_tokens: Some(8),
            ..VulkanTransformerGenerationConfig::default()
        };

        // Longest suffix match wins and the first valid occurrence is used.
        let history = [4_u32, 5, 8, 9, 4, 5];
        assert_eq!(
            generation_prompt_lookup_candidates(&history, 2, 14, 32, &base)?,
            vec![8, 9, 4, 5]
        );

        // Match HF's EOS cropping: EOS itself is not proposed, and an EOS as
        // the first continuation produces an unchanged candidate sequence.
        let eos_config = VulkanTransformerGenerationConfig {
            eos_token_ids: vec![0],
            max_matching_ngram_size: Some(1),
            ..base.clone()
        };
        let eos_history = [6_u32, 7, 8, 51, 0, 10, 11, 12, 13, 51];
        assert!(
            generation_prompt_lookup_candidates(&eos_history, 1, 18, 64, &eos_config)?.is_empty()
        );

        let no_eos = VulkanTransformerGenerationConfig {
            eos_token_ids: Vec::new(),
            ..eos_config
        };
        assert_eq!(
            generation_prompt_lookup_candidates(&eos_history, 1, 18, 64, &no_eos)?,
            vec![0, 10, 11, 12]
        );
        Ok(())
    }

    #[test]
    fn prompt_lookup_generation_config_and_validation_match_hf_contract() -> Result<()> {
        let config = VulkanTransformerGenerationConfig::from_hf_value(&serde_json::json!({
            "max_new_tokens": 5,
            "prompt_lookup_num_tokens": 4,
            "max_matching_ngram_size": 3,
            "use_cache": true
        }))?;
        assert_eq!(config.prompt_lookup_num_tokens, Some(4));
        assert_eq!(config.max_matching_ngram_size, Some(3));
        assert_eq!(
            config.generation_mode(),
            VulkanTransformerGenerationMode::AssistedGeneration
        );
        config.validate_supported_generation_mode()?;

        for (invalid, expected) in [
            (
                VulkanTransformerGenerationConfig {
                    prompt_lookup_num_tokens: Some(0),
                    ..VulkanTransformerGenerationConfig::default()
                },
                "prompt_lookup_num_tokens must be positive",
            ),
            (
                VulkanTransformerGenerationConfig {
                    prompt_lookup_num_tokens: Some(4),
                    max_matching_ngram_size: Some(0),
                    ..VulkanTransformerGenerationConfig::default()
                },
                "max_matching_ngram_size must be positive",
            ),
        ] {
            assert!(
                invalid
                    .validate()
                    .unwrap_err()
                    .to_string()
                    .contains(expected),
                "unexpected validation result for {expected}"
            );
        }

        let no_cache = VulkanTransformerGenerationConfig {
            prompt_lookup_num_tokens: Some(4),
            use_cache: false,
            ..VulkanTransformerGenerationConfig::default()
        };
        assert!(no_cache
            .validate_supported_generation_mode()
            .unwrap_err()
            .to_string()
            .contains("use_cache=true"));

        let sampled_multiple = VulkanTransformerGenerationConfig {
            prompt_lookup_num_tokens: Some(4),
            do_sample: true,
            num_return_sequences: 2,
            ..VulkanTransformerGenerationConfig::default()
        };
        assert!(sampled_multiple
            .validate_supported_generation_mode()
            .unwrap_err()
            .to_string()
            .contains("num_return_sequences=1"));
        Ok(())
    }

