    #[test]
    fn constrained_generation_state_matches_hf_progress_and_reset_semantics() -> Result<()> {
        let constraints =
            generation_parse_force_words_ids(&serde_json::json!([[4, 5], [[7, 8], [9, 10, 11]]]))?;

        let start = VulkanGenerationConstraintListState::from_history(&constraints, &[1, 2]);
        assert_eq!(start.advance_tokens(), vec![4, 7, 9]);
        assert_eq!(start.bank(), 0);

        let phrase_progress =
            VulkanGenerationConstraintListState::from_history(&constraints, &[1, 4]);
        assert_eq!(phrase_progress.advance_tokens(), vec![5]);
        assert_eq!(phrase_progress.bank(), 2);

        let phrase_reset =
            VulkanGenerationConstraintListState::from_history(&constraints, &[1, 4, 6]);
        assert_eq!(phrase_reset.advance_tokens(), vec![7, 9, 4]);
        assert_eq!(phrase_reset.bank(), 0);

        let first_complete =
            VulkanGenerationConstraintListState::from_history(&constraints, &[1, 4, 5]);
        assert_eq!(first_complete.advance_tokens(), vec![7, 9]);
        assert_eq!(first_complete.bank(), 3);

        let all_complete = VulkanGenerationConstraintListState::from_history(
            &constraints,
            &[1, 4, 5, 2, 9, 10, 11],
        );
        assert!(all_complete.is_completed());
        assert_eq!(all_complete.advance_tokens(), Vec::<u32>::new());
        assert_eq!(all_complete.bank(), 6);
        Ok(())
    }

    #[test]
    fn constrained_beam_step_interleaves_constraint_progress_like_hf() -> Result<()> {
        let constraints = generation_parse_force_words_ids(&serde_json::json!([[30, 31]]))?;
        let config = VulkanTransformerGenerationConfig {
            num_beams: 4,
            num_return_sequences: 2,
            force_words_ids: Some(serde_json::json!([[30, 31]])),
            ..VulkanTransformerGenerationConfig::default()
        };

        let mut first_scores = vec![-10.0_f32; 32];
        first_scores[3] = -0.01;
        first_scores[4] = -0.02;
        first_scores[5] = -0.03;
        first_scores[6] = -0.04;
        first_scores[30] = -6.0;
        let (first, completed) = generation_select_constrained_beam_step(
            &[vec![3, 7, 11]],
            &[0.0],
            &[first_scores],
            &constraints,
            &config,
            0,
        )?;
        assert!(completed.is_empty());
        assert_eq!(first.len(), config.num_beams);
        assert!(
            first.iter().any(|candidate| candidate.token == 30),
            "the first forced-phrase token was displaced from the constrained beam set: {first:?}"
        );

        let histories = first
            .iter()
            .map(|candidate| {
                let mut history = vec![3, 7, 11];
                history.push(candidate.token);
                history
            })
            .collect::<Vec<_>>();
        let accumulated_scores = first
            .iter()
            .map(|candidate| candidate.score)
            .collect::<Vec<_>>();
        let second_scores = histories
            .iter()
            .map(|history| {
                let mut scores = vec![-10.0_f32; 32];
                scores[3] = -0.01;
                scores[4] = -0.02;
                scores[5] = -0.03;
                scores[6] = -0.04;
                scores[31] = if history.last() == Some(&30) {
                    -6.0
                } else {
                    -10.0
                };
                scores
            })
            .collect::<Vec<_>>();
        let (second, completed) = generation_select_constrained_beam_step(
            &histories,
            &accumulated_scores,
            &second_scores,
            &constraints,
            &config,
            1,
        )?;
        assert!(completed.is_empty());
        assert!(
            second.iter().any(|candidate| {
                histories[candidate.parent_index].last() == Some(&30) && candidate.token == 31
            }),
            "the completing forced-phrase token was displaced from the constrained beam set: {second:?}"
        );
        Ok(())
    }

    #[test]
    fn gpt2_constrained_beam_forces_phrase_and_kv_cache_matches_full_prefix() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        assert!(graph.supports_generation_kv_cache());
        let prompt = [3_u32, 7, 11];
        let config = VulkanTransformerGenerationConfig {
            // Keep the horizon equal to the phrase length so the regression
            // exercises the actual constraint-progress path rather than HF's
            // documented fallback when a completed low-probability beam is
            // later displaced before finalization.
            max_new_tokens: Some(2),
            num_beams: 4,
            num_return_sequences: 2,
            force_words_ids: Some(serde_json::json!([[30, 31]])),
            ..VulkanTransformerGenerationConfig::default()
        };

        let cached = graph.generate_sequences_ids(&prompt, &config)?;
        let reference = graph.generate_sequences_ids(
            &prompt,
            &VulkanTransformerGenerationConfig {
                use_cache: false,
                ..config.clone()
            },
        )?;
        assert_eq!(cached, reference);
        assert_eq!(cached.len(), config.num_return_sequences);
        assert!(
            cached[0].windows(2).any(|window| window == [30, 31]),
            "highest-ranked constrained output did not contain the forced phrase: {:?}",
            cached[0]
        );
        Ok(())
    }

