    #[test]
    fn gpt2_group_beam_kv_cache_matches_full_prefix_and_structured_output() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        assert!(graph.supports_generation_kv_cache());
        let prompt = [3_u32, 7, 11];
        let config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(3),
            num_beams: 4,
            num_beam_groups: Some(2),
            diversity_penalty: Some(0.75),
            num_return_sequences: 3,
            output_scores: true,
            output_logits: true,
            return_dict_in_generate: true,
            ..VulkanTransformerGenerationConfig::default()
        };

        let cached = graph.generate_sequences_ids(&prompt, &config)?;
        let reference_config = VulkanTransformerGenerationConfig {
            use_cache: false,
            ..config.clone()
        };
        let reference = graph.generate_sequences_ids(&prompt, &reference_config)?;
        assert_eq!(cached, reference);
        assert_eq!(cached.len(), config.num_return_sequences);

        let structured = graph.generate_output(&prompt, &config)?;
        assert_eq!(structured.sequences.len(), cached.len());
        for (sequence, expected) in structured.sequences.iter().zip(&cached) {
            assert_eq!(sequence.generated_ids(), expected);
            assert_eq!(
                sequence
                    .scores
                    .as_ref()
                    .context("missing group-beam scores")?
                    .len(),
                sequence.generated_ids().len()
            );
            assert_eq!(
                sequence
                    .logits
                    .as_ref()
                    .context("missing group-beam logits")?
                    .len(),
                sequence.generated_ids().len()
            );
            let beam_indices = sequence
                .beam_indices
                .as_ref()
                .context("missing group-beam ancestry")?;
            assert_eq!(beam_indices.len(), sequence.generated_ids().len());
            assert!(beam_indices.iter().all(|index| *index < config.num_beams));
            assert!(sequence.sequence_score.unwrap().is_finite());
        }
        Ok(())
    }

