    #[test]
    fn generation_beam_early_stopping_distinguishes_false_true_and_never() {
        let running = vec![VulkanGenerationBeam {
            tokens: vec![1, 2, 3],
            score: -3.0,
        }];
        let completed = vec![
            VulkanGenerationBeam {
                tokens: vec![1, 4],
                score: -0.5,
            },
            VulkanGenerationBeam {
                tokens: vec![1, 5],
                score: -0.6,
            },
        ];

        let heuristic = VulkanTransformerGenerationConfig {
            num_beams: 2,
            length_penalty: 1.0,
            ..VulkanTransformerGenerationConfig::default()
        };
        assert!(generation_beam_should_stop(
            running.iter(),
            &completed,
            1,
            8,
            &heuristic
        ));

        let canonical = VulkanTransformerGenerationConfig {
            early_stopping_never: true,
            ..heuristic.clone()
        };
        assert!(!generation_beam_should_stop(
            running.iter(),
            &completed,
            1,
            8,
            &canonical
        ));

        let immediate = VulkanTransformerGenerationConfig {
            early_stopping: true,
            ..heuristic
        };
        assert!(generation_beam_should_stop(
            running.iter(),
            &completed,
            1,
            8,
            &immediate
        ));
    }

