    #[test]
    fn generation_encoder_no_repeat_ngram_matches_hf_source_ngram_lookup() {
        let encoder_input_ids = [8_u32, 4, 1, 6, 4, 1, 7];
        let history = [2_u32, 9, 4, 1];
        let mut scores = vec![0.0_f32; 12];
        generation_apply_encoder_no_repeat_ngram(&mut scores, &history, &encoder_input_ids, 3);
        for token in [6_usize, 7] {
            assert!(scores[token].is_infinite() && scores[token].is_sign_negative());
        }
        for token in [0_usize, 1, 4, 8, 9, 10, 11] {
            assert_eq!(scores[token], 0.0);
        }

        let mut unigram_scores = vec![0.0_f32; 12];
        generation_apply_encoder_no_repeat_ngram(
            &mut unigram_scores,
            &history,
            &encoder_input_ids,
            1,
        );
        for token in [1_usize, 4, 6, 7, 8] {
            assert!(unigram_scores[token].is_infinite());
        }
    }

    #[test]
    fn generation_encoder_processors_use_original_decoder_only_prompt() -> Result<()> {
        let config = VulkanTransformerGenerationConfig {
            encoder_repetition_penalty: 2.0,
            encoder_no_repeat_ngram_size: 2,
            ..VulkanTransformerGenerationConfig::default()
        };
        // At step 1 the active decoder history is [4, 5, 4], but HF's
        // encoder_input_ids for a decoder-only request remain the original
        // prompt [4, 5]. The suffix [4] therefore bans source continuation 5.
        let logits = vec![1.0_f32; 8];
        let scores = generation_processed_non_beam_scores(&logits, &[4, 5, 4], &config, 1, false)?;
        assert_eq!(scores[4], 2.0);
        assert!(scores[5].is_infinite() && scores[5].is_sign_negative());
        assert_eq!(scores[6], 1.0);
        Ok(())
    }

