    #[test]
    fn generation_forced_bos_and_eos_obey_processor_order() {
        let config = VulkanTransformerGenerationConfig {
            forced_bos_token_id: Some(3),
            forced_eos_token_ids: vec![2, 4],
            suppress_tokens: vec![4],
            begin_suppress_tokens: vec![5],
            ..VulkanTransformerGenerationConfig::default()
        };

        let mut first_scores = vec![0.0f32; 7];
        generation_apply_sequence_constraints(&mut first_scores, &[0], &[], &config, 0, false);
        for (token, score) in first_scores.iter().enumerate() {
            if token == 3 {
                assert_eq!(*score, 0.0);
            } else {
                assert!(score.is_infinite() && score.is_sign_negative());
            }
        }

        let mut second_scores = vec![0.0f32; 7];
        generation_apply_sequence_constraints(&mut second_scores, &[0, 3], &[], &config, 1, false);
        assert!(second_scores[5].is_infinite() && second_scores[5].is_sign_negative());

        let mut final_scores = vec![0.0f32; 7];
        generation_apply_sequence_constraints(&mut final_scores, &[0, 3, 1], &[], &config, 2, true);
        for (token, score) in final_scores.iter().enumerate() {
            if token == 2 {
                assert_eq!(*score, 0.0);
            } else {
                assert!(score.is_infinite() && score.is_sign_negative());
            }
        }
    }

    #[test]
    fn generation_exponential_decay_length_penalty_matches_hf_eos_boost() {
        let penalty = Some((2, 1.5));
        let eos = [1_u32, 3];

        let mut before = vec![2.0, -4.0, 3.0, 5.0];
        generation_apply_exponential_decay_length_penalty(&mut before, 5, 3, &eos, penalty);
        assert_eq!(before, vec![2.0, -4.0, 3.0, 5.0]);

        let mut first = vec![2.0, -4.0, 3.0, 5.0];
        generation_apply_exponential_decay_length_penalty(&mut first, 6, 3, &eos, penalty);
        assert!((first[1] - -2.0).abs() < 1.0e-6);
        assert!((first[3] - 7.5).abs() < 1.0e-6);

        let mut second = vec![2.0, -4.0, 3.0, 5.0];
        generation_apply_exponential_decay_length_penalty(&mut second, 7, 3, &eos, penalty);
        assert!((second[1] - 1.0).abs() < 1.0e-6);
        assert!((second[3] - 11.25).abs() < 1.0e-6);
    }

