    #[test]
    fn generation_sequence_bias_matches_current_hf_prefix_semantics() -> Result<()> {
        let biases = vec![(vec![1, 2], 3.5), (vec![3], -1.25)];

        let mut too_short = vec![0.0f32; 5];
        generation_apply_sequence_bias(&mut too_short, &[1], &biases)?;
        assert_eq!(too_short[2], 0.0);
        assert_eq!(too_short[3], -1.25);

        let mut matching = vec![0.0f32; 5];
        generation_apply_sequence_bias(&mut matching, &[0, 1], &biases)?;
        assert_eq!(matching[2], 3.5);
        assert_eq!(matching[3], -1.25);

        let mut non_matching = vec![0.0f32; 5];
        generation_apply_sequence_bias(&mut non_matching, &[0, 4], &biases)?;
        assert_eq!(non_matching[2], 0.0);
        assert_eq!(non_matching[3], -1.25);

        let error = generation_apply_sequence_bias(&mut [0.0f32; 4], &[0], &[(vec![4], 1.0)])
            .unwrap_err()
            .to_string();
        assert!(error.contains("exceeds model vocabulary size"));
        Ok(())
    }

