    #[test]
    fn gpt2_structured_generation_exposes_hf_style_scores_and_raw_logits() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        let prompt = [3_u32, 7, 11];
        let config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(3),
            do_sample: true,
            top_k: 1,
            num_return_sequences: 2,
            output_scores: true,
            output_logits: true,
            return_dict_in_generate: true,
            seed: 0x57ac_2026,
            ..VulkanTransformerGenerationConfig::default()
        };

        let output = graph.generate_output(&prompt, &config)?;
        let legacy = graph.generate_sequences_ids(&prompt, &config)?;
        assert_eq!(output.sequences.len(), 2);
        assert_eq!(legacy.len(), 2);
        for (sequence_index, sequence) in output.sequences.iter().enumerate() {
            assert_eq!(sequence.prompt_length, prompt.len());
            assert_eq!(&sequence.sequence[..prompt.len()], prompt.as_slice());
            assert_eq!(sequence.generated_ids(), legacy[sequence_index]);
            let scores = sequence.scores.as_ref().context("missing output scores")?;
            let logits = sequence.logits.as_ref().context("missing output logits")?;
            assert_eq!(scores.len(), sequence.generated_ids().len());
            assert_eq!(logits.len(), sequence.generated_ids().len());
            for (step_scores, step_logits) in scores.iter().zip(logits) {
                assert_eq!(step_scores.len(), graph.config().vocab_size);
                assert_eq!(step_logits.len(), graph.config().vocab_size);
                assert_eq!(
                    step_scores.iter().filter(|score| score.is_finite()).count(),
                    1,
                    "top-k=1 should leave exactly one selectable score"
                );
                assert!(step_logits.iter().all(|logit| logit.is_finite()));
            }
        }
        Ok(())
    }

    #[test]
    fn gpt2_structured_generation_exposes_hf_style_hidden_state_shapes() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        let prompt = [3_u32, 7, 11];

        for use_cache in [true, false] {
            let config = VulkanTransformerGenerationConfig {
                max_new_tokens: Some(2),
                use_cache,
                output_hidden_states: true,
                return_dict_in_generate: true,
                ..VulkanTransformerGenerationConfig::default()
            };
            let output = graph.generate_output(&prompt, &config)?;
            let sequence = &output.sequences[0];
            let hidden_states = sequence
                .hidden_states
                .as_ref()
                .context("missing generation hidden states")?;
            assert_eq!(hidden_states.len(), sequence.generated_ids().len());

            for (step, step_states) in hidden_states.iter().enumerate() {
                assert_eq!(step_states.len(), graph.config().num_layers + 1);
                let prefix_len = prompt.len() + step;
                let expected_rows = if use_cache && step > 0 { 1 } else { prefix_len };
                for state in step_states {
                    assert_eq!(state.rows, expected_rows);
                    assert_eq!(state.hidden_size, graph.config().hidden_size);
                    assert_eq!(state.values.len(), expected_rows * state.hidden_size);
                    assert!(state.values.iter().all(|value| value.is_finite()));
                }

                // The final hidden-state slot must agree exactly with the
                // decoder-visible state used by the LM head for the same
                // prefix. This also verifies the cached one-row projection.
                let mut prefix = prompt.to_vec();
                prefix.extend_from_slice(&sequence.generated_ids()[..step]);
                let (_, reference_hidden, reference_width) =
                    graph.generation_last_logits_and_decoder_hidden(&prefix, None, None)?;
                let reference_start = if expected_rows == 1 {
                    (prefix_len - 1) * reference_width
                } else {
                    0
                };
                let reference_end = reference_start + expected_rows * reference_width;
                let final_state = step_states.last().context("missing final hidden state")?;
                assert_eq!(final_state.hidden_size, reference_width);
                assert_eq!(
                    final_state.values,
                    reference_hidden[reference_start..reference_end]
                );
            }
        }
        Ok(())
    }

    #[test]
    fn gpt2_structured_non_beam_attention_outputs_match_vulkan_attention_contract() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        let prompt = [3_u32, 7, 11];

        for use_cache in [true, false] {
            let config = VulkanTransformerGenerationConfig {
                max_new_tokens: Some(2),
                use_cache,
                output_attentions: true,
                return_dict_in_generate: true,
                ..VulkanTransformerGenerationConfig::default()
            };
            let output = graph.generate_output(&prompt, &config)?;
            let sequence = &output.sequences[0];
            let attentions = sequence
                .attentions
                .as_ref()
                .context("missing generation attentions")?;
            assert_eq!(attentions.len(), sequence.generated_ids().len());
            assert!(sequence.cross_attentions.is_none());

            for (step, step_attentions) in attentions.iter().enumerate() {
                assert_eq!(step_attentions.len(), graph.config().num_layers);
                let key_rows = prompt.len() + step;
                let expected_query_rows = if use_cache && step > 0 { 1 } else { key_rows };
                for attention in step_attentions {
                    assert_eq!(attention.query_rows, expected_query_rows);
                    assert_eq!(attention.key_rows, key_rows);
                    assert_eq!(attention.num_heads, graph.config().num_heads);
                    assert_eq!(
                        attention.values.len(),
                        attention.num_heads * attention.query_rows * attention.key_rows
                    );
                    assert!(attention
                        .values
                        .iter()
                        .all(|value| value.is_finite() && *value >= 0.0 && *value <= 1.0));
                    for head in 0..attention.num_heads {
                        for query_row in 0..attention.query_rows {
                            let absolute_query = if use_cache && step > 0 {
                                key_rows - 1
                            } else {
                                query_row
                            };
                            let base =
                                (head * attention.query_rows + query_row) * attention.key_rows;
                            let row = &attention.values[base..base + attention.key_rows];
                            let probability_sum = row.iter().sum::<f32>();
                            assert!(
                                (probability_sum - 1.0).abs() < 1.0e-5,
                                "attention row must normalize: head={head} query={absolute_query} sum={probability_sum}"
                            );
                            assert!(row[absolute_query + 1..]
                                .iter()
                                .all(|probability| probability.abs() < 1.0e-7));
                        }
                    }
                }
            }

            // The final reconstructed probability row must reproduce the
            // context vector emitted by the Vulkan attention shader itself.
            let final_attention = attentions
                .last()
                .and_then(|layers| layers.first())
                .context("missing final first-layer attention")?;
            let key_rows = final_attention.key_rows;
            let query_row = final_attention.query_rows - 1;
            let absolute_query = key_rows - 1;
            let hidden = graph.config().hidden_size;
            let head_dim = graph.config().head_dim;
            let v_values = graph.layers[0].tape.v.read_f32(key_rows * hidden)?;
            let context = graph.layers[0].tape.attention.read_f32(key_rows * hidden)?;
            for head in 0..graph.config().num_heads {
                let probability_base = (head * final_attention.query_rows + query_row) * key_rows;
                for dim in 0..head_dim {
                    let mut expected = 0.0f32;
                    for key in 0..key_rows {
                        expected = final_attention.values[probability_base + key]
                            .mul_add(v_values[key * hidden + head * head_dim + dim], expected);
                    }
                    let actual = context[absolute_query * hidden + head * head_dim + dim];
                    assert!(
                        (actual - expected).abs() < 2.0e-5,
                        "attention readback mismatch: cache={use_cache} head={head} dim={dim} actual={actual} expected={expected}"
                    );
                }
            }
        }

        let beam_config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(2),
            num_beams: 3,
            num_return_sequences: 2,
            output_scores: true,
            output_attentions: true,
            return_dict_in_generate: true,
            ..VulkanTransformerGenerationConfig::default()
        };
        let beam_output = graph.generate_output(&prompt, &beam_config)?;
        assert_eq!(
            beam_output.sequences.len(),
            beam_config.num_return_sequences
        );
        for sequence in &beam_output.sequences {
            let attentions = sequence
                .attentions
                .as_ref()
                .context("missing finalized beam attention trace")?;
            assert_eq!(attentions.len(), sequence.generated_ids().len());
            assert!(sequence.cross_attentions.is_none());
            assert_eq!(
                sequence
                    .beam_indices
                    .as_ref()
                    .context("missing finalized beam ancestry")?
                    .len(),
                sequence.generated_ids().len()
            );
            for (step, step_attentions) in attentions.iter().enumerate() {
                let key_rows = prompt.len() + step;
                let expected_query_rows = if beam_config.use_cache && step > 0 {
                    1
                } else {
                    key_rows
                };
                assert_eq!(step_attentions.len(), graph.config().num_layers);
                assert!(step_attentions.iter().all(|attention| {
                    attention.query_rows == expected_query_rows
                        && attention.key_rows == key_rows
                        && attention.num_heads == graph.config().num_heads
                        && attention.values.len()
                            == attention.num_heads * attention.query_rows * attention.key_rows
                }));
            }
        }
        Ok(())
    }

