    #[test]
    fn gpt2_structured_beam_output_matches_cached_sequence_ranking_and_traces() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let graph = tiny_gpt2_vulkan_graph(device)?;
        let prompt = [3_u32, 7, 11];
        let config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(3),
            num_beams: 3,
            num_return_sequences: 2,
            output_scores: true,
            output_logits: true,
            output_hidden_states: true,
            output_attentions: true,
            return_dict_in_generate: true,
            ..VulkanTransformerGenerationConfig::default()
        };

        let output = graph.generate_output(&prompt, &config)?;
        let cached = graph.generate_sequences_ids(&prompt, &config)?;
        assert_eq!(output.sequences.len(), cached.len());
        for (sequence, expected) in output.sequences.iter().zip(&cached) {
            assert_eq!(sequence.generated_ids(), expected);
            let scores = sequence.scores.as_ref().context("missing beam scores")?;
            let logits = sequence.logits.as_ref().context("missing beam logits")?;
            let beam_indices = sequence
                .beam_indices
                .as_ref()
                .context("missing beam ancestry")?;
            let hidden_states = sequence
                .hidden_states
                .as_ref()
                .context("missing beam hidden states")?;
            let attentions = sequence
                .attentions
                .as_ref()
                .context("missing beam attentions")?;
            assert_eq!(scores.len(), sequence.generated_ids().len());
            assert_eq!(logits.len(), sequence.generated_ids().len());
            assert_eq!(beam_indices.len(), sequence.generated_ids().len());
            assert_eq!(hidden_states.len(), sequence.generated_ids().len());
            assert_eq!(attentions.len(), sequence.generated_ids().len());
            assert!(sequence.cross_attentions.is_none());
            assert!(beam_indices.iter().all(|index| *index < config.num_beams));
            assert!(sequence.sequence_score.unwrap().is_finite());
            for (step, step_states) in hidden_states.iter().enumerate() {
                assert_eq!(step_states.len(), graph.config().num_layers + 1);
                let expected_rows = if config.use_cache && step > 0 {
                    1
                } else {
                    prompt.len() + step
                };
                assert!(step_states.iter().all(|state| {
                    state.rows == expected_rows
                        && state.hidden_size == graph.config().hidden_size
                        && state.values.len() == expected_rows * state.hidden_size
                        && state.values.iter().all(|value| value.is_finite())
                }));
                assert_eq!(attentions[step].len(), graph.config().num_layers);
                assert!(attentions[step].iter().all(|attention| {
                    attention.query_rows == expected_rows
                        && attention.key_rows == prompt.len() + step
                        && attention.num_heads == graph.config().num_heads
                }));
            }
        }
        assert!(
            output.sequences[0].sequence_score.unwrap()
                >= output.sequences[1].sequence_score.unwrap()
        );
        Ok(())
    }

