    #[test]
    fn generation_min_p_and_epsilon_keep_required_top_tokens() -> Result<()> {
        let mut min_p_scores = vec![6.0, 4.0, 0.0, -4.0];
        let min_p = VulkanTransformerGenerationConfig {
            min_p: Some(0.1),
            top_k: 0,
            ..VulkanTransformerGenerationConfig::default()
        };
        generation_apply_sampling_warpers(&mut min_p_scores, &min_p, 1)?;
        assert!(min_p_scores[0].is_finite());
        assert!(min_p_scores[1].is_finite());
        assert!(min_p_scores[2].is_infinite());
        assert!(min_p_scores[3].is_infinite());

        let mut epsilon_scores = vec![6.0, 4.0, 0.0, -4.0];
        let epsilon = VulkanTransformerGenerationConfig {
            epsilon_cutoff: Some(0.99),
            top_k: 0,
            ..VulkanTransformerGenerationConfig::default()
        };
        generation_apply_sampling_warpers(&mut epsilon_scores, &epsilon, 2)?;
        assert!(epsilon_scores[0].is_finite());
        assert!(epsilon_scores[1].is_finite());
        assert!(epsilon_scores[2].is_infinite());
        assert!(epsilon_scores[3].is_infinite());
        Ok(())
    }

