    #[test]
    fn generation_beam_sampling_is_seeded_and_without_replacement() -> Result<()> {
        let config = VulkanTransformerGenerationConfig {
            max_new_tokens: Some(2),
            do_sample: true,
            num_beams: 2,
            seed: 0x1234_5678,
            ..VulkanTransformerGenerationConfig::default()
        };
        let candidates = (0..2)
            .flat_map(|parent_index| {
                (0..6).map(move |token| VulkanGenerationBeamCandidate {
                    parent_index,
                    token,
                    score: -0.1 * f64::from(token + 1) - parent_index as f64 * 0.05,
                    finished: false,
                })
            })
            .collect::<Vec<_>>();
        let first = generation_select_beam_candidates(candidates.clone(), &config, 1)?;
        let second = generation_select_beam_candidates(candidates, &config, 1)?;
        assert_eq!(first.len(), 4);
        assert_eq!(
            first
                .iter()
                .map(|candidate| (candidate.parent_index, candidate.token))
                .collect::<Vec<_>>(),
            second
                .iter()
                .map(|candidate| (candidate.parent_index, candidate.token))
                .collect::<Vec<_>>()
        );
        let unique = first
            .iter()
            .map(|candidate| (candidate.parent_index, candidate.token))
            .collect::<BTreeSet<_>>();
        assert_eq!(unique.len(), first.len());
        Ok(())
    }

    #[test]
    fn generic_decoder_generation_kv_cache_matches_full_prefix_logits() -> Result<()> {
        let Ok(device) = VulkanDevice::new() else {
            return Ok(());
        };
        let mut starcoder2 = tiny_starcoder2_config();
        starcoder2
            .as_object_mut()
            .expect("tiny StarCoder2 config is an object")
            .insert("max_position_embeddings".to_string(), serde_json::json!(8));
        let mut cwm = tiny_cwm_config();
        cwm["sliding_window"] = serde_json::json!(3);
        let cases = [
            ("StableLM", tiny_stablelm_config()),
            ("Phi-3", tiny_phi3_config()),
            ("Gemma", tiny_gemma_config()),
            ("Granite", tiny_granite_config()),
            ("StarCoder2", starcoder2),
            ("CWM", cwm),
        ];

        for (family, value) in cases {
            let graph = tiny_llama_layout_vulkan_graph(device.clone(), value)?;
            assert!(
                graph.supports_generation_kv_cache(),
                "{family} should use the native generation KV cache"
            );

            let prompt = [2_u32, 9, 4];
            let (_, cache) = graph.generation_prefill_kv_cache(&prompt)?;
            let continuation = [6_u32, 12, 18];
            let mut prefix = prompt.to_vec();
            for &token in &continuation {
                let position = prefix.len();
                let cached = graph.generation_cached_step_logits(token, &cache, position)?;
                prefix.push(token);
                let reference = graph.generation_last_logits(&prefix, None, None)?;
                for (index, (&cached, &reference)) in
                    cached.iter().zip(reference.iter()).enumerate()
                {
                    assert!(
                        (cached - reference).abs() <= 4.0e-5,
                        "{family} cached logit mismatch at position {position}, vocab {index}: cached={cached} reference={reference}"
                    );
                }
            }
        }
        Ok(())
    }

